window.CP_ITEMS=window.CP_ITEMS||{};window.CP_ITEMS["抒情"]=[{"uid":"c854a853-b015-4848-823b-a786659d33b3","title":"宿王昌龄隐居","author":"常建","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["清溪深不测，隐处唯孤云。","松际露微月，清光犹为君。","茅亭宿花影，药院滋苔纹。","余亦谢时去，西山鸾鹤群。"],"theme":"闲适隐逸","theme2":["山水田园"],"style":"婉约","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["月","园林","山"],"cats":{"抒情":["孤独"]},"theme_conf":0.88},{"uid":"50fa86ae-4358-4dac-bc7d-26a60929034f","title":"杂曲歌辞 昔昔盐 蘼芜叶复齐","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["提筐红叶下，度日采蘼芜。","掬翠香盈袖，看花忆故夫。","叶齐谁复见，风暖恨偏孤。","一被春光累，容颜与昔殊。"],"theme":"闺情宫怨","theme2":[],"style":"沉郁","style2":["绮丽"],"mood":"愁怨","mood2":["孤寂","相思"],"scene":["花","春"],"cats":{"抒情":["思念","孤独","闺怨"],"四季":["春天"],"植物":["叶子"]},"theme_conf":0.9},{"uid":"f0642653-c834-4a31-9fe4-d60d50a4ca8c","title":"忆荔枝","author":"薛涛","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["传闻象郡隔南荒，绛实丰肌不可忘。","近有青衣连楚水，素浆还得类琼浆。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["雪"],"cats":{"抒情":["思念"],"食物":["荔枝"]},"theme_conf":0.92},{"uid":"7788b1f7-db6a-47b6-8e96-0689afff0c8f","title":"竞渡诗","author":"卢肇","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["石溪久住思端午，馆驿楼前看发机。","鼙鼓动时雷隐隐，兽头凌处雪微微。","冲波突出入齐[譀]，跃浪争先鸟退飞。","向道是龙刚不信，果然夺得锦标归。"],"theme":"节令风俗","theme2":["羁旅思乡","山水田园"],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["端午","雪","楼"],"cats":{"抒情":["思乡"],"节日":["端午节"]},"theme_conf":0.97},{"uid":"08155b8d-f4f2-486d-8d3d-b7260482feb1","title":"大觜乌","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["阳乌有二类，觜白者名慈。","求食哺慈母，因以此名之。","饮啄颇廉俭，音响亦柔雌。","百巢同一树，栖宿不复疑。","得食先反哺，一身常苦羸。","缘知五常性，飜被众禽欺。","其一觜大者，攫搏性贪痴。","有力强如鹘，有爪利如锥。","音响甚㕭嗗，潜通妖怪词。","受日余光庇，终天无死期。","翺翔富人屋，栖息屋前枝。","巫言此乌至，财产日丰宜。","主人一心惑，诱引不知疲。","转见乌来集，自言家转孳。","白鹤门外养，花鹰架上维。","专听乌喜怒，信受若神龟。","举家同此意，弹射不复施。","往往清池侧，却令鹓鹭随。","群乌饱粱肉，毛羽色泽滋。","远近恣所往，贪残无不为。","巢禽攫雏卵，廐马啄疮痍。","渗沥脂膏尽，凤皇那得知。","主人一朝病，争向屋檐窥。","呦鷕呼群𫛳，翩翻集怪鸱。","主人偏养者，啸聚最奔驰。","夜半仍惊噪，鸺鹠逐老狸。","主人病心怯，灯火夜深移。","左右虽无语，奄然皆泪垂。","平明天出日，阴魅走参差。","乌来屋檐上，又惑主人儿。","儿即当家业，玩好方爱奇。","占募能言鸟，置者许高赀。","陇树巢鹦鹉，言语好光仪。","美人倾心献，雕笼身自持。","求者临轩坐，置在白玉墀。","先问鸟中苦，便言乌若斯。","众乌齐搏铄，翠羽几离披。","远掷千余里，美人情亦衰。","举家惩此患，事乌逾昔时。","向言池上鹭，啄肉寝其皮。","夜漏天终晓，阴云风定吹。","况尔乌何者，数极不知危。","会结弥天网，尽取一无遗。","常令阿阁上，宛宛宿长离。"],"theme":"亲情","theme2":[],"style":"沉郁","style2":["绮丽","幽峭"],"mood":"愁怨","mood2":[],"scene":["夜","鸟","楼"],"cats":{"抒情":["伤感","感恩"],"人物":["女子","母亲"]},"theme_conf":1.0},{"uid":"1e77033d-2c4f-4e60-8d42-3b1529f3c93c","title":"横吹曲辞 折杨柳","author":"崔湜","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["二月风光半，三边戍不还。","年华妾自惜，杨柳为君攀。","落絮缘衫袖，垂条拂髻鬟。","那堪音信断，流涕望阳关。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["月"],"cats":{"抒情":["闺怨"],"生活":["边塞"],"植物":["柳树"]},"theme_conf":0.415},{"uid":"4bd7acac-92da-4afa-b14d-010bb5e9da52","title":"杂歌","author":"李端","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["汉水至清泥则浊，松枝至坚萝则弱。","十三女儿事他家，颜色如花终索寞。","兰生当门燕巢幙，兰芽未吐燕泥落。","为姑偏忌诸嫂良，作妇翻嫌壻家恶。","人生照镜须自知，无盐何用妬西施。","秦庭野鹿忽为马，巧伪乱真君试思。","伯奇掇蜂贤父逐，曾参杀人慈母疑。","酒沽千日人不醉，琴弄一弦心已悲。","常闻善交无尔汝，谗口甚甘良药苦。","山鸡锦翼岂凤凰，陇鸟人言止鹦鹉。","向栩非才徒隐灶，田文有命那关户。","犀烛江行见鬼神，木人登席呈歌舞。","乐生东去终居赵，阳虎北辕飜适楚。","世间反复不易陈，缄此贻君泪如雨。"],"theme":"亲情","theme2":["闲适隐逸"],"style":"幽峭","style2":["清新"],"mood":"愁怨","mood2":["悲怆"],"scene":["酒","鸟"],"cats":{"抒情":["伤感","感恩"],"人物":["母亲"]},"theme_conf":0.561},{"uid":"cp9d526676093b5f","title":"绿意・疏影","author":"张炎","dynasty":"宋","section":"宋词","form":"词","paragraphs":["碧圆自洁。","向浅洲远渚，亭亭清绝。","犹有遗簪，不展秋心，能卷几多炎热。","鸳鸯密语同倾盖，且莫与、浣纱人说。","恐怨歌、忽断花风，碎却翠云千叠。","回首当年汉舞，怕飞去、谩皱留仙裙折。","恋恋青衫，犹染枯香，还叹鬓丝飘雪。","盘心清露如铅水，又一夜、西风吹折。","喜静看、匹练秋光，倒泻半湖明月。"],"theme":"爱情相思","theme2":[],"style":"清新","style2":["冲淡"],"mood":"愁怨","mood2":["欢愉","恬淡"],"scene":["江","秋","月"],"cats":{"抒情":["爱情"],"四季":["秋天"],"天气":["月亮"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"22ec1415-85ee-4aa1-8838-62aa3c9b66dd","title":"醉时歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["诸公衮衮登台省，广文先生官独冷。","甲第纷纷厌粱肉，广文先生饭不足。","先生有道出羲皇，先生有才过屈宋。","德尊一代常𫐘轲，名垂万古知何用。","杜陵野客人更嗤，被褐短窄鬓如丝。","日籴太仓五升米，时赴郑老同襟期。","得钱即相觅，沽酒不复疑。","忘形到尔汝，痛饮真吾师。","清夜沈沈动春酌，灯前细雨檐花落。","但觉高歌有鬼神，焉知饿死填沟壑。","相如逸才亲涤器，子云识字终投阁。","先生早赋归去来，石田茅屋荒苍苔。","儒术于我何有哉，孔丘盗跖俱尘埃。","不须闻此意惨怆，生前相遇且衔杯。"],"theme":"寄赠酬答","theme2":["民生疾苦"],"style":"幽峭","style2":["雄浑","豪放"],"mood":"悲怆","mood2":["孤寂"],"scene":["酒"],"cats":{"抒情":["孤独"],"天气":["写雨"],"食物":["写酒"]},"theme_conf":0.78},{"uid":"b54ccce5-156f-4067-8408-a1d8a0d4c180","title":"奉赠萧二十使君","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["惜在严公幕，俱为蜀使臣。","艰危参大府，前后间清尘。","起草鸣先路，乘槎动要津。","王凫聊暂出，萧雉只相驯。","终始任安义，荒芜孟母邻。","联翩匍匐礼，意气死生亲。","张老存家事，嵇康有故人。","食恩慙卤莽，镂骨抱酸辛。","巢许山林志，夔龙廊庙珍。","鹏图乃矫翼，熊轼且移轮。","磊落衣冠地，苍茫土木身。","埙篪鸣自合，金石莹逾新。","重忆罗江外，同游锦水滨。","结欢随过隙，怀旧益沾巾。","旷绝含香舍，稽留伏枕辰。","停骖双阙早，回雁五湖春。","不达长卿病，从来原宪贫。","监河受贷粟，一起辙中鳞。"],"theme":"寄赠酬答","theme2":[],"style":"雄浑","style2":["绮丽","旷达"],"mood":"慷慨","mood2":["欢愉"],"scene":["江","春"],"cats":{"抒情":["友情"],"四季":["春天"],"人生":["梦想"]},"theme_conf":0.86},{"uid":"dc1124b1-22cb-4556-8078-54998b4973f7","title":"相和歌辞 乌夜啼","author":"李群玉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["曾波隔梦渚，一望青枫林。","有乌在其间，达晓自悲吟。","是时月黑天，四野烟雨深。","如闻生离哭，其声痛人心。","悄悄夜正长，空山响哀音。","远客不可听，坐愁华发侵。","既非蜀帝魂，恐是恒山禽。","四子各分散，母声犹至今。"],"theme":"山水田园","theme2":["悼亡挽歌","羁旅思乡"],"style":"悲慨","style2":["沉郁","冲淡"],"mood":"悲怆","mood2":[],"scene":["夜"],"cats":{"抒情":["思乡","伤感","悼亡"]},"theme_conf":0.419},{"uid":"02456f60-6ab5-4de8-b9ed-f7519818f0ca","title":"贾生","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["宣室求贤访逐臣，贾生才调更无伦。","可怜夜半虚前席，不问苍生问鬼神。"],"theme":"咏史怀古","theme2":["讽喻刺世"],"style":"幽峭","style2":[],"mood":"惆怅","mood2":[],"scene":["夜"],"cats":{"抒情":["怀古"]},"theme_conf":0.5},{"uid":"2b563a63-b88a-4af9-99f8-d1840f235ce9","title":"赠岑郎中","author":"戎昱","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["童年未解读书时，诵得郎中数首诗。","四海烟尘犹隔阔，十年魂梦每相随。","虽披云雾逢迎疾，已恨趋风拜德迟。","天下无人鉴诗句，不寻诗伯重寻谁。"],"theme":"应制干谒","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":[],"cats":{"抒情":["孤独"],"人生":["读书"]},"theme_conf":0.92},{"uid":"824423a3-e7e6-41f5-bf24-d0d755bd5ed7","title":"过孔北海墓二十韵","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["抚事如神遇，临风独涕零。","墓平春草绿，碑折古苔青。","珪玉埋英气，山河孕炳灵。","发言惊辨囿，㧑翰动文星。","蕴策期干世，持权欲反经。","激扬思壮志，流落叹颓龄。","恶木人皆息，贪泉我独醒。","轮辕无匠石，刀几有庖丁。","碌碌迷藏器，规规守挈瓶。","愤容凌鼎镬，公议动朝廷。","故国将辞宠，危邦竟缓刑。","钝工磨白璧，凡石砺青萍。","揭日昭东夏，抟风滞北溟。","后尘遵轨辙，前席咏仪型。","木秀当忧悴，弦伤不底宁。","矜夸遭斥鷃，光彩困飞萤。","白羽留谈柄，清风袭德馨。","鸾凰婴雪刃，狼虎犯云屏。","兰蕙荒遗址，榛芜蔽旧坰。","轘辕近沂水，何事恋明庭。"],"theme":"咏史怀古","theme2":["咏史怀古"],"style":"清新","style2":[],"mood":"慷慨","mood2":["孤寂"],"scene":["夏","雪","春"],"cats":{"抒情":["孤独","怀古"],"四季":["春天","夏天"],"人生":["励志","梦想"]},"theme_conf":0.96},{"uid":"b4ab0057-6846-46fc-afce-1d641980509f","title":"吊江南老家人春梅","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["念尔筋力尽，违我衣食恩。","奈何粗犷儿，生鞭见死痕。","旧使常以礼，新怨将谁吞。","胡为乎泥中，消歇教义源。"],"theme":"咏史怀古","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["悲怆","惆怅"],"scene":["江南","春","江"],"cats":{"抒情":["怀古"],"四季":["春天"],"植物":["梅花"]},"theme_conf":0.606},{"uid":"b2d89260-e3b7-4077-aaaa-0a67db01d5b6","title":"酬窦拾遗秋日见呈","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["孤城永巷时相见，衰柳闲门日半斜。","欲送近臣朝魏阙，犹怜残菊在陶家。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"天气":["太阳"]},"theme_conf":0.93},{"uid":"b98a1f96-5eaa-4d8d-ae39-4a7a38b6eb1e","title":"相和歌辞 采莲曲","author":"李白","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["若耶溪边采莲女，笑隔荷花共人语。","日照新妆水底明，风飘香袖空中举。","岸上谁家游冶郎，三三五五映垂杨。","紫骝嘶入落花去，见此踟蹰空断肠。"],"theme":"山水田园","theme2":["爱情相思","闺情宫怨"],"style":"婉约","style2":["清新"],"mood":"愁怨","mood2":["欢愉"],"scene":["花"],"cats":{"抒情":["伤感","闺怨"],"植物":["荷花"]},"theme_conf":0.424},{"uid":"6ec03821-1ece-4cdc-97cb-c7b976ac47b1","title":"自淇涉黄河途中作十三首 二","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["清晨泛中流，羽族满汀渚。","黄鹄何处来，昂藏寡俦侣。","飞鸣无人见，饮啄岂得所。","云汉尔固知，胡为不轻举。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["孤独"],"山水":["黄河"]},"theme_conf":1.0},{"uid":"c1f1cc1d-4eff-438e-8aea-60cb69174965","title":"同卫八题陆少府书斋","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["知君薄州县，好静无冬春。","散帙至栖鸟，明灯留故人。","深房腊酒熟，高院梅花新。","若是周旋地，当令风义亲。"],"theme":"咏物","theme2":["送别"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["冬","春","酒"],"cats":{"抒情":["友情"],"四季":["春天","冬天"]},"theme_conf":0.618},{"uid":"56e0d3a3-858b-4aa9-9227-e73b3c63265b","title":"重寄荔枝与杨使君时闻杨使君欲种植故有落句之戏","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["摘来正带凌晨露，寄去须凭下水船。","映我绯衫浑不见，对公银印最相鲜。","香连翠叶真堪画，红透青笼实可怜。","闻道万州方欲种，愁君得吃是何年。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["舟","花"],"cats":{"抒情":["伤感"],"食物":["荔枝"]},"theme_conf":0.88},{"uid":"40a92675-3a77-4ce1-9242-17eb287a246a","title":"渡江秋怨二首 二","author":"权德舆","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["渡秋江兮渺然，望秋月兮婵娟。","色如练，万里徧，我有所思兮不得见。","不得见兮露寒水深，耿遥夜兮伤心。"],"theme":"闺情宫怨","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","江"],"cats":{"抒情":["伤感","闺怨"],"四季":["秋天"],"山水":["江河"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"f990af2e-d929-48da-a9b3-fdbc706ca4a3","title":"子夜吴歌 冬歌","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["明朝驿使发，一夜絮征袍。","素手抽针冷，那堪把剪刀。","裁缝寄远道，几日到临洮。"],"theme":"闺情宫怨","theme2":["羁旅思乡","送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["冬","夜"],"cats":{"抒情":["思乡","闺怨"],"四季":["冬天"]},"theme_conf":0.347},{"uid":"6b65b2f9-0c0d-4b94-92ad-af22334582cf","title":"九日酬颜少府","author":"高适","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["簷前白日应可惜，篱下黄花为谁有。","行子迎霜未授衣，主人得钱始沽酒。","苏秦顦顇人多厌，蔡泽栖迟世看丑。","纵使登高只断肠，不如独坐空搔首。"],"theme":"寄赠酬答","theme2":["节令风俗"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"抒情":["伤感","孤独"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.86},{"uid":"60b400e0-ad92-455c-bd50-e6c2f1cfaf88","title":"杜中丞书院新移小竹","author":"王建","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["此地本无竹，远从山寺移。","经年求养法，隔日记浇时。","嫩绿卷新叶，残黄收故枝。","色轻寒不动，声与静相宜。","爱护出常数，稀稠看自知。","贫来缘未有，客散独行迟。"],"theme":"咏物","theme2":["山水田园","哲理悟道","羁旅思乡"],"style":"清新","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["园林"],"cats":{"抒情":["思乡","孤独"],"植物":["竹子"]},"theme_conf":0.9},{"uid":"c8b006af-ed1c-4206-8647-24e8623ca5b2","title":"相和歌辞 上留田","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["行至上留田，孤坟何峥嵘。","积此万古恨，春草不复生。","悲风四边来，肠断白杨声。","借问谁家地，埋没蒿里茔。","古老向余言，言是上留田。","蓬科马鬣今已平，昔之弟死兄不葬。","他人于此举铭旌，一鸟死，百鸟鸣，一兽死，百兽惊。","桓山之禽别离苦，欲去回翔不能征。","田氏仓卒骨肉分，青天白日摧紫荆。","交柯之木本同形，东枝顦顇西枝荣。","无心之物尚如此，参商胡乃寻天兵。","孤竹延陵，让国扬名。","高风缅邈，颓波激清。","尺布之谣，塞耳不能听。"],"theme":"咏史怀古","theme2":["悼亡挽歌","送别","讽喻刺世"],"style":"沉郁","style2":["雄浑"],"mood":"愁怨","mood2":["悲怆"],"scene":["塞外","春"],"cats":{"抒情":["离别","伤感","悼亡","怀古"],"四季":["春天"]},"theme_conf":0.95},{"uid":"f93545e7-747e-4d12-a6c8-e484c46b2860","title":"相和歌辞 玉阶怨","author":"李白","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["玉阶生白露，夜久侵罗袜。","却下水精帘，玲珑望秋月。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["秋","夜","月"],"cats":{"抒情":["闺怨"],"四季":["秋天"]},"theme_conf":0.836},{"uid":"cp6c060097980e4f","title":"虞美人","author":"叶梦得","dynasty":"宋","section":"宋词","form":"词","paragraphs":["落花已作风前舞。","又送黄昏雨。","晓来庭院半残红。","惟有游丝千丈、晴空。","殷勤花下同携手。","更尽杯中酒。","美人不用敛蛾眉。","我亦多情、无奈酒阑时。"],"theme":"送别","theme2":[],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["酒","园林","夜","花"],"cats":{"抒情":["伤感"],"人物":["女子"]},"theme_conf":1.0},{"uid":"ecad5c4e-aaeb-4f85-bf79-036e6fe92b66","title":"平陵寓居再逢寒食","author":"朱湾","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["几回江上泣途穷，每遇良辰叹转蓬。","火燧知从新节变，灰心还与故人同。","莫听黄鸟愁啼处，自有花开久客中。","贫病固应无挠事，但将怀抱醉春风。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"愁怨","mood2":["悲怆"],"scene":["清明"],"cats":{"抒情":["思乡","伤感"],"节日":["寒食节","清明节"]},"theme_conf":0.84},{"uid":"402d45dc-7d64-4a0a-b731-79551c95ba91","title":"詶裴云客","author":"元结","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["自厌久荒浪，于时无所任。","耕钓以为事，来家樊水阴。","甚醉或漫歌，甚闲亦漫吟。","不知愚僻意，称得云客心。","云客方持斧，与人正相临。","符印随坐起，守位常森森。","纵能有相招，岂暇来山林。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"恬淡","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"天气":["写云"]},"theme_conf":0.449},{"uid":"655ae29b-c115-4b27-a0b8-caa7e01d1808","title":"武威同诸公过杨七山人得藤字","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["幕府日多暇，田家岁复登。","相知恨不早，乘兴乃无恒。","穷巷在乔木，深斋垂古藤。","边城唯有醉，此外更何能。"],"theme":"山水田园","theme2":["咏史怀古","民生疾苦"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["山"],"cats":{"抒情":["怀古"],"生活":["田野"]},"theme_conf":0.399},{"uid":"f9d02cdb-7dc0-436a-a758-e29b65bb461b","title":"杂曲歌辞 妾薄命","author":"张籍","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["薄命妇，良家子，无事从军去万里。","汉家天子平四夷，护羌都尉裹尸归。","念君此行为死别，对君裁缝泉下衣。","与君一日为夫妇，千年万岁亦相守。","君爱龙城征战功，妾愿青楼欢乐同。","人生各各有所欲，讵得将心入君腹。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["楼"],"cats":{"抒情":["闺怨","悼亡"],"人生":["战争"]},"theme_conf":0.409},{"uid":"06d1e418-5974-47f5-9855-5b2976a02345","title":"郊庙歌辞 祭神州乐章 雍和","author":"褚亮","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["泰折严享，阴郊展敬。","礼以导神，乐以和性。","黝牲在列，黄琮俯暎。","九土既平，万邦贻庆。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"抒情":["怀古","爱国"]},"theme_conf":1.0},{"uid":"e5e5f969-ddac-4491-9cfe-d77742e1416d","title":"将进酒","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["君不见黄河之水天上来，奔流到海不复回。","君不见高堂明镜悲白发，朝如青丝暮成雪。","人生得意须尽欢，莫使金樽空对月。","天生我材必有用，千金散尽还复来。","烹羊宰牛且为乐，会须一饮三百杯。","岑夫子，丹丘生，将进酒，君莫停。","与君歌一曲，请君为我侧耳听。","钟鼓馔玉不足贵，但愿长醉不愿醒。","古来圣贤皆寂寞，惟有饮者留其名。","陈王昔时宴平乐，斗酒十千恣讙谑。","主人何为言少钱，径须沽取对君酌。","五花马，千金裘，呼儿将出换美酒，与尔同销万古愁。"],"theme":"咏怀抒感","theme2":["咏物","哲理悟道"],"style":"豪放","style2":[],"mood":"欢愉","mood2":["孤寂"],"scene":["酒"],"cats":{"抒情":["伤感","孤独"],"山水":["黄河"],"食物":["写酒"]},"theme_conf":0.9},{"uid":"bea6f283-8f90-49b5-8842-1cb906816548","title":"古从军行","author":"李颀","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["白日登山望烽火，黄昏饮马傍交河。","行人刁斗风沙暗，公主琵琶幽怨多。","野云万里无城郭，雨雪纷纷连大漠。","胡鴈哀鸣夜夜飞，胡儿眼泪双双落。","闻道玉门犹被遮，应将性命逐轻车。","年年战骨埋荒外，空见蒲桃入汉家。"],"theme":"边塞征战","theme2":[],"style":"婉约","style2":["豪放","雄浑"],"mood":"愁怨","mood2":[],"scene":["冬","夜"],"cats":{"抒情":["伤感"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.765},{"uid":"b67cee37-9190-4581-89ec-473df5ef0c6f","title":"到村","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["碧涧虽多雨，秋沙先少泥。","蛟龙引子过，荷芰逐花低。","老去参戎幕，归来散马蹄。","稻粱须就列，榛草即相迷。","蓄积思江汉，疎顽惑町畦。","稍酬知己分，还入故林栖。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["秋","雨","江"],"cats":{"抒情":["友情"],"四季":["秋天"],"生活":["乡村"]},"theme_conf":0.707},{"uid":"01d61dfa-6c6e-421d-a5b3-c7db62f9d7fe","title":"题杭州孤山寺","author":"张祜","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["楼台耸碧岑，一径入湖心。","不雨山长润，无云水自阴。","断桥荒藓涩，空院落花深。","犹忆西窗月，钟声在北林。"],"theme":"山水田园","theme2":["哲理悟道"],"style":"沉郁","style2":["幽峭"],"mood":"孤寂","mood2":[],"scene":["山","楼"],"cats":{"抒情":["孤独"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":0.56},{"uid":"bef2cc78-10ff-4c56-8db2-7c496b1891b5","title":"早发若岘驿望庐山","author":"独孤及","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["雨罢山翠鲜，泠泠东风好。","断崖云生处，是向峰顶道。","谁谓峰顶远，跂予可瞻讨。","忘缘祛天机，脱屐恨不早。","祗恐岁云暮，遂与空名老。","心往迹未幷，惭愧山上草。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["山"],"cats":{"抒情":["思乡"],"山水":["庐山"]},"theme_conf":0.548},{"uid":"73b463e3-0634-4be4-8d69-935d41bb76ba","title":"落叶","author":"王建","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["陈绿向参差，初红已重叠。","中庭初扫地，绕树三两叶。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["秋","园林"],"cats":{"抒情":["思乡"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"d6d2ba3a-f3a7-479e-b4d7-705ef40659fc","title":"颍州从事西湖亭䜩饯","author":"许浑","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["西湖清宴不知回，一曲离歌酒一杯。","城带夕阳闻鼓角，寺临秋水见楼台。","兰堂客散蝉犹噪，桂檝人稀鸟自来。","独想征车过巩洛，此中霜菊遶潭开。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["江南","楼","秋","江"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["西湖"]},"theme_conf":0.688},{"uid":"801c3192-8001-4238-8ecf-0111f490e84c","title":"行路难三首 二","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["大道如青天，我独不得出。","羞逐长安社中儿，赤鸡白狗赌梨栗。","弹劒作歌奏苦声，曳裾王门不称情。","淮阴市井笑韩信，汉朝公卿忌贾生。","君不见昔时燕家重郭隗，拥篲折节无嫌猜。","剧辛乐毅感恩分，输肝剖胆效英才。","昭王白骨萦烂草，谁人更扫黄金台。","行路难，归去来。"],"theme":"羁旅思乡","theme2":["闲适隐逸"],"style":"悲慨","style2":[],"mood":"欢愉","mood2":["惆怅","悲怆"],"scene":[],"cats":{"抒情":["思乡","感恩"]},"theme_conf":0.542},{"uid":"0fb0189c-8ff3-4106-af94-f6d26d528a1d","title":"琵琶引","author":"白居易","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["浔阳江头夜送客，枫叶荻花秋索索。","主人下马客在船，举酒欲饮无管弦。","醉不成欢惨将别，别时茫茫江浸月。","忽闻水上琵琶声，主人忘归客不发。","寻声暗问弹者谁，琵琶声停欲语迟。","移船相近邀相见，添酒回灯重开宴。","千呼万唤始出来，犹抱琵琶半遮面。","转轴拨弦三两声，未成曲调先有情。","弦弦掩抑声声思，似诉平生不得意。","低眉信手续续弹，说尽心中无限事。","轻拢慢撚抹复挑，初为霓裳后六幺。","大弦嘈嘈如急雨，小弦切切如私语。","嘈嘈切切错杂弹，大珠小珠落玉盘。","间关莺语花底滑，幽咽泉流水下滩。","水泉冷涩弦疑绝，疑绝不通声暂歇。","别有幽愁暗恨生，此时无声胜有声。","银缾乍破水浆迸，铁骑突出刀枪鸣。","曲终收拨当心画，四弦一声如裂帛。","东舟西舫悄无言，唯见江心秋月白。","沈吟放拨插弦中，整顿衣裳起敛容。","自言本是京城女，家在虾蟇陵下住。","十三学得琵琶成，名蜀教坊第一部。","曲罢曾教善才伏，妆成每被秋娘妬。","五陵年少争缠头，一曲红绡不知数。","钿头云箆击节碎，血色罗帬飜酒污。","今年欢笑复明年，秋月春风等闲度。","弟走从军阿姨死，暮去朝来颜色故。","门前冷落鞍马稀，老大嫁作商人妇。","商人重利轻别离，前月浮梁买茶去。","去来江口守空船，绕船月明江水寒。","夜深忽梦少年事，梦啼妆泪红阑干。","我闻琵琶已叹息，又闻此语重唧唧。","同是天涯沦落人，相逢何必曾相识。","我从去年辞帝京，谪居卧病浔阳城。","浔阳小处无音乐，终岁不闻丝竹声。","住近湓江地低湿，黄芦苦竹绕宅生。","其间旦暮闻何物，杜鹃啼血猨哀鸣。","春江花朝秋月夜，往往取酒还独倾。","岂无山歌与村笛，呕哑嘲哳难为听。","今夜闻君琵琶语，如听仙乐耳暂明。","莫辞更坐弹一曲，为君飜作琵琶行。","感我此言良久立，却坐促弦弦转急。","凄凄不似向前声，满座重闻皆掩泣。","座中泣下谁最多，江州司马青衫湿。"],"theme":"题画咏艺","theme2":["送别"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["欢愉","悲怆"],"scene":["夜","舟","酒","秋","春","鸟"],"cats":{"抒情":["离别","伤感"],"四季":["春天","秋天"]},"theme_conf":0.328},{"uid":"ba10246a-c026-41e7-87a9-2e6ce2a27559","title":"建都十二韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["苍生未苏息，胡马半乾坤。","议在云台上，谁扶黄屋尊。","建都分魏阙，下韶辟荆门。","恐失东人望，其如西极存。","时危当雪耻，计大岂轻论。","虽倚三阶正，终愁万国飜。","牵裾恨不死，漏网荷殊恩。","永负汉庭哭，遥怜湘水魂。","穷冬客江劒，随事有田园。","风断青蒲节，霜埋翠竹根。","衣冠空穰穰，关辅久昏昏。","愿枉长安日，光辉照北原。"],"theme":"边塞征战","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["悲怆"],"scene":["冬","园林","雪"],"cats":{"抒情":["伤感"],"四季":["冬天"],"生活":["田野"]},"theme_conf":0.531},{"uid":"70327e7a-b43e-446d-8e1b-7e9960187f27","title":"过王舍人宅","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["入门花柳暗，知是近臣居。","大隐心何远，高风物自疎。","翛然静者事，宛得上皇余。","鸡犬偷仙药，儿童授道书。","清吟送客后，微月上城初。","彩笔有新咏，文星垂太虚。","承恩金殿宿，应荐马相如。"],"theme":"应制干谒","theme2":["送别","咏物","羁旅思乡"],"style":"清新","style2":["冲淡"],"mood":"恬淡","mood2":[],"scene":["月"],"cats":{"抒情":["思乡"],"人物":["儿童"]},"theme_conf":0.85},{"uid":"bdeeaa87-d383-44e2-8245-d18fcffb107f","title":"柟树为风雨所拔叹","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["倚江柟树草堂前，故老相传二百年。","诛茅卜居总为此，五月髣髴闻寒蝉。","东南飘风动地至，江翻石走流云气。","干排雷雨犹力争，根断泉源岂天意。","沧波老树性所爱，浦上童童一青盖。","野客频留惧雪霜，行人不过听竽籁。","虎倒龙颠委榛棘，泪痕血点垂胷臆。","我有新诗何处吟，草堂自此无颜色。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["雨"],"cats":{"抒情":["伤感"],"天气":["写风","写雨"]},"theme_conf":1.0},{"uid":"7e808dee-54f9-428c-a303-71ea2ee91df5","title":"听崔莒侍御叶家歌","author":"张祜","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["宛罗重縠起歌筵，活凤生花动碧烟。","一声唱断无人和，触破秋云直上天。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":0.65},{"uid":"de28c365-7d67-4513-a2d5-5dec1ff3c795","title":"寄高云","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["南徐风日好，怅望毘陵道。","毘陵有故人，一见恨无因。","独恋青山久，唯令白发新。","每嫌持手板，时见著头巾。","烟景临寒食，农桑接仲春。","家贫仍嗜酒，生事今何有。","芳草遍江南，劳心忆携手。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"清新","style2":[],"mood":"孤寂","mood2":["相思","愁怨"],"scene":["清明","江南","春","酒"],"cats":{"抒情":["友情","思念","孤独"],"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.96},{"uid":"cp21c68dc72e21cb","title":"六州歌头","author":"张孝祥","dynasty":"宋","section":"宋词","form":"词","paragraphs":["长怀望断，关塞莽然平。","征尘暗，霜风劲，悄边声。","黯销凝。","追想当年事，殆天数，非人力，洙泗上，弦歌地，亦膻腥。","隔水毡乡，落日牛羊下，区脱纵横。","看名王宵猎，骑火一川明。","笳鼓悲鸣。","遣人惊。","念腰间箭，匣中剑，空埃蠹，竟何成。","时易失，心徒壮，岁将零。","渺神京。","干羽方怀远，静烽燧，且休兵。","冠盖使，纷驰骛，若为情。","闻道中原遗老，常南望，羽葆霓旌。","使行人到此，忠愤气填膺。","有泪如倾。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["豪放","冲淡"],"mood":"慷慨","mood2":["悲怆"],"scene":["塞外"],"cats":{"抒情":["伤感"],"生活":["边塞"]},"theme_conf":0.75},{"uid":"e4417fb7-c663-4f78-a4c5-ff279a5a5579","title":"酬令狐相公庭前白菊花谢偶书所怀见寄","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["数丛如雪色，一旦冒霜开。","寒蘂差池落，清香断续来。","思深含别怨，芳谢惜年催。","千里难同赏，看看又早梅。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["花","园林"],"cats":{"抒情":["感恩"],"植物":["菊花"]},"theme_conf":0.9},{"uid":"f8e07cab-06f6-4ea0-a6b6-815bd8c22506","title":"归燕","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["不独避霜雪，其如俦侣稀。","四时无失序，八月自知归。","春色岂相访，众雏还识机。","故巢傥未毁，会傍主人飞。"],"theme":"咏物","theme2":["羁旅思乡"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["鸟","雪","春","月"],"cats":{"抒情":["思乡","孤独"],"四季":["春天"],"动物":["写鸟"]},"theme_conf":0.519},{"uid":"a93b3a91-73b6-4087-8757-5a8f1c8d4161","title":"山斋读书寄时校书杜叟","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["日爱蘅茅下，闲观山海图。","幽人自守朴，穷谷也名愚。","倒岭和溪雨，新泉到户枢。","丛兰齐稚子，蟠木老潜夫。","忆戴差过剡，游仙惯入壶。","濠梁时一访，庄叟亦吾徒。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":["相思"],"scene":["山"],"cats":{"抒情":["思念"],"人物":["儿童"],"人生":["读书"]},"theme_conf":0.441},{"uid":"292c14cd-151f-4321-a94c-46fc86693eb3","title":"秋日赴阙题潼关驿楼","author":"许浑","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["红叶晚萧萧，长亭酒一瓢。","残云归太华，疎雨过中条。","树色随山迥，河声入海遥。","帝乡明日到，犹自梦渔樵。"],"theme":"羁旅思乡","theme2":["送别","山水田园"],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":["楼","秋"],"cats":{"抒情":["离别","思乡"],"四季":["秋天"],"天气":["太阳"]},"theme_conf":0.78},{"uid":"648b7a06-ca8e-44e6-9597-c7d25395b78b","title":"赋得铁马鞭","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["成器虽因匠，怀刚本自天。","为怜持寸节，长拟静三边。","未入英髦用，空存铁石坚。","希君剖腹取，还解抱龙泉。"],"theme":"咏物","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":[],"cats":{"抒情":["爱国"],"动物":["写马"]},"theme_conf":1.0},{"uid":"7136e8b6-cec9-423f-89e9-a260eeb32481","title":"春日登陕州城楼俯眺原野回丹碧缀烟霞密翠斑红芳菲花柳即目川岫聊以命篇","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["碧原开雾隰，绮岭峻霞城。","烟峰高下翠，日浪浅深明。","斑红粧橤树，圆青压溜荆。","迹岩劳傅想，窥野访莘情。","巨川何以济，舟楫伫时英。"],"theme":"山水田园","theme2":["咏史怀古","山水田园"],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["山","春","花"],"cats":{"抒情":["怀古"],"四季":["春天"],"天气":["太阳"],"植物":["柳树"]},"theme_conf":0.82},{"uid":"3d5c77d4-1ce5-458f-bf76-648539c0a0b2","title":"闻吹杨叶者二首 二","author":"郎士元","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["天生一艺更无伦，寥亮幽音妙入神。","吹向别离攀折处，当应合有断肠人。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["离别","伤感"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"1487452b-5f49-4f4f-9913-1f3ec1cddf95","title":"饯别王十一南游","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["望君烟水阔，挥手泪沾巾。","飞鸟没何处，青山空向人。","长江一帆远，落日五湖春。","谁见汀洲上，相思愁白苹。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["冲淡"],"mood":"相思","mood2":["愁怨"],"scene":["江"],"cats":{"抒情":["离别","思念","伤感"],"山水":["长江"]},"theme_conf":0.768},{"uid":"c1fa02b3-3fdd-4de6-86d8-264f36cfee99","title":"重阳","author":"高适","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["节物惊心两鬓华，东篱空绕未开花。","百年将半仕三已，五亩就荒天一涯。","岂有白衣来剥啄，一从乌帽自攲斜。","真成独坐空搔首，门柳萧萧噪暮鸦。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"抒情":["孤独"],"节日":["重阳节"]},"theme_conf":0.76},{"uid":"5eb68e82-7216-4179-9b85-6f04894890b0","title":"九日五首 三","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["旧与苏司业，兼随郑广文。","采花香泛泛，坐客醉纷纷。","野树歌还倚，秋砧醒却闻。","欢娱两冥漠，西北有孤云。"],"theme":"悼亡挽歌","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":["孤寂"],"scene":["重阳","秋","花","塞外"],"cats":{"抒情":["孤独","悼亡"],"四季":["秋天"],"节日":["重阳节"]},"theme_conf":0.78},{"uid":"d179b5ca-f7ba-4b1b-8dae-311ef942a6e0","title":"舞曲歌辞 白纻歌二首 二","author":"王建","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["馆娃宫中春日暮，荔枝木瓜花满树。","城头乌栖休击鼓，青娥弹瑟白纻舞。","夜天燑燑不见星，宫中火照西江明。","美人醉起无次第，堕钗遗佩满中庭。","此时但愿可君意，回昼为宵亦不寐，年年奉君君莫弃。"],"theme":"闺情宫怨","theme2":[],"style":"旷达","style2":[],"mood":"愁怨","mood2":[],"scene":["夜"],"cats":{"抒情":["闺怨"],"人物":["女子"],"食物":["荔枝"]},"theme_conf":0.65},{"uid":"a56eb8bb-1b57-4106-a3a6-34be16282ea3","title":"夏夜饯裴行军赴朝命","author":"武元衡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["三年同看锦城花，银烛连宵照绮霞。","报国从来先意气，临岐不用重咨嗟。"],"theme":"送别","theme2":["边塞征战"],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":["夜","夏"],"cats":{"抒情":["离别","爱国"],"四季":["夏天"]},"theme_conf":0.639},{"uid":"209d2029-4af8-471c-91e1-f67ffc20c5b1","title":"宝林寺作","author":"徐浩","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["兹山昔飞来，远自琅琊台。","孤岫龟形在，深泉鳗井开。","越王屡登陟，何相传词才。","塔庙宗其巅，规模称壮哉。","禅堂清溽润，高阁无恢炱。","照耀珠吐月，铿轰钟隐雷。","揆余久缨弁，末路遭邅回。","一弃沧海曲，六年稽岭隈。","逝川惜东驶，驰景怜西颓。","腰带愁疾减，容颜衰悴催。","赖居兹寺中，法士多瓌能。","洗心听经论，礼足蠲凶灾。","永愿依胜侣，清江乘度杯。"],"theme":"佛道禅颂","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂","慷慨"],"scene":["山","江","楼"],"cats":{"抒情":["伤感","孤独"],"人生":["哲理"]},"theme_conf":0.78},{"uid":"cpf852a8c541e368","title":"菩萨蛮","author":"李师中","dynasty":"宋","section":"宋词","form":"词","paragraphs":["子规啼破城楼月。","画船晓载笙歌发。","两岸荔枝红。","万家烟雨中。","佳人相对泣。","泪下罗衣湿。","从此信音稀。","岭南无雁飞。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["绮丽"],"mood":"悲怆","mood2":["愁怨"],"scene":["楼","月","舟","雨","鸟"],"cats":{"抒情":["思乡","伤感"],"人物":["女子"],"食物":["荔枝"]},"theme_conf":0.65},{"uid":"6d1ee060-5750-4c9b-8c75-6080912cbe17","title":"野菊","author":"王建","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["晚艳出荒篱，冷香著秋水。","忆向山中见，伴蛩石壁里。"],"theme":"咏物","theme2":[],"style":"幽峭","style2":[],"mood":"欢愉","mood2":["相思"],"scene":["重阳","秋","山"],"cats":{"抒情":["思念"],"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.579},{"uid":"cp1acc2f34cdbd10","title":"东风第一枝","author":"史达祖","dynasty":"宋","section":"宋词","form":"词","paragraphs":["巧沁兰心，偷黏草甲，东风欲障新暖。","谩凝碧瓦难留，信知暮寒轻浅。","行天入镜，做弄出、轻松纤软。","料故园、不卷重帘，误了乍来双燕。","青未了、柳回白眼。","红欲断、杏开素面。","旧游忆著山阴，厚盟遂妨上苑。","寒炉重暖，便放慢春衫针线。","恐凤靴、挑菜归来，万一灞桥相见。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["清新"],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思念","思乡"],"四季":["春天"],"天气":["写风"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"7ec1676f-cc0c-4065-bffc-26fbe3124c8d","title":"铁笔歌（今按：疑为后人所作，录附参考。）","author":"张巡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["皇天生我兮男子，君王用我兮熊罴。","力拔山兮势雄，气贯日兮虹霓。","月正明兮磨鎗砺剑，星未落兮击鼓掀旗。","捣贼室兮焚寨，脔贼肉兮充饥。","食马革兮计尽，杀妻妾兮心悲。","为厉鬼兮身被铁甲，为明神兮手执金锤。","亦莫指我为张毅，亦莫指我为张飞。","我乃唐之张巡，与许远兮同时。","在东岳兮押案，都统使兮阴司。","事蓬莱兮殿直，任酆都兮狱推。","景祐真君兮阳间封爵，忠烈大夫兮天上官资。","漫濡毫而为翰，俾世人而皆知。","（《古今图书集成·职方典》三九九《归德府部》）（〖1〗康熙《商邱县志》卷十八收此诗，注：「公降乩所作。","」）。"],"theme":"游仙梦幻","theme2":["民生疾苦"],"style":"豪放","style2":[],"mood":"悲怆","mood2":["慷慨"],"scene":["山"],"cats":{"抒情":["伤感"],"天气":["彩虹"]},"theme_conf":0.519},{"uid":"344b8022-5073-4b18-a099-ee3e1f12412b","title":"相和歌辞 短歌行","author":"僧皎然","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["古人若不死，吾亦何所悲。","萧萧烟雨九原上，白杨青松葬者谁。","贵贱同一尘，死生同一指。","人生在世共如此，何异浮云与流水。","短歌行，短歌无穷日已倾。","邺宫梁苑徒有名，春草秋风伤我情。","何为不学金仙侣？一悟空王无死生。"],"theme":"哲理悟道","theme2":["山水田园"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["春","秋","雨"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"],"人生":["哲理"]},"theme_conf":0.531},{"uid":"f2db30a1-f125-44b9-a8d8-287ccb69238a","title":"佳人","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["绝代有佳人，幽居在空谷。","自云良家子，零落依草木。","关中昔丧败，兄弟遭杀戮。","官高何足论，不得收骨肉。","世情恶衰歇，万事随转烛。","夫壻轻薄儿，新人已如玉。","合昏尚知时，鸳鸯不独宿。","但见新人笑，那闻旧人哭。","在山泉水清，出山泉水浊。","侍婢卖珠回，牵萝补茅屋。","摘花不插发，采柏动盈匊。","天寒翠袖薄，日暮倚修竹。"],"theme":"闺情宫怨","theme2":["亲情","闺情宫怨","闲适隐逸"],"style":"绮丽","style2":["婉约","沉郁"],"mood":"孤寂","mood2":["欢愉","悲怆"],"scene":["山"],"cats":{"抒情":["孤独","闺怨"],"人物":["女子"]},"theme_conf":0.85},{"uid":"4d79a7f2-2e3c-496a-b9bd-9f778aee26ee","title":"秋日旅舍别司空文明","author":"李端","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["凉风飒穷巷，秋思满高云。","吏隐俱不就，此心仍别君。","素怀宗淡泊，羁旅念功勋。","转忆西林寺，江声月下闻。"],"theme":"羁旅思乡","theme2":["送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["秋"],"cats":{"抒情":["离别","思念","思乡"],"四季":["秋天"],"山水":["庐山"]},"theme_conf":0.477},{"uid":"809cc96a-74a8-4569-a88d-c218523e0d3c","title":"相和歌辞 秋胡行","author":"高适","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["妾本邯郸未嫁时，容华倚翠人未知。","一朝结发从君子，将妾迢迢东路陲。","时逢大道无难阻，君方游宦从陈汝。","蕙楼独卧频度春，彩落辞君几徂暑。","三月垂杨蚕未眠，携笼结侣南陌边。","道逢行子不相识，赠妾黄金买少年。","妾家夫壻轻离久，寸心誓与长相守。","愿言行路莫多情，送妾贞心在人口。","日暮蚕饥相命归，携笼端饰来庭闱。","劳心苦力终无恨，所冀君恩那可依。","闻说行人已归止，乃是向来赠金子。","相看颜色不复言，相顾怀慙有何已。","从来自隐无疑背，直为君情也相会。","如何咫尺仍有情，况复迢迢千里外。","此时顾恩不顾身，念君此日赴河津。","莫道向来不得意，故欲留规诫后人。"],"theme":"闺情宫怨","theme2":["民生疾苦"],"style":"绮丽","style2":["沉郁","婉约"],"mood":"愁怨","mood2":["慷慨"],"scene":["秋","夏"],"cats":{"抒情":["闺怨"],"四季":["夏天","秋天"]},"theme_conf":0.84},{"uid":"a456cc8d-2cd1-41c9-9cc8-52163216510d","title":"西江上送渔父","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["却逐严光向若耶，钓轮菱櫂寄年华。","三秋梅雨愁枫叶，一夜篷舟宿苇花。","不见水云应有梦，偶随鸥鹭便成家。","白苹风起楼船暮，江燕双双五两斜。"],"theme":"送别","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["江","舟","秋"],"cats":{"抒情":["思念","伤感"],"四季":["秋天"],"山水":["江河"],"人物":["父亲"]},"theme_conf":0.443},{"uid":"cp9a38d953d1f347","title":"瑞鹤仙","author":"陆叡","dynasty":"宋","section":"宋词","form":"词","paragraphs":["湿云黏雁影。","望征路愁迷，离绪难整。","千金买光景。","但疏钟催晓，乱鸦啼暝。","花暗省。","许多情、相逢梦境。","便行云、都不归来，也合寄将音信。","孤迥。","盟鸾心在，跨鹤程高，后期无准。","情丝待翦。","翻惹得，旧时恨。","怕天教何处，参差双燕，还染残朱剩粉。","对菱花、与说相思，看谁瘦损。"],"theme":"送别","theme2":["爱情相思","游仙梦幻"],"style":"沉郁","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["鸟"],"cats":{"抒情":["爱情","思念","伤感"],"动物":["写鸟"]},"theme_conf":0.437},{"uid":"629687ee-7e6f-4b7a-8c3d-2034d5e752da","title":"远游联句","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["别肠车轮转，一日一万周。","离思春冰泮，澜漫不可收。","驰光忽以迫，飞辔谁能留。","取之讵灼灼，此去信悠悠。","楚客宿江上，夜魂栖浪头。","晓日生远岸，水芳缀孤舟。","村饮泊好木，野蔬拾新柔。","独含凄凄别，中结郁郁愁。","人忆旧行乐，鸟吟新得俦。","灵瑟时窅窅，霠猨夜啾啾。","愤涛气尚盛，恨竹泪空幽。","长怀绝无已，多感良自尤。","即路涉献岁，归期眇凉秋。","两欢日牢落，孤悲坐绸缪。","观怪忽荡漾，叩奇独冥搜。","海鲸吞明月，浪岛没大沤。","我有一寸钩，欲钓千丈流。","良知忽然远，壮志郁无抽。","魍魅暂出没，蛟螭互蟠蟉。","昌言拜舜禹，举颿凌斗牛。","怀糈餽贤屈，乘桴追圣丘。","飘然天外步，岂肯区中囚。","楚些待谁吊，贾辞缄恨投。","翳明弗可晓，秘魂安所求。","气毒放逐域，蓼杂芳菲畴。","当春忽凄凉，不枯亦飕飗。","貉谣众猥款，巴语相咿嚘。","默誓去外俗，嘉愿还中州。","江生行既乐，躬辇自相勠。","饮醇趣明代，味腥谢荒陬。","驰深鼓利檝，趋险惊蜚𬨎。","系石沈靳尚，开弓射𫛝吺。","路暗执屏翳，波惊戮阳侯。","广泛信缥缈，高行恣浮游。","外患萧萧去，中悒稍稍瘳。","振衣造云阙，跪坐陈清猷。","德风变谗巧，仁气销戈矛。","名声照西海，淑问无时休。","归哉孟夫子，归去无夷犹。"],"theme":"送别","theme2":["边塞征战","羁旅思乡","送别"],"style":"沉郁","style2":["幽峭","清新"],"mood":"愁怨","mood2":[],"scene":["春","月"],"cats":{"抒情":["离别","思乡","伤感","孤独"],"四季":["春天"],"天气":["月亮"],"人生":["励志","梦想"]},"theme_conf":0.83},{"uid":"bb93206b-92a8-4440-aeb5-4cc3bbe596ea","title":"送僧方及南谒柳员外","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔事庐山远，精舍虎溪东。","朝阳照瀑水，楼阁虹霓中。","骋望羡游云，振衣若秋蓬。","旧房闭松月，远思吟江风。","古寺历头陀，奇峰扳祝融。","南登小桂岭，却望归塞鸿。","衣裓贮文章，自言学雕虫。","抢榆念陵厉，覆篑图穹崇。","远郡多暇日，有诗访禅宫。","石门耸峭绝，竹院含空蒙。","幽响滴岩溜，晴芳飘野丛。","海云悬飓母，山果属狙公。","忽忆吴兴郡，白苹正葱茏。","愿言挹风采，邈若窥华嵩。","桂水夏澜急，火山宵焰红。","三衣濡菌露，一锡飞烟空。","勿谓翻译徒，不为文雅雄。","古来赏音者，燋爨得孤桐。"],"theme":"送别","theme2":["哲理悟道","送别"],"style":"幽峭","style2":["冲淡"],"mood":"相思","mood2":["孤寂"],"scene":["山"],"cats":{"抒情":["思念","孤独"],"山水":["庐山"],"天气":["彩虹","太阳"],"人生":["哲理"],"植物":["柳树"]},"theme_conf":0.92},{"uid":"d5ac076b-9170-4aa1-b6a4-c67a96445b79","title":"洛滨病卧户部李侍郎见惠药物谑以文星之句斐然仰谢","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["隐几支颐对落晖，故人书信到柴扉。","周南留滞商山老，星象如今属少微。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"抒情":["友情","感恩"],"天气":["星星"]},"theme_conf":0.95},{"uid":"7cece203-8db8-49ea-97f2-74f1f885a3bc","title":"青龙寺留别义操阇梨","author":"空海","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["同法同门喜遇深，空随白雾忽归岑。","一生一别难再见，非梦思中数数寻。","（同前）。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":["欢愉"],"scene":[],"cats":{"抒情":["离别"],"植物":["梨花"]},"theme_conf":0.715},{"uid":"7d3a1f16-ac20-4258-b134-a57b42713d8e","title":"鼓吹曲辞 临高台","author":"僧贯休","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["凉风吹远念，使我升高台。","宁知数片云，不是旧山来。","故人天一涯，久客殊未回。","雁来不得书，空寄声哀哀。"],"theme":"送别","theme2":["羁旅思乡"],"style":"冲淡","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["楼"],"cats":{"抒情":["友情","思乡"]},"theme_conf":0.563},{"uid":"e35de5fa-807c-4891-8749-b2c83757c89a","title":"九成宫","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["苍山入百里，崖断如杵臼。","曾宫凭风回，岌嶪土囊口。","立神扶栋梁，凿翠开户牖。","其阳产灵芝，其阴宿牛斗。","纷披长松倒，揭𡿗怪石走。","哀猨啼一声，客泪迸林薮。","荒哉隋家帝，制此今颓朽。","向使国不亡，焉为巨唐有。","虽无新增修，尚置官居守。","巡非瑶水远，迹是雕墙后。","我行属时危，仰望嗟叹久。","天王守太白，驻马更搔首。"],"theme":"咏史怀古","theme2":["羁旅思乡","悼亡挽歌"],"style":"绮丽","style2":["幽峭"],"mood":"悲怆","mood2":[],"scene":[],"cats":{"抒情":["思乡","伤感","悼亡","怀古"]},"theme_conf":0.95},{"uid":"bcf88d70-488c-40a7-b7bf-febc7ab7c797","title":"同王员外雨后登开元寺南楼因寄西岩警上人","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["过雨开楼看晚虹，白云相逐水相通。","寒蝉噪暮野无日，古树伤秋天有风。","数穗远烟凝垅上，一枝繁果忆山中。","何言暂别东林友，惆怅人间事不同。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":["相思"],"scene":["雨","楼","山","秋"],"cats":{"抒情":["思念"],"四季":["秋天"],"山水":["庐山"],"天气":["写雨"]},"theme_conf":0.87},{"uid":"2c036362-9f1d-434c-854f-b97a2a4bb19b","title":"天末忆李白","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["凉风起天末，君子意如何。","鸿雁几时到，江湖秋水多。","文章憎命达，魑魅喜人过。","应共冤魂语，投诗赠汩罗。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["江","秋"],"cats":{"抒情":["思念"],"四季":["秋天"]},"theme_conf":0.668},{"uid":"606d0bd8-31d2-4a7a-97ee-341956e7be60","title":"梦游天姥吟留别","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["海客谈瀛洲，烟涛微茫信难求。","越人语天姥，云霓明灭或可覩。","天姥连天向天横，势拔五岳掩赤城。","天台四万八千丈，对此欲倒东南倾。","我欲因之梦吴越，一夜飞度镜湖月。","湖月照我影，送我至剡溪。","谢公宿处今尚在，渌水荡漾清猨啼。","脚著谢公屐，身登青云梯。","半壁见海日，空中闻天鸡。","千岩万转路不定，迷花倚石忽已暝。","熊咆龙吟殷岩泉，栗深林兮惊层巅。","云青青兮欲雨，水澹澹兮生烟。","列缺霹雳，丘峦崩摧。","洞天石扇，訇然中开。","青冥浩荡不见底，日月照耀金银台。","霓为衣兮风为马，云之君兮纷纷而来下。","虎鼓瑟兮鸾回车，仙之人兮列如麻。","忽魂悸以魄动，怳惊起而长嗟。","惟觉时之枕席，失向来之烟霞。","世间行乐亦如此，古来万事东流水。","别君去时何时还，且放白鹿青崖间，须行即骑访名山。","安能摧眉折腰事权贵？使我不得开心颜。"],"theme":"游仙梦幻","theme2":["送别"],"style":"冲淡","style2":["婉约"],"mood":"相思","mood2":["恬淡"],"scene":["江南","山","江","月"],"cats":{"抒情":["离别","思念"],"人生":["梦想"]},"theme_conf":0.397},{"uid":"7277c420-9f3f-4093-a5b2-6331494721e8","title":"春思","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["燕草如碧丝，秦桑低绿枝。","当君怀归日，是妾断肠时。","春风不相识，何事入罗帏。"],"theme":"闺情宫怨","theme2":[],"style":"清新","style2":["婉约"],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"]},"theme_conf":1.0},{"uid":"3b5db620-1964-4674-a01d-ad70ba3ebd2a","title":"咏怀古迹五首 三","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["群山万壑赴荆门，生长明妃尚有村。","一去紫台连朔漠，独留青冢向黄昏。","画图省识春风面，环佩空归月夜魂。","千载琵琶作胡语，分明怨恨曲中论。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["塞外","山","夜"],"cats":{"抒情":["孤独","怀古"],"人物":["老师"]},"theme_conf":0.549},{"uid":"7dccdf60-ec93-4a4d-be1c-4d725b92cb8e","title":"秋雨叹三首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["雨中百草秋烂死，阶下决明颜色鲜。","著叶满枝翠羽盖，开花无树黄金钱。","凉风萧萧吹汝急，恐汝后时难独立。","堂上书生空白头，临风三齅馨香泣。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"悲怆","mood2":["孤寂"],"scene":["秋","雨"],"cats":{"抒情":["孤独"],"四季":["秋天"],"天气":["写雨"]},"theme_conf":0.8},{"uid":"775398c8-b809-40aa-af2f-93746dbc82ca","title":"客中有感","author":"殷尧藩","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["天地一身在，头颅五十过。","流年消壮志，空使泪成河。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"慷慨","mood2":["愁怨"],"scene":[],"cats":{"抒情":["思乡","伤感"],"人生":["励志","时光","梦想"]},"theme_conf":1.0},{"uid":"41d7e65e-5a99-4597-a1cc-d716c5380584","title":"石柜阁","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["季冬日已长，山晚半天赤。","蜀道多早花，江间饶奇石。","石柜曾波上，临虚荡高壁。","清晖回群鸥，暝色带远客。","羁栖负幽意，感叹向绝迹。","信甘孱懦婴，不独冻馁迫。","优游谢康乐，放浪陶彭泽。","吾衰未自安，谢尔性所适。"],"theme":"羁旅思乡","theme2":[],"style":"幽峭","style2":[],"mood":"恬淡","mood2":["孤寂","欢愉"],"scene":["楼","冬"],"cats":{"抒情":["思乡","孤独"],"四季":["冬天"]},"theme_conf":0.667},{"uid":"8e8e6eed-cb19-49b2-979a-ec1d3a0e3729","title":"萧宅二三子赠答诗二十首 竹请客","author":"卢仝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["我本泰山阿，避地到南国。","主人欲移家，我亦要归北。","上客幸先归，愿托归飞翼。","唯将翛翛风，累路报恩德。"],"theme":"咏物","theme2":["羁旅思乡"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"抒情":["思乡"],"山水":["泰山"],"植物":["竹子"]},"theme_conf":0.9},{"uid":"da9d7556-8296-4658-8f9f-d05ed47f75b9","title":"有僧言罗浮事因为诗以写之","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["君言罗浮上，容易见九垠。","渐高元气壮，汹涌来翼身。","夜宿最高峰，瞻望浩无邻。","海黑天宇旷，星辰来逼人。","是时当朏魄，阴物恣腾振。","日光吐鲸背，劒影开龙鳞。","倏若万马驰，旌旗耸奫沦。","又如广乐奏，金石含悲辛。","疑其有巨灵，怪物尽来宾。","阴阳迭用事，乃俾夜作晨。","咿喔天鸡鸣，扶桑色昕昕。","赤波千万里，涌出黄金轮。","下视生物息，霏如隙中尘。","醯鸡仰瓮口，亦谓云汉津。","世人信耳目，方寸度大钧。","安知视听外，怪愕不可陈。","悠悠想大方，此乃桮水滨。","知小天地大，安能识其真。"],"theme":"哲理悟道","theme2":["山水田园","边塞征战"],"style":"绮丽","style2":["豪放","幽峭"],"mood":"慷慨","mood2":["悲怆"],"scene":["夜"],"cats":{"抒情":["伤感"],"植物":["梅花"]},"theme_conf":0.409},{"uid":"9ca5eb72-69e6-47f0-a27d-06034645217d","title":"酬裴员外以诗代书","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["少时方浩荡，遇物犹尘埃。","脱略身外事，交游天下才。","单车入燕赵，独立心悠哉。","宁知戎马间，忽展平生怀。","且欣清论高，岂顾夕阳颓。","题诗碣石馆，纵酒燕王台。","北望沙漠垂，漫天雪皑皑。","临边无策略，览古空裴回。","乐毅吾所怜，拔齐翻见猜。","荆卿吾所悲，适秦不复廻。","然诺多死地，公忠成祸胎。","与君从此辞，每恐流年催。","如何俱老大，始复忘形骸。","兄弟真二陆，声名连八裴。","乙未将星变，贼臣候天灾。","胡骑犯龙山，乘舆经马嵬。","千官无倚着，万姓徒悲哀。","诛吕鬼神动，安刘天地开。","奔波走风尘，倏忽值云雷。","拥旄出淮甸，入幕征楚材。","誓当剪鲸鲵，永以竭驽骀。","小人胡不仁，谗我成死灰。","赖得日月明，照耀无不该。","留司洛阳宫，詹府唯蒿莱。","是时扫氛祲，尚未歼渠魁。","背河列长围，师老将亦乖。","归军剧风火，散卒争椎埋。","一夕瀍洛空，生灵悲曝腮。","衣冠投草莽，予欲驰江淮。","登顿宛叶下，栖遑襄邓隈。","城池何萧条，邑屋更崩摧。","纵横荆棘丛，但见瓦砾堆。","行人无血色，战骨多青苔。","遂除彭门守，因得朝玉阶。","激昂仰鹓鹭，献替欣盐梅。","驱传及远蕃，忧思郁难排。","罢人纷争讼，赋税如山崖。","所思在畿甸，曾是鲁宓侪。","自从拜郎官，列宿焕天街。","那能访遐僻，还复寄琼瓌。","金玉本高价，埙箎终易谐。","朗咏临清秋，凉风下庭槐。","何意寇盗间，独称名义偕。","辛酸陈侯诔，叹息季鹰杯。","白日屡分手，青春不再来。","卧看中散论，愁忆太常斋。","酬赠徒为尔，长歌还自咍。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["悲慨","豪放"],"mood":"悲怆","mood2":["孤寂","愁怨"],"scene":["酒","雪","园林"],"cats":{"抒情":["伤感","孤独"],"天气":["太阳"],"人生":["青春","时光","战争"]},"theme_conf":0.94},{"uid":"9f033648-d76a-4de4-ba1d-8c0298fa5c3d","title":"送薛居士和州读书","author":"严维","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["孤云独鹤共悠悠，万卷经书一叶舟。","楚地巢城民舍少，烟村社树鹭湖秋。","蒿莱织妾晨炊黍，隅落耕童夕放牛。","年少不应辞苦节，诸生若遇亦封侯。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["舟","秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"人生":["读书"]},"theme_conf":0.49},{"uid":"294f0816-30dd-4941-bb26-bb50378c91b0","title":"濮中言怀","author":"沈千运","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["圣朝优贤良，草泽无遗匿。","人生各有命，在余胡不淑。","一生但区区，五十无寸禄。","衰退当弃捐，贫贱招毁讟。","栖栖去人世，屯踬日穷迫。","不如守田园，岁晏望丰熟。","壮年失宜尽，老大无筋力。","始觉前计非，将贻后生福。","童儿新学稼，少女未能织。","顾此烦知己，终日求衣食。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":[],"cats":{"抒情":["友情"],"生活":["田野"]},"theme_conf":1.0},{"uid":"80159919-0b66-4956-a563-ef9bcf6a05c0","title":"金谷园","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["繁华事散逐香尘，流水无情草自春。","日暮东风怨啼鸟，落花犹似堕楼人。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["春","园林","花"],"cats":{"抒情":["怀古"],"四季":["春天"]},"theme_conf":0.586},{"uid":"3f049d66-1513-407f-bb4e-cf25a7b5069a","title":"自夏口至鹦鹉洲夕望岳阳寄源中丞","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["[汀]洲无浪复无烟，楚客相思益渺然。","汉口夕阳斜渡鸟，洞庭秋水远连天。","孤城背岭寒吹角，独戍临江夜泊船。","贾谊上书忧汉室，长沙谪去古今怜。"],"theme":"寄赠酬答","theme2":["应制干谒","山水田园"],"style":"婉约","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["江"],"cats":{"抒情":["思念","孤独"],"四季":["夏天"]},"theme_conf":0.9},{"uid":"0e651edd-1bc8-49c9-bd85-b49df84c9743","title":"横吹曲辞 折杨柳","author":"韦承庆","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["万里边城地，三春杨柳节。","叶似镜中眉，花如关外雪。","征人远乡思，倡妇高楼别。","不忍掷年华，含情寄攀折。"],"theme":"送别","theme2":["边塞征战","羁旅思乡"],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["雪","春","楼"],"cats":{"抒情":["思乡"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.463},{"uid":"e1f2edef-a6a6-40bd-97e1-c5dedb7976b2","title":"题桐叶","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["去年桐落故溪上，把笔偶题归燕诗。","江楼今日送归燕，正是去年题叶时。","叶落燕归真可惜，东流玄髪且无期。","笑筵歌席反惆怅，明月清风怆别离。","庄叟彭殇同在梦，陶潜身世两相遗。","一丸五色成虚语，石烂松薪更莫疑。","哆侈不劳文似锦，进趋何必利如锥。","钱神任尔知无敌，酒圣于吾亦庶几。","江畔秋光蟾阁镜，槛前山翠茂陵眉。","樽香轻泛数枝菊，簷影斜侵半局棋。","休指宦游论巧拙，秪将愚直祷神祇。","三吴烟水平生念，宁向闲人道所之。"],"theme":"咏怀抒感","theme2":["闲适隐逸","咏物"],"style":"旷达","style2":["婉约","绮丽"],"mood":"惆怅","mood2":[],"scene":["月","酒","楼"],"cats":{"抒情":["离别"],"天气":["月亮"],"植物":["叶子"]},"theme_conf":0.85},{"uid":"cp6fe48a6dc4fefb","title":"瑞鹤仙","author":"袁去华","dynasty":"宋","section":"宋词","form":"词","paragraphs":["郊原初过雨。","见败叶零乱，风定犹舞。","斜阳挂深树。","映浓愁浅黛，遥山眉妩。","来时旧路。","尚岩花、娇黄半吐。","到而今，唯有溪边流水，见人如故。","无语。","邮亭深静，下马还寻，旧曾题处。","无聊倦旅。","伤离恨，最愁苦。","纵收香藏镜，他年重到，人面桃花在否。","念沈沈、小阁幽窗，有时梦去。"],"theme":"爱情相思","theme2":["羁旅思乡","游仙梦幻","闺情宫怨"],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["山","楼","鸟","花","雨"],"cats":{"抒情":["思乡","伤感","闺怨"],"动物":["写鸟"]},"theme_conf":0.79},{"uid":"44e15dd3-3621-46ff-be2a-145555ed2593","title":"城西竹园送裴佶王达","author":"李益","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["葳蕤凌风竹，寂寞离人觞。","怆怀非外至，沈郁自中肠。","远行从此始，别袂重凄霜。"],"theme":"送别","theme2":[],"style":"旷达","style2":["冲淡"],"mood":"孤寂","mood2":["愁怨"],"scene":["园林","酒"],"cats":{"抒情":["离别","孤独"],"植物":["竹子"]},"theme_conf":0.809},{"uid":"d0fa1454-f337-4343-ab4a-2a42dfdf4e8f","title":"春宫曲","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["昨夜风开露井桃，未央前殿月轮高。","平阳歌舞新承宠，帘外春寒赐锦袍。"],"theme":"闺情宫怨","theme2":[],"style":"清新","style2":["绮丽"],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"]},"theme_conf":1.0},{"uid":"b64c656c-1346-4fce-9667-57d2472ab4f2","title":"岁日作","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["不觉老将春共至，更悲携手几人全。","还丹寂寞羞明镜，手把屠苏让少年。"],"theme":"节令风俗","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["孤寂"],"scene":["春"],"cats":{"抒情":["伤感","孤独"],"四季":["春天"],"节日":["春节"]},"theme_conf":0.78},{"uid":"e7c246f6-8c50-43a0-b4ad-6a42a6cf6d7e","title":"云梦故城秋望","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["故国遗墟在，登临想旧游。","一朝人事变，千载水空流。","梦渚鸿声晚，荆门树色秋。","片云凝不散，遥挂望乡愁。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡","怀古"],"四季":["秋天"],"天气":["写云"],"人生":["梦想"]},"theme_conf":0.479},{"uid":"60cc0c7d-7a16-4474-9e97-710f3f5ba362","title":"秋灯","author":"王建","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["向壁暖悠悠，罗帏寒寂寂。","斜照碧山图，松间一片石。"],"theme":"闺情宫怨","theme2":[],"style":"幽峭","style2":["冲淡"],"mood":"孤寂","mood2":[],"scene":["秋","元宵","夜"],"cats":{"抒情":["闺怨"],"四季":["秋天"],"节日":["元宵节"]},"theme_conf":1.0},{"uid":"cpe95478f7a37a64","title":"薄幸","author":"吕渭老","dynasty":"宋","section":"宋词","form":"词","paragraphs":["青楼春晚。","昼寂寂、梳匀又懒。","乍听得、鸦啼莺弄，惹起新愁无限。","记年时、偷掷春心，花间隔雾遥相见。","便角枕题诗，宝钗贳酒，共醉青苔深院。","怎忘得、回廊下，携手处、花明月满。","如今但暮雨，蜂愁蝶恨，小窗闲对芭蕉展。","却谁拘管。","尽无言、闲品秦筝，泪满参差雁。","腰支渐小，心与杨花共远。"],"theme":"闺情宫怨","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["鸟","春","月","酒","园林"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"天气":["月亮"]},"theme_conf":0.62},{"uid":"91019fe2-b58e-4320-a986-6a323847e944","title":"相和歌辞 春江花月夜","author":"张若虚","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["春江潮水连海平，海上明月共潮生。","滟滟随波千万里，何处春江无月明？","江流宛转遶芳甸，月照花林皆似霰。","空里流霜不觉飞，汀上白沙看不见。","江天一色无纤尘，皎皎空中孤月轮。","江畔何人初见月？江月何年初照人？","人生代代无穷已，江月年年望相似。","不知江月待何人，但见长江送流水。","白云一片去悠悠，青枫浦上不胜愁。","谁家今夜扁舟子，何处相思明月楼？","可怜楼上月裴回，应照离人妆镜台。","玉户帘中卷不去，捣衣砧上拂还来。","此时相望不相闻，愿逐月华流照君。","鸿雁长飞光不度，鱼龙潜跃水成文。","昨夜闲潭梦落花，可怜春半不还家。","江水流春去欲尽，江潭落月复西斜。","斜月沈沈藏海雾，碣石潇湘无限路。","不知乘月几人归，落月摇情满江树。"],"theme":"爱情相思","theme2":["送别","羁旅思乡"],"style":"豪放","style2":["沉郁"],"mood":"相思","mood2":[],"scene":["江","月","春"],"cats":{"抒情":["爱情","思念","思乡"],"四季":["春天"],"山水":["江河","长江"],"天气":["月亮"]},"theme_conf":0.75},{"uid":"a8d2011c-dc24-4e9a-a795-92e7473c7ad1","title":"春夜过长孙绎别业","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["佳期难再得，清夜此云林。","带竹新泉冷，穿花片月深。","含毫凝逸思，酌水话幽心。","不觉星河转，山枝惊曙禽。"],"theme":"山水田园","theme2":["送别","闲适隐逸","咏史怀古"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["夜","春"],"cats":{"抒情":["离别","怀古"],"四季":["春天"],"天气":["星星"]},"theme_conf":0.74},{"uid":"c74950d3-3194-4abe-a37c-03a623d03636","title":"送李明府赴滑州","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["渭城寒食罢，送客归远道。","乌帽背斜晖，青骊踏春草。","酒醒孤烛夜，衣冷千山早。","去事沈尚书，应怜词赋好。"],"theme":"送别","theme2":[],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["清明","春","酒","夜"],"cats":{"抒情":["孤独"],"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.633},{"uid":"ac2ea361-8c0d-4c98-b95e-bfcc95443067","title":"相和歌辞 凤笙曲","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["忆昔王子晋，凤笙游云空。","挥手弄白日，安能恋青宫。","岂无婵娟子，结念罗帐中。","怜寿不贵色，身世两无穷。"],"theme":"游仙梦幻","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["中秋"],"cats":{"抒情":["思念"],"节日":["中秋节"]},"theme_conf":0.93},{"uid":"dfe41fd5-0f8c-4a52-9ce5-8622202264ff","title":"琴曲歌辞 湘妃怨","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["南巡竟不返，帝子怨逾积。","万里丧蛾眉，潇湘水空碧。","冥冥荒山下，古庙收贞魄。","乔木深青春，清光满瑶席。","搴芳徒有荐，灵意殊脉脉。","玉佩不可亲，裴回烟波夕。"],"theme":"闺情宫怨","theme2":["闲适隐逸"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春","江","山"],"cats":{"抒情":["闺怨"],"四季":["春天"],"人生":["青春"]},"theme_conf":0.593},{"uid":"cpd9253d8e5dea2b","title":"点绛唇","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["燕雁无心，太湖西畔随云去。","数峰清苦。","商略黄昏雨。","第四桥边，拟共天随住。","今何许。","凭栏怀古。","残柳参差舞。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"清新","style2":["冲淡"],"mood":"恬淡","mood2":[],"scene":["鸟","雨"],"cats":{"抒情":["怀古"],"生活":["写桥"]},"theme_conf":0.582},{"uid":"41181679-c303-4d56-a0a2-f454236cfa0b","title":"裴侍御见赠斑竹杖","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["骚人夸竹杖，赠我意何深。","万点湘妃泪，三年贾谊心。","愿持终白首，谁道贵黄金。","他日归愚谷，偏宜绿绮琴。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":["婉约","沉郁"],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["伤感"],"植物":["竹子"]},"theme_conf":0.78},{"uid":"bbe30e55-8238-495c-bcf9-8144fe363439","title":"自淇涉黄河途中作十三首 六","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋日登滑台，台高秋已暮。","独行既未惬，怀土怅无趣。","晋宋何萧条，羌胡散驰骛。","当时无战略，此地即边戍。","兵革徒自勤，山河孰云固。","乘闲喜临眺，感物伤游寓。","惆怅落日前，飘飖远帆处。","北风吹万里，南雁不知数。","归意方浩然，云沙更廻互。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"惆怅","mood2":["孤寂","欢愉"],"scene":["江","秋","舟"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["江河","黄河"],"人生":["战争"]},"theme_conf":1.0},{"uid":"184965e8-dd83-4699-afb1-eac6f8211dab","title":"惜别行送刘仆射判官","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["闻道南行市骏马，不限匹数军中须。","襄阳幕府天下异，主将俭省忧艰虞。","祗收壮健胜铁甲，岂因格鬬求龙驹。","而今西北自反胡，骐𬴊荡尽一匹无。","龙媒真种在帝都，子孙永落西南隅。","向非戎事备征伐，君肯辛苦越江湖。","江湖凡马多顦顇，衣冠往往乘蹇驴。","梁公富贵于身疎，号令明白人安居。","俸钱时散士子尽，府库不为骄豪虚。","以兹报主寸心赤，气却西戎回北狄。","罗网群马籍马多，气在驱驰出金帛。","刘侯奉使光推择，滔滔才略沧溟窄。","杜陵老翁秋系船，扶病相识长沙驿。","强梳白发提胡卢，手把菊花路旁摘。","九州兵革浩茫茫，三叹聚散临重阳。","当杯对客忍流涕，君不觉老夫神内伤。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["绮丽"],"mood":"慷慨","mood2":["愁怨"],"scene":["重阳","江"],"cats":{"抒情":["离别","伤感"],"节日":["重阳节"]},"theme_conf":0.468},{"uid":"c0f1c8ed-bbf8-4ace-ac86-91e5e57d8ece","title":"鼓吹曲辞 战城南","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["去年战桑干源，今年战葱河道。","洗兵条支海上波，放马天山雪中草。","万里长征战，三军尽衰老。","匈奴以杀戮为耕作，古来唯见白骨黄沙田。","秦家筑城备胡处，汉家还有烽火然。","烽火然不息，征战无已时。","野战格鬬死，败马号鸣向天悲。","乌鸢啄人肠，衔飞上挂枯树枝。","士卒涂草莽，将军空尔为。","乃知兵者是凶器，圣人不得已而用之。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["雪"],"cats":{"抒情":["伤感"],"人生":["战争"]},"theme_conf":0.753},{"uid":"5a76b6ea-07ee-44b6-ac20-a87d18203810","title":"答侯少府","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["常日好读书，晚年学垂纶。","漆园多乔木，睢水清粼粼。","诏书下柴门，天命敢逡巡。","赫赫三伏时，十日到咸秦。","褐衣不得见，黄绶翻在身。","吏道顿羁束，生涯难重陈。","北使经大寒，关山饶苦辛。","边兵若刍狗，战骨成埃尘。","行矣勿复言，归欤伤我神。","如何燕赵陲，忽遇平生亲。","开馆纳征骑，弹弦娱远宾。","飘飖天地间，一别方兹晨。","东道有佳作，南朝无此人。","性灵出万象，风骨超常伦。","吾党谢王粲，群贤推郄诜。","明时取秀才，落日过蒲津。","节苦名已富，禄微家转贫。","相逢愧薄游，抚己荷陶钧。","心事正堪尽，离居宁太频。","两河归路遥，二月芳草新。","柳接滹沱暗，莺连渤海春。","谁谓行路难，猥当希代珍。","提握每终日，相思犹比邻。","江海有扁舟，丘园有角巾。","君意定何适，我怀知所遵。","浮沈各异宜，老大贵全真。","莫作云霄计，遑遑随缙绅。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"清新","style2":["旷达"],"mood":"相思","mood2":[],"scene":["舟","春","鸟"],"cats":{"抒情":["离别","思念","思乡"],"四季":["春天"],"天气":["太阳"],"人生":["读书","战争"]},"theme_conf":0.96},{"uid":"1d70922b-4e1b-4eb5-ae5b-79df44859f57","title":"新竹","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["笋添南堦竹，日日成清閟。","缥节已储霜，黄苞犹揜翠。","出栏抽五六，当户罗三四。","高标陵秋严，贞色夺春媚。","稀生巧补林，并出疑争地。","纵横乍依行，烂熳忽无次。","风枝未飘吹，露粉先涵泪。","何人可携玩，清景空瞪视。"],"theme":"山水田园","theme2":["咏物"],"style":"清新","style2":["绮丽"],"mood":"愁怨","mood2":[],"scene":["秋","春"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"],"植物":["竹子"]},"theme_conf":0.609},{"uid":"002d65d7-a386-46f1-8c8f-007095ec68bd","title":"岁暮怀崔峒耿𣲗","author":"司空曙","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["腊月江天见春色，白花青柳疑寒食。","洛阳旧社各东西，楚国游人不相识。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["清明","春","月"],"cats":{"抒情":["思乡"],"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.87},{"uid":"200fe9fa-0221-4123-86de-4d63ce9d3daf","title":"旅宿","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["旅馆无良伴，凝情自悄然。","寒灯思旧事，断鴈警愁眠。","远梦归侵晓，家书到隔年。","湘江好烟月，门系钓鱼船。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["月","舟","江"],"cats":{"抒情":["思乡","伤感"]},"theme_conf":1.0},{"uid":"67cea0fa-4c7b-456a-ae5d-574d1dc8a878","title":"晚投江泽浦即事呈柳兵曹泥","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["落日过重霞，轻烟上远沙。","移舟冲荇蔓，转浦入芦花。","断岸迂来客，连波漾去槎。","故乡何处在，更道向天涯。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["江","舟"],"cats":{"抒情":["思乡"],"人生":["战争"],"植物":["柳树"]},"theme_conf":0.719},{"uid":"b14af996-a066-4cff-8903-35e2d658155a","title":"送许八拾遗归江宁觐省甫昔时尝客游此县于许生处乞瓦棺寺维摩图样志诸篇末","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["诏许辞中禁，慈颜赴北堂。","圣朝新孝理，祖席倍辉光。","内帛擎偏重，宫衣著更香。","淮阴清夜驿，京口渡江航。","春隔鸡人昼，秋期燕子凉。","赐书夸父老，寿酒乐城隍。","看画曾饥渴，追踪恨淼茫。","虎头金粟影，神妙独难忘。"],"theme":"送别","theme2":["羁旅思乡","送别"],"style":"清新","style2":["沉郁"],"mood":"愁怨","mood2":["孤寂","欢愉"],"scene":["江","夜"],"cats":{"抒情":["思乡","孤独"],"山水":["江河"],"人生":["梦想"]},"theme_conf":0.94},{"uid":"cpfccab6cdeebb35","title":"石州引・石州慢","author":"贺铸","dynasty":"宋","section":"宋词","form":"词","paragraphs":["薄雨初寒，斜照弄晴，春意空阔。","长亭柳色缠黄，远客一枝先折。","烟横水际，映带几点归鸦，东风销尽龙沙雪。","还记初关来，恰而今时节。","将发。","画楼芳酒，红泪清歌，顿成清别。","已是经年，杳杳音尘多绝。","欲知方寸，共有几许清愁，芭蕉不展丁香结。","枉望断天涯，两厌厌风月。"],"theme":"送别","theme2":["羁旅思乡"],"style":"清新","style2":["沉郁","幽峭"],"mood":"愁怨","mood2":[],"scene":["春","楼","花","雪","酒"],"cats":{"抒情":["离别","思乡","伤感"],"四季":["春天"]},"theme_conf":0.509},{"uid":"a8be14f6-49ea-4e59-ad37-30bcf16e17a6","title":"忆友怀野寺旧居","author":"李端","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["自嫌野性共人疎，忆向西林更结庐。","寄谢山阴许都讲，昨来频得远公书。"],"theme":"哲理悟道","theme2":["闲适隐逸","送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["山"],"cats":{"抒情":["友情","思念"],"山水":["庐山"]},"theme_conf":0.393},{"uid":"3d449437-09a5-462b-86e5-e1ff2fdfc832","title":"东楼","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["万里流沙道，西征过北门。","但添新战骨，不返旧征魂。","楼角临风迥，城阴带水昏。","传声看驿使，送节向河源。"],"theme":"送别","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["楼"],"cats":{"抒情":["思乡"],"山水":["黄河"]},"theme_conf":0.577},{"uid":"cp280c3e690a30c6","title":"谢金莲诗酒红梨花・乌夜啼","author":"张寿卿","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["这的是一朵红梨花，休猜做枯枝杏，恰便似佳人面晕微醒。","他三春独掌着花权柄，枝叶儿青青，颜色儿荧荧。","且休说四季牡丹亭，更休过黄花径。","这花与灯，偏相称，灯光闪烁，花影轻盈。","(赵汝州云)小娘子，既有如此好花，何不作一首诗？(正旦云)我单提着红梨花作诗一首。","(赵汝州云)小娘子，你就表白咱。","(正旦念诗科，云)本分天然白雪香，谁知今日却浓妆？秋千院落溶溶月，羞睹红脂睡海棠。","(赵汝州云)妙、妙、妙。","小生也做一首。","(念诗科，云)换却冰肌玉骨胎，丹心吐出异香来。","武陵溪畔人休说，只恐夭桃不敢开。","(正旦云)好高才也。","(唱)。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"孤寂","mood2":[],"scene":["花","夜"],"cats":{"抒情":["孤独","感恩"],"人物":["女子"],"植物":["梨花","荷花"],"食物":["写酒"]},"theme_conf":1.0},{"uid":"ae2ca5e0-6550-4704-8c4f-41d44eb616ef","title":"舞曲歌辞 独漉歌","author":"王建","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["独独漉漉，鼠食猫肉。","乌日中，鹤露宿，黄河水直人心曲。"],"theme":"讽喻刺世","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["孤独"],"山水":["黄河"]},"theme_conf":0.9},{"uid":"93d82a12-5e4d-45c2-b837-d0c54447fba3","title":"与高适薛据慈恩寺浮图","author":"岑参","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["塔势如涌出，孤高耸天宫。","登临出世界，磴道盘虚空。","突兀压神州，峥嵘如鬼工。","四角碍白日，七层摩苍穹。","下窥指高鸟，俯听闻惊风。","连山若波涛，奔凑似朝东。","青槐夹驰道，宫馆何玲珑。","秋色从西来，苍然满关中。","五陵北原上，万古青蒙蒙。","净理了可悟，胜因夙所宗。","誓将挂冠去，觉道资无穷。"],"theme":"题画咏艺","theme2":["哲理悟道"],"style":"雄浑","style2":[],"mood":"孤寂","mood2":["恬淡","愁怨"],"scene":["秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"人生":["哲理"]},"theme_conf":0.615},{"uid":"7e6c09bc-04e4-487b-b201-43aaf6955c73","title":"送苏参军","author":"戎昱","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["忆昨青襟醉里分，酒醒回首怆离群。","舟移极浦城初掩，山束长江日早曛。","客来有恨空思德，别后谁人更议文。","常叹苏生官太屈，应缘才似鲍参军。"],"theme":"送别","theme2":["边塞征战"],"style":"豪放","style2":["沉郁"],"mood":"相思","mood2":["愁怨"],"scene":["江","酒"],"cats":{"抒情":["离别","思念"],"山水":["长江"]},"theme_conf":0.561},{"uid":"7f92251f-8521-4f44-ac7f-2cb17365e348","title":"同皇甫冉赴官留别灵一上人","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["法许庐山远，诗传休上人。","独归双树宿，静与百花亲。","对物虽留兴，观空已悟身。","能令折腰客，遥赏竹房春。"],"theme":"送别","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["欢愉","恬淡"],"scene":["山"],"cats":{"抒情":["离别","孤独"],"山水":["庐山"]},"theme_conf":0.553},{"uid":"cpa67f4336a27ef4","title":"剑器近","author":"袁去华","dynasty":"宋","section":"宋词","form":"词","paragraphs":["夜来雨。","赖倩得、东风吹住。","海棠正妖饶处。","且留取。","悄庭户。","试细听、莺啼燕语。","分明共人愁绪。","怕春去。","佳树。","翠阴初转午。","重帘未卷，乍睡起、寂寞看风絮。","偷弹清泪寄烟波，见江头故人，为言憔悴如许。","彩笺无数。","去却寒暄，到了浑无定据。","断肠落日千山暮。"],"theme":"送别","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春","江","鸟"],"cats":{"抒情":["友情","伤感","孤独"],"四季":["春天"]},"theme_conf":0.637},{"uid":"81b905b4-aac5-4509-ba20-0826d15e9272","title":"寄郑二侍御归新郑无碍寺所居","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["何事休官早，归来作郑人。","云山随伴侣，伏腊见乡亲。","南亩无三径，东林寄一身。","谁当便静者，莫使甑生尘。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"旷达","style2":["清新"],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"抒情":["思乡"],"山水":["庐山"]},"theme_conf":0.9},{"uid":"cbceb077-c964-4d19-8fa4-3b2c6613c08c","title":"杂曲歌辞 破阵乐 三","author":"不详","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["少年胆气凌云，共许骁雄出群。","匹马城南挑战，单刀蓟北从军。","一鼓鲜卑送欵，五饵单于解纷。","誓欲成名报国，羞将开口论勋。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":["欢愉"],"scene":[],"cats":{"抒情":["爱国"],"人生":["战争"]},"theme_conf":0.845},{"uid":"3b52ca46-63f4-441a-97cc-dd5d1b722a47","title":"琴曲歌辞  幽居弄","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["苔衣生，花露滴，月入西林荡东壁。","扣商占角两三声，洞户谿窗一冥寂。","独去沧洲无四邻，身婴世网此何身？","关情命曲寄惆怅，久别江南山里人。"],"theme":"闲适隐逸","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["惆怅"],"scene":["江","江南","月"],"cats":{"抒情":["孤独"],"山水":["庐山"]},"theme_conf":0.62},{"uid":"451fc40e-4dad-47ec-88e7-bb54fbc6bb60","title":"东平留赠狄司马","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["古人无宿诺，兹道以为难。","万里赴知己，一言诚可叹。","马蹄经月窟，劒术指楼兰。","地出北庭尽，城临西海寒。","森然瞻武库，则是弄儒翰。","入幕绾银绶，乘轺兼铁冠。","练兵日精锐，杀敌无遗残。","献捷见天子，论功俘可汗。","激昂丹墀下，顾盼青云端。","谁谓纵横策，翻为权势干。","将军既坎𡒄，使者亦辛酸。","耿介挹三事，羇离从一官。","知君不得意，他日会鹏抟。"],"theme":"寄赠酬答","theme2":["边塞征战"],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"抒情":["友情"],"人生":["梦想"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.86},{"uid":"6d7b4fc4-62ae-48e7-a486-a8ff73caaf7d","title":"送日本国聘贺使晁巨卿东归","author":"包佶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["上才生下国，东海是西邻。","九译蕃君使，千年圣主臣。","野情偏得礼，木性本含真。","锦帆乘风转，金装照地新。","孤城开蜃阁，晓日上朱轮。","早识来朝岁，涂山玉帛均。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["舟","楼","山"],"cats":{"抒情":["孤独"],"天气":["太阳"]},"theme_conf":0.745},{"uid":"f699ef22-319a-481b-8575-103300613ab9","title":"仆射来示有三春向晚四者难幷之说诚哉是言辄引起题重为联句疲兵再战勍敌难降下笔之时冁然自哂走呈仆射兼简尚书","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["三春今向晚，四者昔难幷。","借问低眉坐，何如携手行。","旧游多过隙，新宴且寻盟。","鹦鹉林须乐，麒麟阁未成。","分阴当爱惜，迟景好逢迎。","林野熏风起，楼台谷雨晴。","墙低山半出，池广水初平。","桥转长虹曲，舟回小鹢轻。","残花犹布绣，密竹自闻笙。","欲过芳菲节，难忘宴慰情。","月轮行似箭，时物始如倾。","见雁随兄去，听莺求友声。","蕙长书带展，菰嫩剪刀生。","坐密衣裳暖，堂虚丝管清。","峰峦侵碧落，草木近朱明。","与点非沂水，陪膺是洛城。","拨醅争绿醑，卧酪待朱樱。","几处能留客，何人唤解酲。","旧仪尊右揆，新命宠春卿。","有喜鹊频语，无机鸥不惊。","青林思小隐，白雪仰芳名。","访旧殊千里，登高赖九城。","酂侯司管钥，疏傅傲簪缨。","纶綍曾同掌，烟霄即上征。","册庭尝接武，书殿忝连衡。","兰室春弥馥，松心晚更贞。","琴招翠羽下，钩掣紫鳞呈。","只愿回乌景，谁能避兕觥。","方知醉兀兀，应是走营营。","凤阁鸾台路，从他年少争。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"抒情":["感恩"],"四季":["春天"],"天气":["彩虹"],"人生":["战争"],"生活":["写桥"]},"theme_conf":0.88},{"uid":"cp157df1f3a98fb8","title":"夜游宫","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["叶下斜阳照水。","卷轻浪、沈沈千里。","桥上酸风射眸子。","立多时，看黄昏，灯火市。","古屋寒窗底。","听几片、井桐飞坠。","不恋单衾再三起。","有谁知，为萧娘，书一纸。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["夜"],"cats":{"抒情":["闺怨"],"人生":["读书"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"a335f6c4-e9df-47d5-879d-9ebd3c1baf5c","title":"北征","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["皇帝二载秋，闰八月初吉。","杜子将北征，苍茫问家室。","维时遭艰虞，朝野少暇日。","顾慙恩私被，诏许归蓬荜。","拜辞诣阙下，怵惕久未出。","虽乏谏诤姿，恐君有遗失。","君诚中兴主，经纬固密勿。","东胡反未已，臣甫愤所切。","挥涕恋行在，道途犹恍惚。","乾坤含疮痍，忧虞何时毕。","靡靡逾阡陌，人烟眇萧瑟。","所遇多被伤，呻吟更流血。","回首凤翔县，旌旗晚明灭。","前登寒山重，屡得饮马窟。","邠郊入地底，泾水中荡潏。","猛虎立我前，苍崖吼时裂。","菊垂今秋花，石戴古车辙。","青云动高兴，幽事亦可悦。","山果多琐细，罗生杂橡栗。","或红如丹砂，或黑如点漆。","雨露之所濡，甘苦齐结实。","缅思桃源内，益叹身世拙。","坡陀望鄜畤，岩谷互出没。","我行已水滨，我仆犹木末。","鸱鸟鸣黄桑，野鼠拱乱穴。","夜深经战场，寒月照白骨。","潼关百万师，往者散何卒。","遂令半秦民，残害为异物。","况我堕胡尘，及归尽华发。","经年至茅屋，妻子衣百结。","恸哭松声回，悲泉共幽咽。","平生所娇儿，颜色白胜雪。","见耶背面啼，垢腻脚不韤。","床前两小女，补绽才过膝。","海图坼波涛，旧绣移曲折。","天吴及紫凤，颠倒在裋褐。","老夫情怀恶，呕泄卧数日。","那无囊中帛，救汝寒凛栗。","粉黛亦解苞，衾裯稍罗列。","瘦妻面复光，痴女头自栉。","学母无不为，晓妆随手抹。","移时施朱铅，狼藉画眉阔。","生还对童穉，似欲忘饥渴。","问事竞挽须，谁能即嗔喝。","飜思在贼愁，甘受杂乱聒。","新归且慰意，生理焉能说。","至尊尚蒙尘，几日休练卒。","仰观天色改，坐觉祅气豁。","阴风西北来，惨澹随回鹘。","其王愿助顺，其俗善驰突。","送兵五千人，驱马一万匹。","此辈少为贵，四方服勇决。","所用皆鹰腾，破敌过箭疾。","圣心颇虚伫，时议气欲夺。","伊洛指掌收，西京不足拔。","官军请深入，蓄锐何俱发。","此举开青徐，旋瞻略恒碣。","昊天积霜露，正气有肃杀。","祸转亡胡岁，势成擒胡月。","胡命其能久，皇纲未宜绝。","忆昨狼狈初，事与古先别。","奸臣竟葅醢，同恶随荡析。","不闻夏殷衰，中自诛褒妲。","周汉获再兴，宣光果明哲。","桓桓陈将军，仗钺奋忠烈。","微尔人尽非，于今国犹活。","凄凉大同殿，寂寞白兽闼。","都人望翠华，佳气向金阙。","园陵固有神，埽洒数不缺。","煌煌太宗业，树立甚宏达。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"沉郁","style2":["绮丽","悲慨"],"mood":"悲怆","mood2":["愁怨"],"scene":["秋","山","夜","夏","月"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["夏天","秋天"],"人物":["儿童"],"人生":["战争"]},"theme_conf":0.6},{"uid":"cp2a47b894761820","title":"青玉案","author":"无名氏","dynasty":"宋","section":"宋词","form":"词","paragraphs":["一年春事都来几。","早过了、三之二。","绿暗红嫣浑可事。","绿杨庭院，暖风帘幕，有个人憔悴。","买花载酒长安市。","又争似家山见桃李。","不枉东风吹客泪，相思难表，梦魂无据，惟有归来是。"],"theme":"羁旅思乡","theme2":["爱情相思"],"style":"婉约","style2":["绮丽"],"mood":"相思","mood2":[],"scene":["春","园林"],"cats":{"抒情":["爱情","思念","思乡"],"四季":["春天"]},"theme_conf":0.571},{"uid":"f0b251a5-be1f-43fe-bcf5-f87911834bdd","title":"过长孙宅与朗上人茶会","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["偶与息心侣，忘归才子家。","玄谈兼藻思，绿茗代榴花。","岸帻看云卷，含毫任景斜。","松乔若逢此，不复醉流霞。"],"theme":"闲适隐逸","theme2":["咏史怀古"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["酒"],"cats":{"抒情":["怀古"],"食物":["写茶"]},"theme_conf":0.84},{"uid":"cp0c23cd9569bd5c","title":"渡江云","author":"张炎","dynasty":"宋","section":"宋词","form":"词","paragraphs":["山空天入海，倚楼望极，风急暮潮初。","一帘鸠外雨，几处闲田，隔水动春锄。","新烟禁柳，想如今、绿到西湖。","犹记得、当年深隐，门掩两三株。","愁余。","荒洲古溆，断梗疏萍，更漂流何处。","空自觉、围羞带减，影怯灯孤。","常疑即见桃花面，甚近来、翻笑无书。","书纵远，如何也都无。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["冲淡","清新"],"mood":"孤寂","mood2":["愁怨"],"scene":["江"],"cats":{"抒情":["思乡","伤感","孤独"],"山水":["西湖"]},"theme_conf":0.95},{"uid":"e40d3f8a-7e0c-47df-b0a4-f2e55fded03a","title":"陪包谏议湖墅路中举帆","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["萧萧凉雨歇，境物望中闲。","风际片帆去，烟中独鸟还。","断桥通远浦，野墅接秋山。","更喜陪清兴，尊前一解颜。"],"theme":"山水田园","theme2":["山水田园"],"style":"冲淡","style2":[],"mood":"欢愉","mood2":["孤寂","恬淡"],"scene":["舟"],"cats":{"抒情":["孤独"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":0.88},{"uid":"2d7646fe-985e-4673-a554-61497dd86c8c","title":"同严给事闻唐昌观玉蘂近有仙过因成绝句二首 一","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["千枝花里玉尘飞，阿母宫中见亦稀。","应共诸仙鬬百草，独来偷得一枝归。"],"theme":"游仙梦幻","theme2":["咏史怀古"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":[],"cats":{"抒情":["孤独","怀古"],"人物":["母亲"]},"theme_conf":0.642},{"uid":"2c152693-c25f-45ce-8ef2-cbedce1a62bc","title":"望月怀远","author":"张九龄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["海上生明月，天涯共此时。","情人怨遥夜，竟夕起相思。","灭烛怜光满，披衣觉露滋。","不堪盈手赠，还寝梦佳期。"],"theme":"羁旅思乡","theme2":["爱情相思"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["月"],"cats":{"抒情":["爱情","思念","思乡"],"天气":["月亮"]},"theme_conf":0.377},{"uid":"670009c2-a701-4140-aa31-b4973f76d632","title":"隋宫","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["紫泉宫殿锁烟霞，欲取芜城作帝家。","玉玺不缘归日角，锦帆应是到天涯。","于今腐草无萤火，终古垂杨有暮鸦。","地下若逢陈后主，岂宜重问后庭花。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["舟","园林"],"cats":{"抒情":["怀古"]},"theme_conf":0.618},{"uid":"cpd98ebb7b2c6b91","title":"蓦山溪","author":"曹组","dynasty":"宋","section":"宋词","form":"词","paragraphs":["洗妆真态，不作铅华御。","竹外一枝斜，想佳人、天寒日暮。","黄昏小院，无处著清香，风细细，雪垂垂，何况江头路。","月边疏影，梦到消魂处。","结子欲黄时，又须著、廉纤细雨。","孤芳一世，供断有情愁，销瘦却，东阳也，试问花知否。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":["婉约","幽峭"],"mood":"孤寂","mood2":["愁怨"],"scene":["雨","花","山","雪"],"cats":{"抒情":["伤感","孤独"],"天气":["写雨"],"人物":["女子"]},"theme_conf":1.0},{"uid":"5593d522-b820-4c06-bab6-0ab5a0fc1d46","title":"宣州谢朓楼饯别校书叔云","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["弃我去者昨日之日不可留，乱我心者今日之日多烦忧。","长风万里送秋雁，对此可以酣高楼。","蓬莱文章建安骨，中间小谢又清发。","俱怀逸兴壮思飞，欲上青天览日月。","抽刀断水水更流，举杯销愁愁更愁。","人生在世不称意，明朝散发弄扁舟。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["楼","舟"],"cats":{"抒情":["离别","伤感","感恩"]},"theme_conf":0.531},{"uid":"f7cbf2e2-135e-4220-931b-aa406aff8545","title":"感古四首 二","author":"卢仝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["人生何所贵，所贵有终始。","昨日盈尺璧，今朝尽瑕弃。","苍蝇点垂棘，巧舌成锦绮。","箕子为之奴，比干谏而死。","仲尼鲁司寇，出走为群婢。","假如屈原醒，其奈一国醉。","一国醉号呶，一人行清高。","便欲激颓波，此事真徒劳。","上山逢猛虎，入海逢巨鼇。","王者苟不死，腰下鱼鳞刀。","东海波连天，三度成桑田。","高岸高于屋，斯须变溪谷。","天地犹尚然，人情难久全。","夜半白刃讐，旦来金石坚。","萧绶既解坼，陈印亦弃捐。","竭节遇刀割，输忠遭祸缠。","不予衾之眠，信予衾之穿。","镜明不自照，膏润徒自煎。","抱剑长太息，泪堕秋风前。"],"theme":"山水田园","theme2":["边塞征战"],"style":"绮丽","style2":["豪放"],"mood":"悲怆","mood2":[],"scene":["端午","秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"节日":["端午节"]},"theme_conf":0.487},{"uid":"6326d175-7980-4cbc-9237-62120d12a482","title":"献荥阳公诗五十韵","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["郑驿骑翩翩，丘门子弟贤。","文翁开学日，正礼骋途年。","骏骨黄金买，英髦绛帐延。","趋风皆蹀足，侍坐各差肩。","解榻招徐穉，登楼引仲宣。","凤攒题字扇，鱼落讲经筵。","盛气河包济，贞姿岳柱天。","臯夔当五百，邹鲁重三千。","科斗翻腾取，关雎教授先。","篆垂朝露滴，诗缀夜珠联。","逸礼多心匠，焚书旧口传。","陈遵修尺牍，阮瑀让飞牋。","中的颜初启，抽毫踵未旋。","森罗万木合，属对百花全。","词海跳波涌，文星拂坐悬。","戴冯遥避席，祖逖后施鞭。","西蜀凌云赋，东阳咏月篇。","劲芟鼇足断，精贯虱心穿。","浩汗神弥王，鹞飏兴欲仙。","冰壶通皓雪，绮树眇晴烟。","驱驾雷霆走，铺陈锦绣鲜。","情机登穾奥，流韵溢山川。","墨客膺潜服，谈宾膝误前。","张鳞定摧败，折角反矜怜。","句句推琼玉，声声播管弦。","纤新撩造化，澒洞斡陶甄。","卫磬琤鍧极，齐竽僭滥偏。","空虚慙炙輠，点窜许怀铅。","惫色秋来草，哀吟雨后蝉。","自伤魂惨沮，何暇思幽玄。","喜到樽罍侧，愁亲几案边。","菁华知竭矣，胏腑尚求旃。","抵滞浑成醉，徘徊转慕膻。","老叹才渐少，闲苦病相煎。","瓦砾难追琢，刍荛分弃捐。","漫劳成恳恳，那得美娟娟。","拙劣仍非速，迂愚且异专。","移时停笔砚，挥景乏戈鋋。","仪舌忻犹在，舒帷誓不褰。","会将连献楚，深耻谬游燕。","蒲有临书叶，韦充读易编。","沙须披见宝，经拟带耕田。","入雾长期闰，持朱本望研。","轮辕呈曲直，凿枘取方圆。","呼吸宁徒尔，沾濡岂浪然。","过箫资响亮，随水涨沦涟。","惜日看圭短，偷光恨壁坚。","勤勤雕朽木，细细导蒙泉。","传癖今应甚，头风昨已痊。","丹青公旧物，一为变蚩妍。"],"theme":"应制干谒","theme2":["山水田园","应制干谒","羁旅思乡"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["慷慨"],"scene":["酒","雪","冬","秋"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"人物":["老师"],"人生":["读书"]},"theme_conf":0.98},{"uid":"5cb3f893-1f2c-40fa-bd31-480c52f11940","title":"宿陆氏斋赋得残灯诗","author":"杨衡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["殷勤照永夜，属思未成眠。","余晖含薄雾，落烬迸空筵。","谁比秦楼晓，缄愁别幌前。"],"theme":"咏物","theme2":["送别"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["夜","元宵"],"cats":{"抒情":["伤感"],"节日":["元宵节"]},"theme_conf":0.594},{"uid":"77659827-473d-4602-9888-f305d9c70273","title":"杂曲歌辞 少年行二首 一","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["西陵侠年少，送客过长亭。","青槐夹两路，白马如流星。","闻道羽书急，单于寇井陉。","气高轻赴难，谁顾燕山铭。"],"theme":"边塞征战","theme2":["送别"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["山"],"cats":{"抒情":["离别"],"人生":["青春"]},"theme_conf":0.41},{"uid":"0174cbbc-31fa-4daf-b1cf-7f91c6a646a9","title":"赋得古原草送别","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["离离原上草，一岁一枯荣。","野火烧不尽，春风吹又生。","远芳侵古道，晴翠接荒城。","又送王孙去，萋萋满别情。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春"],"cats":{"抒情":["离别"],"四季":["春天"]},"theme_conf":0.662},{"uid":"cp7755e2bdab1251","title":"解佩环・疏影","author":"彭元逊","dynasty":"宋","section":"宋词","form":"词","paragraphs":["江空不渡，恨蘼芜杜若，零落无数。","远道荒寒，婉娩流年，望望美人迟暮。","风烟雨雪阴晴晚，更何须，春风千树。","尽孤城、落木萧萧，日夜江声流去。","日晏山深闻笛，恐他年流落，与子同赋。","事阔心违，交淡媒劳，蔓草沾衣多露。","汀洲窈窕馀醒寐，遗浮沈沣浦。","有白鸥淡月，微波寄语，逍遥容与。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["江","夜"],"cats":{"抒情":["孤独"],"人物":["女子"],"人生":["时光"],"植物":["梅花"]},"theme_conf":0.5},{"uid":"56f4eb52-4489-494d-a140-817d264544c8","title":"竹","author":"朱放","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["青林何森然，沈沈独曙前。","出墙同淅沥，开户满婵娟。","箨卷初呈粉，苔侵乱上钱。","疎中思水过，深处若山连。","叠夜常栖露，清朝乍有蝉。","砌阴迎缓策，簷翠对欹眠。","迸笋双分箭，繁梢一向偏。","月过惊散雪，风动极闻泉。","幽谷添诗谱，高人欲制篇。","萧萧意何恨，不独往湘川。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":["愁怨"],"scene":["中秋","雪","夜","月"],"cats":{"抒情":["孤独"],"天气":["月亮"],"节日":["中秋节"],"植物":["竹子"]},"theme_conf":0.757},{"uid":"cp67be02e6541d36","title":"忆王孙","author":"李重元","dynasty":"宋","section":"宋词","form":"词","paragraphs":["萋萋芳草忆王孙。","柳外楼高空断魂。","杜宇声声不忍闻。","欲黄昏。","雨打梨花深闭门。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["花","楼","雨","夜"],"cats":{"抒情":["思念"]},"theme_conf":0.65},{"uid":"b5afe65e-41f6-4c7a-8bc7-ff3f024937cb","title":"九日曲江","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["缀席茱萸好，浮舟菡萏衰。","季秋时欲半，九日意兼悲。","江水清源曲，荆门此路疑。","晚来高兴尽，摇荡菊花期。"],"theme":"节令风俗","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["重阳"],"cats":{"抒情":["伤感"],"山水":["江河"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.88},{"uid":"89799bab-6157-4af8-a292-46807a9ed427","title":"春日即事二首 一","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["诗书成志业，嬾慢致蹉跎。","圣代丹霄远，明时白发多。","浅谋堪自笑，穷巷忆谁过。","寂寞前山暮，归人樵采歌。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["欢愉","相思"],"scene":["春"],"cats":{"抒情":["思念","孤独"],"四季":["春天"],"人生":["读书"]},"theme_conf":1.0},{"uid":"cp37eda4b1261602","title":"虞美人","author":"晏几道","dynasty":"宋","section":"宋词","form":"词","paragraphs":["曲阑干外天如水。","昨夜还曾倚。","初将明月比佳期。","长向月圆时候、望人归。","罗衣著破前香在。","旧意谁教改。","一春离恨懒调弦。","犹有两行闲泪、宝筝前。"],"theme":"爱情相思","theme2":["送别","闲适隐逸"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["月"],"cats":{"抒情":["伤感"],"天气":["月亮"],"人物":["女子"]},"theme_conf":0.375},{"uid":"afa11a8c-8bce-408c-a688-2af0cc6632b5","title":"琴曲歌辞 胡笳十八拍 第八拍","author":"刘商","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["忆昔私家恣娇小，远取珍禽学驯扰。","如今沦弃念故乡，悔不当初放林表。","朔风萧萧寒日暮，星河寥落胡天晓。","旦夕思归不得归，愁心想似笼中鸟。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"沉郁","style2":["清新"],"mood":"相思","mood2":["愁怨"],"scene":["冬"],"cats":{"抒情":["思念","思乡","伤感"],"四季":["冬天"],"天气":["写风","星星"]},"theme_conf":0.446},{"uid":"5e4c26bb-a622-4b23-b501-d9c3d94d8547","title":"留别张广文","author":"王建","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["谢恩新入凤皇城，乱定相逢合眼明。","千万求方好将息，杏花寒食的同行。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["清明"],"cats":{"抒情":["离别"],"节日":["寒食节","清明节"]},"theme_conf":0.684},{"uid":"a3c6b2bf-35cf-40dc-bbcf-cfb5efa9f82e","title":"送褚大落第东归","author":"钱起","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["离琴弹苦调，美人惨向隅。","顷来荷策干明主，还复扁舟归五湖。","汉家侧席明扬久，岂意遗贤在林薮。","玉堂金马隔青云，墨客儒生皆白首。","昨梦芳洲采白苹，归期且喜故园春。","稚子只思陶令至，文君不厌马卿贫。","剡中风月久相忆，池上旧游应再得。","酒熟宁孤芳杜春，诗成不枉青山色。","念此那能不羡归，长杨谏猎事皆违。","他日东流一乘兴，知君为我扫荆扉。"],"theme":"送别","theme2":["羁旅思乡"],"style":"绮丽","style2":["豪放"],"mood":"相思","mood2":["欢愉","孤寂"],"scene":["舟","园林","江","春"],"cats":{"抒情":["思念","思乡","孤独"],"四季":["春天"],"人物":["女子","儿童"],"人生":["梦想"]},"theme_conf":0.361},{"uid":"81b32160-4eaa-4765-8824-ef33e4ae353e","title":"赠道者","author":"朱庆余","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["独住神仙境，门当瀑布开。","地多临水石，行不惹尘埃。","风起松花散，琴鸣鹤翅回。","还归九天上，时有故人来。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":[],"cats":{"抒情":["友情","孤独"],"山水":["瀑布"]},"theme_conf":0.88},{"uid":"b49cb64c-709b-4fc0-bf82-ee616cbdc070","title":"送谢夷甫宰余姚县","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["君去方为宰，干戈尚未销。","邑中残老小，乱后少官僚。","廨宇经兵火，公田没海潮。","到时应变俗，新政满余姚。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["江"],"cats":{"抒情":["感恩"],"人生":["战争"]},"theme_conf":0.7},{"uid":"63c586ff-dfa2-4c4e-88fe-4f017c9b52bb","title":"酬翰林白学士代书一百韵","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["昔岁俱充赋，同年遇有司。","八人称迥拔，两郡滥相知。","逸骥初翻步，鞲鹰暂脱羁。","远途忧地窄，高视觉天卑。","并入红兰署，偏亲白玉规。","近朱怜冉冉，伐木愿偲偲。","鱼鲁非难识，铅黄自嬾持。","心轻马融帐，谋夺子房帷。","秀发幽岩电，清澄隘岸陂。","九霄排直上，万里整前期。","勇赠栖鸾句，慙当古井诗。","多闻全受益，择善颇相师。","脱俗殊常调，潜工大有为。","还醇凭酎酒，运智托围棋。","情会招车胤，闲行觅戴逵。","僧餐月灯阁，醵宴劫灰池。","胜概争先到，篇章竞出奇。","输赢论破的，点窜肯容丝。","山岫当街翠，墙花拂面枝。","莺声爱娇小，燕翼玩逶迤。","辔为逢车缓，鞭缘趂伴施。","密携长上乐，偷宿静坊姬。","僻性慵朝起，新晴助晚嬉。","相欢常满目，别处鲜开眉。","翰墨题名尽，光阴听话移。","绿袍因醉典，乌帽逆风遗。","暗插轻筹箸，仍提小屈巵。","本弦才一举，下口已三迟。","逃席冲门出，归倡借马骑。","狂歌繁节乱，醉舞半衫垂。","散漫纷长薄，邀遮守隘岐。","几遭朝士笑，兼任巷童随。","苟务形骸达，浑将性命[推]。","何曾爱官序，不省计家资。","忽悟成虚掷，翻然叹未宜。","使回躭乐事，坚赴策贤时。","寝食都忘倦，园庐遂绝闚。","劳神甘戚戚，攻短过孜孜。","叶怯穿杨箭，囊藏透颕锥。","超遥望云雨，摆落占泉坻。","略削荒凉苑，搜求激直词。","那能作牛后，更拟助洪基。","唱第听鸡集，趋朝忘马疲。","内人舆御案，朝景丽神旗。","首被呼名姓，多慙冠等衰。","千官容眷盼，五色照离披。","鹓侣从兹洽，鸥情转自縻。","分张殊品命，中外却驱驰。","出入称金籍，东西侍碧墀。","鬬班云汹涌，开扇雉参差。","切愧寻常质，亲瞻咫尺姿。","日轮光照耀，龙服瑞葳蕤。","誓欲通愚謇，生憎效喔咿。","佞存真妾妇，谏死是男儿。","便殿承偏召，权臣惧挠私。","庙堂虽稷契，城社有狐貍。","似锦言应巧，如弦数易欺。","敢嗟身暂黜，所恨政无毗。","谬辱良由此，升腾亦在斯。","再令陪宪禁，依旧履阽危。","使蜀常緜远，分台更崄巇。","匿奸劳发掘，破党恶持疑。","斧刃迎皆碎，盘牙老未萎。","乍能还帝笏，讵忍折吾支。","虎尾元来险，圭文却类疵。","浮荣齐壤芥，闲气咏江蓠。","阙下殷勤拜，樽前啸傲辞。","飘沈委蓬梗，忠信敌蛮夷。","戏诮青云驿，讥题皓发祠。","贪过谷隐寺，留读岘山碑。","草没章台阯，隄横楚泽湄。","野莲侵稻陇，亚柳压城陴。","遇物伤凋换，登楼思漫弥。","金攒嫩橙子，瑿泛远鸬鹚。","仰竹藤缠屋，苫茆荻补篱。","面梨通蔕朽，火米带芒炊。","苇笋针筒束，𫚣鱼箭羽鬐。","芋羹真底可，鲈鲙漫劳思。","北渚销魂望，南风著骨吹。","度梅衣色渍，食稗马蹄羸。","院榷和泥碱，官酤小曲醨。","讹音烦缴绕，轻俗丑威仪。","树罕贞心柏，畦丰卫足葵。","坳洼饶尰矮，游惰压庸缁。","病赛乌称鬼，巫占瓦代龟。","连阴蛙张王，瘴疟雪治医。","我正穷于是，君宁念及兹。","一篇从日下，双鲤送天涯。","坐捧迷前席，行吟忘结綦。","匡床铺错绣，几案踊灵芝。","形影同初合，参商喻此离。","扇因秋弃置，镜异月盈亏。","壮志诚难夺，良辰岂复追。","宁牛终夜永，潘鬓去年衰。","溟渤深那测，穹苍意在谁。","驭方轻騕褭，车肯重辛夷。","卧辙希濡沫，低颜受颔颐。","世情焉足怪，自省固堪悲。","溷鼠虚求洁，笼禽方讶饥。","犹胜忆黄犬，幸得早图之。"],"theme":"寄赠酬答","theme2":["山水田园","闲适隐逸"],"style":"绮丽","style2":["清新","豪放"],"mood":"欢愉","mood2":["愁怨","慷慨"],"scene":["酒","山","楼","园林","夜"],"cats":{"抒情":["离别","伤感"],"人生":["励志","时光","梦想"]},"theme_conf":0.95},{"uid":"7bafe460-9265-428c-ab3e-1d2844809efa","title":"吴姬十首 三","author":"薛能","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["滴滴春霖透荔枝，笔题牋动手中垂。","天阴不得君王召，嚬著青蛾作小诗。"],"theme":"闺情宫怨","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["江南","春","雨"],"cats":{"抒情":["闺怨"],"四季":["春天"],"食物":["荔枝"]},"theme_conf":0.97},{"uid":"a6e5e21e-44a8-4e30-b824-ef6344e9d531","title":"相和歌辞 猛虎行","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["朝作猛虎行，暮作猛虎吟。","肠断非关陇头水，泪下不为雍门琴。","旌旗缤纷两河道，战鼓惊山欲倾倒。","秦人半作燕地囚，胡马飜衔洛阳草。","一输一失关下兵，朝降夕叛幽蓟城。","巨鼇未斩海水动，鱼龙奔走安得宁。","颇似楚汉时，飜覆无定止。","朝过博浪沙，暮入淮阴市。","张良未遇韩信贫，刘项存亡在两臣。","暂到下邳受兵略，来投漂母作主人。","贤哲栖栖古如此，今时亦弃青云士。","有策不敢犯龙鳞，窜身南国避胡尘。","宝书长劒挂高阁，金鞍骏马散故人。","昨日方为宣城客，掣铃交通二千石。","有时六博快壮心，绕床三帀呼一掷。","楚人每道张旭奇，心藏风云世莫知。","三吴邦伯多顾盼，四海雄侠皆相推。","萧曹曾作沛中吏，攀龙附凤当有时。","溧阳酒楼三月春，杨花漠漠愁杀人。","胡人绿眼吹玉笛，吴歌白纻飞梁尘。","丈夫相见且为乐，槌牛挝鼓会众宾。","我从此去钓东海，得鱼笑寄情相亲。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["沉郁"],"mood":"愁怨","mood2":["欢愉","慷慨"],"scene":["楼","塞外"],"cats":{"抒情":["伤感"],"人生":["战争"]},"theme_conf":0.41},{"uid":"8b73dd1d-d744-4620-965f-163b4b45127d","title":"南中春意","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["入仕无知言，游方随世道。","平生愿开济，遇物干怀抱。","已阻青云期，甘同散樗老。","客游南海曲，坐见韶阳蚤。","旧国别佳人，他乡思芳草。","惜无鸿鹄翅，安得凌苍昊。"],"theme":"羁旅思乡","theme2":["送别"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"人物":["女子"],"人生":["梦想"]},"theme_conf":0.618},{"uid":"7af5f435-0357-4ff6-ab62-97417d87a31a","title":"相和歌辞 日出行","author":"李贺","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["白日下崐崘，发光如舒丝。","徒照葵藿心，不照游子悲。","折折黄河曲，日从中央转。","旸谷耳曾闻，若木眼不见。","奈何铄石，胡为销人。","羿弯弓属矢那不中，足令久不得奔，讵教晨光夕昏。"],"theme":"边塞征战","theme2":["亲情"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["惆怅"],"scene":["江","夏"],"cats":{"抒情":["伤感"],"山水":["黄河"],"天气":["太阳"]},"theme_conf":0.6},{"uid":"cp8d50fc0d263aa9","title":"蝶恋花","author":"晏几道","dynasty":"宋","section":"宋词","form":"词","paragraphs":["醉别西楼醒不记。","春梦秋云，聚散真容易。","斜月半窗还少睡。","画屏闲展吴山翠。","衣上酒痕诗里字。","点点行行，总是凄凉意。","红烛自怜无好计。","夜寒空替人垂泪。"],"theme":"爱情相思","theme2":["送别"],"style":"婉约","style2":["绮丽","豪放"],"mood":"愁怨","mood2":["孤寂"],"scene":["酒","花","春","秋"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"]},"theme_conf":0.84},{"uid":"64ce1225-6e8b-46b5-b1df-50a4cba1f0f3","title":"晚发江宁道中呈严维","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["惆怅遥江路，萧条落日过。","蝉鸣独树急，鸦向古城多。","转曲随青嶂，因高见白波。","潘生秋径草，严子意如何。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":["孤寂"],"scene":["江","秋"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"山水":["江河"]},"theme_conf":0.86},{"uid":"d1c29cbc-5e59-4332-8a20-033c7524e3d0","title":"杂曲歌辞 少年行三首 三","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见淮南少年游侠客，白日毬猎夜拥掷。","呼卢百万终不惜，报讐千里如咫尺。","少年游侠好经过，浑身装束皆绮罗。","兰蕙相随喧妓女，风光去处满笙歌。","骄矜自言不可有，侠士堂中养来久。","好鞍好马乞与人，十千五千旋沽酒。","赤心用尽为知己，黄金不惜栽桃李。","桃李栽来几度春，一回花落一回新。","府县尽为门下客，王侯皆是平交人。","男儿百年且乐命，何须徇书受贫病。","男儿百年且荣身，何须徇节甘风尘。","衣冠半是征战士，穷儒浪作林泉民。","遮莫枝根长百丈，不如当代多还往。","遮莫姻亲连帝城，不如当身自簪缨。","看取富贵眼前者，何用悠悠身后名。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"绮丽","style2":["旷达"],"mood":"慷慨","mood2":[],"scene":["春","酒"],"cats":{"抒情":["友情","思乡"],"四季":["春天"],"人生":["青春","战争"]},"theme_conf":0.441},{"uid":"0bed9b02-991e-4e28-b631-86640147a712","title":"宿建德江","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["移舟泊烟渚，日暮客愁新。","野旷天低树，江清月近人。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["清新"],"mood":"愁怨","mood2":[],"scene":["江","月"],"cats":{"抒情":["思乡","伤感"],"山水":["江河"]},"theme_conf":0.647},{"uid":"b700208d-d859-4e36-96bf-883c81d4df0f","title":"谷口书斋寄杨补阙","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["泉壑带茅茨，云霞生薜帷。","竹怜新雨后，山爱夕阳时。","闲鹭栖常早，秋花落更迟。","家童扫萝迳，昨与故人期。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["山","秋"],"cats":{"抒情":["友情"],"四季":["秋天"],"天气":["写云"]},"theme_conf":0.9},{"uid":"61304178-6b16-4f98-87b2-4ad6bc98da98","title":"观公孙大娘弟子舞劒器行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["昔有佳人公孙氏，一舞劒气动四方。","观者如山色沮丧，天地为之久低昂。","㸌如羿射九日落，矫如群帝骖龙翔。","来如雷霆收震怒，罢如江海凝清光。","绛唇珠袖两寂莫，况有弟子传芬芳。","临颍美人在白帝，妙舞此曲神扬扬。","与余问答既有以，感时抚事增惋伤。","先帝侍女八千人，公孙劒器初第一。","五十年间似反掌，风尘倾动昏王室。","棃园子弟散如烟，女乐余姿映寒日。","金粟堆南木已拱，瞿唐石城草萧瑟。","玳筵急管曲复终，乐极哀来月东出。","老夫不知其所往，足茧荒山转愁疾。"],"theme":"题画咏艺","theme2":[],"style":"沉郁","style2":["绮丽","豪放"],"mood":"孤寂","mood2":["愁怨","欢愉"],"scene":[],"cats":{"抒情":["伤感"],"人物":["女子","老师"]},"theme_conf":0.95},{"uid":"3ab356ea-69fc-43ff-b74c-4ece4a0b8277","title":"杂曲歌辞 长安少年行十首 一","author":"李廓","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["金紫少年郎，绕街鞍马光。","身从左中尉，官属右春坊。","刬戴扬州帽，重熏异国香。","垂鞭踏青草，来去杏园芳。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"恬淡","mood2":[],"scene":["清明","花","春","园林"],"cats":{"抒情":["思乡"],"四季":["春天"],"人生":["青春"],"节日":["清明节"]},"theme_conf":0.65},{"uid":"3f3870ea-0cc1-4829-971c-b9f5fc7283a9","title":"相和歌辞 挽歌","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["丹旐何飞扬，素骖亦悲鸣。","晨光照闾巷，輀车俨欲行。","萧条九月天，哀挽出重城。","借问送者谁，妻子与弟兄。","苍苍上古原，峨峨开新茔。","含酸一恸哭，异口同哀声。","旧垄转芜绝，新坟日罗列。","春风草绿北邙山，此地年年生死别。"],"theme":"悼亡挽歌","theme2":[],"style":"悲慨","style2":["清新"],"mood":"悲怆","mood2":[],"scene":["春","月"],"cats":{"抒情":["伤感","悼亡"],"四季":["春天"]},"theme_conf":0.99},{"uid":"6d098c75-038d-45f4-8f86-73976c355e44","title":"终南别业","author":"王维","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["中岁颇好道，晚家南山陲。","兴来每独往，胜事空自知。","行到水穷处，坐看云起时。","偶然值林叟，谈笑无还期。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["山"],"cats":{"抒情":["离别","孤独"]},"theme_conf":0.553},{"uid":"bb4a1d16-2a2e-4a68-9732-77e2bfafde5e","title":"奉酬北海李太守丈人夏日平阴亭","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["天子股肱守，丈人山岳灵。","出身侍丹墀，举翮凌青冥。","当昔皇运否，人神俱未宁。","谏官莫敢议，酷吏方专刑。","谷永独言事，匡衡多引经。","两朝纳深衷，万乘无不听。","盛烈播南史，雄词豁东溟。","谁谓整隼旟，翻然忆柴扃。","寄书汶阳客，廻首平阴亭。","开封见千里，结念存百龄。","隐轸江山丽，氛氲兰茝馨。","自怜遇时休，漂泊随流萍。","春野变木德，夏天临火星。","一生徒羡鱼，四十犹聚萤。","从此日闲放，焉能怀拾青。"],"theme":"寄赠酬答","theme2":[],"style":"旷达","style2":["豪放"],"mood":"相思","mood2":["孤寂"],"scene":["夏"],"cats":{"抒情":["思念","孤独"],"四季":["夏天"],"天气":["太阳"]},"theme_conf":0.76},{"uid":"03eb4001-023a-4920-bbc7-a0fc52b2836d","title":"咏怀古迹五首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["支离东北风尘际，漂泊西南天地间。","三峡楼台淹日月，五溪衣服共云山。","羯胡事主终无赖，词客衰时且未还。","庾信平生最萧瑟，暮年诗赋动江关。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":["旷达"],"mood":"惆怅","mood2":[],"scene":["楼","月"],"cats":{"抒情":["怀古"]},"theme_conf":0.504},{"uid":"38653c12-f754-4dc5-8845-4062ed54fdde","title":"郡中","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["乡路音信断，山城日月迟。","欲知州近远，阶前摘荔枝。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["月","山"],"cats":{"抒情":["思乡"],"食物":["荔枝"]},"theme_conf":1.0},{"uid":"869a90a2-6d0b-4c59-90c4-f6c2ec8ab6b6","title":"暮春游长沙东湖赠辛兖州巢父二首 二","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["回环路不尽，历览意弥新。","古木畬田火，澄江荡桨人。","缓歌寻极浦，一醉送残春。","莫恨长沙远，他年忆此辰。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["春","江"],"cats":{"抒情":["思念"],"四季":["春天"],"人物":["父亲"]},"theme_conf":0.78},{"uid":"d1f63af2-2b60-4ca1-bbb5-9c0d65cf44df","title":"晚楼寓怀","author":"刘兼","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["薄暮疎林宿鸟还，倚楼垂袂复凭栏。","月沈江底珠轮净，云锁峰头玉叶寒。","刘毅暂贫虽壮志，冯唐将老自低颜。","无言独对秋风立，拟把朝簪换钓竿。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["沉郁"],"mood":"孤寂","mood2":["慷慨"],"scene":["楼"],"cats":{"抒情":["孤独"],"人生":["励志","梦想"]},"theme_conf":1.0},{"uid":"12029f03-2eaa-44eb-9944-e95e1f178cd8","title":"忆平泉杂咏 忆寒梅","author":"李德裕","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["寒塘数树梅，常近腊前开。","雪映缘岩竹，香侵泛水苔。","遥思清景暮，还有野禽来。","谁是攀枝客，兹辰醉始回。"],"theme":"山水田园","theme2":["咏物"],"style":"幽峭","style2":[],"mood":"相思","mood2":[],"scene":["冬"],"cats":{"抒情":["思念"],"植物":["梅花"]},"theme_conf":0.47},{"uid":"de37c5eb-9420-4c1d-a0a8-e9d9a5a118ca","title":"杂曲歌辞 少年行","author":"韦庄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["五陵豪客多，买酒黄金贱。","醉下酒家楼，美人双翠幰。","挥劒邯郸市，走马梁王苑。","乐事殊未央，年华已云晚。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":["豪放"],"mood":"欢愉","mood2":[],"scene":["酒"],"cats":{"抒情":["思乡"],"人物":["女子"],"人生":["青春"]},"theme_conf":0.654},{"uid":"5de65084-28e0-44c9-b2fc-3bb7a1e2db6d","title":"述怀","author":"魏征","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["中原初逐鹿，投笔事戎轩。","纵横计不就，慷慨志犹存。","杖策谒天子，驱马出关门。","请缨系南粤，凭轼下东藩。","郁纡陟高岫，出没望平原。","古木鸣寒鸟，空山啼夜猿。","既伤千里目，还惊九折魂。","岂不惮艰险，深怀国士恩。","季布无二诺，侯嬴重一言。","人生感意气，功名谁复论。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":["豪放"],"mood":"慷慨","mood2":[],"scene":["山"],"cats":{"抒情":["爱国"]},"theme_conf":1.0},{"uid":"b693eaa3-5152-47da-bb89-56ac4b2d11cd","title":"杂曲歌辞 古别离二首 二","author":"施肩吾","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["老母别爱子，少妻送征郎。","血流既四面，乃亦断二肠。","不愁寒无衣，不怕饥无粮。","惟恐征战不还乡，母化为鬼妻为孀。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["离别","伤感"],"人物":["母亲"],"人生":["战争"]},"theme_conf":0.618},{"uid":"e4a87504-f9a3-4599-b770-aba4afd3cb04","title":"杂曲歌辞 渭城曲","author":"王维","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["谓城朝雨浥轻尘，客舍青青柳色春。","劝君更尽一杯酒，西出阳关无故人。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["酒","春"],"cats":{"抒情":["友情"],"四季":["春天"]},"theme_conf":0.589},{"uid":"c6b86ec1-0218-4426-96a9-ee66e88cd449","title":"别崔少府","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["知君少得意，汶上掩柴扉。","寒食仍留火，春风未授衣。","皆言黄绶屈，早向青云飞。","借问他乡事，今年归不归。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["清明","春"],"cats":{"抒情":["离别"],"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.538},{"uid":"05d03b46-d786-4acf-995e-a20721f16583","title":"秋莺","author":"后主煜","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["残莺何事不知秋，横过幽林尚独游。","老舌百般倾耳听，深黄一点入烟流。","栖迟背世同悲鲁，浏亮如笙碎在缑。","莫更留连好归去，露华凄冷蓼花愁。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["悲怆"],"scene":["秋","春","鸟"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"],"动物":["写鸟"]},"theme_conf":1.0},{"uid":"c5082a98-967f-45dd-aa62-6a0217f71d65","title":"见上林春鴈翔青云寄杨起居李员外","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["上林春更好，宾鴈不知归。","顾影怜青籞，传声入紫微。","夜陪池鹭宿，朝出苑花飞。","宁忆寒乡侣，鸾凰一见稀。"],"theme":"咏物","theme2":["山水田园","羁旅思乡"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思念","思乡"],"四季":["春天"],"人生":["梦想"]},"theme_conf":0.78},{"uid":"35319d7e-9cf6-43b0-bfa3-991cf82a49f9","title":"相和歌辞 子夜四时歌四首 冬歌","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["明朝驿使发，一夜絮征袍。","素手抽针冷，那堪把剪刀。","裁缝寄远道，几日到临洮。"],"theme":"闺情宫怨","theme2":["羁旅思乡","送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["冬","夜"],"cats":{"抒情":["思乡","闺怨"],"四季":["冬天"]},"theme_conf":0.347},{"uid":"63950163-6a10-4e74-af8a-09886e4ef2a8","title":"登鹳雀楼","author":"王之涣","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["白日依山尽，黄河入海流。","欲穷千里目，更上一层楼。"],"theme":"山水田园","theme2":["哲理悟道","咏史怀古"],"style":"冲淡","style2":[],"mood":"慷慨","mood2":[],"scene":["楼"],"cats":{"抒情":["怀古"],"山水":["黄河"]},"theme_conf":0.375},{"uid":"eb1817f2-140c-47c4-b6f3-0f374d7eaded","title":"谒禹庙","author":"徐浩","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["亩浍敷四海，川源涤九州。","既膺九命锡，乃建洪范畴。","鼎革固天启，运兴匪人谋。","肇开宅土业，永庇昏垫忧。","山足灵庙在，门前清镜流。","象筵陈玉帛，容卫俨戈矛。","探穴图书朽，卑宫堂殿修。","梅梁今不坏，松祏古仍留。","负责故乡近，朅来申俎羞。","为鱼知造化，叹凤仰徽猷。","不复闻夏乐，唯余奏楚幽。","婆娑非舞羽，镗鞳异鸣球。","盛德吾无间，高功谁与俦。","灾淫破凶慝，祚圣拥神休。","出谷莺初语，空山猨独愁。","春晖生草树，柳色暖汀洲。","恩贷题舆重，荣殊衣锦游。","宦情同械击，生理任桴浮。","地极临沧海，天遥过斗牛。","精诚如可谅，他日寄冥搜。"],"theme":"山水田园","theme2":["边塞征战","咏史怀古"],"style":"豪放","style2":["清新","绮丽"],"mood":"愁怨","mood2":["孤寂","欢愉"],"scene":["江","春"],"cats":{"抒情":["思乡","伤感","孤独","怀古","感恩"],"四季":["春天"]},"theme_conf":0.4},{"uid":"a8133806-1aeb-44d9-8b5e-6309fe6bd8cb","title":"同吕员外酬田著作幕门军西宿盘山秋夜作","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["碛路天早秋，边城夜应永。","遥传戎旅作，已报关山冷。","上将顿盘阪，诸军徧泉井。","绸缪阃外书，慷慨幕中请。","能使勋业高，动令氛雾屏。","远途能自致，短步终难骋。","羽翮时一看，穷愁始三省。","人生感然诺，何啻若形影。","白发知苦心，阳春见佳境。","星河连塞络，刁斗兼山静。","忆君霜露时，使我空引领。"],"theme":"边塞征战","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["秋","夜","山","塞外"],"cats":{"抒情":["思念","伤感"],"四季":["秋天"],"天气":["星星"],"生活":["边塞"]},"theme_conf":0.428},{"uid":"4d17d86c-b052-4a60-be76-3015ea8d1e8b","title":"怀素上人草书歌","author":"王𩔪","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["衡阳双峡插天峻，青壁巉巉万余仞。","此中灵秀众所知，草书独有怀素奇。","怀素身长五尺四，嚼汤诵呪吁可畏。","铜瓶锡杖倚闲庭，斑管秋毫多逸意。","或粉壁，或彩牋，蒲葵绢素何相鲜。","忽作风驰如电掣，更点飞花兼散雪。","寒猨饮水撼枯藤，壮士拔山伸劲铁。","君不见张芝昔日称独贤，君不见近日张旭为老颠。","二公绝艺人所惜，怀素传之得真迹。","峥嵘蹙出海上山，突兀状成湖畔石。","一纵又一横，一欹又一倾。","临江不羡飞帆势，下笔长为骤雨声。","我牧此州喜相识，又见草书多慧力。","怀素怀素不可得，开卷临池转相忆。"],"theme":"题画咏艺","theme2":["爱情相思"],"style":"冲淡","style2":["幽峭"],"mood":"相思","mood2":["孤寂","慷慨"],"scene":["雪"],"cats":{"抒情":["思念","孤独"],"天气":["写雨"]},"theme_conf":0.98},{"uid":"1274d774-d716-4705-8497-c3cdd510a7c0","title":"过梅里七首  家于无锡四十载今敝庐数堵犹存今列题于后 早梅桥","author":"李绅","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["早梅花，满枝发。","东风报春春未彻，紫萼迎风玉珠裂。","杨柳未黄莺结舌，委素飘香照新月。","桥边一树伤离别，游荡行人莫攀折。","不竞江南艳阳节，任落东风伴春雪。"],"theme":"送别","theme2":["咏史怀古"],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["春","冬","花","雪"],"cats":{"抒情":["离别","怀古"],"四季":["春天"],"生活":["写桥"],"植物":["梅花"]},"theme_conf":0.576},{"uid":"cp34c072b90f0fae","title":"苏幕遮","author":"范仲淹","dynasty":"宋","section":"宋词","form":"词","paragraphs":["碧云天，黄叶地。","秋色连波，波上寒烟翠。","山映斜阳天接水。","芳草无情，更在斜阳外。","黯乡魂，追旅思。","夜夜除非，好梦留人睡。","明月楼高休独倚。","酒入愁肠，化作相思泪。"],"theme":"羁旅思乡","theme2":["爱情相思"],"style":"沉郁","style2":["婉约"],"mood":"相思","mood2":["愁怨"],"scene":["月","夜"],"cats":{"抒情":["爱情","思念","思乡","伤感"],"天气":["月亮"]},"theme_conf":0.639},{"uid":"96314951-671b-423f-a172-4f10ec08a6f2","title":"初秋夜坐赠吴武陵","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["稍稍雨侵竹，翻翻鹊惊丛。","美人隔湘浦，一夕生秋风。","积雾杳难极，沧波浩无穷。","相思岂云远，即席莫与同。","若人抱奇音，朱弦緪枯桐。","清商激西颢，泛滟凌长空。","自得本无作，天成谅非功。","希声閟大朴，聋俗何由聪。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":["冲淡"],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["思念"],"四季":["秋天"],"人物":["女子"],"植物":["桃花"]},"theme_conf":0.95},{"uid":"6a5f693e-7c8d-4c20-a1c3-bfec8a474e6f","title":"重别西湖","author":"李绅","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["浦边梅叶看凋落，波上双禽去寂寥。","吹管曲传花易失，织文机学羽难飘。","雪欺春早摧芳蕚，隼励秋深拂翠翘。","繁艳彩毛无处所，尽成愁叹别谿桥。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["江南","江"],"cats":{"抒情":["离别","伤感"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"f540f519-e3c4-41c2-b299-f1d255977705","title":"宿府","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["清秋幕府井梧寒，独宿江城蜡炬残。","永夜角声悲自语，中天月色好谁看。","风尘荏苒音书绝，关塞萧条行路难。","已忍伶俜十年事，强移栖息一枝安。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"孤寂","mood2":[],"scene":["月","塞外"],"cats":{"抒情":["孤独"],"天气":["月亮"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"2d66a9e4-7b4d-4be4-91fd-6a4b2cd8817b","title":"听安万善吹觱篥歌","author":"李颀","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["南山截竹为觱篥，此乐本自龟兹出。","流传汉地曲转奇，凉州胡人为我吹。","傍邻闻者多叹息，远客思乡皆泪垂。","世人解听不解赏，长飙风中自来往。","枯桑老柏寒飕飗，九雏鸣凤乱啾啾。","龙吟虎啸一时发，万籁百泉相与秋。","忽然更作渔阳掺，黄云萧条白日暗。","变调如闻杨柳春，上林繁花照眼新。","岁夜高堂列明烛，美酒一杯声一曲。"],"theme":"题画咏艺","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"欢愉","mood2":["恬淡"],"scene":["酒","夜","秋","春"],"cats":{"抒情":["思乡"],"四季":["春天","秋天"]},"theme_conf":0.547},{"uid":"e387aad0-cefb-4e70-b299-855d181a36ab","title":"零陵赠李卿元侍御简吴武陵","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["理世固轻士，弃捐湘之湄。","阳光竞四溟，敲石安所施。","铩羽集枯干，低昂互鸣悲。","朔云吐风寒，寂历穷秋时。","君子尚容与，小人守兢危。","惨凄日相视，离忧坐自滋。","尊酒聊可酌，放歌谅徒为。","惜无协律者，窈眇弦吾诗。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["幽峭","悲慨"],"mood":"愁怨","mood2":["孤寂","悲怆"],"scene":["酒","江南"],"cats":{"抒情":["伤感"],"植物":["桃花"]},"theme_conf":0.93},{"uid":"d06f921a-9125-4a21-aad1-f98a429e4727","title":"扬旗","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["江雨飒长夏，府中有余清。","我公会宾客，肃肃有异声。","初筵阅军装，罗列照广庭。","庭空六马入，𫘟騀扬旗旌。","回回偃飞盖，熠熠迸流星。","来缠风飙急，去擘山岳倾。","材归俯身尽，妙取略地平。","虹霓就掌握，舒卷随人轻。","三州陷犬戎，但见西岭青。","公来练猛士，欲夺天边城。","此堂不易升，庸蜀日已宁。","吾徒且加餐，休适蛮与荆。"],"theme":"羁旅思乡","theme2":[],"style":"旷达","style2":[],"mood":"相思","mood2":[],"scene":["山","夏","园林"],"cats":{"抒情":["思乡"],"四季":["夏天"],"天气":["彩虹"]},"theme_conf":1.0},{"uid":"d5653ac5-0da7-42d7-b638-9b818b3567ed","title":"和崔二少府登楚丘城作","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["故人亦不遇，异县久栖托。","辛勤失路意，感叹登楼作。","清晨眺原野，独立穷寥廓。","云散芒砀山，水还睢阳郭。","绕梁即襟带，封卫多漂泊。","事古悲城池，年丰爱墟落。","相逢俱未展，携手空萧索。","何意千里心，仍求百金诺。","公侯皆我辈，动用在谋略。","圣心思贤才，朅来刈葵藿。"],"theme":"应制干谒","theme2":["咏史怀古","送别","羁旅思乡"],"style":"悲慨","style2":["雄浑"],"mood":"孤寂","mood2":["悲怆"],"scene":["楼"],"cats":{"抒情":["友情","思乡","伤感","孤独","怀古"]},"theme_conf":0.76},{"uid":"90f7a912-549f-444d-9b12-99c89f224b94","title":"自常州还江阴途中作","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["处处空篱落，江村不忍看。","无人花色惨，多雨鸟声寒。","黄霸初临郡，陶潜未罢官。","乘春务征伐，谁肯问凋残。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["孤独"],"山水":["江河"],"生活":["乡村"]},"theme_conf":1.0},{"uid":"01524421-e3e5-49f3-a237-ae1c44d720b9","title":"送卢十四弟侍御护韦尚书灵榇归上都二十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["素幕渡江远，朱幡登陆微。","悲鸣驷马顾，失涕万人挥。","参佐哭辞毕，门阑谁送归。","从公伏事久，之子俊才稀。","长路更执绋，此心犹倒衣。","感恩义不小，怀旧礼无违。","墓待龙骧诏，台迎獬豸威。","深衷见士则，雅论在兵机。","戎狄乘妖气，尘沙落禁闱。","往年朝谒断，他日埽除非。","但促铜壶箭，休添玉帐旗。","动询黄阁老，肯虑白登围。","万姓疮痍合，群凶嗜欲肥。","刺规多谏诤，端拱自光辉。","俭约前王体，风流后代希。","对敭期特达，衰朽再芳菲。","空里愁书字，山中疾采薇。","拨杯要忽罢，抱被宿何依。","眼冷看征盖，儿扶立钓矶。","清霜洞庭叶，故就别时飞。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["冲淡"],"mood":"悲怆","mood2":[],"scene":["江","酒","楼"],"cats":{"抒情":["伤感","感恩"]},"theme_conf":0.664},{"uid":"d12edd29-d467-4b19-b3f5-533fa5c8d56a","title":"秋夕","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["红烛秋光冷画屏，轻罗小扇扑流萤。","天阶夜色凉如水，坐看牵牛织女星。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["秋"],"cats":{"抒情":["闺怨"],"四季":["秋天"],"天气":["星星"],"节日":["七夕节"]},"theme_conf":0.92},{"uid":"27246964-80bd-4b60-ae59-0921b0832948","title":"赠别沈四逸人","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["沈侯未可测，其况信浮沈。","十载常独坐，几人知此心。","乘舟蹈沧海，买劒投黄金。","世务不足烦，有田西山岑。","我来遇知己，遂得开清襟。","何意阃阈间，沛然江海深。","疾风扫秋树，濮上多鸣砧。","耿耿尊酒前，联雁飞愁音。","平生重离别，感激对孤琴。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":["江","秋","舟","酒"],"cats":{"抒情":["友情","离别","孤独"],"四季":["秋天"]},"theme_conf":0.711},{"uid":"ac9a971b-9802-4303-a76d-fafaa49563df","title":"寄令狐尚书","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["立身荣贵复何如，龙节红旗从板舆。","妙略多推霍骠骑，能文独见沈尚书。","临风高会千门帐，映水连营百乘车。","他日感恩慙未报，举家犹似涸池鱼。"],"theme":"应制干谒","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":[],"cats":{"抒情":["孤独","感恩"]},"theme_conf":0.84},{"uid":"d669feeb-edbb-433a-b46f-9c302e3e7516","title":"哭裴少府","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["世人谁不死，嗟君非生虑。","扶病适到官，田园在何处？","公才群吏感，葬事他人助。","余亦未识君，深悲哭君去。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["园林"],"cats":{"抒情":["伤感","悼亡"],"生活":["田野"]},"theme_conf":0.99},{"uid":"57c0cd57-397e-4054-86d7-24b6a6842efa","title":"汨罗","author":"李德裕","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["远谪南荒一病身，停舟暂吊汨罗人。","都缘靳尚图专国，岂是怀王厌直臣。","万里碧潭秋景静，四时愁色野花新。","不劳渔父重相问，自有招魂拭泪巾。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":["绮丽"],"mood":"愁怨","mood2":[],"scene":["端午"],"cats":{"抒情":["伤感","怀古"],"节日":["端午节"]},"theme_conf":0.98},{"uid":"fc1ccfae-5091-4e0a-9b84-2e2cdecd6f78","title":"虹藏不见","author":"徐敞","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["迎冬小雪至，应节晚虹藏。","玉气徒成象，星精不散光。","美人初比色，飞鸟罢呈祥。","石涧收晴影，天津失彩梁。","霏霏空暮雨，杳杳暎残阳。","舒卷应时令，因知圣历长。"],"theme":"节令风俗","theme2":["山水田园"],"style":"沉郁","style2":["清新"],"mood":"相思","mood2":[],"scene":["雨","冬","雪"],"cats":{"抒情":["思念"],"四季":["冬天"],"天气":["彩虹"],"人物":["女子"]},"theme_conf":0.96},{"uid":"7201ac2c-75bd-495d-a203-339fb042959a","title":"相和歌辞 子夜四时歌六首 冬歌二首 二","author":"郭元振","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["帷横双翡翠，被卷两鸳鸯。","婉态不自得，宛转君王床。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["冬","夜"],"cats":{"抒情":["爱情"],"四季":["冬天"]},"theme_conf":1.0},{"uid":"56ca5b29-4bb9-4f12-9200-6bc7c72e4e47","title":"秋登兰山寄张五","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["北山白云里，隐者自怡悦。","相望试登高，心飞逐鸟灭。","愁因薄暮起，兴是清秋发。","时见归村人，沙行渡头歇。","天边树若荠，江畔舟如月。","何当载酒来，共醉重阳节。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"沉郁","style2":["豪放"],"mood":"相思","mood2":["愁怨"],"scene":["秋","重阳","山"],"cats":{"抒情":["伤感"],"四季":["秋天"],"节日":["重阳节"]},"theme_conf":0.88},{"uid":"809ad73b-9a8e-436e-9874-f9295b624af0","title":"金陵酒肆留别","author":"李白","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["风吹柳花满店香，吴姬压酒唤客尝。","金陵子弟来相送，欲行不行各尽觞。","请君试问东流水，别意与之谁短长。"],"theme":"送别","theme2":["咏史怀古"],"style":"绮丽","style2":["豪放"],"mood":"惆怅","mood2":[],"scene":["酒"],"cats":{"抒情":["离别","怀古"],"食物":["写酒"]},"theme_conf":0.457},{"uid":"a02551b7-28e1-4a79-8e2c-a185c70cffcb","title":"杂曲歌辞 桃花行 一","author":"李峤","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["岁去无言忽顦顇，时来含笑吐氛氲。","不能拥路迷仙客，故欲开蹊侍圣君。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["花"],"cats":{"抒情":["思乡"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"232b2330-be81-492f-ab96-52be310cd64d","title":"杂曲歌辞 少年乐","author":"李贺","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["芳草落花如锦地，二十长游醉乡里。","红缨不重白马骄，垂柳金丝香拂水。","吴娥未笑花不开，绿鬓耸堕兰云起。","陆郎倚醉牵罗袂，夺得宝钗金翡翠。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["花"],"cats":{"抒情":["思乡"],"人生":["青春"]},"theme_conf":1.0},{"uid":"00a2e26b-5799-453b-bdc1-16b870e092be","title":"清明二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["此身飘泊苦西东，右臂偏枯半耳聋。","寂寂系舟双下泪，悠悠伏枕左书空。","十年蹴鞠将雏远，万里秋千习俗同。","旅雁上云归紫塞，家人钻火用青枫。","秦城楼阁烟花里，汉主山河锦绣中。","风水春来洞庭阔，白苹愁杀白头翁。"],"theme":"羁旅思乡","theme2":["羁旅思乡"],"style":"沉郁","style2":["冲淡","绮丽"],"mood":"愁怨","mood2":["孤寂"],"scene":["清明","楼","秋"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"节日":["清明节"]},"theme_conf":0.8},{"uid":"9380d4f6-e19d-4ff1-8309-07f4ede69f7c","title":"北青萝","author":"李商隐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["残阳西入崦，茅屋访孤僧。","落叶人何在，寒云路几层。","独敲初夜磬，闲倚一枝藤。","世界微尘里，吾宁爱与憎。"],"theme":"送别","theme2":["哲理悟道","闲适隐逸"],"style":"婉约","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["夜"],"cats":{"抒情":["孤独"]},"theme_conf":0.388},{"uid":"b15a6f1f-1730-49e2-8f50-a0a5f7e51e26","title":"松滋江北阻风","author":"阎宽","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["江风久未歇，山雨复相仍。","巨浪天涯起，余寒川上凝。","忧人劳夕惕，乡事惫晨兴。","远听知音骇，诚哉不可陵。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["江"],"cats":{"抒情":["友情","思乡"],"山水":["江河"],"天气":["写风"]},"theme_conf":0.534},{"uid":"8a9d9842-af13-4e4a-9973-63799a2ff132","title":"晚岁登武陵城顾望水陆怅然有作","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["星象承乌翼，蛮陬想犬牙。","俚人祠竹节，仙洞闭桃花。","城基历汉魏，江源自賨巴。","华表廖王墓，菜地黄琼家。","霜轻菊秀晚，石浅水纹斜。","樵音绕故垒，汲路明寒沙。","清风稍改叶，卢橘始含葩。","野桥过驿骑，丛祠发逈笳。","跳鳞避举网，倦鸟寄行楂。","路尘高出树，山火远连霞。","夕曛转赤岸，浮霭起苍葭。","轧轧渡水桨，连连赴林鸦。","呌阍道非远，赐环期自赊。","孤臣本危涕，乔木在天涯。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"悲慨","style2":[],"mood":"孤寂","mood2":[],"scene":["鸟"],"cats":{"抒情":["孤独","怀古"],"生活":["写桥"],"植物":["桃花"]},"theme_conf":0.385},{"uid":"cp841ff9b4d78bde","title":"湘春夜月","author":"黄孝迈","dynasty":"宋","section":"宋词","form":"词","paragraphs":["近清明。","翠禽枝上消魂。","可惜一片清歌，都付与黄昏。","欲共柳花低诉，怕柳花轻薄，不解伤春。","念楚乡旅宿，柔情别绪，谁与温存。","空樽夜泣，青山不语，残月当门。","翠玉楼前，惟是有、一波湘水，摇荡湘云。","天长梦短，问甚时、重见桃根。","这次第，算人间没个并刀，翦断心上愁痕。"],"theme":"羁旅思乡","theme2":["节令风俗"],"style":"婉约","style2":["绮丽","沉郁"],"mood":"愁怨","mood2":["悲怆","相思"],"scene":["夜","春","月"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"天气":["月亮"],"节日":["清明节"]},"theme_conf":0.477},{"uid":"cp49f286ee613c2d","title":"秋霁","author":"史达祖","dynasty":"宋","section":"宋词","form":"词","paragraphs":["江水苍苍，望倦柳愁荷，共感秋色。","废阁先凉，古帘空暮，雁程最嫌风力。","故园信息。","爱渠入眼南山碧。","念上国。","谁是、脍鲈江汉未归客。","还又岁晚，瘦骨临风，夜闻秋声，吹动岑寂。","露蛩悲、清灯冷屋，翻书愁上鬓毛白。","年少俊游浑断得。","但可怜处，无奈苒苒魂惊，采香南浦，翦梅烟驿。"],"theme":"羁旅思乡","theme2":["送别"],"style":"清新","style2":["幽峭","沉郁"],"mood":"愁怨","mood2":["孤寂"],"scene":["秋"],"cats":{"抒情":["离别","思乡","伤感"],"四季":["秋天"]},"theme_conf":0.643},{"uid":"e57b65b7-0644-43db-9cb7-24c1f048abd1","title":"送上官侍御","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["执简朝方下，乘轺去不赊。","感恩轻远道，入幕比还家。","碣石春云色，邯郸古树花。","飞书报明主，烽火静天涯。"],"theme":"送别","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"抒情":["感恩"],"四季":["春天"]},"theme_conf":0.558},{"uid":"194a53e4-d7f8-49a6-92eb-3e36d41fd32c","title":"汨罗遇风","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["南来不作楚臣悲，重入修门自有期。","为报春风汨罗道，莫将波浪枉明时。"],"theme":"羁旅思乡","theme2":["民生疾苦"],"style":"悲慨","style2":["绮丽"],"mood":"慷慨","mood2":["悲怆"],"scene":["端午"],"cats":{"抒情":["思乡","伤感"],"天气":["写风"],"节日":["端午节"]},"theme_conf":0.588},{"uid":"80e7683d-5fdb-4cb6-96a0-c6fe3caac9fd","title":"和武相公中秋锦楼玩月 二","author":"崔备","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["四时皆有月，一夜独当秋。","照耀初含露，裴回正满楼。","遥连雪山净，逈入锦江流。","愿以清光末，年年许从游。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["中秋","秋","月","楼"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["江河"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.86},{"uid":"fdc07d9f-95b8-45f7-b1b3-9d272b3416a4","title":"秋日登吴公台上寺远眺寺即陈将吴明彻战场","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["古台摇落后，秋日望乡心。","野寺人来少，云峰水隔深。","夕阳依旧垒，寒磬满空林。","惆怅南朝事，长江独至今。"],"theme":"咏史怀古","theme2":["哲理悟道","边塞征战","羁旅思乡"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["惆怅"],"scene":["秋","江"],"cats":{"抒情":["思乡","孤独","怀古"],"四季":["秋天"],"山水":["长江"],"天气":["太阳"],"人生":["战争"]},"theme_conf":0.242},{"uid":"bb68efa3-9758-4ac2-927c-a0985c84acad","title":"答白刑部闻新蝉","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["蝉声未发前，已自感流年。","一入凄凉耳，如闻断续弦。","晴清依露叶，晚急畏霞天。","何事秋卿咏，逢时亦悄然。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"人生":["时光"]},"theme_conf":0.86},{"uid":"496955eb-549a-4176-84d3-ab6460eaa70f","title":"桃花","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["桃花浅深处，似匀深浅妆。","春风助肠断，吹落白衣裳。"],"theme":"山水田园","theme2":["咏物"],"style":"冲淡","style2":[],"mood":"愁怨","mood2":[],"scene":["春","花"],"cats":{"抒情":["伤感"],"四季":["春天"],"植物":["桃花"]},"theme_conf":0.516},{"uid":"92c10ce9-23b4-4e64-9b20-fc62a84e288c","title":"枯椶","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["蜀门多椶榈，高者十八九。","其皮割剥甚，虽众亦易朽。","徒布如云叶，青黄岁寒后。","交横集斧斤，凋丧先蒲柳。","伤时苦军乏，一物官尽取。","嗟尔江汉人，生成复何有。","有同枯椶木，使我沈叹久。","死者即已休，生者何自守。","啾啾黄雀啅，侧见寒蓬走。","念尔形影干，摧残没藜莠。"],"theme":"民生疾苦","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["冬"],"cats":{"抒情":["伤感"],"四季":["冬天"]},"theme_conf":0.65},{"uid":"3ce2a6ae-98e8-46bd-b9c1-05f545f7ea1d","title":"太和初靖恭里感事","author":"许浑","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["清湘吊屈原，垂泪撷苹蘩。","谤起乘轩鹤，机沈在槛猨。","乾坤三事贵，华夏一夫冤。","宁有唐虞世，心知不为言。"],"theme":"讽喻刺世","theme2":[],"style":"清新","style2":["婉约","沉郁"],"mood":"愁怨","mood2":[],"scene":["夏","端午"],"cats":{"抒情":["伤感"],"四季":["夏天"],"节日":["端午节"]},"theme_conf":1.0},{"uid":"a2d1860f-cd55-488c-9c4b-3d19d5b8d3ef","title":"病后遇王倚饮赠歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["麟角凤觜世莫识，煎胶续弦奇自见。","尚看王生抱此怀，在于甫也何由羡。","且遇王生慰畴昔，素知贱子甘贫贱。","酷见冻馁不足耻，多病沈年苦无健。","王生怪我颜色恶，荅云伏枕艰难徧。","疟疠三秋孰可忍，寒热百日相交战。","头白眼暗坐有胝，肉黄皮皱命如线。","惟生哀我未平复，为我力致美殽膳。","遣人向市赊香稉，唤妇出房亲自馔。","长安冬葅酸且绿，金城土酥静如练。","兼求富豪且割鲜，密沽斗酒谐终宴。","故人情义晚谁似，令我手脚轻欲漩。","老马为驹信不虚，当时得意况深眷。","但使残年饱吃饭，只愿无事常相见。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["婉约","幽峭"],"mood":"恬淡","mood2":["悲怆"],"scene":["冬","秋","酒"],"cats":{"抒情":["友情"],"四季":["秋天","冬天"]},"theme_conf":0.9},{"uid":"1f411fea-83c6-4e86-aadb-3e0fd0827366","title":"落叶送陈羽","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["落叶不更息，断蓬无复归。","飘飖终自异，邂逅暂相依。","悄悄深夜语，悠悠寒月辉。","谁云少年别，流泪各沾衣。"],"theme":"送别","theme2":["羁旅思乡"],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["秋","夜"],"cats":{"抒情":["思乡","伤感"],"植物":["叶子"]},"theme_conf":0.562},{"uid":"8e7a1341-509d-4548-b45e-2d223e034977","title":"送故人归蜀","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["一骑西南远，翩翩入剑门。","客衣筒布润，山舍荔枝繁。","古庙祠金马，春江带白鼋。","自应成旅逸，爱客有王孙。"],"theme":"送别","theme2":["羁旅思乡"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春","山","江"],"cats":{"抒情":["友情","思乡"],"四季":["春天"],"食物":["荔枝"]},"theme_conf":0.623},{"uid":"4a61c679-137e-47fb-a94c-dc41ff685ab9","title":"览柏中允兼子姪数人除官制词因述父子兄弟四美载歌丝纶","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["纷然丧乱际，见此忠孝门。","蜀中寇亦甚，柏氏功弥存。","深诚补王室，戮力自元昆。","三止锦江沸，独清玉垒昏。","高名入竹帛，新渥照乾坤。","子弟先卒伍，芝兰叠玙璠。","同心注师律，洒血在戎轩。","丝纶实具载，绂冕已殊恩。","奉公举骨肉，诛叛经寒温。","金甲雪犹冻，朱旗尘不飜。","每闻战场说，歘激懦气奔。","圣主国多盗，贤臣官则尊。","方当节钺用，必绝祲沴根。","吾病日回首，云台谁再论。","作歌挹盛事，推毂期孤骞。"],"theme":"亲情","theme2":[],"style":"沉郁","style2":["绮丽"],"mood":"孤寂","mood2":[],"scene":["楼","雪"],"cats":{"抒情":["孤独"],"人物":["父亲"],"人生":["战争"]},"theme_conf":0.585},{"uid":"3e4849dc-c411-49fa-8664-20a58b0493fd","title":"题郎士元半日吴村别业兼呈李长官","author":"钱起","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["半日吴村带晚霞，闲门高柳乱飞鵶。","横云岭外千重树，流水声中一两家。","愁人昨夜相思苦，闰月今年春意赊。","自叹梅生头似雪，却怜潘令县如花。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["江南"],"cats":{"抒情":["离别","思念","伤感"],"天气":["太阳"],"生活":["乡村"]},"theme_conf":0.373},{"uid":"cp414766c933671c","title":"高阳台","author":"周密","dynasty":"宋","section":"宋词","form":"词","paragraphs":["照野旌旗，朝天车马，平沙万里天低。","宝带金章，尊前茸帽风。","秦关汴水经行地，想登临、都付新诗。","纵英游，叠鼓清笳，骏马名姬。","酒酣应对燕山雪，正冰河月冻，晓陇云飞。","投老残年，江南谁念方回。","东风渐绿西湖柳，雁已还、人未南归。","最关情，折尽梅花，难寄相思。"],"theme":"送别","theme2":["爱情相思","民生疾苦","送别"],"style":"清新","style2":["豪放"],"mood":"相思","mood2":[],"scene":["江南","冬","鸟","江"],"cats":{"抒情":["爱情","思念"],"山水":["西湖"]},"theme_conf":0.92},{"uid":"f800050a-d7a0-4f12-a614-17fe23df8f41","title":"送杨氏女","author":"韦应物","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["永日方戚戚，出门复悠悠。","女子今有行，大江溯轻舟。","尔辈况无恃，抚念益慈柔。","幼为长所育，两别泣不休。","对此结中肠，义往难复留。","自小阙内训，事姑贻我忧。","赖兹托令门，仁恤庶无尤。","贫俭诚所尚，资从岂待周。","孝恭遵妇道，容止顺其猷。","别离在今晨，见尔当何秋。","居闲始自遣，临感忽难收。","归来视幼女，零泪缘缨流。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["舟","秋"],"cats":{"抒情":["离别","伤感"],"四季":["秋天"],"山水":["长江"]},"theme_conf":1.0},{"uid":"0b8ef604-25bb-4670-baee-590b8bd7a99f","title":"除夜宿石头驿","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["旅馆谁相问，寒灯独可亲。","一年将尽夜，万里未归人。","寥落悲前事，支离笑此身。","愁颜与衰鬓，明日又逢春。"],"theme":"羁旅思乡","theme2":[],"style":"幽峭","style2":["悲慨","豪放"],"mood":"孤寂","mood2":[],"scene":["夜","除夕"],"cats":{"抒情":["思乡","伤感","孤独"],"节日":["春节"]},"theme_conf":0.688},{"uid":"ead3046a-4747-487f-a645-2695cd744c3d","title":"杂曲歌辞 长安少年行十首 八","author":"李廓","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["新年高殿上，始见有光辉。","玉鴈排方带，金鹅立仗衣。","酒深和椀赐，马疾打珂飞。","朝下人争看，香街意气归。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"慷慨","mood2":["恬淡"],"scene":["酒"],"cats":{"抒情":["思乡"],"人生":["青春"],"节日":["春节"]},"theme_conf":1.0},{"uid":"35c4618c-3896-45f8-9b24-51764c90383f","title":"横吹曲辞 折杨柳","author":"刘宪","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["沙塞三河道，金闺二月春。","碧烟杨柳色，红粉绮罗人。","露叶怜啼脸，风花思舞巾。","攀持君不见，为听曲中新。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"绮丽","style2":["清新"],"mood":"相思","mood2":[],"scene":["塞外","春","花","月"],"cats":{"抒情":["思念","闺怨"],"四季":["春天"],"生活":["边塞"],"植物":["柳树"]},"theme_conf":0.5},{"uid":"e3f71946-f5ac-4789-a750-6af2337a11b8","title":"又酬晓灯[离暗]室五首 四","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["楚僧话寂灭，俗虑比虚空。","赖有残灯喻，相传昏暗中。"],"theme":"佛道禅颂","theme2":[],"style":"冲淡","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["元宵","夜"],"cats":{"抒情":["离别"],"节日":["元宵节"]},"theme_conf":0.9},{"uid":"333b66bc-2738-4424-aaf9-c8834be7fabe","title":"琴曲歌辞 风入松歌","author":"僧皎然","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["西岭松声落日秋，千枝万叶风飕飗。","美人援琴弄成曲，写得松间声断续。","声断续，清我魂，流波坏陵安足论。","美人夜坐月明里，含少商兮照清征。","风何凄兮飘飉，搅寒松兮又夜起。","夜未央，曲何长，金徽更促声泱泱。","何人此时不得意，意苦弦悲闻客堂。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"悲慨","style2":[],"mood":"愁怨","mood2":["悲怆"],"scene":["夜","秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"天气":["写风"],"人物":["女子"]},"theme_conf":0.565},{"uid":"bbe77207-c21e-4f74-9e94-fee4f8cb57fc","title":"相和歌辞 采莲曲","author":"储光羲","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["浅渚荷花繁，深塘菱叶疎。","独往方自得，耻邀淇上姝。","广江无术阡，大泽绝方隅。","浪中海童语，流下鲛人居。","春雁时隐舟，新荷复满湖。","采采乘日暮，不思贤与愚。"],"theme":"爱情相思","theme2":["山水田园"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["孤独"],"植物":["荷花"]},"theme_conf":0.534},{"uid":"542cb326-1037-4bd9-b0f6-6479d165dc4c","title":"岁暮归南山","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["北阙休上书，南山归敝庐。","不才明主弃，多病故人疎。","白发催年老，青阳逼岁除。","永怀愁不寐，松月夜窗虚。"],"theme":"山水田园","theme2":["节令风俗","羁旅思乡"],"style":"沉郁","style2":[],"mood":"惆怅","mood2":["愁怨"],"scene":["山","夜","除夕"],"cats":{"抒情":["思乡","伤感"],"节日":["春节"]},"theme_conf":0.425},{"uid":"246d388f-1a6f-4b5d-a153-617a64578503","title":"和李中丞詶万年房署少府过汾州景云观因以寄上房与李早年同居此观","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["显晦澹无迹，贤哉常晏如。","如何警孤鹤，忽乃传双鱼。","叙以泉石旧，怅然风景余。","低回青油幕，梦寐白云居。","玉洞桂香满，雪坛松影疎。","沈思瞩仙侣，纾组正军书。","积学早成道，感恩难遂初。","梅生谅多感，归止岂吾庐。"],"theme":"寄赠酬答","theme2":["山水田园","应制干谒","咏史怀古"],"style":"冲淡","style2":[],"mood":"相思","mood2":["恬淡","孤寂"],"scene":["冬","雪"],"cats":{"抒情":["孤独","怀古","感恩"],"天气":["写云"]},"theme_conf":0.88},{"uid":"757a180d-55eb-4931-9f10-c71649f6a06d","title":"秋日过鸿举法师寺院便送归江陵","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["看画长廊遍，寻僧一径幽。","小池兼鹤净，古木带蝉秋。","客至茶烟起，禽归讲席收。","浮杯明日去，相望水悠悠。"],"theme":"送别","theme2":["咏史怀古","哲理悟道"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","园林"],"cats":{"抒情":["怀古"],"四季":["秋天"],"天气":["太阳"],"人物":["老师"],"动物":["写鸟"]},"theme_conf":0.28},{"uid":"8e2f586b-9ef4-4672-af24-723a5ec87773","title":"和令狐舍人酬峰上人题山栏孤竹","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["满院冰姿粉箨残，一茎青翠近帘端。","离丛自欲亲香火，抱节何妨共岁寒。","能让繁声任真籁，解将孤影对芳兰。","范云许访西林寺，枝叶须和彩凤看。"],"theme":"山水田园","theme2":["送别"],"style":"沉郁","style2":["旷达"],"mood":"孤寂","mood2":[],"scene":["山","冬"],"cats":{"抒情":["孤独"],"四季":["冬天"],"山水":["庐山"],"植物":["竹子"]},"theme_conf":0.381},{"uid":"3866facf-d8d2-4f4e-b7c4-eefbc12bfdea","title":"关羽祠送高员外还荆州","author":"郎士元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["将军禀天姿，义勇冠今昔。","走马百战场，一剑万人敌。","虽为感恩者，竟是思归客。","流落荆巫间，裴回故乡隔。","离筵对祠宇，洒酒暮天碧。","去去勿复言，衔悲向陈迹。"],"theme":"送别","theme2":["边塞征战","咏史怀古","羁旅思乡"],"style":"豪放","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["酒"],"cats":{"抒情":["思乡","伤感","怀古","感恩"],"人生":["战争"]},"theme_conf":0.72},{"uid":"5bb5c590-5de8-4bfb-aee6-30bc4bcdf99a","title":"次北固山下","author":"王湾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["客路青山外，行舟绿水前。","潮平两岸阔，风正一帆悬。","海日生残夜，江春入旧年。","乡书何处达，归雁洛阳边。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["山","舟","江"],"cats":{"抒情":["思乡"]},"theme_conf":0.583},{"uid":"cp1ed0c38b00fc04","title":"声声慢","author":"李清照","dynasty":"宋","section":"宋词","form":"词","paragraphs":["寻寻觅觅，冷冷清清，凄凄惨惨戚戚。","乍暖还寒时候，最难将息。","三杯两盏淡酒，怎敌他、晚来风急。","雁过也，正伤心，却是旧时相识。","满地黄花堆积。","憔悴损，如今有谁摘。","守著窗儿，独自怎生得黑。","梧桐更兼细雨，到黄昏、点点滴滴。","这次第，怎一个、愁字了得。"],"theme":"闺情宫怨","theme2":[],"style":"沉郁","style2":["婉约","幽峭"],"mood":"愁怨","mood2":[],"scene":["雨","酒","夜"],"cats":{"抒情":["伤感","闺怨"],"天气":["写雨"]},"theme_conf":0.62},{"uid":"e80bca1f-12ef-4187-b623-b614aa6bee78","title":"寄李十二白二十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["昔年有狂客，号尔谪仙人。","笔落惊风雨，诗成泣鬼神。","声名从此大，汩没一朝伸。","文彩承殊渥，流传必绝伦。","龙舟移櫂晚，兽锦夺袍新。","白日来深殿，青云满后尘。","乞归优诏许，遇我宿心亲。","未负幽栖志，兼全宠辱身。","剧谈怜野逸，嗜酒见天真。","醉舞梁园夜，行歌泗水春。","才高心不展，道屈善无邻。","处士祢衡俊，诸生原宪贫。","稻粱求未足，薏苡谤何频。","五岭炎蒸地，三危放逐臣。","几年遭𫛳鸟，独泣向麒麟。","苏武先还汉，黄公岂事秦。","楚筵辞醴日，梁狱上书辰。","已用当时法，谁将此义陈。","老吟秋月下，病起暮江滨。","莫怪恩波隔，乘槎与问津。"],"theme":"寄赠酬答","theme2":["闲适隐逸"],"style":"豪放","style2":["幽峭","沉郁"],"mood":"悲怆","mood2":["孤寂"],"scene":["酒","雨","端午","舟","春","秋"],"cats":{"抒情":["孤独"],"四季":["春天","秋天"],"人生":["梦想"],"节日":["端午节"]},"theme_conf":0.98},{"uid":"b86dfe06-639c-446e-ac96-298a1403d16e","title":"同群公秋登琴台","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["古迹使人感，琴台空寂寥。","静然顾遗尘，千载如昨朝。","临眺自兹始，群贤久相邀。","德与形神高，孰知天地遥。","四时何倏忽，六月鸣秋蜩。","万象归白帝，平川横赤霄。","犹是对夏伏，几时有凉飙。","燕雀满簷楹，鸿鹄抟扶摇。","物性各自得，我心在渔樵。","兀然还复醉，尚握尊中瓢。"],"theme":"咏史怀古","theme2":["闲适隐逸","山水田园"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","楼"],"cats":{"抒情":["怀古"],"四季":["秋天"],"人生":["梦想"]},"theme_conf":0.408},{"uid":"eeafa160-a9d9-484d-9cbe-01a796260aa2","title":"相和歌辞 门有车马客行","author":"虞世南","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["财雄重交结，戚里擅豪华。","曲台临上路，高门抵狭斜。","赭汗千金马，绣毂五香车。","白鹤随飞盖，朱鹭入鸣笳。","夏莲开劒水，春桃发露花。","轻裙染回雪，浮蚁泛流霞。","高谈辨飞兔，摛藻握灵蛇。","逢恩借羽翼，失路委泥沙。","暧暧风烟晚，路长归骑远。","日斜青琐第，尘飞金谷苑。","危弦促柱奏巴渝，遗簪堕珥解罗襦。","如何守直道，飜使谷名愚。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"相思","mood2":[],"scene":["夏","花","雪","春"],"cats":{"抒情":["思乡"],"四季":["春天","夏天"],"动物":["写马"]},"theme_conf":0.661},{"uid":"ac2f736a-0a3d-4ec1-a855-374f26faff25","title":"再至界围岩水帘遂宿岩下","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["发春念长违，中夏欣再覩。","是时植物秀，杳若临悬圃。","歊阳讶垂冰，白日惊雷雨。","笙簧潭际起，鹳鹤云间舞。","古苔凝青枝，阴草湿翠羽。","蔽空素彩列，激浪寒光聚。","的皪沈珠渊，锵鸣捐佩浦。","幽岩画屏倚，新月玉钩吐。","夜凉星满川，忽疑眠洞府。"],"theme":"山水田园","theme2":["闺情宫怨"],"style":"绮丽","style2":["婉约","冲淡"],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"抒情":["闺怨"],"山水":["瀑布"]},"theme_conf":0.579},{"uid":"a7f425de-143b-493d-bb51-13e27c68e871","title":"赠别二首 二","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["多情却似总无情，唯觉尊前笑不成。","蜡烛有心还惜别，替人垂泪到天明。"],"theme":"送别","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"欢愉","mood2":["愁怨"],"scene":[],"cats":{"抒情":["离别","伤感"]},"theme_conf":1.0},{"uid":"8c37cdbb-74bd-4eea-b15e-2237a6d7eaf1","title":"西湖晚归回望孤山寺赠诸客","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["柳湖松岛莲花寺，晚动归桡出道场。","卢橘子低山雨重，棕榈叶战水风凉。","烟波澹荡摇空碧，楼殿参差倚夕阳。","到岸请君回首望，蓬莱宫在海中央。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"冲淡","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["江","山","江南"],"cats":{"抒情":["思乡","孤独"],"山水":["西湖"]},"theme_conf":0.86},{"uid":"a6d7f53c-9631-4849-9975-4887c7e0fb61","title":"又酬晓灯[离暗]室五首 一","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["知疑奸叟谤，闲与情人话。","犹是别时灯，不眠同此夜。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["夜","元宵"],"cats":{"抒情":["离别"],"节日":["元宵节"]},"theme_conf":0.72},{"uid":"9687a143-c526-4bdc-b779-f95ea0de8e69","title":"观灯","author":"张萧远","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["十万人家火烛光，门门开处见红妆。","歌钟喧夜更漏暗，罗绮满街尘土香。","星宿别从天畔出，莲花不向水中芳。","宝钗骤马多遗落，依旧明朝在路傍。"],"theme":"闺情宫怨","theme2":["送别"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["夜","花"],"cats":{"抒情":["闺怨"],"节日":["元宵节"]},"theme_conf":0.536},{"uid":"cpa356df56563a47","title":"双双燕","author":"史达祖","dynasty":"宋","section":"宋词","form":"词","paragraphs":["过春社了，度帘幕中间，去年尘冷。","差池欲住，试入旧巢相并。","还相雕梁藻井。","又软语、商量不定。","飘然快拂花梢，翠尾分开红影。","芳径。","芹泥雨润。","爱贴地争飞，竞夸轻俊。","红楼归晚，看足柳昏花暝。","应自栖香正稳。","便忘了、天涯芳信。","愁损翠黛双蛾，日日画阑独凭。"],"theme":"羁旅思乡","theme2":["闺情宫怨"],"style":"绮丽","style2":["婉约"],"mood":"愁怨","mood2":["孤寂"],"scene":["花"],"cats":{"抒情":["思乡","伤感","孤独","闺怨"],"动物":["写鸟"]},"theme_conf":0.556},{"uid":"8fd9bf41-ae6c-4def-aa3e-e6c92abc811f","title":"杂曲歌辞 出门行","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["兄弟同出门，同行不同志。","凄凄分岐路，各各营所为。","兄上荆山巅，翻石辨虹气。","弟沈沧海底，偷珠待龙睡。","出门不数年，同归亦同遂。","俱用私所珍，升沈自兹异。","献珠龙王宫，值龙觅珠次。","但喜复得珠，不求珠所自。","酬客双龙女，授客六龙辔。","遣充行雨神，雨泽随客意。","雩夏钟鼓繁，禜秋玉帛积。","彩色画廊庙，奴僮被珠翠。","骥𫘧千万双，鸳鸯七十二。","言者禾稼枯，无人敢轻议。","其兄因献璞，再刖不履地。","门户亲戚疎，匡床妻妾弃。","铭心有所待，视足无所愧。","持璞自枕头，泪痕双血渍。","一朝龙醒寤，本问偷珠事。","因知行雨偏，妻子五刑备。","仁兄捧尸哭，势友掉头讳。","丧车黔首葬，吊客青蝇至。","楚有望气人，王前忽长跪。","贺王得贵宝，不远王所莅。","求之果如言，剖则浮云腻。","白珩无颜色，垂棘有瑕累。","在楚列地封，入赵连城贵。","秦遣李斯书，书为传国瑞。","秦亡汉魏传，传者得神器。","卞和名永永，与宝不相坠。","劝尔出门行，行难莫行易。","易得还易失，难同亦难离。","善贾识贪廉，良田无稙穉。","磨劒莫磨锥，磨锥成小利。"],"theme":"哲理悟道","theme2":["送别","悼亡挽歌"],"style":"绮丽","style2":["沉郁"],"mood":"愁怨","mood2":["悲怆"],"scene":["夏","雨"],"cats":{"抒情":["伤感","悼亡"],"四季":["夏天"]},"theme_conf":0.8},{"uid":"529cf938-bb80-4453-b73f-7425d18396e4","title":"杂曲歌辞 长干行二首 二","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["忆妾深闺里，烟尘不曾识。","嫁与长干人，沙头候风色。","五月南风兴，思君在巴陵。","八月西风起，想君发扬子。","去来悲如何，见少别离多。","湘潭几日到，妾梦越风波。","昨夜狂风度，吹折江头树。","淼淼暗无边，行人在何处？","北客真王公，朱衣满江中。","日暮来投宿，数朝不肎东。","好乘浮云骢，佳期兰渚东。","鸳鸯绿浦上，翡翠锦屏中。","自怜十五余，颜色桃李红。","那作商人妇，愁水复愁风。"],"theme":"闺情宫怨","theme2":["送别","爱情相思","羁旅思乡"],"style":"绮丽","style2":[],"mood":"相思","mood2":["愁怨","悲怆"],"scene":["江","月"],"cats":{"抒情":["爱情","离别","思念","思乡","伤感","闺怨"],"天气":["写风"]},"theme_conf":0.85},{"uid":"5f34d119-60d9-4762-87c7-7d84d0baa8ff","title":"相和歌辞 塘上行","author":"李贺","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["藕花凉露湿，花缺藕根涩。","飞下雌鸳鸯，塘水声溢溢。"],"theme":"爱情相思","theme2":[],"style":"幽峭","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["爱情"]},"theme_conf":1.0},{"uid":"c4d9440e-b2d8-4c43-930b-ba0c5dd68548","title":"将晓二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["石城除击柝，铁锁欲开关。","鼓角悲荒塞，星河落曙山。","巴人常小梗，蜀使动无还。","垂老孤帆色，飘飘犯百蛮。"],"theme":"边塞征战","theme2":[],"style":"清新","style2":["沉郁","悲慨"],"mood":"悲怆","mood2":["孤寂"],"scene":["塞外","舟","山"],"cats":{"抒情":["伤感","孤独"],"天气":["星星"],"生活":["边塞"]},"theme_conf":0.683},{"uid":"382c265b-130c-43b1-b500-f49215b85f2e","title":"岭南江行","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["瘴江南去入云烟，望尽黄茆是海边。","山腹雨晴添象迹，潭心日暖长蛟涎。","射工巧伺游人影，飓母偏惊旅客船。","从此忧来非一事，岂容华髪待流年。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"慷慨","mood2":["愁怨"],"scene":["江","山","江南"],"cats":{"抒情":["思乡"],"山水":["江河"],"人生":["时光"]},"theme_conf":0.531},{"uid":"8c0642c4-2103-4d80-bff2-3549978fb9f4","title":"郊庙歌辞 中宗祀昊天乐章 告谢","author":"不详","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["得一流玄泽，通三御紫宸。","远叶千龄运，遐销九域尘。","绝瑞骈阗集，殊祥络绎臻。","登年庆栖亩，稔岁贺盈囷。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"抒情":["感恩"]},"theme_conf":0.9},{"uid":"45e93c66-046f-44aa-9752-7e4246ad6c43","title":"自淇涉黄河途中作十三首 八","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["兹川方悠邈，云沙无前后。","古堰对河壖，长林出淇口。","独行非吾意，东向日已久。","忧来谁得知，且酌尊中酒。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["愁怨"],"scene":["酒","江"],"cats":{"抒情":["孤独"],"山水":["江河","黄河"]},"theme_conf":0.65},{"uid":"17c35064-6bb1-4b91-a555-c2ae3768ec7c","title":"雨二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["青山澹无姿，白露谁能数。","片片水上云，萧萧沙中雨。","殊俗状巢居，曾台俯风渚。","佳客适万里，沈思情延伫。","挂帆远色外，惊浪满吴楚。","久阴蛟螭出，寇盗复几许。"],"theme":"羁旅思乡","theme2":["羁旅思乡","山水田园"],"style":"冲淡","style2":["豪放"],"mood":"恬淡","mood2":[],"scene":["雨"],"cats":{"抒情":["思乡"],"天气":["写雨"]},"theme_conf":0.63},{"uid":"cb55e33f-ee4d-4b88-a23f-280fd0cfd271","title":"杂曲歌辞 春日行","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["深宫高楼入紫清，金作蛟龙盘绣楹。","佳人当窗弄白日，弦将手语弹鸣筝。","春风吹落君王耳，此曲乃是升天行。","因出天池泛蓬瀛，楼船蹙沓波浪惊。","三千双蛾献歌笑，挝钟考鼓宫殿倾。","万姓聚舞歌太平，我无为，人自宁。","三十六帝欲相迎，仙人飘翩下云𫐌。","帝不去，留镐京。","安能为轩辕，独往入窅冥。","小臣拜献南山寿，陛下万古垂鸿名。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独","闺怨"],"四季":["春天"],"天气":["太阳"],"人物":["女子"]},"theme_conf":0.65},{"uid":"56f535d2-27cb-485a-9fc4-1c4f04e2131d","title":"霜菊","author":"席夔","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["时令忽已变，行看被霜菊。","可怜后时秀，当此凛风肃。","淅沥翠枝翻，凄清金蘂馥。","凝姿节堪重，澄艳景非淑。","宁祛青女威，愿盈君子掬。","持来泛罇酒，永以照幽独。"],"theme":"咏物","theme2":["咏物"],"style":"绮丽","style2":["清新"],"mood":"孤寂","mood2":["愁怨"],"scene":["秋","重阳"],"cats":{"抒情":["孤独"],"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.96},{"uid":"b04b21d5-0f49-468d-963b-cfc58ae76654","title":"锦树行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["今日苦短昨日休，岁云暮矣增离忧。","霜凋碧树待锦树，万壑东逝无停留。","荒戍之城石色古，东郭老人住青丘。","飞书白帝营斗粟，琴瑟几杖柴门幽。","青草萋萋尽枯死，天马跂足随牦牛。","自古圣贤多薄命，奸雄恶少皆封侯。","故国三年一消息，终南渭水寒悠悠。","五陵豪贵反颠倒，乡里小儿狐白裘。","生男堕地要膂力，一生富贵倾邦国。","莫愁父母少黄金，天下风尘儿亦得。"],"theme":"讽喻刺世","theme2":["羁旅思乡","咏史怀古","边塞征战"],"style":"绮丽","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["思乡","伤感","怀古"],"人物":["儿童"]},"theme_conf":0.87},{"uid":"f75b4a85-1195-4795-bb42-4d7d52303414","title":"乐府","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["五更窗下簇妆台，已怕堂前阿母催。","满鸭香薰鹦鹉睡，隔帘灯照牡丹开。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["夜"],"cats":{"抒情":["闺怨"],"人物":["母亲"]},"theme_conf":1.0},{"uid":"f45104c8-145d-4f09-ac5d-1b9ac85dad65","title":"人日两篇 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["元日到人日，未有不阴时。","冰雪莺难至，春寒花较迟。","云随白水落，风振紫山悲。","蓬鬓稀疎久，无劳比素丝。"],"theme":"节令风俗","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["春","雪","冬"],"cats":{"抒情":["伤感"],"四季":["春天"],"天气":["写雪","太阳"],"节日":["春节"]},"theme_conf":0.58},{"uid":"b41e25f5-5a57-497f-a3a2-84bdfb9331f5","title":"春怨","author":"金昌绪","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["打起黄莺儿，莫教枝上啼。","啼时惊妾梦，不得到辽西。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"]},"theme_conf":0.769},{"uid":"d45caed5-bc9a-4c16-836a-97e68e9b2f81","title":"解闷十二首 九","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["先帝贵妃今寂寞，荔枝还复入长安。","炎方每续朱[樱]献，玉座应悲白露[团]。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["孤寂"],"scene":["夏"],"cats":{"抒情":["伤感","孤独","怀古"],"食物":["荔枝"]},"theme_conf":0.9},{"uid":"4b0047aa-a695-43a5-a4a7-b1f2529ba792","title":"聪马行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["邓公马癖人共知，初得花骢大宛种。","夙昔传闻思一见，牵来左右神皆竦。","雄姿逸态何崷崪，顾影骄嘶自矜宠。","隅目青荧夹镜悬，肉骏碨礌连钱动。","朝来久试华轩下，未觉千金满高价。","赤汗微生白雪毛，银鞍却覆香罗帕。","卿家旧赐公取之，天厩真龙此其亚。","昼洗须腾泾渭深，朝趋可刷幽幷夜。","吾闻良骥老始成，此马数年人更惊。","岂有四蹄疾于鸟，不与八骏俱先鸣。","时俗造次那得致，云雾晦冥方降精。","近闻下诏喧都邑，肯使骐𬴊地上行。"],"theme":"咏物","theme2":["羁旅思乡"],"style":"绮丽","style2":["婉约"],"mood":"恬淡","mood2":[],"scene":["夜","花","雪"],"cats":{"抒情":["思乡"],"动物":["写马"]},"theme_conf":0.97},{"uid":"5b4779dc-84b7-41d9-80b9-f7fd0393594f","title":"送刘道士之成都严真观","author":"项斯","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["严君名不朽，道出二经中。","归去精诚恳，还应梦寐通。","池台镜定月，松桧雨余风。","想对灵玄忆，人间恋若空。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["月","雨"],"cats":{"抒情":["思念"],"人物":["父亲"]},"theme_conf":1.0},{"uid":"80b59d90-c62e-4269-8883-3b625cd91ba7","title":"至日遣兴奉寄北省旧阁老两院故人二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["忆昨逍遥供奉班，去年今日侍龙颜。","麒麟不动炉烟上，孔雀徐开扇影还。","玉几由来天北极，朱衣只在殿中间。","孤城此日堪肠断，愁对寒云雪满山。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["楼","园林","冬","雪"],"cats":{"抒情":["友情","伤感","孤独"],"天气":["太阳"]},"theme_conf":0.94},{"uid":"2b8a54fd-f08a-4f0d-a6ab-96774ef6b15b","title":"杂曲歌辞 夜坐吟","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["冬夜夜寒觉夜长，沈吟久坐坐北堂。","冰合井泉月入闺，青缸凝明照悲嗁。","青缸灭，嗁转多，掩妾泪，听君歌。","歌有声，妾有情，情声合，两无违。","一语不入意，从君万曲梁尘飞。"],"theme":"闺情宫怨","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["愁怨"],"scene":["夜","冬"],"cats":{"抒情":["伤感","闺怨"],"四季":["冬天"]},"theme_conf":0.676},{"uid":"b9615ed8-64d5-4106-b37e-feca45697b6c","title":"送杨皞擢第游江南","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["行人临水去，新咏复新悲。","万里高秋月，孤山远别时。","挂帆严子濑，酹酒敬亭祠。"],"theme":"送别","theme2":[],"style":"豪放","style2":["悲慨"],"mood":"悲怆","mood2":["孤寂"],"scene":["江南","江"],"cats":{"抒情":["伤感","孤独"],"山水":["西湖"]},"theme_conf":0.825},{"uid":"fe6b1d10-773b-41cc-ba18-6cf545884231","title":"对雪","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["北雪犯长沙，胡云冷万家。","随风且间叶，带雨不成花。","金错囊从罄，银壶酒易赊。","无人竭浮蚁，有待至昏鸦。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["雪"],"cats":{"抒情":["孤独"],"天气":["写雪"]},"theme_conf":1.0},{"uid":"ef4d4ca2-59ea-4c84-b360-b63252700998","title":"同吉中孚梦桃源 一","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["春雨夜不散，梦中山亦阴。","云中碧潭水，路暗红花林。","花水自深浅，无人知古今。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["花","春","雨","夜","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"人生":["梦想"],"植物":["桃花"]},"theme_conf":0.784},{"uid":"da9dca80-4137-4ef6-8851-2c0e23463a22","title":"无可奈何歌","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["无可奈何兮！白日走而朱颜颓，少日往而老日催。","生者不住兮死者不回，况乎宠辱丰顇之外物。","又何常不十去而一来，去不可挽兮来不可推。","无可奈何兮！已焉哉！惟天长而地久，前无始兮后无终。","嗟吾生之几何，寄瞬息乎其中。","又如太仓之稊米，委一粒于万锺。","何不与道逍遥？","委化从容。","纵心放志，泄泄融融。","胡为乎分爱恶于生死，系忧喜于穷通。","倔强其骨髓，龃龉其心胷。","合冰炭以交战，祗自苦兮厥躬。","彼造物者，云何不为。","此与化者，云何不随。","或喣或吹，或盛或衰。","虽千变与万化，委一顺以贯之。","为彼何非，为此何是。","谁冥此心，梦蝶之子。","何祸非福，何吉非凶。","谁达此观，丧马之翁。","俾吾为秋毫之杪，吾亦自足。","不见其小，俾吾为泰山之阿。","吾亦无余，不见其多。","是以达人静则脗然与阴合迹，动则浩然与阳同波。","委顺而已，孰知其他。","时邪命邪！吾其无奈彼何？委邪顺邪！彼亦无奈吾何？夫两无奈何，然后能冥至顺而合太和。","故吾所以饮太和，扣至顺，而为无可奈何之歌。"],"theme":"哲理悟道","theme2":["讽喻刺世","悼亡挽歌","民生疾苦"],"style":"悲慨","style2":["旷达"],"mood":"惆怅","mood2":["愁怨"],"scene":["山"],"cats":{"抒情":["伤感","悼亡"],"山水":["泰山"]},"theme_conf":0.95},{"uid":"cpfcbc3991d9a399","title":"谢金莲诗酒红梨花・采茶歌","author":"张寿卿","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["俺从那期程，伴着这书生，直吃的碧桃花下月三更。","你个嬷嬷夫人心休硬，便有合该罪犯俺招承。"],"theme":"闲适隐逸","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["花","酒","夜"],"cats":{"抒情":["感恩"],"植物":["梨花","荷花"],"食物":["写酒","写茶"]},"theme_conf":1.0},{"uid":"b298777c-4db6-424c-b441-e4051bf7ecc9","title":"春日叶秀才曲江","author":"罗隐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["江花江草暖相隈，也向江边把酒杯。","春色恼人遮不得，别愁如疟避还来。","安排贱迹无良策，裨补明时望重才。","一曲吴歌齐拍手，十年尘眼未曾开。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春","江","酒"],"cats":{"抒情":["伤感"],"四季":["春天"],"山水":["江河"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"82d09cba-94f5-40ba-9435-ec83e2c5ad89","title":"游子","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["萱草生堂堦，游子行天涯。","慈亲倚堂门，不见萱草花。"],"theme":"亲情","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["思念"],"人物":["母亲"]},"theme_conf":0.787},{"uid":"26a4d4f1-b9bb-42c4-8201-8b84b88c5531","title":"江梅","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["梅蘂腊前破，梅花年后多。","绝知春意好，最奈客愁何。","雪树元同色，江风亦自波。","故园不可见，巫岫郁嵯峨。"],"theme":"羁旅思乡","theme2":["咏物"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["江","冬"],"cats":{"抒情":["思乡","伤感"],"山水":["江河"],"植物":["梅花"]},"theme_conf":0.638},{"uid":"b3869955-7214-4042-942d-a22afb8575eb","title":"杂嘲二首 一","author":"崔涯","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["二年不到宋家东，阿母深居僻巷中。","含泪向人羞不语，琵琶弦断倚屏风。"],"theme":"题画咏艺","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["伤感"],"人物":["母亲"]},"theme_conf":1.0},{"uid":"b71d7c9c-7e92-4797-b2c9-8715dd0c2881","title":"与诸子登岘山","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["人事有代谢，往来成古今。","江山留胜迹，我辈复登临。","水落鱼梁浅，天寒梦泽深。","羊公碑字在，读罢泪沾襟。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":["婉约","沉郁"],"mood":"愁怨","mood2":[],"scene":["山"],"cats":{"抒情":["伤感","怀古"]},"theme_conf":0.742},{"uid":"5d5532a1-5286-4ccb-abdc-6118ad48504d","title":"横吹曲辞 折杨柳","author":"乔知之","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["可怜濯濯春杨柳，攀折将来就纤手。","妾容与此同盛衰，何必君恩独能久。"],"theme":"闺情宫怨","theme2":[],"style":"旷达","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独","闺怨"],"四季":["春天"],"植物":["柳树"]},"theme_conf":1.0},{"uid":"1f83fccf-7476-464b-8cd4-8a2b4569c7a0","title":"送友人","author":"李白","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["青山横北郭，白水遶东城。","此地一为别，孤蓬万里征。","浮云游子意，落日故人情。","挥手自兹去，萧萧班马鸣。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"抒情":["友情","孤独"]},"theme_conf":0.73},{"uid":"823ebceb-6848-442c-918e-5cbfe2a70f93","title":"浔阳三题 东林寺白莲","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东林北塘水，湛湛见底清。","中生白芙蓉，菡萏三百茎。","白日发光彩，清飙散芳馨。","泄香银囊破，泻露玉盘倾。","我慙尘垢眼，见此琼瑶英。","乃知红莲花，虚得清净名。","夏萼敷未歇，秋房结才成。","夜深众僧寝，独起绕池行。","欲收一颗子，寄向长安城。","但恐出山去，人间种不生。"],"theme":"咏物","theme2":[],"style":"清新","style2":["绮丽"],"mood":"孤寂","mood2":[],"scene":["花"],"cats":{"抒情":["孤独"],"山水":["庐山"],"植物":["荷花"]},"theme_conf":0.94},{"uid":"d66f1624-d12b-41ca-b51d-b90d430bf734","title":"滕王亭子","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["寂寞春山路，君王不复行。","古墙犹竹色，虚阁自松声。","鸟雀荒村暮，云霞过客情。","尚思歌吹入，千骑把霓旌。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["楼"],"cats":{"抒情":["孤独"],"天气":["写云"]},"theme_conf":1.0},{"uid":"24ca9268-9cbd-423b-b423-12e1a9aa9041","title":"将赴吴兴登乐游原一绝","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["清时有味是无能，闲爱孤云静爱僧。","欲把一麾江海去，乐游原上望昭陵。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"欢愉","mood2":[],"scene":["江南"],"cats":{"抒情":["怀古"]},"theme_conf":0.532},{"uid":"46013ebf-55a5-421e-a8fb-c1d55a3c67b3","title":"壮游","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["往昔十四五，出游翰墨场。","斯文崔魏徒，以我似班扬。","七龄思即壮，开口咏凤皇。","九龄书大字，有作成一囊。","性豪业嗜酒，嫉恶怀刚肠。","脱略小时辈，结交皆老苍。","饮酣视八极，俗物都茫茫。","东下姑苏台，已具浮海航。","到今有遗恨，不得穷扶桑。","王谢风流远，阖庐丘墓荒。","劒池石壁仄，长洲荷芰香。","嵯峨阊门北，清庙映回塘。","每趋吴太伯，抚事泪浪浪。","枕戈忆句践，渡浙想秦皇。","蒸鱼闻匕首，除道哂要章。","越女天下白，鉴湖五月凉。","剡溪蕴秀异，欲罢不能忘。","归帆拂天姥，中岁贡旧乡。","气劘屈贾垒，目短曹刘墙。","忤下考功第，独辞京尹堂。","放荡齐赵间，裘马颇清狂。","春歌丛台上，冬猎青丘旁。","呼鹰皂枥林，逐兽云雪冈。","射飞曾纵鞚，引臂落鹙鸧。","苏侯据鞍喜，忽如携葛强。","快意八九年，西归到咸阳。","许与必词伯，赏游实贤王。","曳裾置醴地，奏赋入明光。","天子废食召，群公会轩裳。","脱身无所爱，痛饮信行藏。","黑貂不免敝，斑鬓兀称觞。","杜曲晚耆旧，四郊多白杨。","坐深乡党敬，日觉死生忙。","朱门任倾夺，赤族迭罹殃。","国马竭粟豆，官鸡输稻粱。","举隅见烦费，引古惜兴亡。","河朔风尘起，岷山行幸长。","两宫各警跸，万里遥相望。","崆峒杀气黑，少海旌旗黄。","禹功亦命子，涿鹿亲戎行。","翠华拥英岳，螭虎噉豺狼。","爪牙一不中，胡兵更陆梁。","大军载草草，凋瘵满膏肓。","备员窃补衮，忧愤心飞扬。","上感九庙焚，下悯万民疮。","斯时伏青蒲，延争守御床。","君辱敢爱死，赫怒幸无伤。","圣哲体仁恕，宇县复小康。","哭庙灰烬中，鼻酸朝未央。","小臣议论绝，老病客殊方。","郁郁苦不展，羽翮困低昂。","秋风动哀壑，碧蕙捐微芳。","之推避赏从，渔父濯沧浪。","荣华敌勋业，岁暮有严霜。","吾观鸱夷子，才格出寻常。","群凶逆未定，侧伫英俊翔。"],"theme":"咏怀抒感","theme2":["咏史怀古","边塞征战","悼亡挽歌"],"style":"沉郁","style2":["豪放"],"mood":"愁怨","mood2":["悲怆","慷慨"],"scene":["冬","江南","酒","山","秋"],"cats":{"抒情":["伤感","悼亡","怀古"],"四季":["秋天","冬天"],"天气":["写风"]},"theme_conf":0.85},{"uid":"cp4a62a14d478e1a","title":"临江仙","author":"苏轼","dynasty":"宋","section":"宋词","form":"词","paragraphs":["夜饮东坡醒复醉，归来仿佛三更。","家童鼻息已雷鸣。","敲门都不应，倚杖听江声。","长恨此身非我有，何时忘却营营。","夜阑风静縠纹平。","小舟从此逝，江海寄馀生。"],"theme":"闲适隐逸","theme2":["哲理悟道","送别","悼亡挽歌"],"style":"婉约","style2":["豪放","沉郁"],"mood":"愁怨","mood2":["恬淡"],"scene":["夜","江"],"cats":{"抒情":["悼亡"],"山水":["江河"]},"theme_conf":0.85},{"uid":"2e0dfd8f-821c-40ce-b802-251e56eb1ed3","title":"隄上柳","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["垂柳万条丝，春来织别离。","行人攀折处，闺妾断肠时。"],"theme":"闺情宫怨","theme2":["送别"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["离别","伤感","闺怨"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.403},{"uid":"0f0fc2c7-01ca-4d6b-93b9-f41de3efca31","title":"东园玩菊","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["少年昨已去，芳岁今又阑。","如何寂莫意，复此荒凉园。","园中独立久，日澹风露寒。","秋蔬尽芜没，好树亦凋残。","唯有数丛菊，新开篱落间。","携觞聊就酌，为尔一留连。","忆我少小日，易为兴所牵。","见酒无时节，未饮已欣然。","近从年长来，渐觉取乐难。","常恐更衰老，强饮亦无欢。","顾谓尔菊花，后时何独鲜。","诚知不为我，借尔暂开颜。"],"theme":"咏物","theme2":[],"style":"冲淡","style2":["沉郁"],"mood":"欢愉","mood2":["孤寂"],"scene":["酒","园林","重阳"],"cats":{"抒情":["孤独"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"0a9b2767-706e-40b9-a423-2097e5f97d10","title":"避暑摩诃池上作","author":"后蜀嗣主孟昶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["冰肌玉骨清无汗，水殿风来暗香暖。","帘开明月独窥人，敧枕钗横云鬓乱。","起来琼户寂无声，时见疎星渡河汉。","屈指西风几时来，只恐流年暗中换。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["夏","月","园林"],"cats":{"抒情":["孤独","闺怨"],"四季":["夏天"],"天气":["月亮"],"人生":["时光"]},"theme_conf":1.0},{"uid":"321a1b75-4cdf-48c7-8f57-047300fa7f50","title":"杂曲歌辞 水调 歌第一","author":"不详","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["平沙落日大荒西，陇上明星高复低。","孤山几处看烽火，壮士连营候鼓鼙。"],"theme":"边塞征战","theme2":["山水田园"],"style":"悲慨","style2":[],"mood":"孤寂","mood2":["慷慨"],"scene":["山"],"cats":{"抒情":["孤独"],"山水":["西湖"],"人生":["战争"]},"theme_conf":0.506},{"uid":"5ceea715-909e-454c-ad89-5cda63cc119d","title":"送汤中丞和蕃","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["继好中司出，天心外国知。","已传尧雨露，更说汉威仪。","陇上应回首，河源复载驰。","孤峰问徒御，空碛见旌麾。","春草乡愁起，边城旅梦移。","莫嗟行远地，此去荅恩私。"],"theme":"送别","theme2":["羁旅思乡"],"style":"沉郁","style2":["冲淡"],"mood":"孤寂","mood2":["愁怨"],"scene":["春","雨","山"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["春天"],"山水":["黄河"]},"theme_conf":0.448},{"uid":"f6b75eb2-255e-4071-bf01-a5db4d409051","title":"孤雁","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["孤雁不饮啄，飞鸣声念群。","谁怜一片影，相失万重云。","望尽似犹见，哀多如更闻。","野鵶无意绪，鸣噪自纷纷。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["鸟"],"cats":{"抒情":["孤独"],"四季":["秋天"],"动物":["写鸟"]},"theme_conf":0.526},{"uid":"d70d3707-c751-4237-9b57-6f0e897d6c4d","title":"同陈六侍御寒食游禅定藏山上人院","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["年少轻行乐，东城南陌头。","与君寂寞意，共作草堂游。"],"theme":"节令风俗","theme2":["哲理悟道"],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["清明"],"cats":{"抒情":["孤独"],"人生":["哲理"],"节日":["寒食节","清明节"]},"theme_conf":0.62},{"uid":"f35c4d3c-1141-4821-9c39-99a480960d98","title":"留别贾严二阁老两院补阙","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["田园须𫏐往，戎马惜离群。","去远留诗别，愁多任酒醺。","一秋常苦雨，今日始无云。","山路时吹角，那堪处处闻。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["园林","楼"],"cats":{"抒情":["离别","伤感"],"生活":["田野"]},"theme_conf":1.0},{"uid":"19340af6-e25d-41c8-90fc-b465d9be1134","title":"登楼","author":"朱斌","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["白日依山尽，黄河入海流。","欲穷千里目，更上一层楼。"],"theme":"山水田园","theme2":["哲理悟道","咏史怀古"],"style":"冲淡","style2":[],"mood":"慷慨","mood2":[],"scene":["楼"],"cats":{"抒情":["怀古"],"山水":["黄河"]},"theme_conf":0.375},{"uid":"8e4f53da-0190-413d-9c18-f8043d90e2be","title":"送幽州陈参军赴任寄呈乡曲父老","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["蓟北三千里，关西二十年。","冯唐犹在汉，乐毅不归燕。","人同黄鹤远，乡共白云连。","郭隗池台处，昭王尊酒前。","故人当已老，旧壑几成田。","红颜如昨日，衰鬓似秋天。","西蜀桥应毁，东周石尚全。","灞池水犹绿，榆关月早圆。","塞云初上雁，庭树欲销蝉。","送君之旧国，挥泪独澘然。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["清新"],"mood":"孤寂","mood2":["欢愉","愁怨"],"scene":["鸟","园林","秋"],"cats":{"抒情":["友情","离别","伤感","孤独"],"四季":["秋天"],"人物":["父亲"],"生活":["写桥"]},"theme_conf":0.434},{"uid":"098ed74c-c5fa-4944-9078-b76bd958fbba","title":"春日忆家","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["自觉劳乡梦，无人见客心。","空余庭草色，日日伴愁襟。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":["孤寂","愁怨"],"scene":["春"],"cats":{"抒情":["思念","思乡","伤感","孤独"],"四季":["春天"],"天气":["太阳"]},"theme_conf":1.0},{"uid":"3f8f27c5-2e3f-42e7-8238-4be04f1e2849","title":"故人寄茶","author":"李德裕","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["劒外九华英，缄题下玉京。","开时微月上，碾处乱泉声。","半夜邀僧至，孤吟对竹烹。","碧流霞脚碎，香泛乳花轻。","六腑睡神去，数朝诗思清。","其余不敢费，留伴读书行。"],"theme":"咏物","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["花","月","夜"],"cats":{"抒情":["友情","孤独"],"人生":["读书"],"食物":["写茶"]},"theme_conf":0.88},{"uid":"eb056fbb-6fd2-4a5d-a4df-38cf4a90f587","title":"故人寄茶","author":"曹邺","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["剑外九华英，缄题下玉京。","开时微月上，碾处乱泉声。","半夜招僧至，孤吟对月烹。","碧沈霞脚碎，香泛乳花轻。","六腑睡神去，数朝诗思清。","月余不敢费，留伴肘书行。"],"theme":"咏物","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["月","花","夜"],"cats":{"抒情":["友情","孤独"],"食物":["写茶"]},"theme_conf":0.8},{"uid":"9309205e-1d08-4a7b-99ef-4a05a9ee4370","title":"过故人庄","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["故人具鸡黍，邀我至田家。","绿树村边合，青山郭外斜。","开筵面场圃，把酒话桑麻。","待到重阳日，还来就菊花。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["重阳","山"],"cats":{"抒情":["友情"],"生活":["乡村","田野"],"节日":["重阳节"]},"theme_conf":0.402},{"uid":"c5b30b4f-a9d1-4c84-8cd9-fdf6a29b7e86","title":"雪谤后书事上皇甫大夫","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["盛德总群英，高标仰国桢。","独安巡狩日，曾掩赵张名。","业就难辞宠，朝回更授兵。","晓川分牧马，夜雪覆连营。","长策威殊俗，嘉谋翊圣明。","画图规阵势，梦笔纪山行。","绶拂池中影，珂摇竹外声。","赐欢征妓乐，陪醉问公卿。","却忆经前事，翻疑得此生。","分深存没感，恩在子孙荣。","览镜愁将老，扪心喜复惊。","岂言沈族重，但觉杀身轻。","有泪沾坟典，无家集弟兄。","东西遭世难，流浪识交情。","阅古宗文举，推才慕正平。","应怜守贫贱，又欲事躬耕。"],"theme":"讽喻刺世","theme2":["山水田园","悼亡挽歌"],"style":"沉郁","style2":["婉约","豪放"],"mood":"欢愉","mood2":["愁怨"],"scene":["雪"],"cats":{"抒情":["伤感","悼亡","感恩"],"天气":["写雪"],"生活":["田野"]},"theme_conf":0.436},{"uid":"14e71d5c-ff47-4b86-b37f-f79cbfbc4796","title":"季秋江村","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["乔木村墟古，疎篱野蔓悬。","清琴将暇日，白首望霜天。","登俎黄甘重，支床锦石圆。","远游虽寂寞，难见此山川。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":["绮丽"],"mood":"孤寂","mood2":[],"scene":["秋","江"],"cats":{"抒情":["孤独"],"四季":["秋天"],"生活":["乡村"]},"theme_conf":0.75},{"uid":"cp501aea08a51a86","title":"齐天乐","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["庾郎先自吟愁赋。","凄凄更闻私语。","露湿铜铺，苔侵石井，都是曾听伊处。","哀音似诉。","正思妇无眠，起寻机杼。","曲曲屏山，夜凉独自甚情绪。","西窗又吹暗雨。","为谁频断续，相和砧杵。","候馆迎秋，离宫吊月，别有伤心无数。","豳诗漫与。","笑篱落呼灯，世间儿女。","写入琴丝，一声声更苦。"],"theme":"送别","theme2":["民生疾苦","山水田园"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["欢愉"],"scene":["夜","秋"],"cats":{"抒情":["离别","伤感"],"四季":["秋天"]},"theme_conf":0.404},{"uid":"cp5f02926940644e","title":"夜合花","author":"史达祖","dynasty":"宋","section":"宋词","form":"词","paragraphs":["柳锁莺魂，花翻蝶梦，自知愁染潘郎。","轻衫未揽，犹将泪点偷藏。","念前事，怯流光。","早春窥、酥雨池塘。","向销凝里，梅开半面，情满徐妆。","风丝一寸柔肠。","曾在歌边惹恨，烛底萦香。","芳机瑞锦，如何未织鸳鸯。","人扶醉，月依墙。","是当初、谁敢疏狂。","把闲言语，花房夜久，各自思量。"],"theme":"爱情相思","theme2":["爱情相思"],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["花","夜","春"],"cats":{"抒情":["爱情","伤感"],"四季":["春天"]},"theme_conf":0.8},{"uid":"99314a0f-cce0-4006-aaaf-1e0cb2569f89","title":"杂曲歌辞 长相思","author":"苏颋","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见天津桥下东流水，东望龙门北朝市。","杨柳青青宛地垂，桃红李白花参差。","花参差，柳堪结，此时忆君心断绝。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["花"],"cats":{"抒情":["爱情","思念"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"a65e5646-14b1-4f75-924b-bbf262b242d7","title":"玉阶怨","author":"李白","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["玉阶生白露，夜久侵罗袜。","却下水晶帘，玲珑望秋月。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["秋","夜","月"],"cats":{"抒情":["闺怨"],"四季":["秋天"]},"theme_conf":0.836},{"uid":"7545545f-e9d3-4382-a987-89262e9fd3ae","title":"题金家竹溪","author":"王建","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["少年因病离天仗，乞得归家自养身。","买断竹溪无别主，散分泉水与新邻。","山头鹿下长惊犬，池面鱼行不怕人。","乡使到来常欵语，还闻世上有功臣。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["沉郁"],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"抒情":["离别"],"植物":["竹子"]},"theme_conf":0.473},{"uid":"a05bf553-aa6e-49b8-8988-a104d0207473","title":"杂歌谣辞 古歌","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["落叶流风向玉台，夜寒秋思洞房开。","水精帘外金波下，云母窗前银汉回。","玉阶阴阴苔藓色，君王履綦难再得。","璇闺窈窕秋夜长，绣户徘徊秋月光。","燕姬彩帐芙蓉色，秦子金炉兰麝香。","北斗七星横夜半，清歌一曲断君肠。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","月","夜"],"cats":{"抒情":["闺怨"],"四季":["秋天"],"天气":["星星"]},"theme_conf":1.0},{"uid":"8981911c-da27-4a25-bffb-a8cc1aa7cdfa","title":"舞曲歌辞 独漉篇","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["独漉水中泥，水浊不见月。","不见月尚可，水深行人没。","越鸟从南来，胡鹰亦北度。","我欲弯弓向天射，惜其中道失归路。","落叶别树，飘零随风。","客无所托，悲与此同。","罗帷舒卷，似有人开。","明月直入，无心可猜。","雄劒挂壁，时时龙鸣。","不断犀象，绣涩苔生。","国耻未雪，何由成名。","神鹰梦泽，不顾鸱鸢。","为君一击，抟鹏九天。"],"theme":"边塞征战","theme2":["羁旅思乡","送别"],"style":"悲慨","style2":["绮丽"],"mood":"孤寂","mood2":[],"scene":["月"],"cats":{"抒情":["思乡","孤独"],"天气":["月亮"],"人生":["梦想"]},"theme_conf":0.425},{"uid":"d1c092e6-cdc6-43e3-a7cd-54397c4f31dd","title":"雨","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["峡云行清晓，烟雾相裴回。","风吹苍江树，雨洒石壁来。","凄凄生余寒，殷殷兼出雷。","白谷变气候，朱炎安在哉？","高鸟湿不下，居人门未开。","楚宫久已灭，幽佩为谁哀。","侍臣书王梦，赋有冠古才。","冥冥翠龙驾，多自巫山台。"],"theme":"山水田园","theme2":["咏史怀古"],"style":"清新","style2":["幽峭"],"mood":"愁怨","mood2":["悲怆"],"scene":["雨"],"cats":{"抒情":["怀古"],"天气":["写雨"]},"theme_conf":0.553},{"uid":"c51ebd5d-f16d-4042-963f-b1ff984d8689","title":"忆长安 七月","author":"陈元初","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["忆长安，七月时，槐花点散罘罳。","七夕针楼竞出，中元香供初移。","绣毂金鞍无限，游人处处归迟。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":["恬淡"],"scene":["月","七夕"],"cats":{"抒情":["思念"],"天气":["月亮"],"节日":["七夕节"]},"theme_conf":0.88},{"uid":"59063901-7dbc-4f22-974f-ddccab675cbc","title":"清平调 二","author":"李白","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["一枝红艳露凝香，云雨巫山枉断肠。","借问汉宫谁得似，可怜飞燕倚新妆。"],"theme":"闺情宫怨","theme2":["咏史怀古"],"style":"清新","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["花","雨","山"],"cats":{"抒情":["伤感","闺怨","怀古"]},"theme_conf":0.637},{"uid":"16668b6e-7a0c-4421-b374-d62a8b9c81eb","title":"真定即事奉赠韦使君二十八韵","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["飘泊怀书客，迟回此路隅。","问津惊弃置，投刺忽踟蹰。","方伯恩弥重，苍生咏已苏。","郡称廉叔度，朝议管夷吾。","乃继三台侧，仍将四岳俱。","江山澄气象，崖谷倚冰壶。","诏宠金门策，官荣叶县凫。","擢才登粉署，飞步蹑云衢。","起草徵调墨，焚香即宴娱。","光华扬盛矣，霄汉在兹乎。","隐轸推公望，逶迤协帝俞。","轩车辞魏阙，旌节副幽都。","始佩仙郎印，俄兼太守符。","尤多蜀郡理，更得颍川谟。","城邑推雄镇，山川列简图。","旧燕当绝漠，全赵对平芜。","旷野何弥漫，长亭复郁纡。","始泉遗俗近，活水战场无。","月换思乡陌，星廻记斗枢。","岁容归万象，和气发鸿罏。","沦落而谁遇，栖遑有是夫。","不才羞拥肿，干禄谢侏儒。","契阔慙行迈，羁离忆友于。","田园同季子，储蓄异陶朱。","方欲呈高义，吹嘘揖大巫。","永怀吐肝胆，犹惮阻荣枯。","解榻情何限，忘言道未殊。","从来贵缝掖，应是念穷途。"],"theme":"应制干谒","theme2":["羁旅思乡"],"style":"雄浑","style2":["清新"],"mood":"相思","mood2":[],"scene":["楼","塞外"],"cats":{"抒情":["离别","思念","思乡"],"生活":["田野"]},"theme_conf":0.95},{"uid":"cp23f78a4e960805","title":"兰陵王","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["柳阴直。","烟里丝丝弄碧。","隋堤上、曾见几番，拂水飘绵送行色。","登临望故国。","谁识。","京华倦客。","长亭路，年去岁来，应折柔条过千尺。","闲寻旧踪迹。","又酒趁哀弦，灯照离席。","梨花榆火催寒食。","愁一箭风快，半篙波暖，回头迢递便数驿。","望人在天北。","凄恻。","恨堆积。","渐别浦萦回，津堠岑寂。","斜阳冉冉春无极。","念月榭携手，露桥闻笛。","沈思前事，似梦里，泪暗滴。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["清明","酒","春"],"cats":{"抒情":["离别","伤感","怀古"],"四季":["春天"],"生活":["写桥"],"节日":["寒食节","清明节"]},"theme_conf":0.427},{"uid":"746089bc-7a9d-46f1-8ff4-7636f0403347","title":"桃源图","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["神僊有无何渺茫，桃源之说诚荒唐。","流水盘回山百转，生绡数幅垂中堂。","武陵太守好事者，题封远寄南宫下。","南宫先生忻得之，波涛入笔驱文辞。","文工画妙各臻极，异境恍惚移于斯。","架岩凿谷开宫室，接屋连墙千万日。","嬴颠刘蹶了不闻，地坼天分非所恤。","种桃处处惟开花，川原近远蒸红霞。","初来犹自念乡邑，岁久此地还成家。","渔舟之子来何所，物色相猜更问语。","大蛇中断丧前王，群马南渡开新主。","听终辞绝共凄然，自说经今六百年。","当时万事皆眼见，不知几许犹流传。","争持酒食来相馈，礼数不同樽俎异。","月明伴宿玉堂空，骨冷魂清无梦寐。","夜半金鸡啁哳鸣，火轮飞出客心惊。","人间有累不可住，依然离别难为情。","船开櫂进一回顾，万里苍苍烟水暮。","世俗宁知伪与真，至今传者武陵人。"],"theme":"题画咏艺","theme2":["山水田园","送别"],"style":"豪放","style2":["绮丽","清新"],"mood":"欢愉","mood2":[],"scene":["酒","舟","山","夜"],"cats":{"抒情":["离别"],"植物":["桃花"]},"theme_conf":0.301},{"uid":"1ce94bde-41ec-42b8-abef-e1e1be55be7c","title":"贼退示官吏","author":"元结","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔岁逢太平，山林二十年。","泉源在庭户，洞壑当门前。","井税有常期，日[晏]犹得眠。","忽然遭世变，数岁亲戎旃。","今来典斯郡，山夷又纷然。","城小贼不屠，人贫伤可怜。","是以陷隣境，此州独见全。","使臣将王命，岂不如贼焉。","今彼徴敛者，迫之如火煎。","谁能绝人命，以作时世贤。","思欲委符节，引竿自刺船。","将家就鱼麦，归老江湖边。"],"theme":"民生疾苦","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["山","江"],"cats":{"抒情":["孤独"]},"theme_conf":0.531},{"uid":"9185b303-813a-493d-ae09-5d4979cd90ef","title":"杂曲歌辞 古离别","author":"僧贯休","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["离恨如旨酒，古今饮皆醉。","只恐长江水，尽是儿女泪。","伊余非此辈，送人空把臂。","他日再相逢，清风动天地。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["豪放"],"mood":"愁怨","mood2":["孤寂"],"scene":["江","酒"],"cats":{"抒情":["离别","伤感"],"山水":["长江"]},"theme_conf":0.691},{"uid":"a2b4e8ca-92e3-4101-8a54-739b8f1d8184","title":"辋川闲居赠裴秀才迪","author":"王维","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["寒山转苍翠，秋水日潺湲。","倚杖柴门外，临风听暮蝉。","渡头余落日，墟里上孤烟。","复值接舆醉，狂歌五柳前。"],"theme":"山水田园","theme2":["送别"],"style":"豪放","style2":["沉郁"],"mood":"恬淡","mood2":["孤寂"],"scene":["秋"],"cats":{"抒情":["孤独"],"四季":["秋天"]},"theme_conf":0.82},{"uid":"b19965c5-9574-43ff-9158-2f61b6a3fde7","title":"酬王季友题半日村别业兼呈李明府","author":"郎士元","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["村映寒原日已斜，烟生密竹早归鸦。","长溪南路当群岫，半景东隣照数家。","门通小径连芳草，马饮春泉踏浅沙。","欲待主人林上月，还思潘岳县中花。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["冬","花"],"cats":{"抒情":["友情","离别"],"天气":["太阳"],"生活":["乡村"]},"theme_conf":0.49},{"uid":"1b0eb975-d6fd-4b70-b6e6-a8ee5bbd6563","title":"同群公题郑少府田家","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["郑侯应凄惶，五十头尽白。","昔为南昌尉，今作东郡客。","与语多远情，论心知所益。","秋林既清旷，穷巷空淅沥。","蝶舞园更闲，鸡鸣日云夕。","男儿未称意，其道固无适。","劝君且杜门，勿叹人事隔。"],"theme":"寄赠酬答","theme2":["民生疾苦","羁旅思乡","咏物"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":["愁怨"],"scene":["秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"生活":["田野"]},"theme_conf":0.85},{"uid":"bce40ff4-816c-490c-be30-04de15f7c25e","title":"题金陵渡","author":"张祜","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["金陵津渡小山楼，一宿行人自可愁。","潮落夜江斜月里，两三星火是瓜州。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["江","楼","夜","月"],"cats":{"抒情":["伤感","怀古"]},"theme_conf":0.701},{"uid":"bf5f4147-1e1c-4bb6-84ab-0e6a6a402325","title":"相和歌辞 公无渡河","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["黄河西来决崐崘，咆吼万里触龙门。","波滔天，尧咨嗟。","大禹理百川，儿啼不窥家。","杀湍湮洪水，九州始蚕麻。","其害乃去，茫然风沙。","被发之叟狂而痴，清晨径流欲奚为。","旁人不惜妻止之，公无渡河苦渡之。","虎可搏，河难凭。","公果溺死流海湄，有长鲸白齿若雪山。","公乎公乎，挂骨于其间，箜篌所悲竟不还。"],"theme":"民生疾苦","theme2":["题画咏艺","山水田园"],"style":"豪放","style2":[],"mood":"悲怆","mood2":[],"scene":["江","雪"],"cats":{"抒情":["伤感"],"山水":["江河","黄河"]},"theme_conf":0.37},{"uid":"72f577cd-8974-4e77-810b-731a0c7d5e2c","title":"隋堤柳","author":"李山甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["曾傍龙舟拂翠华，至今凝恨倚天涯。","但经春色还秋色，不觉杨家是李家。","背日古阴从北朽，逐波疎影向南斜。","年年只有晴风便，遥为雷塘送雪花。"],"theme":"羁旅思乡","theme2":["送别","咏物"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["端午","雪","舟","春","秋"],"cats":{"抒情":["思乡"],"四季":["春天","秋天"],"节日":["端午节"],"植物":["柳树"]},"theme_conf":0.374},{"uid":"cp9847b8d59c45f5","title":"夜半乐","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["冻云黯淡天气，扁舟一叶，乘兴离江渚。","渡万壑千岩，越溪深处。","怒涛渐息，樵风乍起，更闻商旅相呼。","片帆高举。","泛画鹢、翩翩过南浦。","望中酒旆闪闪，一簇烟村，数行霜树。","残日下，渔人鸣榔归去。","败荷零落，衰杨掩映，岸边两两三三，浣沙游女。","避行客、含羞笑相语。","到此因念，绣阁轻抛，浪萍难驻。","叹后约丁宁竟何据。","惨离怀，空恨岁晚归期阻。","凝泪眼、杳杳神京路。","断鸿声远长天暮。"],"theme":"山水田园","theme2":["羁旅思乡","送别"],"style":"沉郁","style2":["冲淡"],"mood":"欢愉","mood2":["愁怨"],"scene":["舟","夜","山"],"cats":{"抒情":["离别","思乡","伤感"]},"theme_conf":0.365},{"uid":"7a97a451-d5e0-4de9-8762-7ccdf64773dd","title":"杂曲歌辞 少年行三首 三","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["马上谁家白面郎，临阶下马坐人床。","不通姓字麄豪甚，指点银瓶索酒尝。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["酒"],"cats":{"抒情":["思乡"],"人生":["青春"]},"theme_conf":1.0},{"uid":"f8afed4e-e8cd-467f-afae-51dc149921f7","title":"夏日南亭怀辛大","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["山光忽西落，池月渐东上。","散发乘夕凉，开轩卧闲敞。","荷风送香气，竹露滴清响。","欲取鸣琴弹，恨无知音赏。","感此怀故人，中宵劳梦想。"],"theme":"送别","theme2":["闲适隐逸"],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["夏"],"cats":{"抒情":["友情"],"四季":["夏天"]},"theme_conf":0.467},{"uid":"065c182e-76f5-4777-b84e-e80651f509df","title":"女耕田行","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["乳燕入巢笋成竹，谁家二女种新谷。","无人无牛不及犁，持刀斫地翻作泥。","自言家贫母年老，长兄从军未娶嫂。","去年灾疫牛囤空，截绢买刀都市中。","头巾掩面畏人识，以刀代牛谁与同。","姊妹相携心正苦，不见路人唯见土。","疏通畦陇防乱苗，整顿沟塍待时雨。","日正南冈下饷归，可怜朝雉扰惊飞。","东邻西舍花发尽，共惜余芳泪满衣。"],"theme":"山水田园","theme2":["边塞征战"],"style":"沉郁","style2":["冲淡","清新"],"mood":"孤寂","mood2":["愁怨"],"scene":["花"],"cats":{"抒情":["伤感","孤独"],"生活":["田野"]},"theme_conf":0.418},{"uid":"afb30a8c-345b-471d-bf80-9f1828f8e097","title":"横吹曲辞 折杨柳","author":"张祜","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["红粉青楼曙，垂杨仲月春。","怀君重攀折，非妾妒腰身。","舞带萦丝断，娇娥向叶嚬。","横吹凡几曲，独自最愁人。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["春","楼","月"],"cats":{"抒情":["伤感","孤独","闺怨"],"四季":["春天"],"植物":["柳树"]},"theme_conf":1.0},{"uid":"495e6bc4-42a4-463e-ac80-b4fa4a6ea878","title":"杂曲歌辞 远别离","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["远别离，古有皇英之二女，乃在洞庭之南，潇湘之浦。","海水直下万里深，谁人不言此离苦。","日惨惨兮云冥冥，猩猩啼烟兮鬼啸雨。","我纵言之将何补，皇穹窃恐不照余之忠诚。","雷冯冯兮欲吼怒，尧舜当之亦禅禹。","君失臣兮龙为鱼，权归臣兮鼠变虎。","或云尧幽囚，舜野死，九疑联緜皆相似，重瞳孤坟竟何是。","帝子泣兮绿云间，随风波兮去无还。","恸哭兮远望，见苍梧之深山。","苍梧山崩湘水绝，竹上之泪乃可灭。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["豪放"],"mood":"悲怆","mood2":["愁怨"],"scene":["江","山"],"cats":{"抒情":["离别","伤感","悼亡"]},"theme_conf":0.516},{"uid":"cca28bc8-2689-4419-bf3b-e5fef10f5db5","title":"横吹曲辞 长安道","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["花枝缺处青楼开，艳歌一曲酒一杯。","美人劝我急行乐，自古朱颜不再来。","君不见外州客，长安道，一回来，一回老。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"恬淡","mood2":[],"scene":["酒"],"cats":{"抒情":["思乡"],"人物":["女子"]},"theme_conf":0.65},{"uid":"82821220-44e6-465e-ae73-68f04886604a","title":"琴曲歌辞 白雪歌","author":"僧贯休","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["列鼎佩金章，泪眼看风枝。","却思食藜藿，身作屠沽儿。","负米无远近，所希升斗归。","为人无贵贱，莫学鸡狗肥。","斯言如不忘，别更无光辉。","斯言如或忘，即安用人为。"],"theme":"讽喻刺世","theme2":["送别"],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["雪"],"cats":{"抒情":["伤感"],"天气":["写雪"]},"theme_conf":0.72},{"uid":"3bb3897a-7460-40d1-9ec3-b4738e3f20b4","title":"忆春日太液池亭候对","author":"李绅","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["宫莺报晓瑞烟开，三岛灵禽拂水回。","桥转彩虹当绮殿，舰浮花鹢近蓬莱。","草承香辇王孙长，桃艳仙颜阿母栽。","簪笔此时方侍从，却思金马笑邹枚。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思念"],"四季":["春天"],"天气":["彩虹"],"人物":["母亲"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"eac61312-dec6-4712-a34a-9a71969af9d5","title":"相和歌辞 采莲曲三首 二","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["荷叶罗裙一色裁，芙蓉向脸两边开。","乱入池中看不见，闻歌始觉有人来。"],"theme":"爱情相思","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["思念"],"植物":["荷花"]},"theme_conf":0.546},{"uid":"59c7eaa9-3c05-4857-8cff-10376706ccb9","title":"月夜","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["今夜鄜州月，闺中只独看。","遥怜小儿女，未解忆长安。","香雾云鬟湿，清辉玉臂寒。","何时倚虚幌，双照泪痕干。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["月"],"cats":{"抒情":["思念","孤独","闺怨"],"天气":["月亮"],"人物":["儿童"]},"theme_conf":0.705},{"uid":"8a851893-3a56-4c0c-8252-ab34c95847ed","title":"德宗皇帝挽歌词四首 一","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["执象宗玄祖，贻谋启孝孙。","文高柏梁殿，礼薄霸陵原。","宫仗辞天阙，朝仪出国门。","生成不可报，二十七年恩。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":[],"cats":{"抒情":["悼亡"],"人物":["老师"]},"theme_conf":0.99},{"uid":"cpbeb305cfba39a6","title":"贺新郎","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["凤尾龙香拨。","自开元、霓裳曲罢，几番风月。","最苦浔阳江头客，画舸亭亭待发。","记出塞、黄云堆雪。","马上离愁三万里，望昭阳、宫殿孤鸿没。","弦解语，恨难说。","辽阳驿使音尘绝。","琐窗寒、轻拢慢拈，泪珠盈睫。","推手含情还却手，一抹梁州哀彻。","千古事、云飞烟灭。","贺老定场无消息，想沈香亭北繁华歇。","弹到此，为呜咽。"],"theme":"羁旅思乡","theme2":["边塞征战","闺情宫怨"],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["塞外","雪"],"cats":{"抒情":["思乡","伤感","闺怨"],"生活":["边塞"]},"theme_conf":0.392},{"uid":"cp7622937b715c55","title":"渡江云三犯・渡江云","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["羞红颦浅恨，晚风为落，片绣点重茵。","旧堤分燕尾，桂棹轻鸥，宝勒倚残云。","千丝怨碧，渐路入、仙坞迷津。","肠漫回，隔花时见，背面楚腰身。","逡巡。","题门惆怅，堕履牵萦，数幽期难准。","还始觉、留情缘眼，宽带因春。","明朝事与孤烟冷，做满湖、风雨愁人。","山黛暝，尘波澹绿无痕。"],"theme":"山水田园","theme2":["闺情宫怨"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["江","雨"],"cats":{"抒情":["伤感","闺怨"],"天气":["写云"]},"theme_conf":0.522},{"uid":"7734c93d-ef83-4857-abc1-07708e9099b3","title":"听旧宫中乐人穆氏唱歌","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["曾随织女渡天河，记得云间第一歌。","休唱贞元供奉曲，当时朝士已无多。"],"theme":"咏史怀古","theme2":[],"style":"旷达","style2":[],"mood":"欢愉","mood2":[],"scene":["七夕"],"cats":{"抒情":["怀古"],"节日":["七夕节"]},"theme_conf":1.0},{"uid":"888e21ea-f3bc-4453-83b8-2048410e3b91","title":"杂曲歌辞 蓟门行","author":"李希仲","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["旄头有精芒，胡骑猎秋草。","羽檄南渡河，边庭用兵早。","汉家爱征战，宿将今已老。","辛苦羽林儿，从戎榆关道。","一身救边速，烽火连蓟门。","前军鸟飞断，格鬬尘沙昏。","寒日鼓声急，单于夜火奔。","当须徇忠义，身死报国恩。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":["孤寂","悲怆"],"scene":["秋","夜"],"cats":{"抒情":["爱国"],"四季":["秋天"],"人生":["战争"]},"theme_conf":0.864},{"uid":"c53ae26b-4d36-4eaa-9ff4-004c922bee79","title":"梦寻西山准上人","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["别处秋泉声，至今犹在耳。","何尝梦魂去，不见雪山子。","新月隔林时，千峰翠微里。","言忘心更寂，迹灭云自起。","觉来缨上尘，如洗功德水。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["山"],"cats":{"抒情":["思念"],"人生":["梦想"]},"theme_conf":0.561},{"uid":"cpbf70c4f59e5765","title":"雨霖铃","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["寒蝉凄切。","对长亭晚，骤雨初歇。","都门帐饮无绪，留恋处、兰舟催发。","执手相看泪眼，竟无语凝噎。","念去去、千里烟波，暮霭沈沈楚天阔。","多情自古伤离别。","更那堪、冷落清秋节。","今宵酒醒何处，杨柳岸、晓风残月。","此去经年，应是良辰、好景虚设。","便纵有、千种风情，更与何人说。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["婉约","清新"],"mood":"愁怨","mood2":[],"scene":["雨"],"cats":{"抒情":["离别","伤感"],"天气":["写雨"]},"theme_conf":1.0},{"uid":"883fcd05-a7b4-40f8-8cbe-5d93d4fad76c","title":"冬日洛城北谒玄元皇帝庙","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["配极玄都閟，凭虚禁御长。","守祧严具礼，掌节镇非常。","碧瓦初寒外，金茎一气旁。","山河扶绣户，日月近雕梁。","仙李盘根大，猗兰奕叶光。","世家遗旧史，道德付今王。","画手看前辈，吴生远擅场。","森罗移地轴，妙绝动宫墙。","五圣联龙衮，千官列雁行。","冕旒俱秀发，旌斾尽飞扬。","翠柏深留景，红棃迥得霜。","风筝吹玉柱，露井冻银床。","身退卑周室，经传拱汉皇。","谷神如不死，养拙更何乡。"],"theme":"佛道禅颂","theme2":["咏史怀古","民生疾苦","应制干谒"],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["冬"],"cats":{"抒情":["怀古"],"四季":["冬天"],"天气":["太阳"]},"theme_conf":0.9},{"uid":"0d73235b-89f8-4e98-87bc-fe4ce5d21836","title":"观卫尚书九日对中使射破的","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["盛宴倾黄菊，殊私降紫泥。","月营开射圃，霜斾拂晴霓。","出将三朝贵，弯弓五善齐。","腕回金镞满，的破绿弦低。","勇气干牛斗，欢声震鼓鼙。","忠臣思报国，更欲取关西。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":["慷慨"],"scene":["重阳"],"cats":{"抒情":["爱国"],"节日":["重阳节"]},"theme_conf":0.84},{"uid":"6e27c564-356b-4c7b-8594-861f03d55cfc","title":"武陵书怀五十韵","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["西汉开支郡，南朝号戚藩。","四封当列宿，百雉俯清沅。","高岸朝霞合，惊湍激箭奔。","积阴春暗度，将霁雾先昏。","俗尚东皇祀，谣传义帝冤。","桃花迷隐迹，楝叶慰忠魂。","户算资渔猎，乡豪恃子孙。","照山畬火动，踏月俚歌喧。","拥檝舟为市，连甍竹覆轩。","披沙金粟见，拾羽翠翘翻。","茗折苍溪秀，苹生枉渚暄。","禽惊格磔起，鱼戏𪡋喁繁。","沈约台榭故，李衡墟落存。","湘灵悲鼓瑟，泉客泣酬恩。","露变蒹葭浦，星悬橘柚村。","虎咆空野震，鼍作满川浑。","邻里皆迁客，儿童习左言。","炎天无冽井，霜月见芳荪。","清白家传远，诗书志所敦。","列科叨甲乙，从宦出丘樊。","结友心多契，驰声气尚吞。","士安曾重赋，元礼许登门。","草檄嫖姚幕，巡兵戊己屯。","筑台先自隗，送客独留髠。","遂结王畿绶，来观衢室罇。","鸢飞入鹰隼，鱼目俪玙璠。","晓烛罗驰道，朝阳辟帝阍。","王正会夷夏，月朔盛旗旛。","独立当瑶阙，传呵步紫垣。","按章清犴狱，视祭洁苹蘩。","御历昌期远，传家宝祚蕃。","繇文光夏启，神教畏轩辕。","内禅因天性，雄图授化元。","继明悬日月，出震统乾坤。","大孝三朝备，洪恩九族惇。","百川宗渤澥，五岳辅昆仑。","何幸逢休运，微班识至尊。","校𦈏资筦榷，复土奉山园。","一失贵人意，徒闻太学论。","直庐辞锦帐，远守愧朱幡。","巢幕方犹燕，抢榆尚笑鲲。","邅回过荆楚，流落感凉温。","旅望花无色，愁心醉不惛。","春江千里草，暮雨一声猿。","问卜安冥数，看方理病源。","带赊衣改制，尘涩劒成痕。","三秀悲中散，二毛伤虎贲。","来忧御魑魅，归愿牧鸡豚。","就日秦京远，临风楚奏烦。","南登无灞岸，旦夕上高原。"],"theme":"羁旅思乡","theme2":["山水田园","送别"],"style":"绮丽","style2":["清新","雄浑"],"mood":"悲怆","mood2":["愁怨","孤寂"],"scene":["夏","江","楼","花"],"cats":{"抒情":["友情","思乡","伤感","孤独"],"四季":["夏天"],"天气":["太阳"],"人物":["儿童"],"人生":["读书"],"植物":["桃花"]},"theme_conf":0.239},{"uid":"45e01605-620b-4b86-acd4-02e10ae12e89","title":"东亭茶宴","author":"鲍氏君徽","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["闲朝向晓出帘栊，茗宴东亭四望通。","远眺城池山色里，俯聆弦管水声中。","幽篁引沼新抽翠，芳槿低檐欲吐红。","坐久此中无限兴，更怜团扇起清风。"],"theme":"闲适隐逸","theme2":[],"style":"清新","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["楼","花"],"cats":{"抒情":["闺怨"],"食物":["写茶"]},"theme_conf":0.88},{"uid":"8aa34b2b-7216-41a4-8453-892834425b91","title":"登秦岭作时陷贼归国","author":"储光羲","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["朝出猛兽林，躨跜登高峰。","僮仆履云雾，随我行太空。","羲和舒灵晖，倏忽西极通。","回首望泾渭，隐隐如长虹。","九逵合苍芜，五陵遥瞳蒙。","鹿游大明殿，雾湿华清宫。","网罗蠛蠓时，顾齿熊罴锋。","失途走江汉，不能有其功。","气逐招遥星，魂随阊阖风。","惟言宇宙清，复使车书同。","林木被繁霜，合沓连山红。","鹏鹗励羽翼，俯视荆棘丛。","誓将食鸧鸮，然后归崆峒。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":["山"],"cats":{"抒情":["怀古"],"天气":["彩虹"]},"theme_conf":0.466},{"uid":"b3415e02-0a13-47d3-8ba2-e33bc0e079b1","title":"云安九日郑十八携酒陪诸公宴","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["寒花开已尽，菊蘂独盈枝。","旧摘人频异，轻香酒𫏐随。","地偏初衣裌，山拥更登危。","万国皆戎马，酣歌泪欲垂。"],"theme":"节令风俗","theme2":[],"style":"豪放","style2":["婉约"],"mood":"欢愉","mood2":["孤寂","恬淡"],"scene":["酒","重阳"],"cats":{"抒情":["孤独"],"节日":["重阳节"],"食物":["写酒"]},"theme_conf":0.78},{"uid":"c680a907-39d1-4968-b638-3bdb6c97eb9b","title":"相和歌辞 燕歌行","author":"陶翰","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["请君留楚调，听我吟燕歌。","家在辽水头，边风意气多。","出身为汉将，正值戎未和。","雪中凌天山，冰上渡交河。","大小百余战，封侯竟蹉跎。","归来霸陵下，故旧无相过。","雄劒委尘匣，空门唯雀罗。","玉𥮾还赵女，宝瑟付齐娥。"],"theme":"边塞征战","theme2":["羁旅思乡","哲理悟道"],"style":"清新","style2":["绮丽"],"mood":"慷慨","mood2":[],"scene":["鸟","冬"],"cats":{"抒情":["思乡"],"人生":["战争"],"动物":["写鸟"]},"theme_conf":0.403},{"uid":"7f86f129-519b-46fd-a95f-b9f1f29c352d","title":"友人山中梅花","author":"殷尧藩","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["南国看花动远情，沈郎诗苦瘦容生。","铁心自儗山中赋，玉笛谁将月下横。","临水一枝春占早，照人千树雪同清。","好风吹醒罗浮梦，莫听空林翠羽声。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["山","花","冬"],"cats":{"抒情":["友情"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"dddc5861-5ad3-438a-999e-f068b10fc886","title":"夜别韦司士得城字","author":"高适","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["高馆张灯酒复清，夜钟残月雁归声。","只言啼鸟堪求侣，无那春风欲送行。","黄河曲里沙为岸，白马津边柳向城。","莫怨他乡暂离别，知君到处有逢迎。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["夜","酒"],"cats":{"抒情":["离别"],"山水":["黄河"]},"theme_conf":0.713},{"uid":"f3a62c39-2698-4d68-842f-a9ff595faa85","title":"题缑山王子晋庙","author":"郑畋","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["有昔灵王子，吹笙溯泬㵳。","六宫攀不住，三岛去相招。","亡国原陵古，宾天岁月遥。","无蹊窥海曲，有庙访山椒。","石帐龙蛇拱，云栊彩翠销。","露坛装琬琰，真像写松乔。","珠馆青童宴，琳宫阿母朝。","气舆仙女侍，天马吏兵调。","湘妓红丝瑟，秦郎白管箫。","西城要绰约，南岳命娇娆。","句曲觞金洞，天台啸石桥。","晚花珠弄蘂，春茹玉生苗。","二景神光秘，三元宝箓饶。","雾垂鸦翅发，冰束虎章腰。","鹤驭争衔箭，龙妃合献绡。","衣从星渚浣，丹就日宫烧。","物外花尝满，人间叶自凋。","望台悲汉戾，阅水笑梁昭。","古殿香残炧，荒堦柳长条。","几曾期七日，无复降重霄。","嵩岭连天汉，伊澜入海潮。","何由得真诀，使我珮环飘。"],"theme":"山水田园","theme2":["咏物","游仙梦幻"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":["悲怆"],"scene":["山"],"cats":{"抒情":["伤感"],"人物":["母亲"],"生活":["写桥"]},"theme_conf":0.418},{"uid":"228c87f2-092b-411b-9029-c5454cc2cb1c","title":"颂古三十二首  其二三","author":"释明辩","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["打起黄莺儿，莫教枝上啼。","几回惊妾梦，不得到辽西。"],"theme":"闺情宫怨","theme2":["哲理悟道"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["闺怨"]},"theme_conf":0.497},{"uid":"39fdb908-0035-476f-b871-31447e4f7af1","title":"奉和元丞侍从游南城别业","author":"李端","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["垂朱领孙子，从宴在池塘。","献寿回龟顾，和羹跃鲤香。","高松先草晚，平石助泉凉。","余橘期相及，门生有陆郎。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"抒情":["离别"],"人物":["老师"]},"theme_conf":0.93},{"uid":"49ba8a46-b588-44fe-8415-e86c3bd6e61e","title":"九日登梓州城","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["客心惊暮序，宾雁下襄州。","共赏重阳节，言寻戏马游。","湖风秋戍柳，江雨暗山楼。","且酌东篱菊，聊祛南国愁。"],"theme":"节令风俗","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["重阳"],"cats":{"抒情":["伤感"],"节日":["重阳节"]},"theme_conf":0.95},{"uid":"a1bfef77-89cd-4e38-90b7-bc41784d58de","title":"书灵筵手巾","author":"后主煜","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["浮生共顦顇，壮岁失婵娟。","汗手遗香渍，痕眉染黛烟。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"慷慨","mood2":[],"scene":["中秋"],"cats":{"抒情":["闺怨"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"dd4808c5-cefb-4840-8782-a1636acc9856","title":"琴曲歌辞 走马引","author":"李贺","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["我有辞乡劒，玉锋堪截云。","襄阳走马客，意气自生春。","朝嫌劒光静，暮嫌劒花冷。","能持劒向人，不解持照身。"],"theme":"羁旅思乡","theme2":["闲适隐逸"],"style":"沉郁","style2":[],"mood":"慷慨","mood2":["恬淡"],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"动物":["写马"]},"theme_conf":0.612},{"uid":"2b87015d-2a4a-4fa7-af5e-fe7cebc4a99f","title":"杂曲歌辞 长相思","author":"张继","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["辽阳望河县，白首无由见。","海上珊瑚枝，年年寄春燕。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["爱情","思念"],"四季":["春天"]},"theme_conf":0.704},{"uid":"4af86c76-18b3-4069-be90-6d8cef430bc7","title":"登金陵凤凰台","author":"李白","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["凤凰台上凤凰游，凤去台空江自流。","吴宫花草埋幽径，晋代衣冠成古丘。","三山半落青天外，二水中分白鹭洲。","总为浮云能蔽日，长安不见使人愁。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["楼","江"],"cats":{"抒情":["伤感","怀古"]},"theme_conf":0.867},{"uid":"8ea76149-dd97-4cd4-9564-7595c9df1506","title":"登润州芙蓉楼","author":"崔峒","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["上古人何在，东流水不归。","往来潮有信，朝暮事成非。","烟树临沙静，云帆入海稀。","郡楼多逸兴，良牧谢玄晖。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"恬淡","mood2":[],"scene":["楼"],"cats":{"抒情":["怀古"],"植物":["荷花"]},"theme_conf":1.0},{"uid":"22923091-18da-429d-9ef1-6b367fd74b1a","title":"杂曲歌辞 游子吟","author":"孟郊","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["慈母手中线，游子身上衣。","临行密密缝，意恐迟迟归。","谁言寸草心，报得三春晖。"],"theme":"亲情","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"抒情":["感恩"],"四季":["春天"],"人物":["母亲"]},"theme_conf":0.845},{"uid":"7ccd9915-51a1-4748-9989-af243036455b","title":"琴曲歌辞 列女操","author":"孟郊","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["梧桐相待老，鸳鸯会双死。","贞妇贵徇夫，舍生亦如此。","波澜誓不起，妾心井中水。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"慷慨","mood2":["悲怆","欢愉"],"scene":[],"cats":{"抒情":["闺怨"]},"theme_conf":0.49},{"uid":"bbcf126a-4653-4297-8d15-52e894fcaaf4","title":"琴曲歌辞  秋思二首 二","author":"王涯","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["宫连太液见苍波，暑气微清秋意多。","一夜轻风苹末起，露珠翻尽满池荷。"],"theme":"闺情宫怨","theme2":[],"style":"清新","style2":["婉约"],"mood":"相思","mood2":[],"scene":["秋","夏"],"cats":{"抒情":["闺怨"],"四季":["夏天","秋天"]},"theme_conf":0.6},{"uid":"28426bd8-902d-435d-887c-9ad55874c0a7","title":"咏史诗 汴水","author":"胡曾","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["千里长河一旦开，亡隋波浪九天来。","锦帆未落干戈起，惆怅龙舟更不回。"],"theme":"咏史怀古","theme2":["咏物"],"style":"绮丽","style2":["雄浑"],"mood":"惆怅","mood2":[],"scene":["舟","端午"],"cats":{"抒情":["怀古"],"节日":["端午节"]},"theme_conf":0.49},{"uid":"cpffa9ae8e43982f","title":"法曲献仙音","author":"王沂孙","dynasty":"宋","section":"宋词","form":"词","paragraphs":["层绿峨峨，纤琼皎皎，倒压波痕清浅。","过眼年华，动人幽意，相逢几番春换。","记唤酒寻芳处，盈盈褪妆晚。","已销黯。","况凄凉、近来离思，应忘却、明月夜深归辇。","荏苒一枝春，恨东风、人似天远。","纵有残花，洒征衣、铅泪都满。","但殷勤折取，自遣一襟幽怨。"],"theme":"咏物","theme2":["游仙梦幻"],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["春","月","花"],"cats":{"抒情":["伤感"],"四季":["春天"],"天气":["月亮"]},"theme_conf":0.8},{"uid":"14316b5b-cba2-41e0-84bd-3c3ed0c02407","title":"过华清宫绝句三首 一","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["长安回望绣成堆，山顶千门次第开。","一骑红尘妃子笑，无人知是荔枝来。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":["清新"],"mood":"孤寂","mood2":["欢愉"],"scene":["山"],"cats":{"抒情":["孤独","怀古"],"食物":["荔枝"]},"theme_conf":1.0},{"uid":"fae577a5-da28-4672-83ff-94c97ae2a4a4","title":"晚次鄂州","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["云开远见汉阳城，犹是孤帆一日程。","估客昼眠知浪静，舟人夜语觉潮生。","三湘衰鬓逢秋色，万里归心对月明。","旧业已随征战尽，更堪江上鼓鼙声。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"冲淡","style2":["豪放"],"mood":"孤寂","mood2":["恬淡"],"scene":["舟","江","夜"],"cats":{"抒情":["思乡","孤独"],"人生":["战争"]},"theme_conf":0.412},{"uid":"9a2c1932-4219-483b-a14b-52dc7265f6fb","title":"同李太守登历下古城员外新亭亭对鹊湖","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["新亭结搆罢，隐见清湖阴。","迹籍台观旧，气溟海岳深。","圆荷想自昔，遗堞感至今。","芳宴此时具，哀丝千古心。","主称寿尊客，筵秩宴北林。","不阻蓬荜兴，得兼梁甫吟。"],"theme":"山水田园","theme2":["咏史怀古","悼亡挽歌"],"style":"清新","style2":[],"mood":"欢愉","mood2":["悲怆"],"scene":["楼","江"],"cats":{"抒情":["悼亡","怀古"],"动物":["写鸟"]},"theme_conf":0.353},{"uid":"c89b78bc-576e-40b0-923d-916d181cf73d","title":"归梦","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["道路时通塞，江山日寂寥。","偷生唯一老，伐叛已三朝。","雨急青枫暮，云深黑水遥。","梦归归未得，不用楚辞招。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["雄浑"],"mood":"相思","mood2":["孤寂"],"scene":["塞外","雨","江","山"],"cats":{"抒情":["思乡"],"人生":["梦想"]},"theme_conf":0.627},{"uid":"ae33fbbe-2f0e-4a1f-b2de-af3fd985ed3b","title":"寄郑员外","author":"张继","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["经月愁闻雨，新年苦忆君。","何时共登眺，整屐待晴云。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["月","雨"],"cats":{"抒情":["思念","伤感"],"节日":["春节"]},"theme_conf":0.97},{"uid":"c480c5e2-1052-4bdc-9fca-44d38c5a2fda","title":"相和歌辞 从军行二首 二","author":"李白","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["百战沙场碎铁衣，城南已合数重围。","突营射杀呼延将，独领残兵千骑归。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":[],"cats":{"抒情":["孤独"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.909},{"uid":"918eefe5-fd66-441d-ac06-01ad799fb485","title":"绛州过夏留献郑尚书","author":"韦庄","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["朝朝沈醉引金船，不觉西风满树蝉。","光景暗消银烛下，梦魂长寄玉轮边。","因循每被时流诮，奋发须由国士怜。","明月客肠何处断，绿槐风里独扬鞭。"],"theme":"应制干谒","theme2":["应制干谒","送别","羁旅思乡"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["夏","月"],"cats":{"抒情":["思乡","孤独"],"四季":["夏天"],"天气":["月亮"],"人生":["励志"]},"theme_conf":0.95},{"uid":"67c18ea1-db49-44b5-8b21-6176e4a86416","title":"送李端","author":"严维","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["故关衰草遍，离别正堪悲。","路出寒云外，人归暮雪时。","少孤为客早，多难识君迟。","揜泣空相向，风尘何所期。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["悲慨"],"mood":"悲怆","mood2":["孤寂","愁怨"],"scene":["冬"],"cats":{"抒情":["离别","伤感","孤独"]},"theme_conf":0.866},{"uid":"8e6ba3fd-d983-4950-9fec-8e55331d0c09","title":"海上诗送薛文学归海东","author":"刘眘虚","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["何处归且远，送君东悠悠。","沧溟千万里，日夜一孤舟。","旷望绝国所，微茫天际愁。","有时近仙境，不定若梦游。","或见青色古，孤山百里秋。","前心方杳眇，后路劳夷犹。","离别惜吾道，风波敬皇休。","春浮花气远，思逐海水流。","日暮骊歌后，永怀空沧洲。"],"theme":"送别","theme2":[],"style":"豪放","style2":["沉郁","冲淡"],"mood":"孤寂","mood2":["相思","愁怨"],"scene":["舟","秋","春","夜"],"cats":{"抒情":["离别","伤感","孤独"],"四季":["春天","秋天"],"山水":["西湖"]},"theme_conf":0.66},{"uid":"d4c03bc1-0596-4177-88ba-e42a97b0a7d9","title":"鼓吹曲辞 君马黄","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["君马黄，我马白。","马色虽不同，人心本无隔。","共作游冶盘，双行洛阳陌。","长劒既照曜，高冠何赩赫。","各有千金裘，俱为五侯客。","猛虎落陷穽，壮夫时屈厄。","相知在急难，独好亦何益。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"慷慨","mood2":["孤寂"],"scene":[],"cats":{"抒情":["孤独"],"动物":["写马"]},"theme_conf":0.65},{"uid":"f1496cf4-4f85-4f9e-9e0e-dd05370641d3","title":"古意","author":"李颀","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["男儿事长征，少小幽燕客。","赌胜马蹄下，由来轻七尺。","杀人莫敢前，须如猬毛磔。","黄云陇底白雪飞，未得报恩不能归。","辽东小妇年十五，惯弹琵琶解歌舞。","今为羗笛出塞声，使我三军泪如雨。"],"theme":"边塞征战","theme2":[],"style":"婉约","style2":["豪放"],"mood":"愁怨","mood2":[],"scene":["塞外","雪","雨"],"cats":{"抒情":["伤感"],"生活":["边塞"]},"theme_conf":0.632},{"uid":"7b028d90-1546-4874-9888-1c57a3f3cb2d","title":"相和歌辞 东武吟","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["好古笑流俗，素闻贤达风。","方希佐明主，长揖辞成功。","白日在高天，回光烛微躬。","恭承凤皇诏，歘起云萝中。","清切紫霄迥，优游丹禁通。","君王赐颜色，声价凌烟虹。","乘舆拥翠盖，扈从金城东。","宝马丽绝景，锦衣入新丰。","倚岩望松雪，对酒鸣丝桐。","因学扬子云，献赋甘泉宫。","天书美片善，清芬播无穷。","归来入咸阳，谈笑皆王公。","一朝去金马，飘落成飞蓬。","宾友日疎散，玉尊亦已空。","才力犹可倚，不慙世上雄。","闲作东武吟，曲尽情未终。","书此谢知己，吾寻黄绮翁。"],"theme":"咏怀抒感","theme2":["山水田园","应制干谒","闲适隐逸"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["雪","酒"],"cats":{"抒情":["友情"]},"theme_conf":0.82},{"uid":"249ae962-2611-4d4f-aeca-7252cc60fafa","title":"夫子鼓琴得其人","author":"白行简","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["宣父穷玄奥，师襄授素琴。","稍殊流水引，全辨圣人心。","慕德声逾感，怀人意自深。","泠泠传妙手，摵摵振空林。","促调清风至，操弦白日沈。","曲终情不尽，千古仰知音。"],"theme":"题画咏艺","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["友情","思念"],"人物":["老师"]},"theme_conf":0.86},{"uid":"55b3c9cc-9b0b-4ed7-92ee-29b01c690c9f","title":"游长安诸寺联句 宣阳坊静域寺 三阶院联句","author":"段成式","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["密密助堂堂，隋人歌檿桑。","双弧摧孔雀，一矢陨贪狼。","百步望云立，九规看月张。","获蛟徒破浪，中乙漫如墙。","还似贯金鼓，更疑穿石梁。","因添挽河力，为灭射天狂。","绝艺却南牧，英声来鬼方。","丽龟何足敌，殪豕未为长。","龙臂胜猨臂，星芒超箭芒。","虚夸绝高鸟，垂拱议明堂。"],"theme":"哲理悟道","theme2":["山水田园","悼亡挽歌"],"style":"幽峭","style2":["冲淡","豪放"],"mood":"恬淡","mood2":[],"scene":["园林","月"],"cats":{"抒情":["悼亡"],"人生":["励志"]},"theme_conf":0.422},{"uid":"d9a38c34-7eb7-46d6-af26-da6f6f68bdf2","title":"送刘四赴夏县","author":"李颀","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["九霄特立红鸾姿，万仞孤生玉树枝。","刘侯致身能若此，天骨自然多叹美。","声名播扬二十年，足下长途几千里。","举世皆亲丞相阁，我心独爱伊川水。","脱略势利犹埃尘，啸傲时人而已矣。","新诗数岁即文雄，上书昔召蓬莱宫。","明主拜官麒麟阁，光车骏马看玉童。","高人往来庐山远，隐士往来张长公。","扶南甘蔗甜如蜜，杂以荔枝龙州橘。","赤县繁词满剧曹，白云孤峰晖永日。","朝持手板望飞鸟，暮诵楞伽对空室。","一朝出宰汾河间，明府下车人吏闲。","端坐讼庭更无事，开门咫尺巫咸山。","男耕女织蒙惠化，麦熟雉鸣长秋稼。","明年九府议功时，五辟三征当在兹。","闻道桐乡有遗老，邑中还欲置生祠。"],"theme":"送别","theme2":["山水田园"],"style":"沉郁","style2":["冲淡","绮丽"],"mood":"孤寂","mood2":[],"scene":["山","夏"],"cats":{"抒情":["孤独"],"四季":["夏天"],"山水":["庐山"],"食物":["荔枝"]},"theme_conf":0.307},{"uid":"26812d7f-e7f0-4936-be69-3dc2cf0bc0c8","title":"和武相公中秋锦楼玩月 一","author":"崔备","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["清景同千里，寒光尽一年。","竟天多鴈过，通夕少人眠。","照别江楼上，添愁野帐前。","隋侯恩未报，犹有夜珠圆。"],"theme":"应制干谒","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["中秋","楼","秋","月"],"cats":{"抒情":["伤感"],"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.86},{"uid":"e961ac8e-2de7-4ba1-a5a4-e1b810809edf","title":"片玉篇","author":"钱起","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["至宝未为代所奇，韫灵示[璞]荆山陲。","独使虹光天子识，不将清韵世人知。","世人所贵惟燕石，美玉对之成瓦砾。","空山埋照凡几年，古色苍痕宛自然。","重溪幂幂暗云树，一片荧荧光石泉。","美人之鉴明且彻，玉指提携叹奇绝。","试劳香袖拂莓苔，不觉清心皎冰雪。","连城美价幸逢时，命代良工岂见遗。","试作珪璋礼天地，何如瓀𤨟在堦墀。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["幽峭","冲淡"],"mood":"孤寂","mood2":[],"scene":["冬","雪","山"],"cats":{"抒情":["孤独"],"天气":["写雪"],"人物":["女子"]},"theme_conf":1.0},{"uid":"a7a08144-c10f-44ef-8558-7064cc123c68","title":"孟夫子生生亭赋","author":"卢仝","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["玉川子沿孟冬之寒流兮，辍櫂上登生生亭。","夫子何之兮，面逐云没兮南行。","百川注海而心不写兮，落日千里凝寒精。","予日衰期人生之世斯已矣，爰为今日犹犹岐路之心生。","悲夫！南国风涛，鱼龙畜伏。","予小子戆朴，必不能济夫子欲。","嗟自慙承夫子而不失予兮，传古道甚分明。","予且广孤目遐賷于天壤兮，庶得外尽万物变化之幽情。","然后慙愧而来归兮，大息吾躬于夫子之亭。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":["悲怆","惆怅"],"scene":["楼","冬"],"cats":{"抒情":["伤感","孤独"],"四季":["冬天"],"人物":["老师"]},"theme_conf":0.72},{"uid":"5901d95d-baf0-46dd-9a29-fd3c020c0a70","title":"相和歌辞 雁门太守行","author":"张祜","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["城头月没霜如水，趚趚蹋沙人似鬼。","灯前拭泪试香裘，长引一声残漏子。","驼囊泻酒酒一杯，前头啑血心不回。","寄语年少妻莫哀，鱼金虎竹天上来，雁门山边骨成灰。"],"theme":"羁旅思乡","theme2":["送别"],"style":"沉郁","style2":["婉约"],"mood":"悲怆","mood2":["愁怨"],"scene":["鸟","酒"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"动物":["写鸟"]},"theme_conf":0.638},{"uid":"f646a1ae-7a3e-4cdb-96d4-8c2ab4fb899a","title":"露青竹杖歌","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["鲜于仲通正当年，章仇兼琼在蜀川。","约束蜀儿采马鞭，蜀儿采鞭不敢眠。","横截斜飞飞鸟边，绳桥夜上层崖颠。","头插白云跨飞泉，采得马鞭长且坚。","浮沤丁子珠联联，灰煮蜡楷光烂然。","章仇兼琼持上天，上天雨露何其偏。","飞龙闲厩马数千，朝饮吴江夕秣燕。","红尘扑辔汗湿鞯，师子麒麟聊比肩。","江面昆明洗刷牵，四蹄踏浪头枿天。","蛟龙稽颡河伯虔，拓羯胡雏脚手鲜。","陈闳韩干丹青妍，欲貌未貌眼欲穿。","金鞍玉勒锦连干，骑入桃花杨柳烟。","十二楼中奏管弦，楼中美人夺神仙。","争爱大家把此鞭，禄山入关关破年。","忽见扬州北邙前，秪有人还千一钱。","亭亭笔直无皴节，磨捋形相一条铁。","市头格是无人别，江海贱臣不拘絏。","垂窗挂影西窗缺，稚子觅衣挑仰穴。","家童拾薪几拗折，玉润犹沾玉垒雪。","碧鲜似染苌弘血，蜀帝城边子规咽。","相如桥上文君绝，往年策马降至尊。","七盘九折横剑门，穆王八骏超昆仑。","安用冉冉孤生根，圣人不贵难得货，金玉珊珊谁买恩。"],"theme":"讽喻刺世","theme2":["山水田园","游仙梦幻","送别"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["雪","楼","鸟"],"cats":{"抒情":["孤独"],"人物":["女子","儿童"],"生活":["写桥"],"植物":["竹子"]},"theme_conf":0.75},{"uid":"8e18183e-5a58-4805-b672-1726969d6526","title":"早寒江上有怀","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["木落雁南度，北风江上寒。","我家襄水上，遥隔楚云端。","乡泪客中尽，孤帆天际看。","迷津欲有问，平海夕漫漫。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["幽峭","婉约"],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["思乡","孤独"],"山水":["江河"]},"theme_conf":0.677},{"uid":"9d8d3ee1-81f4-4938-8797-5dcd5be1f720","title":"李云南征蛮诗","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["圣人赫斯怒，诏伐西南戎。","肃穆庙堂上，深沈节制雄。","遂令感激士，得建非常功。","料死不料敌，顾恩宁顾终。","鼓行天海外，转战蛮夷中。","梯𪩘近高鸟，穿林经毒虫。","鬼门无归客，北户多南风。","蜂虿隔万里，云雷随九攻。","长驱大浪破，急击群山空。","饷道忽已远，悬军垂欲穷。","精诚动白日，愤薄连苍穹。","野食掘田鼠，晡餐兼僰僮。","收兵列亭堠，拓地弥西东。","临事耻苟免，履危能饬躬。","将星独照耀，边色何溟蒙。","泸水夜可涉，交州今始通。","归来长安道，召见甘泉宫。","廉蔺若未死，孙吴知暗同。","相逢论意气，慷慨谢深衷。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":["慷慨","悲怆"],"scene":[],"cats":{"抒情":["孤独"],"天气":["写云"],"人生":["战争"]},"theme_conf":0.589},{"uid":"00ede8d1-4ba1-4b59-9021-bddf471b00e4","title":"早春思归有唱竹枝歌者坐中下泪","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["渺渺春生楚水波，楚人齐唱竹枝歌。","与君皆是思归客，拭泪看花奈老何。"],"theme":"羁旅思乡","theme2":["题画咏艺"],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":["相思"],"scene":["春"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"植物":["竹子"]},"theme_conf":0.402},{"uid":"a4d718ee-c020-42b4-97df-499cd0076f7b","title":"登高","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["风急天高猨啸哀，渚清沙白鸟飞回。","无边落木萧萧下，不尽长江衮衮来。","万里悲秋常作客，百年多病独登台。","艰难苦恨繁霜鬓，潦倒新停浊酒桮。"],"theme":"民生疾苦","theme2":["咏史怀古"],"style":"悲慨","style2":["沉郁"],"mood":"悲怆","mood2":["愁怨"],"scene":["江","秋","重阳"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"山水":["长江"],"节日":["重阳节"]},"theme_conf":0.52},{"uid":"b423f06b-4c05-4892-a409-7933ccf2edf8","title":"横吹曲辞 陇头吟","author":"翁绶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["陇水潺湲陇树黄，征人陇上尽思乡。","马嘶斜日朔风急，雁过寒云边思长。","残月出林明劒戟，平沙隔水见牛羊。","横行俱足封侯者，谁斩楼兰献未央。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["月","楼","冬","鸟"],"cats":{"抒情":["思乡"],"四季":["冬天"],"天气":["写风"],"生活":["边塞"]},"theme_conf":0.645},{"uid":"cp4fe328e8e81bc3","title":"浪涛沙・浪淘沙","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["昼阴重，霜凋岸草，雾隐城堞。","南陌脂车待发。","东门帐饮乍阕。","正拂面垂杨堪缆结。","掩红泪、玉手亲折。","念汉浦离鸿去何许，经时信音绝。","情切。","望中地远天阔。","向露冷风清，无人处、耿耿寒漏咽。","嗟万事难忘，唯是轻别。","翠尊未竭。","凭断云留取，西楼残月。","罗带光销纹衾叠。","连环解、旧香顿歇。","怨歌永、琼壶敲尽缺。","恨春去、不与人期，弄夜色，空馀满地梨花雪。"],"theme":"送别","theme2":["闺情宫怨"],"style":"绮丽","style2":["沉郁","婉约"],"mood":"愁怨","mood2":["孤寂"],"scene":["雪","花","夜","春"],"cats":{"抒情":["离别","伤感","孤独","闺怨"],"四季":["春天"]},"theme_conf":0.59},{"uid":"1e1e7436-6f97-47ee-8d91-e540fe2b1edc","title":"相和歌辞 江南曲","author":"于鹄","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["偶向江边采白苹，还随女伴赛江神。","众中不敢分明语，暗掷金钱卜远人。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["江南","江"],"cats":{"抒情":["闺怨"],"山水":["江河"]},"theme_conf":1.0},{"uid":"315bc0e1-f76c-49d5-9940-b212e5f9c2ae","title":"送人东游","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["荒戍落黄叶，浩然离故关。","高风汉阳渡，初日郢门山。","江上几人在，天涯孤櫂还。","何当重相见，尊酒慰离颜。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"抒情":["孤独"]},"theme_conf":0.72},{"uid":"297dd100-6aab-4685-a52d-983fb0999c7a","title":"和乐天春词","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["新妆面面下朱楼，深锁春光一院愁。","行到中庭数花朵，蜻蜓飞上玉搔头。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":["欢愉","愁怨"],"scene":["春"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"]},"theme_conf":1.0},{"uid":"412f8f86-fdee-4f41-ac00-b5f134ea11c3","title":"和裴延龄尚书寄题果州谢舍人仙居","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["飘然去谒八仙翁，自地从天香满空。","紫盖迥标双鹤上，语音犹在五云中。","青溪不接渔樵路，丹井唯传草木风。","歌此因思捧金液，露盘长庆汉皇宫。"],"theme":"游仙梦幻","theme2":["山水田园","送别","咏物"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"抒情":["感恩"]},"theme_conf":0.82},{"uid":"0e6f466c-3fc6-4930-a25b-3c14172c1b41","title":"寒食宴城北山池即故郡守荣阳郑钢目为折柳亭","author":"羊士谔","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["别馆青山郭，游人折柳行。","落花经上巳，细雨带清明。","𫛸鴂流芳暗，鸳鸯曲水平。","归心何处醉，宝瑟有余声。"],"theme":"节令风俗","theme2":["送别"],"style":"幽峭","style2":[],"mood":"欢愉","mood2":[],"scene":["清明"],"cats":{"抒情":["离别","思乡"],"天气":["写雨"],"节日":["寒食节","清明节"],"植物":["柳树"]},"theme_conf":0.88},{"uid":"acbe1729-cefd-4678-9719-09c5c9c27db0","title":"咏怀古迹五首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["摇落深知宋玉悲，风流儒雅亦吾师。","怅望千秋一洒泪，萧条异代不同时。","江山故宅空文藻，云雨荒台岂梦思。","最是楚宫俱泯灭，舟人指点到今疑。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":["婉约","沉郁"],"mood":"相思","mood2":["悲怆","愁怨"],"scene":["秋","舟","雨","江","山"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"]},"theme_conf":0.805},{"uid":"6fac0cea-b4ee-419b-9802-786d508141f9","title":"冬行三首 一","author":"卢仝","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["虫豸腊月皆在蛰，吾独何乃劳其形。","小大无由知天命，但怪守道不得宁。","老母妻子一挥手，涕下便作千里行。","自顾不及遭霜叶，旦夕保得同飘零。","达生何足云，偶然苦乐经其身。","古来尧孔与桀跖，善恶何补如今人。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"孤寂","mood2":["欢愉"],"scene":["冬"],"cats":{"抒情":["思乡","孤独"],"四季":["冬天"],"人物":["母亲"]},"theme_conf":0.65},{"uid":"73f35093-8a40-44ba-ba98-6b4457303408","title":"送徐州张建封还镇","author":"德宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["牧守寄所重，才贤生为时。","宣风自淮甸，授钺膺藩维。","入觐展遐恋，临轩慰来思。","忠诚在方寸，感激陈情词。","报国尔所向，恤人予是资。","欢宴不尽怀，车马当还期。","谷雨将应候，行春犹未迟。","勿以千里遥，而云无己知。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":["慷慨"],"scene":["春","雨"],"cats":{"抒情":["爱国"],"四季":["春天"]},"theme_conf":0.771},{"uid":"cp4d7a1643bbbda8","title":"喜迁莺","author":"史达祖","dynasty":"宋","section":"宋词","form":"词","paragraphs":["月波疑滴。","望玉壶天近，了无尘隔。","翠眼圈花，冰丝织练，黄道宝光相直。","自怜诗酒瘦，难应接、许多春色。","最无赖，是随香趁烛，曾伴狂客。","踪迹。","谩记忆。","老了杜郎，忍听东风笛。","柳院灯疏，梅厅雪在，谁与细倾春碧。","旧情拘未定，犹自学、当年游历。","怕万一，误玉人、夜寒帘隙。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["豪放","绮丽"],"mood":"欢愉","mood2":["相思"],"scene":["春","冬"],"cats":{"抒情":["思念","思乡"],"四季":["春天"],"动物":["写鸟"]},"theme_conf":0.65},{"uid":"2557d68d-62fd-4a67-a4fc-1a926ec74c43","title":"奉和杜相公移长兴宅奉呈元相公","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["守贵常思俭，平津此意深。","能卑丞相宅，何谢故人心。","种蕙初抽带，移篁不改阴。","院梅朝助鼎，池凤夕归林。","觉路经中得，沧州梦里寻。","道高仍济代，恩重岂投簪。","报国谁知己，推贤共作霖。","兴来文雅振，清韵掷双金。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":["慷慨","相思"],"scene":["园林","雨"],"cats":{"抒情":["友情","爱国"]},"theme_conf":0.92},{"uid":"f6c4737c-b9d3-4cf5-8410-f296cceb839a","title":"赠陶使君求梨","author":"徐铉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["昨宵宴罢醉如泥，惟忆张公大谷梨。","白玉花繁曾缀处，黄金色嫩乍成时。","冷侵肺腑醒偏早，香惹衣襟歇倍迟。","今旦中山方酒渴，唯应此物最相宜。"],"theme":"咏物","theme2":[],"style":"豪放","style2":["绮丽"],"mood":"欢愉","mood2":["相思"],"scene":["酒","花"],"cats":{"抒情":["思念"],"植物":["梨花"]},"theme_conf":0.75},{"uid":"452ca2e5-a3f8-4dd1-b262-6ba2af5f3ea3","title":"杂曲歌辞 拜新月","author":"吉中孚妻张氏","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["拜新月，拜月出堂前。","暗魄深笼桂，虚弓未引弦。","拜新月，拜月妆楼上。","鸾镜未安台，蛾眉已相向。","拜新月，拜月不胜情，庭前风露清。","月临人自老，望月更长生。","东家阿母亦拜月，一拜一悲声断绝。","昔年拜月逞容仪，如今拜月双泪垂。","回看众女拜新月，却忆红闺年少时。"],"theme":"闺情宫怨","theme2":[],"style":"清新","style2":["婉约"],"mood":"相思","mood2":["悲怆","愁怨"],"scene":["月"],"cats":{"抒情":["思念","伤感","闺怨"],"天气":["月亮"],"人物":["母亲"]},"theme_conf":1.0},{"uid":"dbda2c85-f609-450a-8e93-a6c8f2723372","title":"柏崖老人号无名先生男削发女黄冠自以云泉独乐命予赋诗","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["古也忧婚嫁，君能乐性肠。","长男栖月宇，少女炫霓裳。","问尔餐霞处，春山芝桂旁。","鹤前飞九转，壶里驻三光。","与我开龙峤，披云静药堂。","胡麻兼藻绿，石髓隔花香。","帝力言何有，椿年喜渐长。","窅然高象外，宁不傲羲皇。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["月","花","春"],"cats":{"抒情":["孤独"],"四季":["春天"],"天气":["写云"]},"theme_conf":0.779},{"uid":"84bd91bd-11f7-4218-b9e2-b05b06ce8b99","title":"赠内人","author":"张祜","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["禁门宫树月痕过，媚眼唯看宿燕窠。","斜拔玉钗灯影畔，剔开红焰救飞蛾。"],"theme":"闺情宫怨","theme2":["闺情宫怨"],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["月"],"cats":{"抒情":["闺怨"]},"theme_conf":0.96},{"uid":"cp6a47d06d7bc689","title":"醉太平・这些时春寒绣ブ，月暗重门，梨花暮雨近黄昏，把香衾自温。金","author":"吴昌龄","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["杯不洗心头闷，青鸾不寄云边信，玉容不见意中人。","空教人害损。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["酒","花","春","月","雨","夜"],"cats":{"抒情":["闺怨"],"四季":["春天"],"天气":["月亮"],"植物":["梨花"],"食物":["写酒"]},"theme_conf":0.619},{"uid":"f5436455-4bdd-4425-96c5-12ed92905950","title":"重幸武功","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["代马依朔吹，惊禽愁昔丛。","况兹承眷德，怀旧感深衷。","积善忻余庆，畅武悦成功。","垂衣天下治，端拱车书同。","白水巡前迹，丹陵幸旧宫。","列筵欢故老，高宴聚新丰。","驻跸抚田畯，回舆访牧童。","瑞气萦丹阙，祥烟散碧空。","孤屿含霜白，遥山带日红。","于焉欢击筑，聊以咏南风。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":["孤寂"],"scene":[],"cats":{"抒情":["孤独"],"人物":["儿童"]},"theme_conf":0.65},{"uid":"d9dd3520-9aab-4b1b-bd57-810f29391667","title":"江州重别薛六柳八二员外","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["生涯岂料承优诏，世事空知学醉歌。","江上月明胡鴈过，淮南木落楚山多。","寄身且喜沧洲近，顾影无如白发何。","今日龙钟人共弃，媿君犹遣慎风波。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["江"],"cats":{"抒情":["离别"],"山水":["江河"],"植物":["柳树"]},"theme_conf":0.863},{"uid":"11424603-9a22-4564-89a4-95e1766f9685","title":"夕次盱眙县","author":"韦应物","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["落帆逗淮镇，停舫临孤驿。","浩浩风起波，冥冥日沈夕。","人归山郭暗，雁下芦洲白。","独夜忆秦关，听钟未眠客。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["舟","夜","山","鸟"],"cats":{"抒情":["思乡","孤独"]},"theme_conf":0.811},{"uid":"d549304d-762c-49d7-a661-d008586a3ec1","title":"大觉高僧兰若","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["巫山不见庐山远，松林兰若秋风晚。","一老犹鸣日暮钟，诸僧尚乞斋时饭。","香炉峰色隐晴湖，种杏仙家近白榆。","飞锡去年啼邑子，献花何日许门徒。"],"theme":"佛道禅颂","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["山"],"cats":{"抒情":["思念"],"山水":["庐山"]},"theme_conf":0.93},{"uid":"49a7fdb4-f899-42a1-a13f-8397020dc267","title":"相和歌辞 估客乐","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["估客无住著，有利身即行。","出门求火伴，入户辞父兄。","父兄相教示，求利莫求名。","求名有所避，求利无不营。","火伴相勒缚，卖假莫卖诚。","交关少交假，交假本生轻。","自兹相将去，誓死意不更。","一解市头语，便无乡里情。","𨱎石打臂钏，糯米炊项璎。","归来村中卖，敲作金玉声。","村中田舍娘，贵贱不敢争。","所费百钱本，已得十倍赢。","颜色转光净，饮食亦甘馨。","子本频蕃息，货赂日兼幷。","求珠驾沧海，采玉上荆衡。","北买党项马，西擒吐蕃鹦。","炎洲布火浣，蜀地锦织成。","越婢脂肉滑，奚僮眉眼明。","通算衣食费，不计远近程。","经营天下徧，却到长安城。","城中东西市，闻客次第迎。","迎客兼说客，多财为势倾。","客心本明黠，闻语心已惊。","先问十常侍，次求百公卿。","侯家与主第，点缀无不精。","归来始安坐，富与王家勍。","市卒酒肉臭，县胥家舍成。","岂惟绝言语，奔走极使令。","大儿贩材木，巧识梁栋形。","小儿贩盐卤，不入州县征。","一身偃市利，突若截海鲸。","钩距不敢下，下则牙齿横。","生为估客乐，判尔乐一生。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["江"],"cats":{"抒情":["思乡"],"人物":["儿童"]},"theme_conf":1.0},{"uid":"72da81b5-8de5-4b5f-bc46-820925a90d64","title":"寄宋申锡评事时从李少师移军回归","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["君逐元侯静虏归，虎旗龙节驻春晖。","欲求岱岳燔柴礼，已锡鲁人缝掖衣。","长劒一时天外倚，五云多遶日边飞。","心期共贺太平世，去去故乡亲食薇。"],"theme":"寄赠酬答","theme2":["边塞征战","羁旅思乡"],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"抒情":["思乡","感恩"],"四季":["春天"],"山水":["泰山"]},"theme_conf":0.9},{"uid":"2b9b6071-6dc8-4b04-949c-5350f23e4f9d","title":"和微之春日投简阳明洞天五十韵","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["青阳行已半，白日坐将徂。","越国强仍大，稽城高且孤。","利饶盐煮海，名胜水澄湖。","牛斗天垂象，台明地展图。","瓌奇填市井，佳丽溢𬮱阇。","句践遗风霸，西施旧俗姝。","船头龙夭矫，桥脚兽睢盱。","乡味珍蟛蚏，时鲜贵鹧鸪。","语言诸夏异，衣服一方殊。","捣练蛾眉婢，鸣榔蛙角奴。","江清敌伊洛，山翠胜荆巫。","华表双栖鹤，联樯几点乌。","烟波分渡口，云树接城隅。","涧远松如画，洲平水似铺。","绿科秧早稻，紫笋折新芦。","暖蹋泥中藕，香寻石上蒲。","雨来萌尽达，雷后蛰全苏。","柳眼黄丝颣，花房绛蜡珠。","林风新竹折，野烧老桑枯。","带亸长枝蕙，钱穿短贯榆。","暄和生野菜，卑湿长街芜。","女浣纱相伴，儿烹鲤一呼。","山魈啼稚子，林狖挂山都。","产业论蚕蚁，孳生计鸭雏。","泉岩雪飘洒，苔壁锦漫糊。","堰限舟航路，堤通车马途。","耶溪岸回合，禹庙径盘纡。","洞穴何因凿，星槎谁与刳。","石凹仙药臼，峰峭佛香炉。","去为投金简，来因挈玉壶。","贵仍招客宿，健未要人扶。","闻望贤丞相，仪形美丈夫。","前驱驻旌斾，偏坐列笙竽。","刺史旟翻隼，尚书履曳凫。","学禅超后有，观妙造虚无。","髻里传僧宝，环中得道枢。","登楼诗八咏，置砚赋三都。","捧拥罗将绮，趋跄紫与朱。","庙谟藏稷卨，兵略贮孙吴。","令下三军整，风高四海趋。","千家得慈母，六郡事严姑。","重士过三哺，轻财抵一铢。","送觥歌宛转，嘲妓笑卢胡。","佐饮时炮鼈，蠲酲数鲙鲈。","醉乡虽咫尺，乐事亦须臾。","若不中贤圣，何由外智愚。","伊予一生志，我尔百年躯。","江上三千里，城中十二衢。","出多无伴侣，归只对妻孥。","白首青山约，抽身去得无。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":["豪放","婉约"],"mood":"欢愉","mood2":["孤寂"],"scene":["江","山","江南","舟","春"],"cats":{"抒情":["孤独","感恩"],"四季":["春天"],"天气":["太阳"],"人物":["母亲","儿童"],"生活":["写桥"]},"theme_conf":0.9},{"uid":"4e167af1-7d67-4417-aa13-bff4bbe8f9f1","title":"独酌","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["长空碧杳杳，万古一飞鸟。","生前酒伴闲，愁醉闲多少。","烟深隋家寺，殷叶暗相照。","独佩一壶游，秋毫泰山小。"],"theme":"闲适隐逸","theme2":[],"style":"豪放","style2":["雄浑"],"mood":"孤寂","mood2":[],"scene":["酒"],"cats":{"抒情":["孤独"],"山水":["泰山"],"食物":["写酒"]},"theme_conf":0.86},{"uid":"0167687e-8325-48bf-8da4-3749c9ce0a74","title":"横吹曲辞 关山月","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["明月出天山，苍茫云海间。","长风几万里，吹度玉门关。","汉下白登道，胡窥青海湾。","由来征战地，不见有人还。","戍客望边色，思归多苦颜。","高楼当此夜，叹息未应闲。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["雄浑"],"mood":"相思","mood2":[],"scene":["山","月"],"cats":{"抒情":["思念"],"天气":["月亮"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.512},{"uid":"cp28fb75b07e0336","title":"醉花阴","author":"李清照","dynasty":"宋","section":"宋词","form":"词","paragraphs":["薄雾浓云愁永昼。","瑞脑消金兽。","佳节又重阳，玉枕纱厨，半夜凉初透。","东篱把洒黄昏后，有暗香盈袖。","莫道不消魂，帘卷西风，人似黄花瘦。"],"theme":"爱情相思","theme2":["节令风俗"],"style":"婉约","style2":["绮丽"],"mood":"愁怨","mood2":[],"scene":["花","夜","重阳","酒"],"cats":{"抒情":["伤感"],"节日":["重阳节"],"食物":["写酒"]},"theme_conf":0.66},{"uid":"1b9b8047-2410-47ae-a24c-aad7342b338f","title":"石鼓歌","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["张生手持石鼓文，劝我试作石鼓歌。","少陵无人谪仙死，才薄将奈石鼓何。","周纲陵迟四海沸，宣王愤起挥天戈。","大开明堂受朝贺，诸侯劒佩鸣相磨。","搜于岐阳骋雄俊，万里禽兽皆遮罗。","镌功勒成告万世，凿石作鼓隳嵯峨。","从臣才艺咸第一，拣选撰刻留山阿。","雨淋日炙野火燎，鬼物守护烦㧑呵。","公从何处得纸本，毫发尽备无差讹。","辞严义密读难晓，字体不类隶与科。","年深岂免有缺画，快劒斫断生蛟鼍。","鸾翔凤翥众僊下，珊瑚碧树交枝柯。","金绳铁索锁纽壮，古鼎跃水龙腾梭。","陋儒编诗不收入，二雅褊迫无委蛇。","孔子西行不到秦，掎摭星宿遗羲娥。","嗟予好古生苦晚，对此涕泪双滂沱。","忆昔初蒙博士徴，其年始改称元和。","故人从军在右辅，为我度量掘臼科。","濯冠沐浴告祭酒，如此至宝存岂多。","氊包席裹可立致，十鼓祗载数骆驼。","荐诸太庙比郜鼎，光价岂止百倍过。","圣恩若许留太学，诸生讲解得切磋。","观经鸿都尚填咽，坐见举国来奔波。","剜苔剔藓露节角，安置妥帖平不颇。","大厦深簷与盖覆，经历久远期无佗。","中朝大官老于事，讵肯感激徒媕婀。","牧童敲火牛砺角，谁复著手为摩挲。","日销月铄就埋没，六年西顾空吟哦。","羲之俗书趁姿媚，数纸尚可博白鹅。","继周八代争战罢，无人收拾理则那。","方今太平日无事，柄任儒术崇丘轲。","安能以此上论列，愿借辨口如悬河。","石鼓之歌止于此，呜呼吾意其蹉跎。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["幽峭","绮丽"],"mood":"孤寂","mood2":["愁怨"],"scene":[],"cats":{"抒情":["伤感","孤独"],"人物":["儿童"],"人生":["战争"]},"theme_conf":0.562},{"uid":"a1255e7f-9db9-45a3-85cf-ad00559a3e58","title":"沣水送郑鄠县读书","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["麦秋中夏凉风起，送君西郊及沣水。","孤烟远树动离心，隔岸江流若千里。","早年江海谢浮名，此路云山惬尔情。","上古全经皆在口，秦人如见济南生。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["夏","秋","江","山"],"cats":{"抒情":["离别","孤独"],"四季":["夏天","秋天"],"山水":["江河"],"人生":["读书"]},"theme_conf":0.766},{"uid":"b9811b91-7522-46d2-ae55-63d63968adca","title":"自淇涉黄河途中作十三首 十二","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["朝景入平川，川长复垂柳。","遥看魏公墓，突兀前山后。","忆昔大业时，群雄角奔走。","伊人何电迈，独立风尘首。","传檄举敖仓，拥兵屯洛口。","连营一百万，六合如可有。","方项终比肩，乱隋将假手。","力争固难恃，骄战曷能久。","若使学萧曹，功名当不朽。"],"theme":"边塞征战","theme2":["悼亡挽歌"],"style":"豪放","style2":[],"mood":"孤寂","mood2":["慷慨"],"scene":["江"],"cats":{"抒情":["孤独","悼亡"],"山水":["黄河"],"人生":["战争"]},"theme_conf":0.552},{"uid":"3e6f3ca9-f771-438d-8f5f-75ba5b802739","title":"酬李端校书见赠","author":"司空曙","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["绿槐垂穗乳乌飞，忽忆山中独未归。","青镜流年看发变，白云芳草与心违。","乍逢酒客春游惯，久别林僧夜坐稀。","昨日闻君到城阙，莫将簪弁胜荷衣。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":["相思"],"scene":["酒","春","夜","山"],"cats":{"抒情":["思念","孤独"],"四季":["春天"],"人生":["时光"]},"theme_conf":0.97},{"uid":"04803420-1f5b-48f0-abba-2940006ba36b","title":"月夜梧桐叶上见寒露","author":"戴察","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["萧疎桐叶上，月白露初团。","滴沥清光满，荧煌素彩寒。","风摇愁玉坠，枝动惜珠干。","气冷疑秋晚，声微觉夜阑。","凝空流欲遍，润物净宜看。","莫厌窥临倦，将晞聚更难。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":["幽峭","绮丽"],"mood":"孤寂","mood2":["愁怨"],"scene":["夜","月"],"cats":{"抒情":["伤感"],"天气":["月亮"],"植物":["叶子"]},"theme_conf":0.82},{"uid":"bb2b70d6-9985-4b06-a850-5b51f2c98e1b","title":"落叶","author":"王周","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["素律铄欲脆，青女妒复稀。","月冷天风吹，叶叶乾红飞。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["秋","月"],"cats":{"抒情":["思乡"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"b422712d-ef98-46d3-b967-0a2c5c000fc7","title":"杂曲歌辞 结韈子","author":"李白","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["燕南壮士吴门豪，筑中置铅鱼隐刀。","感君恩重许君命，泰山一掷轻鸿毛。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"慷慨","mood2":["欢愉"],"scene":["山"],"cats":{"抒情":["怀古","感恩"],"山水":["泰山"]},"theme_conf":1.0},{"uid":"cp60a401fbbbc431","title":"莺啼序","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["残寒正欺病酒，掩沈香绣户。","燕来晚、飞入西城，似说春事迟暮。","画船载、清明过却，晴烟冉冉吴宫树。","念羁情游荡，随风化为轻絮。","十载西湖，傍柳系马，趁娇尘软雾。","溯红渐、招入仙溪，锦儿偷寄幽素。","倚银屏、春宽梦窄，断红湿、歌纨金缕。","暝堤空，轻把斜阳，总还鸥鹭。","幽兰旋老，杜若还生，水乡尚寄旅。","别后访、六桥无信，事往花委，瘗玉埋香，几番风雨。","长波妒盼，遥山羞黛，渔灯分影春江宿，记当时、短楫桃根渡。","青楼彷佛，临分败壁题诗，泪墨惨澹尘土。","危亭望极，草色天涯，吹鬓侵半苎。","暗点检、离痕欢唾，尚染鲛绡，凤迷归，破鸾慵舞。","殷勤待写，书中长恨，蓝霞辽海沈过雁，漫相思、弹入哀筝柱。","伤心千里江南，怨曲重招，断魂在否。"],"theme":"悼亡挽歌","theme2":["送别"],"style":"沉郁","style2":["绮丽","婉约"],"mood":"相思","mood2":["愁怨"],"scene":["江南","鸟","春"],"cats":{"抒情":["离别","思念","伤感","悼亡"],"四季":["春天"],"山水":["西湖"],"生活":["写桥"],"节日":["清明节"],"动物":["写鸟"]},"theme_conf":0.93},{"uid":"b3146349-87b7-463f-994b-ab5fea5ca2f3","title":"戍客南归","author":"于𣸣","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["北别黄榆塞，南归白云乡。","孤舟下彭蠡，楚月沈沧浪。","为子惜功业，满身刀箭疮。","莫渡汨罗水，回君忠孝肠。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["端午","塞外","舟","月"],"cats":{"抒情":["思乡","孤独"],"生活":["边塞"],"节日":["端午节"]},"theme_conf":0.444},{"uid":"3e2a6b80-7713-4eb1-af64-67bfd3f1d705","title":"谢李六郎中寄新蜀茶","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["故情周匝向交亲，新茗分张及病身。","红纸一封书后信，绿芽十片火前春。","汤添勺水煎鱼眼，末下刀圭搅曲尘。","不寄他人先寄我，应缘我是别茶人。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["春"],"cats":{"抒情":["感恩"],"四季":["春天"],"食物":["写茶"]},"theme_conf":0.95},{"uid":"5400406f-949f-4793-8c52-8cb59b47ac61","title":"忆白菊","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["稚子书传白菊开，西成相滞未容回。","月明阶下窗纱薄，多少清香透入来。"],"theme":"亲情","theme2":["咏物"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["重阳"],"cats":{"抒情":["思念"],"人物":["儿童"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.528},{"uid":"19387623-b6c7-4a43-90c0-6c2208eab545","title":"和太原张相公山亭怀古","author":"高铢","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["鬬石类岩𪩘，飞流泻潺湲。","远壑簷宇际，孤峦雉堞间。","何必到海岳，境幽机自闲。","兹焉得高趣，高步谢东山。"],"theme":"咏史怀古","theme2":[],"style":"旷达","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["山"],"cats":{"抒情":["孤独","怀古"],"山水":["瀑布"]},"theme_conf":0.483},{"uid":"4c5b328d-2ab8-4f4d-a0c2-627b6cb0c92b","title":"金陵图","author":"韦庄","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["谁谓伤心画不成，画人心逐世人情。","君看六幅南朝事，老木寒云满故城。"],"theme":"题画咏艺","theme2":["咏史怀古"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"抒情":["怀古"]},"theme_conf":0.509},{"uid":"664aff60-36cb-4907-8842-e6717be10cce","title":"送耿拾遗𣲗使江南括图书","author":"李端","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["驱传草连天，回风满树蝉。","将过夫子宅，前问孝廉船。","汉使收三箧，周诗采百篇。","别来将有泪，不是怨流年。"],"theme":"题画咏艺","theme2":["送别"],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["江南","江"],"cats":{"抒情":["伤感"],"人生":["时光"]},"theme_conf":0.471},{"uid":"25be9870-8794-4702-bdb9-8ed2a7df8051","title":"湘夫人二首 二","author":"郎士元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["南有涔阳路，渺渺多新愁。","桂酒神降时，回风江上秋。","彩云忽无处，碧水空安流。"],"theme":"游仙梦幻","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["酒","秋","江"],"cats":{"抒情":["伤感"],"四季":["秋天"],"天气":["写云"]},"theme_conf":0.68},{"uid":"0d04cc1d-1ad6-472c-9de3-75695aae467c","title":"送唐中丞开淘西湖夏日游泛因书示郡人","author":"朱庆余","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["萍岸新淘见碧霄，中流相去忽成遥。","空余孤屿来诗景，无复横槎碍柳条。","红斾路幽山翠湿，锦帆风起浪花飘。","共知浸润同雷泽，何虑川源有旱苗。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["惆怅"],"scene":["夏","江南","江"],"cats":{"抒情":["孤独"],"四季":["夏天"],"山水":["西湖"]},"theme_conf":0.67},{"uid":"8d480633-1876-4082-aaca-a7b3a26c04d7","title":"杂曲歌辞 长干曲四首 二","author":"崔颢","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["家临九江水，去来九江侧。","同是长干人，生小不相识。"],"theme":"羁旅思乡","theme2":["闺情宫怨"],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["江"],"cats":{"抒情":["思乡","闺怨"]},"theme_conf":0.572},{"uid":"b849afe9-f7db-4f53-b688-fafa65b264f1","title":"南海马大夫见惠著述三通勒成四帙上自邃古达于国朝采其菁华至简如富钦受嘉贶诗以谢之","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["红旗阅五兵，绛帐领诸生。","味道轻鼎食，退公犹笔耕。","青箱传学远，金匮纳书成。","一瞬见前事，九流当抗行。","编蒲曾苦思，垂竹媿无名。","今日承芳讯，谁言赠衮荣。"],"theme":"寄赠酬答","theme2":["送别","边塞征战"],"style":"豪放","style2":["旷达","绮丽"],"mood":"恬淡","mood2":[],"scene":["花"],"cats":{"抒情":["感恩"],"人物":["老师"],"动物":["写马"]},"theme_conf":0.96},{"uid":"cp7857964ab0bf7a","title":"曲游春","author":"周密","dynasty":"宋","section":"宋词","form":"词","paragraphs":["楚苑东风外，暖丝情絮，春思如织。","燕约莺期，恼芳情偏在，翠深红隙。","漠漠香尘隔。","沸十里、乱弦丛笛。","看画船，尽入西泠，闲却半湖春色。","柳陌。","新烟凝碧。","映帘底宫眉，堤上游勒。","轻暝笼寒，怕梨云梦冷，杏香愁幂。","歌管酬寒食。","奈蝶怨、良宵岑寂。","正满湖、碎月摇花，怎生去得。"],"theme":"节令风俗","theme2":["送别"],"style":"婉约","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["春"],"cats":{"抒情":["伤感"],"四季":["春天"],"节日":["寒食节"]},"theme_conf":0.86},{"uid":"d8a8ab40-f615-44dd-9366-883aa1202a1c","title":"路病","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["病客无主人，艰哉求卧难。","飞光赤道路，内火焦肺肝。","欲饮井泉竭，欲医囊用单。","稚颜能几日，壮志忽已残。","人子不言苦，归书但云安。","愁环在我肠，宛转终无端。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["思乡","伤感"],"人生":["励志","梦想"]},"theme_conf":0.542},{"uid":"4f637cfe-2766-4d58-925a-fe3e4ae6b864","title":"元日朝回中夜书情寄南宫二故人","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["鸣珮随鹓鹭，登堦见冕旒。","无能裨圣代，何事别沧洲。","闲夜贫还醉，浮名老渐羞。","凤城春欲晚，郎吏忆同游。"],"theme":"寄赠酬答","theme2":["节令风俗"],"style":"婉约","style2":[],"mood":"恬淡","mood2":["相思"],"scene":["夜"],"cats":{"抒情":["友情","思念"],"节日":["春节"]},"theme_conf":0.96},{"uid":"49d2767d-7281-4df2-ba8f-36276d5928e4","title":"伤春五首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["鸎入新年语，花开满故枝。","天青风卷幔，草碧水通池。","牢落官军速，萧条万事危。","鬓毛元自白，泪点向来垂。","不是无兄弟，其如有别离。","巴山春色静，北望转逶迤。"],"theme":"送别","theme2":["悼亡挽歌"],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":["恬淡"],"scene":["春"],"cats":{"抒情":["离别","伤感","悼亡"],"四季":["春天"],"节日":["春节"]},"theme_conf":0.4},{"uid":"7ff205d9-e2f9-4721-910c-90213458841a","title":"晚菊","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["少年饮酒时，踊跃见菊花。","今来不复饮，每见恒咨嗟。","伫立摘满手，行行把归家。","此时无与语，弃置奈悲何。"],"theme":"咏物","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["重阳","酒"],"cats":{"抒情":["伤感"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"c5f9b99b-fe97-4eef-8fea-30b45125aa97","title":"送韦侍御奉使江岭诸道催青苗钱","author":"包何","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["近远从王事，南行处处经。","手持霜简白，心在夏苗青。","回鴈书应报，愁猨夜屡听。","因君使绝域，方物尽来庭。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["江","山","夏","夜"],"cats":{"抒情":["伤感"],"四季":["夏天"]},"theme_conf":0.681},{"uid":"9d33c118-cde9-49af-b572-c43427a10b48","title":"巴山道中除夜书怀","author":"崔涂","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["迢遰三巴路，羇危万里身。","乱山残雪夜，孤烛异乡春。","渐与骨肉远，转于僮仆亲。","那堪正漂泊，明日岁华新。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":["夜","山","除夕"],"cats":{"抒情":["思乡","孤独"],"节日":["春节"]},"theme_conf":0.567},{"uid":"bf3103b8-41e4-4193-a126-22fa56214f25","title":"和万州杨使君四绝句 竞渡","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["竞渡相传为汨罗，不能止遏意无他。","自经放逐来顦顇，能校灵均死几多。"],"theme":"咏史怀古","theme2":[],"style":"婉约","style2":[],"mood":"悲怆","mood2":[],"scene":["端午"],"cats":{"抒情":["怀古"],"节日":["端午节"]},"theme_conf":0.82},{"uid":"16f2a421-f439-45f3-9fe5-b9948368568e","title":"送柳道时余北还","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["征役各异路，烟波同旅愁。","轻桡上桂水，大艑下扬州。","何处成后会，今朝分旧游。","离心比杨柳，萧飒不胜秋。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","江"],"cats":{"抒情":["伤感"],"四季":["秋天"],"植物":["柳树"]},"theme_conf":0.802},{"uid":"ea4f954e-f947-4ea6-a7ce-24425dcf7fea","title":"相和歌辞  相逢行","author":"崔颢","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["妾年初二八，家住洛桥头。","玉户临驰道，朱门近御沟。","使君何假问，夫壻大长秋。","女弟新承宠，诸兄近拜侯。","春生百子殿，花发五城楼。","出入千门里，年年乐未休。"],"theme":"讽喻刺世","theme2":["羁旅思乡","闺情宫怨"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["秋","春","楼"],"cats":{"抒情":["思乡","闺怨"],"四季":["春天","秋天"],"生活":["写桥"]},"theme_conf":0.372},{"uid":"cp0f289616020e5f","title":"念奴娇","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["野棠花落，又匆匆、过了青明时节。","地东风欺客梦，一夜云屏寒怯。","曲岸持觞，垂杨系马，此地曾轻别。","楼空人去，旧游飞燕能说。","闻道绮陌东头，行人长见，帘底纤纤月。","旧恨春江流未断，新恨云山千叠。","料得明朝，尊前重见，镜里花难折。","也应惊问，近来多少华发。"],"theme":"送别","theme2":["羁旅思乡"],"style":"婉约","style2":["清新","沉郁"],"mood":"相思","mood2":["愁怨","孤寂"],"scene":["春","酒"],"cats":{"抒情":["思乡"],"四季":["春天"],"山水":["江河"]},"theme_conf":0.531},{"uid":"dad3755e-883c-4022-83a4-4a47583c8112","title":"相和歌辞 陇西行","author":"长孙佐辅","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["阴云凝朔气，陇上正飞雪。","四月草不生，北风劲如切。","朝来羽书急，夜救长城窟。","道隘行不前，相呼抱鞍歇。","人寒指欲堕，马冻蹄亦裂。","射雁旋充饥，斧冰还止渴。","宁辞解围鬬，但恐乘疲没。","早晚边候空，归来养羸卒。"],"theme":"边塞征战","theme2":["民生疾苦","羁旅思乡"],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["雪","冬"],"cats":{"抒情":["思乡"],"天气":["写雪"]},"theme_conf":0.388},{"uid":"d2dac645-ea92-432b-bc76-6656f5515a94","title":"送秘书谢监赴江西使幕","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["谢监忆山程，辞家万里行。","寒衣傍楚色，孤枕宿潮声。","小寇不足问，新诗应渐清。","府公相待日，引斾出江城。"],"theme":"送别","theme2":[],"style":"清新","style2":["豪放"],"mood":"孤寂","mood2":["相思"],"scene":["江"],"cats":{"抒情":["思念","孤独","感恩"],"山水":["江河"]},"theme_conf":1.0},{"uid":"8c70f0e2-8df5-42da-975b-927f7093a3d0","title":"灵岩寺","author":"薛令之","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["草堂栖在灵山谷，勤苦诗书向灯烛。","柴门半掩寂无人，惟有白云相伴宿。"],"theme":"哲理悟道","theme2":["山水田园"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"抒情":["孤独"],"人生":["读书"]},"theme_conf":0.521},{"uid":"19796737-ec7b-4c33-8df4-a81a7ca2cc10","title":"章台夜思","author":"韦庄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["清瑟怨遥夜，遶弦风雨哀。","孤灯闻楚角，残月下章台。","芳草已云暮，故人殊未来。","乡书不可寄，秋雁又南回。"],"theme":"羁旅思乡","theme2":["送别"],"style":"沉郁","style2":["清新"],"mood":"相思","mood2":[],"scene":["夜"],"cats":{"抒情":["友情","思乡"]},"theme_conf":0.516},{"uid":"cp54b638987d48b5","title":"天香","author":"王沂孙","dynasty":"宋","section":"宋词","form":"词","paragraphs":["孤峤蟠烟，层涛蜕月，骊宫夜采铅水。","讯远槎风，梦深薇露，化作断魂心字。","红瓷候火，还乍识、冰环玉指。","一缕萦帘翠影，依稀海天云气。","几回娇半醉。","翦春灯、夜寒花碎。","更好故溪飞雪，小窗深闭。","荀令如今顿老，总忘却、樽前旧风味。","谩惜馀熏，空篝素被。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["婉约","豪放"],"mood":"孤寂","mood2":[],"scene":["雪","夜","花","酒"],"cats":{"抒情":["孤独"],"天气":["写雪"]},"theme_conf":1.0},{"uid":"0a0f9231-d88c-4f81-b941-83b67a736194","title":"长恨歌","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["汉皇重色思倾国，御宇多年求不得。","杨家有女初长成，养在深闺人未识。","天生丽质难自弃，一朝选在君王侧。","回眸一笑百媚生，六宫粉黛无颜色。","春寒赐浴华清池，温泉水滑洗凝脂。","侍儿扶起娇无力，始是新承恩泽时。","云鬓花颜金步摇，芙蓉帐暖度春宵。","春宵苦短日高起，从此君王不早朝。","承欢侍宴无闲暇，春从春游夜专夜。","后宫佳丽三千人，三千宠爱在一身。","金屋妆成娇侍夜，玉楼宴罢醉和春。","姊妹弟兄皆列土，可怜光彩生门户。","遂令天下父母心，不重生男重生女。","骊宫高处入青云，仙乐风飘处处闻。","缓歌慢舞凝丝竹，尽日君王看不足。","渔阳鞞鼓动地来，惊破霓裳羽衣曲。","九重城阙烟尘生，千乘万骑西南行。","翠华摇摇行复止，西出都门百余里。","六军不发无奈何，宛转蛾眉马前死。","花钿委地无人收，翠翘金雀玉搔头。","君王掩面救不得，回看血泪相和流。","黄埃散漫风萧索，云栈萦纡登劒阁。","峨嵋山下少人行，旌旗无光日色薄。","蜀江水碧蜀山青，圣主朝朝暮暮情。","行宫见月伤心色，夜雨闻铃肠断声。","天旋日转回龙驭，到此踌躇不能去。","马嵬坡下泥土中，不见玉颜空死处。","君臣相顾尽沾衣，东望都门信马归。","归来池苑皆依旧，太液芙蓉未央柳。","芙蓉如面柳如眉，对此如何不泪垂？","春风桃李花开夜，秋雨梧桐叶落时。","西宫南苑多秋草，宫叶满阶红不埽。","棃园弟子白发新，椒房阿监青娥老。","夕殿萤飞思悄然，孤灯挑尽未成眠。","迟迟钟鼓初长夜，耿耿星河欲曙天。","鸳鸯瓦冷霜华重，翡翠衾寒谁与共。","悠悠生死别经年，魂魄不曾来入梦。","临邛道士鸿都客，能以精诚致魂魄。","为感君王展转思，遂教方士殷勤觅。","排空驭气奔如电，升天入地求之徧。","上穷碧落下黄泉，两处茫茫皆不见。","忽闻海上有仙山，山在虚无缥缈间。","楼阁玲珑五云起，其中绰约多仙子。","中有一人字太真，雪肤花貌参差是。","金阙西厢叩玉扃，转教小玉报双成。","闻道汉家天子使，九华帐里梦魂惊。","揽衣推枕起裴回，珠箔银屏逦迤开。","云鬓半偏新睡觉，花冠不整下堂来。","风吹仙袂飘飖举，犹似霓裳羽衣舞。","玉容寂莫泪阑干，棃花一枝春带雨。","含情凝睇谢君王，一别音容两渺茫。","昭阳殿里恩爱绝，蓬莱宫中日月长。","回头下望人寰处，不见长安见尘雾。","唯将旧物表深情，钿合金钗寄将去。","钗留一股合一扇，钗擘黄金合分钿。","但教心似金钿坚，天上人间会相见。","临别殷勤重寄词，词中有誓两心知。","七月七日长生殿，夜半无人私语时。","在天愿作比翼鸟，在地愿为连理枝。","天长地久有时尽，此恨緜緜无绝期。"],"theme":"爱情相思","theme2":["爱情相思"],"style":"沉郁","style2":["绮丽"],"mood":"愁怨","mood2":["孤寂"],"scene":["夜","楼","山","春","秋","园林"],"cats":{"抒情":["爱情","伤感","孤独","闺怨","感恩"],"四季":["春天","秋天"],"天气":["写雨","星星"],"人物":["老师"],"人生":["梦想"]},"theme_conf":0.85},{"uid":"0f980b6f-473d-4f04-8090-0e04da5e2655","title":"奉同郭给事汤东灵湫作","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东山气鸿蒙，宫殿居上头。","君来必十月，树羽临九州。","阴火煮玉泉，喷薄涨岩幽。","有时浴赤日，光抱空中搂。","阆风入辙迹，旷原延冥搜。","沸天万乘动，观水百丈湫。","幽灵斯可佳，王命宫属休。","初闻龙用壮，擘石摧林丘。","中夜窟宅改，移因风雨秋。","倒悬瑶池影，屈注苍江流。","味如甘露浆，挥弄滑且柔。","翠旗澹偃蹇，云车纷少留。","箫鼓荡四溟，异香泱漭浮。","鲛人献微绡，曾祝沈豪牛。","百祥奔盛明，古先莫能俦。","坡陀金虾蟆，出见盖有由。","至尊顾之笑，王母不肯收。","复归虚无底，化作长黄虬。","飘飘青琐郎，文采珊瑚钩。","浩歌渌水曲，清绝听者愁。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["婉约","冲淡"],"mood":"慷慨","mood2":["愁怨","恬淡"],"scene":["山","雨","秋"],"cats":{"抒情":["伤感","爱国"],"四季":["秋天"],"山水":["江河"]},"theme_conf":1.0},{"uid":"1d4a2546-2823-49c6-94e2-345a96eee0ce","title":"荔枝树","author":"郑谷","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["二京曾见画图中，数本芳菲色不同。","孤櫂今来巴徼外，一枝烟雨思无穷。","夜郎城近含香瘴，杜宇巢低起暝风。","肠断渝泸霜霰薄，不教叶似灞陵红。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["花","雪","雨","夜","春"],"cats":{"抒情":["伤感","孤独","怀古"],"食物":["荔枝"]},"theme_conf":0.65},{"uid":"49359d18-613c-4aa0-8836-e2253b88d772","title":"十月诞辰内殿宴群臣效柏梁体联句","author":"中宗皇帝","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["润色鸿业寄贤才，叨居右弼媿盐梅。","运筹帷幄荷时来，职掌图籍滥蓬莱。","两司谬忝谢钟裴，礼乐铨管效涓埃。","陈师振旅清九垓，欣承顾问侍天杯。","衔恩献寿梁柏台，黄缣青简奉康哉。","鲰生侍从忝王枚，右掖司言实不才。","宗伯秩礼天地开，帝歌难续仰昭回。","微臣捧日变寒灰，远慙班左媿游陪。"],"theme":"羁旅思乡","theme2":["游仙梦幻","送别"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["月"],"cats":{"抒情":["思乡"],"天气":["月亮"]},"theme_conf":0.35},{"uid":"621d6001-ea93-4bce-adb6-7e085437f15f","title":"秋夜宴王郎中宅赋得露中菊","author":"朱湾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["众芳春竞发，寒菊露偏滋。","受气何曾异，开花独自迟。","晚成犹待赏，欲采未过时。","忍弃东篱下，看随秋草衰。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":["孤寂"],"scene":["秋","重阳","夜"],"cats":{"抒情":["孤独"],"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.682},{"uid":"cpcd87e66c3b994c","title":"石州慢","author":"张元干","dynasty":"宋","section":"宋词","form":"词","paragraphs":["寒水依痕，春意渐回，沙际烟阔。","溪梅晴照生香，冷芯数枝争发。","天涯旧恨，试看几许消魂，长亭门外山重叠。","不尽眼中青，是愁来时节。","情切。","画楼深闭，想见东风，暗销肌雪。","辜负枕前云雨，尊前花月。","心期切处，更有多少凄凉，殷勤留与归时说。","到得却相逢，恰经年离别。"],"theme":"送别","theme2":[],"style":"幽峭","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["春","楼","冬","花","雪"],"cats":{"抒情":["离别","伤感"],"四季":["春天"]},"theme_conf":0.529},{"uid":"070d66a9-c9a0-44a3-be22-af612fac4861","title":"自澧浦东游江表途出巴丘投员外从公虞","author":"李群玉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["短翮后飞者，前攀鸾鹤翔。","力微应万里，矫首空苍苍。","谁昔探花源，考槃西岳阳。","高风动商洛，绮皓无馨香。","一朝下蒲轮，清辉照岩廊。","孤醒立众醉，古道何由昌。","经术震浮荡，国风扫齐梁。","文襟即玄圃，笔下成琳琅。","霞水散吟啸，松筠奉琴觞。","冰壶避皎洁，武库羞锋铓。","小子书代耕，束发颇自强。","艰哉水投石，壮志空摧藏。","十年侣龟鱼，垂头在沅湘。","巴歌揜白雪，鲍肆埋兰芳。","骚雅道未丧，何忧名不彰。","饥寒束困厄，默塞飞星霜。","百志不成一，东波掷年光。","尘生脱粟甑，万里违高堂。","中夜恨火来，焚烧九回肠。","平明梁山泪，缘枕沾匡床。","依泊洞庭波，木叶忽已黄。","哀碪捣秋色，晓月啼寒螀。","复此櫂孤舟，云涛浩茫茫。","朱门待媒势，短褐谁揄扬。","仰羡野陂凫，无心忧稻粱。","不如天边雁，南北皆成行。","男儿白日间，变化未可量。","所希困辱地，剪拂成腾骧。","咋笔话肝肺，咏兹枯鱼章。","何由首西路，目断白云乡。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"沉郁","style2":["婉约","豪放"],"mood":"愁怨","mood2":["孤寂"],"scene":["江","酒","月","花","秋","山"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["秋天"],"人生":["励志","梦想"]},"theme_conf":0.367},{"uid":"73727332-47c2-459f-b186-fef59872a906","title":"相和歌辞 櫂歌行","author":"骆宾王","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["写月图黄罢，凌波拾翠通。","镜花摇芰日，衣麝入荷风。","叶密舟难荡，莲疎浦易空。","凤媒羞自托，鸳翼恨难穷。","秋帐灯花翠，倡楼粉色红。","相思无别曲，幷在櫂歌中。"],"theme":"爱情相思","theme2":["送别"],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["花","舟","秋","月","楼"],"cats":{"抒情":["爱情","思念"],"四季":["秋天"]},"theme_conf":0.536},{"uid":"cp6c37ef5b5bb72d","title":"兰陵王","author":"张元干","dynasty":"宋","section":"宋词","form":"词","paragraphs":["卷朱箔。","朝雨轻阴乍阁。","阑干外，烟柳弄晴，芳草侵阶映红药。","东风妒花恶。","吹落。","梢头嫩萼。","屏山掩，沈水倦熏，中酒心情怕杯勺。","寻思旧京洛。","正年少疏狂，歌笑迷著。","障泥油壁催梳掠。","曾驰道同载，上林携手，灯夜初过早共约。","又争信漂泊。","寂寞。","念行乐。","甚粉淡衣襟，音断弦索。","琼枝璧月春如昨。","怅别后华表，那回双鹤。","相思除是，向醉里、暂忘却。"],"theme":"爱情相思","theme2":["送别","羁旅思乡","咏史怀古"],"style":"冲淡","style2":["豪放","清新"],"mood":"相思","mood2":["欢愉"],"scene":["酒","花","春","楼","夜"],"cats":{"抒情":["爱情","思念","思乡","孤独","怀古"],"四季":["春天"]},"theme_conf":0.317},{"uid":"21500334-b2e4-4199-8c2c-cbff940c9b6d","title":"和裴迪登蜀州东亭送客逢早梅相忆见寄","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["东阁官梅动诗兴，还如何逊在扬州。","此时对雪遥相忆，送客逢春可自由。","幸不折来伤岁暮，若为看去乱乡愁。","江边一树垂垂发，朝夕催人自白头。"],"theme":"送别","theme2":["羁旅思乡"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["冬","楼"],"cats":{"抒情":["思念","思乡","伤感"],"植物":["梅花"]},"theme_conf":0.401},{"uid":"e10bd711-4a4e-40e6-85a7-bcec617b61c0","title":"批叶翘谏书纸尾","author":"闽王王继鹏","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["春色曾看紫陌头，乱红飞尽不禁愁。","人情自厌芳华歇，一叶随风落御沟。"],"theme":"讽喻刺世","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["春","花"],"cats":{"抒情":["伤感"],"四季":["春天"],"人生":["青春"],"植物":["叶子"]},"theme_conf":0.67},{"uid":"06bd32a2-f9f5-4bfe-a55e-fadd67afc789","title":"相和歌辞 饮马长城窟行","author":"王建","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["长城窟，长城窟边多马骨。","古来此地无井泉，赖得秦家筑城卒。","征人饮马愁不回，长城变作望乡堆。","蹄迹未干人去近，续后马来泥污尽。","枕弓睡著待水生，不见阴山在前阵。","马蹄足脱装马头，健儿战死谁封侯。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":["相思","悲怆"],"scene":[],"cats":{"抒情":["思念","思乡","伤感"],"人生":["战争"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.631},{"uid":"80beb8cc-8338-44d4-8b96-7f9d32133c97","title":"西塞山怀古","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["西晋楼船下益州，金陵王气黯然收。","千寻铁锁沈江底，一片降旛出石头。","人世几回伤往事，山形依旧枕江流。","今逢四海为家日，故垒萧萧芦荻秋。"],"theme":"咏史怀古","theme2":[],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["山","塞外"],"cats":{"抒情":["怀古"],"山水":["江河"],"生活":["边塞"]},"theme_conf":0.672},{"uid":"cc0d85da-2fc0-4cd0-9163-b23561e07541","title":"横吹曲辞 陇头吟","author":"王维","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["长安少年游侠客，夜上戍楼看太白。","陇头明月迥临关，陇上行人夜吹笛。","关西老将不胜愁，驻马听之双泪流。","身经大小百余战，麾下偏裨万户侯。","苏武才为典属国，节旄空尽海西头。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["月","夜"],"cats":{"抒情":["伤感"],"天气":["月亮"],"人生":["战争"]},"theme_conf":1.0},{"uid":"ff17b57b-4f6b-4190-93b4-72829ac0e3d3","title":"白菊杂书四首 一","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["黄昏寒立更披襟，露浥清香悦道心。","却笑谁家扃绣户，正薰龙麝暖鸳衾。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["夜","重阳"],"cats":{"抒情":["闺怨"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"a891f80d-fe12-429e-a820-3890a3c6af9e","title":"秋风函谷应诏","author":"徐贤妃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["秋风起函谷，劲气动河山。","偃松千岭上，杂雨二陵间。","低云愁广隰，落日惨重关。","此时飘紫气，应验真人还。"],"theme":"应制干谒","theme2":["山水田园"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"天气":["写风"]},"theme_conf":0.97},{"uid":"6393b72d-7d61-4201-9072-e5589b1637ab","title":"杂曲歌辞 行路难","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见长安城北渭桥边，枯木横槎卧古田。","昔日含红复含紫，常时留雾亦留烟。","春景春风花似雪，香车玉轝恒阗咽。","若个游人不竞攀，若个倡家不来折。","倡家宝袜蛟龙帔，公子银鞍千万骑。","黄莺一向花娇春，两两三三将子戏。","千尺长条百尺枝，丹桂青榆相蔽亏。","珊瑚叶上鸳鸯鸟，凤凰巢里雏鹓儿。","巢倾枝折凤归去，条枯叶落狂风吹。","一朝零落无人问，万古摧残君讵知。","人生贵贱无终始，倏忽须臾难久恃。","谁家能驻西山日，谁家能堰东流水。","汉家陵树满秦川，行来行去尽哀怜。","自昔公卿二千石，咸拟荣华一万年。","不见朱唇将白貌，惟闻素棘与黄泉。","金貂有时须换酒，玉麈但摇莫计钱。","寄言坐客神仙署，一生一死交情处。","苍龙阙下君不来，白鹤山前我应去。","云间海上邈难期，赤心会合在何时？","但愿尧年一百万，长作巢由也不辞。"],"theme":"羁旅思乡","theme2":["哲理悟道","送别","山水田园"],"style":"绮丽","style2":["豪放","雄浑"],"mood":"孤寂","mood2":["悲怆"],"scene":["鸟","春","花","雪"],"cats":{"抒情":["友情","思乡","孤独"],"四季":["春天"],"天气":["写风"],"生活":["写桥"]},"theme_conf":0.35},{"uid":"4f866479-db88-497f-b2b6-29dcb0ec2a63","title":"杂曲歌辞 远别离","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["莲叶团团杏花拆，长江鲤鱼鳍鬣赤。","念君少年弃亲戚，千里万里独为客。","谁言远别心不易，天星坠地能为石。","几时断得城南陌，勿使居人有行役。"],"theme":"送别","theme2":[],"style":"豪放","style2":["冲淡"],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["离别","孤独"],"山水":["长江"]},"theme_conf":0.826},{"uid":"41e2e819-270c-4ae0-acab-8ede9188a7d0","title":"西陵道士茶歌","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["乳窦溅溅通石脉，绿尘愁草春江色。","涧花入井水味香，山月当人松影直。","仙翁白扇霜鸟翎，拂坛夜读黄庭经。","疎香皓齿有余味，更觉鹤心通杳冥。"],"theme":"山水田园","theme2":["闲适隐逸","咏史怀古"],"style":"冲淡","style2":[],"mood":"愁怨","mood2":[],"scene":["鸟","夜","花","春","月","江"],"cats":{"抒情":["伤感","怀古"],"四季":["春天"],"食物":["写茶"]},"theme_conf":0.388},{"uid":"ff2b3cb0-be10-47e9-986f-3fa62c69e727","title":"秋日二首 一","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["菊散金风起，荷疎玉露圆。","将秋数行雁，离夏几林蝉。","云凝愁半岭，霞碎缬高天。","还似成都望，直见峨眉前。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["清新"],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["夏天","秋天"]},"theme_conf":0.667},{"uid":"3701a25a-98c8-4ff3-bfa5-1118d77f8800","title":"答窦援遗卧病见寄","author":"包佶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["今春扶病移沧海，几度承恩对白花。","送客屡闻帘外鹊，销愁已辨酒中虵。","瓶开枸杞悬泉水，鼎炼芙蓉伏火砂。","误入尘埃牵吏役，羞将簿领到君家。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["春","酒","江"],"cats":{"抒情":["伤感"],"四季":["春天"],"山水":["瀑布"]},"theme_conf":0.95},{"uid":"dd0063b6-941f-409a-b14e-e149d44df3a3","title":"舍弟占归草堂检校聊示此诗","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["久客应吾道，相随独尔来。","孰知江路近，频为草堂回。","鹅鸭宜长数，柴荆莫浪开。","东林竹影薄，腊月更须栽。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"旷达","style2":[],"mood":"孤寂","mood2":[],"scene":["月","江"],"cats":{"抒情":["思乡","孤独"],"山水":["庐山"]},"theme_conf":0.624},{"uid":"afb30a0c-422f-4656-b0bb-90174c0d3d1f","title":"长安叙怀寄崔十五","author":"武元衡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["延首直城西，花飞绿草齐。","迢遥隔山水，怅望思游子。","百啭黄鹂细雨中，千条翠柳衡门里。","门对长安九衢路，愁心不惜芳菲度。","风尘冉冉秋复春，钟鼓喧喧朝复暮。","汉家宫阙在中天，紫陌朝臣车马连。","萧萧霓旌合仙杖，悠悠剑佩入炉烟。","李广少时思报国，终军未遇敢论边。","无媒守儒行，荣悴纷相映。","家甚长卿贫，身多公干病。","不知身病竟如何，嬾向青山眠薜萝。","鸡黍空多元伯惠，琴书不见子猷过。","超名累岁与君同，自叹还随鹢退风。","闻说唐生子孙在，何当一为问穷通。"],"theme":"寄赠酬答","theme2":["边塞征战","山水田园"],"style":"沉郁","style2":[],"mood":"慷慨","mood2":["相思","恬淡"],"scene":["雨","春","花"],"cats":{"抒情":["思念","爱国"],"四季":["春天"],"天气":["写雨"]},"theme_conf":0.9},{"uid":"e09998e4-ec09-4118-ac1b-92f7b53b2f7c","title":"寄武陵李少府","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["小县春山口，公孙吏隐时。","楚歌催晚醉，蛮语入新诗。","桂水遥相忆，花源暗有期。","郢门千里外，莫怪尺书迟。"],"theme":"寄赠酬答","theme2":[],"style":"幽峭","style2":[],"mood":"相思","mood2":[],"scene":["春","山","酒"],"cats":{"抒情":["思念"],"四季":["春天"],"植物":["桃花"]},"theme_conf":0.96},{"uid":"eebcac54-df54-47a7-9045-aaa691f418ab","title":"杂曲歌辞 昔昔盐 惊魂同夜鹊","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["万里无人见，众情难与论。","思君常入梦，同鹊屡惊魂。","孤寝红罗帐，双嗁玉筯痕。","妾心甘自保，岂复暂忘恩。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["相思"],"scene":["鸟","夜"],"cats":{"抒情":["孤独"],"动物":["写鸟"]},"theme_conf":0.678},{"uid":"7b1f320f-14f3-4520-9bd8-314be626f5f3","title":"琴曲歌辞 雉朝飞操","author":"张祜","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["朝阳陇东泛暖景，双啄双飞双顾影。","朱冠锦襦聊日整，漠漠雾中如衣褧。","伤心卢女弦，七十老翁长独眠。","雄飞在草雌在田，衷肠结愤气呵天。","圣人在上心不偏，翁得女妻甚可怜。"],"theme":"咏怀抒感","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["塞外"],"cats":{"抒情":["孤独"],"天气":["太阳"]},"theme_conf":0.66},{"uid":"0457d34c-f28a-47a0-aa77-ab3b3a3b14e7","title":"杂曲歌辞 古别离","author":"僧皎然","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["太湖三山口，吴王在时道。","寂寞千载心，无人见春草。","谁堪缄怨者，持此伤怀抱。","孤舟畏狂风，一点宿烟岛。","望所思兮若何，月荡漾兮空波。","云离离兮北断，鴈眇眇兮南多。","身去兮天畔，心折兮湖岸。","春山胡为兮塞路，使我归梦兮撩乱。"],"theme":"送别","theme2":[],"style":"冲淡","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":["春","塞外","舟","山","月"],"cats":{"抒情":["离别","孤独"],"四季":["春天"],"天气":["写风"]},"theme_conf":0.619},{"uid":"cea51298-9d8e-468f-a075-8e843c97e018","title":"自淇涉黄河途中作十三首 十","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["茫茫浊河注，怀古临河滨。","禹功本豁达，汉迹方因循。","坎德昔滂沱，冯夷胡不仁。","激潏陵堤防，东郡多悲辛。","天子忽惊悼，从官皆负薪。","畚筑岂无谋，祈祷如有神。","宣房今安在，高岸空嶙峋。"],"theme":"咏史怀古","theme2":["悼亡挽歌"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["江"],"cats":{"抒情":["伤感","悼亡","怀古"],"山水":["江河","黄河"]},"theme_conf":0.46},{"uid":"38869ec6-7ab2-4c91-b1b1-6772267fdf63","title":"过梅里七首  家于无锡四十载今敝庐数堵犹存今列题于后 忆西湖双㶉𫛶","author":"李绅","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["双㶉𫛶，锦毛斓斑长比翼，戏绕莲藂回锦臆。","照灼花丛两相得，渔歌惊起飞南北。","缭绕追随不迷惑，云间上下同栖息。","不作惊禽远相忆，东家少妇机中语。","剪断回文泣机杼，徒嗟孔雀衔毛羽。","一去东南别离苦，五里裴回竟何补。"],"theme":"咏物","theme2":["送别","民生疾苦","咏史怀古"],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["江南","江"],"cats":{"抒情":["离别","思念","怀古"],"山水":["西湖"],"植物":["梅花"]},"theme_conf":0.85},{"uid":"24f063d6-b3bb-4368-ae89-1e2af8fb3a0f","title":"雨过苏端","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["鸡鸣风雨交，久旱云亦好。","杖藜入春泥，无食起我早。","诸家忆所历，一饭迹便埽。","苏侯得数过，欢喜每倾倒。","也复可怜人，呼儿具梨枣。","浊醪必在眼，尽醉摅怀抱。","红稠屋角花，碧委墙隅草。","亲宾纵谈谑，喧闹畏衰老。","况蒙霈泽垂，粮粒或自保。","妻孥隔军垒，拨弃不拟道。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"欢愉","mood2":[],"scene":["雨"],"cats":{"抒情":["怀古"],"天气":["写雨"]},"theme_conf":1.0},{"uid":"1352fbf1-2c3d-459c-b4ac-061e0c6befb8","title":"杂曲歌辞 长干行二首 一","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["妾发初覆额，折花门前剧。","郎骑竹马来，遶床弄青梅。","同居长干里，两小无嫌猜。","十四为君妇，羞颜尚不开。","低头向暗壁，千唤不一回。","十五始展眉，愿同尘与灰。","常存抱柱信，岂上望夫台。","十六君远行，瞿塘滟预堆。","五月不可触，猨鸣天上哀。","门前迟行迹，一一生绿苔。","苔深不能扫，落叶秋风早。","八月蝴蝶来，双飞西园草。","感此伤妾心，坐愁红颜老。","早晚下三巴，预将书报家。","相迎不道远，直至长风沙。"],"theme":"羁旅思乡","theme2":["闺情宫怨"],"style":"沉郁","style2":["豪放","清新"],"mood":"愁怨","mood2":["悲怆"],"scene":["秋","月","花"],"cats":{"抒情":["思乡","伤感","闺怨"],"四季":["秋天"],"天气":["写风"]},"theme_conf":0.557},{"uid":"6a35a5c8-851b-4f2d-aa73-a0fd3b2fd2b6","title":"郑驸马宅宴洞中","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["主家阴洞细烟雾，留客夏簟清琅玕。","春酒杯浓琥珀薄，冰浆椀碧玛瑙寒。","误疑茅堂过江麓，已入风磴霾云端。","自是秦楼压郑谷，时闻杂佩声珊珊。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["酒","夏","春"],"cats":{"抒情":["思乡"],"四季":["春天","夏天"],"动物":["写马"]},"theme_conf":1.0},{"uid":"aa7d3545-a694-4336-8852-5d491c106b50","title":"相和歌辞 挽歌","author":"赵微明","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["寒日蒿上明，凄凄郭东路。","素车谁家子，丹旐引将去。","原下荆棘丛，丛边有新墓。","人间痛伤别，此是长别处。","旷野何萧条，青松白杨树。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["悲怆"],"scene":[],"cats":{"抒情":["伤感","悼亡"]},"theme_conf":0.99},{"uid":"cp71daa4431df0fe","title":"混江龙・他若是含情一笑，朱唇一颗嵌樱桃。梨花玉体，杨柳纤腰。眉黛","author":"赵彦晖","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["春山娇滴滴，眼波秋水绿淘淘。","可观可看，宜喜宜嗔。","堪怜堪爱，难画难描。","拨银筝音吕韵悠扬，唱阳春白雪依腔调。","你便有千金买笑，怎能够一刻春宵。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["旷达","婉约"],"mood":"欢愉","mood2":[],"scene":["江","春","花","雪","秋"],"cats":{"抒情":["闺怨"],"四季":["春天","秋天"],"植物":["梨花","桃花","柳树"]},"theme_conf":0.694},{"uid":"ab09e37b-0114-49f7-ab82-56480afb3d9e","title":"游子行","author":"聂夷中","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["萱草生堂阶，游子行天涯。","慈亲倚门望，不见萱草花。"],"theme":"亲情","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["思念"],"人物":["母亲"]},"theme_conf":0.68},{"uid":"88d4489c-981b-416d-97bd-d7de86b432d8","title":"九日与敬处士左学士同赋采菊上东山便为首句","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["采菊上东山，山高路非远。","江湖乍辽敻，城郭亦在眼。","昼日市井喧，闰年禾稼晚。","开尊会佳客，长啸临绝𪩘。","戏鹤唳且闲，断云轻不卷。","乡心各万里，醉话时一展。","乔木列遥天，残阳贯平坂。","徒忧征车重，自笑谋虑浅。","却顾郡斋中，寄傲与君同。"],"theme":"节令风俗","theme2":["山水田园","羁旅思乡"],"style":"豪放","style2":[],"mood":"恬淡","mood2":["愁怨","欢愉"],"scene":["重阳","山"],"cats":{"抒情":["思乡"],"天气":["太阳"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.88},{"uid":"bf8918b8-a05a-4ccf-bb2e-3f9b81f6bbfc","title":"渡荆门送别","author":"李白","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["渡远荆门外，来从楚国游。","山随平野尽，江入大荒流。","月下飞天镜，云生结海楼。","仍连故乡水，万里送行舟。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["江"],"cats":{"抒情":["离别","思乡"]},"theme_conf":0.747},{"uid":"58ba4d44-398a-4af4-9ae5-764f809b0de1","title":"绝句漫兴九首 七","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["糁径杨花铺白毡，点溪荷叶叠青钱。","笋根稚子无人见，沙上凫雏傍母眠。"],"theme":"山水田园","theme2":["亲情"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["夏"],"cats":{"抒情":["孤独"],"四季":["夏天"],"人物":["儿童"]},"theme_conf":0.593},{"uid":"9fa92cdf-24cf-4a6a-af33-db5809652091","title":"杂曲歌辞 秋夜曲二首 一","author":"王建","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["天清漏长霜泊泊，兰绿收荣桂膏涸。","高楼云鬟弄婵娟，古瑟暗断秋风弦。","玉关遥隔万里道，金刀不翦双泪泉。","香囊火死香气少，向帷合眼何时晓？","城乌作营嗁野月，秦川少妇生离别。"],"theme":"送别","theme2":[],"style":"清新","style2":["婉约","绮丽"],"mood":"愁怨","mood2":["悲怆"],"scene":["秋","夜"],"cats":{"抒情":["离别","伤感"],"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.511},{"uid":"faada38b-ba84-4066-b426-10159e66011b","title":"陪诸贵公子丈八沟携妓纳凉晚际遇雨二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["雨来沾席上，风急打船头。","越女红帬湿，燕姬翠黛愁。","缆侵隄柳系，幔宛浪花浮。","归路飜萧飒，陂塘五月秋。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["雨"],"cats":{"抒情":["伤感","闺怨"],"天气":["写雨"]},"theme_conf":0.65},{"uid":"12c990df-c417-480a-aa17-39836764b4ef","title":"湘岸移木芙蓉植龙兴精舍","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["有美不自蔽，安能守孤根。","盈盈湘西岸，秋至风露繁。","丽影别寒水，秾芳委前轩。","芰荷谅难杂，反此生高原。"],"theme":"山水田园","theme2":["送别"],"style":"清新","style2":["婉约"],"mood":"孤寂","mood2":["欢愉"],"scene":["秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"植物":["荷花"]},"theme_conf":0.621},{"uid":"b750e80a-f2d3-4197-b1cb-45c9e7251ddd","title":"新年第二夜荅处上人宿玉芝观见寄","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["阳春已三日，会友闻昨夜。","可爱剡溪僧，独寻陶景舍。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["夜"],"cats":{"抒情":["孤独"],"节日":["春节"]},"theme_conf":0.93},{"uid":"6db52079-cf43-4b08-ba0d-edbc69eebe29","title":"相和歌辞 团扇郎","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["团扇复团扇，奉君清暑殿。","秋风入庭树，从此不相见。","上有乘鸾女，苍苍虫网遍。","明年入怀袖，别是机中练。"],"theme":"闺情宫怨","theme2":[],"style":"雄浑","style2":[],"mood":"愁怨","mood2":[],"scene":["夏","秋","园林"],"cats":{"抒情":["闺怨"],"四季":["夏天","秋天"]},"theme_conf":0.505},{"uid":"46503396-3bb3-449c-9c84-f2ff232f7949","title":"寄全椒山中道士","author":"韦应物","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["今朝郡斋冷，忽念山中客。","涧底束荆薪，归来煮白石。","欲持一瓢酒，远慰风雨夕。","落叶满空山，何处寻行迹。"],"theme":"山水田园","theme2":["送别","羁旅思乡"],"style":"幽峭","style2":["冲淡"],"mood":"相思","mood2":[],"scene":["山","雨"],"cats":{"抒情":["思乡"]},"theme_conf":0.382},{"uid":"56164c0c-6a83-4c3b-8f92-4c26a6e8e34e","title":"送从弟谒员外叔父回归义兴","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["异乡兄弟少，见尔自依然。","来酌林中酒，去耕湖上田。","何朝逢暑雨，几夜泊鱼烟。","余力当勤学，成名贵少年。"],"theme":"送别","theme2":["羁旅思乡","亲情"],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["酒","夏"],"cats":{"抒情":["思乡"],"四季":["夏天"],"人物":["父亲"]},"theme_conf":0.296},{"uid":"8474f5c4-d18e-4b42-9702-19ad909b9ea2","title":"哀江头","author":"杜甫","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["少陵野老吞声哭，春日潜行曲江曲。","江头宫殿锁千门，细柳新蒲为谁绿。","忆昔霓旌下南苑，苑中万物生颜色。","昭阳殿里第一人，同辇随君侍君侧。","辇前才人带弓箭，白马嚼啮黄金勒。","翻身向天仰射云，一箭正坠双飞翼。","明眸皓齿今何在，血污游魂归不得。","清渭东流劒阁深，去住彼此无消息。","人生有情泪沾臆，江水江花岂终极。","黄昏胡骑尘满城，欲往城南忘南北。"],"theme":"咏史怀古","theme2":["边塞征战"],"style":"沉郁","style2":["悲慨"],"mood":"悲怆","mood2":["愁怨"],"scene":["江"],"cats":{"抒情":["伤感","闺怨","怀古"],"山水":["江河"]},"theme_conf":0.9},{"uid":"12919986-2d09-4d2e-b5ad-f2485e40ada5","title":"登楼","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["花近高楼伤客心，万方多难此登临。","锦江春色来天地，玉垒浮云变古今。","北极朝廷终不改，西山寇盗莫相侵。","可怜后主还祠庙，日暮聊为梁甫吟。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":["悲慨"],"mood":"惆怅","mood2":[],"scene":["楼"],"cats":{"抒情":["怀古"]},"theme_conf":0.63},{"uid":"c19e64b1-604b-40b7-9e41-6ef57b9c6f7b","title":"别房太尉墓","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["他乡复行役，驻马别孤坟。","近泪无干土，低空有断云。","对碁陪谢傅，把劒觅徐君。","唯见林花落，鸎啼送客闻。"],"theme":"悼亡挽歌","theme2":["送别"],"style":"沉郁","style2":["悲慨","婉约"],"mood":"愁怨","mood2":["孤寂","悲怆"],"scene":[],"cats":{"抒情":["离别","伤感","孤独","悼亡"]},"theme_conf":0.96},{"uid":"e3553a22-2323-4926-a694-752c3481e2a5","title":"阆州东楼筵奉送十一舅往青城县得昏字","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["曾城有高楼，制古丹雘存。","迢迢百余尺，豁达开四门。","虽有车马客，而无人世喧。","游目俯大江，列筵慰别魂。","是时秋冬交，节往颜色昏。","天寒鸟兽休，霜露在草根。","今我送舅氏，万感集清尊。","岂伊山川间，回首盗贼繁。","高贤意不暇，王命久崩奔。","临风欲恸哭，声出已复吞。"],"theme":"送别","theme2":[],"style":"旷达","style2":["清新","沉郁"],"mood":"悲怆","mood2":["孤寂"],"scene":["楼","秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["长江"]},"theme_conf":1.0},{"uid":"06203cef-1dc5-4d60-9ef7-a4bf4306c730","title":"送裴补阙入河南幕","author":"郎士元","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["皎然青琐客，何事动行轩。","苦节酬知己，清吟去掖垣。","秋城临海树，寒月上营门。","邹鲁诗书国，应无鼙鼓喧。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","月"],"cats":{"抒情":["友情"],"四季":["秋天"],"人生":["读书"]},"theme_conf":1.0},{"uid":"18134617-3a61-4d5a-a0c2-3d80b54099f6","title":"步出武陵东亭临江寓望","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["鹰至感风候，霜余变林麓。","孤颿带日来，寒江转沙曲。","戍摇旗影动，津晚橹声促。","月上彩霞收，渔歌远相续。"],"theme":"山水田园","theme2":["咏史怀古","边塞征战"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["孤独","怀古"],"山水":["江河"],"植物":["桃花"]},"theme_conf":0.425},{"uid":"f8d102c4-b25b-412f-afce-35db35c339d9","title":"宫词","author":"薛逢","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["十二楼中尽晓妆，望仙楼上望君王。","锁衔金兽连环冷，水滴铜龙昼漏长。","云髻罢梳还对镜，罗衣欲换更添香。","遥窥正殿帘开处，袍袴宫人扫御床。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":["绮丽"],"mood":"愁怨","mood2":[],"scene":["夜","楼"],"cats":{"抒情":["闺怨"]},"theme_conf":1.0},{"uid":"e11e3a24-c739-4054-b66f-2d7ae8ca09dd","title":"游长宁公主流杯池二十五首 九","author":"上官昭容","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["登山一长望，正遇九春初。","结驷填街术，闾阎满邑居。","鬬雪梅先吐，惊风柳未舒。","直愁斜日落，不畏酒尊虚。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"愁怨","mood2":[],"scene":["酒"],"cats":{"抒情":["伤感"],"食物":["写酒"]},"theme_conf":0.65},{"uid":"18970206-4b28-4c5e-974f-a9ef44cbc9a7","title":"得山中道友书寄苗銭二员外","author":"李端","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["有谋皆𫐘轲，非病亦迟回。","壮志年年减，驰晖日日催。","还山不及伴，到阙又无媒。","高卧成长策，微官称下才。","诗人识何谢，居士别宗雷。","迹向尘中隐，书从谷口来。","药栏遭鹿践，涧户被猿开。","野鹤巢云窦，游龟上水苔。","新欢追易失，故思渺难裁。","自有归期在，劳君示劫灰。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"慷慨","mood2":["欢愉"],"scene":["山"],"cats":{"抒情":["友情"],"人生":["励志","梦想"]},"theme_conf":0.88},{"uid":"3ec9cb88-517c-4922-a82e-e6cc561ace29","title":"往在","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["往在西京日，胡来满彤宫。","中宵焚九庙，云汉为之红。","解瓦飞十里，𰬸帷纷曾空。","疚心惜木主，一一灰悲风。","合昏排铁骑，清旭散锦𩦺贼臣表逆节，相贺以成功。","是时妃嫔戮，连为粪土丛。","当宁陷玉座，白间剥画虫。","不知二圣处，私泣百岁翁。","车驾既云还，楹桷歘穹崇。","故老复涕泗，祠官树椅桐。","宏壮不如初，已见帝力雄。","前春礼郊庙，祀事亲圣躬。","微躯忝近臣，景从陪群公。","登阶捧玉册，峨冕耿金钟。","侍祠恧先露，掖垣迩濯龙。","天子惟孝孙，五云起九重。","镜匳换粉黛，翠羽犹葱胧。","前者厌羯胡，后来遭犬戎。","俎豆腐膻肉，罘罳行角弓。","安得自西极，申命空山东。","尽躯诣阙下，士庶塞关中。","主将晓逆顺，元元归始终。","一朝自罪己，万里车书通。","锋镝供锄犂，征戍听所从。","冗官各复业，土著还力农。","君臣节俭足，朝野欢呼同。","中兴似国初，继体如太宗。","端拱纳谏诤，和风日冲融。","赤墀樱桃枝，隐映银丝笼。","千春荐陵寝，永永垂无穷。","京都不再火，泾渭开愁容。","归号故松柏，老去苦飘蓬。"],"theme":"边塞征战","theme2":["山水田园"],"style":"绮丽","style2":[],"mood":"悲怆","mood2":["愁怨","欢愉"],"scene":["春","塞外"],"cats":{"抒情":["伤感"],"四季":["春天"],"生活":["田野","边塞"]},"theme_conf":0.516},{"uid":"c244a5b4-0ed0-48fe-8694-95309acac184","title":"登幽州台歌","author":"陈子昂","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["前不见古人，后不见来者。","念天地之悠悠，独怆然而涕下。"],"theme":"咏史怀古","theme2":["闲适隐逸"],"style":"悲慨","style2":[],"mood":"愁怨","mood2":["相思","孤寂"],"scene":["楼"],"cats":{"抒情":["思念","孤独","怀古"]},"theme_conf":0.526},{"uid":"16dea403-c108-4546-89a5-18e8f1d3373c","title":"相和歌辞 短歌行六首 二","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["我欲升天天隔霄，我思渡水水无桥。","我欲上山山路险，我欲汲井井泉遥。","越人翠被今何夕，独立沙边江草碧。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["山","江南","江"],"cats":{"抒情":["孤独"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"e4545449-1757-4265-96bb-8fb65870b953","title":"池州夫子庙麟台","author":"韦表微","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["二仪既闭，三象乃乖。","圣道埋郁，人心不开。","上无文武，下有定哀。","吁嗟麟兮，孰为来哉。","周虽不纲，孔实嗣圣。","诗书既删，礼乐大定。","劝善惩恶，奸邪乃正。","吁嗟麟兮，克昭符命。","圣与时合，化行位尊。","苟或乖戾，身穷道存。","于昭鲁邑，栖迟孔门。","吁嗟麟兮，孰知其仁。","运极数残，德至时否。","楚国寖广，秦封益侈。","墙仞迫阨，崎岖阙里。","吁嗟麟兮，靡有攸止。","世治则麟，世乱则麕。","出非其时，麋鹿同群。","孔不自圣，麟不自祥。","吁嗟麟兮，天何所亡。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["园林","楼"],"cats":{"抒情":["怀古"],"人物":["老师"],"人生":["读书"]},"theme_conf":0.9},{"uid":"4b28f85a-4497-40f0-b1c5-ed939c384dc2","title":"酬谢侍御喜王宇及第见贺不遇之作","author":"严维","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["寂寞柴门掩，经过柱史荣。","老夫宁有力，半子自成名。","柳映三桥发，花连上道明。","缄书到别墅，郢曲果先成。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":["孤寂"],"scene":[],"cats":{"抒情":["孤独","感恩"],"生活":["写桥"]},"theme_conf":0.96},{"uid":"8eeb3273-d271-4674-900b-2057c3f59957","title":"杂曲歌辞 结客少年场行","author":"虞世南","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["韩魏多奇节，倜傥遗名利。","共矜然诺心，各负纵横志。","结友一言重，相思千里至。","绿沈明月弦，金络浮云辔。","吹箫入吴市，击筑游燕肆。","寻源博望侯，结客远相求。","少年重一顾，长驱背陇头。","燄燄霜戈动，耿耿劒虹浮。","天山冬夏雪，交河南北流。","云起龙沙暗，木落鴈行秋。","轻生徇知己，非是为身谋。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"清新","style2":["豪放"],"mood":"相思","mood2":[],"scene":["月","冬","秋","夏","雪"],"cats":{"抒情":["友情","思念","思乡"],"四季":["夏天","秋天","冬天"],"天气":["月亮"],"人生":["青春"]},"theme_conf":0.495},{"uid":"98b0fd3d-e436-43bb-98b3-3949c75a902a","title":"三星行","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["我生之辰，月宿南斗。","牛奋其角，箕张其口。","牛不见服箱，斗不挹酒浆。","箕独有神灵，无时停簸扬。","无善名已闻，无恶声已讙。","名声相乘除，得少失有余。","三星各在天，什伍东西陈。","嗟汝牛与斗，汝独不能神。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["酒","月"],"cats":{"抒情":["思乡","孤独"],"天气":["星星"]},"theme_conf":0.65},{"uid":"6d47c928-e6dd-4417-a9a5-acb7d4272e84","title":"新乐府 陵园妾\t怜幽闭也","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["陵园妾，颜色如花命如叶。","命如叶薄将奈何，一奉寝宫年月多。","年月多，时光换，春愁秋思知何限。","青丝发落丛鬓疎，红玉肤销系帬慢。","忆昔宫中被妬猜，因谗得罪配陵来。","老母啼呼趁车别，中官监送鏁门回。","山宫一闭无开日，未死此身不令出。","松门到晓月裴回，柏城尽日风萧瑟。","松门柏城幽闭深，闻蝉听燕感光阴。","眼看菊蘂重阳泪，手把棃花寒食心。","把花掩泪无人见，绿芜墙绕青苔院。","四季徒支妆粉钱，三朝不识君王面。","遥想六宫奉至尊，宣徽雪夜浴堂春。","雨露之恩不及者，犹闻不啻三千人。","三千人，我尔君恩何厚薄。","愿令轮转直陵园，三岁一来均苦乐。"],"theme":"闺情宫怨","theme2":["送别","节令风俗"],"style":"沉郁","style2":["清新"],"mood":"愁怨","mood2":["欢愉"],"scene":["园林","重阳"],"cats":{"抒情":["伤感","闺怨"],"人物":["母亲"],"人生":["时光"],"节日":["寒食节","重阳节"]},"theme_conf":0.266},{"uid":"8399a509-3f09-4027-a389-f5c4ba9e5dfe","title":"送李翺习之","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["习之势翩翩，东南去遥遥。","赠君双履足，一为上臯桥。","臯桥路逶迤，碧水清风飘。","新秋折藕花，应对吴语娇。","千巷分渌波，四门生早潮。","湖榜轻褭褭，酒旗高寥寥。","小时屐齿痕，有处应未销。","旧忆如雾星，怳见于梦消。","言之烧人心，事去不可招。","独孤宅前曲，箜篌醉中谣。","壮年俱悠悠，逮兹各焦焦。","执手复执手，唯道无枯凋。"],"theme":"送别","theme2":[],"style":"清新","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":["酒","江","秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"人物":["老师"],"生活":["写桥"]},"theme_conf":0.8},{"uid":"ae6937be-51cb-4b1f-b735-cfa0644fd547","title":"相和歌辞 江南曲八首 五","author":"刘希夷","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["舣舟乘潮去，风帆振草凉。","潮平见楚甸，天际望维扬。","洄溯经千里，烟波接两乡。","云明江屿出，日照海流长。","此中逢岁晏，浦树落花芳。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["江","江南"],"cats":{"抒情":["思乡"],"山水":["江河"]},"theme_conf":1.0},{"uid":"8eaf97fd-82bb-4651-9dde-9a5a6f78182c","title":"春宫怨","author":"杜荀鹤","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["早被婵娟误，欲妆临镜慵。","承恩不在貌，教妾若为容。","风暖鸟声碎，日高花影重。","年年越溪女，相忆采芙蓉。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"节日":["中秋节"]},"theme_conf":0.76},{"uid":"9715a2f1-2b9f-459e-9d0d-36e9c5b78544","title":"又酬晓灯[离暗]室五首 二","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["寒灯扬晓焰，重屋惊春雨。","应想远行人，路逢泥泞阻。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["元宵","夜"],"cats":{"抒情":["离别","思乡"],"节日":["元宵节"]},"theme_conf":0.73},{"uid":"9e40d9e8-6894-423e-a22e-41f78c97937a","title":"读谢灵运诗","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["吾闻达士道，穷通顺冥数。","通乃朝廷来，穷即江湖去。","谢公才廓落，与世不相遇。","壮志郁不用，须有所泄处。","泄为山水诗，逸韵谐奇趣。","大必笼天海，细不遗草树。","岂惟玩景物，亦欲摅心素。","往往即事中，未能忘兴谕。","因知康乐作，不独在章句。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":["慷慨","孤寂"],"scene":["江"],"cats":{"抒情":["孤独","感恩"],"人生":["励志","梦想"]},"theme_conf":1.0},{"uid":"9ce3f413-a677-4e46-a301-43f8be3a40c2","title":"琴曲歌辞 双燕离","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["双燕复双燕，双飞令人羡。","玉楼珠阁不独栖，金窗绣户长相见。","柏梁失火去，因入吴王宫。","吴宫又焚荡，雏尽巢亦空。","憔悴一身在，孀雌忆故雄。","双飞难再得，伤我寸心中。"],"theme":"咏物","theme2":["爱情相思","咏史怀古","闲适隐逸"],"style":"绮丽","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["鸟","楼"],"cats":{"抒情":["离别","孤独","怀古"],"动物":["写鸟"]},"theme_conf":0.9},{"uid":"94b9c1e7-9b5f-4925-bd3d-9499f3f1e4ec","title":"和姚令公哭李尚书乂","author":"张九龄","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["贵贱虽殊等，平生窃下风。","云泥势已绝，山海纳还通。","忽叹登龙者，翻将吊鹤同。","琴诗犹可托，剑履独成空。","畴昔尝论礼，兴言每匪躬。","人思崔琰议，朝掩祭遵公。","作善神何酷，依仁命不融。","天文虚北斗，人事罢南宫。","上幸既伤旧，下流弥感衷。","无恩报国士，徒欲问玄穹。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":["豪放"],"mood":"悲怆","mood2":["慷慨","孤寂"],"scene":[],"cats":{"抒情":["伤感","孤独","悼亡","爱国"]},"theme_conf":0.93},{"uid":"a36d2096-432b-4a13-8527-0110a781f74f","title":"送李明府赴连州","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["万里向南湘，孤舟入桂阳。","诸侯迎上客，小吏拜官郎。","春服橦花细，初筵木槿芳。","看承雨露速，不待荔枝香。"],"theme":"送别","theme2":[],"style":"婉约","style2":["豪放","清新"],"mood":"孤寂","mood2":[],"scene":["花","舟","春"],"cats":{"抒情":["孤独"],"四季":["春天"],"食物":["荔枝"]},"theme_conf":0.538},{"uid":"cpfeda664cad7f2d","title":"贺新郎","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["绿树听鹈。","更那堪、鹧鸪声住，杜鹃声切。","啼到春归无寻处，苦恨芳菲都歇。","算未抵、人间离别。","马上琵琶关塞黑，更长门、翠辇辞金阙。","看燕燕，送归妾。","将军百战身名裂。","向河梁、回头万里，故人长绝。","易水萧萧西风冷，满座衣冠似雪。","正壮士、悲歌未彻。","啼鸟还知如许恨，料不啼清泪长啼血。","谁共我，醉明月。"],"theme":"送别","theme2":["边塞征战","闺情宫怨"],"style":"清新","style2":["悲慨","沉郁"],"mood":"愁怨","mood2":[],"scene":["鸟","春","月"],"cats":{"抒情":["友情","离别","伤感","闺怨"],"四季":["春天"],"天气":["月亮"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.357},{"uid":"0879b3a8-9a54-4a34-9746-c2490ef2497e","title":"抱疾谢李吏部赠诃黎勒叶","author":"包佶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["一叶生西徼，赍来上海查。","岁时经水府，根本别天涯。","方士真难见，商胡辄自夸。","此香同异域，看色胜仙家。","茗饮暂调气，梧丸喜伐邪。","幸蒙祛老疾，深愿驻韶华。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"抒情":["感恩"],"植物":["叶子"]},"theme_conf":0.88},{"uid":"25eeaa0b-dad0-4164-bb62-1896bdb82443","title":"詶国子崔博士立之见寄","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["健笔高科早绝伦，后来无不揖芳尘。","遍看今日乘轩客，多是昔年呈卷人。","胄子执经瞻讲坐，郎官共食接华茵。","烦君远寄相思曲，慰问天南一逐臣。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["思念"],"人物":["老师"]},"theme_conf":0.98},{"uid":"96afd27a-b059-4d11-9430-d3bf951080a3","title":"题商山店","author":"韩琮","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["商山驿路几经过，未到仙娥见谢娥。","红锦机头抛皓腕，绿云鬟下送横波。","佯嗔阿母留宾客，暗为王孙换绮罗。","碧涧门前一条水，岂知平地有天河。"],"theme":"爱情相思","theme2":["羁旅思乡","咏物"],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"抒情":["思乡"],"人物":["母亲"]},"theme_conf":0.8},{"uid":"cp97068e7a4cc0ab","title":"三姝媚","author":"史达祖","dynasty":"宋","section":"宋词","form":"词","paragraphs":["烟光摇缥瓦。","望晴檐多风，柳花如洒。","锦瑟横床，想泪痕尘影，凤弦常下。","倦出犀帷，频梦见、王孙骄马。","讳道相思，偷理绡裙，自惊腰衩。","惆怅南楼遥夜。","记翠箔张灯，枕肩歌罢。","又入铜驼，遍旧家门巷，首询声价。","可惜东风，将恨与、闲花俱谢。","记取崔徽模样，归来暗写。"],"theme":"爱情相思","theme2":["羁旅思乡"],"style":"沉郁","style2":["绮丽"],"mood":"相思","mood2":["愁怨"],"scene":["夜","楼"],"cats":{"抒情":["爱情","思念","思乡","伤感"]},"theme_conf":0.577},{"uid":"195ac36f-552e-4cc2-9e99-6d8c0cc93b72","title":"杂曲歌辞 少年行二首 一","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["官为骏马监，职帅羽林儿。","两绶藏不见，落花何处期？","猎敲白玉镫，怒袖紫金锤。","田窦长留醉，苏辛曲护岐。","豪持出塞节，笑别远山眉。","捷报云台贺，公卿拜寿巵。"],"theme":"边塞征战","theme2":["送别","羁旅思乡"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["塞外","酒","山"],"cats":{"抒情":["思乡"],"人生":["青春"],"生活":["边塞"]},"theme_conf":0.409},{"uid":"cp64bdebe2320818","title":"谢金莲诗酒红梨花・梁州第七","author":"张寿卿","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["不离了这花阴柳影，也强如绣帏中冷冷清清。","想才郎没半米儿尘俗性。","他比着那谢东山后嗣，杜工部门生，潘安仁颜貌，曹子建才能，他生的才貌相应。","虽不设海誓山盟，他、他、他，端的有千种风情，俺、俺、俺，办着个十分志诚，敢、敢、敢，成合了一世的前程。","对着这良宵，媚景。","玉纤重把罗衣整，露湿的绣鞋儿冷。","绕遍园池过小亭，怎敢稍停？。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":["花","酒","园林"],"cats":{"抒情":["闺怨","感恩"],"人物":["老师"],"植物":["梨花","荷花"],"食物":["写酒"]},"theme_conf":1.0},{"uid":"ea100f9a-3504-4a7d-844c-c23ba23f364b","title":"将适吴楚留别章使君留后兼幕府诸公得柳字","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["我来入蜀门，岁月亦已久。","岂惟长儿童，自觉成老丑。","常恐性坦率，失身为杯酒。","近辞痛饮徒，折节万夫后。","昔如纵壑鱼，今如丧家狗。","既无游方恋，行止复何有。","相逢半新故，取别随薄厚。","不意青草湖，扁舟落吾手。","眷眷章梓州，开筵俯高柳。","楼前出骑马，帐下罗宾友。","健儿簸红旗，此乐或难朽。","日车隐昆仑，鸟雀噪户牖。","波涛未足畏，三峡徒雷吼。","所忧盗贼多，重见衣冠走。","中原消息断，黄屋今安否。","终作适荆蛮，安排用庄叟。","随云拜东皇，挂席上南斗。","有使即寄书，无使长回首。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["舟","酒","江南"],"cats":{"抒情":["离别"],"人物":["儿童"],"植物":["柳树"]},"theme_conf":0.715},{"uid":"cp3a5031bf7e3981","title":"拜星月・拜星月慢","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["夜色催更，清尘收露，小曲幽坊月暗。","竹槛灯窗，识秋娘庭院。","笑相遇，似觉琼枝玉树相倚，暖日明霞光烂。","水眄兰情，总平生稀见。","画图中、旧识春风面。","谁知道、自到瑶台畔。","眷恋雨润云温，苦惊风吹散。","念荒寒、寄宿无人馆。","重门闭、败壁秋虫叹。","怎奈向、一缕相思，隔溪山不断。"],"theme":"山水田园","theme2":["爱情相思","游仙梦幻"],"style":"清新","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["月","园林","夜"],"cats":{"抒情":["爱情","思念","孤独"],"天气":["月亮","星星"]},"theme_conf":0.359},{"uid":"36b6f467-dc98-4ac0-9b1b-316b4a65db43","title":"连州吟 二","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["羽翼不自有，相追力难任。","唯凭方寸灵，独夜万里寻。","方寻魂飘飖，南梦山岖嵚。","髣髴惊魍魉，悉窣闻枫林。","正直被放者，鬼魅无所侵。","贤人多安排，俗士多虚钦。","孤怀吐明月，众毁铄黄金。","愿君保玄曜，壮志无自沉。"],"theme":"游仙梦幻","theme2":[],"style":"幽峭","style2":["旷达","豪放"],"mood":"孤寂","mood2":[],"scene":["月"],"cats":{"抒情":["孤独"],"天气":["月亮"],"人生":["励志","梦想"]},"theme_conf":0.65},{"uid":"1f6ef42b-eb0a-49f8-971b-d59a58ec6239","title":"百丈谿新理茅茨读书","author":"阎防","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["浪迹弃人世，远山自幽独。","始傍巢由踪，吾其获心曲。","荒庭何所有，老树半空腹。","秋蜩鸣北林，暮鸟穿我屋。","栖迟乐遵渚，恬旷寡所欲。","开卦推盈虚，散帙攻节目。","养闲度人事，达命知止足。","不学东周儒，俟时劳伐辐。"],"theme":"闲适隐逸","theme2":[],"style":"沉郁","style2":["冲淡"],"mood":"孤寂","mood2":["欢愉","恬淡"],"scene":["秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"人生":["读书"]},"theme_conf":0.9},{"uid":"3c480b6c-f2a8-4726-8cdd-1e4c8c54f2d7","title":"哭灵一上人","author":"严维","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["一公何不住，空有远公名。","共说岑山路，今时不可行。","旧房松更老，新塔草初生。","经论传缁侣，文章遍墨卿。","禅林枝干折，法宇栋梁倾。","谁复修僧史，应知传已成。"],"theme":"悼亡挽歌","theme2":["哲理悟道"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["山"],"cats":{"抒情":["悼亡"],"人生":["哲理"]},"theme_conf":0.97},{"uid":"c1ab438f-0521-4b14-8056-9e57eb77a87a","title":"采莲子二首 一","author":"皇甫松","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["菡萏香连十顷陂，小姑贪戏采莲迟。","晚来弄水船头湿，更脱红裙裹鸭儿。"],"theme":"爱情相思","theme2":["闺情宫怨"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["花","舟"],"cats":{"抒情":["闺怨"],"植物":["荷花"]},"theme_conf":0.636},{"uid":"26cbab92-a321-44e6-842b-13acc9749fc0","title":"羌村 三","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["群鸡正乱叫，客至鸡鬬争。","驱鸡上树木，始闻叩柴荆。","父老四五人，问我久远行。","手中各有携，倾榼浊复清。","苦辞酒味薄，黍地无人耕。","兵革既未息，儿童尽东征。","请为父老歌，艰难块深情。","歌罢仰天叹，四座泪纵横。"],"theme":"山水田园","theme2":["边塞征战"],"style":"豪放","style2":["沉郁"],"mood":"愁怨","mood2":["孤寂"],"scene":["酒"],"cats":{"抒情":["伤感","孤独"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.379},{"uid":"3909f623-a817-420a-9fd9-b6e1f2722909","title":"睡后茶兴忆杨同州","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昨晚饮太多，嵬峩连宵醉。","今朝餐又饱，烂熳移时睡。","睡足摩挲眼，眼前无一事。","信脚绕池行，偶然得幽致。","婆娑绿阴树，斑駮青苔地。","此处置绳床，傍边洗茶器。","白瓷瓯甚洁，红炉炭方炽。","沫下曲尘香，花浮鱼眼沸。","盛来有佳色，咽罢余芳气。","不见杨慕巢，谁人知此味。"],"theme":"闲适隐逸","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["花"],"cats":{"抒情":["思念"],"食物":["写茶"]},"theme_conf":0.8},{"uid":"eff8686f-2cb8-4d15-9adb-7439085544ad","title":"过梅里七首  家于无锡四十载今敝庐数堵犹存今列题于后 忆东郭居","author":"李绅","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔余过稚齿，从师昧知奥。","徒怀利物心，不获藏身宝。","曳娄一缝掖，出处劳昏早。","醒醉迷啜哺，衣裳辨颠倒。","忠诚贯白日，直己凭苍昊。","卷舌堕谗谀，惊波息行潦。","衰禽识旧木，疲马知归道。","杨柳长庭柯，兰荃覆阶草。","旌旄光里舍，骑服欢妻嫂。","绿鬓绝新知，苍须稀旧老。","冠緌身忝贵，斋沐心常祷。","笙磬谅谐和，庭除还洒扫。","栖迟还竹巷，物役浸江岛。","倏忽变星霜，悲伤满衷抱。"],"theme":"咏怀抒感","theme2":["羁旅思乡","咏物","讽喻刺世"],"style":"清新","style2":[],"mood":"相思","mood2":["悲怆","欢愉"],"scene":["园林","冬"],"cats":{"抒情":["思念","思乡","伤感"],"植物":["梅花"]},"theme_conf":0.75},{"uid":"da157c27-d317-4205-9cdc-a254445659fc","title":"落花","author":"李商隐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["高阁客竟去，小园花乱飞。","参差连曲陌，迢遰送斜晖。","肠断未忍扫，眼穿仍欲归。","芳心向春尽，所得是沾衣。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["花"],"cats":{"抒情":["伤感"]},"theme_conf":0.433},{"uid":"1f0f728d-0c02-4fd4-9976-ba6f0cba1c12","title":"相和歌辞 采莲归","author":"王勃","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["采莲归，绿水芙蓉衣，秋风起浪凫雁飞。","桂棹兰桡下长浦，罗裙玉腕摇轻橹。","叶屿花潭极望平，江讴越吹相思苦。","相思苦，佳期不可驻。","塞外征夫犹未还，江南采莲今已暮。","今已暮，摘莲花，今渠那必尽倡家。","官道城南把桑叶，何如江上采莲花？","莲花复莲花，花叶何重叠。","叶翠本羞眉，花红彊如颊。","佳人不兹期，怅望别离时。","牵花怜共蒂，折藕爱连丝。","故情何处所？新物徒华滋。","不惜南津交佩解，还羞北海雁书迟。","采莲歌有节，采莲夜未歇。","正逢浩荡江上风，又值徘徊江上月。","莲浦夜相逢，吴姬越女何丰茸。","共问寒江千里外，征客关山更几重。"],"theme":"爱情相思","theme2":["羁旅思乡"],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["江南","塞外","舟"],"cats":{"抒情":["爱情","离别","思念","思乡"],"人物":["女子"],"植物":["荷花"]},"theme_conf":0.374},{"uid":"2d6eff0e-d937-4d1f-9e3b-91241dd3db27","title":"冬夜赠别友人","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["愁听千家流水声，相思独向月中行。","侵堦暗草秋霜重，遍郭寒山夜月明。","连年客舍唯多病，数亩田园又废耕。","更送乘轺归上国，应怜贡禹未成名。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":["孤寂","愁怨"],"scene":["夜","冬"],"cats":{"抒情":["友情","离别","思念","伤感","孤独"],"四季":["秋天","冬天"],"生活":["田野"]},"theme_conf":0.601},{"uid":"7e30c468-9d80-4b8c-9a87-1276b583687a","title":"夜闻江南人家赛神因题即事","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["南方淫祀古风俗，楚妪解唱迎神曲。","鎗鎗铜鼓芦叶深，寂寂琼筵江水绿。","雨过风清洲渚闲，椒浆醉尽迎神还。","帝女凌空下湘岸，番君隔浦向尧山。","月隐回塘犹自舞，一门依倚神之祜。","韩康灵药不复求，扁鹊医方曾莫覩。","逐客临江空自悲，月明流水无已时。","听此迎神送神曲，携觞欲吊屈原祠。"],"theme":"节令风俗","theme2":["送别","羁旅思乡","闲适隐逸"],"style":"冲淡","style2":["清新"],"mood":"孤寂","mood2":["悲怆"],"scene":["江","江南"],"cats":{"抒情":["思乡","伤感"],"山水":["江河"],"节日":["端午节"]},"theme_conf":0.85},{"uid":"2b7e4088-5605-41dc-8565-bcce73c7dfad","title":"相和歌辞 楚妃怨","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["梧桐叶下黄金井，横架辘轳牵素绠。","美人初起天未明，手拂银缾秋水冷。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"抒情":["闺怨"],"四季":["秋天"],"人物":["女子"]},"theme_conf":1.0},{"uid":"9bc25c25-81f9-4003-8592-9f413774e85f","title":"夜梦","author":"萧妃","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昨日梦君归，贱妾下鸣机。","极知意气薄，不著去时衣。","故言如梦里，赖得雁书飞。"],"theme":"羁旅思乡","theme2":["闺情宫怨","游仙梦幻"],"style":"沉郁","style2":[],"mood":"相思","mood2":["慷慨"],"scene":["夜"],"cats":{"抒情":["思念","思乡","闺怨"],"人生":["梦想"]},"theme_conf":0.437},{"uid":"b7d50789-e0d5-4291-8014-eddf65a124df","title":"瑶瑟怨","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["冰簟银床梦不成，碧天如水夜云轻。","雁声远过潇湘去，十二楼中月自明。"],"theme":"闺情宫怨","theme2":["送别"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["夜","楼","月","冬","鸟"],"cats":{"抒情":["闺怨"]},"theme_conf":0.637},{"uid":"2bdc3e83-80ca-4977-bbc1-cc1e37918e14","title":"送陆鸿渐山人采茶回","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["千峰待逋客，香茗复丛生。","采摘知深处，烟霞羡独行。","幽期山寺远，野饭石泉清。","寂寂燃灯夜，相思一磬声。"],"theme":"送别","theme2":["闲适隐逸","山水田园"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["相思"],"scene":["山"],"cats":{"抒情":["思念","孤独"],"动物":["写鸟"],"食物":["写茶"]},"theme_conf":0.279},{"uid":"e0eb3016-9288-4dc0-9257-3de36e5ad73c","title":"锦瑟","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["锦瑟无端五十弦，一弦一柱思华年。","庄生晓梦迷蝴蝶，望帝春心托杜鹃。","沧海月明珠有泪，蓝田日暖玉生烟。","此情可待成追忆，只是当时已惘然。"],"theme":"爱情相思","theme2":["哲理悟道"],"style":"绮丽","style2":[],"mood":"相思","mood2":["惆怅"],"scene":["春","月","江","鸟"],"cats":{"抒情":["思念"],"四季":["春天"]},"theme_conf":0.633},{"uid":"de948fac-a55e-462b-98f8-aa3b9214fc54","title":"醉为马坠诸公携酒相看","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["甫也诸侯老宾客，罢酒酣歌拓金戟。","骑马忽忆少年时，散蹄迸落瞿塘石。","白帝城门水云外，低身直下八千尺。","粉堞电转紫游缰，东得平冈出天壁。","江村野堂争入眼，垂鞭亸鞚凌紫陌。","向来皓首惊万人，自倚红颜能骑射。","安知决臆追风足，朱汗骖驔犹喷玉。","不虞一蹶终损伤，人生快意多所辱。","职当忧戚伏衾枕，况乃迟暮加烦促。","明知来问腆我颜，杖藜强起依僮仆。","语尽还成开口笑，提携别埽清谿曲。","酒肉如山又一时，初筵哀丝动豪竹。","共指西日不相贷，喧呼且复杯中渌。","何必走马来为问，君不见嵇康养生遭杀戮。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"豪放","style2":["沉郁"],"mood":"欢愉","mood2":["相思","悲怆"],"scene":["酒"],"cats":{"抒情":["思念","伤感"],"动物":["写马"],"食物":["写酒"]},"theme_conf":0.82},{"uid":"8b57e03d-6d1f-4a4a-ba34-1f58e2551ca1","title":"遣悲怀三首 一","author":"元稹","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["谢公最小偏怜女，嫁与黔娄百事乖。","顾我无衣搜画箧，泥他沽酒拔金钗。","野蔬充膳甘长藿，落叶添薪仰古槐。","今日俸钱过十万，与君营奠复营斋。"],"theme":"悼亡挽歌","theme2":["闲适隐逸"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["酒"],"cats":{"抒情":["伤感","悼亡"]},"theme_conf":0.98},{"uid":"34d3b009-d2b6-456e-969f-8b4a0283356b","title":"东南行一百韵寄通州元九侍御澧州李十一舍人果州崔二十二使君开州韦大员外庾三十二补阙杜十四拾遗李二十助教员外窦七校书","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["南去经三楚，东来过五湖。","山头看候馆，水面问征途。","地远穷江界，天低极海隅。","飘零同落叶，浩荡似乘桴。","渐觉乡原异，深知土产殊。","夷音语嘲异常，蛮态笑睢盱。","水市通阛阓，烟村混舳舻。","吏征渔户税，人纳火田租。","亥日饶𫚥蟹，寅年足虎䝙。","成人男作丱，事鬼女为巫。","楼暗攒倡妇，隄长簇贩夫。","夜船论铺赁，春酒断缾酤。","见果皆卢橘，闻禽悉鹧鸪。","山歌猨独叫，野哭鸟相呼。","岭徼云成栈，江郊水当郛。","月移翘柱鹤，风泛飐樯乌。","鼇碍潮无信，蛟惊浪不虞。","鼍鸣江擂鼓，蜃气海浮图。","树裂山魈穴，沙含水弩枢。","喘牛犂紫芋，羸马放青菰。","绣面谁家婢，鵶头几岁奴。","泥中采菱芡，烧后拾樵苏。","鼎腻愁烹鼈，盘腥厌脍鲈。","钟仪徒恋楚，张翰浪思吴。","气序凉还热，光阴旦复晡。","身方逐萍梗，年欲近桑榆。","渭北田园废，江西岁月徂。","忆归恒惨澹，怀旧忽踟蹰。","自念咸秦客，尝为邹鲁儒。","蕴藏经国术，轻弃度关𦈡。","赋力凌鹦鹉，词锋敌辘轳。","战文重掉鞅，射策一弯弧。","崔杜鞭齐下，元韦辔并驱。","名声逼扬马，交分过萧朱。","世务轻摩揣，周行窃觊觎。","风云皆会合，雨露各沾濡。","共遇升平代，偏慙固陋躯。","承明连夜直，建礼拂晨趋。","美服颁王府，珍羞降御厨。","议高通白虎，谏切伏青蒲。","柏殿行陪宴，花楼走看酺。","神旗张鸟兽，天籁动笙芋。","戈劒星芒耀，鱼龙电策驱。","定场排越伎，促坐进吴歈。","缥缈疑仙乐，婵娟胜画图。","歌鬟低翠羽，舞汗堕红珠。","别选闲游伴，潜招小饮徒。","一杯愁已破，三醆气弥麤。","輭美仇家酒，幽闲葛氏姝。","十千方得斗，二八正当垆。","论笑杓胡律，谈怜巩嗫嚅。","李酣犹短窦，庾醉更蔫迂。","鞍马呼教住，骰盘喝遣输。","长驱波卷白，连掷采成卢。","筹幷频逃席，觥严列置盂。","满巵那可灌，颓玉不胜扶。","入视中枢草，归乘内廐驹。","醉曾冲宰相，骄不揖金吾。","日近恩虽重，云高势却孤。","飜身落霄汉，失脚倒泥涂。","博望移门籍，浔阳佐郡符。","时情变寒暑，世利算锱铢。","即日辞双阙，明朝别九衢。","播迁分郡国，次第出京都。","秦岭驰三驿，商山上二邘。","岘阳亭寂莫，夏口路崎岖。","大道全生棘，中丁尽执殳。","江关未撤警，淮寇尚稽诛。","林对东西寺，山分大小姑。","庐峰莲刻削，湓浦带萦纡。","九派吞青草，孤城覆绿芜。","黄昏钟寂寂，清晓角呜呜。","春色辞门柳，秋声到井梧。","残芳悲𫛸鴂，暮节感茱萸。","蘂坼金英菊，花飘雪片芦。","波红日斜没，沙白月平铺。","几见林抽笋，频惊燕引雏。","岁华何倏忽，年少不须臾。","眇默思千古，苍茫想八区。","孔穷缘底事，颜夭有何辜。","龙智犹经醢，龟灵未免刳。","穷通应已定，圣哲不能逾。","况我身谋拙，逢他厄运拘。","漂流随大海，锤锻任洪𬬻。","险阻尝之矣，栖迟命也夫。","沈冥消意气，穷饿耗肌肤。","防瘴和残药，迎寒补旧襦。","书床鸣蟋蟀，琴匣网蜘蛛。","贫室如悬磐，端忧剧守株。","时遭人指点，数被鬼揶揄。","兀兀都疑梦，昏昏半是愚。","女惊朝不起，妻怪夜长吁。","万里抛朋侣，三年隔友于。","自然悲聚散，不是恨荣枯。","去夏微之疟，今春席八殂。","天涯书达否，泉下哭知无。","谩写诗盈卷，空盛酒满壶。","只添新怅望，岂复旧欢娱。","壮志因愁减，衰容与病俱。","相逢应不识，满颔白髭须。"],"theme":"寄赠酬答","theme2":["羁旅思乡","民生疾苦","送别"],"style":"沉郁","style2":["豪放","绮丽"],"mood":"孤寂","mood2":["欢愉","愁怨"],"scene":["酒","山","江","夏","夜","鸟"],"cats":{"抒情":["思乡","伤感","孤独","悼亡"],"四季":["夏天"],"天气":["月亮"],"人生":["励志","时光","梦想"],"生活":["田野"],"节日":["中秋节","重阳节"]},"theme_conf":0.85},{"uid":"6533dc36-cc73-4798-b24a-fbff04fc2a85","title":"渡中江望石城泣下","author":"后主煜","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["江南江北旧家乡，三十年来梦一场。","吴苑宫闱今冷落，广陵台殿已荒凉。","云笼远岫愁千片，雨打归舟泪万行。","兄弟四人三百口，不堪闲坐细思量。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["婉约","幽峭"],"mood":"愁怨","mood2":["悲怆"],"scene":["江","江南"],"cats":{"抒情":["思乡","伤感"],"山水":["江河"]},"theme_conf":0.532},{"uid":"06f6c725-bf53-4a76-9bb3-4aea454900f0","title":"七夕赋咏成篇","author":"沈叔安","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["皎皎宵月丽秋光，耿耿天津横复长。","停梭且复留残纬，拂镜及早更新妆。","彩凤齐驾初成辇，雕鹊填河已作梁。","虽喜得同今夜枕，还愁重空明日床。"],"theme":"节令风俗","theme2":["咏物"],"style":"沉郁","style2":["清新"],"mood":"愁怨","mood2":["欢愉"],"scene":["七夕","夜"],"cats":{"抒情":["伤感"],"节日":["七夕节"]},"theme_conf":0.87},{"uid":"7e1be9c9-fa2f-44c2-a6bc-3edcece745fe","title":"夜泊牛渚怀古","author":"李白","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["牛渚西江夜，青天无片云。","登舟望秋月，空忆谢将军。","余亦能高咏，斯人不可闻。","明朝挂帆席，枫叶落纷纷。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"相思","mood2":[],"scene":["江","月","夜","舟","秋"],"cats":{"抒情":["思念","怀古"],"四季":["秋天"]},"theme_conf":0.796},{"uid":"6487761a-51bf-4362-9513-52c1f6c495bb","title":"哭张十八校书","author":"权德舆","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["芸阁为郎一命初，桐州寄傲十年余。","魂随逝水归何处，名在新诗众不如。","蹉跎江浦生华发，牢落寒原会素车。","更忆八行前日到，含凄为报秣陵书。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["楼","江"],"cats":{"抒情":["悼亡"],"人生":["时光"]},"theme_conf":0.98},{"uid":"c89fcc8b-70df-4b67-84c8-6c855555eb41","title":"杂曲歌辞 夜坐吟","author":"李白","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["踏踏马头谁见过，眼看北斗直天河。","西风罗幕生翠波，铅华笑妾颦青蛾。","为君起唱长相思，帘外严霜皆倒飞。","明星烂烂东方陲，红霞稍出东南涯，陆郎去矣乘斑骓。"],"theme":"闺情宫怨","theme2":["爱情相思"],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["夜","秋"],"cats":{"抒情":["爱情","思念","闺怨"],"四季":["秋天"],"天气":["星星"]},"theme_conf":0.5},{"uid":"71077c12-3f1e-40bc-b453-2fa73f3be4aa","title":"又题洛苑梧叶上","author":"天宝宫人","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["一叶题诗出禁城，谁人酬和独含情。","自嗟不及波中叶，荡漾乘春取次行。"],"theme":"咏物","theme2":["送别"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独"],"四季":["春天"],"植物":["叶子"]},"theme_conf":0.617},{"uid":"3530235e-e711-41d8-b30a-4a238a3d9ed4","title":"宋中十首 五","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["登高临旧国，怀古对穷秋。","落日鸿雁度，寒城砧杵愁。","昔贤不复有，行矣莫淹留。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","重阳"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"节日":["重阳节"]},"theme_conf":1.0},{"uid":"33f3bc50-8a7f-4445-995e-1d1af406ae26","title":"送汴州监军俱文珍","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["奉使羌池静，临戎汴水安。","冲天鹏翅阔，报国劒铓寒。","晓日驱征骑，春风咏采兰。","谁言臣子道，忠孝两全难。"],"theme":"边塞征战","theme2":["送别"],"style":"豪放","style2":[],"mood":"恬淡","mood2":["慷慨"],"scene":["春"],"cats":{"抒情":["爱国"],"四季":["春天"]},"theme_conf":0.507},{"uid":"dcb153ef-db2d-4222-b72e-f762b9f6ef6d","title":"拟古三首 三","author":"徐彦伯","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["颓光无淹晷，逝水有迅流。","绿苔纷易歇，红颜不再求。","歌笑当及春，无令壮志秋。","弱年仕关辅，簃门豁御沟。","敷愉东城际，婉娈南陌头。","荷花娇绿水，杨叶暖青楼。","中有绮罗人，可怜名莫愁。","画屏绕金膝，珠帘悬玉钩。","纤指调宝琴，泠泠哀且柔。","赠君鸳鸯带，因以鹔鹴裘。","窗晓吟日坐，闺夕秉烛游。","无作北门客，咄咄怀百忧。"],"theme":"咏怀抒感","theme2":["悼亡挽歌","送别","山水田园"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["花","春","秋"],"cats":{"抒情":["伤感","悼亡"],"四季":["春天","秋天"],"人生":["励志","梦想"]},"theme_conf":0.7},{"uid":"383d41a8-5155-4fff-b91f-87d5585ff03e","title":"古柏行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["孔明庙前有老柏，柯如青铜根如石。","霜皮溜雨四十围，黛色参天二千尺。","君臣已与时际会，树木犹为人爱惜。","云来气接巫峡长，月出寒通雪山白。","忆昨路绕锦亭东，先主武侯同閟宫。","崔嵬枝干郊原古，窈窕丹青户牖空。","落落盘踞虽得地，冥冥孤高多烈风。","扶持自是神明力，正直原因造化功。","大厦如倾要梁栋，万牛回首丘山重。","不露文章世已惊，未辞剪伐谁能送。","苦心岂免容蝼蚁，香叶终经宿鸾凤。","志士幽人莫怨嗟，古来材大难为用。"],"theme":"咏物","theme2":["送别","题画咏艺","讽喻刺世"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["愁怨"],"scene":["山","雪"],"cats":{"抒情":["孤独"]},"theme_conf":0.289},{"uid":"7241e2c5-7d41-4cbd-86d7-9be3e63208f7","title":"送客之上谷","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["北客悲秋色，田园忆去来。","披衣朝易水，匹马夕燕台。","风翦荷花碎，霜迎栗罅开。","赏心知不浅，累月故人杯。"],"theme":"送别","theme2":["羁旅思乡"],"style":"清新","style2":["悲慨"],"mood":"悲怆","mood2":["相思"],"scene":["秋"],"cats":{"抒情":["友情","思念","思乡","伤感"],"四季":["秋天"],"生活":["田野"]},"theme_conf":0.465},{"uid":"ca8dc6f9-911f-4ae1-8f6a-0e6b374a5ede","title":"奉先刘少府新画山水障歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["堂上不合生枫树，怪底江山起烟雾。","闻君埽却赤县图，乘兴谴画沧洲趣。","画师亦无数，好手不可遇。","对此融心神，知君重毫素。","岂但祁岳与郑虔，笔迹远过杨契丹。","得非悬圃裂，无乃潇湘飜。","悄然坐我天姥下，耳边已似闻清猨。","反思前夜风雨急，乃是蒲城鬼神人。","元气淋漓障犹湿，真宰上诉天应泣。","野亭春还杂花远，渔翁暝蹋孤舟立。","沧浪水深青溟阔，攲岸侧岛秋毫末。","不见湘妃鼓瑟时，至今斑竹临江活。","刘侯天机精，爱画入骨髓。","自有两儿郎，挥洒亦莫比。","大儿聪明到，能添老树巅崖里。","小儿心孔开，貌得山僧及童子。","若耶溪，云门寺。","吾独胡为在泥滓，青鞵布韤从此始。"],"theme":"山水田园","theme2":["题画咏艺"],"style":"幽峭","style2":["清新","沉郁"],"mood":"孤寂","mood2":["相思","悲怆"],"scene":["山","秋","江","雨"],"cats":{"抒情":["思念","孤独"],"四季":["秋天"],"人物":["儿童"]},"theme_conf":0.468},{"uid":"cpbf297a8f400d71","title":"澡兰香","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["盘丝系腕，巧篆垂簪，玉隐绀纱睡觉。","银瓶露井，彩云窗，往事少年依约。","为当时、曾写榴裙，伤心红绡褪萼。","黍梦光阴渐老，汀洲烟箬。","莫唱江南古调，怨抑难招，楚江沈魄。","薰风燕乳，暗雨梅黄，午镜澡兰帘幕。","念秦楼、也拟人归，应翦菖浦自酌。","但怅望、一屡新蟾，随人天角。"],"theme":"咏史怀古","theme2":[],"style":"婉约","style2":["清新","绮丽"],"mood":"相思","mood2":["愁怨"],"scene":["江","花","江南"],"cats":{"抒情":["伤感","怀古"],"天气":["写云"],"人生":["时光"]},"theme_conf":1.0},{"uid":"b9629e5e-c8bc-47e6-ae9f-2eba96a7fbda","title":"鼓吹曲辞 有所思","author":"卢仝","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["当时我醉美人家，美人颜色娇如花。","今日美人弃我去，青楼珠箔天之涯。","天涯娟娟常娥月，三五二八盈又缺。","翠眉蝉鬓生别离，一望不见心断绝。","心断绝，几千里，梦中醉卧巫山云。","觉来泪滴湘江水，湘江两岸花木深。","美人不见愁人心，含愁更奏绿绮琴，调高弦绝无知音。","美人兮美人！不知为暮雨兮为朝云。","相思一夜梅花发，忽到窗前疑是君。"],"theme":"爱情相思","theme2":["送别"],"style":"绮丽","style2":["沉郁","婉约"],"mood":"相思","mood2":[],"scene":["夜","酒","江"],"cats":{"抒情":["爱情","友情","离别","思念","伤感"],"人物":["女子"]},"theme_conf":0.367},{"uid":"b4f9c5b3-0108-4127-bf3e-73fd207176f3","title":"杂曲歌辞 行路难三首 三","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["有耳莫洗颍川水，有口莫食首阳蕨。","含光混世贵无名，何用孤高比云月。","吾观自古贤达人，功成不退皆殒身。","子胥既弃吴江上，屈原终投湘水滨。","陆机才多岂自保，李斯税驾苦不早。","华亭鹤唳讵可闻，上蔡苍鹰何足道？君不见吴中张翰称达士，秋风忽忆江东行。","且乐生前一杯酒，何须身后千载名。"],"theme":"民生疾苦","theme2":["哲理悟道"],"style":"旷达","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["酒","端午","秋"],"cats":{"抒情":["思念","孤独"],"四季":["秋天"],"节日":["端午节"]},"theme_conf":0.601},{"uid":"3e598395-2064-42df-ae7a-16bf591c0695","title":"苦雪四首 一","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["二月犹北风，天阴雪冥冥。","寥落一室中，怅然慙百龄。","苦愁正如此，门柳复青青。"],"theme":"民生疾苦","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["雪"],"cats":{"抒情":["伤感"],"天气":["写雪"]},"theme_conf":1.0},{"uid":"68a65221-277b-4996-8d68-fed7604c1b8c","title":"东平蓬莱驿夜宴平卢杨判官醉后赠别姚太守置酒留宴","author":"独孤及","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["驿楼涨海壖，秋月寒城边。","相见自不足，况逢主人贤。","夜清酒浓人如玉，一斗何啻直十千。","木兰为樽金为杯，江南急管卢女弦。","齐童如花解郢曲，起舞激楚歌采莲。","固知别多相逢少，乐极哀至心婵娟。","少留莫辞醉，前路方悠然。","明日分飞傥相忆，祗应遥望西南天。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["酒"],"cats":{"抒情":["离别"],"天气":["月亮"],"节日":["中秋节"],"食物":["写酒"]},"theme_conf":0.416},{"uid":"87f5949b-bdad-4b5e-b488-7015bd45cc4f","title":"咏怀古迹五首 五","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["诸葛大名垂宇宙，宗臣遗像肃清高。","三分割据纡筹策，万古云霄一羽毛。","伯仲之间见伊吕，指挥若定失萧曹。","福移汉祚难恢复，志决身歼军务劳。"],"theme":"咏史怀古","theme2":[],"style":"雄浑","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"抒情":["怀古"]},"theme_conf":0.787},{"uid":"f28dfaa3-ff90-42e3-923d-63a5635afab8","title":"七夕二首 二","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["天衢启云帐，神驭上星桥。","初喜渡河汉，频惊转斗杓。","余霞张锦幛，轻电闪红绡。","非是人间世，还悲后会遥。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":["悲慨"],"mood":"悲怆","mood2":["欢愉"],"scene":["七夕"],"cats":{"抒情":["伤感"],"生活":["写桥"],"节日":["七夕节"]},"theme_conf":0.92},{"uid":"5180277d-a3b2-4644-9f1f-2d5a4af7c604","title":"杂曲歌辞 春日行","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["春日融融池上暖，竹牙出土兰心短。","草堂晨起酒半醒，家僮报我园花满。","头上皮冠未曾整，直入花间不寻径。","树树殷勤尽遶行，举枝未徧春日暝。","不用积金著青天，不用服药求神仙。","但愿园里花长好，一生饮酒花前老。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"天气":["太阳"]},"theme_conf":1.0},{"uid":"368cbc24-d33d-4ef5-9940-c16acc077d73","title":"相和歌辞 江南曲八首 八","author":"刘希夷","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["忆昔江南年盛时，平生怨在长洲曲。","冠盖星繁湘水上，冲风摽落洞庭渌。","落花舞袖红纷纷，朝霞高阁洗晴云。","谁言此处婵娟子，珠玉为心以奉君。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["江","江南"],"cats":{"抒情":["思念"],"山水":["江河"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"335314f2-aa38-4f25-a0c3-6d8e375daec6","title":"宿曾江口示姪孙湘二首 一","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["云昏水奔流，天水漭相围。","三江灭无口，其谁识涯圻。","暮宿投民村，高处水半扉。","犬鸡俱上屋，不复走与飞。","篙舟入其家，暝闻屋中唏。","问知岁常然，哀此为生微。","海风吹寒晴，波扬众星辉。","仰视北斗高，不知路所归。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"冲淡","style2":[],"mood":"悲怆","mood2":[],"scene":["江"],"cats":{"抒情":["思乡"],"山水":["江河"],"天气":["星星"]},"theme_conf":0.534},{"uid":"0b6a4293-c89f-4e4b-9365-be01edb02ccd","title":"诸葛庙","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["久游巴子国，屡入武侯祠。","竹日斜虚寝，溪风满薄帷。","君臣当共济，贤圣亦同时。","翊戴归先主，幷吞更出师。","虫虵穿画壁，巫觋醉蛛丝。","歘忆吟梁父，躬耕也未迟。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"悲慨","style2":[],"mood":"相思","mood2":[],"scene":["酒"],"cats":{"抒情":["思念","怀古"],"生活":["田野"]},"theme_conf":0.584},{"uid":"d0a388eb-dd3d-4735-aacc-392ff3a2bed1","title":"留上李右相","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["风俗登淳古，君臣挹大庭。","深沈谋九德，密勿契千龄。","独立调元气，清心豁窅冥。","本枝连帝系，长策冠生灵。","傅说明殷道，萧何律汉刑。","钧衡持国柄，柱石总朝经。","隐轸江山藻，氛氲鼎鼐铭。","兴中皆白雪，身外即丹青。","江海呼穷鸟，诗书问聚萤。","吹嘘成羽翼，提握动芳馨。","倚伏悲还笑，栖迟醉复醒。","恩荣初就列，含育忝宵形。","有窃丘山惠，无时枕席宁。","壮心瞻落景，生事感浮萍。","莫以才难用，终期善易听。","未为门下客，徒谢少微星。"],"theme":"题画咏艺","theme2":[],"style":"豪放","style2":["婉约"],"mood":"慷慨","mood2":["欢愉","悲怆"],"scene":["雪","江","山"],"cats":{"抒情":["伤感"],"人生":["读书"]},"theme_conf":1.0},{"uid":"33f9ccb9-1b90-41cf-9ce3-e9394b68c4a3","title":"落叶","author":"孔绍安","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["早秋惊落叶，飘零似客心。","翻飞未肯下，犹言惜故林。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":0.791},{"uid":"e75b38bd-659f-4d46-9c7f-f4213be5f33f","title":"从江西至彭蠡入浙西淮南界道中寄齐相公","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["大贤旧丞相，作镇江山雄。","自镇江山来，何人得如公。","处士待徐孺，仙人期葛洪。","一身控上游，八郡趋下风。","比屋除畏溺，林塘曳烟虹。","生人罢虔刘，井税均且充。","大府肃无事，欢然接悲翁。","心清百丈泉，目送孤飞鸿。","数年鄱阳掾，抱责栖微躬。","首阳及汨罗，无乃褊其衷。","杨朱幷阮籍，未免哀途穷。","四贤虽得仁，此怨何怱怱。","老氏齐宠辱，于陵一穷通。","本师留度门，平等冤亲同。","能依二谛法，了达三轮空。","真境靡方所，出离内外中。","无边尽未来，定惠双修功。","蹇步慙寸进，餙装随转蓬。","朝行楚水阴，夕宿吴洲东。","吴洲复白云，楚水飘丹枫。","晚霞烧廻潮，千里光曈曈。","蓂开海上影，桂吐淮南丛。","何当翼明庭，草木生春融。"],"theme":"寄赠酬答","theme2":[],"style":"悲慨","style2":["雄浑","旷达"],"mood":"悲怆","mood2":["孤寂"],"scene":["江"],"cats":{"抒情":["伤感","孤独"],"山水":["江河"],"节日":["端午节"]},"theme_conf":0.72},{"uid":"f8ec87e7-3074-40dd-8d87-a260dad83ae7","title":"相和歌辞 短歌行二首 一","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["曈曈太阳如火色，上行千里下一刻。","出为白昼入为夜，圜转如珠住不得。","住不得，可奈何？为君举酒歌短歌。","歌声苦，词亦苦，四座少年君听取。","今夕未竟明夕催，秋风才往春风回。","人无根蔕时不驻，朱颜白日相隳颓。","劝君且强笑一面，劝君复强饮一杯。","人生不得长欢乐，年少须臾老到来。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["酒","秋","春"],"cats":{"抒情":["思乡"],"四季":["春天","秋天"],"天气":["写风"],"人生":["青春"]},"theme_conf":0.65},{"uid":"8cefa67f-2b9a-4e13-8158-4d38cbfb331b","title":"长沙过贾谊宅","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["三年谪宦此栖迟，万古惟留楚客悲。","秋草独寻人去后，寒林空见日斜时。","汉文有道恩犹薄，湘水无情吊岂知。","寂寂江山摇落处，怜君何事到天涯。"],"theme":"咏史怀古","theme2":["羁旅思乡"],"style":"雄浑","style2":["冲淡"],"mood":"孤寂","mood2":[],"scene":["秋","江","山"],"cats":{"抒情":["思乡","孤独","怀古"],"四季":["秋天"]},"theme_conf":0.519},{"uid":"84d91507-c2a6-4260-8145-2ed3cab95504","title":"夜归","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["夜来归来冲虎过，山黑家中已眠卧。","傍见北斗向江低，仰看明星当空大。","庭前把烛嗔两炬，峡口惊猿闻一个。","白头老罢舞复歌，杖藜不睡谁能那。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["夜"],"cats":{"抒情":["思乡"],"天气":["星星"]},"theme_conf":1.0},{"uid":"b18e52d9-a647-499b-a759-bca7c250393f","title":"与沈杨二舍人合老同食勅赐樱桃玩物感恩因成十四韵","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["清晓趋丹禁，红缨降紫宸。","驱禽养得熟，和叶摘来新。","圆转盘倾玉，鲜明笼透银。","内园题两字，西掖赐三臣。","荧惑晶华赤，醍醐气味真。","如珠未穿孔，似火不烧人。","杏俗难为对，桃顽讵可伦。","肉嫌卢橘厚，皮笑荔枝皴。","琼液酸甜足，金丸大小匀。","偷须防曼倩，惜莫掷安仁。","手擘才离核，匙抄半是津。","甘为舌上露，暖作腹中春。","已惧长尸禄，仍惊数食珍。","最慙恩未报，饱𫗪不才身。"],"theme":"应制干谒","theme2":["应制干谒"],"style":"绮丽","style2":["清新"],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"抒情":["感恩"],"四季":["春天"],"植物":["桃花"],"食物":["荔枝"]},"theme_conf":0.87},{"uid":"3ef4b782-4495-49dc-9da5-b022da15c2a6","title":"句","author":"后主煜","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["迢迢牵牛星，杳在河之阳。","粲粲黄姑女，耿耿遥相望。","鸎狂应有恨，蝶舞已无多。","揖让月在手，动摇风满怀。","病态如衰弱，厌厌向五年。","衰颜一病难牵复，晓殿君临颇自羞。","冷笑秦皇经远略，静怜姬满苦时巡。","鬓从今日添新白，菊是去年依旧黄。","万古到头归一死，醉乡葬地有高原。","人生不满百，刚作千年画。","日暎仙云薄，秋高天碧深。","乌照始潜辉，龙烛便争秉。","凝珠满露枝，游飏日已西。","肃穆寒初至，九重开扇鹄。","四牖炳灯鱼，羽觞无算酌。","倾盌更为寿，深卮递酬宾。"],"theme":"羁旅思乡","theme2":["送别"],"style":"清新","style2":["沉郁","豪放"],"mood":"愁怨","mood2":[],"scene":["酒"],"cats":{"抒情":["思乡"],"天气":["星星"]},"theme_conf":0.507},{"uid":"8e427cef-2f58-4725-a290-2e3e6f4db072","title":"听蜀道士琴歌","author":"李宣古","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["至道不可见，正声难得闻。","忽逢羽客抱绿绮，西别峨嵋峰顶云。","初排□面蹑轻响，似掷细珠鸣玉上。","忽挥素爪画七弦，苍崖劈裂迸碎泉。","愤声高，怨声咽，屈原呌天两妃绝。","朝雉飞，双鹤离，属玉夜啼独鹜悲。","吹我神飞碧霄里，牵我心灵入秋水。","有如驱逐太古来，邪淫辟荡贞心开。","孝为子，忠为臣，不独语言能教人。","前弄啸，后弄嚬，一舒一惨非冬春。","从朝至暮听不足，相将直说瀛洲宿。","更深弹罢背孤灯，窗雪萧萧打寒竹。","人间岂合值仙踪，此别多应不再逢。","抱琴却上瀛洲去，一片白云千万峰。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"孤寂","mood2":[],"scene":["夜","冬","雪","端午"],"cats":{"抒情":["离别","孤独"],"四季":["冬天"],"节日":["端午节"]},"theme_conf":0.437},{"uid":"d7a14b06-eb3f-4534-9f3b-fc81842cefd9","title":"逢谢偃","author":"高适","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["红颜怆为别，白发始相逢。","唯余昔时泪，无复旧时容。"],"theme":"送别","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["伤感","感恩"]},"theme_conf":1.0},{"uid":"cp9258161a87ac7c","title":"谢金莲诗酒红梨花・四块玉","author":"张寿卿","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["我剔的这灯焰儿光，那的这花瓶儿正。","我对着这烛底花前说叮咛，则愿的灯休灭花休谢人休另。","这知音人存着志诚，似花枝常在瓶，似灯儿分外明。"],"theme":"闲适隐逸","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["花","酒"],"cats":{"抒情":["友情","感恩"],"植物":["梨花","荷花"],"食物":["写酒"]},"theme_conf":0.65},{"uid":"49577c84-9adc-4983-96ef-81d474492aa9","title":"又雪","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["南雪不到地，青崖沾未消。","微微向日薄，脉脉去人遥。","冬热鸳鸯病，峡深豺虎骄。","愁边有江水，焉得北之朝。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["雪","冬"],"cats":{"抒情":["爱情","伤感"],"四季":["冬天"],"天气":["写雪"]},"theme_conf":1.0},{"uid":"2618397e-f65f-4680-9751-f0f1e2ce2533","title":"奉和荥阳公离筵作","author":"元稹","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["南郡生徒辞绛帐，东山妓乐拥油旌。","钧天排比箫韶待，犹顾人间有别情。"],"theme":"应制干谒","theme2":["送别"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"抒情":["离别"],"人物":["老师"]},"theme_conf":0.76},{"uid":"3f692193-2a80-41b5-b4bf-47176d040535","title":"赋得长亭柳","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["濯濯长亭柳，阴连灞水流。","雨搓金缕细，烟褭翠丝柔。","送客添新恨，听莺忆旧游。","赠行多折取，那得到深秋。"],"theme":"送别","theme2":[],"style":"婉约","style2":["绮丽"],"mood":"愁怨","mood2":["相思"],"scene":["楼","秋"],"cats":{"抒情":["离别","思念"],"四季":["秋天"],"植物":["柳树"]},"theme_conf":0.786},{"uid":"1deac6d5-6da0-4d9f-a182-2f0697cbb932","title":"已凉","author":"韩偓","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["碧阑干外绣帘垂，猩血屏风画折枝。","八尺龙须方锦褥，已凉天气未寒时。"],"theme":"闺情宫怨","theme2":["爱情相思"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["闺怨"]},"theme_conf":0.5},{"uid":"551ff4cc-f942-44ea-942a-9e97dedc5431","title":"舞曲歌辞 东海有勇妇","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["梁山感杞妻，恸哭为之倾。","金石忽暂开，都由激深情。","东海有勇妇，何慙苏子卿。","学劒越处子，超腾若流星。","捐躯报夫讐，万死不顾生。","白刃耀素雪，苍天感精诚。","十步两躩跃，三呼一交兵。","斩首掉国门，蹴踏五藏行。","割此伉俪愤，粲然大义明。","北海李使君，飞章奏天庭。","舍罪警风俗，流芳播沧瀛。","志在列女籍，竹帛已光荣。","淳于免诏狱，汉主为缇萦。","津妾一櫂歌，脱父于严刑。","十子若不肖，不如一女英。","豫让斩空衣，有心竟无成。","要离杀庆忌，壮夫素所轻。","妻子亦何辜，焚之买虚名。","岂如东海妇，事立独扬名。"],"theme":"闺情宫怨","theme2":["送别"],"style":"豪放","style2":["冲淡"],"mood":"悲怆","mood2":["慷慨"],"scene":["雪","江南"],"cats":{"抒情":["闺怨","爱国"],"天气":["写雪"]},"theme_conf":0.643},{"uid":"4f4067b1-b822-4ef2-84d4-24f473b14178","title":"逼寒节寄崔七","author":"朱湾","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["闲庭只是长莓苔，三径曾无车马来。","旅馆尚愁寒食火，羁心嬾向不然灰。","门前下客虽弹铗，溪畔穷鱼且曝腮。","他日趋庭应问礼，须言陋巷有颜回。"],"theme":"寄赠酬答","theme2":["送别"],"style":"幽峭","style2":[],"mood":"孤寂","mood2":["愁怨"],"scene":["清明","园林"],"cats":{"抒情":["伤感"],"节日":["寒食节","清明节"]},"theme_conf":0.9},{"uid":"99167d13-8e2c-4b75-bf93-62b0682dfdd0","title":"清平调词三首 二","author":"李白","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["一枝秾艳露凝香，云雨巫山枉断肠。","借问汉宫谁得似，可怜飞燕倚新妆。"],"theme":"闺情宫怨","theme2":["咏史怀古"],"style":"清新","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["雨","山"],"cats":{"抒情":["伤感","闺怨","怀古"]},"theme_conf":0.637},{"uid":"f250e306-a578-4bb0-bdef-066a2be420fb","title":"晚发咸阳寄同院遗补","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["征战初休草又衰，咸阳晚眺泪堪垂。","去路全无千里客，秋田不见五陵儿。","秦家故事随流水，汉代高坟对石碑。","回首青山独不语，羡君谈笑万年枝。"],"theme":"咏史怀古","theme2":["悼亡挽歌","边塞征战"],"style":"旷达","style2":["婉约","沉郁"],"mood":"孤寂","mood2":["愁怨","欢愉"],"scene":["园林","秋"],"cats":{"抒情":["伤感","孤独","悼亡","怀古"],"四季":["秋天"],"人生":["战争"]},"theme_conf":0.96},{"uid":"2be36bb1-fc64-4a1c-b627-ceb6eb84a047","title":"送王师鲁协律赴湖南使幕","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["翩翩马上郎，驱传渡三湘。","橘树沙洲暗，松醪酒肆香。","素风传竹帛，高价聘琳瑯。","楚水多兰芷，何人事搴芳。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江","酒"],"cats":{"抒情":["爱国"]},"theme_conf":0.665},{"uid":"a5f2d36f-9597-41a7-99cc-5ff88b7c8c79","title":"相和歌辞 采莲曲","author":"僧齐己","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["越江女，越江莲。","齐菡萏，双婵娟。","嬉游向何处？","采摘且同船。","浩唱发容与，清波生漪涟。","时逢岛屿泊，几共鸳鸯眠。","襟袖既盈溢，馨香亦相传。","薄暮归去来，苎罗生碧烟。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["中秋","江南","江","舟"],"cats":{"抒情":["爱情"],"节日":["中秋节"],"植物":["荷花"]},"theme_conf":0.66},{"uid":"0f7ccc3d-418a-4e51-a5c5-5e22c163b042","title":"刘禅奴弹琵琶歌","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["乐府只传横吹好，琵琶写出关山道。","羁雁出塞绕黄云，边马仰天嘶白草。","明妃愁中汉使回，蔡琰愁处胡笳哀。","鬼神知妙欲收响，阴风切切四面来。","李陵寄书别苏武，自有生人无此苦。","当时若值霍骠姚，灭尽乌孙夺公主。"],"theme":"题画咏艺","theme2":[],"style":"幽峭","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["塞外"],"cats":{"抒情":["伤感"],"人生":["哲理"]},"theme_conf":0.397},{"uid":"805134d3-3d71-496b-a4ae-08e6871461ec","title":"咏虹","author":"苏味道","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["纡余带星渚，窈窕架天浔。","空因壮士见，还共美人沈。","逸照含良玉，神花藻瑞金。","独留长劒彩，终负昔贤心。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":["悲慨"],"mood":"孤寂","mood2":["慷慨"],"scene":[],"cats":{"抒情":["孤独"],"天气":["彩虹"],"人物":["女子"]},"theme_conf":1.0},{"uid":"a2c48eae-6285-411b-af3d-bb24b2520d4e","title":"越王楼歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["緜州州府何磊落，显庆年中越王作。","孤城西北起高楼，碧瓦朱甍照城郭。","楼下长江百丈清，山头落日半轮明。","君王旧迹今人赏，转见千秋万古情。"],"theme":"咏史怀古","theme2":[],"style":"雄浑","style2":[],"mood":"孤寂","mood2":[],"scene":["江","楼","江南"],"cats":{"抒情":["孤独","怀古"],"山水":["长江"]},"theme_conf":0.88},{"uid":"489e9d6a-f619-4103-acde-0ba0bdfca086","title":"相和歌辞 蛾眉怨","author":"王翰","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见宜春苑中九华殿，飞阁连连直如发。","白日全含朱鸟窗，流云半入苍龙阙。","宫中彩女夜无事，学凤吹箫弄清越。","珠帘北卷待凉风，绣户南开向明月。","忽闻天子忆蛾眉，宝凤衔花揲两螭。","传声走马开金屋，夹路鸣环上玉墀。","长乐彤庭宴华寝，三千美人曳光锦。","灯前含笑更罗衣，帐里承恩荐瑶枕。","不意君心半路回，求仙别作望仙台。","仓琅禁闼遥相忆，紫翠岩房昼不开。","欲向人间种桃实，先从海底觅蓬莱。","蓬莱可求不可上，孤舟缥缈知何往？","黄金作盘铜作茎，晴天白露掌中擎。","王母嫣然感君意，云车雨斾欲相迎。","飞帘观前空怨慕，少君何事须相误。","一朝埋没茂陵田，贱妾蛾眉不重顾。","宫车晚出向南山，仙卫逶迤去不还。","朝晡泣对麒麟树，树下苍苔日渐斑。","人生百年夜将半，对酒长歌莫长叹。","賸知白日不可思，一死一生何足算。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"愁怨","mood2":["相思","欢愉"],"scene":["夜","月","山","楼"],"cats":{"抒情":["思念","闺怨","感恩"],"天气":["月亮"],"人物":["女子"]},"theme_conf":0.59},{"uid":"e4b624d5-60a5-42e4-8417-298431fb7625","title":"成都府","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["翳翳桑榆日，照我征衣裳。","我行山川异，忽在天一方。","但逢新人民，未卜见故乡。","大江东流去，游子去日长。","曾城填华屋，季冬树木苍。","喧然名都会，吹箫间笙簧。","信美无与适，侧身望川梁。","鸟[雀]夜各归，中原杳茫茫。","初月出不高，众星尚争光。","自古有羁旅，我何苦哀伤。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["冬","夜","月"],"cats":{"抒情":["思乡","伤感"],"四季":["冬天"],"山水":["长江"]},"theme_conf":0.617},{"uid":"edeba321-b6dc-4573-b3d9-6e5d1ac95d0c","title":"将之泸郡旅次遂州遇裴晤员外谪居于此话旧凄凉因寄二首 二","author":"郑谷","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["昔年共照松溪影，松折溪荒僧已无。","今日重思锦城事，雪销花谢梦何殊。","乱离未定身俱老，骚雅全休道甚孤。","我拜师门更南去，荔枝春熟向渝泸。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"沉郁","style2":["绮丽"],"mood":"愁怨","mood2":["相思","孤寂"],"scene":["雪","春"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["春天"],"人物":["老师"],"食物":["荔枝"]},"theme_conf":0.92},{"uid":"b3acf8eb-5401-4982-b1a9-a836e4abe5fb","title":"相和歌辞 从军行六首 六","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["黄沙一万里，白首无人怜。","报国劒已折，归乡身幸全。","单于古台下，边色寒苍然。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":["慷慨"],"scene":[],"cats":{"抒情":["孤独","爱国"]},"theme_conf":0.775},{"uid":"f0952fff-6045-44ee-bc86-cf2192e23e7c","title":"题禅院","author":"喻凫","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["无花地亦香，有鹤松多直。","向此奚必孤，山僧尽相识。"],"theme":"闲适隐逸","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["园林","花"],"cats":{"抒情":["孤独"],"山水":["西湖"],"人生":["哲理"]},"theme_conf":0.68},{"uid":"948fa40a-492e-4fa1-99f4-b002ae87cd24","title":"清平调词三首 一","author":"李白","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["云想衣裳花想容，春风拂槛露华浓。","若非群玉山头见，会向瑶台月下逢。"],"theme":"游仙梦幻","theme2":["闺情宫怨"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春","月","山"],"cats":{"抒情":["闺怨"],"四季":["春天"]},"theme_conf":0.513},{"uid":"b48efd98-7757-45e7-88d9-f9bbcadadc51","title":"相里使君第七男生日","author":"包何","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["取妻生子复生男，独有君家众所谈。","荀氏八龙唯欠一，桓山四凤已过三。","他时干蛊声名著，今日悬弧宴乐酣。","谁道众贤能继体，须知个个出于蓝。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":["孤寂"],"scene":["山"],"cats":{"抒情":["孤独"],"天气":["太阳"]},"theme_conf":1.0},{"uid":"04fa7a4c-e624-4083-9668-b05394a5a61d","title":"九日登梓州城","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["伊昔黄花酒，如今白发翁。","追欢筋力异，望远岁时同。","弟妹悲歌里，朝廷醉眼中。","兵戈与关塞，此日意无穷。"],"theme":"边塞征战","theme2":["节令风俗"],"style":"豪放","style2":["悲慨"],"mood":"悲怆","mood2":["欢愉"],"scene":["酒","重阳","塞外"],"cats":{"抒情":["伤感"],"天气":["太阳"],"生活":["边塞"],"节日":["重阳节"]},"theme_conf":0.374},{"uid":"7b60930e-556e-433e-a978-8a175c33ee87","title":"病柏","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["有柏生崇冈，童童状车盖。","偃蹙龙虎姿，主当风云会。","神明依正直，故老多再拜。","岂知千年根，中路颜色坏。","出非不得地，蟠据亦高大。","岁寒忽无凭，日夜柯叶改。","丹凤领九雏，哀鸣翔其外。","鸱鸮志意满，养子穿穴内。","客从何乡来，伫立久吁怪。","静求元精理，浩荡难倚赖。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"悲怆","mood2":["恬淡"],"scene":["冬","夜"],"cats":{"抒情":["思乡"],"四季":["冬天"]},"theme_conf":1.0},{"uid":"60e6c4fc-0583-4d86-898f-9bab22c5846a","title":"杂曲歌辞 壮士行","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["西方太白高，壮士羞病死。","心知报恩处，对酒歌易水。","砂鸿嗥天末，横劒别妻子。","苏武执节归，班超束书起。","山河不足重，重在遇知己。"],"theme":"送别","theme2":["羁旅思乡"],"style":"悲慨","style2":[],"mood":"慷慨","mood2":[],"scene":["酒","山"],"cats":{"抒情":["友情","思乡"]},"theme_conf":0.634},{"uid":"ae660471-84bc-4a58-a438-005b8a99c3c1","title":"赤壁","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["折戟沈沙铁未销，自将磨洗认前朝。","东风不与周郎便，铜雀春深锁二乔。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"惆怅","mood2":[],"scene":["春"],"cats":{"抒情":["怀古"],"四季":["春天"]},"theme_conf":0.739},{"uid":"eb9530d2-e4c7-4c34-9214-06c28ca586bf","title":"渡汉江","author":"宋之问","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["岭外音书断，经冬复历春。","近乡情更怯，不敢问来人。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["江"],"cats":{"抒情":["思乡"]},"theme_conf":0.698},{"uid":"22abc39e-e43e-4644-97f0-08053b5fa3ee","title":"相和歌辞 上云乐","author":"李贺","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["飞香走红满天春，花龙盘盘上紫云。","三千宫女列金屋，五十弦瑟海上闻。","大江碎碎银沙路，嬴女机中断烟素。","断烟素，缝舞衣，八月一日君前舞。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["豪放"],"mood":"欢愉","mood2":[],"scene":["花","春","月"],"cats":{"抒情":["闺怨"],"四季":["春天"],"山水":["长江"],"天气":["写云"]},"theme_conf":1.0},{"uid":"cd8c3590-e097-4289-bcda-ad852ed095ab","title":"杂曲歌辞 悲哉行","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["促促晨复昏，死生同一源。","贵年不惧老，贱老伤久存。","朗朗哭前歌，绛旌引幽魂。","来为千金子，去卧百草根。","黄土塞生路，悲风送回辕。","金鞍旧良马，四顾不出门。","生结千岁念，荣及百代孙。","黄金买性命，白刃讐一言。","宁知北山上，松柏侵田园。"],"theme":"边塞征战","theme2":["送别"],"style":"悲慨","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":["塞外"],"cats":{"抒情":["伤感"],"人物":["老师"],"生活":["田野","边塞"]},"theme_conf":0.516},{"uid":"f619ba03-5e1d-497e-af90-2367f48e9c01","title":"杂曲歌辞 昔昔盐 一去无还意","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["良人征绝域，一去不言还。","百战攻胡虏，三冬阻玉关。","萧萧边马思，猎猎戍旗闲。","独把千重恨，连年未解颜。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["愁怨","恬淡"],"scene":["冬"],"cats":{"抒情":["孤独"],"四季":["冬天"],"人生":["战争"]},"theme_conf":0.796},{"uid":"253ad6ba-185c-4915-9b9a-95e2d1a4515a","title":"梅花二首 二","author":"王初","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["迎春雪艳飘零极，度夕蟾华掩映多。","欲托清香传远信，一枝无计奈愁何。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["花","冬","雪","春"],"cats":{"抒情":["伤感"],"四季":["春天"],"植物":["梅花"]},"theme_conf":0.98},{"uid":"3f6984d9-50a0-4932-be6f-de39922b55c7","title":"中兴乐","author":"毛文锡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["豆蔻花繁烟艳深，丁香輭结同心。","翠鬟女，相与，共淘金。","红蕉叶里猩猩语，鸳鸯浦。","镜中鸾舞，丝雨，隔荔枝阴。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["花","雨"],"cats":{"抒情":["爱情"],"食物":["荔枝"]},"theme_conf":1.0},{"uid":"e05b6908-5d87-4a15-b58b-54fd0c59c00e","title":"旅次汉故畤","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["我行过汉畤，寥落见孤城。","邑里经多难，儿童识五兵。","广川桑遍绿，丛薄雉连鸣。","惆怅萧关道，终军愿请缨。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"惆怅","mood2":["慷慨","孤寂"],"scene":[],"cats":{"抒情":["思乡","孤独","爱国"],"人物":["儿童"]},"theme_conf":0.632},{"uid":"fde30eaa-9b2c-47ce-ba49-c1356353ac9a","title":"陇西行四首 二","author":"陈陶","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["誓扫匈奴不顾身，五千貂锦丧胡尘。","可怜无定河边骨，犹是春闺梦里人。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"绮丽","style2":[],"mood":"相思","mood2":["慷慨"],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"]},"theme_conf":0.448},{"uid":"ad7a0111-98f9-43e5-bad4-9c73c5336389","title":"归雁","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["闻道今春雁，南归自广州。","见花辞涨海，避雪到罗浮。","是物关兵气，何时免客愁。","年年霜露隔，不过五湖秋。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["鸟","秋"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"动物":["写鸟"]},"theme_conf":0.559},{"uid":"32083c21-f38b-4576-93f8-7dda5f34ff6b","title":"湖中古愁三首 二","author":"李群玉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["昔我覩云梦，穷秋经汨罗。","灵均竟不返，怨气成微波。","奠桂开古祠，朦胧入幽萝。","落日潇湘上，凄凉吟九歌。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["端午","江","秋"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"节日":["端午节"]},"theme_conf":0.65},{"uid":"a2aed629-465d-412c-a68d-780068488725","title":"自河南经乱关内阻饥兄弟离散各在一处因望月有感聊书所怀寄上浮梁大兄於潜七兄乌江十五兄兼示符离及下邽弟妹","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["时难年饥世业空，弟兄羇旅各西东。","田园寥落干戈后，骨肉流离道路中。","吊影分为千里鴈，辞根散作九秋蓬。","共看明月应垂泪，一夜乡心五处同。"],"theme":"亲情","theme2":["民生疾苦","亲情","羁旅思乡"],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["月"],"cats":{"抒情":["离别","思乡","伤感"],"山水":["江河"],"天气":["月亮"],"生活":["田野"]},"theme_conf":0.87},{"uid":"183d219f-5901-43a4-ac3a-12ef4bedd6c4","title":"七夕泛舟二首 二","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["凤杼秋期至，凫舟野望开。","微吟翠塘侧，延想白云隈。","石似支机罢，槎疑犯宿来。","天潢殊漫漫，日暮独悠哉。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["七夕","舟"],"cats":{"抒情":["孤独"],"节日":["七夕节"]},"theme_conf":0.9},{"uid":"cp3852710fce4ca5","title":"祝英台近","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["采幽香，巡古苑，竹冷翠微路。","斗草溪根，沙印小莲步。","自怜两鬓清霜，一年寒食，又身在、云山深处。","昼闲度。","因甚天也悭春，轻阴便成雨。","绿暗长亭，归梦趁风絮。","有情花影阑干，莺声门径，解留我、霎时凝伫。"],"theme":"羁旅思乡","theme2":["闲适隐逸","节令风俗","送别"],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["楼","春","清明"],"cats":{"抒情":["离别","思乡"],"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.85},{"uid":"3a07b10d-d744-4217-9ed1-39199b7ec44f","title":"送王六觐巢县叔父二首 二","author":"李涉","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["长忆山阴旧会时，王家兄弟尽相随。","老来放逐潇湘路，泪滴秋风引献之。"],"theme":"送别","theme2":["亲情"],"style":"沉郁","style2":["旷达","婉约"],"mood":"愁怨","mood2":["相思"],"scene":["秋","山"],"cats":{"抒情":["思念","伤感"],"四季":["秋天"],"人物":["父亲"]},"theme_conf":0.603},{"uid":"64458e92-e680-4804-99da-aebca507210b","title":"送进士李殷下第游汾河","author":"曹邺","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["上国花照地，遣君向西征。","旁人亦有恨，况复故人情。","单车欲云去，别酒忽然醒。","如何今夜梦，半作道路程。","边士不好礼，全家住军城。","城中鼓角严，旅客常夜惊。","中有左记室，逢人眼光明。","西门未归者，下马如到京。","还应一开卷，为子心不平。","慇懃说忠抱，壮志勿自轻。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["慷慨"],"scene":["夜","酒"],"cats":{"抒情":["友情"],"人生":["励志","梦想"]},"theme_conf":0.534},{"uid":"29ad430b-4f67-43c7-bbd2-0a7020e2a9aa","title":"和段校书冬夕寄题庐山","author":"刘得仁","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["名高身未到，此恨蓄多时。","是夕吟因话，他年必去随。","尝闻庐岳顶，半入楚江湄。","几处悬崖上，千寻瀑布垂。","炉峰松淅沥，湓浦柳参差。","日色连湖白，钟声拂浪迟。","烟梯缘薜荔，岳寺步欹危。","地本饶灵草，林曾出祖师。","石楼霞耀壁，猨树鹤分枝。","细径萦岩末，高窗见海涯。","嵌空寒更极，寂寞夜尤思。","阴谷冰埋术，仙田雪覆芝。","乱泉禅客濑，异迹逸人知。","藓室新开灶，柽潭末了棋。","如何遂闲放，长得在希夷。","空务渔樵事，方无道路悲。","谢公台尚在，陶令柳潜衰。","尘外难相许，人间贵迹遗。","虽怀丹桂影，不忘白云期。","仁者终携手，今朝预赋诗。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["山","冬"],"cats":{"抒情":["孤独"],"四季":["冬天"],"山水":["庐山","瀑布"]},"theme_conf":0.381},{"uid":"e2046d37-f9c4-40ed-a327-e10c26f7de43","title":"酬皇甫郎中对新菊花见忆","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["爱菊高人吟逸韵，悲秋病客感衰怀。","黄花助兴方携酒，红叶添愁正满堦。","居士荤腥今已断，仙郎杯杓为谁排。","媿君相忆东篱下，拟废重阳一日斋。"],"theme":"寄赠酬答","theme2":["闲适隐逸"],"style":"沉郁","style2":["悲慨","清新"],"mood":"相思","mood2":[],"scene":["重阳","花"],"cats":{"抒情":["思念","伤感"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.92},{"uid":"3a4f178b-0009-40ce-9c8d-2c76c6d58279","title":"马嵬坡","author":"张祜","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["旌旗不整奈君何，南去人稀北去多。","尘土已残香粉艳，荔枝犹到马嵬坡。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"抒情":["怀古"],"动物":["写马"],"食物":["荔枝"]},"theme_conf":0.662},{"uid":"e3bf5676-319c-460e-b5b2-e53daad7f6d0","title":"秋行官张请督促东渚耗稻向毕清晨遣女奴阿稽竖子阿段往问","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东渚雨今足，伫闻稉稻香。","上天无偏颇，蒲稗各自长。","人情见非类，田家戒其荒。","功夫竞搰搰，除草置岸旁。","谷者命之本，客居安可忘。","青春具所务，勤垦免乱常。","吴牛力容易，竝驱动莫当。","丰苗亦已穊，云水照方塘。","有生固蔓延，静一资隄防。","督领不无人，提携颇在纲。","荆扬风土暖，肃肃候微霜。","尚恐主守疎，用心未甚臧。","清朝遣婢仆，寄语逾崇冈。","西成聚必散，不独陵我仓。","岂要仁里誉，感此乱世忙。","北风吹蒹葭，蟋蟀近中堂。","荏苒百工休，郁纡迟暮伤。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["沉郁","婉约"],"mood":"孤寂","mood2":["恬淡"],"scene":["秋","江"],"cats":{"抒情":["孤独"],"四季":["秋天"],"人生":["青春"],"生活":["田野"]},"theme_conf":0.688},{"uid":"6cc5782f-97e4-4f04-970a-d56618e8edf9","title":"杂曲歌辞 少年行三首 一","author":"李白","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["击筑饮美酒，劒歌易水湄。","经过燕太子，结托幷州儿。","少年负壮气，奋烈自有时。","因声鲁句践，争情勿相欺。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"慷慨","mood2":[],"scene":["酒"],"cats":{"抒情":["思乡"],"人生":["青春"]},"theme_conf":0.65},{"uid":"e26934fb-899d-4d12-aeec-81f11c5e903f","title":"送辰州郑使君","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["谁人不谴谪，君去独堪伤。","长子家无弟，慈亲老在堂。","惊魂随驿吏，冒暑向炎方。","未到猨啼处，参差已断肠。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["夏"],"cats":{"抒情":["伤感","孤独"],"四季":["夏天"],"人物":["母亲"]},"theme_conf":0.758},{"uid":"8036c622-e19b-454b-be17-d5fd4f9ec789","title":"江畔独步寻花七绝句 三","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["江深竹静两三家，多事红花映白花。","报答春光知有处，应须美酒送生涯。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["江","花"],"cats":{"抒情":["孤独","感恩"],"山水":["江河"]},"theme_conf":0.703},{"uid":"9149aa7c-b352-4a0f-aaeb-85ab10403744","title":"和谢舍人雪夜寓直","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["禁省夜沈沈，春风雪满林。","沧洲归客梦，青琐近臣心。","挥翰宣鸣玉，承恩在赐金。","建章寒漏起，更助掖垣深。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["夜","雪"],"cats":{"抒情":["思乡","感恩"],"天气":["写雪"]},"theme_conf":1.0},{"uid":"e4d4c69a-9803-4863-bb93-8b0be8420bbd","title":"郊居对雨寄赵涓给事包佶郎中","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["暑雨青山里，随风到野居。","乱沤浮曲砌，悬溜响前除。","尘镜愁多掩，蓬头嬾更梳。","夜窗凄枕席，阴壁润图书。","萧飒宜新竹，龙钟拾野蔬。","石泉空自咽，药圃不堪锄。","浊水淙深辙，荒兰拥败渠。","繁枝留宿鸟，碎浪出寒鱼。","桑屐时登望，荷衣自卷舒。","应怜在泥滓，无路托高车。"],"theme":"山水田园","theme2":["送别"],"style":"清新","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":["雨","夏"],"cats":{"抒情":["伤感"],"四季":["夏天"],"天气":["写雨"],"生活":["田野"]},"theme_conf":0.577},{"uid":"1f85b405-4320-4281-aba7-61db92674d02","title":"相和歌辞 白头吟二首 二","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["锦水东流碧，波荡双鸳鸯。","雄巢汉宫树，雌弄秦草芳。","相如去蜀谒武帝，赤车驷马生辉光。","一朝再览大人作，万乘忽欲凌云翔。","闻道阿娇失恩宠，千金买赋要君王。","相如不忆贫贱日，官高金多聘私室。","茂陵姝子皆见求，文君欢爱徒此毕。","泪如双泉水，行堕紫罗襟。","五起鸡三唱，清晨白头吟。","长吁不整绿云鬓，仰诉青天哀怨深。","城崩杞梁妻，谁道土无心。","东流不作西归水，落花辞枝羞故林。","头上玉燕钗，是妾嫁时物。","赠君表相思，罗袖幸时拂。","莫卷龙须席，从他生网丝。","且留琥珀枕，还有梦来时。","鹔鹴裘在锦屏上，自君一挂无由披。","妾有秦楼镜，照心胜照井。","愿持照新人，双对可怜影。","覆水却收不满杯，相如还谢文君回。","古来得意不相负，祗今惟有青陵台。"],"theme":"闺情宫怨","theme2":["闺情宫怨","爱情相思","山水田园"],"style":"绮丽","style2":["沉郁","清新"],"mood":"相思","mood2":["愁怨"],"scene":["楼","花"],"cats":{"抒情":["爱情","思念","伤感","闺怨"]},"theme_conf":0.95},{"uid":"59f7c852-316a-4a45-838a-923df108a993","title":"赠王二十四侍御契四十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["往往虽相见，飘飘媿此身。","不关轻绂冕，俱是避风尘。","一别星桥夜，三移斗柄春。","败亡非赤壁，奔走为黄巾。","子去何潇洒，余藏异隐沦。","书成无过雁，衣故有县鹑。","恐惧行装数，伶俜卧疾频。","晓鸎工迸泪，秋月解伤神。","会面嗟黧黑，含凄话苦辛。","接舆还入楚，王粲不归秦。","锦里残丹灶，花溪得钓纶。","消中祗自惜，晚起索谁亲。","伏柱闻周史，乘槎有汉臣。","鸳鸿不易狎，龙虎未宜驯。","客则挂冠至，交非倾盖新。","由来意气合，直取性情真。","浪迹同生死，无心耻贱贫。","偶然存蔗芋，幸各对松筠。","麤饭依他日，穷愁怪此辰。","女长裁褐稳，男大卷书匀。","漰口江如练，蚕崖雪似银。","名园当翠𪩘，野棹没青苹。","屡喜王侯宅，时邀江海人。","追随不觉晚，欵曲动弥旬。","但使芝兰秀，何烦栋宇邻。","山阳无俗物，郑驿正留宾。","出入并鞍马，光辉参席珍。","重游先主庙，更历少城𬮱。","石镜通幽魄，琴台隐绛唇。","送终惟粪土，结爱独荆榛。","置酒高林下，观碁积水滨。","区区甘累趼，稍稍息劳筋。","网聚粘圆鲫，丝繁煮细莼。","长歌敲柳瘿，小睡凭藤轮。","农月须知课，田家敢忘勤。","浮生难去食，良会惜清晨。","列国兵戈暗，今王德教淳。","要闻除䝟貐，休作画麒麟。","洗眼看轻薄，虚怀任屈伸。","莫令胶漆地，万古重雷陈。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"婉约","style2":["沉郁","旷达"],"mood":"愁怨","mood2":[],"scene":["夜","雪"],"cats":{"抒情":["伤感"],"生活":["田野","写桥"]},"theme_conf":0.96},{"uid":"4506e47c-d89b-45ca-a9c5-8f9c457409b6","title":"奉酬睢阳李太守","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["公族称王佐，朝经允帝求。","本枝疆我李，盘石冠诸刘。","礼乐光辉盛，山河气象幽。","系高周柱史，名重晋阳秋。","华省膺推择，青云宠宴游。","握兰多具美，前席有嘉谋。","赋得黄金赐，言皆白璧酬。","着鞭驱驷马，操刃解全牛。","出镇兼方伯，承家复列侯。","朝瞻孔北海，时用杜荆州。","广固才登陟，毘陵忽阻修。","三台冀入梦，四岳尚分忧。","郡邑连京口，山川望石头。","海门当建节，江路引鸣驺。","俗见中兴理，人逢至道休。","先移白额横，更息赭衣偷。","梁国歌来晚，徐方怨不留。","岂伊齐政术，将以变浇浮。","讼简知能吏，刑宽察要囚。","坐堂风偃草，行县雨随辀。","地是蒙庄宅，城遗阏伯丘。","孝王余井径，微子故田畴。","冬至招摇转，天寒䗖𬟽收。","猿岩飞雨雪，兔苑落梧楸。","列戟霜侵户，褰帏月在钩。","好贤常解榻，乘兴每登楼。","逸足横千里，高谈注九流。","诗题青玉案，衣赠黑貂裘。","穷巷轩车静，闲斋耳目愁。","未能方管乐，翻欲慕巢由。","讲德良难敌，观风岂易俦。","寸心仍有适，江海一扁舟。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["恬淡","欢愉"],"scene":["楼","舟","冬","山","秋"],"cats":{"抒情":["伤感"],"四季":["秋天","冬天"],"人生":["梦想"]},"theme_conf":0.95},{"uid":"21d815f2-631f-4389-935e-f7054b2552e2","title":"谪官辰州冬至日[有]怀","author":"戎昱","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["去年长至在长安，策杖曾簪獬豸冠。","此岁长安逢至日，下堦遥想雪霜寒。","梦随行伍朝天去，身寄穷荒报国难。","北望南郊消息断，江头唯有泪阑干。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"慷慨","mood2":["相思","愁怨"],"scene":["冬"],"cats":{"抒情":["思乡","伤感","爱国"],"四季":["冬天"],"天气":["太阳"]},"theme_conf":0.86},{"uid":"ac8989bc-6581-4530-9869-49574f9b111c","title":"竹","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["卷箨正离披，新枝复蒙密。","翛翛月下闻，褭褭林际出。","岂独对芳菲，终年色如一。"],"theme":"山水田园","theme2":["咏物","送别"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["月","春"],"cats":{"抒情":["孤独"],"植物":["竹子"]},"theme_conf":0.392},{"uid":"ebaa76e9-e569-4145-bf34-2c543612c475","title":"郊庙歌辞 享懿德太子庙乐章 登歌酌鬯","author":"不详","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["誉阐元储，寄崇明两。","玉裕虽晦，铜楼可想。","弦诵辍音，笙歌罢响。","币帛言设，礼容无爽。"],"theme":"咏史怀古","theme2":["送别"],"style":"悲慨","style2":[],"mood":"欢愉","mood2":[],"scene":["酒"],"cats":{"抒情":["怀古"],"食物":["写酒"]},"theme_conf":0.585},{"uid":"cp5992981c866722","title":"高阳台","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["修竹凝妆，垂杨驻马，凭阑浅画成图。","山色谁题，楼前有雁斜书。","东风紧送斜阳下，弄旧寒、晚酒醒馀。","自销凝，能几花前，顿老相如。","伤春不在高楼上，在灯前攲枕，雨外熏炉。","怕舣游船，临流可奈清臞。","飞红若到西湖底，搅翠澜、总是愁鱼。","莫重来，吹尽香绵，泪满平芜。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["婉约","绮丽"],"mood":"愁怨","mood2":[],"scene":["楼","春","花"],"cats":{"抒情":["伤感"],"四季":["春天"],"山水":["西湖"]},"theme_conf":1.0},{"uid":"9154fc22-5e19-45b7-a506-435298bb26fc","title":"台城","author":"韦庄","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["江雨霏霏江草齐，六朝如梦鸟空啼。","无情最是台城柳，依旧烟笼十里堤。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"惆怅","mood2":[],"scene":["雨","楼"],"cats":{"抒情":["怀古"]},"theme_conf":0.767},{"uid":"e641d940-1046-4717-a1eb-e7eff336bc3b","title":"婺州路别录事","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["府中相见少，江上独行遥。","会日起离恨，新年别旧僚。","春云犹伴雪，寒渚未通潮。","回首群山暝，思君转寂寥。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["离别","孤独"],"节日":["春节"]},"theme_conf":1.0},{"uid":"cd7b79ad-21b9-4628-ab5f-ddc8ba1343b6","title":"病橘","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["群橘少生意，虽多亦奚为。","惜哉结实小，酸涩如棠棃。","剖之尽蠹虫，采掇爽其宜。","纷然不适口，岂只存其皮。","萧萧半死叶，未忍别故枝。","玄冬霜雪积，况乃回风吹。","尝闻蓬莱殿，罗列潇湘姿。","此物岁不稔，玉食失光辉。","寇盗尚凭陵，当君减膳时。","汝病是天意，吾谂罪有司。","忆昔南海使，奔腾献荔支。","百马死山谷，到今耆旧悲。"],"theme":"送别","theme2":["游仙梦幻"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["冬","雪"],"cats":{"抒情":["伤感"],"四季":["冬天"]},"theme_conf":0.541},{"uid":"43f8bb74-5673-41a8-96ac-6a5e3a906382","title":"北风","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["春生南国瘴，气待北风苏。","向晚霾残日，初宵鼓大𬬻。","爽携卑湿地，声拔洞庭湖。","万里鱼龙伏，三更鸟兽呼。","涤除贪破浪，愁绝付摧枯。","执热沈沈在，凌寒往往须。","且知宽疾胏，不敢恨危途。","再宿烦舟子，衰容问仆夫。","今晨非盛怒，便道即长驱。","隐几看帆席，云州涌坐隅。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":["豪放"],"mood":"愁怨","mood2":[],"scene":["夜","江","舟"],"cats":{"抒情":["伤感"],"天气":["写风"],"人生":["励志"]},"theme_conf":0.72},{"uid":"862104e5-cfeb-4843-9e5f-8bdff6294563","title":"感春","author":"戎昱","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["看花泪尽知春尽，魂断看花秪恨春。","名位未沾身欲老，诗书宁救眼前贫。"],"theme":"游仙梦幻","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["伤感"],"四季":["春天"],"人生":["读书"]},"theme_conf":0.65},{"uid":"f89aa5e5-a703-4956-8fa0-91a512364ee8","title":"读史五首 一","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["楚怀放灵均，国政亦荒淫。","彷徨未忍决，绕泽行悲吟。","汉文疑贾生，谪置湘之阴。","是时刑方措，此去难为心。","士生一代间，谁不有浮沈。","良时真可惜，乱世何足钦。","乃知汨罗恨，未抵长沙深。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["愁怨"],"scene":["端午"],"cats":{"抒情":["伤感","怀古"],"节日":["端午节"]},"theme_conf":0.98},{"uid":"78f6ebbf-396a-4980-bbf1-0c14d80d384d","title":"二灵寺守岁","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["守岁山房迥绝缘，灯光香灺共萧然。","无人更献椒花颂，有客同参栢子禅。","已悟化城非乐界，不知今夕是何年。","忧心悄悄浑忘寐，坐待扶桑日丽天。"],"theme":"节令风俗","theme2":["哲理悟道"],"style":"清新","style2":[],"mood":"孤寂","mood2":["欢愉","愁怨"],"scene":["除夕"],"cats":{"抒情":["孤独"],"人生":["哲理"],"节日":["春节"]},"theme_conf":0.76},{"uid":"3e627ebd-0fd3-4669-a32c-5d108d5d4ce6","title":"相和歌辞 决绝[词]三首 一","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["乍可为天上牵牛织女星，不愿为庭前红槿枝。","七月七日一相见，故心终不移。","那能朝开暮飞去，一任东西南北吹。","分不两相守，恨不两相思。","对面且如此，背面当何知。","春风撩乱伯劳语，此时抛去时。","握手苦相问，竟不言后期。","君情既决绝，妾意已参差。","借如死生别，安得长苦悲。"],"theme":"闺情宫怨","theme2":["爱情相思"],"style":"旷达","style2":["沉郁"],"mood":"悲怆","mood2":["相思","愁怨"],"scene":["七夕","春","月"],"cats":{"抒情":["爱情","思念","伤感","闺怨"],"四季":["春天"],"天气":["星星"],"节日":["七夕节"]},"theme_conf":0.84},{"uid":"a352e426-485f-4d00-8ae5-98191e2c5a87","title":"晚晴吴郎见过北舍","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["圃畦新雨润，媿子废鉏来。","竹杖交头拄，柴扉隔径开。","欲栖群鸟乱，未去小童催。","明日重阳酒，相迎自酦醅。"],"theme":"咏史怀古","theme2":["节令风俗"],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["重阳","江南","酒","雨"],"cats":{"抒情":["怀古"],"节日":["重阳节"]},"theme_conf":0.514},{"uid":"9c08d89e-9c4a-4cb2-a7f7-8affe0e8fe70","title":"送夏侯校书归华阴别墅","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["山前白鹤村，竹雪覆柴门。","候客定为黍，务农因燎原。","乳冰悬暗井，莲石照晴轩。","贳酒邻里睦，曝衣场圃喧。","依然望君去，余性亦何昏。"],"theme":"送别","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["夏","冬"],"cats":{"抒情":["离别"],"四季":["夏天"],"生活":["乡村"]},"theme_conf":0.483},{"uid":"e9ff4727-4dec-4fd8-ab61-336c693af7c3","title":"清明日登城春望寄大夫使君","author":"王表","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["春城闲望爱睛天，何处风光不眼前。","寒食花开千树雪，清明日出万家烟。","兴来促席唯同舍，醉后狂歌尽少年。","闻说莺啼却惆怅，诗成不见谢临川。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["清新"],"mood":"相思","mood2":["惆怅"],"scene":["清明","春"],"cats":{"抒情":["思念"],"四季":["春天"],"天气":["太阳"],"节日":["寒食节","清明节"]},"theme_conf":0.86},{"uid":"1dc19ddd-357b-4a1a-b5b2-260954fde2a4","title":"华清宫和杜舍人","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["五十年天子，离宫仰峻墙。","登封时正泰，御宇日何长。","上位先名实，中兴事宪章。","起戎轻甲胄，余地复河湟。","道帝玄元祖，儒封孔子王。","因缘百司署，藂会一人汤。","渭水波摇绿，秦郊草半黄。","马驯金勒细，鹰健玉铃锵。","下箭朱弓满，鸣鞭皓腕攘。","畋思获吕望，谏祇避周昌。","兔迹贪前逐，枭心不早防。","几添鹦鹉劝，先赐荔枝尝。","月锁千门静，天吹一笛凉。","细音摇羽珮，轻步宛霓裳。","祸乱基潜结，升平意遽忘。","衣冠逃犬虏，鼙鼓动渔阳。","外戚心殊迫，中途事可量。","血埋妃子艳，刅断禄儿肠。","近侍烟尘隔，前踪辇路荒。","益知迷宠佞，遗恨丧贤良。","北阙尊明主，南宫逊上皇。","禁清余凤吹，池冷睡龙光。","祝寿山犹在，流年水共伤。","杜鹃魂厌蜀，蝴蝶梦悲庄。","雀卵遗雕栱，虫丝罥画粱。","紫苔侵壁润，红树闭门芳。","守吏齐鸳瓦，耕民得翠珰。","登年齐酺乐，讲武旧兵场。","暮草深岩翠，幽花坠径香。","不堪垂白叟，行折御沟杨。"],"theme":"咏史怀古","theme2":["咏史怀古","边塞征战"],"style":"绮丽","style2":["清新","婉约"],"mood":"相思","mood2":["欢愉","悲怆"],"scene":["花","山"],"cats":{"抒情":["伤感","怀古"],"人生":["时光","战争"],"食物":["荔枝"]},"theme_conf":0.97},{"uid":"50b39f91-4d82-4166-b291-d73be5d35733","title":"阻雨不得归瀼西甘林","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["三伏适已过，骄阳化为霖。","欲归瀼西宅，阻此江浦深。","坏舟百版坼，峻岸复万寻。","篙工初一弃，恐泥劳寸心。","伫立东城隅，怅望高飞禽。","草堂乱悬圃，不隔昆仑岑。","昏浑衣裳外，旷绝同层阴。","园甘长成时，三寸如黄金。","诸侯旧上计，厥贡倾千林。","邦人不足重，所迫豪吏侵。","客居暂封殖，日夜偶瑶琴。","虚徐五株态，侧塞烦胸襟。","焉得辍两足，杖藜出岖嵚。","条流数翠实，偃息归碧浔。","拂拭乌皮几，喜闻樵牧音。","令儿快搔背，脱我头上簪。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["雨"],"cats":{"抒情":["思乡"],"天气":["写雨"]},"theme_conf":0.357},{"uid":"cp6327af1ef41d9d","title":"菩萨蛮","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["郁孤台下清江水。","中间多少行人泪。","西北是长安。","可怜无数山。","青山遮不住。","毕竟江流去。","江晚正愁予。","山深闻鹧鸪。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["江","山"],"cats":{"抒情":["伤感","怀古"],"山水":["江河"]},"theme_conf":0.84},{"uid":"e1404531-b21b-4e48-b715-9a9ead6cf56c","title":"寄卢仝","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["玉川先生洛城里，破屋数间而已矣。","一奴长须不裹头，一婢赤脚老无齿。","辛勤奉养十余人，上有慈亲下妻子。","先生结发憎俗徒，闭门不出动一纪。","至今邻僧乞米送，仆忝县尹能不耻。","俸钱供给公私余，时致薄少助祭祀。","劝参留守谒大尹，言语才及輙掩耳。","水北山人得名声，去年去作幕下士。","水南山人又继往，鞍马仆从塞闾里。","少室山人索价高，两以谏官徴不起。","彼皆刺口论世事，有力未免遭驱使。","先生事业不可量，惟用法律自绳己。","春秋三传束高阁，独抱遗经究终始。","往年弄笔嘲同异，怪辞惊众谤不已。","近来自说寻坦途，犹上虚空跨绿駬。","去年生儿名添丁，意令与国充耘耔。","国家丁口连四海，岂无农夫亲耒耜。","先生抱才终大用，宰相未许终不仕。","假如不在陈力列，立言垂范亦足恃。","苗裔当蒙十世宥，岂谓贻厥无基阯。","故知忠孝生天性，洁身乱伦安足拟。","昨晚长须来下状，隔墙恶少恶难似。","每骑屋山下窥阚，浑舍惊怕走折趾。","凭依婚媾欺官吏，不信令行能禁止。","先生受屈未曾语，忽此来告良有以。","嗟我身为赤县令，操权不用欲何俟。","立召贼曹呼伍伯，尽取鼠辈尸诸市。","先生又遣长须来，如此处置非所喜。","况又时当长养节，都邑未可猛政理。","先生固是余所畏，度量不敢窥涯涘。","放纵是谁之过欤，效尤戮仆愧前史。","买羊沽酒谢不敏，偶逢明月曜桃李。","先生有意许降临，更遣长须致双鲤。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["月","春","塞外","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"天气":["月亮"],"人物":["母亲"]},"theme_conf":0.95},{"uid":"cb8e3c11-4405-450d-ab33-af54d1dc2df0","title":"五老峰大明观赠隐者","author":"姚系","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["云观此山北，与君携手稀。","林端涉横水，洞口入斜晖。","颇觉鸾鹤迩，忽为烟雾飞。","故人清和客，默会琴心微。","丹术幸可授，青龙当未归。","悠悠平生意，此日复相违。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"抒情":["友情"],"山水":["庐山"]},"theme_conf":0.86},{"uid":"cp63c0eb274856fe","title":"念奴娇","author":"张孝祥","dynasty":"宋","section":"宋词","form":"词","paragraphs":["洞庭青草，近中秋、更无一点风色。","玉鉴琼田三万顷，著我扁舟一叶。","素月分辉，明河共影，表里俱澄澈。","悠然心会，妙处难与君说。","应念岭海经年，孤光自照，肝肺皆冰雪。","短发萧骚襟袖冷，稳泛沧浪空阔。","尽吸西江，细斟北斗，万象为宾客。","扣舷独笑，不知今夕何夕。"],"theme":"羁旅思乡","theme2":["节令风俗"],"style":"冲淡","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":["雪","江","舟","中秋","冬"],"cats":{"抒情":["思乡","孤独"],"天气":["写雪"],"节日":["中秋节"]},"theme_conf":0.529},{"uid":"b08883e7-d43b-45fd-9c1d-b770b8e8bbdf","title":"奉使过石门观瀑","author":"丘丹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["溪上望悬泉，耿耿云中见。","披榛上岩岫，峭壁正东面。","千仞泻联珠，一潭喷飞霰。","嵯𤄓满山响，坐觉炎氛变。","照日类虹霓，从风似绡练。","灵奇既天造，惜处穷海甸。","吾祖昔登临，谢公亦游衍。","王程惧淹泊，下磴空延眷。","千里雷尚闻，峦回树葱蒨。","此来共贱役，探讨愧前彦。","永欲洗尘缨，终当惬此愿。"],"theme":"山水田园","theme2":["咏史怀古","民生疾苦"],"style":"幽峭","style2":[],"mood":"恬淡","mood2":[],"scene":["山"],"cats":{"抒情":["怀古"],"山水":["瀑布"],"天气":["彩虹"]},"theme_conf":0.44},{"uid":"0be9008f-d175-47f6-aa53-87fce8d020fa","title":"渔父歌","author":"高适","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["曲岸深潭一山叟，驻眼看钩不移手。","世人欲得知姓名，良久问他不开口。","笋皮笠子荷叶衣，心无所营守钓矶。","料得孤舟无定止，日暮持竿何处归。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["舟","山"],"cats":{"抒情":["孤独"],"人物":["父亲"]},"theme_conf":0.545},{"uid":"afc2e6d6-e67f-4513-a6ab-82841d2f97cc","title":"寄人 一","author":"张泌","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["别梦依依到谢家，小廊回合曲阑斜。","多情只有春庭月，犹为离人照落花。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["月","园林"],"cats":{"抒情":["离别"]},"theme_conf":0.9},{"uid":"7e6e299e-64bd-43d0-a15b-7512bead4c84","title":"惜别行送向卿进奉端午御衣之上都","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["肃宗昔在灵武城，指挥猛将收咸京。","向公泣血洒行殿，佐佑卿相乾坤平。","逆胡冥寞随烟烬，卿家兄弟功名震。","麒麟图画鸿雁行，紫极出入黄金印。","尚书勋业超千古，雄镇荆州继吾祖。","裁缝云雾成御衣，拜跪题封向端午。","向卿将命寸心赤，青山落日江潮白。","卿到朝廷说老翁，漂零已是沧浪客。"],"theme":"送别","theme2":["节令风俗"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["慷慨"],"scene":["端午"],"cats":{"抒情":["离别"],"节日":["端午节"]},"theme_conf":0.369},{"uid":"f7c9c409-9571-4eb8-abd9-91ec6c1ff564","title":"常娥","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["云母屏风烛影深，长河渐落晓星沈。","常娥应悔偷灵药，碧海青天夜夜心。"],"theme":"闺情宫怨","theme2":[],"style":"雄浑","style2":[],"mood":"孤寂","mood2":[],"scene":["中秋","夜"],"cats":{"抒情":["闺怨"],"节日":["中秋节"]},"theme_conf":0.72},{"uid":"7b1fdef6-f900-4fbc-8542-43c3cdd6eab7","title":"九日奉陪令公登白楼同咏菊","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["琼尊犹有菊，可以献留侯。","愿比三花秀，非同百卉秋。","金英分蘂细，玉露结房稠。","黄雀知恩在，衔飞亦上楼。"],"theme":"应制干谒","theme2":["咏物","咏史怀古"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳","楼"],"cats":{"抒情":["怀古"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.78},{"uid":"7dfd67f3-45f7-404f-a5b2-f25e123508ea","title":"送郑权尚书南海","author":"王建","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["七郡双旌贵，人皆不忆廻。","戍头龙脑铺，关口象牙堆。","勅设熏𬬻出，蛮辞咒节开。","市喧山贼破，金贱海船来。","白氎家家织，红蕉处处栽。","已将身报国，莫起望乡台。"],"theme":"送别","theme2":["羁旅思乡"],"style":"豪放","style2":["绮丽"],"mood":"慷慨","mood2":["相思"],"scene":["舟","山"],"cats":{"抒情":["思念","思乡","爱国"]},"theme_conf":0.443},{"uid":"f88a6dbd-bf83-458c-b5e2-85fdd1ed98b2","title":"至德二载甫自京金光门出问道归凤翔乾元初从左拾遗移华州掾与亲故别因出此门有悲往事","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["此道昔归顺，西郊胡正繁。","至今残破胆，应有未招魂。","近得归京邑，移官岂至尊。","无才日衰老，驻马望千门。"],"theme":"送别","theme2":["悼亡挽歌"],"style":"悲慨","style2":["绮丽","沉郁"],"mood":"悲怆","mood2":["相思"],"scene":[],"cats":{"抒情":["离别","伤感","悼亡"]},"theme_conf":0.389},{"uid":"5bce54d8-5f1a-487b-807c-b30714c006f4","title":"不见","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["不见李生久，佯狂真可哀。","世人皆欲杀，吾意独怜才。","敏捷诗千首，飘零酒一桮。","匡山读书处，头白好归来。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["沉郁","悲慨"],"mood":"相思","mood2":[],"scene":["山"],"cats":{"抒情":["思念"],"人生":["读书"]},"theme_conf":0.76},{"uid":"2c1d7719-593f-489d-ae78-3e1e34a66412","title":"鼓吹曲辞 将进酒","author":"李贺","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["将进酒，将进酒。","酒中有毒酖主父，言之主父伤主母。","母为妾地父妾天，仰天俯地不忍言。","佯为僵踣主父前，主父不知加妾鞭。","旁人知妾为主说，主将泪洗鞭头血。","推摧主母牵下堂，扶妾遣升堂上床。","将进酒，酒中无毒令主寿。","愿主回思归主母，遣妾如此事主父。","妾为此事人偶知，自慙不密方自悲。","主今颠倒安置妾，贪天僭地谁不为。"],"theme":"讽喻刺世","theme2":["闺情宫怨","羁旅思乡","闲适隐逸"],"style":"豪放","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":["酒"],"cats":{"抒情":["思乡","伤感","闺怨"],"人物":["父亲"],"食物":["写酒"]},"theme_conf":0.9},{"uid":"08d0e076-ff46-4c75-b7d2-60a94290dfb6","title":"千叶桃花","author":"杨凭","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["千叶桃花胜百花，孤荣春晚驻年华。","若教避俗秦人见，知向河源旧侣夸。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["花"],"cats":{"抒情":["孤独"],"山水":["黄河"],"植物":["桃花","叶子"]},"theme_conf":1.0},{"uid":"03999410-ba31-4a8a-8718-340aa7d38735","title":"相和歌辞 江南曲八首 六","author":"刘希夷","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["暮春三月晴，维扬吴楚城。","城临大江汜，回映洞浦清。","晴云曲金阁，珠楼碧烟里。","月明芳树群鸟飞，风过长林杂花起。","可怜离别谁家子，于此一至情何已。"],"theme":"送别","theme2":["山水田园"],"style":"绮丽","style2":["清新"],"mood":"惆怅","mood2":[],"scene":["江南","江"],"cats":{"抒情":["离别"],"山水":["江河","长江"]},"theme_conf":0.58},{"uid":"f523cd08-69d6-45c1-bc6a-633f43223f59","title":"春日淇上作","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["淇上春风涨，鸳鸯逐浪飞。","清明桑叶小，度雨杏花稀。","卫女红粧薄，王孙白马肥。","相将踏青去，不解惜罗衣。"],"theme":"节令风俗","theme2":["爱情相思","山水田园"],"style":"绮丽","style2":["婉约"],"mood":"欢愉","mood2":[],"scene":["春","清明"],"cats":{"抒情":["爱情"],"四季":["春天"],"节日":["清明节"]},"theme_conf":0.9},{"uid":"e9e6425c-6c14-4f69-8694-87a8b96a43de","title":"春望","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["国破山河在，城春草木深。","感时花溅泪，恨别鸟惊心。","烽火连三月，家书抵万金。","白头搔更短，浑欲不胜簪。"],"theme":"咏怀抒感","theme2":["边塞征战","山水田园"],"style":"沉郁","style2":["悲慨"],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["伤感"],"四季":["春天"],"人生":["战争"]},"theme_conf":0.7},{"uid":"186aab50-4ead-4c61-9764-1867aec86f52","title":"寄张十二山人彪三十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["独卧蒿阳客，三违颍水春。","艰难随老母，惨澹向时人。","谢氏寻山屐，陶公漉酒巾。","群凶弥宇宙，此物在风尘。","历下辞姜被，关西得孟邻。","早通交契密，晚接道流新。","静者心多妙，先生艺绝伦。","草书何太苦，诗兴不无神。","曹植休前辈，张芝更后身。","数篇吟可老，一字买堪贫。","将恐曾防寇，深潜托所亲。","宁闻倚门夕，尽力洁飧晨。","疎嬾为名误，驱驰丧我真。","索居犹寂寞，相遇益悲辛。","流转依边徼，逢迎念席珍。","时来故旧少，乱后别离频。","世祖修高庙，文公赏从臣。","商山犹入楚，源水不离秦。","存想青龙秘，骑行白鹿驯。","耕岩非谷口，结草即河滨。","肘后符应验，囊中药未陈。","旅怀殊不惬，良觌渺无因。","自古皆悲恨，浮生有屈伸。","此邦今尚武，何处且依仁。","鼓角凌天籁，关山信月轮。","官场罗镇碛，贼火近洮岷。","萧索论兵地，苍茫鬬将辰。","大军多处所，余孽尚纷纶。","高兴知笼鸟，斯文起获麟。","穷秋正摇落，回首望松筠。"],"theme":"寄赠酬答","theme2":["山水田园","边塞征战","羁旅思乡"],"style":"冲淡","style2":["悲慨","雄浑"],"mood":"孤寂","mood2":["恬淡","愁怨"],"scene":["山"],"cats":{"抒情":["离别","思乡","伤感","孤独"],"人物":["母亲"]},"theme_conf":0.98},{"uid":"479f4614-220f-481a-b5ac-0fe0fbe3c708","title":"谢寄新茶","author":"杨嗣复","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["石上生芽二月中，蒙山顾渚莫争雄。","封题寄与杨司马，应为前衔是相公。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["月","山"],"cats":{"抒情":["感恩"],"食物":["写茶"]},"theme_conf":0.88},{"uid":"42bc232f-00c5-4e92-8c55-8f38280a9dbe","title":"杂曲歌辞 爱妾换马 一","author":"张祜","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["一面妖桃千里蹏，娇姿骏背价应齐。","乍牵玉勒辞金栈，催整花钿出绣闺。","去日岂无沾袂泣，归时还有顿衔嘶。","婵娟躞蹀春风里，挥手摇鞭杨柳堤。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"悲怆","mood2":[],"scene":["中秋","春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"节日":["中秋节"],"动物":["写马"]},"theme_conf":1.0},{"uid":"153dd336-48dc-4173-a668-e9b90b2304fb","title":"舞曲歌辞 冬白纻歌","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["吴宫夜长宫漏款，帘幕四垂灯焰暖。","西施自舞王自管，雪纻翻翻鹤翎散。","促节牵繁舞腰嬾，舞腰嬾，王罢饮。","盖覆西施凤花锦，身作匡床臂为枕。","朝佩𪭢𪭢王晏寝，酒醒阍报门无事。","子胥死后言为讳，近王之臣谕王意。","共笑越王穷惴惴，夜夜抱冰寒不睡。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["欢愉"],"scene":["冬","夜"],"cats":{"抒情":["怀古"],"四季":["冬天"]},"theme_conf":1.0},{"uid":"b67ddf05-43fb-4859-a1a9-34f95d45aabf","title":"和晋陵陆丞早春游望","author":"韦应物","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["独有宦游人，偏惊物候新。","云霞出海曙，梅柳渡江春。","淑气催黄鸟，晴光照绿苹。","忽闻歌苦调，归思欲沾巾。"],"theme":"羁旅思乡","theme2":["咏史怀古","送别"],"style":"清新","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["春"],"cats":{"抒情":["思乡","怀古"],"四季":["春天"],"天气":["写云"]},"theme_conf":0.464},{"uid":"ee3195f6-eb17-4e87-b714-f7cf07ff03f2","title":"鼓吹曲辞 上之回","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["三十六离宫，楼台与天通。","阁道步行月，美人愁烟空。","恩疎宠不及，桃李伤春风。","淫乐意何极，金舆向回中。","万乘出黄道，千旗扬彩虹。","前军细柳北，后骑甘泉东。","岂问渭川老，宁邀襄野童。","秋暮瑶池宴，归来乐未穷。"],"theme":"民生疾苦","theme2":["边塞征战"],"style":"沉郁","style2":["悲慨"],"mood":"欢愉","mood2":["愁怨"],"scene":["楼","春"],"cats":{"抒情":["伤感"],"四季":["春天"],"天气":["彩虹"],"人物":["女子"]},"theme_conf":0.538},{"uid":"4cfeb483-2cfb-4f3e-8ed1-059eaccdd260","title":"君不见简苏徯","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见道边废弃池，君不见前者摧折桐。","百年死树中琴瑟，一斛旧水藏蛟龙。","丈夫盖棺事始定，君今幸未成老翁。","何恨顦顇在山中，深山穷谷不可处，霹雳魍魉兼狂风。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"豪放","style2":["沉郁"],"mood":"相思","mood2":[],"scene":["山"],"cats":{"抒情":["思念"],"天气":["写风"]},"theme_conf":0.88},{"uid":"26587ca4-6af1-4180-a430-b29652a14f1d","title":"送高司直寻封阆州","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["丹雀衔书来，暮栖何乡树。","骅骝事天子，辛苦在道路。","司直非冗官，荒山甚无趣。","借问泛舟人，胡为入云雾。","与子姻娅间，即亲亦有故。","万里长江边，邂逅一相遇。","长卿消渴再，公干沈緜屡。","清谈慰老夫，开卷得佳句。","时见文章士，欣然澹情素。","伏枕闻别离，畴能忍漂寓。","良会苦短促，溪行水奔注。","熊罴咆空林，游子慎驰骛。","西谒巴中侯，艰险如跬步。","主人不世才，先帝常特顾。","拔为天军佐，崇大王法度。","淮海生清风，南翁尚思慕。","公宫造广厦，木石乃无数。","初闻伐松柏，犹卧天一柱。","我瘦书不成，成字读亦误。","为我问故人，劳心练征戍。"],"theme":"送别","theme2":[],"style":"冲淡","style2":["幽峭","豪放"],"mood":"恬淡","mood2":["欢愉"],"scene":["江"],"cats":{"抒情":["友情","离别"],"山水":["长江"]},"theme_conf":0.486},{"uid":"efb8e0c4-59ad-4806-9df7-31ce2b642c11","title":"南家桃","author":"元稹","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["南家桃树深红色，日照露光看不得。","树小花狂风易吹，一夜风吹满墙北。","离人自有经时别，眼前落花心叹息。","更待明年花满枝，一年迢递空相忆。"],"theme":"送别","theme2":["羁旅思乡","爱情相思"],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":["夜","花"],"cats":{"抒情":["离别","思念","思乡"],"天气":["写风"],"植物":["桃花"]},"theme_conf":0.374},{"uid":"66652d2e-dd84-451f-a266-0250675171d1","title":"与诸客携酒寻去年梅花有感","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["马上同携今日杯，湖边共觅去春梅。","年年只是人空老，处处何曾花不开。","诗思又牵吟咏发，酒酣闲唤管弦来。","樽前百事皆依旧，点检惟无薛秀才。"],"theme":"羁旅思乡","theme2":["闲适隐逸"],"style":"豪放","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["酒"],"cats":{"抒情":["思乡"],"植物":["梅花"],"食物":["写酒"]},"theme_conf":0.522},{"uid":"70adc79e-eace-4cd8-a20e-1e8b609ab8eb","title":"杂曲歌辞 少年行","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["少年从出猎长杨，禁中新拜羽林郎。","独到辇前射双虎，君王手赐黄金铛。","日日鬬鸡都市里，赢得宝刀重刻字。","百里报讐夜出城，平明还在倡楼醉。","遥闻虏到平陵下，不待诏书行上马。","斩得名王献桂宫，封侯起第一日中。","不为六郡良家子，百战始取边城功。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["夜","楼"],"cats":{"抒情":["思乡","孤独"],"人生":["青春","战争"]},"theme_conf":0.613},{"uid":"889929d5-2846-4b0b-a3ad-1572ec48dfa4","title":"仲夏江阴官舍寄裴明府","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["万室边江次，孤城对海安。","朝霞晴作雨，湿气晚生寒。","苔色侵衣桁，潮痕上井栏。","题诗招茂宰，思尔欲辞官。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["江","夏"],"cats":{"抒情":["孤独"],"四季":["夏天"],"山水":["江河"]},"theme_conf":0.97},{"uid":"545ae0c5-171e-4e69-9c4c-b9a4300f6f95","title":"九日","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["惆怅重阳日，空山野菊新。","蒹葭百战地，江海十年人。","叹老堪衰柳，伤秋对白苹。","孤楼闻夕磬，塘路向城𬮱。"],"theme":"节令风俗","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["惆怅"],"scene":["重阳"],"cats":{"抒情":["孤独"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.9},{"uid":"0a6798a1-eae0-48d8-9a2a-7dde2eae81fc","title":"琴曲歌辞 别鹤","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["海鹤一为别，高程方杳然。","影摇江海路，思结潇湘天。","皎然仰白日，真姿栖紫烟。","含情九霄际，顾侣五云前。","遐心属清都，凄响激朱弦。","超摇间云雨，迢遰各山川。","东南信多水，会合当有年。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["鸟"],"cats":{"抒情":["离别"],"动物":["写鸟"]},"theme_conf":0.782},{"uid":"776db07f-66d2-4776-bd49-70f44b8aa67f","title":"奉和太常王卿酬中书李舍人中书寓直春夜对月见寄","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["露如轻雨月如霜，不见星河见鴈行。","虚晕入池波自泛，满轮当苑桂多香。","春台几望黄龙阙，云路宁分白玉郎。","是夜巴歌应金石，岂殊萤影对清光。"],"theme":"寄赠酬答","theme2":["应制干谒"],"style":"绮丽","style2":["婉约","清新"],"mood":"相思","mood2":[],"scene":["月","春","夜"],"cats":{"抒情":["思念"],"四季":["春天"],"天气":["月亮","星星"]},"theme_conf":0.98},{"uid":"dfaaaf11-9ead-4921-a71e-1f60be94af03","title":"得柳员外书封寄近诗书中兼报新主行营兵马因代书戏答","author":"独孤及","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["郎官作掾心非好，儒服临戎政已闻。","说劒尝宗漆园吏，戒严应笑棘门军。","遥知抵掌论皇道，时复吟诗向白云。","百越待君言即叙，相思不敢怆离群。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["园林","江南"],"cats":{"抒情":["思念"],"人生":["读书","战争"],"动物":["写马"],"植物":["柳树"]},"theme_conf":0.95},{"uid":"995153fc-153b-4165-8a84-3cbad12232ef","title":"南海使院对菊怀丁卯别墅","author":"许浑","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["何处曾移菊，溪桥鹤岭东。","篱疎还有艳，园小亦无丛。","日晚秋烟里，星繁晓露中。","影摇金涧水，香染玉潭风。","罢酒慙陶令，题诗答谢公。","朝来数花发，身在尉佗宫。"],"theme":"送别","theme2":["山水田园"],"style":"豪放","style2":["绮丽","清新"],"mood":"惆怅","mood2":[],"scene":["园林","重阳"],"cats":{"抒情":["离别"],"生活":["写桥"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.402},{"uid":"ef9b9e25-0e0d-4eca-83c6-43d1b4fa241f","title":"赠渔父","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["芦花深泽静垂纶，月夕烟朝几十春。","自说孤舟寒水畔，不曾逢著独醒人。"],"theme":"闲适隐逸","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["中秋","春","舟","月"],"cats":{"抒情":["孤独"],"四季":["春天"],"人物":["父亲"],"节日":["中秋节"]},"theme_conf":0.86},{"uid":"cp870e408ebfdc4b","title":"谢金莲诗酒红梨花・寄生草","author":"张寿卿","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["我这里从头说，你那里试听咱。","有吴融八韵赋自古无人压，有杜甫五言诗盖吐人惊讶，有李白一封书吓的那南蛮怕。","你只说秀才无路上云霄，却不道文官把笔平天下。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["酒","花"],"cats":{"抒情":["孤独","感恩"],"植物":["梨花","荷花"],"食物":["写酒"]},"theme_conf":1.0},{"uid":"c501f17a-230a-49b5-833c-5889a4e9bc85","title":"自淇涉黄河途中作十三首 十一","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["我行倦风湍，辍棹将问津。","空传歌瓠子，感慨独愁人。","孟夏桑叶肥，秾阴夹长津。","蚕农有时节，田野无闲人。","临水狎渔樵，望山怀隐沦。","谁能去京洛，顦顇对风尘。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["愁怨","恬淡"],"scene":["江","夏","舟","山"],"cats":{"抒情":["伤感","孤独"],"四季":["夏天"],"山水":["黄河"]},"theme_conf":0.603},{"uid":"8dfd661e-00e1-4cef-b3bc-923559cf6c66","title":"汴河览古","author":"徐凝","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["炀帝龙舟向此行，三千宫女采桡轻。","渡河不似如今唱，为是杨家怨思声。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["端午","舟"],"cats":{"抒情":["闺怨"],"山水":["江河"],"节日":["端午节"]},"theme_conf":1.0},{"uid":"9a5070c8-8b6a-46d3-a976-ce942baf42e7","title":"玉台体十二首 十一","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["昨夜裙带解，今朝蟢子飞。","铅华不可弃，莫是藁砧归。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["楼","夜"],"cats":{"抒情":["闺怨"]},"theme_conf":1.0},{"uid":"258e8498-75f6-4ec4-968f-9043297c7e68","title":"送著公归越","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["谁能愁此别，到越会相逢。","长忆云门寺，门前千万峰。","石床埋积雪，山路倒枯松。","莫学白居士，无人知去踪。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["孤寂","相思"],"scene":["江南","山"],"cats":{"抒情":["思念","伤感","孤独"],"天气":["写雪"]},"theme_conf":0.644},{"uid":"4bd8ab64-ee6d-4ba5-938c-85650dace115","title":"献襄阳于大夫","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["襄阳青山郭，汉江白铜堤。","谢公领兹郡，山水无尘泥。","铁马万霜雪，绛旗千虹霓。","风漪参差泛，石板重叠跻。","旧泪不复堕，新欢居然齐。","还畊竟原野，归老相扶携。","物色增暧暧，寒芳更萋萋。","渊清有遐略，高躅无近蹊。","即此富苍翠，自然引翔栖。","曩游常抱忆，夙好今尚暌。","愿言从逸辔，暇日凌清溪。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"沉郁","style2":["清新"],"mood":"欢愉","mood2":["愁怨"],"scene":["雪","山"],"cats":{"抒情":["伤感"],"天气":["彩虹"]},"theme_conf":0.479},{"uid":"424be0b8-1f41-4659-9e87-3e9bcbb7cab9","title":"过司空曙村居","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["南北与山邻，蓬庵庇一身。","繁霜疑有雪，枯草似无人。","遂性在耕稼，所交唯贱贫。","何言张掾傲，每重德璋亲。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["雪","山"],"cats":{"抒情":["孤独"],"生活":["乡村"]},"theme_conf":0.662},{"uid":"bfb6764d-41ce-4929-946c-2bce0573be04","title":"和韦承庆过义阳公主山池五首 四","author":"杜审言","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["攒石当轩倚，悬泉度牖飞。","鹿麛冲妓席，鹤子曳童衣。","园果尝难遍，池莲摘未稀。","卷帘唯待月，应在醉中归。"],"theme":"山水田园","theme2":["咏史怀古"],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["园林"],"cats":{"抒情":["怀古"],"山水":["瀑布"]},"theme_conf":0.544},{"uid":"99fc9acc-fbe7-4ecf-a3f3-5b9426ed68eb","title":"舞曲歌辞 屈柘词","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["杨柳萦桥绿，玫瑰拂地红。","绣衫金騕褭，花髻玉珑璁。","宿雨香潜润，春流水暗通。","画楼初梦断，晴日照湘风。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["清新"],"mood":"愁怨","mood2":[],"scene":["花","春","雨","楼"],"cats":{"抒情":["闺怨"],"四季":["春天"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"0d876872-31d8-49d7-a9cf-efbf71e5827b","title":"横吹曲辞 紫骝马","author":"李益","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["争场看鬬鸡，白鼻紫䯄嘶。","漳水春归晚，丛台日向低。","歇鞍珠作汗，试劒玉如泥。","为谢红梁燕，年年妾独栖。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独","闺怨"],"四季":["春天"],"动物":["写马"]},"theme_conf":1.0},{"uid":"8b41afb4-d737-43e1-9f79-1a8101eaa87e","title":"相和歌辞 从军行","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔从李都尉，双鞬照马蹄。","擒生黑山北，杀敌黄云西。","太白沈虏地，边草复萋萋。","归来邯郸市，百尺青楼梯。","感激然诺重，平生胆力齐。","芳筵暮歌发，艳粉轻鬟低。","半醉秋风起，铁骑门前嘶。","远戍报烽火，孤城严鼓鼙。","挥鞭望尘去，少妇莫含啼。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","楼"],"cats":{"抒情":["孤独"],"四季":["秋天"],"人生":["战争"]},"theme_conf":0.858},{"uid":"269e39c7-8e54-43de-bad4-86909285f911","title":"寄献北都留守裴令公","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["天上中台正，人间一品高。","休明值尧舜，勋业过萧曹。","始擅文三捷，终兼武六韬。","动人名赫赫，忧国意忉忉。","荡蔡擒封豕，平齐斩巨鼇。","两河收土宇，四海定波涛。","宠重移宫籥，恩新换阃旄。","保厘东宅静，守护北门牢。","晋国封疆阔，幷州士马豪。","胡兵惊赤帜，边雁避乌号。","令下流如水，仁沾泽似膏。","路喧歌五袴，军醉感单醪。","将校森貔武，宾僚俨隽髦。","客无烦夜柝，吏不犯秋毫。","神在台骀助，魂亡猃狁逃。","德星销彗孛，霖雨灭腥臊。","烽戍高临代，关河远控洮。","汾云晴漠漠，朔吹冷𩙫𩙫。","豹尾交牙戟，蚪须捧佩刀。","通天白犀带，照地紫麟袍。","羌管吹杨柳，燕姬酌蒲萄。","银含凿落醆，金屑琵琶槽。","遥想从军乐，应忘报国劳。","紫微留北阙，绿野寄东臯。","忽忆前时会，多慙下客叨。","清宵陪䜩话，美景从游遨。","花月还同赏，琴诗雅自操。","朱弦拂宫征，洪笔振风骚。","近竹开方丈，依林架桔槔。","春池八九曲，画舫两三艘。","径滑苔黏屐，潭深水没篙。","绿丝萦岸柳，红粉映楼桃。","为穆先陈醴，招刘共藉糟。","舞鬟金翡翠，歌颈玉蛴螬。","盛德终难过，明时岂易遭。","公虽慕张范，帝未舍伊臯。","眷恋心方结，踟蹰首已搔。","鸾皇上寥廓，燕雀任蓬蒿。","欲献文狂简，徒烦思郁陶。","可怜四百字，轻重抵鸿毛。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":["清新","豪放"],"mood":"欢愉","mood2":["相思","慷慨"],"scene":["雨","酒","夜","鸟","楼"],"cats":{"抒情":["思念","爱国"],"山水":["黄河"]},"theme_conf":0.451},{"uid":"8073152d-7f39-430b-93d2-24a9f7fc5323","title":"冬到金华山观因得故拾遗陈公学堂遗迹","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["涪右众山内，金华紫崔嵬。","上有蔚蓝天，垂光抱琼台。","系舟接绝壁，杖策穷萦回。","四顾俯层巅，澹然川谷开。","雪岭日色死，霜鸿有余哀。","焚香玉女跪，雾里仙人来。","陈公读书堂，石柱仄青苔。","悲风为我起，激烈伤雄才。"],"theme":"山水田园","theme2":["悼亡挽歌","游仙梦幻"],"style":"绮丽","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["山","冬"],"cats":{"抒情":["伤感","悼亡"],"四季":["冬天"],"人生":["读书"]},"theme_conf":0.424},{"uid":"41e3f463-1460-4aed-a203-56402ea427ef","title":"戏招诸客","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["黄醅绿醑迎冬熟，绛帐红炉逐夜开。","谁道洛中多逸客，不将书唤不曾来。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["冬"],"cats":{"抒情":["思乡"],"四季":["冬天"],"人物":["老师"]},"theme_conf":1.0},{"uid":"b4636285-4584-486f-8b92-1192ac91983a","title":"谢刘相寄天柱茶","author":"薛能","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["两串春团敌夜光，名题天柱印维扬。","偷嫌曼倩桃无味，捣觉嫦娥药不香。","惜恐被分缘利市，尽应难觅为供堂。","麤官寄与真抛却，赖有诗情合得尝。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春","夜"],"cats":{"抒情":["感恩"],"四季":["春天"],"食物":["写茶"]},"theme_conf":0.82},{"uid":"733afc7b-e370-4724-b755-e9342c574d22","title":"咏怀古迹五首 四","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["蜀主窥吴幸三峡，崩年亦在永安宫。","翠华想像空山里，玉殿虚无野寺中。","古庙杉松巢水鹤，岁时伏腊走村翁。","武侯祠屋常邻近，一体君臣祭祀同。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["江南","山"],"cats":{"抒情":["怀古"]},"theme_conf":0.613},{"uid":"361e35b8-dcc9-42ea-99ad-f07e9ef14918","title":"放歌行","author":"邵谒","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["龟为秉灵亡，鱼为弄珠死。","心中自有贼，莫怨任公子。","屈原若不贤，焉得沈湘水。"],"theme":"羁旅思乡","theme2":[],"style":"豪放","style2":["旷达"],"mood":"愁怨","mood2":["悲怆"],"scene":["端午"],"cats":{"抒情":["思乡"],"节日":["端午节"]},"theme_conf":0.65},{"uid":"f1befe2e-2e4d-4220-aa06-5fae1d3a1a04","title":"送王绪剡中","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["不见关山去，何时到郯中。","已闻成竹木，更道长儿童。","篱落云常聚，村墟水自通。","朝朝忆玄度，非是对清风。"],"theme":"送别","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["塞外","山"],"cats":{"抒情":["思念"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.592},{"uid":"edc474d8-bb0f-469e-9367-328d9aefb568","title":"相和歌辞 江南曲","author":"宋之问","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["妾住越城南，离居不自堪。","采花惊曙鸟，摘叶𫗪春蚕。","嬾结茱萸带，愁安玳瑁簪。","侍臣消瘦尽，日暮碧江潭。"],"theme":"闺情宫怨","theme2":["送别","民生疾苦"],"style":"沉郁","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":["江南","江"],"cats":{"抒情":["伤感","闺怨"],"山水":["江河"],"节日":["重阳节"]},"theme_conf":0.474},{"uid":"0d699470-bc8e-49d9-85e5-b1987b01c2dd","title":"江汉","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["江汉思归客，乾坤一腐儒。","片云天共远，永夜月同孤。","落日心犹壮，秋风病欲疎。","古来存老马，不必取长途。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["慷慨"],"scene":["江"],"cats":{"抒情":["思乡","孤独"],"山水":["江河","长江"]},"theme_conf":1.0},{"uid":"8341c4f7-04b1-4c38-b0aa-2103807662cf","title":"汴河亭","author":"许浑","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["广陵花盛帝东游，先劈昆仑一派流。","百二禁兵辞象阙，三千宫女下龙舟。","凝云鼓震星辰动，拂浪旗开日月浮。","四海义师归有道，迷楼还似景阳楼。"],"theme":"咏史怀古","theme2":[],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["楼","端午"],"cats":{"抒情":["怀古"],"节日":["端午节"]},"theme_conf":0.5},{"uid":"699800d5-6ce3-4f34-8f68-78b6c32f7202","title":"古瑟怨","author":"李益","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["破瑟悲秋已减弦，湘灵沈怨不知年。","感君拂拭遗音在，更奏新声明月天。"],"theme":"闺情宫怨","theme2":[],"style":"悲慨","style2":[],"mood":"愁怨","mood2":[],"scene":["月"],"cats":{"抒情":["伤感","闺怨","感恩"],"天气":["月亮"]},"theme_conf":1.0},{"uid":"0d2c5fba-d350-4c3f-b55e-72a491a84df6","title":"韩碑","author":"李商隐","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["元和天子神武姿，彼何人哉轩与羲。","誓将上雪列圣耻，坐法宫中朝四夷。","淮西有贼五十载，封狼生䝙䝙生罴。","不据山河据平地，长戈利矛日可麾。","帝得圣相相曰度，贼斫不死神扶持。","腰悬相印作都统，阴风惨澹天王旗。","愬武古通作牙爪，仪曹外郎载笔随。","行军司马智且勇，十四万众犹虎貔。","入蔡缚贼献太庙，功无与让恩不訾。","帝曰汝度功第一，汝从事愈宜为辞。","愈拜稽首蹈且舞，金石刻画臣能为。","古者世称大手笔，此事不系于职司。","当仁自古有不让，言讫屡颔天子颐。","公退斋戒坐小阁，濡染大笔何淋漓。","点窜尧典舜典字，涂改清庙生民诗。","文成破体书在纸，清晨再拜铺丹墀。","表曰臣愈昧死上，咏神圣功书之碑。","碑高三丈字如斗，负以灵鼇蟠以螭。","句奇语重喻者少，谗之天子言其私。","长绳百尺拽碑倒，麤砂大石相磨治。","公之斯文若元气，先时已入人肝脾。","汤盘孔鼎有述作，今无其器存其辞。","呜呼圣皇及圣相，相与烜赫流淳熙。","公之斯文不示后，曷与三五相攀追。","愿书万本诵万过，口角流沫右手胝。","传之七十有二代，以为封禅玉检明堂基。"],"theme":"咏史怀古","theme2":["边塞征战"],"style":"幽峭","style2":["绮丽"],"mood":"慷慨","mood2":["悲怆"],"scene":["楼","雪"],"cats":{"抒情":["怀古"]},"theme_conf":0.593},{"uid":"791da1d7-ca84-47fa-aa2a-fda1635a2f79","title":"游义兴寺寄上李逢吉相公","author":"令狐楚","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["柳营无事诣莲宫，步步犹疑是梦中。","劳役徒为万夫长，闲游曾与二人同。","凤鸾飞去仙巢在，龙象潜来讲席空。","松下花飞频伫立，一心千里忆梁公。"],"theme":"寄赠酬答","theme2":["哲理悟道","应制干谒"],"style":"婉约","style2":[],"mood":"相思","mood2":["欢愉","恬淡"],"scene":[],"cats":{"抒情":["思念"],"人物":["老师"]},"theme_conf":0.88},{"uid":"0422e408-0484-40d0-b826-da8e2c947490","title":"猛虎行","author":"李贺","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["长戈莫舂，长弩莫抨。","乳孙哺子，教得生狞。","举头为城，掉尾为旌。","东海黄公，愁见夜行。","道逢驺虞，牛哀不平。","何用尺刀，壁上雷鸣。","泰山之下，妇人哭声。","官家有程，吏不敢听。"],"theme":"边塞征战","theme2":["悼亡挽歌","羁旅思乡"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["山"],"cats":{"抒情":["思乡","伤感","悼亡"],"山水":["泰山"]},"theme_conf":0.408},{"uid":"ecd3d20d-3811-4313-9588-dfedb060eef4","title":"法镜寺","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["身危适他州，勉强终劳苦。","神伤山行深，愁破崖寺古。","婵娟碧鲜净，萧摵寒箨聚。","回回山根水，冉冉松上雨。","泄云蒙清晨，初日翳复吐。","朱甍半光炯，户牖粲可数。","拄策忘前期，出萝已亭午。","冥冥子规叫，微径不复取。"],"theme":"哲理悟道","theme2":[],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["中秋","山","雨"],"cats":{"抒情":["伤感"],"节日":["中秋节"]},"theme_conf":0.666},{"uid":"793368a9-a932-42cc-bf9c-e959f80b45eb","title":"京口怀古","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["大江横万里，古渡渺千秋。","浩浩波声险，苍苍天色愁。","三方归汉鼎，一水限吴州。","霸国今何在，清泉长自流。"],"theme":"咏史怀古","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","江","江南"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"山水":["长江"]},"theme_conf":0.693},{"uid":"cp87b3bcef15e86b","title":"长亭怨慢","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["渐吹尽、枝头香絮。","是处人家，绿深门户。","远浦萦回，暮帆零乱向何许。","阅人多矣，谁得似、长亭树。","树若有情时，不会得、青青如此。","日暮。","望高城不见，只见乱山无数。","韦郎去也，怎忘得、玉环分付。","第一是、早早归来，怕红萼、无人为主。","算空有并刀，难翦离愁千缕。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["绮丽","冲淡"],"mood":"愁怨","mood2":["孤寂"],"scene":["楼","花"],"cats":{"抒情":["离别","伤感","孤独"]},"theme_conf":1.0},{"uid":"18e0b8cc-e35e-44c2-9756-c08d1bd2a2f6","title":"下第题长安客舍","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["不遂青云望，愁看黄鸟飞。","棃花度寒食，客子未春衣。","世事随时变，交情与我违。","空余主人柳，相见却依依。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["恬淡","惆怅"],"scene":["清明","春"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.507},{"uid":"cp749e871e4d03de","title":"淡黄柳","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["空城晓月。","吹入垂杨陌。","马上单衣寒恻恻。","看尽鹅黄嫩绿，都是江南旧相识。","正岑寂。","明朝又寒食。","强携酒、小桥宅，怕梨花落尽成秋色。","燕燕飞来，问春何在，唯有池塘自碧。"],"theme":"羁旅思乡","theme2":[],"style":"冲淡","style2":["清新"],"mood":"孤寂","mood2":["恬淡"],"scene":["清明","江南","酒","秋","春","月"],"cats":{"抒情":["思乡"],"四季":["春天","秋天"],"生活":["写桥"],"节日":["寒食节","清明节"],"植物":["柳树"]},"theme_conf":0.86},{"uid":"54b45313-84ba-446a-9cbe-f58304b1c29b","title":"相和歌辞 江南弄","author":"王勃","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["江南弄，巫山连楚梦，行雨行云几相送。","瑶轩金谷上春时，玉童仙女无见期。","紫露香烟眇难托，清风明月遥相思。","遥相思，草徒绿，为听双飞凤凰曲。"],"theme":"山水田园","theme2":["爱情相思","送别"],"style":"清新","style2":["绮丽"],"mood":"相思","mood2":[],"scene":["江南","江"],"cats":{"抒情":["爱情","思念"],"山水":["江河"],"天气":["月亮"]},"theme_conf":0.357},{"uid":"66ebcb4d-63b0-485b-8ba3-bb6f6963454c","title":"塞上曲二首 二","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["汉家旌帜满阴山，不遣胡儿匹马还。","愿得此身长报国，何须生入玉门关。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外"],"cats":{"抒情":["爱国"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"cp1eb7d5610773cc","title":"水龙吟","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["楚天千里清秋，水随天去秋无际。","遥岑远目，献愁供恨，玉簪螺髻。","落日楼头，断鸿声里，江南游子。","把吴钩看了，栏干拍遍，无人会、登临意。","休说鲈鱼堪。","尽西风、季鹰归未。","求田问舍，怕应羞见，刘郎才气。","可惜流年，忧愁风雨，树犹如此。","倩何人，唤取盈盈翠袖，英雄泪。"],"theme":"闺情宫怨","theme2":["亲情"],"style":"婉约","style2":["沉郁","豪放"],"mood":"愁怨","mood2":[],"scene":["江南","秋","雨"],"cats":{"抒情":["伤感","闺怨"],"四季":["秋天"],"人生":["时光"]},"theme_conf":0.588},{"uid":"f5003828-ec14-49f6-a2b4-9eb6ce67a9d8","title":"遣怀","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔我游宋中，惟梁孝王都。","名今陈留亚，剧则贝魏俱。","邑中九万家，高栋照通衢。","舟车半天下，主客多欢娱。","白刃讐不义，黄金倾有无。","杀人红尘里，报答在斯须。","忆与高李辈，论交入酒垆。","两公壮藻思，得我色敷腴。","气酣登吹台，怀古视平芜。","芒砀云一去，雁鹜空相呼。","先帝正好武，寰海未凋枯。","猛将收西域，长戟破林胡。","百万攻一城，献捷不云输。","组练弃如泥，尺土负百夫。","拓境功未已，元和辞大炉。","乱离朋友尽，合沓岁月徂。","吾衰将焉托，存殁再呜呼。","萧条益堪媿，独在天一隅。","乘黄已去矣，凡马徒区区。","不复见颜鲍，系舟卧荆巫。","临餐吐更食，常恐违抚孤。"],"theme":"咏怀抒感","theme2":["羁旅思乡","咏史怀古","边塞征战"],"style":"豪放","style2":[],"mood":"孤寂","mood2":["慷慨"],"scene":["舟","酒"],"cats":{"抒情":["思乡","孤独","怀古","感恩"]},"theme_conf":0.95},{"uid":"5f5d6ee5-b0eb-4fe8-b26f-26f4bd9fe093","title":"杂曲歌辞 渭城少年行","author":"崔颢","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["洛阳二月梨花飞，秦地行人春忆归。","扬鞭走马城南陌，朝逢驿使秦川客。","驿使前日发章台，传道长安春早来。","棠梨宫中燕初至，葡萄馆里花正开。","念此使人归更早，三月便达长安道。","长安道上春可怜，摇风荡日曲河边。","万户楼台临渭水，五陵花柳满秦川。","秦川寒食盛繁华，游子春来喜见花。","鬬鸡下杜尘初合，走马章台日半斜。","章台帝城称贵里，青楼日晚歌钟起。","贵里豪家白马骄，五陵年少不相饶。","双双挟弹来金市，两两鸣鞭上渭桥。","渭城桥头酒新熟，金鞍白马谁家宿。","可怜锦瑟筝琵琶，玉台清酒就君家。","小妇春来不解羞，娇歌一曲杨柳花。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":["清新"],"mood":"相思","mood2":["欢愉"],"scene":["楼","清明","春","酒"],"cats":{"抒情":["思念","思乡"],"四季":["春天"],"人生":["青春"],"生活":["写桥"],"节日":["寒食节","清明节"]},"theme_conf":0.579},{"uid":"1b942cdf-a8ec-4bf9-8c1e-bba47e0c4726","title":"暮秋枉裴道州手札率尔遣兴寄近呈苏涣侍御","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["久客多枉友朋书，素书一月凡一束。","虚名但蒙寒温问，泛爱不救沟壑辱。","齿落未是无心人，舌存耻作穷途哭。","道州手札适复至，纸长要自三过读。","盈把那须沧海珠，入怀本倚昆山玉。","拨弃潭州百斛酒，芜没潇岸千株菊。","使我昼立烦儿孙，令我夜坐费灯烛。","忆子初尉永嘉去，红颜白面花映肉。","军符侯印取岂迟，紫燕𫘧耳行甚速。","圣朝尚飞战鬬尘，济世宜引英俊人。","黎元愁痛会苏息，夷狄跋扈徒逡巡。","授钺筑坛闻意旨，颓纲漏网期弥纶。","郭钦上书见大计，刘毅答诏惊群臣。","他日更仆语不浅，明公论兵气益振。","倾壶箫管黑白发，儛劒霜雪吹青春。","宴筵曾语苏季子，后来杰出云孙比。","茅斋定王城郭门，药物楚老渔商市。","市北肩舆每联袂，郭南抱瓮亦隐几。","无数将军西第成，早作丞相东山起。","鸟雀苦肥秋粟菽，蛟龙欲蛰寒沙水。","天下鼓角何时休，阵前部曲终日死。","附书与裴因示苏，此生已媿须人扶。","致君尧舜付公等，早据要路思捐躯。"],"theme":"边塞征战","theme2":["送别","民生疾苦"],"style":"沉郁","style2":["绮丽"],"mood":"悲怆","mood2":["愁怨","慷慨"],"scene":["秋","夜"],"cats":{"抒情":["伤感","爱国"],"四季":["秋天"],"人生":["青春","战争"]},"theme_conf":0.356},{"uid":"ca632d53-d4c4-41c3-a8e7-82f9c48cfd29","title":"初入谏司喜家室至","author":"窦群","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["一旦悲欢见孟光，十年辛苦伴沧浪。","不知笔砚缘封事，犹问佣书日几行。"],"theme":"羁旅思乡","theme2":[],"style":"悲慨","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"人生":["读书"]},"theme_conf":0.65},{"uid":"dc988aaa-b1e6-4a0f-b0e5-798d42652c8c","title":"杂曲歌辞 茱萸女","author":"万楚","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["山阴柳家女，九日采茱萸。","复得东邻伴，双为陌上姝。","插花向高髻，结子置长裾。","作性恒迟缓，非关诧丈夫。","平明折林树，日入反城隅。","侠客邀罗袖，行人挑短书。","蛾眉自有主，年少莫踟蹰。"],"theme":"羁旅思乡","theme2":["闺情宫怨"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["重阳"],"cats":{"抒情":["思乡","闺怨"],"节日":["重阳节"]},"theme_conf":0.529},{"uid":"bddf2874-e96b-43b9-85d9-e4d7d89d25b9","title":"大堤曲","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["二八婵娟大堤女，开垆相对依江渚。","待客登楼向水看，邀郎卷幔临花语。","细雨蒙蒙湿芰荷，巴东商侣挂帆多。","自传芳酒涴红袖，谁调妍妆回翠娥。","珍簟华灯夕阳后，当垆理瑟矜纤手。","月落星微五鼓声，春风摇荡牕前柳。","岁岁逢迎沙岸间，北人多识绿云鬟。","无端嫁与五陵少，离别烟波伤玉颜。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["豪放","婉约"],"mood":"惆怅","mood2":[],"scene":["江","雨","花"],"cats":{"抒情":["离别"],"天气":["写雨","月亮"],"节日":["中秋节"]},"theme_conf":0.667},{"uid":"c3702d36-4293-4d70-a4e9-3b752445769f","title":"杂曲歌辞 少年行三首 二","author":"僧贯休","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["自拳五色毬，迸入他人宅。","却捉苍头奴，玉鞭打一百。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"人生":["青春"]},"theme_conf":0.65},{"uid":"906627d5-30e9-4ed3-adeb-3de852f9be50","title":"幽居有白菊一丛因而成咏呈知己","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["还是延年一种材，即将瑶朵冒霜开。","不如红艳临歌扇，欲伴黄英入酒杯。","陶令接䍠堪岸著，梁王高屋好欹来。","月中若有闲田地，为劝嫦娥作意裁。"],"theme":"咏物","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["酒","重阳"],"cats":{"抒情":["友情"],"天气":["月亮"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.96},{"uid":"cp6dc364d590f073","title":"猫儿坠・绿荷萧索无可盖眠鸥，碧粼粼露远洲。羁人无力冷飕飕，合愁，","author":"高明","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["早知道宋玉当时顿觉伤秋。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["江","夏","秋"],"cats":{"抒情":["思乡","伤感"],"四季":["夏天","秋天"],"动物":["写鸟","写猫"],"植物":["荷花"]},"theme_conf":0.517},{"uid":"c48a91ea-6d94-42d1-8466-f5a9f42cc1d6","title":"送兵到蓟北","author":"高适","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["积雪与天迥，屯军连塞愁。","谁知此行迈，不为觅封侯。"],"theme":"送别","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["塞外","雪"],"cats":{"抒情":["伤感"],"天气":["写雪"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.529},{"uid":"9ea879f4-9781-469a-8b52-fc5777e633c2","title":"茅屋为秋风所破歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["八月秋高风怒号，卷我屋上三重茅。","茅飞度江洒江郊，高者挂罥长林梢。","下者飘转沈塘坳，南邨群童欺我老无力。","忍能对面为盗贼，公然抱茅入竹去。","唇焦口燥呼不得，归来倚仗自叹息。","俄顷风定云墨色，秋天漠漠向昏黑。","布衾多年冷似铁，骄儿恶卧踏里裂。","床床屋漏无干处，雨脚如麻未断绝。","自经丧乱少睡眠，长夜沾湿何由彻。","安得广厦千万间，大庇天下寒士俱欢颜。","风雨不动安如山，呜呼！何时眼前突兀见此屋？","吾庐独破受冻死亦足。"],"theme":"山水田园","theme2":["民生疾苦"],"style":"悲慨","style2":["幽峭"],"mood":"孤寂","mood2":["慷慨","欢愉"],"scene":["秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"天气":["写风"]},"theme_conf":0.568},{"uid":"32744451-b4f4-47d1-866c-44b2675377c3","title":"横吹曲辞 折杨柳","author":"翁绶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["紫陌金堤映绮罗，游人处处动离歌。","阴移古戍迷荒草，花带残阳落远波。","台上少年吹白雪，楼中思妇敛青蛾。","殷勤攀折赠行客，此去关山雨雪多。"],"theme":"送别","theme2":["羁旅思乡","边塞征战"],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["楼","雪","雨","塞外"],"cats":{"抒情":["思乡"],"植物":["柳树"]},"theme_conf":0.4},{"uid":"c4912092-34c2-42fe-a9ff-b924b0dddf7f","title":"相和歌辞 春江花月夜","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["玉树歌阑海云黑，花庭忽作青芜国。","秦淮有水水无情，还向金陵漾春色。","杨家二世安九重，不御华芝嫌六龙。","百幅锦帆风力满，连天展尽金芙蓉。","珠翠丁星复明灭，龙头劈浪哀笳发。","千里涵空照水魂，万枝破鼻团香雪。","漏转霞高沧海西，颇黎枕上闻天鸡。","蛮弦代雁曲如语，一醉昏昏天下迷。","四方倾动烟尘起，犹在浓香梦魂里。","后主荒宫有晓莺，飞来只隔西江水。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["悲怆"],"scene":["江","春"],"cats":{"抒情":["怀古"],"四季":["春天"],"山水":["江河"],"天气":["月亮"]},"theme_conf":1.0},{"uid":"0532d507-dd36-4bb4-868a-fe771d68c11e","title":"华清宫三十韵","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["绣岭明珠殿，层峦下缭墙。","仰窥丹槛影，犹想赭袍光。","昔帝登封后，中原自古强。","一千年际会，三万里农桑。","几席延尧舜，轩墀接禹汤。","雷霆驰号令，星斗焕文章。","钓筑乘时用，芝兰在处芳。","北扉闲木索，南面富循良。","至道思玄圃，平居厌未央。","钩陈裹岩谷，文陛压青苍。","歌吹千秋节，楼台八月凉。","神仙高缥缈，环珮碎丁当。","泉暖涵窓镜，云娇惹粉囊。","嫩岚滋翠葆，清渭照红粧。","帖泰生灵寿，懽娱岁序长。","月闻仙曲调，霓作舞衣裳。","雨露偏金穴，乾坤入醉乡。","玩兵师汉武，回手倒干将。","黥鬣掀东海，胡牙揭上阳。","喧呼马嵬血，零落羽林枪。","倾国留无路，还魂怨有香。","蜀峰横惨澹，秦树远微茫。","鼎重山难转，天扶业更昌。","望贤余故老，花萼旧池塘。","往事人谁问，幽襟泪独伤。","碧簷斜送日，殷叶半凋霜。","迸水倾瑶砌，疎风罅玉房。","尘埃羯鼓索，片段荔枝筐。","鸟啄摧寒木，蜗涎蠹画梁。","孤烟知客恨，遥起泰陵傍。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"绮丽","style2":["沉郁","豪放"],"mood":"愁怨","mood2":["孤寂","恬淡"],"scene":["山","花","园林","楼"],"cats":{"抒情":["伤感","孤独","怀古"],"四季":["秋天"],"人生":["战争"],"食物":["荔枝"]},"theme_conf":0.305},{"uid":"a07e44fe-2a73-40af-a53a-e735eb124928","title":"宿悬泉驿","author":"贾岛","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["晓行沥水楼，暮到悬泉驿。","林月值云遮，山灯照愁寂。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["楼","月","山"],"cats":{"抒情":["思乡","伤感"],"山水":["瀑布"]},"theme_conf":0.524},{"uid":"cp1ab8bda1f065cf","title":"采莲令","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["月华收，云淡霜天曙。","西征客、此时情苦。","翠娥执手送临歧，轧轧开朱户。","千娇面、盈盈伫立，无言有泪，断肠争忍回顾。","一叶兰舟，便恁急桨凌波去。","贪行色、岂知离绪。","万般方寸，但饮恨，脉脉同谁语。","更回首、重城不见，寒江天外，隐隐两三烟树。"],"theme":"送别","theme2":["爱情相思"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["舟","月"],"cats":{"抒情":["伤感"],"天气":["月亮"],"植物":["荷花"]},"theme_conf":0.622},{"uid":"ae472a2c-7977-4ed6-a893-7ef7c3136666","title":"柴门","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["孤舟登瀼西，回首望两崖。","东城干旱天，其气如焚柴。","长影没窈窕，余光散唅呀。","大江蟠嵌根，归海成一家。","下冲割坤轴，竦壁攒镆铘。","萧飒洒秋色，氛昏霾日车。","峡门自此始，最窄容浮查。","禹功翊造化，疎凿就攲斜。","巨渠决太古，众水为长蛇。","风烟渺吴蜀，舟楫通盐麻。","我今远游子，飘转混泥沙。","万物附本性，约身不愿奢。","茅栋盖一床，清池有余花。","浊醪与脱粟，在眼无咨嗟。","山荒人民少，地僻日夕佳。","贫病固其常，富贵任生涯。","老于干戈际，宅幸蓬荜遮。","石乱上云气，杉清延月华。","赏妍又分外，理惬夫何夸。","足了垂白年，敢居高士差。","书此豁平昔，回首犹暮霞。"],"theme":"山水田园","theme2":["羁旅思乡","闲适隐逸"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["舟","秋","酒"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"山水":["长江"],"天气":["月亮"],"生活":["乡村"]},"theme_conf":0.35},{"uid":"1fcf1381-8137-43b2-8863-bc92e00f50c8","title":"相和歌辞 决绝[词]三首 二","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["噫春冰之将泮，何余怀之独结。","有美一人，于焉旷绝。","一日不见，比一日于三年，况三年之旷别。","水得风兮小而已波，笋在苞兮高不见节。","矧桃李之当春，竞众人之攀折。","我自顾悠悠而若云，又安能保君皓皓之如雪。","感破镜之分明，覩泪痕之余血。","幸他人之既不我先，又安能使他人之终不我夺。","已焉哉！织女别黄姑，一年一度暂相见，彼此隔河何事无。"],"theme":"爱情相思","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["春","冬","七夕","雪"],"cats":{"抒情":["孤独"],"四季":["春天"],"节日":["七夕节"]},"theme_conf":0.84},{"uid":"e70522e6-cb7f-4624-94e7-96ce81db4c6c","title":"故吏部郎中赠给事中韦公挽歌二首 二","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["社里东城接，松阡北地开。","闻笳春色惨，执绋故人哀。","终日南山对，何时渭水回。","仁兄与恩旧，相望泣泉台。"],"theme":"悼亡挽歌","theme2":["送别"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["春","山"],"cats":{"抒情":["友情","悼亡"],"四季":["春天"]},"theme_conf":0.98},{"uid":"4bea25d5-1cef-483d-923d-bc9c50c7bbe5","title":"题孤山寺山石榴花示诸僧众","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["山榴花似结红巾，容艳新妍占断春。","色相故关行道地，香尘拟触坐禅人。","瞿昙弟子君知否，恐是天魔女化身。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"孤寂","mood2":[],"scene":["花","山"],"cats":{"抒情":["孤独"],"山水":["西湖"]},"theme_conf":0.76},{"uid":"cpd2765c5b36f5e9","title":"青玉案","author":"无名氏","dynasty":"宋","section":"宋词","form":"词","paragraphs":["年年社日停针线。","怎忍见、双飞燕。","今日江城春已半。","一身犹在，乱山深处，寂寞溪桥畔。","春衫著破谁针线。","点点行行泪痕满。","落日解鞍芳草岸。","花无人戴，酒无人劝，醉也无人管。"],"theme":"羁旅思乡","theme2":["山水田园","闲适隐逸"],"style":"婉约","style2":["绮丽","清新"],"mood":"孤寂","mood2":[],"scene":["酒","春","花"],"cats":{"抒情":["思乡","孤独"],"四季":["春天"],"生活":["写桥"]},"theme_conf":0.93},{"uid":"a9d1f98c-aa7c-47ab-8c78-22435044a3ac","title":"汴河怀古","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["锦缆龙舟隋炀帝，平台复道汉梁王。","游人闲起前朝念，折柳孤吟断杀肠。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["端午","舟"],"cats":{"抒情":["孤独","怀古"],"节日":["端午节"]},"theme_conf":0.724},{"uid":"b323c71f-ed8e-49cd-8baf-42089fa17706","title":"石州城","author":"武元衡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["丈夫心爱横行，报国知嫌命轻。","楼兰径百战，更道戍龙城。","锦字窦车骑，胡笳李少卿。","生离两不见，万古难为情。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["雄浑","幽峭"],"mood":"慷慨","mood2":[],"scene":["楼"],"cats":{"抒情":["爱国"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.828},{"uid":"f865e685-cc9b-4edc-b254-6326223ef92c","title":"伤大理谢少卿","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["旧馆绝逢迎，新诗何处呈。","空留封禅草，已作岱宗行。","柳蠹风吹析，堦崩雪遶平。","无因重来此，剩哭两三声。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["山","雪"],"cats":{"抒情":["伤感","悼亡","感恩"],"山水":["泰山"]},"theme_conf":0.96},{"uid":"e475a182-9775-4dcb-9087-4abb71fc6476","title":"杂曲歌辞 少年子","author":"李白","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["青云少年子，挟弹章台左。","鞍马四边开，突如流星过。","金丸落飞鸟，夜入琼楼卧。","夷齐是何人？独守西山饿。"],"theme":"民生疾苦","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["楼","夜"],"cats":{"抒情":["孤独"],"人生":["青春"]},"theme_conf":1.0},{"uid":"cp3bf43d6100f34f","title":"满江红","author":"岳飞","dynasty":"宋","section":"宋词","form":"词","paragraphs":["怒发冲冠，凭阑处、潇潇雨歇。","抬望眼、仰天长啸，壮怀激烈。","三十功名尘与土，八千里路云和月。","莫等闲、白了少年头，空悲切。","靖康耻，犹未雪。","臣子恨，何时灭。","驾长车踏破，贺兰山缺。","壮志饥餐胡虏肉，笑谈渴饮匈奴血。","待从头、收拾旧山河，朝天阙。"],"theme":"民生疾苦","theme2":["边塞征战"],"style":"豪放","style2":["沉郁","悲慨"],"mood":"慷慨","mood2":[],"scene":["雨","江","雪"],"cats":{"抒情":["爱国"],"山水":["江河"],"人生":["励志","梦想"]},"theme_conf":0.542},{"uid":"a9d85d1f-936c-489c-a074-9e2be10e5af6","title":"遣闷奉呈严公二十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["白水鱼竿客，清秋鹤发翁。","胡为来幕下，秪合在舟中。","黄卷真如律，青袍也自公。","老妻忧坐[痹]，幼女问头风。","平地专欹倒，分曹失异同。","礼甘衰力就，义忝上官通。","畴昔论诗蚤，光辉仗钺雄。","宽容存性拙，剪拂念途穷。","露裛思藤架，烟霏想桂丛。","信然龟触网，直作鸟窥笼。","西岭纡村北，南江遶舍东。","竹皮寒旧翠，椒实雨新红。","浪簸船应坼，杯干瓮即空。","藩篱生野径，斤斧任樵童。","束缚酬知己，蹉跎効小忠。","周防期稍稍，太简遂悤悤。","晓入朱扉启，昏归画角终。","不成寻别业，未敢息微躬。","乌鹊愁银汉，驽骀怕锦幪。","会希全物色，时放倚梧桐。"],"theme":"山水田园","theme2":["送别"],"style":"清新","style2":["绮丽","沉郁"],"mood":"愁怨","mood2":[],"scene":["鸟","舟","雨"],"cats":{"抒情":["友情","伤感"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.374},{"uid":"664ccc00-6def-413f-94ac-733c4ec9b6c1","title":"杂曲歌辞 君子有所思行 一","author":"僧贯休","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["我爱正考甫，思贤作商颂。","我爱扬子云，理乱皆如凤。","振衣中夜起，露花香旖旎。","扑碎骊龙明月珠，敲出凤凰五色髓。","陋卷萧萧风淅淅，缅想斯人胜珪璧。","寂寥千载不相逢，无限区区尽虚掷。","君不见沈约道，佳人不在兹，春光为谁惜。"],"theme":"咏史怀古","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["月","花"],"cats":{"抒情":["思念","怀古"],"天气":["月亮"],"人物":["女子"]},"theme_conf":0.86},{"uid":"7e75853a-bf7a-4d8d-b3e9-0537f4ed913a","title":"马嵬坡","author":"郑畋","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["[玄]宗回马杨妃死，云雨虽亡日月新。","终是圣明天子事，景阳宫井又何人。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["雨","月"],"cats":{"抒情":["怀古"],"动物":["写马"]},"theme_conf":1.0},{"uid":"cp910bd0baa4338d","title":"玉蝴蝶","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["望处雨收云断，凭阑悄悄，目送秋光。","晚景萧疏，堪动宋玉悲凉。","水风轻、苹花渐老，月露冷、梧叶飘黄。","遣情伤。","故人何在，烟水茫茫。","难忘。","文期酒会，几孤风月，屡变星霜。","海阔山遥，未知何处是潇湘。","念双燕、难凭远信，指暮天、空识归航。","黯相望。","断鸿声里，立尽斜阳。"],"theme":"送别","theme2":["哲理悟道"],"style":"绮丽","style2":["沉郁","冲淡"],"mood":"孤寂","mood2":["悲怆","相思"],"scene":["秋","月","酒"],"cats":{"抒情":["友情","伤感","孤独"],"四季":["秋天"]},"theme_conf":0.524},{"uid":"a1824eb8-4e2e-4d53-9a33-e1dcfe7d1c73","title":"经邹鲁祭孔子而叹之","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["夫子何为者？栖栖一代中。","地犹鄹氏邑，宅即鲁王宫。","叹凤嗟身否，伤麟怨道穷。","今看两楹奠，当与梦时同。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["伤感","怀古"]},"theme_conf":1.0},{"uid":"af84c796-64c8-4c7c-9e57-ef9340202749","title":"七夕","author":"张文恭","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["凤律惊秋气，龙梭静夜机。","星桥百枝动，云路七香飞。","映月回雕扇，凌霞曳绮衣。","含情向华幄，流态入重闱。","欢余夕漏尽，怨结晓骖归。","谁念分河汉，还忆两心违。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":["愁怨","欢愉"],"scene":["七夕"],"cats":{"抒情":["思念"],"生活":["写桥"],"节日":["七夕节"]},"theme_conf":0.95},{"uid":"40c8fa66-2802-43df-ada6-1bd286cb49db","title":"八哀诗 赠司空王公思礼","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["司空出东夷，童稚刷劲翮。","追随燕蓟儿，颖锐物不隔。","服事哥舒翰，意无流沙碛。","未甚拔行间，犬戎大充斥。","短小精悍姿，屹然强寇敌。","贯穿百万众，出入由咫尺。","马鞍悬将首，甲外控鸣镝。","洗劒青海水，刻铭天山石。","九曲非外蕃，其王转深壁。","飞兔不近驾，鸷鸟资远击。","晓达兵家流，饱闻春秋癖。","胷襟日沈静，肃肃自有适。","潼关初溃散，万乘犹辟易。","偏裨无所施，元帅见手格。","太子入朔方，至尊狩梁益。","胡马缠伊洛，中原气甚逆。","肃宗登宝位，塞望势敦迫。","公时徒步至，请罪将厚责。","际会清河公，间道传玉册天王拜跪毕，谠议果冰释。","翠华卷飞雪，熊虎亘阡陌。","屯兵凤皇山，帐殿泾渭辟。","金成贼咽喉诏镇雄所搤。","禁暴清无双，爽气春淅沥。","巷有从公歌，野多青青麦。","及夫哭庙后，复领太原役恐惧禄位高，怅望王土窄。","不得见清时，呜呼就窀穸。","永系五湖舟，悲甚田横客。","千秋汾晋间，事与云水白。","昔观文苑传，岂述廉蔺绩。","嗟嗟邓大夫，士卒终倒戟。"],"theme":"悼亡挽歌","theme2":["悼亡挽歌","送别"],"style":"冲淡","style2":["悲慨","清新"],"mood":"悲怆","mood2":[],"scene":["雪","鸟","冬"],"cats":{"抒情":["伤感","悼亡"],"山水":["黄河"],"天气":["写雪"]},"theme_conf":0.95},{"uid":"b4a96752-93b2-4088-bdb3-4c45a5584e78","title":"龊龊","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["龊龊当世士，所忧在饥寒。","但见贱者悲，不闻贵者叹。","大贤事业异，远抱非俗观。","报国心皎洁，念时涕汍澜。","妖姬坐左右，柔指发哀弹。","酒肴虽日陈，感激宁为欢。","秋阴欺白日，泥潦不少干。","河堤决东郡，老弱随惊湍。","天意固有属，谁能诘其端。","愿辱太守荐，得充谏诤官。","排云呌阊阖，披腹呈琅玕。","致君岂无术，自进诚独难。"],"theme":"民生疾苦","theme2":[],"style":"悲慨","style2":["豪放"],"mood":"悲怆","mood2":["孤寂","慷慨"],"scene":["酒","秋"],"cats":{"抒情":["伤感","孤独","爱国"],"四季":["秋天"]},"theme_conf":1.0},{"uid":"2dad9262-faad-45d2-a3d8-69c51f97ddad","title":"送萧颖士赴东府得散字","author":"殷少野","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["官闲幕府下，聊以任纵诞。","文学鲁仲尼，高标嵇中散。","出门时雨润，对酒春风暖。","感激知己恩，别离魂欲断。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["酒","春","雨"],"cats":{"抒情":["友情","离别"],"四季":["春天"]},"theme_conf":0.827},{"uid":"71613d6e-3c46-4916-91b1-2f2bdb65cc30","title":"题武关","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["碧溪留我武关东，一笑怀王迹自穷。","郑袖娇娆酣似醉，屈原憔悴去如蓬。","山墙谷堑依然在，弱吐强吞尽已空。","今日圣神家四海，戌旗长卷夕阳中。"],"theme":"咏史怀古","theme2":["咏史怀古","咏物","山水田园"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["端午","酒","山"],"cats":{"抒情":["怀古"],"节日":["端午节"]},"theme_conf":0.95},{"uid":"09d9d2b1-e2a0-499c-a673-bd9f9333a435","title":"酬栢侍御闻与韦处士同游灵台寺见寄","author":"王建","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["西域传中说，灵台属雍州。","有泉皆圣迹，有石皆佛头。","所出薝卜香，外国俗来求。","毒蛇护其下，樵者不可偷。","古碑在云巅，备载置寺由。","魏家移下来，后人始增修。","近与韦处士，爱此山之幽。","各自具所须，竹笼盛茶瓯。","牵马过危栈，襞衣涉奔流。","草开平路尽，林下大石稠。","过郭转经峰，忽见东西楼。","瀑布当寺门，逬落衣裳秋。","石苔铺紫花，溪叶裁碧油。","松根载殿高，飘飖仙山浮。","县中贤大夫，一月前此游。","赛神贺得雨，岂暇多停留。","二十韵新诗，远寄寻山俦。","清冷玉涧泣，冷切石磬愁。","君名高难闲，余身愚终休。","相将长无因，从今生离忧。"],"theme":"寄赠酬答","theme2":["送别"],"style":"幽峭","style2":[],"mood":"愁怨","mood2":[],"scene":["楼","山"],"cats":{"抒情":["伤感"],"山水":["瀑布"]},"theme_conf":0.85},{"uid":"27423bb8-fa3f-41e6-83a6-9c105c176d3d","title":"御沟新柳","author":"冯宿","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["夹道天渠远，垂丝御柳新。","千条宜向日，万户共迎春。","轻翠含烟发，微音逐吹频。","静看思渡口，回望忆江滨。","袅袅分游骑，依依驻旅人。","阳和如可及，攀折在兹辰。"],"theme":"羁旅思乡","theme2":["咏物"],"style":"清新","style2":["婉约","冲淡"],"mood":"相思","mood2":[],"scene":["春","江"],"cats":{"抒情":["思念","思乡"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.528},{"uid":"03f25790-0eb4-41e1-861e-fcf5e124ea89","title":"怀江上（句）（卢延逊五举方登第。〖2〗尝作诗云。「狐冲」二句，租庸张相濬每诵之。又「饿猫」二句，成中令汭激赏之。又「栗爆」二句，王中懿建爱之。卢尝谓人曰：「平生投谒公卿，不意得猫儿狗子之力也。」） 一","author":"卢延让","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["狐冲官道过，犬刺客门开（一作「狗判店门开」）。","〖3〗。"],"theme":"民生疾苦","theme2":["咏史怀古"],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["江"],"cats":{"抒情":["怀古"],"动物":["写猫"]},"theme_conf":0.546},{"uid":"021b47d2-ef8a-42ca-a7c6-8a8bbb39a98a","title":"简简吟","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["苏家小女名简简，芙蓉花顋柳叶眼。","十一把镜学点妆，十二抽针能绣裳。","十三行坐事调品，不肯迷头白地藏。","玲珑云髻生花样，飘飖风袖蔷薇香。","殊姿异态不可状，忽忽转动如有光。","二月繁霜杀桃李，明年欲嫁今年死。","丈人阿母勿悲啼，此女不是凡夫妻。","恐是天仙谪人世，只合人间十三岁。","大都好物不坚牢，彩云易散琉璃脆。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"悲怆","mood2":[],"scene":["花"],"cats":{"抒情":["伤感","闺怨"],"天气":["写云"],"人物":["母亲"]},"theme_conf":1.0},{"uid":"2264ebda-c26d-44d0-ade0-b4e4f611f5cf","title":"宫词一百首 九十四","author":"王建","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["画作天河刻作牛，玉梭金镊采桥头。","每年宫里穿针夜，𠡠赐诸亲乞巧楼。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["七夕","夜","楼"],"cats":{"抒情":["闺怨"],"生活":["写桥"],"节日":["七夕节"]},"theme_conf":0.732},{"uid":"4e409fd6-6f44-40e3-82b0-3c0fb1f146ef","title":"秋暮忆中秋夜与王璠侍御赏月因怆远离聊以奉寄","author":"鲍防","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["前月月明夜，美人同远光。","清尘一以间，今夕坐相忘。","风落芙蓉露，疑余绣被香。"],"theme":"寄赠酬答","theme2":["节令风俗"],"style":"冲淡","style2":["沉郁","清新"],"mood":"相思","mood2":["欢愉"],"scene":["中秋","月","夜","秋"],"cats":{"抒情":["离别","思念"],"四季":["秋天"],"天气":["月亮"],"人物":["女子"],"节日":["中秋节"]},"theme_conf":0.9},{"uid":"090b7792-2942-4f3c-a34d-caccd066c76f","title":"芙蓉楼送辛渐二首 一","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["寒雨连天夜入湖，平明送客楚山孤。","洛阳亲友如相问，一片冰心在玉壶。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["雨","楼"],"cats":{"抒情":["孤独"],"植物":["荷花"]},"theme_conf":0.807},{"uid":"dc5bb894-c908-405b-8280-571cdb08da82","title":"绝句","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["江边踏青罢，回首见旌旗。","风起春城暮，高楼鼓角悲。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["清明","春","楼","江"],"cats":{"抒情":["伤感"],"四季":["春天"],"节日":["清明节"]},"theme_conf":1.0},{"uid":"b0a1fb5f-9390-4ccb-b4e2-9bde13822508","title":"洛阳早春忆吉中孚校书司空曙主簿因寄清江上人","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["值迥逢高驻马频，雪晴闲看洛阳春。","莺声报远同芳信，柳色邀欢似故人。","酒貌昔将花共艳，鬓毛今与草争新。","年来百事皆无绪，唯与汤师结净因。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":["冲淡"],"mood":"相思","mood2":["孤寂","欢愉"],"scene":["春"],"cats":{"抒情":["友情","思念"],"四季":["春天"],"节日":["春节"]},"theme_conf":0.82},{"uid":"a50fdaca-5397-4000-8c2c-bfcb9ab8e681","title":"杂曲歌辞 从军中行路难二首 一","author":"骆宾王","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见封狐雄虺自成群，冯深负固结妖氛。","玉玺分兵征恶少，金坛受律动将军。","将军拥旄宣庙略，战士横行静夷落。","长驱一息背铜梁，直指三巴逾劒阁。","阁道岧嶤上戍楼，劒门遥裔俯灵丘。","邛关九折无平路，江水双源有急流。","征役无期返，他乡岁华晚。","杳杳丘陵出，苍苍林薄远。","途危紫盖峰，路涩青泥坂。","去去指哀牢，行行入不毛。","绝壁千里险，连山四望高。","中外分区宇，夷夏殊风土。","交趾枕南荒，昆弥临北户。","川源饶毒雾，溪谷多淫雨。","行潦四时流，崩查千岁古。","漂梗飞蓬不自安，扪藤引葛度危峦。","昔时闻道从军乐，今日方知行路难。","苍江绿水东流驶，炎洲丹徼南中地。","南中南斗映星河，秦川秦塞阻烟波。","三春边地风光少，五月泸中瘴疠多。","朝驱疲斥候，夕息倦谁何。","向月弯繁弱，连星转太阿。","重义轻生怀一顾，东伐西征凡几度。","夜夜朝朝斑鬓新，年年岁岁戎衣故。","灞城隅，滇池水，天涯望转积，地际行无已。","徒觉炎凉节物非，不知关山千万里。","弃置勿重陈，重陈多苦辛。","且悦清笳杨柳曲，讵忆芳园桃李人。","绛节朱旗分白羽，丹心白刃酬明主。","但令一技君王识，谁惮三边征战苦。","行路难，行路难，岐路几千端。","无复归云冯短翰，望日想长安。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":["清新","绮丽"],"mood":"相思","mood2":["恬淡"],"scene":["江","夏","塞外","楼","山","春"],"cats":{"抒情":["思念"],"四季":["春天","夏天"],"天气":["星星"],"人生":["战争"],"生活":["边塞"],"节日":["春节"]},"theme_conf":0.599},{"uid":"f2413b7a-cfda-4d88-8c24-6684aa4bcf8a","title":"七月三日亭午已后较热退晚加小凉稳睡有诗因论壮年乐事戏呈元二十一曹长","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["今兹商用事，余热亦已末。","衰年旅炎方，生意从此活。","亭午减汗流，北邻耐人聒。","晚风爽乌匼，筋力苏摧折。","闭目逾十旬，大江不止渴。","退藏恨雨师，健步闻旱魃。","园蔬抱金玉，无以供采掇。","密云虽聚散，徂暑终衰歇。","前圣眘焚巫，武王亲救暍。","阴阳相主客，时序递回斡。","洒落唯清秋，昏霾一空阔。","萧萧紫塞雁，南向欲行列。","歘思红颜日，霜露冻阶闼。","胡马挟雕弓，鸣弦不虚发。","长鈚逐狡兔，突羽当满月。","惆怅白头吟，萧条游侠窟。","临轩望山阁，缥缈安可越。","高人炼丹砂，未念将朽骨。","少壮迹颇疎，欢乐曾倏忽。","杖藜风尘际，老丑难翦拂。","吾子得神仙，本是池中物。","贱夫美一睡，烦促婴词笔。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"绮丽","style2":["沉郁"],"mood":"欢愉","mood2":["慷慨"],"scene":["楼","月","夏"],"cats":{"抒情":["思乡"],"四季":["夏天","秋天"],"山水":["长江"],"天气":["太阳","月亮"],"人生":["青春"],"生活":["边塞"]},"theme_conf":0.448},{"uid":"133359e4-c7c2-4a43-9adc-e5e8ea4e2e41","title":"杂曲歌辞 少年行四首 三","author":"令狐楚","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["弓背霞明劒照霜，秋风走马出咸阳。","未收天子河湟地，不拟回头望故乡。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"悲慨","style2":[],"mood":"慷慨","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"人生":["青春"]},"theme_conf":0.517},{"uid":"8aa6132d-c61e-4218-af24-5d9009e6795d","title":"春日书情寄元校书伯和相国元子","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["数岁平津邸，诸生出门时。","羇孤力行早，疎贱托身迟。","芳草看无厌，青山到未期。","贫居悲老大，春日上茅茨。","卫玠琼瑶色，玄成鼎鼐姿。","友朋汉相府，兄弟谢家诗。","律合声虽应，劳歌调自悲。","流年不可住，惆怅镜中丝。"],"theme":"寄赠酬答","theme2":["应制干谒"],"style":"沉郁","style2":["悲慨"],"mood":"悲怆","mood2":["惆怅","孤寂"],"scene":["春"],"cats":{"抒情":["伤感","孤独"],"四季":["春天"],"天气":["太阳"],"人生":["时光"]},"theme_conf":0.88},{"uid":"9a2bdab8-9e68-4478-ade8-11d5fbb822c6","title":"杂曲歌辞 生别离","author":"孟云卿","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["结发生别离，相思复相保。","何知日已久，五变庭中草。","眇眇天海途，悠悠吴江岛。","但恐不出门，出门无远道。","远道行既难，家贫衣服单。","严风吹积雪，晨起鼻何酸。","人生各有恋，岂不怀所安。","分明天上日，生死誓同欢。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":["慷慨"],"scene":["雪"],"cats":{"抒情":["离别","思念"],"天气":["写雪"]},"theme_conf":0.74},{"uid":"eaef090a-c731-44fb-8d03-829ed9237e25","title":"柳州罗池庙诗（题拟）","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["荔子丹兮蕉黄（「蕉」下或有「叶」字，或有「子」字），杂肴蔬兮进侯堂。","侯之船兮两旗，度中流兮风泊之，待侯不来兮不知我悲。","侯乘驹兮入庙，慰我民兮不嚬以笑。","鹅之山兮柳之水，桂树团团兮白石齿齿。","侯朝出游兮暮来归，春与猿吟兮秋鹤与飞。","（《唐文粹》及欧阳修所见《韩集》均作「秋与鹤飞」。","《集古录跋尾》卷八录碑文作「秋鹤与飞」，欧疑碑文有误。","沈括《梦溪笔谈》卷十四以为此用《楚辞》相错成文格，今从其说。","）北方之人兮为侯是非，千秋万岁兮侯无我违。","福我兮寿我，驱厉鬼兮山之左。","下无湿兮高无干，秔稌充羡兮蛇蛟结蟠。","我民报事兮无怠其始，自今兮钦于世世。","（同前书卷三一、《唐文粹》卷五二《柳州罗池庙碑》附）（〖1〗《柳州罗池庙碑》云：「三年孟秋辛卯，侯降于州之后堂，欧阳翼等见而拜之。","其夕，梦翼而告之曰：『馆我于罗池。","』其日景辰，庙成，大祭。","过客李仪醉酒，慢侮堂上，得疾，扶出庙门即死。","明年春，魏忠、欧阳翼使谢宁来京师，请书其事于石。","余谓柳侯生能泽其民，死能惊动祸福之，以食其土，可谓灵也已。","作迎享送神诗遗柳民，俾歌以祀焉而幷刻之。","……其词曰〖词略〗。","」《湖南通志·金石》六著录嘉定刻此碑，题作《唐罗池庙享神词碑》，附魏绍芳跋此为享神诗。","《唐诗别裁集》卷七收入。","朱东润师主编《中国历代文学作品选》中编第一册收此诗，题作《柳州罗池庙诗》，解题云：「此庙建成后，韩愈为撰《柳州罗池庙碑》，诗就附在碑文的后面。","诗效《楚辞·九歌》体，作为祭祀中迎神、送神时歌唱之用。","」）。"],"theme":"佛道禅颂","theme2":["咏物","咏史怀古","山水田园"],"style":"绮丽","style2":["幽峭","豪放"],"mood":"悲怆","mood2":[],"scene":["园林","酒","秋"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"人生":["读书"],"植物":["柳树"],"食物":["荔枝"]},"theme_conf":0.75},{"uid":"0222bb09-1f03-473b-b3d7-bd41709a2643","title":"朱陈村","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["徐州古丰县，有村曰朱陈。","去县百余里，桑麻青氛氲。","机梭声札札，牛驴走纭纭。","女汲涧中水，男采山上薪。","县远官事少，山深人俗淳。","有财不行商，有丁不入军。","家家守村业，头白不出门。","生为村之民，死为村之尘。","田中老与幼，相见何欣欣。","一村唯两姓，世世为婚姻。","亲疎居有族，少长游有群。","黄鸡与白酒，欢会不隔旬。","生者不远别，嫁娶先近邻。","死者不远葬，坟墓多绕村。","既安生与死，不苦形与神。","所以多寿考，往往见玄孙。","我生礼义乡，少小孤且贫。","徒学辨是非，祗自取辛勤。","世法贵名教，士人重冠婚。","以此自桎梏，信为大谬人。","十岁解读书，十五能属文。","二十举秀才，三十为谏臣。","下有妻子累，上有君亲恩。","承家与事国，望此不肖身。","忆昨旅游初，迨今十五春。","孤舟三适楚，羸马四经秦。","昼行有饥色，夜寝无安魂。","东西不暂住，来往若浮云。","离乱失故乡，骨肉多散分。","江南与江北，各有平生亲。","平生终日别，逝者隔年闻。","朝忧卧至暮，夕哭坐达晨。","悲火烧心曲，愁霜侵鬓根。","一生苦如此，长羡村中民。"],"theme":"山水田园","theme2":["羁旅思乡","悼亡挽歌"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["愁怨"],"scene":["江南"],"cats":{"抒情":["离别","思乡","伤感","悼亡"],"人物":["老师"],"人生":["读书"],"生活":["乡村","田野"]},"theme_conf":0.301},{"uid":"b6bf3b29-a210-4644-9ac4-51c39dac7751","title":"南阳道中作","author":"窦巩","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["东风雨洗顺阳川，蜀锦花开绿草田。","彩雉鬬时频驻马，酒旗翻处亦留钱。","新晴日照山头雪，薄暮人争渡口船。","早晚到家春欲尽，今年寒食月初圆。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春","雨","清明","雪","酒"],"cats":{"抒情":["思乡"],"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.95},{"uid":"02880a43-5d89-4b2b-b2a9-f99228969262","title":"西陵口观海","author":"薛据","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["长江漫汤汤，近海势弥广。","在昔胚浑凝，融为百川泱。","地形失端倪，天色𪷽滉漾。","东南际万里，极目远无象。","山影乍浮沈，潮波忽来往。","孤帆或不见，櫂歌犹想像。","日暮长风起，客心空振荡。","浦口霞未收，潭心月初上。","林屿几邅回，亭臯时偃仰。","岁晏访蓬瀛，真游非外奖。"],"theme":"咏史怀古","theme2":["送别","羁旅思乡"],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["思乡","孤独","怀古"],"山水":["长江"]},"theme_conf":0.357},{"uid":"3e504df9-b22d-480e-9e7c-9f8ab8591b91","title":"宿业师山房期丁大不至","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["夕阳度西岭，群壑倏已暝。","松月生夜凉，风泉满清听。","樵人归欲尽，烟鸟栖初定。","之子期宿来，孤琴候萝迳。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"抒情":["孤独"]},"theme_conf":0.807},{"uid":"e70730a9-552c-481c-aadc-364713afd410","title":"横吹曲辞 折杨柳","author":"李白","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["垂杨拂绿水，摇艳东风年。","花明玉关雪，叶暖金窗烟。","美人结长恨，相对心凄然。","攀条折春色，远寄龙庭前。"],"theme":"闺情宫怨","theme2":["送别"],"style":"绮丽","style2":["沉郁"],"mood":"愁怨","mood2":["相思"],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"人物":["女子"],"植物":["柳树"]},"theme_conf":0.526},{"uid":"4c9c3d75-272f-4529-bf21-8aafbe5b276e","title":"杂曲歌辞 昔昔盐 那能惜马蹏","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["云中路杳杳，江畔草萋萋。","妾久垂珠泪，君何惜马蹏。","边风悲晓角，营月怨春鼙。","未道休征战，愁眉又复低。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["婉约","悲慨"],"mood":"愁怨","mood2":[],"scene":["春","月","江"],"cats":{"抒情":["伤感"],"四季":["春天"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.665},{"uid":"1f92134b-bca9-46eb-b2fe-87b30413041a","title":"江雪","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["千山鸟飞绝，万迳人踪灭。","孤舟蓑笠翁，独钓寒江雪。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["雪","冬"],"cats":{"抒情":["孤独"],"山水":["江河"],"天气":["写雪"]},"theme_conf":0.787},{"uid":"f5e1247c-6c4a-45a3-9f2e-60adee788526","title":"琴曲歌辞 宛转歌二首 二","author":"刘方平","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["晓将近，黄姑织女银河尽。","九华锦衾无复情，千金宝镜谁能引。","歌宛转，宛转伤别离。","愿作杨与柳，同向玉窗垂。"],"theme":"送别","theme2":["闲适隐逸"],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["七夕"],"cats":{"抒情":["离别"],"天气":["星星"],"节日":["七夕节"]},"theme_conf":0.486},{"uid":"7b36c019-2f0c-433b-b1a9-a4b5dec9b64b","title":"銮驾避狄岁寄别韩云卿","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["白发壮心死，愁看国步移。","关山惨无色，亲爱忽惊离。","影绝龙分剑，声衰鸟恋枝。","茫茫云海外，相忆不相知。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":["愁怨","悲怆"],"scene":["塞外","山"],"cats":{"抒情":["离别","伤感"],"天气":["写云"]},"theme_conf":0.839},{"uid":"07238ad9-c348-43d4-b1d7-25d89369286d","title":"逢入京使","author":"岑参","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["故园东望路漫漫，双袖龙钟泪不干。","马上相逢无纸笔，凭君传语报平安。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"婉约","style2":["沉郁"],"mood":"恬淡","mood2":["愁怨"],"scene":["园林"],"cats":{"抒情":["思乡","伤感"]},"theme_conf":0.593},{"uid":"6b939a56-7ec3-4f83-a887-48db856ae272","title":"杂曲歌辞 古别离","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["白水东悠悠，中有西行舟。","舟行有返棹，水去无还流。","奈何生别者，戚戚怀远游。","远游谁当惜，所悲会难收。","自君间芳躧，青阳四五遒。","皓月掩兰室，光风虚蕙楼。","相思无明晦，长叹累冬秋。","离居分迟暮，驾高何淹留。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["悲慨"],"mood":"相思","mood2":["悲怆"],"scene":["舟","冬"],"cats":{"抒情":["离别","思念","伤感"],"四季":["冬天"]},"theme_conf":0.842},{"uid":"ed13392c-ff75-46b4-923b-509cadddbc24","title":"冬宵各为四韵","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["雕宫静龙漏，绮阁宴公侯。","珠帘烛燄动，绣柱月光浮。","云起将歌发，风停与管遒。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":["欢愉"],"scene":["冬","夜","月"],"cats":{"抒情":["闺怨"],"四季":["冬天"]},"theme_conf":1.0},{"uid":"cp4f2dbc5ba59cc9","title":"高阳台","author":"王沂孙","dynasty":"宋","section":"宋词","form":"词","paragraphs":["残雪庭阴，轻寒帘影，霏霏玉管春葭。","小帖金泥，不知春在谁家。","相思一夜窗前梦，奈个人、水隔天遮。","但凄然，满树幽香，满地横斜。","江南自是离愁苦，况游骢古道，归雁平沙。","怎得银笺，殷勤与说年华。","如今处处生芳草，纵凭高、不见天涯。","更消他，几度东风，几度飞花。"],"theme":"羁旅思乡","theme2":["爱情相思"],"style":"婉约","style2":["沉郁","绮丽"],"mood":"相思","mood2":["愁怨"],"scene":["春","花"],"cats":{"抒情":["爱情","思念","思乡","伤感"],"四季":["春天"]},"theme_conf":0.639},{"uid":"cp4100786b85f97e","title":"阮郎归","author":"晏几道","dynasty":"宋","section":"宋词","form":"词","paragraphs":["天边金掌露成霜。","云随雁字长。","绿杯红袖称重阳。","人情似故乡。","兰佩紫，菊簪黄。","殷勤理旧狂。","欲将沈醉换悲凉。","清歌莫断肠。"],"theme":"羁旅思乡","theme2":["节令风俗"],"style":"豪放","style2":["清新","绮丽"],"mood":"悲怆","mood2":["愁怨"],"scene":["重阳","酒"],"cats":{"抒情":["思乡","伤感"],"节日":["重阳节"]},"theme_conf":0.601},{"uid":"c56ad06f-0556-40c9-a32b-cdd4cc2536c8","title":"夜泊湘江","author":"于武陵","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["北风吹楚树，此地独先秋。","何事屈原恨，不随湘水流。","凉天生片月，竟夕伴孤舟。","一作南行客，无成空白头。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["夜","江","端午","秋","舟"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"节日":["端午节"]},"theme_conf":1.0},{"uid":"6d8b0386-c539-45d8-8d63-f7d90c74f21c","title":"哭刘夫子","author":"于鹄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["近问南州客，云亡已数春。","痛心曾受业，追服恨无亲。","孀妇归乡里，书斋属四邻。","不知经乱后，奠祭有何人。"],"theme":"悼亡挽歌","theme2":["羁旅思乡"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["春"],"cats":{"抒情":["思乡","悼亡"],"四季":["春天"],"人物":["老师"]},"theme_conf":0.97},{"uid":"ab8714f5-9716-490c-ba80-04926c6c4849","title":"送柳道士","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["去世能成道，游仙不定家。","归期千岁鹤，行迈五云车。","海上春应尽，壶中日未斜。","不知相忆处，琪树几枝花。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思念"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.546},{"uid":"4bef9a5e-f4a1-44bd-a78c-cb0fe38ccdff","title":"杂曲歌辞 长干曲四首 一","author":"崔颢","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["君家定何处？妾住在横塘。","停舟暂借问，或恐是同乡。"],"theme":"羁旅思乡","theme2":["闺情宫怨"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["舟"],"cats":{"抒情":["思乡","闺怨"]},"theme_conf":0.594},{"uid":"cpeebd84aa2d951a","title":"踏莎行","author":"晏殊","dynasty":"宋","section":"宋词","form":"词","paragraphs":["祖席离歌，长亭别宴。","香尘已隔犹回面。","居人匹马映林嘶，行人去棹依波转。","画阁魂消，高楼目断。","斜阳只送平波远。","无穷无尽是离愁，天涯地角寻思遍。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["欢愉"],"scene":["楼"],"cats":{"抒情":["离别","伤感"]},"theme_conf":0.806},{"uid":"a6819c5a-cece-4e07-a998-9513c2c2851d","title":"叶落","author":"吴融","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["红影飘来翠影微，一辞林表不知归。","伴愁无色烟犹在，替恨成啼露未晞。","若逐水流应万里，莫因风起便孤飞。","楚郊千树秋声急，日暮纷纷惹客衣。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"a87be94b-e983-40ff-8350-48a16dbfc585","title":"过严君平古井","author":"郑世翼","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["严平本高尚，远蹈古人风。","卖卜成都市，流名大汉中。","旧井改人世，寒泉久不通。","多年既罢汲，无禽乃遂空。","如何属秋气，唯见落双桐。"],"theme":"咏史怀古","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"抒情":["怀古"],"四季":["秋天"],"人物":["父亲"]},"theme_conf":1.0},{"uid":"ab76c0fc-144b-4884-a054-efec2987e260","title":"和谒孔子庙","author":"刘斌","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["性与虽天纵，主世乃无由。","何言泰山毁，空惊逝水流。","及门思往烈，入室想前修。","寂寞荒堦暮，摧残古木秋。","遗风暧如此，聊以慰蒸求。"],"theme":"咏史怀古","theme2":["悼亡挽歌"],"style":"冲淡","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"抒情":["孤独","悼亡","怀古"],"山水":["泰山"]},"theme_conf":0.501},{"uid":"36128fe1-a9f6-4841-99a6-9b7995ac94d3","title":"游徐城河忽见清淮因寄赵八","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["自缘迟暮忆沧洲，翻爱南河浊水流。","初过重阳惜残菊，行看旧浦识群鸥。","朝霞映日同归处，暝柳摇风欲别秋。","长恨相逢即分首，含情掩泪独回头。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["重阳"],"cats":{"抒情":["伤感"],"山水":["江河"],"节日":["重阳节"]},"theme_conf":0.88},{"uid":"e4bc93c8-417d-4670-8fc0-ca28d3fa3bf8","title":"忆长安 二月","author":"鲍防","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["忆长安，二月时，玄鸟初至禖祠。","百啭宫莺绣羽，千条御柳黄丝。","更有曲江胜地，此来寒食佳期。"],"theme":"节令风俗","theme2":["爱情相思"],"style":"清新","style2":[],"mood":"相思","mood2":["恬淡"],"scene":["月","清明"],"cats":{"抒情":["思念"],"天气":["月亮"],"节日":["寒食节","清明节"]},"theme_conf":0.95},{"uid":"a9d3bfca-8402-4946-ad02-53db1964a3b2","title":"列女操","author":"孟郊","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["梧桐相待老，鸳鸯会双死。","贞女贵狥夫，舍生亦如此。","波澜誓不起，妾心井中水。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"慷慨","mood2":["悲怆","欢愉"],"scene":[],"cats":{"抒情":["闺怨"]},"theme_conf":0.669},{"uid":"5a8125f7-cc2c-43dc-82e6-3d74dcb898c2","title":"宫词一百首 五十八","author":"王建","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["风帘水阁压芙蓉，四面钩栏在水中。","避热不归金殿宿，秋河织女夜妆红。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["七夕","秋","夜","楼"],"cats":{"抒情":["闺怨"],"四季":["秋天"],"节日":["七夕节"]},"theme_conf":1.0},{"uid":"ef3c51b2-f0a5-4d9b-8ae3-2a24b342ddee","title":"新乐府 隋堤柳\t悯亡国也","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["隋堤柳，岁久年深尽衰朽。","风飘飘兮雨萧萧，三株两株汴河口。","老枝病叶愁杀人，曾经大业年中春。","大业年中炀天子，种柳成行夹流水。","西自黄河东至淮，绿阴一千三百里。","大业末年春暮月，柳色如烟絮如雪。","南幸江都恣佚游，应将此柳系龙舟。","紫髯郎将护锦缆，青娥御史直迷楼。","海内财力此时竭，舟中歌笑何日休。","上荒下困势不久，宗社之危如缀旒。","炀天子，自言福祚长无穷，岂知皇子封酅公。","龙舟未过彭城合，义旗已入长安宫。","萧墙祸生人事变，晏驾不得归秦中。","土坟数尺何处葬，吴公台下多悲风。","二百年来汴河路，沙草和烟朝复暮。","后王何以鉴前王，请看隋堤亡国树。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["江","端午","楼","舟","春"],"cats":{"抒情":["伤感","怀古"],"四季":["春天"],"山水":["黄河"],"节日":["端午节"],"植物":["柳树"]},"theme_conf":0.92},{"uid":"6bb164b4-b9d3-4d23-b54b-e71e3535ddc7","title":"左掖梨花","author":"丘为","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["冷艳全欺雪，余香乍入衣。","春风且莫定，吹向玉阶飞。"],"theme":"咏物","theme2":["闺情宫怨"],"style":"悲慨","style2":["旷达"],"mood":"孤寂","mood2":[],"scene":["花","雪","春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"植物":["梨花"]},"theme_conf":0.556},{"uid":"cp8eb6476175d018","title":"风流子","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["新绿小池塘。","风帘动，碎影舞斜阳。","羡金屋去来，旧时巢燕，土花缭绕，前度莓墙。","绣阁凤帏深几许，曾听得理丝簧。","欲说又休，虑乖芳信，未歌先咽，愁近清觞。","遥知新妆了，开朱户，应自待月西厢。","最苦梦魂，今宵不到伊行。","问甚时说与，佳音密耗，寄将秦镜，偷换韩香。","天便教人，霎时厮见何妨。"],"theme":"闺情宫怨","theme2":[],"style":"清新","style2":["旷达","绮丽"],"mood":"愁怨","mood2":[],"scene":["花","酒"],"cats":{"抒情":["伤感","闺怨"],"天气":["写风"]},"theme_conf":0.733},{"uid":"cp7b0c4733cd64bf","title":"谢金莲诗酒红梨花・那咤令","author":"张寿卿","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["这妮子我问着呵，没些儿个势沙；这妮子道着呵，将话儿对答；这妮子使着呵，早装聋做哑。","泼贱才，堪人骂，再休来利齿能牙。","(梅香云)我说甚的来？(正旦唱)。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["花","酒"],"cats":{"抒情":["感恩"],"植物":["梨花","荷花"],"食物":["写酒"]},"theme_conf":1.0},{"uid":"bdb32446-6efc-402e-93f0-901b8eefe57e","title":"杂曲歌辞 生别离","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["食蘗不易食梅难，蘗能苦兮梅能酸。","未如生别之为难，苦在心兮酸在肝。","晨鸡载鸣残月没，征马重嘶行人出。","回看骨肉哭一声，梅酸蘗苦甘如蜜。","黄河水白黄云秋，行人河边相对愁。","天寒野旷何处宿？棠梨叶战风飕飕。","生离别，生离别，忧从中来无断绝。","忧积心劳血气衰，未年三十生白发。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["江","秋","月"],"cats":{"抒情":["离别","伤感"],"四季":["秋天"],"山水":["黄河"],"人生":["战争"]},"theme_conf":0.762},{"uid":"f129bf81-4ca2-41c1-912e-4348dfb7956e","title":"吊白居易","author":"宣宗皇帝","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["缀玉联珠六十年，谁教冥路作诗仙。","浮云不系名居易，造化无为字乐天。","童子解吟《长恨曲》，胡儿能唱《琵琶篇》。","文章已满行人耳，一度思卿一怆然。"],"theme":"悼亡挽歌","theme2":["咏史怀古","题画咏艺","边塞征战"],"style":"绮丽","style2":["沉郁"],"mood":"悲怆","mood2":["愁怨","欢愉"],"scene":[],"cats":{"抒情":["悼亡","怀古"]},"theme_conf":0.99},{"uid":"30a03a87-348d-477a-9f49-962ce991f8a8","title":"詶皇甫侍御望天灊山见示之作","author":"独孤及","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["早岁慕五岳，尝为尘机碍。","孰知天柱峰，今与郡斋对。","隐嶙抱元气，氤氲含青霭。","云崖媚远空，石壁寒古塞。","汉皇南游日，望秩此昭配。","法驾到谷口，礼容振荒外。","焚柴百神趋，执玉万方会。","天旋物顺动，德布泽霶霈。","讲武威已耀，学仙功未艾。","黄金竟何成，洪业遽沦昧。","度世若一瞬，昨朝已千载。","如今封禅坛，唯见云雨晦。","长望哀往古，劳生惭大块。","清晖幸相娱，幽独知所赖。","寒城春方正，初日明可爱。","万殊喜阳和，余亦荷时泰。","山色日夜绿，下有清浅濑。","愧作拳偻人，沈迷簿书内。","登临叹拘限，出处悲老大。","况听郢中曲，复识湘南态。","思免物累牵，敢令道机退。","瞒然诵佳句，持此秋兰佩。"],"theme":"山水田园","theme2":["应制干谒"],"style":"清新","style2":["冲淡","悲慨"],"mood":"悲怆","mood2":["孤寂","相思"],"scene":["山"],"cats":{"抒情":["伤感","孤独"],"山水":["泰山"]},"theme_conf":0.359},{"uid":"79ddee12-c5fd-4c8d-a46b-eb1d6649d850","title":"郊庙歌辞 享节愍太子庙乐章 登歌酌鬯","author":"不详","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["灼灼重明，仰承元首。","既贤且哲，惟孝与友。","惟孝虽遥，灵规不朽。","礼因诚致，备絜玄酒。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"欢愉","mood2":[],"scene":["酒"],"cats":{"抒情":["怀古"],"食物":["写酒"]},"theme_conf":1.0},{"uid":"a4027d74-3867-4341-ad57-5248746e36a5","title":"和令狐相公春日寻花有怀白侍郎阁老","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["芳菲满雍州，鸾凤许同游。","花迳须深入，时光不少留。","色鲜由树嫩，枝亚为房稠。","静对仍持酒，高看特上楼。","晴宜连夜赏，雨便一年休。","共忆秋官处，余霞曲水头。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"恬淡","mood2":["相思"],"scene":["春","楼","花"],"cats":{"抒情":["思念"],"四季":["春天"],"人生":["时光"]},"theme_conf":0.95},{"uid":"cp8ce1e669f23042","title":"戚氏","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["晚秋天。","一霎微雨洒庭轩。","槛菊萧疏，井梧零乱惹残烟。","凄然。","望江关。","飞云黯淡夕阳间。","当时宋玉悲感，向此临水与登山。","远道迢递，行人凄楚，倦听陇水潺。","正蝉吟败叶，蛩响衰草，相应喧喧。","孤馆度日如年。","风露渐变，悄悄至更阑。","长天净，绛河清浅，皓月婵娟。","思绵绵。","夜永对景，那堪屈指，暗想从前。","未名未禄，绮陌红楼，往往经岁迁延。","帝里风光好，当年少日，暮宴朝欢。","况有狂朋怪侣，遇当歌、对酒竞留连。","别来迅景如梭，旧游似梦，烟水程何限。","念利名、憔悴长萦绊。","追往事、空惨愁颜。","漏箭移、稍觉轻寒。","渐呜咽、画角数声残。","对闲窗畔，停灯向晓，抱影无眠。"],"theme":"羁旅思乡","theme2":["咏史怀古","送别"],"style":"冲淡","style2":["沉郁","婉约"],"mood":"愁怨","mood2":["孤寂","相思"],"scene":["夜","园林","楼"],"cats":{"抒情":["思乡","伤感","孤独","怀古"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.95},{"uid":"14d67e42-0340-4c29-8fd4-0beddfe1dc2a","title":"湖上醉中代诸妓寄严郎中","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["笙歌杯酒正欢娱，忽忆仙郎望帝都。","借问连宵直南省，何如尽日醉西湖。","蛾眉别久心知否，鸡舌含多口厌无。","还有些些惆怅事，春来山路见蘼芜。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":[],"mood":"惆怅","mood2":["相思","欢愉"],"scene":["酒"],"cats":{"抒情":["思念"],"山水":["西湖"],"食物":["写酒"]},"theme_conf":0.88},{"uid":"252c40ba-d76c-4893-925b-41883a6f254c","title":"横吹曲辞 出塞","author":"陈子昂","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["忽闻天上将，关塞重横行。","始返楼兰国，还向朔方城。","黄金装战马，白羽集神兵。","星月开天阵，山川列地营。","晚风吹画角，春色耀飞旌。","宁知班定远，独是一书生。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["塞外"],"cats":{"抒情":["孤独"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.843},{"uid":"53e02f22-5213-4ef0-8258-451dfe9d5052","title":"江州赴忠州至江陵已来舟中示舍弟五十韵","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["昔作咸秦客，常思江海行。","今来仍尽室，此去又专城。","典午犹为幸，分忧固是荣。","箳篂州乘送，艛艓驿船迎。","共载皆妻子，同游即弟兄。","宁辞浪迹远，且贵赏心幷。","云展帆高挂，飙驰櫂迅征。","溯流从汉浦，循路转荆衡。","山逐时移色，江随地改名。","风光近东早，水木向南清。","夏口烟孤起，湘川雨半晴。","日煎红浪沸，月射白砂明。","北渚寒留雁，南枝暖待莺。","骈朱桃露萼，点翠柳含萌。","亥市鱼盐聚，神林鼓笛鸣。","壶浆椒叶气，歌曲竹枝声。","系缆怜沙静，垂纶爱岸平。","水飡红粒稻，野茹紫花菁。","瓯泛茶如乳，台黏酒似饧。","脍长抽锦缕，藕脆削琼英。","容易来千里，斯须进一程。","未曾劳气力，渐觉有心情。","卧稳添春睡，行迟带酒酲。","忽愁牵世网，便欲濯尘缨。","早接文场战，曾争翰苑盟。","掉头称俊造，翘足取公卿。","且昧随时义，徒输报国诚。","众排恩易失，偏压势先倾。","虎尾忧危切，鸿毛性命轻。","烛蛾谁救活，蚕茧自缠萦。","歛手辞双阙，回眸望两京。","长沙抛贾谊，漳浦卧刘桢。","𫛸鴂鸣还歇，蟾蜍破又盈。","年光同激箭，乡思极摇旌。","潦倒亲知笑，衰羸旧识惊。","乌头因感白，鱼尾为劳頳。","劒学将何用，丹烧竟不成。","孤舟萍一叶，双鬓雪千茎。","老见人情尽，闲思物理精。","如汤探冷热，似博鬬输赢。","险路应须避，迷途莫共争。","此心知止足，何物要经营。","玉向泥中洁，松经雪后贞。","无妨隐朝市，不必谢寰瀛。","但在前非悟，期无后患婴。","多知非景福，少语是元亨。","晦即全身药，明为伐性兵。","昏昏随世俗，蠢蠢学黎甿。","鸟以能言{构木=糸}，龟缘入梦烹。","知之一何晚，犹足保余生。"],"theme":"亲情","theme2":["山水田园","闲适隐逸"],"style":"沉郁","style2":["绮丽","幽峭"],"mood":"愁怨","mood2":["慷慨","恬淡"],"scene":["舟","江"],"cats":{"抒情":["伤感","爱国"],"山水":["江河"],"人生":["战争"]},"theme_conf":0.85},{"uid":"fad0b1d2-0982-4e21-a0f7-9fbde68bd3e3","title":"秋晓招隐寺东峰茶宴送内弟阎伯均归江州","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["万畦新稻傍山村，数里深松到寺门。","幸有香茶留穉子，不堪秋草送王孙。","烟尘怨别唯愁隔，井邑萧条谁忍论。","莫怪临歧独垂泪，魏舒偏念外家恩。"],"theme":"送别","theme2":["山水田园"],"style":"清新","style2":["沉郁","婉约"],"mood":"愁怨","mood2":[],"scene":["秋","山"],"cats":{"抒情":["伤感"],"四季":["秋天"],"食物":["写茶"]},"theme_conf":0.362},{"uid":"a6e781fe-94d9-48fd-9d57-cc331970e10f","title":"姑苏怀古送秀才下第归江南","author":"刘商","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["姑苏台枕吴江水，层级鳞差向天倚。","秋高露白万林空，低望吴田三百里。","当时雄盛如何比，千仞无根立平地。","台前夹月吹玉鸾，台上迎凉撼金翠。","银河倒泻君王醉，滟酒峩冠眄西子。","宫娃酣态舞娉婷，香飙四飒青城坠。","伍员结舌长嘘嚱，忠谏无因到君耳。","城乌啼尽海霞销，深掩金屏日高睡。","王道潜隳伍员死，可叹斗间瞻王气。","会稽句践拥长矛，万马鸣蹄扫空垒。","瓦解冰销真可耻，凝艳妖芳安足恃。","可怜荒堞晚冥蒙，麋鹿呦呦达遗址。","君怀逸气还东吴，吟狂日日游姑苏。","兴来下笔到奇景，瑶盘迸洒蛟人珠。","大鹏矫翼翻云衢，嵩峰霁后凌天孤。","海潮秋打罗刹石，月魄夜当彭蠡湖。","有时凝思家虚无，霓幢仿佛游仙都。","琳琅暗戛玉华殿，天香静褭金芙蕖。","君声日下闻来久，清赡何人敢敌手。","我逃名迹遁西林，不得灞陵倾别酒。","莫便五湖为隐沦，年年三十升仙人。"],"theme":"咏史怀古","theme2":["送别"],"style":"豪放","style2":["绮丽"],"mood":"孤寂","mood2":["恬淡"],"scene":["江南","江"],"cats":{"抒情":["孤独","怀古"],"山水":["庐山","江河"]},"theme_conf":0.458},{"uid":"cp969dea94a53490","title":"谢金莲诗酒红梨花・天下乐","author":"张寿卿","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["你岂知他那有志题桥汉司马，怎不教人嗔怒发，是和非你心中自临察。","端的个无礼法，只管里抵触咱，梅香你记着我这一顿打。"],"theme":"闲适隐逸","theme2":[],"style":"绮丽","style2":["豪放"],"mood":"欢愉","mood2":[],"scene":["花","酒"],"cats":{"抒情":["感恩"],"生活":["写桥"],"植物":["梨花","荷花"],"食物":["写酒"]},"theme_conf":0.65},{"uid":"d35f583a-c20c-453c-a886-e13f98b2e4b4","title":"春思","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["莺啼燕语报新年，马邑龙堆路几千。","家住秦城邻汉苑，心随明月到胡天。","机中锦字论长恨，楼上花枝笑独眠。","为问元戎窦车骑，何时反斾勒燕然。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"清新","style2":["绮丽","沉郁"],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"天气":["月亮"],"节日":["春节"]},"theme_conf":0.596},{"uid":"30150c8b-deff-44b6-ba7a-01561f0a0c30","title":"叹鲁二首 二","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["展禽胡为者，直道竟三黜。","颜子何如人，屡空聊过日。","皆怀王佐道，不践陪臣秩。","自古无奈何，命为时所屈。","有如草木分，天各与其一。","荔枝非名花，牡丹无甘实。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":["惆怅"],"scene":[],"cats":{"抒情":["伤感"],"食物":["荔枝"]},"theme_conf":1.0},{"uid":"7b8079ae-910c-4680-883a-6f747712ce0d","title":"行路难二首 二","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见富家翁，旧时贫贱谁比数。","一朝金多结豪贵，万事胜人健如虎。","子孙成行满眼前，妻能管弦妾能舞。","自矜一身忽如此，却笑傍人独愁苦。","东邻少年安所如，席门穷巷出无车。","有才不肯学干谒，何用年年空读书。"],"theme":"讽喻刺世","theme2":["羁旅思乡","闺情宫怨","民生疾苦"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":[],"cats":{"抒情":["思乡","伤感","孤独","闺怨"],"人生":["读书"]},"theme_conf":0.98},{"uid":"a36a0840-505a-449f-b3eb-e0060e8ae76d","title":"过梅里七首  家于无锡四十载今敝庐数堵犹存今列题于后","author":"李绅","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["羽毛似雪无瑕点，顾影秋池舞白云。","闲整素仪三岛近，回飘清唳九霄闻。","好风顺举应摩日，逸翮将成莫恋群。","凌励坐看空碧外，更怜凫鹭老江𣸣。"],"theme":"咏物","theme2":["咏史怀古"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["雪","冬","秋"],"cats":{"抒情":["怀古"],"四季":["秋天"],"植物":["梅花"]},"theme_conf":0.95},{"uid":"20aa930c-017e-4a7d-8909-0782047d574d","title":"苦雨寄房四昆季","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["独坐见多雨，况兹兼索居。","茫茫十月交，穷阴千里余。","弥望无端倪，北风击林箊。","白日渺难覩，黄云争卷舒。","安得造化功，旷然一扫除。","滴沥簷宇愁，寥寥谈笑疎。","泥涂拥城郭，水潦盘丘墟。","惆怅悯田农，裴回伤里闾。","曾是力井税，曷为无斗储。","万事切中怀，十年思上书。","君门嗟缅邈，身计念居诸。","沈吟顾草茅，郁怏任盈虚。","黄鹄不可羡，鸡鸣时起予。","故人平台侧，高馆临通衢。","兄弟方荀陈，才华冠应徐。","弹棋自多暇，饮酒更何如。","知人想林宗，直道慙史鱼。","携手风流在，开襟鄙吝祛。","宁能访穷巷，相与对园蔬。"],"theme":"寄赠酬答","theme2":["民生疾苦"],"style":"婉约","style2":[],"mood":"孤寂","mood2":["愁怨","惆怅"],"scene":["雨"],"cats":{"抒情":["友情","伤感","孤独"],"天气":["写雨"]},"theme_conf":0.78},{"uid":"252b4e33-b8d1-462d-a8e9-55a9766df5cf","title":"送惠师","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["惠师浮屠者，乃是不羇人。","十五爱山水，超然谢朋亲。","脱冠翦头发，飞步遗踪尘。","发迹入四明，梯空上秋旻。","遂登天台望，众壑皆嶙峋。","夜宿最高顶，举头看星辰。","光芒相照烛，南北争罗陈。","兹地绝翔走，自然严且神。","微风吹木石，澎湃闻韶钧。","夜半起下视，溟波衔日轮。","鱼龙惊踊跃，呌啸成悲辛。","怪气或紫赤，敲磨共轮囷。","金鸦既腾翥，六合俄清新。","常闻禹穴奇，东去窥瓯闽。","越俗不好古，流传失其真。","幽踪邈难得，圣路嗟长堙。","回临浙江涛，屹起高峨岷。","壮志死不息，千年如隔晨。","是非竟何有，弃去非吾伦。","凌江诣庐岳，浩荡极游巡。","崔崒没云表，陂陀浸湖沦。","是时雨初霁，悬瀑垂天绅。","前年往罗浮，步戛南海漘。","大哉阳德盛，荣茂恒留春。","鹏𬸣堕长翮，鲸戏侧修鳞。","自来连州寺，曾未造城𬮱。","日携青云客，探胜穷崖滨。","太守邀不去，群官请徒频。","囊无一金资，翻谓富者贫。","昨日忽不见，我令访其隣。","奔波自追及，把手问所因。","顾我却兴欢，君宁异于民。","离合自古然，辞别安足珍。","吾闻九疑好，夙志今欲伸。","斑竹啼舜妇，清湘沈楚臣。","衡山与洞庭，此固道所循。","寻崧方抵洛，历华遂之秦。","浮游靡定处，偶往即通津。","吾言子当去，子道非吾遵。","江鱼不池活，野鸟难笼驯。","吾非西方教，怜子狂且醇。","吾嫉惰游者，怜子愚且谆。","去矣各异趣，何为浪沾巾。"],"theme":"送别","theme2":[],"style":"清新","style2":["幽峭","豪放"],"mood":"悲怆","mood2":["慷慨","欢愉"],"scene":["江","山"],"cats":{"抒情":["离别","伤感"],"山水":["江河"],"人生":["励志","梦想"]},"theme_conf":0.619},{"uid":"f3c09e9e-e471-4489-9d3f-a598832ac638","title":"悲陈陶","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["孟冬十郡良家子，血作陈陶泽中水。","野旷天清无战声，四万义军同日死。","群胡归来血洗箭，仍唱胡歌饮都市。","都人回面北向啼，日夜更望官军至。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["夜","冬"],"cats":{"抒情":["伤感"],"四季":["冬天"],"人生":["战争"]},"theme_conf":1.0},{"uid":"cp148022419cf353","title":"念奴娇","author":"李清照","dynasty":"宋","section":"宋词","form":"词","paragraphs":["萧条庭院，有斜风细雨，重门须闭。","宠柳娇花寒食近，种种恼人天气。","险韵诗成，扶头酒醒，别是闲滋味。","征鸿过尽，万千心事难寄。","楼上几日春寒，帘垂四面，玉阑干慵倚。","被冷香消新梦觉，不许愁人不起。","清露晨流，新桐初引，多少游春意。","日高烟敛，更看今日晴未。"],"theme":"送别","theme2":["节令风俗","闲适隐逸"],"style":"婉约","style2":["清新","幽峭"],"mood":"相思","mood2":["慷慨","愁怨"],"scene":["雨","园林","楼","清明","春","花"],"cats":{"抒情":["伤感"],"四季":["春天"],"天气":["写雨"],"节日":["寒食节","清明节"]},"theme_conf":0.45},{"uid":"5f4c3465-566a-4a92-886d-20155ea07a0e","title":"相和歌辞 挽歌二首 二","author":"于鹄","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["双辙出郭门，緜緜东西道。","送死多于生，几人得终老。","见人切肺肝，不如归山好。","不闻哀哭声，默默安怀抱。","时尽从物化，又免生忧扰。","世间寿者稀，尽为悲伤恼。"],"theme":"悼亡挽歌","theme2":[],"style":"悲慨","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":["山"],"cats":{"抒情":["伤感","悼亡"]},"theme_conf":0.94},{"uid":"34751bd9-cc56-4d97-b75a-ff8665fd9b27","title":"鹦鹉猫儿篇","author":"阎朝隐","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["霹雳引，丰隆鸣，猛兽噫气蛇吼声。","鹦鹉鸟，同资造化兮殊粹精。","鹔鹴毛，翡翠翼。","鹓雏延颈，鹍鸡弄色。","鹦鹉鸟，同禀阴阳兮异埏埴。","彼何为兮，隐隐振振。","此何为兮，绿衣翠襟。","彼何为兮，窘窘蠢蠢。","此何为兮，好貌好音。","彷彷兮徉徉，似妖姬躧步兮动罗裳。","趋趋兮跄跄，若处子回眸兮登玉堂。","爰有兽也，安其忍，觜其脇，距其胸，与之放旷浪浪兮，从从容容。","钩爪锯牙也，宵行昼伏无以当，遇之兮忘味。","抟击腾掷也，朝飞暮噪无以拒，逢之兮屏气。","由是言之，贪残薄则智慧作，贪残临之兮不复攫。","由是言之，智慧周则贪残囚，智慧犯之兮不复忧。","菲形陋质虽贱微，皇王顾遇长光辉。","离宫别馆临朝市，妙舞繁弦杂宫征。","嘉喜堂前景福内，合欢殿上明光里。","云母屏风文彩合，流苏斗帐香烟起。","承恩宴盼接宴喜，高视七头金骆驼。","平怀五尺铜狮子，国有君兮国有臣。","君为主兮臣为宾，朝有贤兮朝有德。","贤为君兮德为饰，千年万岁兮心转忆。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"抒情":["离别"],"动物":["写猫"]},"theme_conf":1.0},{"uid":"7fc091bf-83dd-498d-87e0-d82fd2575e0f","title":"赴阙次留献荆南成相公三十韵","author":"吴融","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["分阃兼文德，持衡有武功。","荆南知独去，海内更谁同。","拔地孤峰秀，当天一鹗雄。","云生五色笔，月吐六钧弓。","骨格凌秋耸，心源见底空。","神清飡沆瀣，气逸饮洪蒙。","临事成奇策，全身仗至忠。","解鞍欺李广，煮弩笑臧洪。","往昔逢多难，来兹故统戎。","卓旗云梦泽，扑火细腰宫。","铲土楼台搆，连江雉堞笼。","似平铺掌上，疑涌出壶中。","岂是劳人力，宁因役鬼工。","本遗三户在，今匝万家通。","画舸横青雀，危樯列彩虹。","席飞巫峡雨，袖拂宋亭风。","塲广盘毬子，池闲引钓筒。","礼贤金璧贱，煦物雪霜融。","酒满梁尘动，棋残漏滴终。","俭常资澹静，贵绝恃穹崇。","唯要臣诚显，那求帝渥隆。","甘棠名异奭，大树姓非冯。","自念为迁客，方谐谒上公。","痛知遭止棘，频叹委飘蓬。","借宅诛茅绿，分囷指粟红。","只惭燕馆盛，宁觉阮途穷。","涣汗沾明主，沧浪别钓翁。","去曾忧塞马，归欲逐边鸿。","积感深于海，衔恩重极嵩。","行行柳门路，回首下离东。"],"theme":"应制干谒","theme2":["闲适隐逸","应制干谒","送别"],"style":"冲淡","style2":["清新","幽峭"],"mood":"孤寂","mood2":["恬淡"],"scene":["楼","秋","酒","塞外"],"cats":{"抒情":["离别","孤独"],"四季":["秋天"],"天气":["彩虹"]},"theme_conf":0.95},{"uid":"800f5d12-980c-463a-acbd-4b6d675ac93d","title":"徒步归行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["明公壮年值时危，经济实藉英雄姿。","国之社稷今若是，武定祸乱非公谁。","凤翔千官且饱饭，衣马不复能轻肥。","青袍朝士最困者，白头拾遗徒步归。","人生交契无老少，论交何必先同调。","妻子山中哭向天，须公枥上追风骠。"],"theme":"羁旅思乡","theme2":["悼亡挽歌"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["慷慨"],"scene":[],"cats":{"抒情":["思乡","悼亡"]},"theme_conf":0.585},{"uid":"202641be-8d53-4de4-b477-fcbef11c89bf","title":"种白蘘荷","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["血虫化为疠，夷俗多所神。","衔猜每腊毒，谋富不为仁。","蔬果自远至，杯酒盈肆陈。","言甘中必苦，何用知其真。","华洁事外饰，尤病中州人。","钱刀恐贾害，饥至益逡巡。","窜伏常战栗，怀故逾悲辛。","庶氏有嘉草，攻禬事久泯。","炎帝垂灵编，言此殊足珍。","崎岖乃有得，托以全余身。","纷敷碧树阴，眄睐心所亲。"],"theme":"讽喻刺世","theme2":["民生疾苦","边塞征战","咏物"],"style":"沉郁","style2":["清新"],"mood":"悲怆","mood2":[],"scene":["夏","酒"],"cats":{"抒情":["伤感"],"四季":["夏天"],"人生":["战争"],"植物":["荷花"]},"theme_conf":0.88},{"uid":"4dbfdde1-a5ba-440f-8acc-3d0872c72351","title":"浔阳陶氏别业","author":"刘眘虚","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["陶家习先隐，种柳长江边。","朝夕浔阳郭，白衣来几年。","霁云明孤岭，秋水澄寒天。","物象自清旷，野情何绵联。","萧萧丘中赏，明宰非徒然。","愿守黍稷税，归耕东山田。"],"theme":"送别","theme2":["山水田园","民生疾苦"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["离别","孤独"],"山水":["长江"]},"theme_conf":0.382},{"uid":"ef32c93e-f044-4031-b566-3c4bd658a396","title":"寄永嘉王十二","author":"钱起","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["永嘉风景入新年，才子诗成定可怜。","梦里还乡不相见，天涯忆戴复谁传。","花倾晓露垂如泪，莺拂游丝断若弦。","愿得回风吹海雁，飞书一宿到君边。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"清新","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["鸟"],"cats":{"抒情":["思念","思乡","伤感"],"节日":["春节"]},"theme_conf":0.95},{"uid":"215caa5f-74fc-4e81-af61-b8ba6c9a9ff0","title":"落第归乡留别长安主人","author":"豆卢复","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["客里愁多不记春，闻莺始叹柳条新。","年年下第东归去，羞见长安旧主人。"],"theme":"羁旅思乡","theme2":["送别"],"style":"沉郁","style2":[],"mood":"恬淡","mood2":["愁怨"],"scene":["春"],"cats":{"抒情":["离别","思乡","伤感"],"四季":["春天"],"节日":["春节"]},"theme_conf":0.597},{"uid":"992319d5-c110-4285-9302-cb6d8144bd85","title":"田家春望","author":"高适","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["出门何所见，春色满平芜。","可叹无知己，高阳一酒徒。"],"theme":"山水田园","theme2":["民生疾苦"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"抒情":["友情"],"四季":["春天"],"生活":["田野"]},"theme_conf":0.598},{"uid":"66d08e7c-5949-4f75-a9bf-6fa8f16392c9","title":"过梅里七首  家于无锡四十载今敝庐数堵犹存今列题于后 翡翠坞","author":"李绅","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["翡翠飞飞绕莲坞，一啄嘉鱼一鸣舞。","莲茎触散莲叶欹，露滴珠光似还浦。","虞人掠水轻浮弋，翡翠惊飞飞不息。","直上层空翠影高，还向云间双比翼。","弹射莫及弋不得，日暮虞人空叹息。"],"theme":"咏史怀古","theme2":["爱情相思"],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["冬"],"cats":{"抒情":["爱情","怀古"],"植物":["梅花"]},"theme_conf":0.565},{"uid":"3ca0e586-2804-4c73-9190-1ccc18267e00","title":"送王府张参军附学及第东归","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["邻家不识鬬鸡翁，闭户能齐隐者风。","顾步曾为小山客，成名因事大江公。","一身千里寒芜上，单马重裘腊月中。","寂寂故园行见在，暮天残雪洛城东。"],"theme":"送别","theme2":["羁旅思乡","边塞征战"],"style":"沉郁","style2":["冲淡"],"mood":"孤寂","mood2":[],"scene":["雪","月","山","江","园林"],"cats":{"抒情":["思乡"],"山水":["长江"]},"theme_conf":0.366},{"uid":"afb9c85b-d867-4bda-8c84-516d90b554e0","title":"落叶","author":"孔德绍","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["早秋惊叶落，飘零似客心。","翻飞未肯下，犹言惜故林。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":0.761},{"uid":"ecfeec5e-3205-401e-bc5d-e9b58efb9031","title":"桃源行送友","author":"武元衡","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["武陵川径入幽遐，中有鸡犬秦人家，家傍流水多桃花。","桃花两边种来久，流水一通何时有。","垂条落蘂暗春风，夹岸芳菲至山口。","岁岁年年能寂寥，林下青苔日为厚。","时有仙鸟来衔花，曾无世人此携手。","可怜不知若为名，君往从之多所更。","古驿荒桥平路尽，崩湍怪石小溪行。","相见维舟登览处，红堤绿岸宛然成。","多君此去从仙隐，令人晚节悔营营。"],"theme":"送别","theme2":["山水田园"],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["春","花"],"cats":{"抒情":["友情"],"四季":["春天"],"生活":["写桥"],"植物":["桃花"]},"theme_conf":0.408},{"uid":"cpc3d19d89e4eef8","title":"八归","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["芳莲坠粉，蔬桐吹绿，庭院暗雨乍歇。","无端抱影销魂处，还见筱墙萤暗，藓阶蛩切。","送客重寻西去路，问水面、琵琶谁拨。","最可惜、一片江山，总付与啼。","长恨相从未款，而今何事，又对西风离别。","渚寒烟淡，棹移人远，缥缈行舟如叶。","想文君望久，倚竹愁生步罗袜。","归来后、翠尊双饮，下了珠帘，玲珑闲看月。"],"theme":"送别","theme2":[],"style":"婉约","style2":["绮丽","沉郁"],"mood":"愁怨","mood2":["恬淡"],"scene":["舟","园林","江"],"cats":{"抒情":["离别","伤感"]},"theme_conf":0.545},{"uid":"26b530b0-e610-4d5c-b8a1-0d7a9b648dac","title":"相和歌辞 江南曲八首 二","author":"刘希夷","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["艳唱潮初落，江花露未晞。","春洲惊翡翠，朱服弄芳菲。","画舫烟中浅，青阳日际微。","锦帆冲浪湿，罗袖拂行衣。","含情罢所采，相叹惜流晖。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["江","江南"],"cats":{"抒情":["闺怨"],"山水":["江河"]},"theme_conf":0.62},{"uid":"a5301061-dc9b-4a5b-b5ec-55cb5c2feb65","title":"晋公魏国夫人柳氏挽歌","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["鱼轩海上遥，鸾影月中销。","双剑来时合，孤桐去日凋。","夕阳迷陇隧，秋雨咽笳箫。","画翣无留影，铭旌已度桥。"],"theme":"悼亡挽歌","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","月","雨"],"cats":{"抒情":["孤独","悼亡"],"四季":["秋天"],"生活":["写桥"],"植物":["柳树"]},"theme_conf":0.99},{"uid":"e49af687-a500-425c-a9cb-0e7816bbb04e","title":"赠翰林张四学士","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["翰林逼华盖，鲸力破沧溟。","天上张公子，宫中汉客星赋诗拾翠殿，佐酒望云亭。","紫诰仍兼绾，黄麻似六经。","内分金带赤，恩与荔枝青。","无复随高凤，空余泣聚萤。","此生任春草，垂老独漂萍。","傥忆山阳会，悲歌在一听。"],"theme":"应制干谒","theme2":["山水田园"],"style":"绮丽","style2":["悲慨"],"mood":"悲怆","mood2":["孤寂"],"scene":["酒","春"],"cats":{"抒情":["伤感","孤独"],"四季":["春天"],"食物":["荔枝"]},"theme_conf":0.78},{"uid":"16aeb267-54a8-4c49-9d94-3306022db14d","title":"东兵长句十韵","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["上党争为天下脊，邯郸四十万秦坑。","狂童何者欲专地，圣主无私岂玩兵。","玄象森罗摇北落，诗人章句咏东征。","雄如马武皆弹劒，少似终军亦请缨。","屈指庙堂无失策，垂衣尧舜待升平。","羽林东下雷霆怒，楚甲南来组练明。","即墨龙文光照曜，常山蛇阵势纵横。","落雕都尉万人敌，黑矟将军一鸟轻。","渐见长围云欲合，可怜穷垒带犹萦。","凯歌应是新年唱，便逐春风浩浩声。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["绮丽"],"mood":"慷慨","mood2":[],"scene":["春"],"cats":{"抒情":["爱国"],"四季":["春天"],"人生":["战争"],"节日":["春节"]},"theme_conf":1.0},{"uid":"d77f340f-1a04-4c5b-9704-2536e4249c6b","title":"野望","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["西山白雪三奇戍，南浦清江万里桥。","海内风尘诸弟隔，天涯涕泪一身遥。","唯将迟暮供多病，未有涓埃荅圣朝。","跨马出郊时极目，不堪人事日萧条。"],"theme":"咏怀抒感","theme2":["边塞征战","送别","闲适隐逸"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["雪","山","江"],"cats":{"抒情":["离别","伤感"],"生活":["写桥"]},"theme_conf":0.84},{"uid":"0145ae39-2773-42f7-9287-ea653ce947a7","title":"过故斛斯校书庄二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["燕入非旁舍，鸥归祗故池。","断桥无复板，卧柳自生枝。","遂有山阳作，多惭鲍叔知。","素交零落尽，白首泪双垂。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["山"],"cats":{"抒情":["伤感","怀古"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":0.617},{"uid":"6ee646bb-07d2-4847-9527-8f90351bbe22","title":"沭阳古渡作","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["日落问津处，云霞残碧空。","牧牛避田烧，退鹢随潮风。","回首故乡远，临流此路穷。","翩翩青冥去，羡彼高飞鸿。"],"theme":"羁旅思乡","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["江"],"cats":{"抒情":["思乡"],"天气":["写云"]},"theme_conf":1.0},{"uid":"bc326cee-2472-4d7d-8c4c-97a590a72ade","title":"官渡柳歌送李员外承恩往扬州觐省","author":"独孤及","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见官渡河两岸，三月杨柳枝。","千条万条色，一一胜绿丝。","花作铅粉絮，叶成翠羽帐。","此时送远人，怅望春水上。","远客折杨柳，依依两含情。","夹郎木兰舟，送郎千里行。","郎把紫泥书，东征觐庭闱。","脱却貂襜褕，新著五彩衣。","双凤幷两翅，将雏东南飞。","五两得便风，几日到扬州。","莫贪扬州好，客行剩淹留。","郎到官渡头，春阑已应久。","殷勤道远别，为谢大堤柳。","攀条傥相忆，五里一回首。","明年柳枝黄，问郎还家否。"],"theme":"送别","theme2":[],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["春","舟"],"cats":{"抒情":["思念"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.702},{"uid":"cpfe0eee546aea6b","title":"八声甘州","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["渺空烟四远，是何年、青天坠长星。","幻苍崖云树，名娃金屋，残霸宫城。","箭径酸风射眼，腻水染花腥。","时靸双鸳响，廊叶秋声。","宫里吴王沈醉，倩五湖倦客，独钓醒醒。","问苍波无语，华发奈山青。","水涵空、阑干高处，送乱鸦、斜日落渔汀。","连呼酒，上琴台去，秋与云平。"],"theme":"咏史怀古","theme2":["闲适隐逸","送别","闺情宫怨"],"style":"豪放","style2":["冲淡"],"mood":"孤寂","mood2":[],"scene":["酒","江","楼","秋"],"cats":{"抒情":["孤独","闺怨","怀古"],"四季":["秋天"]},"theme_conf":0.96},{"uid":"3ff36d5d-66cc-48ce-9c48-924ef008666f","title":"送少微师西行","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["随缘忽西去，何日返东林。","世路宁磋别，空门久息心。","人烟一饭少，山雪独行深。","天外猨啼处，谁闻清梵音。"],"theme":"送别","theme2":[],"style":"旷达","style2":["婉约"],"mood":"孤寂","mood2":[],"scene":["雪","山"],"cats":{"抒情":["孤独"],"山水":["庐山"]},"theme_conf":0.673},{"uid":"3f44618a-ec8e-40e0-bbfd-7cefa27e61d2","title":"杂曲歌辞 凉州词","author":"薛逢","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["昨夜蕃兵报国讐，沙州都护破凉州。","黄河九曲今归汉，塞外纵横战血流。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["豪放"],"mood":"慷慨","mood2":[],"scene":["江","塞外","夜"],"cats":{"抒情":["爱国"],"山水":["黄河"],"人生":["战争"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"07fd04c5-458a-4ba0-80d6-7787739a2627","title":"宫词一百首 七十三","author":"王建","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["殿前铺设两边楼，寒食宫人步打毬。","一半走来争跪拜，上棚先谢得头筹。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["清明","楼"],"cats":{"抒情":["闺怨"],"节日":["寒食节","清明节"]},"theme_conf":0.719},{"uid":"7247095c-ceeb-44e4-91e6-663aa7d504f5","title":"桂州岁暮","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["岁暮天涯客，寒窗欲晓时。","君恩空自感，乡思梦先知。","重谊人愁别，惊栖鹊恋枝。","不堪楼上角，南向海风吹。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["相思","孤寂"],"scene":["月","楼"],"cats":{"抒情":["思乡","伤感"],"人生":["读书"]},"theme_conf":0.676},{"uid":"5a5a657c-624e-44c1-8abd-4318953d1c56","title":"送臯法师","author":"司空曙","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["江草知寒柳半衰，行吟怨别独迟迟。","何人讲席投如意，唯有东林远法师。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":["愁怨"],"scene":["江"],"cats":{"抒情":["孤独"],"山水":["庐山"],"人物":["老师"]},"theme_conf":1.0},{"uid":"1689d325-7e76-4865-862b-6fe65ca9432f","title":"晚次荆江","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["孤舟大江水，水涉无昏曙。","雨暗迷津时，云生望乡处。","渔翁闲自乐，樵客纷多虑。","秋色湖上山，归心日边树。","徒称竹箭美，未得枫林趣。","向夕垂钓还，吾从落潮去。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["恬淡","欢愉"],"scene":["江"],"cats":{"抒情":["思乡","孤独"],"山水":["江河","长江"]},"theme_conf":0.505},{"uid":"0da128ae-3425-4b49-9dd3-1c1cd99e9030","title":"读史","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["鬼书报秦亡，天地亦云闭。","赤龙吟大野，老[母]哭白帝。","苍苍无白日，项氏徒先济。","六合已姓刘，鸿门事难制。","坑降嬴政在，衣锦人望替。","宿昔见汉兵，龙蛇满旌棨。","始矜山可拔，终叹骓不逝。","区区亚父心，未究天人际。","萧张马无汗，盛业垂千世。"],"theme":"咏史怀古","theme2":["亲情"],"style":"幽峭","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":[],"cats":{"抒情":["怀古"],"人物":["母亲"]},"theme_conf":0.98},{"uid":"cp81edf0b8fe51f3","title":"谢金莲诗酒红梨花・感皇恩","author":"张寿卿","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["嬷嬷也老不以筋力为能，咱须是负屈高声。","俺赏的这上阳花，饮的这长寿酒，烧的这短檠灯。","正是银河耿耿，玉器泠泠，对着那一轮月，千里风，满大星。"],"theme":"闲适隐逸","theme2":["咏史怀古"],"style":"绮丽","style2":["豪放"],"mood":"恬淡","mood2":[],"scene":["酒","花"],"cats":{"抒情":["怀古","感恩"],"天气":["星星"],"植物":["梨花","荷花"],"食物":["写酒"]},"theme_conf":0.501},{"uid":"cp211b6898a10092","title":"谢金莲诗酒红梨花・混江龙","author":"张寿卿","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["则在夕阳西下，黄昏啼杀后栖鸦。","看一庭花月，几缕烟霞。","暮雨有情沾杏蕊，春风无处不杨花。","我裙拖翡翠，鞋蹙鸳鸯，行过低矮矮这个荼藤架。","我则见花穿曲径，草接平沙。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["花"],"cats":{"抒情":["爱情","感恩"],"植物":["梨花","荷花"],"食物":["写酒"]},"theme_conf":1.0},{"uid":"22e90c0d-2b59-4500-8e5d-80d38ec4692c","title":"闻官军收河南河北","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["劒外忽传收蓟北，初闻涕泪满衣裳。","却看妻子愁何在，漫卷诗书喜欲狂。","白日放歌须纵酒，青春作伴好还乡。","即从巴峡穿巫峡，便下襄阳向洛阳。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"豪放","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["酒","春"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"人生":["青春","读书"]},"theme_conf":0.512},{"uid":"7ef56b5d-6cad-4297-bae0-712a661e30a2","title":"东都所居寒食下作","author":"陈润","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["江南寒食早，二月杜鹃鸣。","日暖山初绿，春寒雨欲晴。","浴蚕当社日，改火待清明。","更喜瓜田好，令人忆邵平。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":["幽峭"],"mood":"孤寂","mood2":["欢愉","相思"],"scene":["清明"],"cats":{"抒情":["思念"],"节日":["寒食节","清明节"]},"theme_conf":0.92},{"uid":"36f4450b-ab48-4dad-8d98-a1f7ae6c66e9","title":"和武中丞秋日寄怀简诸僚故","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["退朝还公府，骑吹息繁阴。","吏散秋庭寂，乌啼烟树深。","威生奉白简，道胜外华簪。","风物清远目，功名怀寸阴。","云衢念前侣，彩翰写冲襟。","凉菊照幽径，败荷攒碧浔。","感时江海思，报国松筠心。","空愧寿陵步，芳尘何处寻。"],"theme":"寄赠酬答","theme2":["应制干谒"],"style":"冲淡","style2":["清新"],"mood":"慷慨","mood2":["孤寂"],"scene":["秋"],"cats":{"抒情":["爱国"],"四季":["秋天"]},"theme_conf":0.96},{"uid":"02943f6d-2c91-4d9c-9690-247eab9ae3ec","title":"行宫","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["寥落古行宫，宫花寂寞红。","白头宫女在，闲坐说玄宗。"],"theme":"闺情宫怨","theme2":["咏史怀古"],"style":"婉约","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["花"],"cats":{"抒情":["孤独","闺怨","怀古"]},"theme_conf":0.438},{"uid":"e932f96f-0c1b-4526-a14b-420a3368969c","title":"茶亭","author":"朱景玄","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["静得尘埃外，茶芳小华山。","此亭真寂寞，世路少人闲。"],"theme":"闲适隐逸","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":["孤寂"],"scene":["楼"],"cats":{"抒情":["孤独"],"食物":["写茶"]},"theme_conf":0.82},{"uid":"a58dc2b0-7454-4599-aa4c-a06605f39978","title":"相和歌辞 子夜四时歌六首 冬歌二首 一","author":"郭元振","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["北极严气升，南至温风谢。","调丝竞短歌，拂枕怜长夜。"],"theme":"闺情宫怨","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["夜","冬"],"cats":{"抒情":["闺怨"],"四季":["冬天"]},"theme_conf":0.82},{"uid":"0f7504df-cda2-4fe2-bc63-867ec2e418e7","title":"鼓吹曲辞 将进酒","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["君不见黄河之水天上来，奔流到海不复回。","君不见高堂明镜悲白发，朝如青丝暮成雪。","人生得意须尽欢，莫使金尊空对月。","天生我材必有用，千金散尽还复来。","烹羊宰牛且为乐，会须一饮三百杯。","岑夫子，丹丘生，将进酒，杯莫停。","与君歌一曲，请君为我侧耳听。","钟鼓馔玉不足贵，但愿长醉不复醒。","古来圣贤皆寂寞，惟有饮者留其名。","陈王昔时宴平乐，斗酒十千恣欢谑。","主人何为言少钱，径须酤取对君酌。","五花马，千金裘，呼儿将出换美酒，与尔同销万古愁。"],"theme":"咏怀抒感","theme2":["咏物","哲理悟道"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["酒"],"cats":{"抒情":["伤感","孤独"],"山水":["黄河"],"食物":["写酒"]},"theme_conf":0.9},{"uid":"6cf4f8dd-9d3b-4ba0-84e6-109d36a9863e","title":"至日遣兴奉寄北省旧阁老两院故人二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["去岁兹辰捧御床，五更三点入鹓行。","欲知趋走伤心地，正想氛氲满眼香。","无路从容陪语笑，有时颠倒著衣裳。","何人错忆穷愁日，愁日愁随一线长。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["楼","园林"],"cats":{"抒情":["友情","伤感"],"天气":["太阳"]},"theme_conf":0.93},{"uid":"cd904f43-b9eb-4e30-a3fe-f2bcb215a8db","title":"木莲树生巴峡山谷间巴民亦呼为黄心树大者高五丈涉冬不凋身如青杨有白文叶如桂厚大无脊花如莲香色艳腻皆同独房蘂有异四月初始开自开迨谢仅二十日忠州西北十里有鸣玉谿生者秾茂尤异元和十四年夏命道士母丘元志写惜其遐僻因题三绝句云 二","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["红似燕支腻如粉，伤心好物不须臾。","山中风起无时节，明日重来得在无。"],"theme":"山水田园","theme2":["咏物"],"style":"绮丽","style2":["清新","婉约"],"mood":"孤寂","mood2":[],"scene":["月","花","山","冬","夏"],"cats":{"抒情":["孤独","感恩"],"四季":["夏天","冬天"],"天气":["太阳","月亮"],"人生":["梦想"],"植物":["荷花","叶子"]},"theme_conf":0.446},{"uid":"cd3d8e0c-a549-44a9-b55c-4f1c9b9befed","title":"秋霖中奉裴令公见招早出赴会马上先寄六韵","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["雨暗三秋日，泥深一尺时。","老人平旦出，自问欲何之。","不是寻医药，非干送别离。","素书传好语，绛帐赴佳期。","续借桃花马，催迎杨柳姬。","只愁张录事，罚我怪来迟。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":["秋","雨"],"cats":{"抒情":["离别","伤感"],"四季":["秋天"],"天气":["写雨"],"人物":["老师"],"动物":["写马"]},"theme_conf":0.88},{"uid":"538c200b-49c5-4487-8087-9736b2947053","title":"楚怨","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋入楚江水，独照汨罗魂。","手把绿荷泣，意愁珠泪翻。","九门不可入，一犬吠千门。"],"theme":"闺情宫怨","theme2":[],"style":"沉郁","style2":["绮丽","清新"],"mood":"愁怨","mood2":[],"scene":["端午","秋","江"],"cats":{"抒情":["伤感","闺怨"],"四季":["秋天"],"节日":["端午节"]},"theme_conf":1.0},{"uid":"f7961f8c-6bd0-4a4d-89f8-0a10ba3f77b9","title":"谢严中丞送青城山道士乳酒一瓶","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["山瓶乳酒下青云，气味浓香幸见分。","鸣鞭走送怜渔父，洗盏开尝对马军。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["酒","山"],"cats":{"抒情":["感恩"],"食物":["写酒"]},"theme_conf":0.445},{"uid":"9bd49546-5289-4351-97f4-d69296720dfc","title":"江南词","author":"李益","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["嫁得瞿塘贾，朝朝悮妾期。","早知潮有信，嫁与弄潮儿。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["江南","江"],"cats":{"抒情":["闺怨"]},"theme_conf":1.0},{"uid":"ee1af307-1e4b-4b18-a2d9-1194784cae0a","title":"寄张仲甫","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["悲风生旧浦，云岭隔东田。","伏腊同鸡黍，柴门闭雪天。","孤村明夜火，稚子候归船。","静者心相忆，离居畏度年。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["孤寂","恬淡"],"scene":["雪","夜","舟"],"cats":{"抒情":["伤感","孤独"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.94},{"uid":"7c0b2801-38db-4c5a-95c1-9a8f1a65a1b9","title":"游石堂观","author":"萧祜","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["西山高高何所如，上有古昔真人居。","嵚崖巨石自成室，其下磅礴含清虚。","我来斯邑访遗迹，乃遇沈生躭载籍。","沈生为政哀惸[嫠]，又能索隐探灵奇。","欣然向我话佳境，与我崎岖到山顶。","甘瓜剖绿出寒泉，碧瓯浮花酌春茗。","嚼瓜啜茗身清凉，汗消𫄨绤如迎霜。","胡为空山百草花，倏尔笾豆肆我旁。","始惊知周无小大，力寡多方验斯在。","妙用腾声冠盖间，胜游恣意烟霞外。","故碑石像凡几年，云郁雨霏生绿烟。","我知游此多灵仙，缥缈月中飞下天。","天风微微夕露委，松梢飕飕晓声起。","凤去空遗箫管音，星翻寥落银河水。","劝君学道此时来，结茅独宿何辽哉。","斋心玄默感灵卫，必见鸾鹤相裴回。","我爱崇山双劒北，峰如人首拄天黑。","群仙伛偻势奔走，壮若归尊趋有德。","半岩有洞顶有池，出入灵怪潜蛟螭。","我去不得昼夜思，梦游曾信南风吹。","南风吹我到林岭，故国不见秦天逈。","山花名药扑地香，月色泉声洞心冷。","荫松散发逢异人，寂寞旷然口不言。","道陵公远莫能识，发短耳长谁独存。","司农惊觉忽惆怅，可惜所游俱是妄。","蕴怀耿耿谁与言，直至今来意通形神开。","拥传又恨斜阳催，一丘人境尚堪恋，何况海上金银台。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["山","月"],"cats":{"抒情":["孤独","怀古"],"天气":["月亮","星星"]},"theme_conf":0.517},{"uid":"517b0595-b7cd-41dc-9ee7-b8b4a9a2f076","title":"辞辇行","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["汉家代久淳风薄，帝重微行极荒乐。","青娥三千奉一人，班女不以色事君。","朝停玉辇诏同载，三十六宫皆眄睐。","不惊六马缓天仪，从容鸣环前致辞。","君恩如海深难竭，妾命如丝轻易绝。","愿陪阿[母]同小星，敢使太阳齐万物。","周末幽王不可宗，妾闻上圣遗休风。","五更三老待白日，八十一女居深宫。","愿将辇内有余席，回赐忠臣妾恩泽。"],"theme":"闺情宫怨","theme2":["羁旅思乡"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["思乡","闺怨"],"人物":["母亲"]},"theme_conf":0.609},{"uid":"f40cb6c3-66e9-4a83-a497-124d085ed298","title":"杂曲歌辞 缓歌行","author":"李颀","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["小来托身攀贵游，倾财破产无所忧。","暮拟经过石渠署，朝将出入铜龙楼。","结交杜陵轻薄子，谓言可生复可死。","一沈一浮会有时，弃我翻然如脱屣。","男儿立身须自彊，十五闭户颍水阳。","业就功成见明主，击钟鼎食坐华堂。","二八蛾眉梳堕马，美酒清歌曲房下。","文昌宫中赐锦衣，长安陌上退朝归。","五侯宾从莫敢视，三省官僚揖者稀。","早知今日读书是，悔作从来任侠非。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["酒"],"cats":{"抒情":["思乡"],"人生":["读书"]},"theme_conf":1.0},{"uid":"2deab82a-0a07-4848-85e1-f77dc21495d8","title":"赠赵将军","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["当年胆略已纵横，每见妖星气不平。","身贵早登龙尾道，功高自破鹿头城。","寻常得对论边事，委曲承恩掌内兵。","会取安西将报国，凌烟阁上大书名。"],"theme":"边塞征战","theme2":["送别"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["楼"],"cats":{"抒情":["爱国"]},"theme_conf":0.595},{"uid":"cpb21db1402576f8","title":"西河","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["佳丽地。","南朝盛事谁记。","山围故国绕清江，髻鬟对起。","怒涛寂寞打孤城，风樯遥度天际。","断崖树，犹倒倚。","莫愁艇子曾系。","空馀旧迹郁苍苍，雾沈半垒。","夜深月过女墙来，赏心东望淮水。","酒旗戏鼓甚处市。","想依稀、王谢邻里。","燕子不知何世。","入寻常、巷陌人家，相对如说兴亡，斜阳里。"],"theme":"咏史怀古","theme2":[],"style":"冲淡","style2":["沉郁","清新"],"mood":"孤寂","mood2":[],"scene":["酒","夜","月"],"cats":{"抒情":["孤独","怀古"],"山水":["江河"]},"theme_conf":0.741},{"uid":"b42b8d7b-3d04-46ed-ba87-11478e25d391","title":"送刘评事充朔方判官赋得征马嘶","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["征马向边州，萧萧嘶不休。","思深应带别，声断为兼秋。","岐路风将远，关山月共愁。","赠君从此去，何日大刀头。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["秋","月","塞外","山"],"cats":{"抒情":["思念","伤感"],"四季":["秋天"],"动物":["写马"]},"theme_conf":0.479},{"uid":"8b282727-8bff-446e-8add-a32cfba7671d","title":"和令狐相公玩白菊","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["家家菊尽黄，梁国独如霜。","莹静真琪树，分明对玉堂。","仙人披雪氅，素女不红妆。","粉蝶来难见，麻衣拂更香。","向风摇羽扇，含露滴琼桨。","高艳遮银井，繁枝覆象床。","桂丛慙竝发，梅蘂妬先芳。","一入瑶华咏，从兹播乐章。"],"theme":"咏物","theme2":[],"style":"冲淡","style2":["绮丽"],"mood":"孤寂","mood2":["恬淡","欢愉"],"scene":["雪","重阳","花"],"cats":{"抒情":["孤独"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.96},{"uid":"c9e63635-0caa-43c2-b4b8-b459f9983fbf","title":"送高三十五书记","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["崆峒小麦熟，且愿休王师。","请公问主将，焉用穷荒为。","饥鹰未饱肉，侧翅随人飞。","高生跨鞍马，有似幽幷儿。","脱身簿尉中，始与捶楚辞。","借问今何官，触热向武威。","答云一书记，所媿国士知。","人实不易知，更须慎其仪。","十年出幕府，自可持旌麾。","此行既特达，足以慰所思。","男儿功名遂，亦在老大时。","常恨结驩浅，各在天一涯。","又如参与商，惨惨中肠悲。","惊风吹鸿鹄，不得相追随。","黄尘翳沙漠，念子何当归。","边城有余力，早寄从军诗。"],"theme":"送别","theme2":[],"style":"旷达","style2":["沉郁"],"mood":"悲怆","mood2":["相思","愁怨"],"scene":["塞外"],"cats":{"抒情":["伤感"],"人生":["梦想"]},"theme_conf":0.587},{"uid":"c8284ada-18a4-46ad-8a47-c2b0c02204ff","title":"过柳州","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["地尽江南戍，山分桂北林。","火云三月合，石路九疑深。","暗谷随风过，危桥共鸟寻。","羁魂愁似绝，不复待猨吟。"],"theme":"羁旅思乡","theme2":["山水田园","边塞征战","羁旅思乡"],"style":"悲慨","style2":[],"mood":"愁怨","mood2":[],"scene":["月","江南","江","山"],"cats":{"抒情":["思乡","伤感"],"生活":["写桥"],"植物":["柳树"]},"theme_conf":0.93},{"uid":"3f27da66-1e73-4bee-91a4-9de2d9545fc2","title":"相和歌辞 采莲曲","author":"徐彦伯","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["妾家越水边，摇艇入江烟。","既觅同心侣，复采同心莲。","折藕丝能脆，开花叶正圆。","春歌弄明月，归棹落花前。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["月"],"cats":{"抒情":["爱情"],"天气":["月亮"],"植物":["荷花"]},"theme_conf":0.713},{"uid":"7ac0a7d0-2347-4647-8165-9dca1bef2530","title":"鲜于少府宅看花","author":"李端","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["谢家能植药，万簇相萦倚。","烂熳绿苔前，婵娟青草里。","垂栏复照户，映竹仍临水。","骤雨发芳香，回风舒锦绮。","孤光杂新故，众色更重累。","散碧出疎茎，分黄成细蘂。","游蜂高更下，惊蝶坐还起。","玉貌对应慙，霞标方不似。","春阴怜弱蔓，夏日同短晷。","回落报荣衰，交关鬬红紫。","花时苟未赏，老至谁能止。","上客屡移床，幽僧劳凭几。","初合虽薄劣，却得陪君子。","敢问贤主人，何如种桃李。"],"theme":"咏物","theme2":["羁旅思乡","山水田园"],"style":"绮丽","style2":["婉约"],"mood":"孤寂","mood2":[],"scene":["花"],"cats":{"抒情":["思乡","孤独"],"天气":["写雨"],"节日":["中秋节"]},"theme_conf":0.84},{"uid":"cp62f4acdb0a97af","title":"宴清都","author":"卢祖皋","dynasty":"宋","section":"宋词","form":"词","paragraphs":["春讯飞琼管。","风日薄、度墙啼鸟声乱。","江城次第，笙歌翠合，绮罗香暖。","溶溶涧渌冰泮。","醉梦里、年华暗换。","料黛眉重锁隋堤，芳心还动梁苑。","新来雁阔云音，鸾分槛影，无计重见。","啼春细雨，笼愁澹月，恁时庭院。","离肠未语先断。","算犹有、凭高望眼。","更那堪、芳草连天，飞梅弄晚。"],"theme":"山水田园","theme2":["闺情宫怨"],"style":"绮丽","style2":["清新","婉约"],"mood":"欢愉","mood2":["愁怨","恬淡"],"scene":["园林","雨","鸟","冬"],"cats":{"抒情":["伤感","闺怨"],"天气":["写雨"]},"theme_conf":0.509},{"uid":"0ee73c58-cce4-4852-b95b-73ce2d12618e","title":"过宣上人湖上兰若","author":"朱湾","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["十年湖上结幽期，偏向东林遇远师。","未道姓名童子识，不酬言语上人知。","闲花落日滋苔径，细雨和烟著柳枝。","问我别来何所得，解将无事当无为。"],"theme":"佛道禅颂","theme2":["闲适隐逸","山水田园","咏史怀古"],"style":"婉约","style2":[],"mood":"恬淡","mood2":[],"scene":["江","雨"],"cats":{"抒情":["怀古"],"山水":["庐山"],"天气":["写雨"]},"theme_conf":0.82},{"uid":"e6bf25ce-19e9-4316-bd35-cdc6bb050c61","title":"奉酬卢给事云夫四兄曲江荷花行见寄幷呈上钱七兄阁老张十八助教","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["曲江千顷秋波净，平铺红云盖明镜。","大明宫中给事归，走马来看立不正。","遗我明珠九十六，寒光映骨睡骊目。","我今官闲得婆娑，问言何处芙蓉多。","撑舟昆明度云锦，脚敲两舷呌吴歌。","太白山高三百里，负雪崔嵬插花里。","玉山前却不复来，曲江汀滢水平杯。","我时相思不觉一回首，天门九扇相当开。","上界真人足官府，岂如散仙鞭笞鸾凤终日相追陪。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["江","花","山"],"cats":{"抒情":["思念"],"山水":["江河"],"天气":["写云"],"植物":["荷花"]},"theme_conf":0.95},{"uid":"b96a1832-961d-48f5-9004-7ea944e8c071","title":"代琵琶弟子谢女师曹供奉寄新调弄谱","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["琵琶师在九重城，忽得书来喜且惊。","一纸展看非旧谱，四弦翻出是新声。","蕤宾掩抑娇多怨，散水玲珑峭更清。","珠颗泪沾金捍拨，红妆弟子不胜情。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":["清新","幽峭"],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["伤感","感恩"],"人物":["老师"]},"theme_conf":0.769},{"uid":"923e2f27-fc95-4649-9442-1aeeb083da91","title":"湘中","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["猿愁鱼踊水翻波，自古流传是汨罗。","苹藻满盘无处奠，空闻渔父扣舷歌。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"愁怨","mood2":[],"scene":["端午"],"cats":{"抒情":["伤感"],"节日":["端午节"]},"theme_conf":1.0},{"uid":"8877c330-ce31-4a0b-a939-33b21e56b422","title":"行不由径","author":"俞简","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["古人心有尚，乃是孔门生。","为计安贫乐，当从大道行。","讵应流远迹，方欲料前程。","捷径虽云易，长衢岂不平。","后来无枉路，先达擅前名。","一示遵途意，微衷益自精。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"人物":["老师"]},"theme_conf":1.0},{"uid":"526d4ecc-e123-4b9d-a213-958bb947593d","title":"凉州词二首 一","author":"王之涣","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["黄河远上白云间，一片孤城万仞山。","羌笛何须怨杨柳，春光不度玉门关。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["江","春","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"山水":["黄河"],"生活":["边塞"]},"theme_conf":0.508},{"uid":"d09d57f9-e7ee-4088-8cf0-06423f1dede0","title":"四皓驿听琴送王师简归湖南使幕","author":"窦庠","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["朱弦韵正调，清夜似闻韶。","山馆月犹在，松枝雪未消。","城笳三奏晓，别鹤一声遥。","明日思君处，春泉翻寂寥。"],"theme":"送别","theme2":["送别"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["江","雪","春","夜","月","山"],"cats":{"抒情":["爱国"],"四季":["春天"]},"theme_conf":0.95},{"uid":"7ecd869d-dd96-421b-905b-a70a0cb44bad","title":"琴曲歌辞 秋风引","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["何处秋风至？萧萧送鴈群。","朝来入庭树，孤客最先闻。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"天气":["写风"]},"theme_conf":0.402},{"uid":"8baf651c-c608-4795-9260-c572c4af580b","title":"杂曲歌辞 少年行三首 三","author":"李嶷","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["玉劒膝边横，金杯马上倾。","朝游茂陵道，暮宿凤凰城。","豪吏多猜忌，无劳问姓名。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["酒"],"cats":{"抒情":["思乡"],"人生":["青春"]},"theme_conf":0.65},{"uid":"f55da3dd-e810-4e90-b065-acb1459bf7c5","title":"踏歌行 一","author":"陈去疾","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["鸳鸯楼下万花新，翡翠宫前百戏陈。","夭矫翔龙衔火树，飞来瑞凤散芳春。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["元宵","花","春","楼"],"cats":{"抒情":["爱情"],"四季":["春天"],"节日":["元宵节"]},"theme_conf":1.0},{"uid":"7bc83be6-9f75-4612-af7d-f4fa66548049","title":"去杭州","author":"元稹","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["房杜王魏之子孙，虽及百代为清门。","骏骨凤毛真可贵，冈头泽底何足论。","去年江上识君面，爱君风貌情已敦。","与君言语见君性，灵府坦荡消尘烦。","自兹心洽迹亦洽，居常并榻游竝轩。","柳阴覆岸郑监水，李花压树韦公园。","每出新诗共联缀，闲因醉舞相牵援。","时寻沙尾枫林夕，夜摘兰丛衣露繁。","今君别我欲何去，自言远结迢迢婚。","简书五府已再至，波涛万里酬一言。","为君再拜赠君语，愿君静听君勿喧。","君名师范欲何范，君之烈祖遗范存。","永宁昔在抡鉴表，沙汰沈浊澄浚源。","君今取友由取士，得不别白清与浑。","昔公事主尽忠谠，虽及死谏誓不谖。","今君佐藩如佐主，得不陈露詶所恩。","昔公为善日不足，假寐待旦朝至尊。","今君三十朝未与，得不寸晷倍玙璠。","昔公令子尚贵主，公执舅礼妇执笲。","返拜之仪自此绝，关雎之化皎不昏。","君今远娉奉明祀，得不齐励亲苹蘩。","斯言皆为书佩带，然后别袂乃可扪。","别袂可扪不可解，解袂开帆凄别魂。","魂摇江树鸟飞没，帆挂樯竿鸟尾翻。","翻风驾浪拍何处，直指杭州由上元。","上元萧寺基址在，杭州潮水霜雪屯。","潮户迎潮击潮鼓，潮平潮退有潮痕。","得得为题罗刹石，古来非独伍员冤。"],"theme":"送别","theme2":[],"style":"清新","style2":["豪放"],"mood":"恬淡","mood2":["慷慨"],"scene":["江","元宵","秋"],"cats":{"抒情":["离别"],"四季":["秋天"],"节日":["元宵节"]},"theme_conf":0.603},{"uid":"e2fec465-cea1-4829-b12d-3ba37a267562","title":"同从弟销南斋玩月忆山阴崔少府","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["高卧南斋时，开帷月初吐。","清辉淡水木，演漾在窗户。","苒苒几盈虚，澄澄变今古。","美人清江畔，是夜越吟苦。","千里其如何，微风吹兰杜。"],"theme":"送别","theme2":["山水田园"],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["月"],"cats":{"抒情":["思念"],"天气":["月亮"],"人物":["女子"]},"theme_conf":0.503},{"uid":"94ae3e7e-eb5d-414c-bfd6-124f50687ce5","title":"客夜与故人偶集","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["天秋月又满，城阙夜千重。","还作江南会，翻疑梦里逢。","风枝惊暗鹊，露草覆寒蛩。","羁旅长堪醉，相留畏晓钟。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["秋","夜"],"cats":{"抒情":["友情","思乡"],"四季":["秋天"]},"theme_conf":0.649},{"uid":"5043109d-30c1-4c03-a6b5-c04c46051954","title":"相和歌辞 苦辛行","author":"戎昱","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["且莫奏短歌，听余苦辛词。","如今刀笔士，不及屠酤儿。","少年无事学诗赋，岂意文章复相误。","东西南北少知音，终年竟岁悲行路。","仰面诉天天不闻，低头告地地不言。","天地生我尚如此，陌上他人何足论。","谁谓西江深，涉之固无忧。","谁谓南山高，可以登之游。","险巇惟有世间路，一向令人堪白头。","贵人立意不可测，等闲桃李成荆棘。","风尘之士深可亲，心如鸡犬能依人。","悲来却忆汉天子，不弃相如家旧贫。","饮酒酒能散羇愁，谁家有酒判一醉，万事从他江水流。"],"theme":"咏怀抒感","theme2":["民生疾苦","羁旅思乡"],"style":"豪放","style2":["沉郁","悲慨"],"mood":"愁怨","mood2":[],"scene":["酒"],"cats":{"抒情":["友情","思乡","伤感"]},"theme_conf":0.67},{"uid":"8f3bd134-ac28-4961-b0c9-141140f72e47","title":"横吹曲辞 折杨柳 二","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["楼上春风过，风前杨柳歌。","枝疎缘别苦，曲怨为年多。","花惊燕地雪，叶映楚池波。","谁堪别离此，征戍在交河。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["雪","春","楼"],"cats":{"抒情":["离别"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.664},{"uid":"9deee86d-3d16-40f1-aff9-f8805c75d827","title":"送王正字山寺读书","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["欲究先儒教，还过支遁居。","山堦闲听法，竹迳独看书。","向日荷新卷，迎秋柳半疎。","风流有佳句，不似带经锄。"],"theme":"送别","theme2":["山水田园"],"style":"清新","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["山"],"cats":{"抒情":["孤独"],"人生":["读书"],"生活":["田野"]},"theme_conf":0.418},{"uid":"cp8d127e60c3623a","title":"生查子","author":"王观","dynasty":"宋","section":"宋词","form":"词","paragraphs":["关山魂梦长，塞雁音书少。","两鬓可怜青，一夜相思老。","归傍碧纱窗，说与人人道。","真个别离难，不似相逢好。"],"theme":"爱情相思","theme2":["羁旅思乡","边塞征战","爱情相思"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["塞外"],"cats":{"抒情":["爱情","离别","思念","思乡"],"生活":["边塞"]},"theme_conf":0.82},{"uid":"fb3ddaff-b685-4259-b956-5cf875608319","title":"又酬晓灯[离暗]室五首 五","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["雨声乱灯影，明灭在空堦。","并枉五言赠，知同万里怀。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":["豪放"],"mood":"惆怅","mood2":[],"scene":["元宵","夜"],"cats":{"抒情":["离别"],"节日":["元宵节"]},"theme_conf":0.91},{"uid":"471d5abe-d0cf-4dd2-a94b-ab5552be07d9","title":"元日示宗武","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["汝啼吾手战，吾笑汝身长。","处处逢正月，迢迢滞远方。","飘零还柏酒，衰病只藜床。","训喻青衿子，名慙白首郎。","赋诗犹落笔，献寿更称觞。","不见江东弟，高歌泪数行。"],"theme":"亲情","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["酒"],"cats":{"抒情":["伤感"],"节日":["春节"]},"theme_conf":0.9},{"uid":"5f5d9f3e-a3d3-446a-ba9c-3066f4b6eff9","title":"杂曲歌辞 少年行四首 四","author":"令狐楚","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["霜满中庭月过楼，金尊玉柱对清秋。","当年称意须为乐，不到天明未肯休。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"人生":["青春"]},"theme_conf":0.65},{"uid":"cp2e2a1c2fd58b4f","title":"喜迁莺","author":"刘一止","dynasty":"宋","section":"宋词","form":"词","paragraphs":["晓光催角。","听宿鸟未惊，邻鸡先觉。","迤逦烟村，马嘶人起，残月尚穿林薄。","泪痕带霜微凝，酒力冲寒犹弱。","叹倦客、悄不禁，重染风尘京洛。","追念，人别后，心事万重，难觅孤鸿托。","翠幌娇深，曲屏香暖，争念岁寒飘泊。","怨月恨花烦恼，不是不曾经著。","这情味，望一成消减，新来还恶。"],"theme":"山水田园","theme2":["送别"],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":["欢愉"],"scene":["鸟","春"],"cats":{"抒情":["伤感"],"四季":["春天"],"动物":["写鸟"]},"theme_conf":0.5},{"uid":"b6475dea-1d69-4f0d-b98a-39393f47741e","title":"无题二首 二","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["重帷深下莫愁堂，卧后清宵细细长。","神女生涯原是梦，小姑居处本无郎。","风波不信菱枝弱，月露谁教桂叶香。","直道相思了无益，未妨惆怅是清狂。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":["清新","豪放"],"mood":"相思","mood2":[],"scene":["月","夜"],"cats":{"抒情":["爱情","思念"]},"theme_conf":1.0},{"uid":"05d0c667-b634-4962-8141-6a0cd84f56be","title":"一叶落","author":"薛能","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["轻叶独悠悠，天高片影流。","随风来此地，何树落先秋。","变色黄应近，辞林绿尚稠。","无双浮水面，孤绝落关头。","乍减诚难觉，将凋势未休。","客心空自比，谁肯问新愁。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["清新","旷达"],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"92786fed-bd1f-4b19-bbe1-145d5120f253","title":"送温况游蜀","author":"武元衡","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["游人西去客三巴，身逐孤蓬不定家。","山近峨眉飞暮雨，江连濯锦起朝霞。","云深九折刀州远，路绕千岩剑阁斜。","应到严君开卦处，将余一为问生涯。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["绮丽"],"mood":"孤寂","mood2":[],"scene":["山","雨"],"cats":{"抒情":["孤独"],"人物":["父亲"]},"theme_conf":0.501},{"uid":"6d3b137e-8d62-4d8d-be0f-88c9589f8ae6","title":"野老","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["野老篱前江岸回，柴门不正逐江开。","渔人网集澄潭下，贾客船随返照来。","长路关心悲劒阁，片云何意傍琴台。","王师未报收东郡，城阙秋生画角哀。"],"theme":"咏怀抒感","theme2":["山水田园"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["楼","秋","江","舟"],"cats":{"抒情":["伤感"],"四季":["秋天"],"生活":["乡村"]},"theme_conf":0.7},{"uid":"02feeee3-8ca8-43eb-9e53-507cd7b9a960","title":"自淇涉黄河途中作十三首 一","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["川上常极目，世情今已闲。","去帆带落日，征路随长山。","亲友若云霄，可望不可攀。","于兹任所惬，浩荡风波间。"],"theme":"羁旅思乡","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江","舟","山"],"cats":{"抒情":["思乡"],"山水":["黄河"]},"theme_conf":0.86},{"uid":"f9798830-48c1-45e3-be90-4028d93954dc","title":"感遇十二首 四","author":"张九龄","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["孤鸿海上来，池潢不敢顾。","侧见双翠鸟，巢在三珠树。","矫矫珍木巅，得无金丸惧。","美服患人指，高明逼神恶。","今我游冥冥，弋者何所慕。"],"theme":"哲理悟道","theme2":["山水田园"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":[],"cats":{"抒情":["孤独"]},"theme_conf":0.588},{"uid":"b1dad78c-4dd8-4b99-b37b-741ed761f26a","title":"宿桐庐江寄广陵旧游","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["山暝闻猿愁，沧江急夜流。","风鸣两岸叶，月照一孤舟。","建德非吾土，维扬忆旧游。","还将两行泪，遥寄海西头。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["江"],"cats":{"抒情":["思念","思乡","伤感"],"山水":["江河"]},"theme_conf":0.78},{"uid":"b9a7a335-e9cc-4737-bfe8-ebb2775baabf","title":"霓裳羽衣歌","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["我昔元和侍宪皇，曾陪内宴宴昭阳。","千歌百舞不可数，就中最爱霓裳舞。","舞时寒食春风天，玉钩栏下香案前。","案前舞者颜如玉，不著人家俗衣服。","虹裳霞帔步摇冠，钿璎累累佩珊珊。","娉婷似不任罗绮，顾听乐悬行复止。","磬箫筝笛遰相搀，击𢬍弹吹声逦迤。","散序六奏未动衣，阳台宿云慵不飞。","中序擘𬴃初入拍，秋竹竿裂春冰拆。","飘然转旋回雪轻，嫣然纵送游龙惊。","小垂手后柳无力，斜曳裾时云欲生。","烟蛾歛略不胜态，风袖低昂如有情。","上元点鬟招萼绿，王母挥袂别飞琼。","繁音急节十二徧，跳珠撼玉何铿铮。","翔鸾舞了却收翅，唳鹤曲终长引声。","当时乍见惊心目，凝视谛听殊未足。","一落人间八九年，耳冷不曾闻此曲。","湓城但听山魈语，巴峡唯闻杜鹃哭。","移领钱唐第二年，始有心情问丝竹。","玲珑箜篌谢好筝，陈宠觱栗沈平笙。","清弦脆管纤纤手，教得霓裳一曲成。","虚白亭前湖水畔，前后祗应三度按。","便除庶子抛却来，闻道如今各星散。","今年五月至苏州，朝钟暮角催白头。","贪看案牍常侵夜，不听笙歌直到秋。","秋来无事多闲闷，忽忆霓裳无处问。","闻君部内多乐徒，问有霓裳舞者无。","荅云七县十万户，无人知有霓裳舞。","唯寄长歌与我来，题作霓裳羽衣谱。","四幅花牋碧间红，霓裳实录在其中。","千姿万状分明见，恰与[昭]阳舞者同。","眼前髣髴覩形质，昔日今朝想如一。","疑从魂梦呼召来，似著丹青图写出。","我爱霓裳君合知，发于歌咏形于诗。","君不见我歌云，惊破霓裳羽衣曲。","又不见我诗云，曲爱霓裳未拍时。","由来能事皆有主，杨氏创声君造谱。","君言此舞难得人，须是倾城可怜女。","吴妖小玉飞作烟，越艳西施化为土。","娇花巧笑久寂寥，娃馆苎萝空处所。","如君所言诚有是，君试从容听我语。","若求国色始翻传，但恐人间废此舞。","妍媸优劣宁相远，大都只在人擡举。","李娟张态君莫嫌，亦拟随宜且教取。"],"theme":"送别","theme2":["节令风俗","题画咏艺"],"style":"绮丽","style2":["沉郁"],"mood":"孤寂","mood2":["欢愉","相思"],"scene":["花","江南","雪","清明","元宵","鸟"],"cats":{"抒情":["思念","孤独","闺怨"],"节日":["元宵节","寒食节","清明节"]},"theme_conf":0.366},{"uid":"1422a3b8-f6db-44e5-a842-3a1c44359b59","title":"过天门山怀友","author":"吴筠","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["举帆遇风劲，逸势如飞奔。","缥缈凌烟波，崩腾走川原。","两山夹沧江，豁尔开天门。","须臾轻舟远，想象孤屿存。","归路日已近，怡然慰心魂。","所经多奇趣，待与吾友论。","一日如三秋，相思意弥敦。"],"theme":"咏史怀古","theme2":["爱情相思","山水田园"],"style":"悲慨","style2":[],"mood":"相思","mood2":[],"scene":["山","舟","江"],"cats":{"抒情":["爱情","友情","思念","怀古"],"山水":["泰山"]},"theme_conf":0.371},{"uid":"db9d91d8-9d41-4922-82a7-1c8d23f66238","title":"秋夜梁七兵曹同宿二首 二","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["好欲弃吾道，今宵又遇君。","老夫相劝酒，稚子待题文。","月下谁家笛，城头几片云。","如何此幽兴，明日重离群。"],"theme":"寄赠酬答","theme2":["亲情","边塞征战","羁旅思乡"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["夜","秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"人物":["儿童"],"人生":["战争"]},"theme_conf":0.6},{"uid":"79462191-3bcb-4599-b51b-40bcf4d3065d","title":"杂曲歌辞 结客少年场行","author":"虞羽客","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["幽幷侠少年，金络控连钱。","窃符方救赵，击筑正怀燕。","轻生辞凤阙，挥袂上祁连。","陆离横宝劒，出没惊徂旃。","蒙轮恒顾敌，超乘忽争先。","摧枯逾百战，拓地远三千。","骨都魂已散，楼兰首复传。","龙城含晓雾，瀚海隔遥天。","歌吹金微返，振旅玉门旋。","烽火今已息，非复照甘泉。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"绮丽","style2":["婉约","清新"],"mood":"欢愉","mood2":[],"scene":["楼"],"cats":{"抒情":["思乡"],"人生":["青春","战争"],"生活":["边塞"]},"theme_conf":0.565},{"uid":"cp5be9581b63edc2","title":"锁窗寒・琐寒窗","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["暗柳啼鸦，单衣伫立，小帘朱户。","桐花半亩，静锁一庭愁雨。","洒空阶，夜阑未休，故人剪烛西窗语。","似楚江暝宿，风灯零乱，少年羁旅。","迟暮。","嬉游处。","正店舍无烟，禁城百五。","旗亭唤酒，付与高阳俦侣。","想东园，桃李自春，小唇秀靥今在否。","到归时，定有残英，待客携尊俎。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["园林","春","夜","酒","雨"],"cats":{"抒情":["思乡"],"四季":["春天"],"人生":["读书"]},"theme_conf":1.0},{"uid":"ed0d4f1c-f300-48b1-8139-706fb3a1aa2c","title":"横吹曲辞 出关","author":"魏征","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["中原还逐鹿，投笔事戎轩。","纵横计不就，慷慨志犹存。","策杖谒天子，驱马出关门。","请缨羁南越，凭轼下东藩。","郁纡陟高岫，出没望平原。","古木吟寒鸟，空山啼夜猨。","既伤千里目，还惊九折魂。","岂不惮艰险，深怀国士恩。","季布无二诺，侯嬴重一言。","人生感意气，功名谁复论。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":["豪放"],"mood":"慷慨","mood2":[],"scene":["山"],"cats":{"抒情":["爱国"]},"theme_conf":0.496},{"uid":"a68013c8-4630-41c6-a5ee-a658b57f58fe","title":"淮上喜会梁川故人","author":"韦应物","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["江汉曾为客，相逢每醉还。","浮云一别后，流水十年间。","欢笑情如旧，萧疎鬓已斑。","何因北归去，淮上对秋山。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["秋","江","酒","山"],"cats":{"抒情":["友情"],"四季":["秋天"]},"theme_conf":0.78},{"uid":"09366fe4-04f9-4665-abc0-810b9a9c6720","title":"投简成华两县诸子","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["赤县官曹拥材杰，软裘快马当冰雪。","长安苦寒谁独悲，杜陵野老骨欲折。","南山豆苗早荒秽，青门瓜地新冻裂。","乡里儿童项领成，朝廷故旧礼数绝。","自然弃掷与时异，况乃疎顽临事拙。","饥卧动即向一旬，敝裘何啻联百结。","君不见空墙日色晚，此老无声泪垂血。"],"theme":"民生疾苦","theme2":[],"style":"沉郁","style2":["冲淡"],"mood":"孤寂","mood2":["愁怨","悲怆"],"scene":["冬","雪"],"cats":{"抒情":["伤感","孤独"],"天气":["写雪"],"人物":["儿童"]},"theme_conf":0.73},{"uid":"3e457b1c-8c36-46fe-bca9-14cf644ec9ca","title":"相和歌辞 蒿里","author":"僧贯休","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["兔不迟，乌更急，但恐穆王八骏，著鞭不及。","所以蒿里，坟出蕺蕺，气凌云天，龙腾凤集，尽为风消土吃，狐掇蚁拾。","黄金不啼玉不泣，白杨骚屑。","乱风愁月，折碑石人。","莽秽榛没，牛羊窸窣。","时见牧童儿，弄枯骨。"],"theme":"悼亡挽歌","theme2":[],"style":"绮丽","style2":["豪放"],"mood":"愁怨","mood2":["悲怆"],"scene":["月"],"cats":{"抒情":["伤感","悼亡"],"人物":["儿童"]},"theme_conf":0.98},{"uid":"6df38a77-6e5d-43ae-a115-7de36475f53e","title":"感遇十二首 二","author":"张九龄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["幽林归独卧，滞虑洗孤清。","持此谢高鸟，因之传远情。","日夕怀空意，人谁感至精。","飞沈理自隔，何所慰吾诚。"],"theme":"哲理悟道","theme2":["山水田园","讽喻刺世"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":[],"cats":{"抒情":["孤独"]},"theme_conf":0.375},{"uid":"a9c84c93-6f83-4456-80d8-8b7fe5e427a2","title":"江上曲","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["江心澹澹芙蓉花，江口蛾眉独浣纱。","可怜应是阳台女，对坐鹭鸶娇不语。","掩面羞看北地人，回身忽作空山语。","苍梧秋色不堪论，千载依依帝子魂。","君看峰上斑斑竹，尽是湘妃泣泪痕。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":["婉约"],"mood":"孤寂","mood2":["恬淡","悲怆"],"scene":["江","山"],"cats":{"抒情":["伤感","孤独"],"山水":["江河"]},"theme_conf":1.0},{"uid":"49255a86-1217-48f7-b480-0f562a4dcf91","title":"远怀舍弟颖观等","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["阳翟空知处，荆南近得书。","积年仍远别，多难不安居。","江汉春风起，冰霜昨夜除。","云天犹错莫，花萼尚萧疎。","对酒都疑梦，吟诗正忆渠。","旧时元日会，乡党羡吾庐。"],"theme":"羁旅思乡","theme2":["节令风俗","送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["花","春","酒","夜","江","冬"],"cats":{"抒情":["思念","思乡"],"四季":["春天"],"节日":["春节"]},"theme_conf":0.412},{"uid":"1dcde895-c371-410d-b870-0ee3f99b0c86","title":"江行无题一百首 六十九","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["咫尺愁风雨，匡庐不可登。","秖疑云雾窟，犹有六朝僧。"],"theme":"咏史怀古","theme2":["哲理悟道"],"style":"悲慨","style2":[],"mood":"愁怨","mood2":[],"scene":["雨","江","山"],"cats":{"抒情":["伤感","怀古"],"山水":["庐山"]},"theme_conf":0.56},{"uid":"09fea87e-c0a8-44bc-a18f-307b9f7ee92b","title":"杂曲歌辞 桃花曲","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["魏帝宫人舞凤楼，隋家天子泛龙舟。","君王夜醉春眠[晏]，不觉桃花逐水流。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["花","端午","舟","春"],"cats":{"抒情":["怀古"],"四季":["春天"],"节日":["端午节"],"植物":["桃花"]},"theme_conf":0.9},{"uid":"cp412e673eb67571","title":"贺新郎","author":"刘克庄","dynasty":"宋","section":"宋词","form":"词","paragraphs":["深院榴花吐。","画帘开、衣纨扇，午风清暑。","儿女纷纷夸结束，新样钗符艾虎。","早已有、游人观渡。","老大逢场慵作戏，任陌头、年少争旗鼓。","溪雨急，浪花舞。","灵均标致高如许。","忆生平、既纫兰佩，更怀椒糈。","谁信骚魂千载后，波底垂涎角黍。","又说是、蛟馋龙怒。","把似而今醒到了，料当年、醉死差无苦。","聊一笑，吊千古。"],"theme":"闺情宫怨","theme2":["山水田园"],"style":"清新","style2":["旷达"],"mood":"愁怨","mood2":[],"scene":["夏"],"cats":{"抒情":["闺怨"],"四季":["夏天"]},"theme_conf":0.531},{"uid":"ccf1691d-8325-4d04-9eda-9d8608216ba7","title":"周平西墓","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["英威今寂寞，陈迹对崇丘。","壮志清风在，荒坟白日愁。","穷泉那复晓，乔木不知秋。","岁岁寒塘侧，无人水自流。"],"theme":"咏史怀古","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","冬"],"cats":{"抒情":["孤独","怀古"],"四季":["秋天","冬天"],"人生":["励志","梦想"]},"theme_conf":0.96},{"uid":"b0049020-3b5e-4a46-9b66-71f6de65501d","title":"杂曲歌辞 少年行三首 一","author":"李嶷","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["十八羽林郎，戎衣事汉王。","臂鹰金殿侧，挟弹玉舆旁。","驰道春风起，陪游出建章。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"人生":["青春"]},"theme_conf":0.65},{"uid":"b79db72a-d0ca-42d1-846e-43cb64cea188","title":"杂曲歌辞 行路难五首 四","author":"僧贯休","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见道傍树有寄生枝，青青郁郁同荣衰。","无情之物尚如此，为人不及还堪悲。","父归坟兮未朝夕，已分黄金争田宅。","高堂老母头似霜，心作数支泪常滴。","我闻忽如负芒刺，不独为君空叹息。","古人尺布犹可缝，浔阳义犬令人忆。","寄言世上为人子，孝义团圆莫如此。"],"theme":"亲情","theme2":["送别","悼亡挽歌"],"style":"沉郁","style2":["悲慨"],"mood":"愁怨","mood2":["孤寂","相思"],"scene":[],"cats":{"抒情":["思念","伤感","孤独","悼亡"],"人物":["母亲"]},"theme_conf":0.8},{"uid":"40dbb564-d86b-4616-882c-4dbbd9ac9335","title":"过故人旧宅","author":"王乔","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["故人轩骑罢归来，旧宅园林闲不开。","唯余挟瑟楼中妇，哭向平生歌舞台。"],"theme":"送别","theme2":["咏史怀古"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["恬淡"],"scene":["楼"],"cats":{"抒情":["友情","怀古"]},"theme_conf":0.463},{"uid":"ee380cd0-fea2-4baa-92b7-c82c834265e6","title":"相和歌辞  豫章行","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["胡风吹代马，北拥鲁阳关。","吴兵照海雪，西讨何时还？","半渡上辽津，黄云惨无颜。","老母与子别，呼天野草间。","白马绕旌旗，悲鸣相追攀。","白杨秋月苦，早落豫章山。","本为休明人，斩虏素不闲。","岂惜战鬬死，为君埽凶顽。","精感石没羽，岂忘惮险艰。","楼船若鲸飞，波荡落星湾。","此曲不可奏，三军鬓成斑。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":[],"mood":"悲怆","mood2":[],"scene":["雪","秋","月","楼","舟"],"cats":{"抒情":["伤感"],"四季":["秋天"],"人物":["母亲"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.582},{"uid":"ed5ce508-2df4-4ef2-a6a0-5b8586766d6f","title":"惟此温泉是称愈疾岂予独受其福思与兆人共之乘暇巡游乃言其志","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["桂殿与山连，兰汤涌自然。","阴崖含秀色，温谷吐潺湲。","绩为蠲邪著，功因养正宣。","愿言将亿兆，同此共昌延。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["相思"],"scene":["山"],"cats":{"抒情":["孤独"],"人生":["梦想"]},"theme_conf":1.0},{"uid":"5ddf9bdd-fa07-4f3c-897e-d6428fb97147","title":"送人游蜀","author":"马戴","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["别离杨柳陌，迢遰蜀门行。","若听清猨后，应多白发生。","虹霓侵栈道，风雨杂江声。","过尽愁人处，烟花是锦城。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["雨"],"cats":{"抒情":["离别","伤感"],"天气":["彩虹"]},"theme_conf":1.0},{"uid":"ae4776cb-0cb8-4a59-bad7-7a8aefac04bb","title":"郊村独游","author":"徐夤","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["岁闰堪怜历候迟，出门惟与野云期。","惊鱼掷上绿荷芰，栖鸟啄余红荔枝。","末路可能长薄命，修途应合有良时。","市头相者休相戏，蹙膝先生半自知。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":[],"cats":{"抒情":["孤独"],"生活":["乡村"],"食物":["荔枝"]},"theme_conf":1.0},{"uid":"73e9346a-f26a-43b0-8b93-a0eeaf09b90d","title":"短灯檠歌","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["长檠八尺空自长，短檠二尺便且光。","黄帘绿幕朱户闭，风露气入秋堂凉。","裁衣寄远泪眼暗，搔头频挑移近床。","太学儒生东鲁客，二十辞家来射策。","夜书细字缀语言，两目眵昏头雪白。","此时提携当案前，看书到晓那能眠。","一朝富贵还自恣，长檠高张照珠翠。","吁嗟世事无不然，墙角君看短檠弃。"],"theme":"羁旅思乡","theme2":["送别"],"style":"婉约","style2":["清新","绮丽"],"mood":"愁怨","mood2":[],"scene":["夜","元宵"],"cats":{"抒情":["思乡","伤感"],"节日":["元宵节"]},"theme_conf":0.5},{"uid":"9e6cbc1b-95ed-406b-8c9d-d05876a1342c","title":"送陈章甫","author":"李颀","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["四月南风大麦黄，枣花未落桐阴长。","青山朝别暮还见，嘶马出门思旧乡。","陈侯立身何坦荡，虬须虎眉仍大颡。","腹中贮书一万卷，不肯低头在草莽。","东门酤酒饮我曹，心轻万事皆鸿毛。","醉卧不知白日暮，有时空望孤云高。","长河浪头连天黑，津口停舟渡不得。","郑国游人未及家，洛阳行子空叹息。","闻道故林相识多，罢官昨日今如何。"],"theme":"送别","theme2":[],"style":"雄浑","style2":["豪放","沉郁"],"mood":"孤寂","mood2":["相思"],"scene":["酒","舟"],"cats":{"抒情":["孤独"],"人生":["读书"]},"theme_conf":0.675},{"uid":"92ae04dc-89af-45d6-9e31-204a01df801d","title":"遣怀","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["落魄江南载酒行，楚腰肠断掌中轻。","十年一觉扬州梦，赢得青楼薄幸名。"],"theme":"咏怀抒感","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["江南","酒","楼","江"],"cats":{"抒情":["伤感"]},"theme_conf":0.88},{"uid":"d3357800-9021-4647-a0a0-98499a0ee3c5","title":"春宫怨","author":"杜荀鹤","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["早被婵娟误，欲妆临镜慵。","承恩不在貌，教妾若为容。","风暖鸟声碎，日高花影重。","年年越溪女，相忆采芙蓉。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"节日":["中秋节"]},"theme_conf":0.76},{"uid":"8040db71-8a96-49e2-9f4d-5417af0a0e3e","title":"送孔巢父谢病归游江东兼呈李白","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["巢父掉头不肯住，东将入海随烟雾。","诗卷长流天地间，钓竿欲拂珊瑚树。","深山大泽龙蛇远，春寒野阴风景暮。","蓬莱织女回云车，指点虚无是征路。","自是君身有仙骨，世人那得知其故。","惜君只欲苦死留，富贵何如草头露。","蔡侯静者意有余，清夜置酒临前除。","罢琴惆怅月照席，几岁寄我空中书。","南寻禹穴见李白，道甫问信今何如。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["冲淡","豪放"],"mood":"孤寂","mood2":["惆怅"],"scene":["酒","江","七夕"],"cats":{"抒情":["感恩"],"人物":["父亲"],"节日":["七夕节"]},"theme_conf":0.415},{"uid":"cpbba50c920e98dd","title":"南浦","author":"孔夷","dynasty":"宋","section":"宋词","form":"词","paragraphs":["风悲画角，听单于、三弄落谯门。","投宿征骑，飞雪满孤村。","酒市渐闲灯火，正敲窗、乱叶舞纷纷。","送数声惊雁，下离烟水，嘹唳度寒云。","好在半胧溪月，到如今、无处不销魂。","故国梅花归梦，愁损绿罗裙。","为问暗香闲艳，也相思、万点付啼痕。","算翠屏应是，两眉馀恨倚黄昏。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":["相思","孤寂"],"scene":["雪","夜"],"cats":{"抒情":["离别","思念","思乡","伤感","孤独","怀古"],"天气":["写雪"]},"theme_conf":0.92},{"uid":"39c8eb21-2fd1-42bb-9540-3ff56ea983c3","title":"鼓吹曲辞 朱鹭","author":"张籍","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["翩翩兮朱鹭，来泛春塘栖绿树。","羽毛如翦色如染，远飞欲下双翅敛。","避人引子入深壍，动处水纹开滟滟。","谁知豪家网尔躯，不如饮啄江海隅。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["春","江"],"cats":{"抒情":["思乡"],"四季":["春天"],"动物":["写鸟"]},"theme_conf":0.65},{"uid":"a0a22f26-bd2a-457b-8f7d-74add294e009","title":"九日","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["去年登高郪县北，今日重在涪江滨。","苦遭白发不相放，羞见黄花无数新。","世乱郁郁久为客，路难悠悠常傍人。","酒阑却忆十年事，肠断骊山清路尘。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["重阳"],"cats":{"抒情":["伤感"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.76},{"uid":"1c1df671-910d-4111-9d6b-b002d51f5dff","title":"送张郎中还蜀歌","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["秦家御史汉家郎，亲专两印征殊方。","功成走马朝天子，伏槛论边若流水。","晓离僊署趋紫微，夜接高儒读青史。","泸南五将望君还，愿以天书示百蛮。","曲栈重江初过雨，前旌后骑不同山。","迎车拜舞多耆老，旧卒新营遍青草。","塞口云生火候迟，烟中鹤唳军行早。","黄花川下水交横，远映孤霞蜀国晴。","邛竹笋长椒瘴起，荔枝花发杜鹃鸣。","回首岷峨半天黑，传觞接膝何由得。","空令豪士仰威名，无复贫交恃颜色。","垂杨不动雨纷纷，锦帐胡瓶争送君。","须臾醉起箫笳发，空见红旌入白云。"],"theme":"送别","theme2":[],"style":"清新","style2":["绮丽","沉郁"],"mood":"孤寂","mood2":[],"scene":["酒","鸟","塞外","花","雨"],"cats":{"抒情":["离别","孤独"],"食物":["荔枝"]},"theme_conf":0.624},{"uid":"cd99fae2-e492-43a5-991d-5febb80ba51d","title":"宋中遇刘书记有别","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["何代无秀士，高门生此才。","森然覩毛发，若见河山来。","几载困常调，一朝时运催。","白身谒明主，待诏登云台。","相逢梁宋间，与我醉蒿莱。","寒楚眇千里，雪天昼不开。","末路终离别，不能强悲哀。","男儿争富贵，劝尔莫迟廻。"],"theme":"送别","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["雪"],"cats":{"抒情":["离别","伤感"],"人物":["老师"]},"theme_conf":1.0},{"uid":"f969fcea-2dd7-4d7b-8257-8f228da97489","title":"郊庙歌辞 祭神州乐章 肃和","author":"褚亮","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["大矣坤仪，至哉神县。","包含日域，牢笼月竁。","露絜三清，风调六变。","皇祇介祉，式歆恭荐。"],"theme":"咏史怀古","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["月"],"cats":{"抒情":["怀古","爱国"]},"theme_conf":1.0},{"uid":"0145b0c7-8703-4e0d-b2a0-16a069723bd0","title":"杂曲歌辞 少年行","author":"张祜","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["少年足风情，垂鞭卖眼行。","带金师子小，裘锦骐𬴊狞。","选匠装金镫，推钱买[钿]筝。","李陵虽效死，时论得虚名。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"悲怆","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"人生":["青春"]},"theme_conf":0.65},{"uid":"cp70325eab0d962a","title":"临江仙","author":"陈与义","dynasty":"宋","section":"宋词","form":"词","paragraphs":["忆昔午桥桥上饮，坐中多是豪英。","长沟流月去无声。","杏花疏影里，吹笛到天明。","二十馀年如一梦，此身虽在堪惊。","闲登小阁看新晴。","古今多少事，渔唱起三更。"],"theme":"游仙梦幻","theme2":["闲适隐逸"],"style":"清新","style2":[],"mood":"相思","mood2":["恬淡"],"scene":["江","夜","月"],"cats":{"抒情":["思念"],"生活":["写桥"]},"theme_conf":0.571},{"uid":"cpd4852635a024cd","title":"八声甘州","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["对潇潇、暮雨洒江天，一番洗清秋。","渐霜风凄惨，关河冷落，残照当楼。","是处红衰翠减，苒苒物华休。","惟有长江水，无语东流。","不忍登高临远，望故乡渺邈，归思难收。","叹年来踪迹，何事苦淹留。","想佳人、妆楼望，误几回、天际识归舟。","争知我、倚阑干处，正恁凝愁。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["婉约","绮丽"],"mood":"愁怨","mood2":[],"scene":["江"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"山水":["长江"],"人物":["女子"]},"theme_conf":1.0},{"uid":"de67de33-4490-4be1-accf-46965ae26d38","title":"杂曲歌辞 少年行二首 二","author":"杜牧","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["连环羁玉声光碎，绿锦蔽泥虬卷高。","春风细雨走马去，珠落璀璀白𦋺袍。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["雨"],"cats":{"抒情":["思乡"],"天气":["写雨"],"人生":["青春"]},"theme_conf":1.0},{"uid":"a853ea87-07a2-401d-85ab-ff6ad9767bdc","title":"山路见梅感而有作","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["莫言山路僻，还被好风催。","行客凄凉过，村篱冷落开。","晚溪寒水照，晴日数蜂来。","重忆江南酒，何因把一杯。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["山","酒","江南"],"cats":{"抒情":["思念","伤感"],"生活":["乡村"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"c8a4faa6-8666-44f9-b4c9-df78d7af844d","title":"送别","author":"王维","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["山中相送罢，日暮掩柴扉。","春草明年绿，王孙归不归。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春","山"],"cats":{"抒情":["离别"],"四季":["春天"]},"theme_conf":1.0},{"uid":"bb6982c8-4d92-4a8d-8b0c-dbe7b324219c","title":"建除诗","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["建节出王都，雄雄大丈夫。","除书加右职，骑吏拥前驱。","满月张繁弱，含霜耀鹿卢。","平明跃騕褭，清夜击珊瑚。","定远功那比，平津策乃迂。","执心思报国，效节在忘躯。","破胆销丹浦，颦蛾舞绿珠。","危冠徒自爱，长毂事应殊。","成绩封千室，畴劳使五符。","收功轻骠卫，致埋迈黄虞。","开济今如此，英威古不侔。","闭关草玄者，无乃误为儒。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":["豪放","清新"],"mood":"慷慨","mood2":[],"scene":[],"cats":{"抒情":["爱国"]},"theme_conf":0.86},{"uid":"bb80e9ef-e078-4ae2-8502-7f344d5fc05d","title":"过蜀龙门","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["龙门非禹凿，诡怪乃天功。","西南出巴峡，不与众山同。","长窦亘五里，宛转复嵌空。","伏湍喣潜石，瀑水生轮风。","流水无昼夜，喷薄龙门中。","潭河势不测，藻葩垂彩虹。","我行当季月，烟景共舂融。","江关勤亦甚，𪩘崿意难穷。","势将息机事，炼药此山东。"],"theme":"咏史怀古","theme2":[],"style":"幽峭","style2":[],"mood":"惆怅","mood2":[],"scene":["山","夜","月"],"cats":{"抒情":["怀古"],"天气":["彩虹"]},"theme_conf":1.0},{"uid":"ba2f4924-7ab8-48f2-9e23-d656dea0117b","title":"杂曲歌辞 行路难二首 二","author":"高适","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["长安少年不少钱，能骑骏马鸣金鞭。","五侯相逢大道边，美人弦管争留连。","黄金如斗不敢惜，片言如山莫弃捐。","安知顦顇读书者，暮宿虚台私自怜。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["山"],"cats":{"抒情":["思乡"],"人物":["女子"],"人生":["读书"]},"theme_conf":0.65},{"uid":"3e025699-a493-49b3-8b9d-be47fd65a2ae","title":"太子张舍人遗织成褥段","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["客从西北来，遗我翠织成。","开缄风涛涌，中有掉尾鲸。","逶迤罗水族，琐细不足名。","客云充君褥，承君终宴荣。","空堂魑魅走，高枕形神清。","领客珍重意，顾我非公卿。","留之惧不祥，施之混柴荆。","服饰定尊卑，大哉万古程。","今我一贱老，裋褐更无营。","煌煌珠宫物，寝处祸所婴。","叹息当路子，干戈尚纵横。","掌握有权柄，衣马自肥轻。","李鼎死岐阳，实以骄贵盈。","来瑱赐自尽，气豪直阻兵。","皆闻黄金多，坐见悔吝生。","奈何田舍翁，受此厚贶情。","锦鲸卷还客，始觉心和平。","振我麤席尘，媿客茹藜羹。"],"theme":"边塞征战","theme2":["悼亡挽歌","羁旅思乡"],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":[],"cats":{"抒情":["思乡","悼亡"],"人生":["战争"]},"theme_conf":0.384},{"uid":"c507b869-c422-46dc-be74-0d9ca10a7217","title":"杜鹃","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["西川有杜鹃，东川无杜鹃。","涪万无杜鹃，云安有杜鹃。","我昔游锦城，结庐锦水边。","有竹一顷余，乔木上参天。","杜鹃暮春至，哀哀叫其间。","我见常再拜，重是古帝魂。","生子百鸟巢，百鸟不敢嗔。","仍为𫗪其子，礼若奉至尊。","鸿雁及羔羊，有礼太古前。","行飞与跪乳，识序如知恩。","圣贤古法则，付与后世传。","君看禽鸟情，犹解事杜鹃。","今忽暮春间，值我病经年。","身病不能拜，泪下如迸泉。"],"theme":"山水田园","theme2":["咏物"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["鸟"],"cats":{"抒情":["伤感"],"动物":["写鸟"]},"theme_conf":0.59},{"uid":"cp4cbe1f231c0a58","title":"永遇乐","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["千古江山，英雄无觅，孙仲谋处。","舞榭歌台，风流总被，雨打风吹去。","斜阳草树，寻常巷陌，人道寄奴曾住。","想当年，金戈铁马，气吞万里如虎。","元嘉草草，封狼居胥，赢得仓皇北顾。","四十三年，望中犹记，烽火扬州路。","可堪回首，佛狸祠下，一片神鸦社鼓。","凭谁问，廉颇老矣，尚能饭否。"],"theme":"边塞征战","theme2":["咏史怀古"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["雨"],"cats":{"抒情":["怀古"],"人生":["战争"]},"theme_conf":0.351},{"uid":"8ac1fb39-17d3-4dae-b046-94dfd282aa77","title":"相和歌辞 善哉行","author":"僧齐己","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["大鹏刷翮谢溟渤，青云万层高突出。","下视秋涛空渺弥，旧处鱼龙皆细物。","人生在世何容易，眼浊心昏信生死。","愿除嗜欲待身轻，携手同寻列仙事。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":[],"mood":"悲怆","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"人生":["梦想"]},"theme_conf":0.65},{"uid":"ad067534-b1c5-4baa-8454-3dc50c11e1c3","title":"感怀 二","author":"后主煜","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["层城无复见娇姿，佳节缠哀不自持。","空有当年旧烟月，芙蓉城上哭蛾眉。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["月"],"cats":{"抒情":["悼亡"]},"theme_conf":0.9},{"uid":"1318e5a7-c894-4bb0-a1aa-f5760e0b7f63","title":"旅馆雪晴又覩新月众兴所感因成杂言","author":"权德舆","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["寥寥深夜雪初晴，楼上云开月渐明。","池中片影依稀见，帘外清光远近生。","皎皎晴空疑破镜，广庭积素偏相映。","珠帘卷却光更深，玉指持来色逾净。","梦觉青楼最可怜，婵娟素魄满寒天。","天地寥寥同一色，秦淮楚江无限极。","归鸿断猨何处声，深闺旅馆遥相忆。","长安五侯华阁开，嘉宾列坐倾金罍。","赏明月，玩流雪，纤手蛾眉座中设。","清歌一声无断绝，夜已央，乐未阑。","狐裘兽炭不知寒，珠环翠珮声珊珊。","履舃纷纭桂袖攒，朱颜倚醉尽君欢。","人生少年全不久，相看且劝杯中酒。","丈夫富贵自有期，映雪读书徒白首。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":["绮丽","豪放"],"mood":"欢愉","mood2":["孤寂"],"scene":["雪","月"],"cats":{"抒情":["思乡"],"天气":["写雪","月亮"],"人生":["青春","读书"],"节日":["中秋节"]},"theme_conf":0.557},{"uid":"6767b044-44d9-46ee-b87b-33bfcb381ba0","title":"哭遂州萧侍郎二十四韵","author":"李商隐","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["遥作时多难，先令祸有源。","初惊逐客议，旋骇党人冤。","密侍荣方入，司刑望愈尊。","皆因优诏用，实有谏书存。","苦雾三辰没，穷阴四塞昏。","虎威狐更假，隼击鸟逾喧。","徒欲心存阙，终遭耳属垣。","遗音和蜀魄，易箦对巴猿。","有女悲初寡，无男泣过门。","朝争屈原草，庙馁莫敖魂。","迥阁伤神峻，长江极望翻。","青云宁寄意，白骨始沾恩。","早岁思东合，为邦属故园。","登舟惭郭泰，解榻愧陈蕃。","分以忘年契，情犹锡类敦。","公先真帝子，我系本王孙。","啸傲张高盖，从容接短辕。","秋吟小山桂，春醉后堂萱。","自叹离通籍，何尝忘呌阍。","不成穿圹入，终拟上书论。","多士还鱼贯，云谁正骏奔。","暂能诛儵忽，长与问乾坤。","蚁漏三泉路，螀啼百草根。","始知同泰讲，徼福是虚言。"],"theme":"悼亡挽歌","theme2":[],"style":"悲慨","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":["江"],"cats":{"抒情":["思乡","伤感","悼亡"],"山水":["长江"],"节日":["端午节"]},"theme_conf":0.96},{"uid":"f4a9f923-e4e3-4a02-856b-892800774ad4","title":"白沙渡","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["畏途随长江，渡口下绝岸。","差池上舟楫，杳窕入云汉。","天寒荒野外，日暮中流半。","我马向北嘶，山猨饮相唤。","水清石礧礧，沙白滩漫漫。","迥然洗愁辛，多病一疎散。","高壁抵嵚崟，洪涛越凌乱。","临风独回首，揽辔复三叹。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["愁怨"],"scene":["江"],"cats":{"抒情":["思乡","伤感","孤独"],"山水":["长江"]},"theme_conf":0.78},{"uid":"d3e70d45-82d5-44a7-a20e-cbb2c762d857","title":"夜坐吟","author":"李贺","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["踏踏马蹄谁见过，眼看北斗直天河。","西风罗幕生翠波，铅华笑妾颦青蛾。","为君起唱长相思，帘外严霜皆倒飞。","明星烂烂东方陲，红霞梢出东南涯，陆郎去矣乘班骓。"],"theme":"闺情宫怨","theme2":["爱情相思"],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["夜","秋"],"cats":{"抒情":["爱情","思念","闺怨"],"四季":["秋天"],"天气":["星星"]},"theme_conf":0.5},{"uid":"8c0c4d2b-a459-4a8b-9597-4d479f018863","title":"漫歌八曲 小回中","author":"元结","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["丛石横大江，人言是钓台。","水石相冲激，此中为小回。","回中浪不恶，复在武昌郭。","来客去客船，皆向此中泊。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["舟","江"],"cats":{"抒情":["思乡"],"山水":["长江"]},"theme_conf":0.503},{"uid":"35b59fb5-75cd-4bf0-ac6e-86b0dd9cb22a","title":"焦篱店醉题","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["洛下渠头百卉新，满筵歌笑独伤春。","何须更弄邵翁伯，即我此身如此人。"],"theme":"咏物","theme2":["山水田园","闲适隐逸"],"style":"豪放","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["酒","春"],"cats":{"抒情":["孤独"],"四季":["春天"],"生活":["乡村"],"食物":["写酒"]},"theme_conf":0.43},{"uid":"5e190844-b5af-4f96-8560-1fab6dded1cf","title":"巴陵寄李二户部张十四礼部","author":"贾至","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["江南春草初幂幂，愁杀江南独愁客。","秦中杨柳也应新，转忆秦中相忆人。","万里莺花不相见，登高一望泪沾巾。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["春","江南","重阳","江"],"cats":{"抒情":["思念","伤感"],"四季":["春天"],"节日":["重阳节"]},"theme_conf":0.85},{"uid":"cp1e3fc70b8b96e6","title":"千秋岁引","author":"王安石","dynasty":"宋","section":"宋词","form":"词","paragraphs":["别馆寒砧，孤城画角。","一派秋声入寥廓。","东归燕从海上去，南来雁向沙头落。","楚台风，庾楼月，宛如昨。","无奈被些名利缚。","无奈被他情担阁。","可惜风流总闲却。","当初漫留华表语，而今误我秦楼约。","梦阑时，酒醒后，思量著。"],"theme":"咏怀抒感","theme2":["送别","羁旅思乡"],"style":"豪放","style2":[],"mood":"孤寂","mood2":["相思","愁怨"],"scene":["秋","楼"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["秋天"]},"theme_conf":0.85},{"uid":"5022a1cb-449b-4dcc-8b78-33e9e5914d02","title":"相和歌辞 大堤行","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["大堤行乐处，车马相驰突。","岁岁春草生，踏青二三月。","王孙挟珠弹，游女矜罗韈。","携手今莫同，江花为谁发。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":["豪放"],"mood":"欢愉","mood2":[],"scene":["清明","春","月","江"],"cats":{"抒情":["思乡"],"四季":["春天"],"节日":["清明节"]},"theme_conf":0.65},{"uid":"0a3c8ec7-42d7-48b9-90df-b961b50d2a28","title":"逢王泌自东京至","author":"李端","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["逢君自乡至，雪涕问田园。","几处生乔木，谁家在旧村。","山峰横二室，水色映千门。","愁见游从处，如今花正繁。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"冲淡","style2":[],"mood":"愁怨","mood2":[],"scene":["山","雪"],"cats":{"抒情":["思乡","伤感"],"生活":["田野"]},"theme_conf":0.554},{"uid":"ccbadda6-7e25-4df6-bde4-cff74e45d080","title":"瘦马行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["东郊瘦马使我伤，骨骼硉兀如堵墙。","绊之欲动转敧侧，此岂有意仍腾骧。","细看六印带官字，众道三军遗路旁。","皮干剥落杂泥滓，毛暗萧条连雪霜。","去岁奔波逐余寇，骅骝不惯不得将。","士卒多骑内厩马，惆怅恐是病乘黄。","当时历块误一蹶，委弃非汝能周防。","见人惨澹若哀诉，失主错莫无晶光。","天寒远放雁为伴，日暮不收乌啄疮。","谁家且养愿终惠，更试明年春草长。"],"theme":"羁旅思乡","theme2":["边塞征战","悼亡挽歌"],"style":"幽峭","style2":[],"mood":"惆怅","mood2":["恬淡","悲怆"],"scene":["雪","春"],"cats":{"抒情":["思乡","伤感","悼亡"],"四季":["春天"],"动物":["写马"]},"theme_conf":0.371},{"uid":"27acb13b-76e1-46ee-a681-148fc96b24b6","title":"早秋京口旅泊章侍御寄书相问因以赠之时七夕","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["移家避寇逐行舟，厌见南徐江水流。","吴越征徭非旧日，秣陵凋弊不宜秋。","千家闭户无砧杵，七夕何人望斗牛。","祗有同时骢马客，偏宜尺牍问穷愁。"],"theme":"羁旅思乡","theme2":["送别","羁旅思乡"],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["七夕","秋"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"节日":["七夕节"]},"theme_conf":0.74},{"uid":"cp2a7fdfe25cb12e","title":"琥珀猫儿堕","author":"施惠《幽闺记》","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["(小生)听哥说罢，方识此根由。","这是王尚书，招商店也是王尚书。","有事可疑。","哥哥，破镜重圆从古有，何须疑虑反生愁？(生)兄弟，断无此事，不可错疑了。","(小生)不谬。","重整备乘龙花烛风流。"],"theme":"亲情","theme2":[],"style":"冲淡","style2":[],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["伤感"],"动物":["写猫"]},"theme_conf":1.0},{"uid":"cpdfe6d2cd46549c","title":"夏云峰","author":"仲殊","dynasty":"宋","section":"宋词","form":"词","paragraphs":["天阔云高，溪横水远。","晚日寒生轻晕。","闲阶静、杨花渐少，朱门掩、莺声犹嫩。","悔匆匆、过却清明，旋占得馀芳，已成幽恨。","都几日阴沈，连宵慵困。","起来韶华都尽。","怨入双眉闲斗损。","乍品得情怀，看承全近。","深深态、无非自许。","厌厌意、终羞人间。","争知道、梦里蓬莱，待忘了馀香，时传音信。","纵留得莺花，东风不住，也则眼前愁闷。"],"theme":"闺情宫怨","theme2":["闲适隐逸"],"style":"婉约","style2":["沉郁","冲淡"],"mood":"愁怨","mood2":["恬淡"],"scene":["夏","花","清明","春","山"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天","夏天"],"天气":["写云"],"节日":["清明节"]},"theme_conf":0.9},{"uid":"66711c88-d15e-4440-a51c-03447a294dee","title":"秋中雨田园即事","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["漠漠重云暗，萧萧密雨垂。","为霖淹古道，积日满荒陂。","五稼何时获，孤村几户炊。","乱流发通圃，腐叶著秋枝。","暮爨新樵湿，晨渔旧浦移。","空余去年菊，花发在东篱。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["惆怅"],"scene":["雨","秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"天气":["写雨"],"生活":["乡村","田野"]},"theme_conf":0.762},{"uid":"cp667abac29b3ed1","title":"乔木查・掩柴扉静悄，不许红尘到。皓月清风为故友，肩将梨杖桃，闲访","author":"高秀文","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["渔樵。"],"theme":"闲适隐逸","theme2":["山水田园"],"style":"冲淡","style2":["清新","绮丽"],"mood":"恬淡","mood2":[],"scene":["月"],"cats":{"抒情":["友情"],"天气":["月亮"],"植物":["梨花","桃花"]},"theme_conf":0.528},{"uid":"ce491725-b96b-46a7-b83c-463d2094ef3f","title":"和张仆射塞下曲 一","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["鹫翎金仆姑，燕尾绣蝥弧。","独立扬新令，千营共一呼。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":["清新"],"mood":"孤寂","mood2":["欢愉"],"scene":["塞外"],"cats":{"抒情":["孤独"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"b47c9575-fe60-44e4-92f7-94386b4d512f","title":"春和杜相公移入长兴宅奉呈诸宰执","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["欲向幽偏适，还从绝地移。","秦官鼎食贵，尧世土阶卑。","戟户槐阴满，书窗竹叶垂。","才分午夜漏，遥隔万年枝。","北阙深恩在，东林远梦知。","日斜门掩暎，山远树参差。","论道齐鸳翼，题诗忆凤池。","从公亦何幸，长与珮声随。"],"theme":"应制干谒","theme2":["山水田园"],"style":"绮丽","style2":[],"mood":"相思","mood2":["欢愉"],"scene":["春","夜"],"cats":{"抒情":["思念"],"四季":["春天"],"山水":["庐山"]},"theme_conf":0.95},{"uid":"cpeb9e1e9caece13","title":"永遇乐","author":"苏轼","dynasty":"宋","section":"宋词","form":"词","paragraphs":["明月如霜，好风如水，清景无限。","曲港跳鱼，圆荷泻露，寂寞无人见。","如三鼓，铿然一叶，黯黯梦云惊断。","夜茫茫，重寻无处，觉来小园行遍。","天涯倦客，山中归路，望断故园心眼。","燕子楼空，佳人何在，空锁楼中燕。","古今如梦，何曾梦觉，但有旧欢新怨。","异时对，黄楼夜景，为余浩叹。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["月","楼","夜"],"cats":{"抒情":["思乡","孤独"],"天气":["月亮"],"人物":["女子"]},"theme_conf":0.763},{"uid":"11964ccb-20f2-4a42-9ae2-d6a3e11ef7dc","title":"登刘宾客高斋","author":"钱起","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["能以功成疎宠位，不将心赏负云霞。","林间客散孙弘阁，城上山宜绮季家。","蝴蝶晴连池岸草，黄鹂晚出柳园花。","日陪鲤也趋文苑，谁道门生隔绛纱。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["园林"],"cats":{"抒情":["思乡"],"天气":["写云"],"人物":["老师"]},"theme_conf":0.581},{"uid":"da254237-36a9-4eec-b44c-47058833c411","title":"山亭怀古","author":"张弘靖","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["丛石依古城，悬泉洒清池。","高低袤丈内，衡霍相蔽亏。","归田竟何因，为郡岂所宜。","谁能辨人野，寄适聊在斯。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"惆怅","mood2":[],"scene":["山","楼"],"cats":{"抒情":["怀古"],"山水":["瀑布"]},"theme_conf":0.595},{"uid":"4d6f83e9-8232-4db1-903e-f9e619df5ecb","title":"西施咏","author":"王维","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["艳色天下重，西施宁久微。","朝仍越溪女，暮作吴宫妃。","贱日岂殊众，贵来方悟稀。","邀人傅香粉，不自著罗衣。","君宠益娇态，君怜无是非。","当时浣纱伴，莫得同车归。","持谢邻家子，效颦安可希。"],"theme":"咏史怀古","theme2":["咏物"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江南"],"cats":{"抒情":["怀古"]},"theme_conf":0.4},{"uid":"9fb8dfe5-540c-4e2e-b12a-085273a6cf99","title":"和王相公题中书丛竹寄上元相公","author":"郎士元","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["多时仙掖里，色并翠琅玕。","幽意含烟月，清阴庇蕙兰。","枝繁宜露重，叶老爱天寒。","竟日双鸾止，孤吟为一看。"],"theme":"咏物","theme2":["送别","应制干谒","咏物"],"style":"沉郁","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["元宵"],"cats":{"抒情":["孤独"],"节日":["元宵节"],"植物":["竹子"]},"theme_conf":0.7},{"uid":"5d8ad939-d581-4971-83b3-160b1486a2b5","title":"寄题余杭郡楼兼呈裴使君","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["官历二十政，宦游三十秋。","江山与风月，最忆是杭州。","北郭沙堤尾，西湖石岸头。","绿觞春送客，红烛夜回舟。","不敢言遗爱，空知念旧游。","凭君吟此句，题向望涛楼。"],"theme":"寄赠酬答","theme2":[],"style":"雄浑","style2":[],"mood":"相思","mood2":[],"scene":["楼","江"],"cats":{"抒情":["思念"],"山水":["西湖"]},"theme_conf":0.9},{"uid":"0201eede-b035-4751-a5b5-e2bfbdc6caa2","title":"别崔潩因寄薛据孟云卿","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["志士惜妄动，知深难固辞。","如何久磨砺，但取不磷缁。","夙夜听忧主，飞腾急济时。","荆州过薛孟，为报欲论诗。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["夜"],"cats":{"抒情":["离别"],"人生":["励志"]},"theme_conf":1.0},{"uid":"9da0cbe5-52d4-4efc-8be2-2f78f1a8f097","title":"客至","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["舍南舍北皆春水，但见群鸥日日来。","花径不曾缘客扫，蓬门今始为君开。","盘餐市远无兼味，樽酒家贫只旧醅。","肯与邻翁相对饮，隔篱呼取尽余桮。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["酒"],"cats":{"抒情":["思乡"]},"theme_conf":0.49},{"uid":"5c154375-4cf7-4a77-b792-b211e2dc4842","title":"海上卧病寄王临","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["离客穷海阴，萧辰归思结。","一随浮云滞，几怨黄鹄别。","妙年即沈疴，生事多所阙。","劒中负明义，枕上惜玄发。","之子良史才，华簪偶时哲。","相思千里道，愁望飞鸟绝。","岁暮冰雪寒，淮湖不可越。","百年去心虑，孤影守薄劣。","独余慕侣情，金石无休歇。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":["愁怨","孤寂"],"scene":["冬","雪"],"cats":{"抒情":["离别","思念","伤感","孤独"],"天气":["写雪"]},"theme_conf":0.83},{"uid":"027bd68f-e4fa-4564-a2cd-f18352352932","title":"梨园弟子","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["白头垂泪话梨园，五十年前雨露恩。","莫问华清今日事，满山红叶鏁宫门。"],"theme":"闺情宫怨","theme2":["咏史怀古"],"style":"沉郁","style2":["清新"],"mood":"愁怨","mood2":[],"scene":["园林"],"cats":{"抒情":["伤感","闺怨","怀古"],"人物":["老师"],"植物":["梨花"]},"theme_conf":0.624},{"uid":"2c9fcb36-9e32-4ad9-8e44-eafc1df1b2a3","title":"杂曲歌辞 悲歌","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["悲来乎，悲来乎！主人有酒且莫斟，听我一曲悲来吟。","悲来不吟还不笑，天下无人知我心。","君有数斗酒，我有三尺琴。","琴鸣酒乐两相得，一杯不啻千钧金。","悲来乎，悲来乎！天虽长，地虽久，金玉满堂应不守。","富贵百年能几何？死生一度人皆有。","孤猨坐啼坟上月，且须一尽杯中酒。","悲来乎，悲来乎！凤鸟不至河无图，微子去之箕子奴。","汉帝不忆李将军，楚王放却屈大夫。","悲来乎，悲来乎！秦家李斯早追悔，虚名拨向身之外。","范子何曾爱五湖，功成名遂身自退。","劒是一夫用，书能知姓名。","惠施不肯干万乘，卜式未必穷一经。","还须黑头取方伯，莫谩白首为儒生。"],"theme":"咏怀抒感","theme2":["闲适隐逸","讽喻刺世","悼亡挽歌"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["孤寂"],"scene":["酒"],"cats":{"抒情":["伤感","孤独","悼亡"]},"theme_conf":0.9},{"uid":"495d3ae4-4bc2-46f3-a2bd-1fda9353283f","title":"景龙二年余自门下平章事削阶授江州员外司马寻拜襄州刺史春日赴襄阳途中言志","author":"崔湜","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["余本燕赵人，秉心愚且直。","群籍备所见，孤贞每自饬。","徇禄期代耕，受任亦量力。","幸逢休明时，朝野两荐推。","一朝趋金门，十载奉瑶墀。","入掌迁固笔，出参枚马词。","吏部既三践，中书亦五期。","进无负鼎说，退慙补衮诗。","常恐婴悔吝，不得少酬私。","嗷嗷路傍子，纳谤纷无已。","上动明主疑，下贻大臣耻。","毫发顾无累，冰壶邈自持。","天道何期平，幽冤终见明。","始佐庐陵郡，寻牧襄阳城。","彤帏荷新宠，朱黻蒙旧荣。","力薄慙任重，恩深知命轻。","饬徒留前路，行子悲且慕。","犹闻长乐钟，尚辨青门树。","慈亲不忍诀，昆弟默相顾。","去去勿重陈，川长日云暮。"],"theme":"咏怀抒感","theme2":["应制干谒","闲适隐逸","送别"],"style":"清新","style2":["旷达","沉郁"],"mood":"悲怆","mood2":["孤寂"],"scene":["春","江"],"cats":{"抒情":["伤感","孤独"],"四季":["春天"],"天气":["太阳"],"人物":["母亲"],"人生":["梦想"],"动物":["写马"]},"theme_conf":0.85},{"uid":"1b0a3511-24ee-414c-a93f-b561d791f545","title":"题梅妃画真","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["忆昔娇妃在紫宸，铅华不御得天真。","霜绡虽似当时态，争奈娇波不顾人。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["冬"],"cats":{"抒情":["思念"],"植物":["梅花"]},"theme_conf":0.828},{"uid":"d5f4c0a5-e669-4943-85bd-6b9c2f15d98d","title":"晚春永宁墅小园独坐寄上王相公","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["东阁一何静，莺声落日愁。","夔龙暂为别，昏旦思兼秋。","蕙草出篱外，花枝寄竹幽。","上方传雅颂，七夕让风流。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["春","七夕","园林"],"cats":{"抒情":["孤独"],"四季":["春天"],"节日":["七夕节"]},"theme_conf":0.85},{"uid":"8fbcb3d0-f752-4276-9e20-971e82b36b3e","title":"酬令狐相公六言见寄","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["已嗟别离太远，更被光阴苦催。","吴苑燕辞人去，汾川鴈带书来。","愁吟月落犹望，忆梦天明未回。","今日便令歌者，唱兄诗送一杯。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["月","江南","酒"],"cats":{"抒情":["离别","思念","伤感"],"人生":["时光"]},"theme_conf":0.96},{"uid":"601d90fb-3589-44f1-9a25-9e16af2102c3","title":"陪李七司马皂江上观造竹桥即日成往来之人免冬寒入水聊题短作简李公二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["把烛成桥夜，回舟坐客时。","天高云去尽，江迥月来迟。","衰谢多扶病，招邀屡有期。","异方乘此兴，乐罢不无悲。"],"theme":"山水田园","theme2":[],"style":"悲慨","style2":["幽峭","沉郁"],"mood":"欢愉","mood2":["悲怆"],"scene":["江","冬"],"cats":{"抒情":["伤感"],"四季":["冬天"],"山水":["江河"],"生活":["写桥"],"动物":["写马"],"植物":["竹子"]},"theme_conf":1.0},{"uid":"e018d77b-84a8-4e85-b9af-d81845efe2a6","title":"苦雨奉寄陇西公兼呈王征士","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["今秋乃淫雨，仲月来寒风。","群木水光下，万象云气中。","所思碍行潦，九里信不通。","悄悄素浐路，迢迢天汉东。","愿腾六尺马，背若孤征鸿。","划见公子面，超然欢笑同。","奋飞既胡越，局促伤樊笼。","一饭四五起，凭轩心力穷。","嘉蔬没混浊，时菊碎榛丛。","鹰隼亦屈猛，乌鸢何所蒙。","式瞻北邻居，取适南巷翁。","挂席钓川涨，焉知清兴终。"],"theme":"寄赠酬答","theme2":["送别","民生疾苦","山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":["孤寂","愁怨"],"scene":["雨"],"cats":{"抒情":["伤感","孤独"],"天气":["写雨"]},"theme_conf":0.93},{"uid":"0f5874bf-3748-44c9-bc3a-be4a8c3eb2f6","title":"阁夜","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["岁暮阴阳催短景，天涯霜雪霁寒宵。","五更鼓角声悲壮，三峡星河影动摇。","野哭几家闻战伐，夷歌数处起渔樵。","卧龙跃马终黄土，人事依依漫寂寥。"],"theme":"边塞征战","theme2":["山水田园","羁旅思乡"],"style":"沉郁","style2":["悲慨"],"mood":"悲怆","mood2":["孤寂"],"scene":["夜"],"cats":{"抒情":["思乡","伤感"],"天气":["星星"],"人生":["战争"]},"theme_conf":0.425},{"uid":"cb457f4a-a49c-46cc-becf-d4419d617b79","title":"玉华宫","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["溪回松风长，苍鼠窜古瓦。","不知何王殿，遗构绝壁下。","阴房鬼火青，坏道哀湍泻。","万籁真笙竽，秋色正萧洒。","美人为黄土，况乃粉黛假。","当时侍金舆，故物独石马。","忧来藉草坐，浩歌泪盈把。","冉冉征途间，谁是长年者。"],"theme":"山水田园","theme2":["悼亡挽歌"],"style":"绮丽","style2":["幽峭"],"mood":"愁怨","mood2":["悲怆","孤寂"],"scene":["秋"],"cats":{"抒情":["伤感","孤独","悼亡"],"四季":["秋天"],"人物":["女子"]},"theme_conf":0.516},{"uid":"6e8b1a9f-037f-4f95-94e3-4287c2a9787a","title":"岁除日奉推事使牒追赴抚州辨对留别崔法曹陆大祝处士上人同赋人字口号","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["上国杳未到，流年忽复新。","回车不自识，君定送何人。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["除夕"],"cats":{"抒情":["离别"],"人生":["时光"],"节日":["春节"]},"theme_conf":0.651},{"uid":"a3e4aa0f-aba7-4024-a349-3c9fb23be270","title":"汉州月夕游房太尉西湖","author":"李德裕","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["丞相鸣琴地，何年闭玉徽。","偶因明月夕，重敞故楼扉。","桃柳谿空在，芙蓉客暂依。","谁怜济川楫，长与夜舟归。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["中秋","月","江南"],"cats":{"抒情":["思乡"],"山水":["西湖"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"e4354c00-c83e-43da-9341-7007889dd625","title":"过香积寺","author":"王维","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["不知香积寺，数里入云峰。","古木无人迳，深山何处钟。","泉声咽危石，日色冷青松。","薄暮空潭曲，安禅制毒龙。"],"theme":"佛道禅颂","theme2":["山水田园"],"style":"婉约","style2":["幽峭"],"mood":"孤寂","mood2":[],"scene":["山","花"],"cats":{"抒情":["孤独"],"人生":["哲理"]},"theme_conf":0.74},{"uid":"cpe17f558a5aa701","title":"洞仙歌","author":"苏轼","dynasty":"宋","section":"宋词","form":"词","paragraphs":["冰肌玉骨，自清凉无汗。","水殿风来暗香满。","绣帘开、一点明月窥人，人未寝、枕钗横鬓乱。","起来携素手，庭户无声，时见疏星渡河汉。","试问夜如何，夜已三更，金波淡、玉绳低转。","但屈指、西风几时来，又不道、流年暗中偷换。"],"theme":"闺情宫怨","theme2":["游仙梦幻"],"style":"绮丽","style2":["冲淡","婉约"],"mood":"恬淡","mood2":[],"scene":["夜","月"],"cats":{"抒情":["闺怨"],"天气":["月亮"],"人生":["时光"]},"theme_conf":0.623},{"uid":"cpaf5595daded2dc","title":"渔家傲","author":"朱服","dynasty":"宋","section":"宋词","form":"词","paragraphs":["小雨廉纤风细细。","万家杨柳轻烟里。","恋树湿花飞不起。","愁无比。","和春付与西流水。","九十光阴能有几。","金龟解尽留无计。","寄语东城沽酒市。","拼一醉。","而今乐事他年泪。"],"theme":"咏怀抒感","theme2":["羁旅思乡","送别","闲适隐逸"],"style":"婉约","style2":["豪放","沉郁"],"mood":"愁怨","mood2":[],"scene":["酒","春"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"人生":["时光"]},"theme_conf":0.88},{"uid":"7af6841a-3381-426d-a811-4e1d133ba180","title":"正月十五夜闻京有灯恨不得观","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["月色灯光满帝都，香车宝辇隘通衢。","身闲不睹中兴盛，羞逐乡人赛紫姑。"],"theme":"羁旅思乡","theme2":["闲适隐逸"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["元宵","月","夜"],"cats":{"抒情":["思乡"],"天气":["月亮"],"节日":["元宵节"]},"theme_conf":0.545},{"uid":"1809b35f-90e9-48f1-9844-c467caabddd7","title":"琴曲歌辞 胡笳十八拍 第十八拍","author":"刘商","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["归来故乡见亲族，田园半芜春草绿。","明烛重然煨烬灰，寒泉更洗沈泥玉。","载持巾栉礼仪好，一弄丝桐生死足。","出入关山十二年，哀情尽在胡笳曲。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["春","塞外","园林","山"],"cats":{"抒情":["思乡"],"四季":["春天"],"生活":["田野"]},"theme_conf":0.412},{"uid":"15a3131f-aaa2-4557-9233-aeceb9edbb63","title":"舟中夜雪有怀卢十四侍御弟","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["朔风吹桂水，朔雪夜纷纷。","暗度南楼月，寒深北渚云。","烛斜初近见，舟重竟无闻。","不识山阴道，听鸡更忆君。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["雪","夜","舟","冬"],"cats":{"抒情":["思念"],"四季":["冬天"],"天气":["写风","写雪"]},"theme_conf":0.65},{"uid":"f8055804-4c69-4e9d-b63c-d649c86a6b5f","title":"奉汉中王手札报韦侍御萧尊师亡","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋日萧韦逝，淮王报峡中。","少年疑柱史，多术怪仙公。","不但时人惜，祗应吾道穷。","一哀侵疾病，相识自儿童。","处处邻家笛，飘飘客子蓬。","强吟怀旧赋，已作白头翁。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"悲怆","mood2":[],"scene":["秋"],"cats":{"抒情":["悼亡"],"四季":["秋天"],"人物":["儿童"]},"theme_conf":0.98},{"uid":"23818817-a8c2-4a52-a995-0f84dd5b548e","title":"送敭法师","author":"贾岛","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["度岁不相见，严冬始出关。","孤烟寒色树，高雪夕阳山。","瀑布寺应到，牡丹房甚闲。","南朝遗迹在，此去几时还。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["冬","雪"],"cats":{"抒情":["孤独"],"四季":["冬天"],"山水":["瀑布"]},"theme_conf":0.616},{"uid":"6ac98d23-849c-4cdc-9c66-72fc3d6c87c7","title":"长门怨","author":"徐贤妃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["旧爱柏梁台，新宠昭阳殿。","守分辞芳辇，含情泣团扇。","一朝歌舞荣，夙昔诗书贱。","颓恩诚已矣，覆水难重荐。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["闺怨"],"人生":["读书"]},"theme_conf":1.0},{"uid":"d9bb3556-f0d9-4989-afdd-0163fb826a01","title":"相和歌辞 从军行","author":"刘希夷","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋来风瑟瑟，群马胡行疾。","严城昼不开，伏兵暗相失。","天子庙堂拜，将军玉门出。","纷纷伊洛间，戎马数千匹。","军门压黄河，兵气冲白日。","平生怀伏劒，忼慨既投笔。","南登汉月孤，北走燕云密。","近取韩彭计，早知孙吴术。","丈夫清万里，谁能埽一室。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":["孤寂"],"scene":["江","秋","月"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["黄河"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"06c84041-b4d9-4317-8d51-863fe37b087b","title":"谢赐珍珠","author":"江妃","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["桂叶双眉久不描，残妆和泪汚红绡。","长门尽日无梳洗，何必珍珠慰寂寥。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":["孤寂","愁怨"],"scene":[],"cats":{"抒情":["伤感","闺怨","感恩"]},"theme_conf":0.758},{"uid":"cpdef5aab5815c88","title":"木兰花慢","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["老来情味减，对别酒、怯流年。","况屈指中秋，十分好月，不照人圆。","无情水、都不管，共西风、只等送归船。","秋晚莼鲈江上，夜深儿女灯前。","征衫。","便好去朝天。","玉殿正思贤。","想夜半承明，留教视草，却遣筹边。","长安故人问我，道寻常、泥酒只依然。","目断秋霄落雁，醉来时响空弦。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","酒","夜","中秋"],"cats":{"抒情":["友情"],"四季":["秋天"],"人生":["时光"],"节日":["中秋节"]},"theme_conf":0.568},{"uid":"f96506ea-e8ac-47e0-a0a6-ccd306e56645","title":"旅夜书怀","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["细草微风岸，危樯独夜舟。","星垂平野阔，月涌大江流。","名岂文章著，官因老病休。","飘飘何所似，天地一沙鸥。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["夜"],"cats":{"抒情":["思乡","孤独"],"山水":["江河","长江"]},"theme_conf":0.651},{"uid":"cp387273cafb9464","title":"鹧鸪天","author":"晏几道","dynasty":"宋","section":"宋词","form":"词","paragraphs":["彩袖殷勤捧玉锺。","当年拼却醉颜红。","舞低杨柳楼心月，歌尽桃花扇影风。","从别后，忆相逢。","几回魂梦与君同。","今宵剩把银釭照，犹恐相逢是梦中。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["豪放"],"mood":"相思","mood2":[],"scene":["花","楼","月","酒","夜"],"cats":{"抒情":["思念"]},"theme_conf":1.0},{"uid":"c166938b-f267-49e1-8a9b-a76852e97540","title":"阌乡姜七少府设脍戏赠长歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["姜侯设脍当严冬，昨日今日皆天风。","河冻未渔不易得，凿冰恐侵河伯宫。","饔人受鱼鲛人手，洗鱼磨刀鱼眼红。","无声细下飞碎雪，有骨已剁觜春葱。","偏劝腹腴媿年少，软炊香饭缘老翁。","落碪何曾白纸湿，放箸未觉金盘空。","新欢便饱姜侯德，清觞异味情屡极。","东归贪路自觉难，欲别上马身无力。","可怜为人好心事，于我见子真颜色。","不恨我衰子贵时，怅望且为今相忆。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"沉郁","style2":["婉约","绮丽"],"mood":"相思","mood2":["欢愉","愁怨"],"scene":["冬"],"cats":{"抒情":["思念","思乡"],"四季":["冬天"]},"theme_conf":0.86},{"uid":"1e5d503c-12ee-4e2c-a645-80e5e892316b","title":"赠薛戴","author":"李端","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["晓雾忽为霜，寒蝉还罢响。","行人在长道，日暮多归想。","射策本何功，名登绛帐中。","遂矜丘室重，不料阮途穷。","交结慙时辈，龙钟似老翁。","机非鄙夫正，懒是平生性。","欹枕鸿雁高，闭关花药盛。","厨烟当雨绝，阶竹连窗暝。","欲赋苦饥行，无如消渴病。","旧业历胡尘，荒原少四邻。","田园空有处，兄弟未成人。","毛义心长苦，袁安家转贫。","今呈胸臆事，当为泪沾巾。"],"theme":"寄赠酬答","theme2":["民生疾苦"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"人物":["老师"],"生活":["田野"]},"theme_conf":0.96},{"uid":"4e92a96d-aa74-4153-8314-b6df22d1e18a","title":"相和歌辞 子夜四时歌四首 春歌","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["秦地罗敷女，采桑绿水边。","素手青条上，红妆白日鲜。","蚕饥妾欲去，五马莫留连。"],"theme":"闺情宫怨","theme2":["民生疾苦"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"]},"theme_conf":0.471},{"uid":"3b67a24e-33da-4a40-941a-e7a42931b390","title":"咏荆轲","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["燕秦不两立，太子已为虞。","千金奉短计，匕首荆卿趋。","穷年徇所欲，兵势且见屠。","微言激幽愤，怒目辞燕都。","朔风动易水，挥爵前长驱。","函首致宿怨，献田开版图。","炯然耀电光，掌握罔正夫。","造端何其锐，临事竟趑趄。","长虹吐白日，仓卒反受诛。","按劒赫凭怒，风雷助号呼。","慈父断子首，狂走无容躯。","夷城芟七族，台观皆焚污。","始期忧患弭，卒动灾祸枢。","秦皇本诈力，事与桓公殊。","奈何效曹子，实谓勇且愚。","世传故多谬，太史征无且。"],"theme":"咏史怀古","theme2":["咏物"],"style":"悲慨","style2":[],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["怀古"],"天气":["写风","彩虹"]},"theme_conf":0.516},{"uid":"cp39e5bcd45f57af","title":"卜算子","author":"李之仪","dynasty":"宋","section":"宋词","form":"词","paragraphs":["我住长江头，君住长江尾。","日日思君不见君，共饮长江水。","此水几时休，此恨何时已。","只愿君心似我心，定不负相思意。"],"theme":"爱情相思","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["江"],"cats":{"抒情":["爱情","思念"],"山水":["长江"]},"theme_conf":1.0},{"uid":"0f9dd333-5f18-478b-8b18-53ed1bf06e91","title":"秋夜听严绅巴童唱竹枝歌","author":"刘商","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["巴人远从荆山客，回首荆山楚云隔。","思归夜唱竹枝歌，庭槐叶落秋风多。","曲中历历叙乡土，乡思绵绵楚词古。","身骑吴牛不畏虎，手提蓑笠欺风雨。","猨啼日暮江岸边，绿芜连山水连天。","来时十三今十五，一成新衣已再补。","鸿雁南飞报邻伍，在家欢乐辞家苦。","天晴露白钟漏迟，泪痕满面看竹枝。","曲终寒竹风袅袅，西方落日东方晓。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["夜","秋"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"人物":["儿童"],"植物":["竹子"]},"theme_conf":0.586},{"uid":"cpfed98815648c9e","title":"绿头鸭・多丽","author":"贺铸","dynasty":"宋","section":"宋词","form":"词","paragraphs":["玉人家，画楼珠箔临津。","托微风、彩箫流怨，断肠马上曾闻。","燕堂开、艳妆丛里，调琴思、认歌颦。","麝蜡烟浓，玉莲漏短，更衣不待酒初醺。","绣屏掩、枕鸳相就，香气渐暾暾。","回廊影，疏钟淡月，几许销魂。","翠钗分、银笺封泪，舞鞋从此生尘。","住兰舟、载将离恨，转南浦、背西曛。","记取明年，蔷薇谢后，佳期应未误行云。","凤城远，楚梅香嫩，先寄一枝春。","青门外，祗凭芳草，寻访郎君。"],"theme":"送别","theme2":["闺情宫怨"],"style":"婉约","style2":["绮丽","清新"],"mood":"愁怨","mood2":[],"scene":["花","夜","酒","舟","春"],"cats":{"抒情":["离别","伤感","闺怨"],"四季":["春天"]},"theme_conf":0.436},{"uid":"4d9c03ce-ae52-44ae-8100-f43432da8432","title":"杂曲歌辞 少年乐","author":"张祜","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["二十便封侯，名居第一流。","绿鬟深小院，清管下高楼。","醉把金船掷，闲敲玉镫游。","带盘红鼹鼠，袍砑紫犀牛。","锦袋归调箭，罗鞋起拨毬。","眼前长贵盛，那信世间愁。"],"theme":"讽喻刺世","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["楼","舟","园林","酒"],"cats":{"抒情":["伤感"],"人生":["青春"]},"theme_conf":0.62},{"uid":"c222b6d5-2eb5-4603-84ed-b5afef260fae","title":"河口逢江州朱道士因听琴","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["庐山道士夜携琴，映月相逢辨语音。","引坐霜中弹一弄，满船商客有归心。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["山","江"],"cats":{"抒情":["思乡"],"山水":["庐山","江河"]},"theme_conf":0.56},{"uid":"e43db4ab-925d-4cb0-b14a-d105ef6cd63c","title":"杂曲歌辞 昔昔盐 风月守空闺","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["良人犹远戍，耿耿夜闺空。","绣户流宵月，罗帷坐晓风。","魂飞沙帐北，肠断玉关中。","尚自无消息，锦衾那得同。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["冲淡"],"mood":"孤寂","mood2":["愁怨"],"scene":["月","夜"],"cats":{"抒情":["伤感","闺怨"],"天气":["写风","月亮"]},"theme_conf":0.818},{"uid":"4889a0b4-4921-4d09-bab3-b69ae5fb1f5b","title":"同辛衮州巢父虚副端岳相思献酬之作因纾归怀兼呈辛魏二院长杨长宁","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["暮角发高城，情人坐中起。","临觞不及醉，分散秋风里。","虽有明月期，离心若千里。","前欢反惆怅，后会还如此。","焉得夜淹留，一回终宴喜。","羇游复牵役，馆至重湖水。","早晚泛归舟，吾从数君子。"],"theme":"寄赠酬答","theme2":["爱情相思"],"style":"婉约","style2":[],"mood":"相思","mood2":["欢愉"],"scene":["月","酒","园林"],"cats":{"抒情":["爱情","思念"],"天气":["月亮"],"人物":["父亲"]},"theme_conf":0.93},{"uid":"0055db4e-e8d3-41a0-b201-0e3b970e27b6","title":"秋夜曲","author":"王涯","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["桂魄初生秋露微，轻罗已薄未更衣。","银筝夜久殷勤弄，心怯空房不忍归。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":["清新"],"mood":"相思","mood2":[],"scene":["秋","夜"],"cats":{"抒情":["闺怨"],"四季":["秋天"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"6bbd1c2c-8c43-4ffb-b7b3-506d74266cee","title":"九月九日忆山东兄弟","author":"王维","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["独在异乡为异客，每逢佳节倍思亲。","遥知兄弟登高处，遍插茱萸少一人。"],"theme":"羁旅思乡","theme2":["节令风俗","亲情"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["重阳"],"cats":{"抒情":["思念","思乡"],"天气":["月亮"],"节日":["重阳节"]},"theme_conf":0.364},{"uid":"132c7276-e108-4501-b619-ae997cf31e4b","title":"杂曲歌辞 江上曲","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["江上澹澹芙蓉花，江口蛾眉独浣纱。","可怜应是阳台女，坐对鸬鹚娇不语。","掩面羞看北地人，回首忽作空山雨。","苍梧秋色不堪论，千载依依帝子魂。","君看峰上斑斑竹，尽是湘妃泣泪痕。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":["婉约"],"mood":"孤寂","mood2":["恬淡","悲怆"],"scene":["江","山"],"cats":{"抒情":["伤感","孤独"],"山水":["江河"]},"theme_conf":1.0},{"uid":"bcdf6f13-4cb9-418f-9279-c690522e0a27","title":"横吹曲辞 出塞","author":"王之涣","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["黄砂直上白云间，一片孤城万仞山。","羌笛何须怨杨柳，春风不度玉门关。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["塞外"],"cats":{"抒情":["孤独"],"生活":["边塞"]},"theme_conf":0.667},{"uid":"cp0be6d5514dd406","title":"临江仙","author":"晁冲之","dynasty":"宋","section":"宋词","form":"词","paragraphs":["忆昔西池池上饮，年年多少欢娱。","别来不寄一行书。","寻常相见了，犹道不如初。","安稳锦屏今夜梦，月明好度江湖。","相思休问定何如。","情知春去后，管得落花无。"],"theme":"送别","theme2":["爱情相思"],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["江"],"cats":{"抒情":["爱情","思念"],"山水":["江河"]},"theme_conf":0.469},{"uid":"ef36b0a2-6327-47a2-b777-ccf669af3ebb","title":"大历三年春白帝城放船出瞿塘峡久居夔府将适江陵漂泊有诗凡四十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["老向巴人里，今辞楚塞隅。","入舟飜不乐，解缆独长吁。","窄转深啼狖，虚随乱浴凫。","石苔凌几杖，空翠扑肌肤。","叠壁排霜劒，奔泉溅水珠。","杳冥藤上下，浓澹树荣枯。","神女峰娟妙，昭君宅有无。","曲留明怨惜，梦尽失欢娱。","摆阖盘涡沸，欹斜激浪输。","风雷缠地脉，冰雪耀天衢。","鹿角真走险，狼头如跋胡。","恶滩宁变色，高卧负微躯。","书史全倾挠，装囊半压濡。","生涯临臬兀，死地脱斯须。","不有平川决，焉知众壑趋。","乾坤霾涨海，雨露洗春芜。","欧鸟牵丝飏，骊龙濯锦纡。","落霞沈绿绮，残月坏金枢。","泥笋苞初荻，沙茸出小蒲。","雁儿争水马，燕子逐樯乌。","绝岛容烟雾，环洲纳晓晡。","前闻辨陶牧，转眄拂宜都。","县郭南畿好，津亭北望孤。","劳心依憩息，朗咏划昭苏。","意遣乐还笑，衰迷贤与愚。","飘萧将素发，汩没听洪𬬻。","丘壑曾忘返，文章敢自诬。","此生遭圣代，谁分哭穷途。","卧疾淹为客，蒙恩早厕儒。","廷争酬造化，朴直乞江湖。","滟滪险相迫，沧浪深可逾。","浮名寻已已，嬾计却区区。","喜近天皇寺，先披古画图。","应经帝子渚，同泣舜苍梧。","朝士兼戎服，君王按湛卢。","旄头初俶扰，鹑首丽泥涂。","甲卒身虽贵，书生道固殊。","出尘皆野鹤，历块匪辕驹。","伊吕终难降，韩彭不易呼。","五云高太甲，六月旷抟扶。","回首黎元病，争权将帅诛。","山林托疲苶，未必免崎岖。"],"theme":"羁旅思乡","theme2":["羁旅思乡","边塞征战"],"style":"绮丽","style2":["沉郁","清新"],"mood":"欢愉","mood2":["悲怆","孤寂"],"scene":["江","鸟","春","舟","山"],"cats":{"抒情":["思乡","孤独"],"四季":["春天"],"山水":["江河"],"天气":["写雪"],"生活":["边塞"]},"theme_conf":0.8},{"uid":"22099372-939e-4154-a175-15d5365ac21c","title":"奉酬乐天立秋夕有怀见寄","author":"李绅","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["深夜星汉静，秋风初报凉。","阶篁淅沥响，露叶参差光。","冰兔半升魄，铜壶微滴长。","薄帷乍飘卷，襟带轻摇飏。","此际昏梦清，斜月满轩房。","屣履步前楹，劒戟森在行。","重城宵正分，号鼓互相望。","独坐有所思，夫君鸾凤章。","天津落星河，一苇安可航。","龙泉白玉首，鱼服黄金装。","报国未知効，惟鹈徒在梁。","裴回顾戎旃，颢气生东方。","衰叶满栏草，斑毛盈镜霜。","羸牛未脱辕，老马强腾骧。","吟君白雪唱，慙媿巴人肠。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":["婉约","绮丽"],"mood":"孤寂","mood2":["慷慨","欢愉"],"scene":["秋"],"cats":{"抒情":["孤独","爱国"],"四季":["秋天"],"天气":["星星"]},"theme_conf":0.96},{"uid":"cp9ea58780dad3ab","title":"贺新郎","author":"刘克庄","dynasty":"宋","section":"宋词","form":"词","paragraphs":["湛湛长空黑。","更那堪、斜风细雨，乱愁如织。","老眼平生空四海，赖有高楼百尺。","看浩荡、千崖秋色。","白发书生神州泪，尽凄凉、不向牛山滴。","追往事，去无迹。","少年自负凌云笔。","到而今、春华落尽，满怀萧瑟。","常恨世人新意少，爱说南朝狂客。","把破帽、年年拈出。","若对黄花孤负酒，怕黄花、也笑人岑寂。","鸿北去，日西匿。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["豪放"],"mood":"愁怨","mood2":["孤寂"],"scene":["雨"],"cats":{"抒情":["思乡","伤感","孤独"],"天气":["写雨"]},"theme_conf":0.65},{"uid":"f1177b2a-c00f-4d1a-a8f8-95e33bd6c4f5","title":"秋风二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["秋风淅淅吹我衣，东流之外西日微。","天清小城捣练急，石古细路行人稀。","不知明月为谁好，早晚孤帆他夜归。","会将白发倚庭树，故园池台今是非。"],"theme":"羁旅思乡","theme2":["送别"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","园林","月"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"天气":["写风","月亮"]},"theme_conf":0.567},{"uid":"cp7d9065abd6353a","title":"玉楼春","author":"严仁","dynasty":"宋","section":"宋词","form":"词","paragraphs":["春风只在园西畔。","荠菜花繁胡蝶乱。","冰池晴绿照还空，香径落红吹已断。","意长翻恨游丝短。","尽日相思罗带缓。","宝奁明月不欺人，明日归来君试看。"],"theme":"爱情相思","theme2":["边塞征战"],"style":"绮丽","style2":["清新"],"mood":"相思","mood2":["孤寂"],"scene":["春"],"cats":{"抒情":["爱情","思念"],"四季":["春天"],"天气":["月亮"]},"theme_conf":0.577},{"uid":"20491a26-8ddd-490c-bc26-c8d48929d779","title":"登蒲州石矶望横江口潭岛深逈斜对香零山","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["隐忧倦永夜，凌雾临江津。","猿鸣稍已疎，登石娱清沦。","日出洲渚静，澄明皛无垠。","浮晖翻高禽，沈景照文鳞。","双江汇西奔，诡怪潜坤珍。","孤山乃北峙，森爽栖灵神。","洄潭或动容，岛屿疑摇振。","陶埴兹择土，蒲鱼相与邻。","信美非所安，羁心屡逡巡。","𫄙结良可解，纡郁亦已伸。","高歌返故室，自𫍬非所欣。"],"theme":"咏史怀古","theme2":["山水田园","羁旅思乡"],"style":"幽峭","style2":["清新"],"mood":"恬淡","mood2":["孤寂","愁怨"],"scene":["江","山"],"cats":{"抒情":["思乡","孤独","怀古"],"山水":["江河","西湖"]},"theme_conf":0.388},{"uid":"15c6cbc9-753a-4f09-86bf-4fe2d8bb1fee","title":"凉思","author":"李商隐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["客去波平槛，蝉休露满枝。","永怀当此节，倚立自移时。","北斗兼春远，南陵寓使迟。","天涯占梦数，疑误有新知。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"]},"theme_conf":1.0},{"uid":"fd63be75-f6b3-491d-91d5-04179194f1aa","title":"初春登楼即目观作述怀","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["凭轩俯兰阁，眺瞩散灵襟。","绮峰含翠雾，照日蕊红林。","镂丹霞锦岫，残素雪斑岑。","拂浪堤垂柳，娇花鸟续吟。","连甍岂一拱，众干如千寻。","明非独材力，终藉栋梁深。","弥怀矜乐志，更惧戒盈心。","媿制劳居逸，方规十产金。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["楼","春","花"],"cats":{"抒情":["孤独","怀古"],"四季":["春天"],"天气":["写雪"]},"theme_conf":0.565},{"uid":"b6985205-7423-47bf-ad4d-19e2ee4eaed0","title":"夜闻觱篥","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["夜闻觱篥沧江上，衰年侧耳情所向。","邻舟一听多感伤，塞曲三更歘悲壮。","积雪飞霜此夜寒，孤灯急管复风湍。","君知天地干戈满，不见江湖行路难。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"孤寂","mood2":["悲怆","慷慨"],"scene":["夜"],"cats":{"抒情":["伤感","孤独"],"天气":["写雪"],"人生":["战争"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"86a4b0c2-fd29-4877-ae66-d5ee191930b9","title":"谢韦大夫柳栽","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["本在胡笳曲，今从汉将营。","浓阴方待庇，弱植岂无情。","比雪花应吐，藏乌叶未成。","五株蒙远赐，应使号先生。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["雪"],"cats":{"抒情":["感恩"],"植物":["柳树"]},"theme_conf":1.0},{"uid":"05ca1eef-d549-4f8e-b853-1340fbb486b8","title":"杂曲歌辞 行路难五首 三","author":"贺兰进明","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见荒树枝，春花落尽蜂不窥。","君不见梁上泥，秋风始高燕不栖。","荡子从军事征战，蛾眉婵娟空守闺。","独宿自然堪下泪，况复时闻乌夜啼。"],"theme":"边塞征战","theme2":[],"style":"婉约","style2":["冲淡","沉郁"],"mood":"孤寂","mood2":["愁怨"],"scene":["中秋","春","秋","夜"],"cats":{"抒情":["伤感","孤独"],"四季":["春天","秋天"],"人生":["战争"],"节日":["中秋节"]},"theme_conf":0.714},{"uid":"dff1b780-5ef1-4c4f-abff-ef38d41e3c32","title":"醉歌行赠公安颜少府请顾八题壁","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["神仙中人不易得，颜氏之子才孤标。","天马长鸣待驾驭，秋鹰整翮当云霄。","君不见东吴顾文学，君不见西汉杜陵老。","诗家笔势君不嫌，词翰升堂为君埽。","是日霜风冻七泽，乌蛮落照衔赤壁。","酒酣耳热忘头白，感君意气无所惜，一为歌行歌主客。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":["恬淡","孤寂"],"scene":["酒","秋"],"cats":{"抒情":["孤独","感恩"],"四季":["秋天"],"食物":["写酒"]},"theme_conf":0.86},{"uid":"9cf2d943-e52c-4406-bd53-03f686f4abb7","title":"和都官苗员外秋夜省直对雨简诸知己","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["多雨南宫夜，仙郎寓直时。","漏长丹凤阙，秋冷白云司。","萤影侵堦乱，鸿声出苑迟。","萧条人吏散，小谢有新诗。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["夜","秋","雨"],"cats":{"抒情":["友情"],"四季":["秋天"],"天气":["写雨"]},"theme_conf":0.95},{"uid":"cp001b676231ad9c","title":"紫萸香慢","author":"姚云文","dynasty":"宋","section":"宋词","form":"词","paragraphs":["近重阳、偏多风雨，绝怜此日暄明。","问秋香浓未，待携客、出西城。","正自羁怀多感，怕荒台高处，更不胜情。","向尊前、又忆洒酒插花人。","只座上、已无老兵。","凄情。","浅醉还醒。","愁不肯、与诗平。","记长楸走马，雕弓笮柳，前事休评。","紫萸一枝传赐，梦谁到、汉家陵。","尽乌纱、便随风去，要天知道，华发如此星星。","歌罢涕零。"],"theme":"咏史怀古","theme2":["边塞征战","咏史怀古","节令风俗"],"style":"婉约","style2":["沉郁","豪放"],"mood":"愁怨","mood2":["相思"],"scene":["花","酒","雨","重阳"],"cats":{"抒情":["思念","伤感","怀古"],"节日":["重阳节"]},"theme_conf":0.72},{"uid":"a6a2e130-f45f-49a4-a7da-e0441d1578cd","title":"酬庞十兵曹","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["忆昔游京华，自言生羽翼。","怀书访知己，末路空相识。","许国不成名，还家有慙色。","托身从𤱶亩，浪迹初自得。","雨泽感天时，耕耘忘帝力。","同人洛阳至，问我睢水北。","遂尔款津涯，净然见胸臆。","高谈悬物象，逸韵投翰墨。","别岸迥无垠，海鹤鸣不息。","梁城多古意，携手共凄恻。","怀贤想邹枚，登高思荆棘。","世情恶疵贱，之子怜孤直。","酬赠感幷深，离忧岂终极。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["孤寂","相思"],"scene":["重阳"],"cats":{"抒情":["友情","离别","思念","孤独"],"人生":["战争"],"节日":["重阳节"]},"theme_conf":0.82},{"uid":"21943b5d-11e5-44f2-9714-ad996dade3ae","title":"杂曲歌辞 少年行二首 二","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["走马还相寻，西楼下夕阴。","结交期一劒，留意赠千金。","高阁歌声远，重关柳色深。","夜闲须尽醉，莫负百年心。"],"theme":"咏怀抒感","theme2":["送别","羁旅思乡"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["楼"],"cats":{"抒情":["思乡"],"人生":["青春"]},"theme_conf":0.78},{"uid":"417dd972-fc55-4972-b698-e5e595453dbd","title":"相和歌辞 王昭君","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["自矜妖艳色，不顾丹青人。","那知粉缋能相负，却使容华飜误身。","上马辞君嫁骄虏，玉颜对人啼不语。","北风雁急浮清秋，万里独见黄河流。","纤腰不复汉宫宠，双蛾长向胡天愁。","琵琶弦中苦调多，萧萧羌笛声相和。","可怜一曲传乐府，能使千秋伤绮罗。"],"theme":"题画咏艺","theme2":["边塞征战"],"style":"绮丽","style2":["豪放"],"mood":"愁怨","mood2":[],"scene":["江","秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"山水":["黄河"]},"theme_conf":0.435},{"uid":"faaf019b-5e60-4094-a7a6-754762ed30df","title":"重忆山居六首 泰山石","author":"李德裕","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["鸡鸣日观望，远与扶桑对。","沧海似镕金，众山如点黛。","遥知碧峰首，独立烟岚内。","此石依五松，苍苍几千载。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":["雄浑"],"mood":"相思","mood2":[],"scene":["山"],"cats":{"抒情":["思念"],"山水":["泰山"]},"theme_conf":1.0},{"uid":"78975868-daef-40f6-89f2-1aa8b5308c55","title":"木莲树生巴峡山谷间巴民亦呼为黄心树大者高五丈涉冬不凋身如青杨有白文叶如桂厚大无脊花如莲香色艳腻皆同独房蘂有异四月初始开自开迨谢仅二十日忠州西北十里有鸣玉谿生者秾茂尤异元和十四年夏命道士母丘元志写惜其遐僻因题三绝句云 三","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["已愁花落荒岩底，复恨根生乱石间。","几度欲移移不得，天教抛掷在深山。"],"theme":"山水田园","theme2":["咏物"],"style":"沉郁","style2":["绮丽","婉约"],"mood":"愁怨","mood2":["孤寂"],"scene":["山","花","月","冬","夏"],"cats":{"抒情":["伤感","孤独","感恩"],"四季":["夏天","冬天"],"天气":["月亮"],"人生":["梦想"],"植物":["荷花","叶子"]},"theme_conf":0.475},{"uid":"00cc533a-059f-49d8-9812-a43906c52e11","title":"看浑中丞山桃花初有他客不通晚方得入因有戏赠","author":"吕温","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["朝来驻马香街里，风度遥闻语笑声。","无事闭门教日晚，山桃落尽不胜情。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["山","花"],"cats":{"抒情":["思乡"],"植物":["桃花"]},"theme_conf":0.86},{"uid":"ee523bdd-916e-4c51-b261-5bbc2d6f5bfd","title":"八哀诗 故司徒李公光弼","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["司徒天宝末，北收晋阳甲。","胡骑攻吾城，愁寂意不惬。","人安若泰山，蓟北断右胁。","朔方气乃苏，黎首见帝业。","二宫泣西郊，九庙起颓压。","未散河阳卒，思明伪臣妾。","复自碣石来，火焚乾坤猎。","高视笑禄山，公又大献捷。","异王册崇勋，小敌信所怯。","拥兵镇河汴，千里初妥帖。","青蝇纷营营，风雨秋一叶。","内省未入朝死泪终映睫。","大屋去高栋，长城埽遗堞。","平生白羽扇，零落蛟龙匣。","雅望与英姿，恻怆槐里接。","三军晦光彩，烈士痛稠叠。","直笔在史臣，将来洗箱箧。","吾思哭孤冢，南纪阻归楫。","扶颠永萧条，未济失利涉。","疲{艹/尔}竟何人，洒涕巴东峡。"],"theme":"悼亡挽歌","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["山","雨"],"cats":{"抒情":["伤感","悼亡"],"山水":["泰山"]},"theme_conf":0.97},{"uid":"c269dec4-e6e7-40b3-b1c5-b371d0450eb0","title":"怀素上人草书歌","author":"窦冀","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["狂僧挥翰狂且逸，独任天机摧格律。","龙虎惭因点画生，雷霆却避锋铓疾。","鱼牋娟素岂不贵，只嫌局促儿童戏。","粉壁长廊数十间，兴来小豁胸襟气。","长幼集，贤豪至，枕糟藉曲犹半醉。","忽然绝叫三五声，满壁纵横千万字。","吴兴张老尔莫颠，叶县公孙我何谓。","如熊如罴不足比，如虺如蛇不足拟。","涵物为动鬼神泣，狂风入林花乱起。","殊形怪状不易说，就中惊燥尤枯绝。","边风杀气同惨烈，崩槎卧木争摧折。","塞草遥飞大漠霜，胡天乱下阴山雪。","偏看能事转新奇，郡守王公同赋诗。","枯藤劲铁媿三舍，骤雨寒猨惊一时。","此生绝艺人莫测，假此常为护持力。","连城之璧不可量，五百年知草圣当。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":["豪放"],"mood":"孤寂","mood2":["悲怆"],"scene":["雪","塞外"],"cats":{"抒情":["孤独"],"天气":["写风","写雨"],"人物":["儿童"],"生活":["边塞"]},"theme_conf":0.773},{"uid":"e9f0c9ff-9301-4ad3-99f5-7283edd3aa6d","title":"伤春赠远","author":"独孤及","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["去水流年日并驰，年光客思两相随。","咨嗟斑鬓今承弁，慙愧新荷又发池。","杨柳逶迤愁远道，鹧鸪啁哳怨南枝。","忆君何啻同琼树，但向春风送别离。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":["冲淡"],"mood":"相思","mood2":["愁怨"],"scene":["春"],"cats":{"抒情":["离别","思念","伤感"],"四季":["春天"],"人生":["时光"]},"theme_conf":0.86},{"uid":"cpda401b77a73d37","title":"贺新郎","author":"叶梦得","dynasty":"宋","section":"宋词","form":"词","paragraphs":["睡起啼莺语。","掩青苔、房栊向晚，乱红无数。","吹尽残花无人见，惟有垂杨自舞。","渐暖霭、初回轻暑。","宝扇重寻明月影，暗尘侵、尚有乘鸾女。","惊旧恨，遽如许。","江南梦断横江渚。","浪黏天、葡萄涨绿，半空烟雨。","无限楼前沧波意，谁采苹花寄取。","但怅望、兰舟容与。","万里云帆何时到，送孤鸿、目断千山阻。","谁为我，唱金缕。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["清新","豪放"],"mood":"孤寂","mood2":[],"scene":["月","舟","江","江南","花","夏"],"cats":{"抒情":["孤独"],"四季":["夏天"],"天气":["月亮"]},"theme_conf":0.659},{"uid":"d0be6b0d-6be7-4235-9db2-55ab10e437fd","title":"月宫词","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["宫中月明何所似，如积如流满田地。","逈过前殿曾学眉，回照长门惯催泪。","昭阳昨夜秋风来，绮阁金铺情影开。","藻井浮花共陵乱，玉阶零露相裴回。","稍映明河泛仙驭，满牕犹在更衣处。","管弦回烛无限情，环珮凭栏不能去。","皎皎苍苍千里同，穿烟飘叶九门通。","珠帘欲卷畏成水，瑶席初陈惊似空。","复值君王事欢宴，宫女三千一时见。","飞盖愁看素晕低，称觞愿踏清辉遍。","江上无云夜可怜，冒沙披浪自婵娟。","若共心赏风流夜，那比高高太液前。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"欢愉","mood2":["愁怨"],"scene":["月"],"cats":{"抒情":["伤感","闺怨"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"4365fdc6-9e89-489c-abe1-4eda95a85062","title":"杂曲歌辞 升天行","author":"僧齐己","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["身不沈，骨不重，驱青鸾，驾白凤。","幢盖飘飘入冷空，天风瑟瑟星河动。","瑶阙参差阿母家，楼台戏闭凝彤霞。","五三仙子乘龙车，堂前碾烂蟠桃花。","回头却顾蓬山顶，一点浓岚在深井。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["楼"],"cats":{"抒情":["思乡"],"天气":["星星"],"人物":["母亲"]},"theme_conf":1.0},{"uid":"571a9d34-1572-42f4-bb50-96c4d88974b4","title":"春日忆李白","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["白也诗无敌，飘然思不群。","清新庾开府，俊逸鲍参军。","渭北春天树，江东日暮云。","何时一尊酒，重与细论文。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思念"],"四季":["春天"],"天气":["太阳"]},"theme_conf":0.86},{"uid":"294bc7b2-b4f8-4a53-be17-a40ded4afd1a","title":"白雪歌送武判官归京","author":"岑参","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["北风卷地白草折，胡天八月即飞雪。","忽然一夜春风来，千树万树梨花开。","散入珠帘湿罗幕，狐裘不煖锦衾薄。","将军角弓不得控，都护铁衣冷难着。","瀚海阑干百丈冰，愁云黪淡万里凝。","中军置酒饮归客，胡琴琵琶与羌笛。","纷纷暮雪下辕门，风掣红旗冻不翻。","轮台东门送君去，去时雪满天山路。","山回路转不见君，雪上空留马行处。"],"theme":"送别","theme2":["边塞征战"],"style":"绮丽","style2":["豪放"],"mood":"愁怨","mood2":[],"scene":["雪","冬"],"cats":{"抒情":["离别","伤感"],"天气":["写风","写雪"]},"theme_conf":0.33},{"uid":"6f9c734b-00ef-4d46-b30a-79ff6770c7aa","title":"长安书怀","author":"马戴","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["岐路今如此，还堪恸哭频。","关中成久客，海上老诸亲。","谷口田应废，乡山草又春。","年年销壮志，空作献书人。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["春","山"],"cats":{"抒情":["思乡"],"四季":["春天"],"人生":["励志","梦想"]},"theme_conf":1.0},{"uid":"f0d11fd0-26d2-4608-aeb0-dc841b80470b","title":"瀑布","author":"章孝标","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["秋河溢长空，天洒万丈布。","深雷隐云壑，孤电挂岩树。","沧溟晓喷寒，碧落晴荡素。","非趋下流急，势使不得住。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["山","秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["瀑布"]},"theme_conf":1.0},{"uid":"2e8ddf82-3bbc-49aa-ac97-2abdd2cd760a","title":"相和歌辞 懊恼曲","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["藕丝作线难胜针，蘂粉染黄那得深。","玉白兰芳不相顾，倡楼一笑轻千金。","莫言自古皆如此，健劒刜钟铅绕指。","三秋庭绿尽迎霜，惟有荷花守红死。","西江小吏朱斑轮，柳缕吐芽香玉春。","两股金钗已相许，不令独作空城尘。","悠悠楚水流如马，恨紫愁红满平野。","野土千年怨不平，至今烧作鸳鸯瓦。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":["沉郁","旷达"],"mood":"愁怨","mood2":[],"scene":["花","秋"],"cats":{"抒情":["爱情","伤感"],"四季":["秋天"]},"theme_conf":1.0},{"uid":"4cf19354-4c0a-4e55-980b-69fa7f81ed0f","title":"游子吟","author":"孟郊","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["慈母手中线，游子身上衣。","临行密密缝，意恐迟迟归。","谁言寸草心，报得三春晖。"],"theme":"亲情","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"抒情":["感恩"],"四季":["春天"],"人物":["母亲"]},"theme_conf":0.845},{"uid":"cp54f371b40dff60","title":"忆少年","author":"晁补之","dynasty":"宋","section":"宋词","form":"词","paragraphs":["无穷官柳，无情画舸，无根行客。","南山尚相送，只高城人隔。","罨画园林溪绀碧。","算重来、尽成陈迹。","刘郎鬓如此，况桃花颜色。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["舟","山","园林"],"cats":{"抒情":["思念"],"人生":["青春"]},"theme_conf":0.538},{"uid":"55b11522-995c-490d-ada6-d82404b72473","title":"相和歌辞 大堤曲","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["二八婵娟大堤女，开𬬻相对依江渚。","待客登楼向水看，邀郎卷幔临花语。","细雨蒙蒙湿芰荷，巴东商侣挂帆多。","自传芳酒涴红袖，谁调妍妆回翠蛾。","珍簟华灯夕阳后，当𬬻理瑟矜纤手。","月落星微五鼓声，春风摇荡窗前柳。","岁岁逢迎沙岸间，北人多识绿云鬟。","无端嫁与五陵少，离别烟波伤玉颜。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["豪放","婉约"],"mood":"惆怅","mood2":[],"scene":["江","雨","花"],"cats":{"抒情":["离别","闺怨"],"天气":["写雨","月亮"],"节日":["中秋节"]},"theme_conf":0.62},{"uid":"b541e528-83cc-4c89-9990-94fda479abdb","title":"留别郑三韦九兼洛下诸公","author":"高适","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["忆昨相逢论久要，顾君哂我轻常调。","羁旅虽同白社游，诗书已作青云料。","蹇质蹉跎竟不成，年过四十尚躬耕。","长歌达者桮中物，大笑前人身后名。","幸逢明盛多招隐，高山大泽征求尽。","此时亦得辞渔樵，青袍裹身荷圣朝。","犂牛钓竿不复见，县人邑吏来相邀。","远路鸣蝉秋兴发，华堂美酒离忧销。","不知何日更携手，应念兹晨去折腰。"],"theme":"送别","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"相思","mood2":["欢愉"],"scene":["秋","酒"],"cats":{"抒情":["离别","思念"],"四季":["秋天"],"人生":["读书"],"生活":["田野"]},"theme_conf":0.432},{"uid":"cp8d4d1ee0e7ab9c","title":"应天长","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["条风布暖，霏雾弄晴，池塘遍满春色。","正是夜堂无月，沈沈暗寒食。","梁间燕，前社客。","似笑我、闭门愁寂。","乱花过，隔院芸香，满地狼藉。","长记那回时，邂逅相逢，郊外驻油壁。","又见汉宫传烛，飞烟五候宅。","青青草，迷路陌。","强带酒，细寻前迹。","市桥远，柳下人家，犹自相识。"],"theme":"节令风俗","theme2":["羁旅思乡","咏史怀古"],"style":"婉约","style2":["清新","冲淡"],"mood":"孤寂","mood2":["愁怨","欢愉"],"scene":["清明","园林","花","春","酒","夜"],"cats":{"抒情":["思乡","伤感","怀古"],"四季":["春天"],"生活":["写桥"],"节日":["寒食节","清明节"]},"theme_conf":0.68},{"uid":"3f218bb2-5f46-423d-869b-fa166ac8ba49","title":"秋灯对雨寄史近崔积","author":"武元衡","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["坐听宫城传晚漏，起看衰叶下寒枝。","空庭绿草结离念，细雨黄花赠所思。","蟋蟀已惊良节度，茱萸偏忆故人期。","相逢莫厌尊前醉，春去秋来自不知。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["雨","秋"],"cats":{"抒情":["友情","思念"],"四季":["秋天"],"天气":["写雨"],"节日":["元宵节","重阳节"]},"theme_conf":0.95},{"uid":"afa0d6db-b93a-4e96-aae9-59ec920eb6de","title":"杂曲歌辞 游子吟","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["故枥思疲马，故巢思迷禽。","浮云蔽我乡，踯躅游子吟。","游子悲久滞，浮云郁东岑。","客堂无丝桐，落叶如秋霖。","艰哉远游子，所以悲滞淫。","一为浮云词，愤塞谁能禁。","驰晖百年内，惟愿展所钦。","胡为不归欤，坐使年病侵。","未老霜遶鬓，非狂火烧心。","太行何艰哉？北斗不可斟。","夜晴星河出，耿耿辰与参。","佳人敻青天，尺素重于金。","泬寥群动异，眇默诸境森。","苔衣上闲阶，蜻蛚催寒砧。","立身计几误，道险无容针。","三年不还家，万里遗锦衾。","梦魂无重阻，离忧因古今。","胡为不归欤，孤负丘中琴。","腰下是何物？牵缠旷登寻。","朝与名山期，夕宿楚水阴。","楚水殊演漾，名山杳岖嵚。","客从洞庭来，婉娈潇湘深。","橘柚在南国，鸿雁遗秋音。","下有碧草洲，上有青橘林。","引烛窥洞穴，凌波睥天琛。","蒲荷影参差，凫鹤雏淋涔。","浩歌惜芳杜，散发轻华簪。","胡为不归欤，泪下沾衣襟。","鸢飞戾霄汉，蝼蚁制鳣鱏。","赫赫大圣朝，日月光照临。","圣主虽启迪，奇人分堙沈。","层城发云韶，玉府锵球琳。","鹿鸣志丰草，况复虞人箴。"],"theme":"羁旅思乡","theme2":["山水田园","亲情"],"style":"沉郁","style2":["豪放","绮丽"],"mood":"愁怨","mood2":["悲怆","孤寂"],"scene":["秋","江","月"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["秋天"],"天气":["写云","星星"],"人物":["女子"]},"theme_conf":0.291},{"uid":"cee17360-6fa9-4406-9794-394ac59be538","title":"横吹曲辞 梅花落","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["铁骑几时回，金闺怨早梅。","雪中花已落，风暖叶应开。","夕逐新春管，香迎小岁杯。","感时何足贵，书里报轮台。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["花","冬"],"cats":{"抒情":["闺怨"],"植物":["梅花"]},"theme_conf":0.519},{"uid":"3fa3ea71-5f33-42c7-8b83-2b96734e20cd","title":"戏赠韩判官绅卿","author":"李端","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["少寻道士居嵩岭，晚事高僧住沃洲。","齿发未知何处老，身名且被外人愁。","欲随山水居茅洞，已有田园在虎丘。","独怪子猷缘掌马，雪时不肯更乘舟。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"沉郁","style2":["幽峭"],"mood":"愁怨","mood2":["孤寂"],"scene":["山","雪","舟"],"cats":{"抒情":["伤感","孤独"],"生活":["田野"]},"theme_conf":0.9},{"uid":"fc228c0d-4d2a-45a3-a137-a3ca03b5d7f0","title":"与从弟瑾同下第后出关言别 四","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["谁怜苦志已三冬，却欲躬耕学老农。","流水白云寻不尽，期君何处得相逢。"],"theme":"送别","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["冬"],"cats":{"抒情":["离别"],"四季":["冬天"],"生活":["田野"]},"theme_conf":0.476},{"uid":"3c6b2b9c-7570-4a5a-8635-1857e0a01c9b","title":"别青州妓段东美 二","author":"薛宜僚","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["阿母桃花方似锦，王孙草色正如烟。","不须更向沧溟望，惆怅欢情恰一年。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":["欢愉"],"scene":[],"cats":{"抒情":["离别"],"人物":["母亲"]},"theme_conf":1.0},{"uid":"1eb3241e-272e-4183-801d-b37e6beb048f","title":"拟娼楼节怨","author":"刘方平","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["上苑离离莺度，昆明幂幂蒲生。","时光春华可惜，何须对镜含情。"],"theme":"闺情宫怨","theme2":["送别"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["楼","春"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"人生":["时光"]},"theme_conf":0.544},{"uid":"2188f98e-d5f0-4740-b94b-e1497a3619ee","title":"黄鹤楼","author":"崔颢","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["昔人已乘白云去，此地空余黄鹤楼。","黄鹤一去不复返，白云千载空悠悠。","晴川历历汉阳树，春草萋萋鹦鹉洲。","日暮乡关何处是，烟波江上使人愁。"],"theme":"羁旅思乡","theme2":["咏史怀古"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["惆怅"],"scene":["楼","江","鸟"],"cats":{"抒情":["思乡","伤感","怀古"],"天气":["写云"],"动物":["写鸟"]},"theme_conf":0.443},{"uid":"ab4b1a7f-4fbe-438b-817f-9e1ed2d39f4f","title":"宫词","author":"朱庆余","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["寂寂花时闭院门，美人相并立琼轩。","含情欲说宫中事，鹦鹉前头不敢言。"],"theme":"闺情宫怨","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["园林"],"cats":{"抒情":["闺怨"],"人物":["女子"]},"theme_conf":1.0},{"uid":"22624fe3-d419-451c-81e0-51d4be56e014","title":"长江二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["众水会涪万，瞿塘争一门。","朝宗人共挹，盗贼尔谁尊。","孤石隐如马，高萝垂饮猨。","归心异波浪，何事即飞飜。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["思乡","孤独"],"山水":["长江"]},"theme_conf":1.0},{"uid":"35f446ec-9bd1-4df3-bb94-7b3b45888f24","title":"新乐府 缭绫\t\t念女工之劳也","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["缭绫缭绫何所似，不似罗绡与纨绮。","应似天台山上月明前，四十五尺瀑布泉。","中有文章又奇绝，地铺白烟花簇雪。","织者何人衣者谁，越溪寒女汉宫姬。","去年中使宣口敕，天上取样人间织。","织为云外秋雁行，染作江南春水色。","广裁衫袖长制帬，金斗熨波刀翦纹。","异彩奇文相隐映，转侧看花花不定。","昭阳舞人恩正深，春衣一对直千金。","汗沾粉污不再著，曳土蹋泥无惜心。","缭绫织成费功绩，莫比寻常缯与帛。","丝细缲多女手疼，扎扎千声不盈尺。","昭阳殿里歌舞人，若见织时应也惜。"],"theme":"山水田园","theme2":["闺情宫怨"],"style":"绮丽","style2":["幽峭"],"mood":"欢愉","mood2":[],"scene":["江南"],"cats":{"抒情":["闺怨"],"山水":["瀑布"]},"theme_conf":0.585},{"uid":"a4856804-965c-40d0-a54d-5379ace1d95c","title":"陪王使君晦日泛江就黄家亭子二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["山豁何时断，江平不肯流。","稍知花改岸，始验鸟随舟。","结束多红粉，欢娱恨白头。","非君爱人客，晦日更添愁。"],"theme":"羁旅思乡","theme2":["送别"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["江"],"cats":{"抒情":["思乡","伤感"],"山水":["江河"],"天气":["太阳"]},"theme_conf":0.634},{"uid":"cpec064f31d7955a","title":"青门引・青门饮","author":"张先","dynasty":"宋","section":"宋词","form":"词","paragraphs":["乍暖还轻冷。","风雨晚来方定。","庭轩寂寞近清明，残花中酒，又是去年病。","楼头画角风吹醒。","入夜重门静。","那堪更被明月，隔墙送过秋千影。"],"theme":"闺情宫怨","theme2":["送别"],"style":"冲淡","style2":["沉郁"],"mood":"孤寂","mood2":["恬淡"],"scene":["月","雨","清明","楼","夜"],"cats":{"抒情":["孤独","闺怨"],"天气":["月亮"],"节日":["清明节"]},"theme_conf":0.66},{"uid":"ebb316eb-28f4-4a18-9eb2-07ccf943a7eb","title":"送少微上人东南游","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["石梁人不到，独往更迢迢。","乞食山家少，寻钟野寺遥。","松门风自扫，瀑布雪难消。","秋夜闻清梵，余音逐海潮。"],"theme":"送别","theme2":["哲理悟道"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["夜","雪","秋","山","江"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["瀑布"]},"theme_conf":0.511},{"uid":"6367bd53-1d65-492f-afae-57db79e5c812","title":"舟中寒食","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["寒食空江曲，孤舟渺水前。","鬬鸡沙鸟异，禁火岸花然。","日霁开愁望，波喧警醉眠。","因看数茎鬓，倍欲惜芳年。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"孤寂","mood2":[],"scene":["清明","舟"],"cats":{"抒情":["思乡","孤独"],"节日":["寒食节","清明节"]},"theme_conf":0.75},{"uid":"238e54b0-be71-449d-8184-a084c2769f0a","title":"杂曲歌辞 昔昔盐 垂柳覆金堤","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["新年垂柳色，袅袅对空闺。","不畏芳菲好，自缘离别嗁。","因风飘玉户，向日映金堤。","驿使何时度？还将赠陇西。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["春"],"cats":{"抒情":["离别"],"节日":["春节"],"植物":["柳树"]},"theme_conf":0.607},{"uid":"96a483bc-6822-490e-a891-e13f609af452","title":"奉使采箭簳竹谷中晨兴赴岭","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["孤客倦夜坐，闻猨乘早发。","背溪已斜汉，登栈尚残月。","重峰转森爽，幽步更超越。","云木耸鹤巢，风萝扫虎穴。","人群从自远，世役终难歇。","入山非买山，采竹异采蕨。","谁见子牟意，悁劳书魏阙。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["山"],"cats":{"抒情":["孤独"],"植物":["竹子"]},"theme_conf":0.85},{"uid":"39b2954c-04df-4561-ad6e-f4ddbae0db1e","title":"行经华阴","author":"崔颢","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["岧嶤太华俯咸京，天外三峰削不成。","武帝祠前云欲散，仙人掌上雨初晴。","河山北枕秦关险，驿树西连汉畤平。","借问路傍名利客，无如此处学长生。"],"theme":"山水田园","theme2":["羁旅思乡","咏史怀古"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["山","雨"],"cats":{"抒情":["思乡","怀古"]},"theme_conf":0.37},{"uid":"827e44b1-7064-4ff7-9a9c-192eece94e2d","title":"韦讽录事宅观曹将军画马图","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["国初已来画鞍马，神妙独数江都王。","将军得名三十载，人间又见真乘黄。","曾貌先帝照夜白，龙池十日飞霹雳。","内府殷红马脑盌，倢伃传诏才人索。","盌赐将军拜舞归，轻纨细绮相追飞。","贵戚权门得笔迹，始觉屏障生光辉。","昔日太宗拳毛䯄，近时郭家师子花。","今之新图有二马，复令识者久叹嗟。","此皆骑战一敌万，缟素漠漠开风沙。","其余七匹亦殊绝，迥若寒空动烟雪。","霜蹄蹴踏长楸间，马官厮养森成列。","可怜九马争神骏，顾视清高气深稳。","借问苦心爱者谁，后有韦讽前支遁。","忆昔巡幸新丰宫，翠华拂天来向东。","腾骧磊落三万匹，皆与此图筋骨同。","自从献宝朝河宗，无复射蛟江水中。","君不见金粟堆前松柏里，龙媒去尽鸟呼风。"],"theme":"边塞征战","theme2":["题画咏艺"],"style":"绮丽","style2":["清新"],"mood":"孤寂","mood2":["相思"],"scene":["雪","塞外"],"cats":{"抒情":["思念","孤独"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.481},{"uid":"5ccd5188-0e5d-450e-8ec5-d6e661fac4f7","title":"没蕃故人","author":"张籍","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["前年伐月支，城上没全师。","蕃汉断消息，死生长别离。","无人收废帐，归马识残旗。","欲祭疑君在，天涯哭此时。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["相思"],"scene":["月"],"cats":{"抒情":["友情","离别"]},"theme_conf":0.786},{"uid":"cp96c41b444b7052","title":"幺・故人一去无音信，望篷莱隔几重云。燕未归，春将尽，梨花庭院，和","author":"张可久","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["月掩朱门。","秋思酸斋索赋鸳鸯飞起藕花洲，碧水明秋。","玉人天际认归舟，秋来后，憔悴见花羞。"],"theme":"爱情相思","theme2":["送别","讽喻刺世","山水田园"],"style":"清新","style2":["婉约"],"mood":"相思","mood2":[],"scene":["园林","春","花"],"cats":{"抒情":["爱情","友情"],"四季":["春天"],"动物":["写鸟"],"植物":["梨花"]},"theme_conf":0.284},{"uid":"cp1061a9efb70635","title":"踏莎行","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["燕燕轻盈，莺莺娇软。","分明又向华胥见。","夜长争得薄情知，春初早被相思染。","别后书辞，别时针线。","离魂暗逐郎行远。","淮南皓月冷千山，冥冥归去无人管。"],"theme":"送别","theme2":["爱情相思"],"style":"婉约","style2":["清新"],"mood":"相思","mood2":[],"scene":["春","鸟"],"cats":{"抒情":["爱情","离别","思念"],"四季":["春天"]},"theme_conf":0.631},{"uid":"cpead5ea21c5d00e","title":"六州歌头","author":"韩元吉","dynasty":"宋","section":"宋词","form":"词","paragraphs":["东风著意。","先上小桃枝。","红粉腻。","娇如醉。","倚朱扉。","记年时。","隐映新妆，面临水岸。","春将半。","云日暖。","斜桥转。","夹城西。","草软莎平跋马，垂杨渡、玉勒争嘶。","认蛾眉凝笑，脸薄拂燕支。","绣户曾窥。","恨依依。","共携手处。","香如雾。","红随步。","怨春迟。","消瘦损。","凭谁问。","只花知。","泪空垂。","旧日堂前燕，和烟雨，又双飞。","人自老。","春长好。","梦佳期。","前度刘郎，几许风流地，花也应悲。","但茫茫暮霭，目断武陵溪。","往事难追。"],"theme":"咏物","theme2":["爱情相思","山水田园","咏史怀古"],"style":"沉郁","style2":["婉约","绮丽"],"mood":"愁怨","mood2":[],"scene":["春","花"],"cats":{"抒情":["伤感","怀古"],"四季":["春天"],"生活":["写桥"]},"theme_conf":0.75},{"uid":"cf98fca8-9bf1-4af4-bd35-e51bfe7f09ed","title":"酬谢韦卿二十五兄俯赠輙敢书情","author":"窦庠","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["大贤持赠一明珰，蓬荜初惊满室光。","埋没剑中生紫气，尘埃瑟上动清商。","荆山璞在终应识，楚国人知不是狂。","莫恨伏辕身未老，会将筋力是王良。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["沉郁"],"mood":"慷慨","mood2":["愁怨"],"scene":["山"],"cats":{"抒情":["感恩"]},"theme_conf":0.94},{"uid":"a2a74e95-00c2-4dce-a38e-6a4ec4a8923d","title":"赠别张驸马","author":"戎昱","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["上元年中长安陌，见君朝下欲归宅。","飞龙骑马三十匹，玉勒雕鞍照初日。","数里衣香遥扑人，长衢雨歇无纤尘。","从奴斜抱𠡠赐锦，双双蹙出金麒麟。","天子爱壻皇后弟，独步明时负权势。","一身扈跸承殊泽，甲第朱门耸高戟。","凤凰楼上伴吹箫，鹦鹉杯中醉留客。","泰去否来何足论，宫中晏驾人事翻。","一朝负谴辞丹阙，五年待罪湘江源。","冠冕凄凉几迁改，眼看桑田变成海。","华堂金屋别赐人，细眼黄头总何在。","渚宫相见寸心悲，嬾欲今时问昔时。","看君风骨殊未歇，不用愁来双泪垂。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["酒","元宵","江"],"cats":{"抒情":["离别","伤感"],"节日":["元宵节"],"动物":["写马"]},"theme_conf":0.579},{"uid":"39b2b613-94a2-492b-aaaa-cee6c34a6c41","title":"鼓吹曲辞 芳树","author":"徐彦伯","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["玉花珍簟上，金缕画屏开。","晓月怜筝柱，春风忆镜台。","筝柱春风吹晓月，芳树落花朝暝歇。","藳砧刀头未有时，攀条拭泪坐相思。"],"theme":"爱情相思","theme2":["节令风俗"],"style":"绮丽","style2":["婉约","沉郁"],"mood":"相思","mood2":[],"scene":["花"],"cats":{"抒情":["爱情","思念"]},"theme_conf":0.517},{"uid":"e0b629da-76cc-4223-98b8-25fad7f63656","title":"忆寿春废虎坑余以春二月至郡主吏举所职称霍山多虎每岁采茶为患择肉于人至春常修陷穽数十所勒猎者采其皮睛余悉除罢之是岁虎不复为害至余去郡三载","author":"李绅","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["匪将履尾求兢惕，那效探雏所患争。","当路绝群尝诫暴，为猫驱狝亦先迎。","每推至化宣余力，岂用潜机害尔生。","休逐豺狼止贪戾，好为仁兽答皇明。"],"theme":"咏物","theme2":["边塞征战","送别","山水田园"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["春","月","山"],"cats":{"抒情":["思念"],"四季":["春天"],"天气":["月亮"],"食物":["写茶"]},"theme_conf":0.65},{"uid":"ed79f9bc-d5d1-4251-b22d-d091e0758a3f","title":"无题","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["相见时难别亦难，东风无力百花残。","春蚕到死丝方尽，蜡炬成灰泪始干。","晓镜但愁云鬓改，夜吟应觉月光寒。","蓬山此去无多路，青鸟殷勤为探看。"],"theme":"爱情相思","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["月","春"],"cats":{"抒情":["伤感"],"四季":["春天"]},"theme_conf":0.691},{"uid":"912f6639-a774-4d02-8c17-07f6bc3b1d63","title":"送大理张卿","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["春色依依惜解携，月卿今夜泊隋堤。","白沙洲上江篱长，绿树村边谢豹啼。","迁客比来无倚仗，故人相去隔云泥。","越禽唯有南枝分，目送孤鸿飞向西。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["江","春","月","夜"],"cats":{"抒情":["友情","孤独"],"四季":["春天"],"生活":["乡村"]},"theme_conf":0.783},{"uid":"8585ac55-69dd-47ef-92b8-006e47054cc2","title":"长沙九日登东楼观舞 二","author":"李群玉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["慢态不能穷，繁姿曲向终。","低回莲破浪，凌乱雪萦风。","坠珥时流盻，修裾欲溯空。","唯愁捉不住，飞去逐惊鸿。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["惆怅"],"scene":["楼","重阳","雪"],"cats":{"抒情":["伤感"],"人生":["励志"],"节日":["重阳节"]},"theme_conf":0.553},{"uid":"49194c4b-b775-4d21-a506-fc0a2ff308f1","title":"相和歌辞 子夜四时歌四首 秋歌","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["长安一片月，万户捣衣声。","秋风吹不尽，总是玉关情。","何日平胡虏？良人罢远征。"],"theme":"闺情宫怨","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["秋","月"],"cats":{"抒情":["思念","闺怨"],"四季":["秋天"]},"theme_conf":0.576},{"uid":"15a04b03-7a41-4faa-9e46-c8d6fb228bb0","title":"涉沅潇","author":"李绅","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["屈原死处潇湘阴，沧浪淼淼云沈沈。","蛟龙长怒虎长啸，山木翛翛波浪深。","烟横日落惊鸿起，山映余霞杳千里。","鸿叫离离入暮天，霞消漠漠深云水。","水灵江暗扬波涛，鼋鼍动荡风骚骚。","行人愁望待明月，星汉沈浮𩲒鬼号。","屈原尔为怀王没，水府通天化灵物。","何不驱雷击电除奸邪，可怜空作沈泉骨。","举杯沥酒招尔魂，月影滉漾开乾坤。","波白水黑山隐见，汨罗之上遥昏昏。","风帆候晓看五两，戍鼓冬冬远山响。","潮满江津猨鸟啼，荆夫楚语飞蛮桨。","潇湘岛浦无人居，风惊水暗惟鲛鱼。","行来击棹独长叹，问尔精魄何所如。"],"theme":"山水田园","theme2":["边塞征战"],"style":"豪放","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["端午","月","酒","舟","江"],"cats":{"抒情":["孤独"],"天气":["月亮"],"节日":["端午节"]},"theme_conf":0.58},{"uid":"3d7fc8a1-0d5c-4a78-924c-01b1889059f8","title":"相和歌辞 登高丘而望远","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["登高丘而望远海，六鼇骨已霜，三山流安在。","扶桑半摧折，白日沈光彩。","银台金阙如梦中，秦皇汉武空相待。","精卫费木石，鼋鼍无所凭。","君不见骊山茂陵尽灰灭，牧羊之子来攀登。","盗贼劫宝玉，精灵竟何能。"],"theme":"咏史怀古","theme2":[],"style":"冲淡","style2":["绮丽"],"mood":"相思","mood2":[],"scene":["重阳"],"cats":{"抒情":["思念","怀古"],"节日":["重阳节"]},"theme_conf":0.762},{"uid":"4ac3f099-73da-43e8-a4e5-1dbbd9427491","title":"闺怨","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["闺中少妇不曾愁，春日凝妆上翠楼。","忽见陌头杨柳色，悔教夫壻觅封侯。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"]},"theme_conf":1.0},{"uid":"e5949236-b878-4ef5-aa53-445651fb04ac","title":"情人玉清歌","author":"毕耀","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["洛阳有人名玉清，可怜玉清如其名。","善踏斜柯能独立，婵娟花艳无人及。","珠为帬，玉为缨，临春风，吹玉笙。","悠悠满天星，黄金阁上晚妆成。","云和曲中为曼声，玉梯不得蹈。","摇袂两盈盈，城头之日复何情。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["中秋","春"],"cats":{"抒情":["孤独"],"四季":["春天"],"节日":["中秋节"]},"theme_conf":0.68},{"uid":"c5b74274-de21-482b-ae7a-b0d8200bbb18","title":"琴曲歌辞 湘妃","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["帝子不可见，秋风来暮思。","婵娟湘江月，千载空蛾眉。"],"theme":"咏史怀古","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["中秋","秋","月","江"],"cats":{"抒情":["怀古"],"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.86},{"uid":"2ac203a8-6e70-4b78-ad75-9acacae9b04a","title":"相和歌辞  北上行","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["北上何所苦，北上缘太行。","磴道盘且峻，巉岩凌穹苍。","马足蹶侧石，车轮摧高冈。","沙尘接幽州，烽火连朔方。","杀气毒劒戟，严风裂衣裳。","奔鲸夹黄河，凿齿屯洛阳。","前行无归日，返顾思旧乡。","惨戚冰雪里，悲号绝中肠。","尺布不掩体，皮肤剧枯桑。","汲水涧谷阻，采薪陇坂长。","猛虎又掉尾，磨牙皓秋霜。","草木不可湌，饥饮零露浆。","叹此北上苦，停骖为之伤。","何日王道平？开颜覩天光。"],"theme":"边塞征战","theme2":["民生疾苦","山水田园","羁旅思乡"],"style":"豪放","style2":[],"mood":"相思","mood2":["悲怆"],"scene":["秋","冬","江","雪"],"cats":{"抒情":["思念","思乡","伤感"],"四季":["秋天"],"山水":["黄河"],"天气":["写雪"],"人生":["战争"]},"theme_conf":0.296},{"uid":"b0f61bf4-5c31-4875-a33f-97de1a1560d2","title":"浪淘沙九首 一","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["九曲黄河万里沙，浪淘风簸自天涯。","如今直上银河去，同到牵牛织女家。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["江","七夕"],"cats":{"抒情":["思乡"],"山水":["黄河"],"天气":["星星"],"节日":["七夕节"]},"theme_conf":0.551},{"uid":"86f844a6-969b-4af7-be73-b1c12c0cd7fb","title":"九日五首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["重阳独酌杯中酒，抱病起登江上台。","竹叶于人既无分，菊花从此不须开。","殊方日落玄猨哭，旧国霜前白雁来。","弟妹萧条各何往，干戈衰谢两相催。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":["悲怆","孤寂"],"scene":["重阳","酒"],"cats":{"抒情":["思乡","孤独"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.8},{"uid":"212bf433-f47a-4f05-84d1-172804896869","title":"三川观水涨二十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["我经华原来，不复见平陆。","北上唯土山，连山走穷谷。","火云无时出，飞电常在目。","自多穷岫雨，行潦相豗蹙。","蓊匌川气黄，群流会空曲。","清晨望高浪，忽谓阴崖踣。","恐泥窜蛟龙，登危聚麋鹿。","枯查卷拔树，礧磈共充塞。","声吹鬼神下，势阅人代速。","不有万穴归，何以尊四渎。","及观泉源涨，反惧江海覆。","漂沙坼岸去，漱壑松柏秃。","乘陵破山门，回斡裂地轴。","交洛赴洪河，及关岂信宿。","应沈数州没，如听万室哭。","秽浊殊未清，风涛怒犹蓄。","何时通舟车，阴气不黪黩。","浮生有荡汨，吾道正羁束。","人寰难容身，石壁滑侧足。","云雷此不已，艰险路更跼。","普天无川梁，欲济愿水缩。","因悲中林士，未脱众鱼腹。","举头向苍天，安得骑鸿鹄。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":["雄浑"],"mood":"悲怆","mood2":[],"scene":["山"],"cats":{"抒情":["伤感"],"人生":["梦想"]},"theme_conf":0.579},{"uid":"23073075-096d-449e-8467-acb59dbe4d9c","title":"赠别上元主簿张著","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["上书一见平津侯，劒笏斜齐秣陵尉。","朝垂绶带迎远客，暮锁印囊飞上吏。","长乐花深万井时，同官无事有归期。","回船对酒三生渚，系马焚香五愿祠。","日日澄江带山翠，绿芳都在经过地。","行人看射领军堂，游女题诗光宅寺。","风流才调爱君偏，此别相逢定几年。","惆怅浮云迷远道，张侯楼上月娟娟。"],"theme":"送别","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":["欢愉"],"scene":["元宵","花"],"cats":{"抒情":["离别"],"节日":["元宵节"]},"theme_conf":0.557},{"uid":"8721c066-db42-44da-be87-a1a76680992b","title":"别尹炼师","author":"李群玉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["吾家五千言，至道悬日月。","若非函谷令，谁注流沙说。","多君飞升志，机悟独超拔。","学道玉笥山，烧丹白云穴。","南穷衡疑秀，采药历幽绝。","夜卧瀑布风，朝行碧岩雪。","洞宫四百日，玉籍恣探阅。","徒以菌蟪姿，缅攀修真诀。","尘笼罩浮世，遐思空飞越。","一罢棋酒欢，离情满寥泬。","愿骑紫盖鹤，早向黄金阙。","城市不可留，尘埃秽仙骨。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["山","雪","酒"],"cats":{"抒情":["离别","孤独"],"山水":["瀑布"]},"theme_conf":0.576},{"uid":"46bf764a-2ccb-479c-991b-e83fc8966b16","title":"题汉州西湖","author":"严公弼","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["西湖创置自房公，心匠纵横造化同。","见说凤池推独步，高名何事滞川中。"],"theme":"咏物","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["江南","江"],"cats":{"抒情":["孤独"],"山水":["西湖"]},"theme_conf":1.0},{"uid":"bcd31207-66ec-44c9-9890-1c70b6e8ea69","title":"相和歌辞 挽歌二首 一","author":"于鹄","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["阴风吹黄蒿，挽歌渡秋水。","车马却归城，孤坟月明里。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","月"],"cats":{"抒情":["孤独","悼亡"],"四季":["秋天"]},"theme_conf":0.98},{"uid":"2ef10f56-c14a-40e7-bf35-c91dc8c61f89","title":"奉和七夕宴悬圃应制二首 二","author":"许敬宗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["婺闺期今夕，娥轮泛浅潢。","迎秋伴暮雨，待暝合神光。","荐寝低云鬓，呈态解霓裳。","喜中愁漏促，别后怨天长。"],"theme":"应制干谒","theme2":["节令风俗"],"style":"沉郁","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["七夕"],"cats":{"抒情":["伤感"],"节日":["七夕节"]},"theme_conf":0.98},{"uid":"5a429d13-1d1b-4a15-9823-4abea75b9fa4","title":"闻庆州赵纵使君与党项战中箭身死辄书长句","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["将军独乘铁骢马，榆溪战中金仆姑。","死绥却是古来有，骁将自惊今日无。","青史文章争点笔，朱门歌舞笑捐躯。","谁知我亦轻生者，不得君王丈二殳。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"悲怆","mood2":[],"scene":[],"cats":{"抒情":["爱国"],"人生":["战争"]},"theme_conf":0.639},{"uid":"eb5774b6-2822-479b-92ab-c4028ec564bd","title":"送张淑归觐叔父","author":"李端","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["日惨长亭暮，天高大泽闲。","风中闻草木，雪里见江山。","马向塞云去，人随古道还。","阮家今夜乐，应在竹林间。"],"theme":"送别","theme2":[],"style":"雄浑","style2":[],"mood":"恬淡","mood2":["欢愉"],"scene":["塞外","雪","夜","江","山"],"cats":{"抒情":["离别"],"人物":["父亲"]},"theme_conf":0.443},{"uid":"f1320c1f-949a-4cbe-ad23-4806878632c5","title":"杂曲歌辞 婆罗门","author":"杨敬述进","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["回乐峰前沙似雪，受降城外月如霜。","不知何处吹芦管？一夜征人尽望乡。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["月","冬"],"cats":{"抒情":["思乡"]},"theme_conf":0.62},{"uid":"1f66d2ec-8418-485e-a434-e21a0d439dda","title":"杂曲歌辞 秋夜曲","author":"王涯","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["桂魄初生秋露微，轻罗已薄未更衣。","银筝夜久殷勤弄，心怯空房不忍归。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":["清新"],"mood":"相思","mood2":[],"scene":["秋","夜"],"cats":{"抒情":["闺怨"],"四季":["秋天"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"655e4998-5575-47e5-b386-655ace27fc36","title":"梨花","author":"温宪","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["绿阴寒食晚，犹自满空园。","两歇芳菲白，蜂稀寂寞繁。","一枝横野路，数树出江村。","怅望频回首，何人共酒尊。","（《古今图书集成·草木典·梨部》（见宋陈景沂《全芳备祖前集》卷九《梨花》。","「蜂稀」，《全芳备祖》作「蜂声」。","）。"],"theme":"咏物","theme2":["咏物","闲适隐逸"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["花","清明"],"cats":{"抒情":["孤独"],"节日":["寒食节","清明节"],"植物":["梨花"]},"theme_conf":0.86},{"uid":"e16cb386-9a1c-463f-a43f-2110e2a36e33","title":"杂曲歌辞 少年行四首 一","author":"王维","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["新丰美酒斗十千，咸阳游侠多少年。","相逢意气为君饮，系马高楼垂柳边。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"慷慨","mood2":[],"scene":["酒","楼"],"cats":{"抒情":["思乡"],"人生":["青春"]},"theme_conf":0.65},{"uid":"2036833d-b04f-49fe-b709-3eccd090f147","title":"相和歌辞 采莲曲二首 一","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["虽听采莲曲，讵识采莲心。","漾檝爱花远，回船愁浪深。","烟生极浦色，日落半江阴。","同侣怜波静，看妆堕玉簪。"],"theme":"爱情相思","theme2":[],"style":"冲淡","style2":[],"mood":"愁怨","mood2":["恬淡"],"scene":["舟","江"],"cats":{"抒情":["伤感"],"植物":["荷花"]},"theme_conf":0.657},{"uid":"dd52aa19-bfdc-4169-9aca-f3cccb0e993c","title":"上元夜忆长安","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["沧州老一年，老去忆秦川。","处处逢珠翠，家家听管弦。","云车龙阙下，火树凤楼前。","今夜沧州夜，沧州夜月圆。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["元宵","夜"],"cats":{"抒情":["思念","思乡"],"节日":["元宵节"]},"theme_conf":0.82},{"uid":"44f744e6-ab04-4af4-82e9-5a28fe9142a2","title":"县中池竹言怀","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["官小志已足，时清免负薪。","卑栖且得地，荣耀不关身。","自爱赏心处，丛篁流水滨。","荷香度高枕，山色满南邻。","道在即为乐，机忘宁厌贫。","却愁丹凤诏，来访漆园人。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["园林"],"cats":{"抒情":["伤感"],"植物":["竹子"]},"theme_conf":1.0},{"uid":"8b41c002-e220-45f6-b816-c8f499e39622","title":"述梦诗四十韵","author":"李德裕","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["赋命诚非薄，良时幸已遭。","君当尧舜日，官接凤皇曹。","目睇烟霄阔，心惊羽翼高。","椅梧连鹤禁，壀堄接龙韬。","我后怜词客，吾僚并隽髦。","著书同陆贾，待诏比王褒。","重价连悬璧，英词淬宝刀。","泉流初落涧，露滴更濡毫。","赤豹欣来献，彤弓喜暂櫜非烟含瑞气，驯雉洁霜毛。","静室便幽独，虚楼散郁陶。","花光晨艳艳，松韵晚骚骚。","画壁看飞鹤，仙图见巨鼇。","倚簷阴药树，落格蔓蒲桃。","荷静蓬池鲙，冰寒郢水醪。","荔枝来自远，卢橘赐仍叨。","麝气随兰泽，霜华入杏膏。","恩光惟觉重，携挈未为劳。","夕阅梨园骑，宵闻禁杖獒。","扇回交彩翟，雕起飏银绦。","辔待袁丝揽，书期蜀客操。","尽规常謇謇，退食尚忉忉。","龟顾垂金钮，鸾飞曳锦袍。","御沟杨柳弱，天廐骕骦豪。","屡换青春直，闲随上苑遨。","烟低行殿竹，风拆绕墙桃。","聚散俄成昔，悲愁益自熬。","每怀仙驾远，更望茂陵号。","地接三茅岭，川迎伍子涛。","花迷瓜步暗，石固蒜山牢。","兰野凝香管，梅洲动翠篙。","泉鱼惊彩妓，溪鸟避干旄。","感旧心犹绝，思归首更搔。","无聊燃[蜜]炬，谁复劝金舠。","岚气朝生栋，城阴夜入濠。","望烟归海峤，送鴈渡江臯。","宛马嘶寒枥，吴钩在锦弢。","未能追狡兔，空觉长黄蒿。","水国逾千里，风帆过万艘。","阅川终古恨，惟见暮滔滔。"],"theme":"咏怀抒感","theme2":["羁旅思乡"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["孤寂","相思"],"scene":["夜","鸟","园林","山","江"],"cats":{"抒情":["思乡","伤感","孤独"],"人生":["青春"],"食物":["荔枝"]},"theme_conf":0.78},{"uid":"215dbf70-fc96-41e5-80ae-edf233df30e1","title":"杂曲歌辞 出门行二首 二","author":"孟郊","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["海风萧萧天雨霜，穷愁独坐夜何长？","驱车旧忆太行险，始知游子悲故乡。","美人相思隔天阙，长望云端不可越。","手持琅玕欲有赠，爱而不见心断绝。","南山峨峨白石烂，碧海之波浩漫漫。","参辰出没不相待，我欲横天无羽翰。"],"theme":"羁旅思乡","theme2":["爱情相思","送别","亲情"],"style":"幽峭","style2":["悲慨"],"mood":"相思","mood2":[],"scene":["雨","夜"],"cats":{"抒情":["爱情","思念","思乡","伤感"],"人物":["女子"]},"theme_conf":0.319},{"uid":"0b24addb-6986-4eb1-ae0a-e7fbfb72e243","title":"祭神州乐章 雍和","author":"褚亮","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["泰圻严享，阴郊展敬。","礼以导神，乐以和性。","黝牲在列，黄琮俯暎。","九土既平，万邦贻庆。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"抒情":["怀古","爱国"]},"theme_conf":1.0},{"uid":"1fd7fb7a-8fd1-45bc-9dcb-803c52590d34","title":"横吹曲辞 折杨柳","author":"余延寿","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["大道连国门，东西种杨柳。","葳蕤君不见，褭娜垂来久。","缘枝栖暝禽，雄去雌独吟。","余花怨春尽，微月起秋阴。","坐望窗中蝶，起攀枝上叶。","好风吹长条，妸娜何如妾。","妾见柳园新，高楼四五春。","莫吹胡塞曲，愁杀陇头人。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["春","塞外","秋","月","楼"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天","秋天"],"生活":["边塞"],"植物":["柳树"]},"theme_conf":0.644},{"uid":"2fa17eef-441f-4e0f-bb10-37d2d71f601c","title":"军事院霜菊盛开因书一绝寄上谏议","author":"皮日休","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["金华千点晓霜凝，独对壶觞又不能。","已过重阳三十日，至今犹自待王弘。"],"theme":"边塞征战","theme2":["送别"],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳","秋","酒","园林"],"cats":{"抒情":["孤独"],"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.403},{"uid":"d4baf2d1-ea61-4fb3-a284-e889275bdca2","title":"杂曲歌辞 长相思三首 一","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["长相思，在长安，络纬秋啼金井栏。","微霜凄凄簟色寒，孤灯不明思欲绝。","卷帷望月空长叹，美人如花隔云端。","上有青冥之长天，下有绿水之波澜。","天长路远魂飞苦，梦魂不到关山难。","长相思，摧心肝。"],"theme":"爱情相思","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["爱情","思念"],"四季":["秋天"],"人物":["女子"]},"theme_conf":0.775},{"uid":"a06cb556-2b4d-4b1c-a52a-fcff10b7f87e","title":"杂曲歌辞 昔昔盐 空梁落燕泥","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["春至今朝燕，花时伴独嗁。","飞斜珠箔隔，语近画梁低。","帷卷闲窥户，床空暗落泥。","谁能长对此，双去复双栖。"],"theme":"闺情宫怨","theme2":[],"style":"冲淡","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["鸟"],"cats":{"抒情":["孤独","闺怨"],"动物":["写鸟"]},"theme_conf":0.92},{"uid":"a057cb3f-9d7a-44ab-8172-cdb3ebfd049a","title":"王师渡汉水经襄阳","author":"李百药","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["导漾疏源远，归海会流长。","延波接荆梦，通望迩沮漳。","高岸沈碑影，曲溆丽珠光。","云昏翠岛没，水广素涛扬。","阅川已多叹，遐睇几增伤。","临谿犹驻马，望岘欲沾裳。","乔木下寒叶，亭林落晓霜。","山公不可遇，谁与访高阳。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":["绮丽"],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["爱国"]},"theme_conf":1.0},{"uid":"4c7205af-d1e8-48ed-8220-fe095418b95a","title":"杂诗三首 二","author":"王维","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["君自故乡来，应知故乡事。","来日绮窗前，寒梅着花未。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["思乡"]},"theme_conf":0.716},{"uid":"f0d0412b-b79c-4643-a730-f980bf7e088a","title":"秋日荆南送石首薛明府辞满告别奉寄薛尚书颂德敍怀斐然之作三十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["南征为客久，西候别君初。","岁满归凫舄，秋来把雁书。","荆门留美化，姜被就离居。","闻道和亲人，垂名报国余。","连枝不日竝，八座几时除。","往者胡星孛，恭惟汉网疎。","风尘相澒洞，天地一丘墟。","殿瓦鸳鸯坼，宫帘翡翠虚。","钩陈摧徼道，枪櫐失储胥。","文物陪巡守，亲贤病拮据。","公时呵䝟貐，首唱却鲸鱼。","势惬宗萧相，材非一范雎。","尸填太行道，血走浚仪渠。","滏口师仍会，函关愤已摅。","紫微临大角，皇极正乘舆。","赏从频峨冕，殊私再直庐。","岂惟高卫霍，曾是接应徐。","降集飜翔凤，追攀绝众狙。","侍臣双宋玉，战策两穰苴。","鉴澈劳悬镜，荒芜已荷锄。","向来披述作，重此忆吹嘘。","白发甘凋丧，青云亦卷舒。","经纶功不朽，跋涉体何如。","应讶耽湖橘，常餐占野蔬。","十年婴药饵，万里狎樵渔。","扬子淹投阁，邹生惜曳裾。","但惊飞熠耀，不记改蟾蜍。","烟雨封巫峡，江淮略孟诸。","汤池虽险固，辽海尚填淤。","努力输肝胆，休烦独起予。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["豪放","幽峭"],"mood":"慷慨","mood2":[],"scene":["秋"],"cats":{"抒情":["离别","爱国"],"四季":["秋天"],"天气":["太阳"],"人生":["战争"]},"theme_conf":0.532},{"uid":"c7e721a1-9169-46c6-bbf3-970fef076539","title":"相和歌辞 铜雀妓","author":"刘商","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["魏主矜蛾眉，美人美于玉。","高台无昼夜，歌舞竟未足。","盛色如转圜，夕阳落深谷。","仍令身殁后，尚足平生欲。","红粉横泪痕，调弦空向屋。","举头君不在，唯见西陵木。","玉辇岂再来，娇鬟为谁绿。","那堪秋风里，更舞阳春曲。","曲终情不胜，阑干向西哭。","台边生野草，来去罥罗縠。","况复陵寝间，双双见麋鹿。"],"theme":"咏史怀古","theme2":[],"style":"婉约","style2":["绮丽","沉郁"],"mood":"悲怆","mood2":["愁怨"],"scene":["楼","夜","秋","春"],"cats":{"抒情":["伤感","怀古"],"四季":["春天","秋天"],"人物":["女子"]},"theme_conf":1.0},{"uid":"6f33754e-1fb7-4140-8654-d729e9254a10","title":"走笔谢孟谏议寄新茶","author":"卢仝","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["日高丈五睡正浓，军将打门惊周公。","口云谏议送书信，白绢斜封三道印。","开缄宛见谏议面，手阅月团三百片。","闻道新年入山里，蛰虫惊动春风起。","天子须尝阳羡茶，百草不敢先开花。","仁风暗结珠琲瓃，先春抽出黄金芽。","摘鲜焙芳旋封裹，至精至好且不奢。","至尊之余合王公，何事便到山人家。","柴门反关无俗客，纱帽笼头自煎吃。","碧云引风吹不断，白花浮光凝椀面。","一椀喉吻润，两椀破孤闷。","三椀搜枯肠，唯有文字五千卷。","四椀发轻汗，平生不平事。","尽向毛孔散，五椀肌骨清。","六椀通仙灵，七椀吃不得也。","唯觉两腋习习清风生，蓬莱山，在何处？","玉川子，乘此清风欲归去。","山上群仙司下土，地位清高隔风雨。","安得知百万亿苍生命，堕在巅崖受辛苦。","便为谏议问苍生，到头还得苏息否。"],"theme":"寄赠酬答","theme2":["闲适隐逸"],"style":"绮丽","style2":["清新"],"mood":"惆怅","mood2":[],"scene":["雨","花","春","山"],"cats":{"抒情":["感恩"],"四季":["春天"],"节日":["春节"],"食物":["写茶"]},"theme_conf":0.9},{"uid":"caa023cf-9f55-450c-9638-1cf5c0223cc1","title":"杂曲歌辞 长相思三首 二","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["日色已尽花含烟，月明欲素愁不眠。","赵瑟初停凤凰柱，蜀琴欲奏鸳鸯弦。","此曲有意无人传，愿随春风寄燕然，忆君迢迢隔青天。","昔日横波目，今成流泪泉。","不信妾肠断，归来看取明镜前。"],"theme":"爱情相思","theme2":[],"style":"沉郁","style2":["清新"],"mood":"相思","mood2":[],"scene":["春","月"],"cats":{"抒情":["爱情","思念","伤感"],"四季":["春天"]},"theme_conf":0.5},{"uid":"18a2aaed-39a3-4ec2-a730-4479ec0b94ec","title":"孤山寺遇雨","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["拂波云色重，洒叶雨声繁。","水鹭双飞起，风荷一向翻。","空蒙连北岸，萧飒入东轩。","或拟湖中宿，留船在寺门。"],"theme":"哲理悟道","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["雨","山"],"cats":{"抒情":["孤独"],"山水":["西湖"],"天气":["写雨"]},"theme_conf":0.564},{"uid":"bdd79ce6-205b-4c91-bf73-532087f5acfe","title":"杂曲歌辞 空城雀","author":"王建","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["空城雀，何不飞来人家住？","空城无人种禾黍。","土间生子草间长，满地蓬蒿幸无主。","近村虽有高树枝，雨中无食长苦饥。","八月小儿夹弓箭，家家畏我田头飞。","但能不出空城里，秋时百草皆有子。","黄口黄口莫啾啾，长尔得成无横死。"],"theme":"民生疾苦","theme2":["山水田园"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["秋","雨","月"],"cats":{"抒情":["孤独"],"四季":["秋天"],"人物":["儿童"]},"theme_conf":0.522},{"uid":"6f0897e1-ef12-4042-8e56-8cb1134cf9c3","title":"初秋夜坐","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["斜廊连绮阁，初月照宵帏。","塞冷鸿飞疾，园秋蝉噪迟。","露结林疎叶，寒轻菊吐滋。","愁心逢此节，长叹独含悲。"],"theme":"边塞征战","theme2":[],"style":"清新","style2":["幽峭","悲慨"],"mood":"孤寂","mood2":["愁怨","悲怆"],"scene":["秋","夜"],"cats":{"抒情":["伤感","孤独"],"四季":["秋天"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"be118ff0-566d-466d-ac07-0de6e6493419","title":"雨中宿义兴寺","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["遥夜宿东林，虫声阶草深。","高风初落叶，多雨未归心。","家国身犹负，星霜鬓已侵。","沧洲纵不去，何处有知音。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["雨"],"cats":{"抒情":["友情","思乡"],"山水":["庐山"],"天气":["写雨"]},"theme_conf":0.658},{"uid":"c59e8104-e7ec-433d-ae2f-033ba7267993","title":"伤辽东战亡","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["凿门初奉律，仗战始临戎。","振鳞方跃浪，骋翼正凌风。","未展六奇术，先亏一篑功。","防身岂乏智，殉命有余忠。"],"theme":"边塞征战","theme2":["悼亡挽歌"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":[],"cats":{"抒情":["伤感","悼亡"],"人生":["战争"]},"theme_conf":0.544},{"uid":"473617e8-f2d2-4f2a-a26d-df696f3c9890","title":"题藏公院","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["古院林公住，疎篁近井桃。","俗年人见少，禅地自知高。","药草诚多喻，沧溟在一毫。","仍悲次宗辈，尘事日为劳。"],"theme":"佛道禅颂","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["园林"],"cats":{"抒情":["伤感"],"人生":["哲理"]},"theme_conf":0.86},{"uid":"b5f1094b-b9be-43cf-8e04-9b984642a630","title":"杂曲歌辞 清平调 一","author":"李白","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["云想衣裳花想容，春风拂槛露华浓。","若非群玉山头见，会向瑶台月下逢。"],"theme":"游仙梦幻","theme2":["闺情宫怨"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春","月","山"],"cats":{"抒情":["闺怨"],"四季":["春天"]},"theme_conf":0.513},{"uid":"1168c377-42c2-4c1f-a283-1ba089165dab","title":"秋日荆南述怀三十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔承推奖分，媿匪挺生材。","迟暮宫臣忝，艰危衮职陪。","扬镳随日驭，折槛出云台。","罪戾宽犹活，干戈塞未开。","星霜玄鸟变，身世白驹催。","伏枕因超忽，扁舟任往来。","九钻巴噀火，三蛰楚祠雷。","望帝传应实，昭王问不回。","蛟螭深作横，豺虎乱雄猜。","素业行已矣，浮名安在哉？","琴乌曲怨愤，庭鹤舞摧颓。","秋雨漫湘水，阴风过岭梅。","苦摇求食尾，常曝报恩顋。","结舌防谗柄，探肠有祸胎。","苍茫步兵哭，展转仲宣哀。","饥籍家家米，愁征处处杯。","休为贫士叹，任受众人咍。","得丧初难识，荣枯划易该。","差池分组冕，合沓起蒿莱。","不必伊周地，皆知屈宋才。","汉庭和异域，晋史坼中台。","霸业寻常体，忠臣忌讳灾。","群公纷戮力，圣虑窅裴回。","数见铭钟鼎，真宜法斗魁。","愿闻锋镝铸，莫使栋梁摧。","盘石圭多翦，凶门毂少推。","垂旒资穆穆，祝网但恢恢。","赤雀飜然至，黄龙讵假媒。","贤非梦傅野，隐类凿颜坯。","自古江湖客，冥心苦死灰。"],"theme":"咏怀抒感","theme2":["羁旅思乡","咏史怀古","讽喻刺世"],"style":"沉郁","style2":["旷达"],"mood":"愁怨","mood2":["悲怆"],"scene":["秋","园林","舟"],"cats":{"抒情":["思乡","伤感","怀古"],"四季":["秋天"],"天气":["太阳"],"人生":["时光","战争"]},"theme_conf":0.95},{"uid":"fbf22c24-6020-4423-b6ce-2980ad7128d6","title":"过天门街","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["雪尽终南又欲春，遥怜翠色对红尘。","千车万马九衢上，回首看山无一人。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["雪","春","山"],"cats":{"抒情":["怀古"],"四季":["春天"],"山水":["泰山"]},"theme_conf":1.0},{"uid":"14ac7bda-d0fc-47fd-b824-b71f6ebfe7b2","title":"相和歌辞 栖乌曲二首 一","author":"刘方平","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["蛾眉曼脸倾城国，鸣环动佩新相识。","银汉斜临白玉堂，芙蓉行障掩灯光。"],"theme":"闺情宫怨","theme2":["爱情相思"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["七夕"],"cats":{"抒情":["闺怨"],"节日":["七夕节"]},"theme_conf":0.5},{"uid":"cp8bb678591e441b","title":"伴云来・天香","author":"贺铸","dynasty":"宋","section":"宋词","form":"词","paragraphs":["烟络横林，山沈远照，逦迤黄昏钟鼓。","烛映帘栊，蛩催机杼，共苦清秋风露。","不眠思妇，齐应和、几声砧杵。","惊动天涯倦宦，岁华行暮。","当年酒狂自负。","谓东君、已春相付。","流浪征骖北道，客墙南浦。","幽恨无人晤语。","赖明月曾知旧游处。","好伴云来，还将梦去。"],"theme":"羁旅思乡","theme2":["民生疾苦","送别"],"style":"豪放","style2":["婉约","沉郁"],"mood":"愁怨","mood2":["相思","孤寂"],"scene":["月","秋"],"cats":{"抒情":["离别","思乡","孤独"],"四季":["秋天"],"天气":["写云","月亮"]},"theme_conf":0.286},{"uid":"280875c7-9ec4-4d0e-9022-ecf6b1d67705","title":"夜归孤山寺却寄卢郎中","author":"许浑","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["青山有志路犹赊，心在琴书自忆家。","醉别庾楼山色晓，夜归萧寺月光斜。","落帆露湿回塘柳，别院风惊满地花。","他日此身须报德，莫言空爱旧烟霞。"],"theme":"寄赠酬答","theme2":["哲理悟道"],"style":"沉郁","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["夜","山","月"],"cats":{"抒情":["孤独"],"山水":["西湖"]},"theme_conf":0.86},{"uid":"6fc239af-e267-4a89-a804-330cf037dcb5","title":"秋夜有怀高三十五兼呈空和尚","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["晚节闻君趋道深，结茅栽树近东林。","大师几度曾摩顶，高士何年遂发心。","北渚三更闻过雁，西城万里动寒砧。","不见支公与玄度，相思拥膝坐长吟。"],"theme":"哲理悟道","theme2":["爱情相思"],"style":"豪放","style2":["冲淡"],"mood":"相思","mood2":["孤寂"],"scene":["夜","秋"],"cats":{"抒情":["爱情","思念"],"四季":["秋天"],"山水":["庐山"]},"theme_conf":0.603},{"uid":"fdc856e6-09cc-44bf-a4ad-b5badbc57951","title":"蜀州郑史君寄鸟觜茶因以赠答八韵","author":"薛能","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["鸟觜撷浑牙，精灵胜镆铘。","烹尝方带酒，滋味更无茶。","拒碾干声细，撑封利颖斜。","衔芦齐劲实，啄木聚菁华。","盐损添常诫，姜宜著更夸。","得来抛道药，携去就僧家。","旋觉前瓯浅，还愁后信赊。","千慙故人意，此惠敌丹砂。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["鸟"],"cats":{"抒情":["友情","伤感"],"食物":["写茶"]},"theme_conf":0.95},{"uid":"6358b620-0c4b-4bd3-ae41-b93271318a05","title":"相和歌辞 短歌行二首 二","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["世人求富贵，多为身嗜欲。","盛衰不自由，得失常相逐。","问君少年日，苦学将干禄。","负笈尘中游，抱书雪前宿。","布衾不周体，藜茄才充腹。","三十登宦途，五十被朝服。","奴温已挟纩，马肥初食粟。","未敢议欢游，尚为名检束。","耳目聋暗后，堂上调丝竹。","牙齿缺落时，盘中堆酒肉。","彼来此已去，外余中不足。","少壮与荣华，相避如寒燠。","青云去地远，白日终天速。","从古无奈何，短歌听一曲。"],"theme":"讽喻刺世","theme2":[],"style":"悲慨","style2":[],"mood":"愁怨","mood2":["欢愉","慷慨"],"scene":["雪","酒"],"cats":{"抒情":["伤感"],"人生":["青春"]},"theme_conf":1.0},{"uid":"85a83aa1-746f-4baa-bc0f-deaf8de5fdcd","title":"相和歌辞 白头吟","author":"刘希夷","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["洛阳城东桃李花，飞来飞去落谁家。","洛阳女儿惜颜色，行逢落花长叹息。","今年花落颜色改，明年花开复谁在。","已见松柏摧为薪，更闻桑田变成海。","古人无复洛城东，今人还对落花风。","年年岁岁花相似，岁岁年年人不同。","寄言全盛红颜子，须怜半死白头翁。","此翁白头真可怜，伊昔红颜美少年。","公子王孙芳树下，清歌妙舞落花前。","光禄池台文锦绣，将军楼阁画神仙。","一朝卧病无人识，三春行乐在谁边。","宛转蛾眉能几时，须臾白发乱如丝。","但看旧来歌舞地，惟有黄昏鸟雀悲。"],"theme":"山水田园","theme2":["边塞征战"],"style":"沉郁","style2":["绮丽"],"mood":"悲怆","mood2":["愁怨"],"scene":["楼","花","春","夜"],"cats":{"抒情":["伤感"],"四季":["春天"],"人物":["女子"]},"theme_conf":0.477},{"uid":"26f3fc34-fc1c-41ef-8c59-9b6d1806020e","title":"杂曲歌辞 少年行","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["千点斓斒喷玉骢，青丝结尾绣缠騣。","鸣鞭晚出章台路，叶叶春依杨柳风。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"人生":["青春"]},"theme_conf":0.65},{"uid":"cpeee94b3a49dd8c","title":"宴山亭・燕山亭","author":"张","dynasty":"宋","section":"宋词","form":"词","paragraphs":["幽梦初回，重阴未开，晓色吹成疏雨。","竹槛气寒，蕙畹声摇，新绿暗通南浦。","未有人行，才半启、回廊朱户。","无绪。","空望极霓旌，锦书难据。","苔径追忆曾游，念谁伴、秋千采绳芳柱。","犀奁黛卷，凤枕云孤，应也几番凝伫。","怎得伊来，花雾绕、小堂深处。","留住。","直到老、不教归去。"],"theme":"山水田园","theme2":["送别"],"style":"清新","style2":[],"mood":"相思","mood2":["孤寂","欢愉"],"scene":["山","园林","楼","鸟","花"],"cats":{"抒情":["离别","思念","孤独"],"动物":["写鸟"]},"theme_conf":0.579},{"uid":"163e6b84-544c-426c-820f-0b6bac718a2d","title":"相和歌辞 江南曲","author":"罗隐","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["江烟湿雨鲛绡輭，漠漠远山眉黛浅。","水国多愁又有情，夜槽压酒银船满。","绷丝采怨凝晓空，吴王台榭春梦中。","鸳鸯㶉𫛶唤不起，平铺渌水眠东风。","西陵路边月悄悄，油壁轻车嫁苏小。"],"theme":"咏史怀古","theme2":["山水田园","爱情相思"],"style":"婉约","style2":["冲淡"],"mood":"愁怨","mood2":[],"scene":["江南","江"],"cats":{"抒情":["爱情","伤感","怀古"],"四季":["春天"],"山水":["江河"]},"theme_conf":0.55},{"uid":"9482c243-95f3-4929-a211-9081efcc386d","title":"一百五日夜对月","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["无家对寒食，有泪如金波。","斫却月中桂，清光应更多。","仳离放红蘂，想像嚬青蛾。","牛女漫愁思，秋期犹渡河。"],"theme":"爱情相思","theme2":["送别"],"style":"沉郁","style2":["绮丽"],"mood":"愁怨","mood2":["相思"],"scene":["月","夜"],"cats":{"抒情":["伤感"],"天气":["月亮"],"节日":["寒食节","七夕节"]},"theme_conf":0.86},{"uid":"a782bd15-160a-4ffd-803e-35334740fbff","title":"相和歌辞 张静婉采莲曲","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["兰膏坠发红玉春，燕钗拖颈抛盘云。","城西杨柳向娇晚，门前沟水波潾潾。","麒麟公子朝天客，珮马珰珰铛度春陌。","掌中无力舞衣轻，翦断鲛绡破春碧。","抱月飘烟一尺腰，麝脐龙髓怜娇饶。","秋罗拂衣碎光动，露重花多香不销。","㶉𫛶胶胶塘水满，绿萍如粟莲茎短。","一夜西风送雨来，粉痕零落愁红浅。","船头折藕丝暗牵，藕根莲子相留连。","郎心似月月易缺，十五十六清光圆。"],"theme":"爱情相思","theme2":["送别"],"style":"绮丽","style2":["清新"],"mood":"恬淡","mood2":["愁怨"],"scene":["秋","花","春","月"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"],"植物":["荷花"]},"theme_conf":0.503},{"uid":"99b28edd-1f27-415b-993f-f7ca05f18279","title":"深上人见访忆李端","author":"司空曙","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["雁稀秋色尽，落日对寒山。","避事多称疾，留僧独闭关。","心归尘俗外，道胜有无间。","仍忆东林友，相期久不还。"],"theme":"寄赠酬答","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["秋","鸟","山"],"cats":{"抒情":["思念","孤独"],"四季":["秋天"],"山水":["庐山"]},"theme_conf":0.56},{"uid":"bf7821d0-4630-4e62-8462-c3e189277a4e","title":"三乡驿楼伏覩玄宗望女几山诗小臣斐然有感","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["开元天子万事足，唯惜当时光景促。","三乡陌上望仙山，归作霓裳羽衣曲。","仙心从此在瑶池，三清八景相追随。","天上忽乘白云去，世间空有秋风词。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["山","楼"],"cats":{"抒情":["思乡"],"人生":["时光"]},"theme_conf":0.503},{"uid":"d71a5667-a683-40ec-bb82-94373c508595","title":"春日咏梅花二首 二","author":"王初","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["青帝来时值远芳，残花残雪尚交光。","隔年拟待春消息，得见春风已断肠。"],"theme":"咏物","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春","花"],"cats":{"抒情":["伤感"],"四季":["春天"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"157a14f5-9ce9-41a4-ad4d-05e4b7ba595e","title":"杂曲歌辞 长干行","author":"张潮","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["壻贫如珠玉，壻富如埃尘。","贫时不忘旧，富贵多宠新。","妾本富家女，与君为偶匹。","惠好一何深，中门不曾出。","妾有绣衣裳，葳蕤金缕光。","念君贫且贱，易此从远方。","远方三千里，发去悔不已。","日暮情更来，空望去时水。","孟夏麦始秀，江上多南风。","商贾归欲尽，君今尚巴东。","巴东有巫山，窈窕神女颜。","常恐游此山，果然不知还。"],"theme":"闺情宫怨","theme2":["羁旅思乡","山水田园"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["夏","山"],"cats":{"抒情":["思乡","闺怨"],"四季":["夏天"]},"theme_conf":0.41},{"uid":"11df3b79-9086-4902-840b-c9e9adf9fc25","title":"九日送人","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["晴景应重阳，高台怆远乡。","水澄千室倒，雾卷四山长。","受节人逾老，惊寒菊半黄。","席前愁此别，未别已沾裳。"],"theme":"送别","theme2":["节令风俗"],"style":"清新","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["重阳"],"cats":{"抒情":["伤感"],"节日":["重阳节"]},"theme_conf":0.476},{"uid":"cf75254e-a399-47c0-b188-79c3b0be396b","title":"小孤山","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["古庙枫林江水边，寒鸦接饭雁横天。","大孤山远小孤出，月照洞庭归客船。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["山","江","鸟"],"cats":{"抒情":["思乡","孤独"],"山水":["西湖"]},"theme_conf":0.514},{"uid":"cae8a893-7ae6-4824-b4c5-eada730b075f","title":"苏武庙","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["苏武魂销汉使前，古祠高树两茫然。","云边雁断胡天月，陇上羊归塞草烟。","廻日楼台非甲帐，去时冠劒是丁年。","茂陵不见封侯印，空向秋波哭逝川。"],"theme":"咏史怀古","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["惆怅","欢愉"],"scene":["楼","塞外","江南","秋","月"],"cats":{"抒情":["怀古"],"四季":["秋天"],"生活":["边塞"]},"theme_conf":0.461},{"uid":"cp0ebe2ac2d276d9","title":"绣鸾凤花犯・花犯","author":"周密","dynasty":"宋","section":"宋词","form":"词","paragraphs":["楚江湄，湘娥乍见，无言洒清泪。","淡然春意。","空独倚东风，芳思谁寄。","凌波路冷秋无际。","香云随步起。","谩记得，汉宫仙掌，亭亭明月底。","冰弦写怨更多情，骚人恨，枉赋芳兰幽芷。","春思远，谁叹赏、国香风味。","相将共、岁寒伴侣。","小窗净、沈烟熏翠袂。","幽梦觉，涓涓清露，一枝灯影里。"],"theme":"闺情宫怨","theme2":["送别"],"style":"婉约","style2":["绮丽","冲淡"],"mood":"愁怨","mood2":["孤寂"],"scene":["花","春","月","冬"],"cats":{"抒情":["伤感","孤独","闺怨"],"四季":["春天","冬天"],"天气":["月亮"]},"theme_conf":0.588},{"uid":"4b3cec93-fc44-44d2-91fa-a4feed67aaf9","title":"遣兴五首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["蛰龙三冬卧，老鹤万里心。","昔时贤俊人，未遇犹视今。","嵇康不得死，孔明有知音。","又如垅底松，用舍在所寻。","大哉霜雪干，岁久为枯林。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":["悲怆"],"scene":["冬","雪"],"cats":{"抒情":["友情"],"四季":["冬天"]},"theme_conf":1.0},{"uid":"3fe183cd-7771-4bb4-81d1-0d3ee507c647","title":"观拔河俗戏","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["壮徒恒贾勇，拔拒抵长河。","欲练英雄志，须明胜负多。","噪齐山岌嶪，气作水腾波。","预期年岁稔，先此乐时和。"],"theme":"咏史怀古","theme2":[],"style":"雄浑","style2":["豪放"],"mood":"慷慨","mood2":["欢愉"],"scene":["山"],"cats":{"抒情":["怀古"],"山水":["江河"]},"theme_conf":0.65},{"uid":"29caf0d7-6d84-4b60-975d-d2acce3b89e4","title":"喜辱韩十四郎中书兼封近诗示代书题赠","author":"独孤及","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["各牵于役间游遨，独坐相思正郁陶。","长跪读书心𫏐缓，短章投我曲何高。","宦情缘木知非愿，王事敦人敢告劳。","所叹在官成远别，徒言岏水才容舠。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":["相思","欢愉"],"scene":[],"cats":{"抒情":["思念","孤独"],"人生":["读书"]},"theme_conf":0.95},{"uid":"21781aca-5d96-4c9e-9bc1-ed8140e1107b","title":"杂曲歌辞 悲哉行","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["悲哉为儒者，力学不能疲。","读书眼欲暗，秉笔手生胝。","十上方一第，成名常苦迟。","纵有宦达者，两鬓已成丝。","可怜少壮日，适在穷贱时。","丈夫老且病，焉用富贵为。","沈沈朱门宅，中有乳臭儿。","状貌如妇人，光明膏粱肌。","手不把书卷，身不擐戎衣。","二十袭封爵，门承勋戚资。","春来日日出，服御何轻肥。","朝从博徒饮，暮有倡楼期。","评封还酒债，堆金选蛾眉。","声色狗马外，其余一无知。","山苗与涧松，地势随高卑。","古来无奈何，非君独伤悲。"],"theme":"讽喻刺世","theme2":["山水田园"],"style":"悲慨","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":["春","酒"],"cats":{"抒情":["伤感"],"四季":["春天"],"人生":["青春","读书"]},"theme_conf":0.641},{"uid":"bbbbba72-14ae-42d1-9f5a-09a077f2d0c6","title":"最能行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["峡中丈夫绝轻死，少在公门多在水。","富豪有钱驾大舸，贫穷取给行艓子。","小儿学问止论语，大儿结束随商旅。","攲帆侧柁入波涛，撇漩捎𣸣无险阻。","朝发白帝暮江陵，顷来目击幸有征。","瞿堂漫天虎须怒，归州长年行最能。","此乡之人气量窄，误竞南风疎北客。","若道土无英俊才，何得山有屈原宅。"],"theme":"羁旅思乡","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":["悲怆"],"scene":["舟","端午"],"cats":{"抒情":["思乡"],"人物":["儿童"],"节日":["端午节"]},"theme_conf":1.0},{"uid":"f15c4b50-ee89-4927-8cf3-15e3a6a6ab95","title":"蜀道难","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["噫吁戏！危乎高哉！蜀道之难难于上青天！蚕丛及鱼凫，开国何茫然。","尔来四万八千岁，不与秦塞通人烟。","西当太白有鸟道，可以横绝峨眉巅。","地崩山摧壮士死，然后天梯石栈相钩连。","上有六龙回日之高标，下有冲波逆折之回川。","黄鹤之飞尚不得过，猨猱欲度愁攀援。","青泥何盘盘，百步九折萦岩峦。","扪参历井仰胁息，以手抚膺坐长叹。","问君西游何时还？畏途巉岩不可攀。","但见悲鸟号古木，雄飞雌从绕林间。","又闻子规啼夜月，愁空山，蜀道之难难于上青天，使人听此凋朱颜。","连峰去天不盈尺，枯松倒挂倚绝壁。","飞湍瀑流争喧豗，砅厓转石万壑雷。","其险也如此，嗟尔远道之人胡为乎来哉！劒阁峥嵘而崔嵬，一夫当关，万夫莫开。","所守或匪亲，化为狼与豺。","朝避猛虎，夕避长蛇。","磨牙吮血，杀人如麻。","锦城虽云乐，不如早还家。","蜀道之难难于上青天，侧身西望长咨嗟。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":["悲慨","沉郁"],"mood":"悲怆","mood2":["愁怨"],"scene":["山"],"cats":{"抒情":["伤感"]},"theme_conf":0.713},{"uid":"84c3e8ec-51c4-408a-b93f-a56ad1360586","title":"敬宗睿武昭愍孝皇帝挽歌三首 二","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["任贤劳梦寐，登位富春秋。","欲遂东人幸，宁虞杞国忧。","长杨收羽骑，太液泊龙舟。","惟有衣冠在，年年怆月游。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["端午","春","秋","舟","月"],"cats":{"抒情":["悼亡"],"四季":["春天","秋天"],"节日":["端午节"]},"theme_conf":0.99},{"uid":"83383a17-2f32-4c5e-a25b-1b1d9c7873a1","title":"杂曲歌辞 古别离二首 一","author":"施肩吾","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["古人谩歌西飞燕，十年不见狂夫面。","三更风作切梦刀，万转愁成系肠线。","所嗟不及牛女星，一年一度得相见。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["夜","七夕"],"cats":{"抒情":["离别","思念","伤感"],"节日":["七夕节"]},"theme_conf":1.0},{"uid":"f27f6d5d-9d1b-4e86-b88e-efd452c1d424","title":"醉妆词","author":"后主衍","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["者边走，那边走，只是寻花柳。","那边走，者边走，莫厌金杯酒。"],"theme":"闲适隐逸","theme2":["闺情宫怨"],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["酒"],"cats":{"抒情":["闺怨"],"食物":["写酒"]},"theme_conf":0.64},{"uid":"36e09cb4-4fb7-48be-b6c6-c9bd906d9331","title":"辋川集 竹里馆","author":"王维","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["独坐幽篁里，弹琴复长啸。","深林人不知，明月来相照。"],"theme":"闲适隐逸","theme2":["山水田园"],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["月"],"cats":{"抒情":["孤独"],"天气":["月亮"],"植物":["竹子"]},"theme_conf":0.86},{"uid":"9ee9b746-0c42-41af-bd85-630f391f7c59","title":"相和歌辞 采莲曲","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["秋江岸边莲子多，采莲女儿凭船歌。","青房圆实齐戢戢，争前竞折荡漾波。","试牵绿茎下寻藕，断处丝多刺伤手。","白练束腰袖半卷，不插玉钗妆梳浅。","船中未满度前洲，借问谁家家住远。","归时共待暮潮上，自弄芙蓉还荡桨。"],"theme":"爱情相思","theme2":["闺情宫怨"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["江"],"cats":{"抒情":["闺怨"],"植物":["荷花"]},"theme_conf":0.467},{"uid":"41815024-acd3-414d-9520-a00f0ceb3edd","title":"上韦左相二十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["凤历轩辕纪，龙飞四十春。","八荒开寿域，一气转洪钧。","霖雨思贤佐，丹青忆老臣。","应图求骏马，惊代得麒麟。","沙汰江河浊，调和鼎鼐新。","韦贤初相汉，范叔已归秦。","盛业今如此，传经固绝伦。","豫樟深出地，沧海阔无津。","北斗司喉舌，东方领搢绅。","持衡留藻鉴，听履上星辰。","独步才超古，余波德照邻。","聪明过管辂，尺牍倒陈遵。","岂是池中物，由来席上珍。","庙堂知至理，风俗尽还淳。","才杰俱登用，愚蒙但隐沦。","长卿多病久，子夏索居频。","回首驱流俗，生涯似众人。","巫咸不可问，邹鲁莫容身。","感激时将晚，苍茫兴有神。","为公歌此曲，涕泪在衣巾。"],"theme":"题画咏艺","theme2":[],"style":"雄浑","style2":["沉郁","豪放"],"mood":"相思","mood2":["孤寂"],"scene":["雨","江"],"cats":{"抒情":["思念","孤独"],"天气":["星星"]},"theme_conf":1.0},{"uid":"a833a7e3-13da-49f1-83eb-4b3db1dab38d","title":"赋虞书歌","author":"贾躭","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["众书之中虞书巧，体法自然归大道。","不同怀素只攻颠，岂类张芝惟创草。","形势素，筋骨老，父子君臣相揖抱。","孤青似竹更飕飔，阔白如波长浩渺。","能方正，不隳倒，功夫未至难寻奥。","须知孔子庙堂碑，便是青箱中至宝。"],"theme":"咏史怀古","theme2":[],"style":"冲淡","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":[],"cats":{"抒情":["孤独","怀古"],"人物":["父亲"]},"theme_conf":0.65},{"uid":"f515aba3-5d02-403d-b829-c550e84156db","title":"王起居独游青龙寺玩红叶因寄","author":"羊士谔","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["十亩苍苔遶画廊，几株红树过清霜。","高情还似看花去，闲对南山步夕阳。"],"theme":"寄赠酬答","theme2":["哲理悟道"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["花"],"cats":{"抒情":["孤独"],"植物":["叶子"]},"theme_conf":0.88},{"uid":"f51694bd-8955-4c4d-9ed6-673c2fbb5321","title":"太子李舍人城东别业与二三文友逃暑","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["下马失炎暑，重门深绿篁。","宫臣礼嘉客，林表开兰堂。","兹夕兴难尽，澄罍照墨塲。","鲜风吹印绶，密坐皆馨香。","美景惜文会，清吟迟羽觞。","东林晚来好，目极趣何长。","鸟道挂疎雨，人家残夕阳。","城隅拥归骑，留醉恋琼芳。"],"theme":"送别","theme2":["羁旅思乡"],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["夏"],"cats":{"抒情":["友情","离别","思乡"],"四季":["夏天"],"山水":["庐山"]},"theme_conf":0.585},{"uid":"af091f2d-1eb6-4b68-b180-7aa8cfbae23d","title":"荔枝楼","author":"薛能","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["高槛起边愁，荔枝谁致楼。","会须教匠坼，不欲见蛮陬。","树痺无春影，天连觉汉流。","仲宣如可拟，即此是荆州。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["楼"],"cats":{"抒情":["思乡","伤感"],"食物":["荔枝"]},"theme_conf":0.82},{"uid":"4ddb6dda-68be-4bb2-8874-8508c6c6e3ad","title":"寄人二首  其一","author":"张佖","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["别梦依依到谢家，小廊回合曲阑斜。","多情只有春庭月，犹为离人照落花。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["月","园林"],"cats":{"抒情":["离别"]},"theme_conf":0.86},{"uid":"337b1cbf-675e-490f-a23d-48bee622b21f","title":"萤火","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["幸因腐草出，敢近太阳飞。","未足临书卷，时能点客衣。","随风隔幔小，带雨傍林微。","十月清霜重，飘零何处归。"],"theme":"咏物","theme2":["讽喻刺世","羁旅思乡"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["雨","月"],"cats":{"抒情":["思乡"],"人生":["读书"]},"theme_conf":0.373},{"uid":"6ae53f2c-48fa-464c-8453-de7b2434c716","title":"过王濬暮","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["吴国分牛斗，晋室命龙骧。","受任敌已灭，策勋名不彰。","居美未尽善，矜功徒自伤。","长戟今何在？孤坟此路傍。","不观松柏茂，空余荆棘场。","叹嗟悬劒陇，谁识梦刀祥。"],"theme":"咏史怀古","theme2":["咏史怀古"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["惆怅"],"scene":["江南"],"cats":{"抒情":["孤独","悼亡","怀古"]},"theme_conf":0.98},{"uid":"6d46b6ce-5c89-4a0b-b496-c1718293fa90","title":"赋得北方有佳人","author":"徐贤妃","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["由来称独立，本自号倾城。","柳叶眉间发，桃花脸上生。","腕摇金钏响，步转玉环鸣。","纤腰宜宝袜，红衫艳织成。","悬知一顾重，别觉舞腰轻。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"孤寂","mood2":[],"scene":["花"],"cats":{"抒情":["孤独"],"人物":["女子"]},"theme_conf":0.476},{"uid":"aaa3d713-8c7f-4f46-a0d5-39ed552d9511","title":"杂曲歌辞 鸣雁行","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["嗷嗷鸣雁鸣且飞，穷秋南去春北归。","去寒就暖识所处，天长地阔栖息稀。","风霜酸苦稻粱微，羽毛摧落身不肥。","徘徊反顾群侣违，哀鸣欲下洲渚非。","江南水阔朝云多，草长沙輭无网罗。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["鸟","江","秋","江南"],"cats":{"抒情":["思乡"],"四季":["秋天"],"动物":["写鸟"]},"theme_conf":0.487},{"uid":"2e743a29-04ae-416e-a014-6da19281a515","title":"雪后宿王纯池州草堂","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["宿君湖上宅，琴韵静参差。","夜雪入秋浦，孤城连贵池。","流年看共老，衔酒发中悲。","良会应难再，晨鸡自有期。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["悲慨"],"mood":"悲怆","mood2":["孤寂","恬淡"],"scene":["雪","园林"],"cats":{"抒情":["伤感","孤独"],"天气":["写雪"],"人生":["时光"]},"theme_conf":0.72},{"uid":"0db42110-bda6-490a-b3e0-61a5dfffad79","title":"江陵节度阳城郡王新楼成王请严侍御判官赋七字句同作","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["楼上炎天冰雪生，高飞燕雀贺新成。","碧窗宿雾蒙蒙湿，朱栱浮云细细轻。","杖钺褰帷瞻具美，投壶散帙有余清。","自公多暇延参佐，江汉风流万古情。"],"theme":"咏史怀古","theme2":[],"style":"清新","style2":["婉约"],"mood":"惆怅","mood2":[],"scene":["楼","江"],"cats":{"抒情":["怀古"],"山水":["江河"],"天气":["写雪"]},"theme_conf":1.0},{"uid":"c1ebbb06-55b7-40d1-8f23-63491faa6fa7","title":"送崔侍御入朝","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["十年犹执宪，万里独归春。","旧国逢芳草，青云见故人。","潘郎今发白，陶令本家贫。","相送临京口，停桡泪满巾。"],"theme":"送别","theme2":[],"style":"豪放","style2":["婉约","沉郁"],"mood":"孤寂","mood2":["愁怨"],"scene":["春"],"cats":{"抒情":["友情","伤感","孤独"],"四季":["春天"]},"theme_conf":1.0},{"uid":"96964fe2-9087-42a4-abe9-87cc8e846c59","title":"唐明堂乐章 皇帝行","author":"则天皇后","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["仰膺历数，俯顺讴歌。","远安迩肃，俗阜时和。","化光玉镜，讼息金科。","方兴典礼，永戢干戈。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"人生":["战争"]},"theme_conf":0.521},{"uid":"690ec16d-1c00-4f82-afe0-98e4dd46ead0","title":"月三首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["并照巫山出，新窥楚水清。","羁栖愁里见，二十四回明。","必验升沈体，如知进退情。","不违银汉落，亦伴玉绳横。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["月","七夕"],"cats":{"抒情":["思乡","伤感"],"天气":["月亮"],"节日":["七夕节"]},"theme_conf":1.0},{"uid":"dabbc6bb-8c93-4605-b262-6aa32751bc54","title":"系乐府十二首 下客谣","author":"元结","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["下客无黄金，岂思主人怜。","客言胜黄金，主人然不然。","珠玉成彩翠，绮罗如婵娟。","终恐见斯好，有时去君前。","岂知保忠信，长使令德全。","风声与时茂，歌颂万千年。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["中秋"],"cats":{"抒情":["思乡"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"dbde2fca-6bfe-4f14-bf89-5df0f900b277","title":"鼓吹曲辞 鼓吹铙歌 吐谷浑","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["吐谷浑盛彊，背西海以夸。","岁侵扰我疆，退匿险且遐。","帝谓神武师，往征靖皇家。","烈烈斾其旗，熊虎杂龙蛇。","王旅千万人，衔枚默无哗。","束刃逾山徼，张翼纵漠沙。","一举刈膻腥，尸骸积如麻。","除恶务本根，况敢遗萌芽。","洋洋西海水，威命穷天涯。","系虏来王都，犒乐穷休嘉。","登高望还师，竟野如春华。","行者靡不归，亲戚讙要遮。","凯旋献清庙，万国思无邪。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"幽峭","style2":[],"mood":"相思","mood2":[],"scene":["塞外","春","重阳"],"cats":{"抒情":["思乡"],"四季":["春天"],"节日":["重阳节"]},"theme_conf":0.522},{"uid":"02c923a2-c7b4-4464-a46c-e5e4a1156933","title":"重游木兰亭","author":"徐铉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["缭绕长隄带碧浔，昔年游此尚青衿。","兰桡破浪城阴直，玉勒穿花苑树深。","宦路尘埃成久别，仙家风景有谁寻。","那知年长多情后，重凭栏干一独吟。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["楼"],"cats":{"抒情":["孤独"],"人生":["励志"]},"theme_conf":1.0},{"uid":"c836e52f-2346-4a3e-84bb-97514b17faf6","title":"孤鴈 二","author":"崔涂","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["几行归去尽，片影独何之。","暮雨相呼失，寒塘独下迟。","渚云低暗度，关月冷遥随。","未必逢矰缴，孤飞自可疑。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["雨","月"],"cats":{"抒情":["思乡","孤独"]},"theme_conf":0.578},{"uid":"26a0266d-313c-4911-b629-2418556d1b03","title":"洗兵马","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["中兴诸将收山东，捷书日报清昼同。","河广传闻一苇过，胡危命在破竹中。","祗残邺城不日得，独任朔方无限功。","京师皆骑汗血马，回纥喂肉葡萄宫。","已喜皇威清海岱，常思仙仗过崆峒。","三年笛里关山月，万国兵前草木风。","成王功大心转小，郭相谋深古来少。","司徒清鉴悬明镜，尚书气与秋天杳。","二三豪俊为时出，整顿乾坤济时了。","东走无复忆鲈鱼，南飞觉有安巢鸟。","青春复随冠冕入，紫禁正耐烟花绕。","鹤禁通霄凤辇备，鸡鸣问寝龙楼晓。","攀龙附凤势莫当，天下尽化为侯王。","汝等岂知蒙帝力，时来不得夸身强。","关中既留萧丞相，幕下复用张子房。","张公一生江海客，身长九尺须眉苍。","征起适遇风云会，扶颠始知筹策良。","青袍白马更何有，后汉今周喜再昌。","寸地尺天皆入贡，奇祥异瑞争来送。","不知何国致白环，复道诸山得银瓮。","隐士休歌紫芝曲，词人解撰河清颂。","田家望望惜雨干，布谷处处催春种。","淇上健儿归莫嬾，城南思妇愁多梦。","安得壮士挽天河，净洗甲兵长不用。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["旷达","清新"],"mood":"欢愉","mood2":["相思"],"scene":["鸟","春"],"cats":{"抒情":["思念"],"四季":["春天"],"人生":["青春","战争"],"动物":["写马"]},"theme_conf":0.43},{"uid":"fbddd4e6-86e1-444f-9e4e-09e473f2a306","title":"新乐府 海漫漫\t戒求仙也","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["海漫漫，直下无底傍无边。","云涛烟浪最深处，人传中有三神山。","山上多生不死药，服之羽化为天仙。","秦皇汉武信此语，方士年年采药去。","蓬莱今古但闻名，烟水茫茫无觅处。","海漫漫，风浩浩，眼穿不见蓬莱岛。","不见蓬莱不敢归，童男丱女舟中老。","徐福文成多诳诞，上元太一虚祈祷。","君看骊山顶上茂陵头，毕竟悲风吹蔓草。","何况玄元圣祖五千言，不言药，不言仙，不言白日升青天。"],"theme":"游仙梦幻","theme2":["咏史怀古"],"style":"豪放","style2":[],"mood":"悲怆","mood2":["欢愉"],"scene":["元宵","山","舟"],"cats":{"抒情":["伤感","怀古"],"节日":["元宵节"]},"theme_conf":0.465},{"uid":"276d7c1f-d89d-48fd-a8f5-777b9efd9d23","title":"酬秘书弟兼寄幕下诸公","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["亚相膺时杰，群才遇良工。","翩翩幕下来，拜赐甘泉宫。","信知命世奇，适会非常功。","侍御执邦宪，清词焕春丛。","末路望绣衣，他时常发蒙。","孰云三军壮，惧我弹射雄。","谁谓万里遥，在我樽俎中。","光禄经济器，精微自深衷。","前席屡荣问，长城兼在躬。","高纵激颓波，逸翮驰苍穹。","将副节制筹，欲令沙漠空。","司业志应徐，雅度思冲融。","相思三十年，忆昨犹儿童。","今来抱青紫，忽若披鹓鸿。","说劒增慷慨，论交持始终。","秘书即吾门，虚白无不通。","多才陆平原，硕学郑司农。","献封到关西，独步归山东。","永意久知处，嘉言能亢宗。","客从梁宋来，行役随转蓬。","酬赠欣元弟，忆贤瞻数公。","游鳞戏沧浪，鸣凤栖梧桐。","并负垂天翼，俱乘破浪风。","眈眈天府间，偃仰谁敢同。","何意搆广厦，翻然顾雕虫。","应知阮步兵，惆怅此途穷。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":["豪放"],"mood":"相思","mood2":[],"scene":["塞外"],"cats":{"抒情":["思念"],"人物":["儿童"],"人生":["励志"]},"theme_conf":0.95},{"uid":"cp7169fdcc1834b8","title":"望湘人","author":"贺铸","dynasty":"宋","section":"宋词","form":"词","paragraphs":["厌莺声到枕，花气动帘，醉魂愁梦相半。","被惜馀薰，带惊剩眼。","几许伤春春晚。","泪竹痕鲜，佩兰香老，湘天浓暖。","记小江、风月佳时，屡约非烟游伴。","须信鸾弦易断。","奈云和再鼓，曲终人远。","认罗袜无踪，旧处弄波清浅。","青翰棹舣，白苹洲畔。","尽木临皋飞观。","不解寄、一字相思，幸有归来双燕。"],"theme":"爱情相思","theme2":["送别"],"style":"沉郁","style2":["婉约","冲淡"],"mood":"相思","mood2":["愁怨"],"scene":["春","江","鸟","花"],"cats":{"抒情":["爱情","思念","伤感"],"四季":["春天"]},"theme_conf":0.556},{"uid":"d9aa05ba-6c7d-4ebd-9401-5edd412f9b93","title":"轻薄行","author":"齐己","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["玉鞭金镫骅骝蹄，横眉吐气如虹霓。","五陵春暖芳草齐，笙歌到处花成泥。","日沉月上且鬬鸡，醉来莫问天高低。","伯阳道德何唾咦，仲尼礼乐徒卑栖。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["花","春","月","酒"],"cats":{"抒情":["思乡"],"四季":["春天"],"天气":["彩虹"]},"theme_conf":0.65},{"uid":"dcccde71-c438-4fa8-ac7a-a9ac53638a7c","title":"登垅","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["垅头远行客，垅上分流水。","流水无尽期，行人未云已。","浅才登一命，孤劒通万里。","岂不思故乡，从来感知己。"],"theme":"羁旅思乡","theme2":["咏史怀古"],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":[],"cats":{"抒情":["友情","思乡","孤独","怀古"]},"theme_conf":0.576},{"uid":"cp0646461af1c005","title":"荔枝香","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["甚处寻芳赏翠，归去晚。","缓步罗袜生尘，来绕琼筵看。","金缕霞衣轻褪，似觉春游倦。","遥认，众里盈盈好身段。","拟回首，又伫立、帘帏畔。","素脸红眉，时揭盖头微见。","笑整金翘，一点芳心在娇眼。","王孙空恁肠断。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":["绮丽"],"mood":"欢愉","mood2":["愁怨"],"scene":["花","雪"],"cats":{"抒情":["伤感","闺怨"],"食物":["荔枝"]},"theme_conf":0.65},{"uid":"99c57fb0-4d0e-47f6-95a6-ef1769ddb878","title":"宫词三十首 二十一","author":"王涯","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["迥出芙蓉阁上头，九天悬处正当秋。","年年七夕晴光里，宫女穿针尽上楼。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["楼","七夕","秋"],"cats":{"抒情":["闺怨"],"四季":["秋天"],"节日":["七夕节"]},"theme_conf":0.771},{"uid":"6340ef19-35e2-4194-96a9-3ee0a667905b","title":"送魏万之京","author":"李颀","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["朝闻游子唱离歌，昨夜微霜初渡河。","鸿鴈不堪愁里听，云山况是客中过。","关城树色催寒近，御苑砧声向晚多。","莫见长安行乐处，空令岁月易蹉跎。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["孤寂","欢愉"],"scene":["秋","夜","月","山"],"cats":{"抒情":["伤感"],"四季":["秋天"]},"theme_conf":0.714},{"uid":"303d9236-55b2-4dea-8967-74d66f440450","title":"相和歌辞 采菱行","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["白马湖平秋日光，紫菱如锦彩鸾翔。","荡舟游女满中央，采菱不顾马上郎。","争多逐胜纷相向，时转兰桡破轻浪。","长鬟弱袂动参差，钗影钏文浮荡漾。","笑语哇咬顾晚晖，蓼花绿岸扣舷归。","归来共到市桥步，野蔓系船萍满衣。","家家竹楼临广陌，下有连樯多估客。","携觞荐芰夜经过，醉踏大堤相应歌。","屈平祠下沅江水，月照寒波白烟起。","一曲南音此地闻，长安北望三千里。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["舟","酒","江"],"cats":{"抒情":["思乡"],"生活":["写桥"]},"theme_conf":0.421},{"uid":"7545d07f-17d2-47df-89d1-ed639aeff478","title":"武陵观火诗","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["楚乡祝融分，炎火常为虞。","是时直突烟，发自晨炊徒。","盲风扇其威，白昼曛阳鸟。","操绠不暇汲，循墙还避逾。","怒如列缺光，迅与芬轮俱。","联延掩四远，赫弈成洪𬬻。","汹疑云涛翻，飒若鬼神趋。","当前迎惞𨹮，是物同膏腴。","金乌入梵天，赤龙游玄都。","腾烟透窻户，飞燄生栾栌。","火山摧半空，星雨洒中衢。","瑶坛被髹漆，宝树攒珊瑚。","光县与琴焦，旗亭无酒濡。","市人委百货，邑令遗双凫。","余势下隈隩，长熛烘舳舻。","吹焚照水府，炙浪愁天吴。","灾罢云日晚，心惊视听殊。","高灰辨廪庾，黑土连𬮱阇。","众烬合星罗，游氛铄人肤。","厚地藏宿热，遥林呈骤枯。","火德资生人，庸可一日无。","御之失其道，敲石弥天隅。","晋库走龙劒，吴宫伤燕雏。","五行有沴气，先哲垂𬣙谟。","宋郑同日起，时当贤大夫。","无苛自可乐，弭患非所图。","贤守恤人瘼，临烟驻骊驹。","吊场色惨忸，颜失词劬愉。","下令蠲里布，指期轻市租。","闬垣适未立，苫盖自相娱。","山木行剪伐，江泥宜墐途。","邑臣不必曾，何用征越巫。"],"theme":"民生疾苦","theme2":["山水田园","哲理悟道"],"style":"绮丽","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":["江南","鸟"],"cats":{"抒情":["伤感"],"植物":["桃花"]},"theme_conf":0.92},{"uid":"a9b7af05-49db-4fac-8c70-6f300183e59f","title":"宋中送族姪式颜","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["大夫击东胡，胡尘不敢起。","胡人山下哭，胡马海边死。","部曲尽公侯，舆台亦朱紫。","当时有勋业，末路遭谗毁。","转斾燕赵间，剖符括苍里。","弟兄莫相见，亲族远枌梓。","不改青云心，仍招布衣士。","平生怀感激，本欲候知己。","去矣难重陈，飘然自兹始。","游梁且未遇，适越今何以。","乡山西北愁，竹箭东南美。","峥嵘缙云外，苍莽几千里。","旅雁悲啾啾，朝昏孰云已。","登临多瘴疠，动息在风水。","虽有贤主人，终为客行子。","我携一尊酒，满酌聊劝尔。","劝尔惟一言，家声勿沦滓。"],"theme":"送别","theme2":["羁旅思乡"],"style":"雄浑","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":["酒","鸟"],"cats":{"抒情":["友情","思乡","伤感"]},"theme_conf":0.465},{"uid":"a22763d6-eb7f-4487-a68d-dad57e5ef898","title":"南征怨","author":"曹邺","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["万浪东不回，昭王南征早。","龙舟没何处，独树江上老。","吾欲问水滨，宫殿已生草。"],"theme":"闺情宫怨","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["端午","舟","江"],"cats":{"抒情":["闺怨"],"节日":["端午节"]},"theme_conf":0.5},{"uid":"7c93c162-d424-4d91-b71b-7c9b81713b8c","title":"赤壁","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["折戟沈沙铁未销，自将磨洗认前朝。","东风不与周郎便，铜雀春深鏁二乔。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"惆怅","mood2":[],"scene":["春"],"cats":{"抒情":["怀古"],"四季":["春天"]},"theme_conf":0.739},{"uid":"b6be3e45-97f6-4b6e-a61a-860fb324b6a1","title":"小寒食舟中作","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["佳辰强饭食犹寒，隐几萧条带鹖冠。","春水船如天上坐，老年花似雾中看。","娟娟戏蝶过闲幔，片片轻鸥下急湍。","云白山清万余里，愁看直北是长安。"],"theme":"羁旅思乡","theme2":[],"style":"幽峭","style2":["沉郁","悲慨"],"mood":"恬淡","mood2":["愁怨","孤寂"],"scene":["清明","舟"],"cats":{"抒情":["思乡","伤感"],"节日":["寒食节","清明节"]},"theme_conf":0.82},{"uid":"b5246cf9-130a-4cd8-afc5-ca0f33a16b32","title":"对雪","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["战哭多新鬼，愁吟独老翁。","乱云低薄暮，急雪舞回风。","瓢弃尊无绿，炉存火似红。","数州消息断，愁坐正书空。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["愁怨","悲怆"],"scene":["雪","冬"],"cats":{"抒情":["伤感","孤独"],"天气":["写雪"]},"theme_conf":1.0},{"uid":"b458468f-a5c3-44a5-aa38-29e8ab8f3533","title":"酬别薛三蔡大留简韩十四主簿","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["迢递辞京华，辛勤异乡县。","登高俯沧海，廻首泪如霰。","同人久离别，失路还相见。","薛侯怀直道，德业应时选。","蔡子负清才，当年擢宾荐。","韩公有奇节，词赋凌群彦。","读书嵩岑间，作吏沧海甸。","伊余寡栖托，感激多愠见。","纵诞非尔情，飘沦任疵贱。","忽枉琼瑶作，乃深平生眷。","始谓吾道存，终嗟客游倦。","归心无昼夜，别事除言宴。","复值凉风时，苍茫夏云变。"],"theme":"送别","theme2":["羁旅思乡"],"style":"雄浑","style2":["豪放"],"mood":"惆怅","mood2":[],"scene":["雪","夏","江","重阳"],"cats":{"抒情":["离别","思乡"],"四季":["夏天"],"人生":["读书"],"节日":["重阳节"]},"theme_conf":0.63},{"uid":"b9521e2b-963e-4d90-acf3-d87c2a135071","title":"古意呈补阙乔知之","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["卢家少妇郁金堂，海燕双栖玳瑁梁。","九月寒砧催木叶，十年征戍忆辽阳。","白狼河北音书断，丹凤城南秋夜长。","谁谓含愁独不见，更教明月照流黄。"],"theme":"闺情宫怨","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["月","秋","夜"],"cats":{"抒情":["思念","闺怨"],"四季":["秋天"],"天气":["月亮"]},"theme_conf":0.594},{"uid":"cp6ed8f2981cfc67","title":"霜叶飞","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["断烟离绪。","关心事，斜阳红隐霜树。","半壶秋水荐黄花，香西风雨。","纵玉勒、轻飞迅羽。","凄凉谁吊荒台古。","记醉蹋南屏，彩扇咽、寒蝉倦梦，不知蛮素。","聊对旧节传杯，尘笺蠹管，断阕经岁慵赋。","小蟾斜影转东篱，夜冷残蛩语。","早白发、缘愁万缕。","惊飙从卷乌纱去。","漫细将、茱萸看，但约明年，翠微高处。"],"theme":"节令风俗","theme2":["咏史怀古"],"style":"婉约","style2":["绮丽"],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"节日":["重阳节"],"植物":["叶子"]},"theme_conf":0.78},{"uid":"cp1018b391d4cfee","title":"六丑","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["正单衣试酒，恨客里、光阴虚掷。","愿春暂留，春归如过翼。","一去无迹。","为问花何在，夜来风雨，葬楚宫倾国。","钗钿堕处遗香泽。","乱点桃蹊，轻翻柳陌。","多情为谁追惜。","但蜂媒蝶使，时叩窗隔。","东园岑寂。","渐蒙笼暗碧。","静绕珍丛底，成叹息。","长条故惹行客。","似牵衣待话，别情无极。","残英小、强簪巾帻。","终不似一朵，钗头颤袅，向人侧。","漂流处、莫趁潮汐。","恐断红、尚有相思字，何由见得。"],"theme":"咏物","theme2":["爱情相思","羁旅思乡","送别"],"style":"沉郁","style2":["冲淡","婉约"],"mood":"相思","mood2":["孤寂"],"scene":["雨","花","春","酒"],"cats":{"抒情":["爱情","思念","思乡"],"四季":["春天"],"人生":["时光"]},"theme_conf":0.93},{"uid":"051a325b-0ad3-42b1-89dc-8c9d09cf45d5","title":"相和歌辞 苦寒行","author":"刘驾","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["严寒动八荒，莿莿无休时。","阳乌不自暖，雪压扶桑枝。","岁暮寒益壮，青春安得归。","朔雁到南海，越禽何处飞？","谁言贫士叹，不为身无衣。"],"theme":"民生疾苦","theme2":["羁旅思乡"],"style":"豪放","style2":["幽峭"],"mood":"愁怨","mood2":["孤寂","慷慨"],"scene":["雪","春","鸟","江南"],"cats":{"抒情":["思乡"],"四季":["春天"],"人生":["青春"]},"theme_conf":0.51},{"uid":"fbda7bf3-886d-49a8-b855-117d39ac92e2","title":"送郑书记","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["决胜无遗策，辞天便起缨。","出身唯殉死，报国且能兵。","受命麒膦殿，参谋骠骑营。","短箫催别酒，斜日驻前旌。","义勇千夫敌，风沙万里行。","几年丹阙下，侯印锡书生。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":["悲怆"],"scene":["酒"],"cats":{"抒情":["爱国"]},"theme_conf":1.0},{"uid":"1b9d00c7-3128-4bee-b338-2d354d51c002","title":"和武相公中秋锦楼玩月得苍字","author":"张正一","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["高秋今夜月，皓色正苍苍。","远水澄如练，孤鸿逈带霜。","旅人方积思，繁宿稍沈光。","朱槛叨陪赏，尤宜清漏长。"],"theme":"应制干谒","theme2":[],"style":"雄浑","style2":["绮丽","清新"],"mood":"孤寂","mood2":[],"scene":["秋","中秋","月"],"cats":{"抒情":["孤独"],"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.88},{"uid":"be6c51dd-d0bb-4030-b9ba-eb4d4a165f76","title":"送杜𫖮赴润州幕","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["少年才俊赴知音，丞相门栏不觉深。","直道事人男子业，异乡加饭弟兄心。","还须整理韦弦佩，莫独矜夸玳瑁簪。","若去上元怀古去，谢安坟下与沈吟。"],"theme":"送别","theme2":["羁旅思乡"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["元宵"],"cats":{"抒情":["友情","思乡","孤独","怀古"],"节日":["元宵节"]},"theme_conf":0.352},{"uid":"8c257f77-fbd5-4f89-a01d-f069cc2189b2","title":"杂曲歌辞 悲哉行","author":"孟云卿","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["孤儿去慈亲，远客丧主人。","莫吟苦辛曲，谁忍闻可闻。","可闻不可说，去去无期别。","行人念前程，不待参辰没。","朝亦常苦饥，暮亦常苦饥。","飘飘万余里，贫贱多是非。","少年莫远游，远游多不归。"],"theme":"羁旅思乡","theme2":["民生疾苦"],"style":"悲慨","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":[],"cats":{"抒情":["思乡","伤感"],"人物":["母亲"]},"theme_conf":0.402},{"uid":"4b70cf4d-91c2-4f35-88b6-27719132e234","title":"留别公安太易沙门","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["隐居欲就庐山远，丽藻初逢休上人。","数问舟航留制作，长开箧笥拟心神。","沙村白雪仍含冻，江县红梅已放春。","先蹋炉峰置兰若，徐飞锡杖出风尘。"],"theme":"送别","theme2":[],"style":"旷达","style2":[],"mood":"恬淡","mood2":[],"scene":["山","冬"],"cats":{"抒情":["离别"],"山水":["庐山"]},"theme_conf":0.433},{"uid":"0f5af383-765a-4d56-b00b-79ee2ccd5111","title":"岁除夜有怀","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["迢递三巴路，羁危万里身。","乱山残雪夜，孤灯异乡人。","渐与骨肉远，转于奴仆亲。","那堪正飘泊，来日岁华新。"],"theme":"羁旅思乡","theme2":["节令风俗"],"style":"沉郁","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":["除夕","夜"],"cats":{"抒情":["思乡","孤独"],"节日":["春节"]},"theme_conf":0.494},{"uid":"2d69a74c-1dad-46c4-a6d8-78d56d12145d","title":"东郊纳凉忆左威卫李录事收昆季太原崔参军三首 二","author":"楼颕","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["纳凉每选地，近得青门东。","林与缭垣接，池将沁水通。","枝交帝女树，桥映美人虹。","想是忘机者，悠悠在兴中。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"相思","mood2":["恬淡"],"scene":[],"cats":{"抒情":["思念"],"山水":["庐山"],"人物":["女子"],"生活":["写桥"]},"theme_conf":0.695},{"uid":"bd285a68-be33-4ac0-b7ca-0dbd2b19b885","title":"平齐行二首 二","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["泰山沈寇六十年，旅祭不享生愁烟。","今逢圣君欲封禅，神使阴兵来阻战。","妖氛扫尽河水清，日观杲杲卿云见。","开元黄帝东封时，百神受职争奔驰。","千钧猛簴顺流下，洪波涵淡浮熊罴。","侍臣燕公秉文笔，玉检告天无媿词。","当今睿孙承圣祖，岳神望幸河宗舞。","青门大道属车尘，共待葳蕤翠华举。"],"theme":"应制干谒","theme2":["边塞征战","闺情宫怨","哲理悟道"],"style":"绮丽","style2":["清新"],"mood":"愁怨","mood2":["恬淡"],"scene":["山"],"cats":{"抒情":["伤感","闺怨"],"山水":["泰山"],"人生":["哲理","战争"]},"theme_conf":0.82},{"uid":"ac3757d4-033b-4c69-baf8-8558055d42d4","title":"陈后宫","author":"李商隐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["玄武开新苑，龙舟䜩幸频。","渚莲参法驾，沙鸟犯句陈。","寿献金茎露，歌翻玉树尘。","夜来江令醉，别诏宿临春。"],"theme":"闺情宫怨","theme2":["送别"],"style":"绮丽","style2":["清新"],"mood":"愁怨","mood2":[],"scene":["江","端午","舟","春","夜"],"cats":{"抒情":["闺怨"],"四季":["春天"],"节日":["端午节"]},"theme_conf":0.637},{"uid":"4be77185-992e-4614-9746-de2e73c8a3c3","title":"关山月","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["明月出天山，苍茫云海间。","长风几万里，吹度玉门关。","汉下白登道，胡窥青海湾。","由来征战地，不见有人还。","[戍]客望边色，思归多苦颜。","高楼当此夜，叹息未应闲。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["雄浑"],"mood":"相思","mood2":[],"scene":["山","月"],"cats":{"抒情":["思念"],"天气":["月亮"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.512},{"uid":"cp3132bc43c19b92","title":"摸鱼儿","author":"刘辰翁","dynasty":"宋","section":"宋词","form":"词","paragraphs":["怎知他、春归何处，相逢且尽尊酒。","少年袅袅天涯恨，长结西湖烟柳。","休回首。","但细雨断桥，憔悴人归后。","东风似旧。","问前度桃花，刘郎能记，花复认郎否。","君且住，草草留君翦韭。","前宵更恁时候。","深杯欲共歌声滑，翻湿春衫半袖。","空眉皱。","看白发尊前，已似人人有。","临分把手。","叹一笑论文，清狂顾曲，此会几时又。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["旷达","豪放"],"mood":"愁怨","mood2":[],"scene":["春","雨","酒","夜","江南"],"cats":{"抒情":["思乡"],"四季":["春天"],"山水":["西湖"],"天气":["写雨"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"cp6c9ac421dd02c8","title":"齐天乐","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["烟波桃叶西陵路，十年断魂潮尾。","古柳重攀，轻鸥聚别，陈迹危亭独倚。","凉飔乍起。","渺烟碛飞帆，暮山横翠。","但有江花，共临秋镜照憔悴。","华堂烛暗送客，眼波回盼处，芳艳流水。","素骨凝冰，柔葱蘸雪，犹忆分瓜深意。","清尊未洗。","梦不湿行云，漫沾残泪。","可惜秋宵，乱蛩疏雨里。"],"theme":"送别","theme2":["山水田园"],"style":"婉约","style2":["沉郁"],"mood":"欢愉","mood2":["相思","孤寂"],"scene":["江","雪","冬"],"cats":{"抒情":["思念","伤感","孤独"]},"theme_conf":0.505},{"uid":"9391ef33-933e-452d-8fc3-5c6ccfe8eb12","title":"和崔中丞中秋月","author":"张南史","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["秋夜月偏明，西楼独有情。","千家看露湿，万里觉天清。","映水金波动，衔山桂树生。","不知飞鹊意，何用此时惊。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["月","中秋","秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.84},{"uid":"d9afbbdc-a953-44c7-93c6-dd133a03a2cd","title":"送辽阳使还军","author":"李益","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["征人歌且行，北上辽阳城。","二月戎马息，悠悠边草生。","青山出塞断，代地入云平。","昔者匈奴战，多闻杀汉兵。","平生报国愤，日夜角弓鸣。","勉君万里去，勿使虏尘惊。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外","月","夜","山"],"cats":{"抒情":["爱国"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.666},{"uid":"c39225f9-16b2-4713-a11c-d7030ec3b1c9","title":"长干曲四首 一","author":"崔颢","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["君家何处住？妾住在横塘。","停船暂借问，或恐是同乡。"],"theme":"羁旅思乡","theme2":["闺情宫怨"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["舟"],"cats":{"抒情":["思乡","闺怨"]},"theme_conf":0.594},{"uid":"37cd5393-d24a-426a-9c53-a774251bd650","title":"蒙山作","author":"萧颖士","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东蒙镇海沂，合沓余百里。","清秋净氛霭，崖崿隐天起。","于役劳往还，息徒暂攀跻。","将穷绝迹处，偶得冥心理。","云气杂虹霓，松声乱风水。","微明绿林际，杳窱丹洞里。","仙鸟时可闻，羽人邈难视。","此焉多深邃，贤达昔所止。","子尚捐俗纷，季随蹑遐轨。","蕴真道弥旷，怀古情未已。","白鹿凡几游，黄精复奚似。","顾予尚牵缠，家业重书史。","少学务从师，壮年贵趋仕。","方驰桂林誉，未暇桃源美。","岁暮期再寻，幽哉羡门子。"],"theme":"山水田园","theme2":["游仙梦幻"],"style":"清新","style2":["旷达"],"mood":"慷慨","mood2":[],"scene":["山","秋"],"cats":{"抒情":["怀古"],"四季":["秋天"],"天气":["彩虹"]},"theme_conf":0.435},{"uid":"38438036-586a-47f6-a4c0-d75bc30801c0","title":"相和歌辞 从军行二首 一","author":"虞世南","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["涂山烽候惊，弭节度龙城。","冀马楼兰将，燕犀上谷兵。","劒寒花不落，弓晓月逾明。","凛凛严霜节，冰壮黄河绝。","蔽日卷征蓬，浮天散飞雪。","全兵值月满，精骑乘胶折。","结发早驱驰，辛苦事旌麾。","马冻重关冷，轮摧九折危。","独有西山将，年年属数奇。"],"theme":"边塞征战","theme2":[],"style":"幽峭","style2":["清新"],"mood":"孤寂","mood2":["慷慨"],"scene":["雪","冬","江"],"cats":{"抒情":["孤独"],"山水":["黄河"],"天气":["写雪"],"生活":["边塞"]},"theme_conf":0.776},{"uid":"4c745990-657a-41fe-ba2c-d9cf371ca563","title":"贼平后送人北归","author":"司空曙","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["世乱同南去，时清独北还。","他乡生白发，旧国见青山。","晓月过残垒，繁星宿故关。","寒禽与衰草，处处伴愁颜。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["清新"],"mood":"愁怨","mood2":["孤寂"],"scene":["月","山"],"cats":{"抒情":["伤感","孤独"]},"theme_conf":0.725},{"uid":"9f32abfa-6459-4020-b79d-5f96a026c945","title":"九月十日雨中过张伯佳期柳镇未至以诗招之","author":"李益","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["柳吴兴近无消息，张长公贫苦寂寥。","唯有角巾沾雨至，手持残菊向西招。"],"theme":"爱情相思","theme2":["咏史怀古"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["雨","月"],"cats":{"抒情":["怀古"],"天气":["写雨","月亮"],"植物":["柳树"]},"theme_conf":0.574},{"uid":"e953a74d-4075-48bb-928f-114d0cd1a9eb","title":"哭单父梁九少府","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["开箧泪沾臆，见君前日书。","夜台今寂寞，独是子云居。","畴昔探云奇，登临赋山水。","同舟南浦下，望月西江里。","契阔多别离，绸缪到生死。","九原即何处，万事皆如此。","晋山徒峨峨，斯人已冥冥。","常时禄且薄，殁后家复贫。","妻子在远道，弟兄无一人。","十上多苦辛，一官恒自哂。","青云将可致，白日忽先尽。","唯有身后名，空留无远近。"],"theme":"送别","theme2":["悼亡挽歌"],"style":"沉郁","style2":["冲淡"],"mood":"孤寂","mood2":["悲怆"],"scene":["舟","山"],"cats":{"抒情":["离别","伤感","孤独","悼亡"],"人物":["父亲"]},"theme_conf":0.371},{"uid":"0ed53ef4-30ca-41ac-a629-d778e5cc2bfa","title":"相和歌辞 从军行","author":"李颀","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["白日登山望烽火，昏黄饮马傍交河。","行人刁斗风砂暗，公主琵琶幽怨多。","野营万里无城郭，雨雪纷纷连大漠。","胡雁哀鸣夜夜飞，胡儿眼泪双双落。","闻道玉门犹被遮，应将性命逐轻车。","年年战骨埋荒外，空见蒲萄入汉家。"],"theme":"边塞征战","theme2":[],"style":"婉约","style2":["豪放","雄浑"],"mood":"愁怨","mood2":[],"scene":["冬"],"cats":{"抒情":["伤感"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.748},{"uid":"47c36bbc-9c5d-474e-a665-96380be371b7","title":"言行相顾","author":"吴叔达","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["圣人垂政教，万古请常传。","立志言为本，修身行乃先。","相须宁得阙，相顾在无偏。","荣辱当于己，忠贞必动天。","大名如副宝，至道亦通玄。","千里犹能应，何云迩者焉。"],"theme":"羁旅思乡","theme2":[],"style":"雄浑","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"人生":["励志"]},"theme_conf":0.65},{"uid":"04bf9a4a-a4fc-4ad0-95f0-ee3c63af195c","title":"熟食日示宗文宗武","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["消渴游江汉，羇栖尚甲兵。","几年逢熟食，万里逼清明。","松柏邛山路，风花白帝城。","汝曹催我老，回首泪纵横。"],"theme":"亲情","theme2":[],"style":"豪放","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["清明"],"cats":{"抒情":["伤感"],"节日":["清明节"]},"theme_conf":0.82},{"uid":"7a4aebc8-e23e-42b7-8ccb-8a40366adcee","title":"隔浦莲","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["隔浦爱红莲，昨日看犹在。","夜来风吹落，只得一回采。","花开虽有明年期，复愁明年还暂时。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["花","夜"],"cats":{"抒情":["伤感"],"植物":["荷花"]},"theme_conf":1.0},{"uid":"c3c25268-b08b-4126-8e77-141cf5bbeaad","title":"茂陵村行赠何兆","author":"李端","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["春天黄鸟啭，野迳白云闲。","解带依芳草，支颐想故山。","人行九州路，树老五陵间。","谁道临邛远，相如自忆还。"],"theme":"寄赠酬答","theme2":["山水田园","咏史怀古"],"style":"婉约","style2":[],"mood":"恬淡","mood2":["相思"],"scene":["春","山"],"cats":{"抒情":["思念","怀古"],"四季":["春天"],"生活":["乡村"]},"theme_conf":0.64},{"uid":"b0394c9f-7d5a-4880-a96a-b9211aecc6db","title":"王敬伯歌","author":"李端","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["妾本舟中女，闻君江上琴。","君初感妾意，妾亦感君心。","遂出合欢被，同为交颈禽。","传杯唯畏浅，接膝犹嫌远。","侍婢奏箜篌，女郎歌宛转。","宛转怨如何，中庭霜渐多。","霜多叶可惜，昨日非今夕。","徒结万重欢，终成一宵客。","王敬伯，绿水青山从此隔。"],"theme":"闺情宫怨","theme2":["题画咏艺","羁旅思乡"],"style":"清新","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["舟"],"cats":{"抒情":["思乡","伤感","闺怨","感恩"]},"theme_conf":0.369},{"uid":"cp29e160902dce30","title":"六丑","author":"彭元逊","dynasty":"宋","section":"宋词","form":"词","paragraphs":["似东风老大，那复有、当时风气。","有情不收，江山身是寄。","浩荡何世。","但忆临官道，暂来不住，便出门千里。","痴心指望回风坠。","扇底相逢，钗头微缀。","他家万条千缕，解遮亭障驿，不隔江水。","瓜洲曾舣，等行人岁岁。","日下长秋，城乌夜起。","帐庐好在春睡。","共飞归湖上，草青无地。","雨、春心如腻。","欲待化、丰乐楼前，青门都废。","何人念、流落无几。","点点抟作，雪绵松润，为君泪。"],"theme":"羁旅思乡","theme2":["送别","山水田园"],"style":"婉约","style2":["沉郁"],"mood":"相思","mood2":[],"scene":["江","春","楼"],"cats":{"抒情":["思念","思乡"],"四季":["春天"]},"theme_conf":0.415},{"uid":"1575c835-1241-4d7b-99dc-6d700549ac65","title":"渭城曲","author":"王维","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["渭城朝雨浥轻尘，客舍青青杨柳春。","劝君更尽一杯酒，西出阳关无故人。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["酒","春"],"cats":{"抒情":["友情"],"四季":["春天"]},"theme_conf":0.589},{"uid":"1bcd81fb-6fb5-4994-b9ec-6baf5bbd4142","title":"遣兴五首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["朔风飘胡雁，惨澹带砂砾。","长林何萧萧，秋草萋更碧。","北里富熏天，高楼夜吹笛。","焉知南邻客，九月犹𫄨绤。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":["欢愉"],"scene":["夜","秋","楼","月","冬","鸟"],"cats":{"抒情":["思乡"],"四季":["秋天","冬天"],"天气":["写风"]},"theme_conf":0.551},{"uid":"af29ed64-419d-4eeb-803a-8466d45a7a2b","title":"昼梦","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["二月饶睡昏昏然，不独夜短昼分眠。","桃花气暖眼自醉，春渚日落梦相牵。","故乡门巷荆棘底，中原君臣豺虎边。","安得务农息战鬬，普天无吏横索钱。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["春","月","夜","酒"],"cats":{"抒情":["思乡","孤独"],"四季":["春天"],"人生":["梦想"]},"theme_conf":0.658},{"uid":"6dcc533e-01af-48f9-835f-47f087bc81c7","title":"酬李二十二兄主簿马迹山见寄","author":"权德舆","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["杳杳尘外想，悠悠区中缘。","如何战未胜，曾是教所牵。","远郊有灵峰，夙昔栖真仙。","鸾声去已久，马迹空依然。","丹崖转初旭，碧落凝秋烟。","松风共箫飒，萝月想婵娟。","内兄蕴遐心，嘉遯性所便。","不能栖枳棘，且复探云泉。","中有冥寂人，闲读逍遥篇。","联袂共支[策]，抠衣赏绝编。","徐行石上苔，静韵风中弦。","烟霞湿儒服，日月生寥天。","新诗来起予，璀璨六义全。","能尽含写意，转令山水鲜。","若闻笙鹤声，宛在耳目前。","登攀阻心赏，愁绝空怀贤。","出处岂异途，心冥即真筌。","𫏐从西府檄，终卧东菑田。","不嫌予步蹇，但恐君行膻。","如能固旷怀，谷口期穷年。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["恬淡","愁怨"],"scene":["山"],"cats":{"抒情":["伤感"],"天气":["月亮"],"节日":["中秋节"],"动物":["写马"]},"theme_conf":0.457},{"uid":"872fd5bd-c6d8-4aef-bc03-85ac1550b561","title":"羌村 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["峥嵘赤云西，日脚下平地。","柴门鸟雀噪，归客千里至。","妻孥怪我在，惊定还拭泪。","世乱遭飘荡，生还偶然遂。","邻人满墙头，感叹亦歔欷。","夜阑更秉烛，相对如梦寐。"],"theme":"山水田园","theme2":["边塞征战"],"style":"幽峭","style2":["雄浑","婉约"],"mood":"愁怨","mood2":[],"scene":["夜"],"cats":{"抒情":["伤感"],"生活":["乡村"]},"theme_conf":0.47},{"uid":"e8cc31e9-6b51-4a37-818b-7891dfb9677c","title":"哭陆处士","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["从此无期见，柴门对雪开。","二毛逢世难，万恨掩泉台。","返照空堂夕，孤城吊客回。","汉家偏访道，犹畏鹤书来。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["孤寂"],"scene":["雪"],"cats":{"抒情":["孤独","悼亡"]},"theme_conf":0.99},{"uid":"8502e6fa-f283-440a-a69a-12bb1b54610f","title":"酬盩厔耿少府𣲗见寄","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["方丈萧萧落叶中，暮天深巷起悲风。","流年不尽人自老，外事无端心已空。","家近小山当海畔，身留环衞荫墙东。","遥闻相访频逢雪，一醉寒宵谁与同。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["沉郁","悲慨"],"mood":"悲怆","mood2":["孤寂","惆怅"],"scene":["雪","山","酒","夜"],"cats":{"抒情":["伤感"],"人生":["时光"]},"theme_conf":0.95},{"uid":"88abad3a-4ba9-461a-a592-34eb50aa80ef","title":"湖城东遇孟云卿复归刘颢宅宿宴饮散因为醉歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["疾风吹尘暗河县，行子隔手不相见。","湖城城南一开眼，驻马偶识云卿面。","向非刘颢为地主，嬾回鞭辔成高宴。","刘侯叹我携客来，置酒张灯促华馔。","且将款曲终今夕，休语艰难尚酣战。","照室红炉促曙光，萦窗素月垂文练。","天开地裂长安陌，寒尽春生洛阳殿。","岂知驱车复同轨，可惜刻漏随更箭。","人生会合不可常，庭树鸡鸣泪如线。"],"theme":"羁旅思乡","theme2":["闲适隐逸"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["酒","江","夜"],"cats":{"抒情":["思乡","伤感"],"天气":["写云"],"食物":["写酒"]},"theme_conf":0.381},{"uid":"b7dd27c6-0626-42da-a842-380334fadf9a","title":"寄上礼部李侍郎","author":"崔峒","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["吴楚相逢处，江湖共泛时。","任风舟去远，待月酒行迟。","白发常同欢，青云本要期。","贵来君却少，秋至老偏悲。","玉佩明朝盛，苍苔陋巷滋。","追寻恨无路，唯有梦相思。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["悲慨"],"mood":"相思","mood2":[],"scene":["江","舟","酒","秋","月"],"cats":{"抒情":["思念"],"四季":["秋天"],"人生":["梦想"]},"theme_conf":0.95},{"uid":"1168acab-dc79-42cd-82a8-439ee1fc51ae","title":"杂曲歌辞 十二月乐辞 七月","author":"李贺","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["星依云渚冷，露滴盘中圆。","好花生木末，衰蕙愁空园。","夜天如玉砌，池叶极青钱。","仅厌舞衫薄，稍知花簟寒。","晓风何拂拂，北斗光阑干。"],"theme":"节令风俗","theme2":[],"style":"幽峭","style2":["清新"],"mood":"欢愉","mood2":["愁怨","孤寂"],"scene":["园林","月"],"cats":{"抒情":["伤感"],"天气":["月亮","星星"]},"theme_conf":0.9},{"uid":"56bec3c2-9c0c-4d40-9750-2e28bdc9a20e","title":"送綦毋潜落第还乡","author":"王维","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["圣代无隐者，英灵尽来归。","遂令东山客，不得顾采薇。","既至君门远，孰云吾道非。","江淮度寒食，京洛缝春衣。","置酒临长道，同心与我违。","行当浮桂櫂，未几拂荆扉。","远树带行客，孤村当落晖。","吾谋适不用，勿谓知音稀。"],"theme":"送别","theme2":["羁旅思乡"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["清明","春","酒"],"cats":{"抒情":["友情","思乡","孤独"],"四季":["春天"],"节日":["寒食节","清明节"]},"theme_conf":0.443},{"uid":"d2d9fa8e-5872-480a-ad45-b1b62af3619a","title":"题洛苑梧叶上","author":"天宝宫人","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["旧宠悲秋扇，新恩寄早春。","聊题一片叶，将寄接流人。"],"theme":"咏物","theme2":["送别"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["秋","春"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"],"植物":["叶子"]},"theme_conf":0.47},{"uid":"0d8d840d-1f94-44da-9b52-18a01cf8ed82","title":"下第日书情寄上叔父","author":"司空曙","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["微才空觉滞京师，末学曾为叔父知。","雪里题诗偏见赏，林间饮酒独令随。","游客尽伤春色老，贫居还惜暮阴移。","欲归江海寻山去，愿报何人得桂枝。"],"theme":"寄赠酬答","theme2":["亲情"],"style":"沉郁","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":["雪","酒","春","江","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"人物":["父亲"]},"theme_conf":0.8},{"uid":"e2595ed8-1345-4194-86f6-ec71bd785110","title":"同诸公登慈恩寺塔","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["高标跨苍天，烈风无时休。","自非旷士怀，登兹翻百忧。","方知象教力，足可追冥搜。","仰穿龙蛇窟，始出枝撑幽。","七星在北户，河汉声西流。","羲和鞭白日，少昊行清秋。","秦山忽破碎，泾渭不可求。","俯视但一气，焉能辨皇州。","回首叫虞舜，苍梧云正愁。","惜哉瑶池饮，日宴昆仑丘。","黄鹄去不息，哀鸣何所投。","君看随阳雁，各有稻粱谋。"],"theme":"咏史怀古","theme2":["哲理悟道","咏史怀古","游仙梦幻"],"style":"冲淡","style2":[],"mood":"愁怨","mood2":[],"scene":["重阳","秋"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"节日":["重阳节"]},"theme_conf":0.6},{"uid":"0a988f56-b22d-48cb-94f1-fc75e2532eab","title":"长相思","author":"刘复","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["长相思，在桂林，苍梧山远潇湘深。","秋堂零泪倚金瑟，朱颜摇落随光阴。","长宵嘹唳鸿命侣，河汉苍苍隔牛女。","宁知一水不可渡，况复万山修且阻。","彩丝织绮文双鸳，昔时赠君君可怜。","何言一去瓶落井，流尘歇灭金炉前。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":["婉约","雄浑"],"mood":"相思","mood2":[],"scene":["七夕","秋","山"],"cats":{"抒情":["爱情","思念"],"四季":["秋天"],"人生":["时光"],"节日":["七夕节"]},"theme_conf":0.705},{"uid":"cp3e738af0f919e6","title":"甘州・八声甘州","author":"张炎","dynasty":"宋","section":"宋词","form":"词","paragraphs":["记玉关、踏雪事清游。","寒气脆貂裘。","傍枯林古道，长河饮马，此意悠悠。","短梦依然江表，老泪洒西州。","一字无题处，落叶都愁。","载取白云归去，问谁留楚佩，弄影中洲。","折芦花赠远，零落一身秋。","向寻常野桥流水，待招来、不是旧沙鸥。","空怀感，有斜阳处，却怕登楼。"],"theme":"山水田园","theme2":["羁旅思乡","送别"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","江","雪"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"生活":["写桥"]},"theme_conf":0.358},{"uid":"cp2a56a9bb8978f0","title":"三台","author":"万俟咏","dynasty":"宋","section":"宋词","form":"词","paragraphs":["见梨花初带夜月，海棠半含朝雨。","内苑春、不禁过青门，御沟涨、潜通南浦。","东风静、细柳垂金缕。","望凤阙、非烟非雾。","好时代、朝野多欢，遍九陌、太平箫鼓。","乍莺儿百啭断续，燕子飞来飞去。","近绿水、台榭映秋千，斗草聚、双双游女。","饧香更、酒冷踏青路。","会暗识、夭桃朱户。","向晚骤、宝马雕鞍，醉襟惹、乱花飞絮。","正轻寒轻暖漏永，半阴半晴云暮。","禁火天、已是试新妆，岁华到、三分佳处。","清明看、汉宫传蜡炬。","散翠烟、飞入槐府。","敛兵卫、阊阖门开，住传宣、又还休务。"],"theme":"节令风俗","theme2":["节令风俗","送别"],"style":"清新","style2":["婉约","绮丽"],"mood":"欢愉","mood2":[],"scene":["清明","春","夜","酒","楼"],"cats":{"抒情":["离别"],"四季":["春天"],"节日":["清明节"]},"theme_conf":0.86},{"uid":"12d952ff-d24d-4920-86ac-54e2f1404375","title":"贞元末东院尝接事今西川武相公于兹三周谬领中宪徘徊厅宇多获文篇夏日即事因寄四韵","author":"窦群","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["重轩深似谷，列柏镇含烟。","境绝苍蝇到，风生白雪前。","弹冠惊迹近，专席感恩偏。","霄汉朝来下，油幢路几千。"],"theme":"寄赠酬答","theme2":["应制干谒"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["夏","园林"],"cats":{"抒情":["感恩"],"四季":["夏天"]},"theme_conf":0.9},{"uid":"57444b76-3bd5-4667-8998-b0888da88a61","title":"送叶秀才","author":"王初","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["快骑璁珑刻玉羁，河梁返照上征衣。","层冰春近蟠龙起，九泽云闲独鹤飞。","行想北山清梦断，重游西洛故人稀。","汉庭狗监深知己，有日前驱负弩归。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["春","冬","山","园林"],"cats":{"抒情":["友情","孤独"],"四季":["春天"],"植物":["叶子"]},"theme_conf":0.649},{"uid":"fcf8623a-3c01-4bea-94cd-663e6b2a2f76","title":"又酬晓灯[离暗]室五首 三","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["灯光照虚屋，雨影悬空壁。","一向簷下声，远来愁处滴。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":["冲淡"],"mood":"愁怨","mood2":[],"scene":["元宵","夜"],"cats":{"抒情":["离别","思乡","伤感"],"节日":["元宵节"]},"theme_conf":0.7},{"uid":"632dc421-6fac-46f6-9e92-590d5adfb994","title":"题汉州西湖","author":"严公贶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["凤沼才难尽，余思凿西湖。","珍木罗修岸，冰光映坐隅。","琴台今寂寞，竹岛尚萦纡。","犹蕴济川志，芳名终不渝。"],"theme":"咏物","theme2":["山水田园"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["江南","江"],"cats":{"抒情":["孤独"],"山水":["西湖"]},"theme_conf":0.62},{"uid":"56f2dfa5-3d19-4b8f-a6da-8323290985ba","title":"杂诗","author":"独孤及","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["百花结成子，春物舍我去。","流年惜不得，独坐空闺暮。","心自有所待，甘为物华悮。","未必千黄金，买得一人顾。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独","闺怨"],"四季":["春天"],"人生":["时光"]},"theme_conf":1.0},{"uid":"dfb61907-f39f-4797-8ee8-4086c79317a9","title":"伤进士谢庭皓","author":"徐夤","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["献书犹未达明君，何事先游岱岳云。","惟有春风护冤魄，与生青草盖孤坟。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["园林","春"],"cats":{"抒情":["伤感","孤独","悼亡","感恩"],"四季":["春天"],"山水":["泰山"]},"theme_conf":0.98},{"uid":"fabc073e-fb05-46e9-92c1-398d7c47c759","title":"阳城驿","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["商有阳城驿，名同阳道州。","阳公没已久，感我泪交流。","昔公孝父母，行与曾闵俦。","既孤善兄弟，兄弟和且柔。","一夕不相见，若怀三岁忧。","遂誓不婚娶，没齿同衾裯。","妹夫死他县，遗骨无人收。","公令季弟往，公与仲弟留。","相别竟不得，三人同远游。","共负他乡骨，归来藏故丘。","栖迟居夏邑，邑人无苟媮。","里中竞长短，来问劣与优。","官刑一朝耻，公短终身羞。","公亦不遗布，人自不盗牛。","问公何能尔，忠信先自修。","发言当道理，不顾党与讐。","声香渐翕习，冠盖若云浮。","少者从公学，老者从公游。","往来相告报，县尹与公侯。","名落公卿口，涌如波荐舟。","天子得闻之，书下再三求。","书中愿一见，不异旱地虬。","何以持为聘，束帛藉琳球。","何以持为御，驷马驾安辀。","公方伯夷操，事殷不事周。","我实唐士庶，食唐之田畴。","我闻天子忆，安敢专自由。","来为谏大夫，朝夕侍冕旒。","希夷惇薄俗，密勿献良筹。","神医不言术，人瘼曾暗瘳。","月请谏官俸，诸弟相对谋。","皆曰亲戚外，酒散目前愁。","公云不有尔，安得此嘉猷。","施余尽酤酒，客来相献酬。","日旰不谋食，春深仍弊裘。","人心良戚戚，我乐独由由。","贞元岁云暮，朝有曲如钩。","风波势奔蹙，日月光绸缪。","齿牙属为猾，禾黍暗生蟊。","岂无司言者，肉食吞其喉。","岂无司搏者，利柄扼其鞲。","鼻复势气塞，不得辩薰莸。","公虽未显谏，惴惴如患瘤。","飞章八九上，皆若珠暗投。","炎炎日将炽，积燎无人抽。","公乃帅其属，决谏同报仇。","延英殿门外，叩合仍叩头。","且曰事不止，臣谏誓不休。","上知不可遏，命以美语酬。","降官司成署，俾之为赘疣。","奸心不快活，击刺砺戈矛。","终为道州去，天道竟悠悠。","遂令不言者，反以言为訧。","喉舌坐成木，鹰鹯化为鸠。","避权如避虎，冠豸如冠猴。","平生附我者，诗人称好逑。","私来一执手，恐若坠诸沟。","送我不出户，决我不回眸。","唯有太学生，各具粮与糇。","咸言公去矣，我亦去荒陬。","公与诸生别，步步驻行驺。","有生不可诀，行行过闽瓯。","为师得如此，得为贤者不。","道州闻公来，鼓舞歌且讴。","昔公居夏邑，狎人如狎鸥。","况自为刺史，岂复援鼓桴。","滋章一时罢，教化天下遒。","炎瘴不得老，英华忽已秋。","有鸟哭杨震，无儿悲邓攸。","唯余门弟子，列树松与楸。","今来过此驿，若吊汨罗洲。","祠曹讳羊祜，此驿何不侔。","我愿避公讳，名为避贤邮。","此名有深意，蔽贤天所尤。","吾闻玄元教，日月冥九幽。","幽阴蔽翳者，永为幽翳囚。"],"theme":"咏史怀古","theme2":["送别","边塞征战"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["孤寂","愁怨"],"scene":["夏","月"],"cats":{"抒情":["伤感","孤独","怀古"],"四季":["夏天"],"生活":["边塞"],"节日":["端午节"]},"theme_conf":0.96},{"uid":"f0cd6afd-c89d-4fc3-b214-bcbf63042e8e","title":"喜外弟卢纶见宿","author":"司空曙","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["静夜四无邻，荒居旧业贫。","雨中黄叶树，灯下白头人。","以我独沈久，愧君相见频。","平生自有分，况是蔡家亲。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":["恬淡"],"scene":["夜","雨"],"cats":{"抒情":["思乡"]},"theme_conf":1.0},{"uid":"bce77cf0-244d-435a-8a25-8d28a83bc4b9","title":"奉赠韦左丞二十二韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["纨袴不饿死，儒冠多误身。","丈人试静听，贱子请具陈。","甫昔少年日，早充观国宾。","读书破万卷，下笔如有神。","赋料扬雄敌，诗看子建亲。","李邕求识面，王翰愿卜邻。","自谓颇挺出，立登要路津。","致君尧舜上，再使风俗淳。","此意竟萧条，行歌非隐沦。","骑驴三十载，旅食京华春。","朝扣富儿门，暮随肥马尘。","残杯与冷炙，到处潜悲辛。","主上顷见征，歘然欲求伸。","青冥却垂翅，蹭蹬无纵鳞。","甚媿丈人厚，甚知丈人真。","每于百僚上，猥诵佳句新。","窃效贡公喜，难甘原宪贫。","焉能心怏怏，秪是走踆踆。","今欲东入海，即将西去秦。","尚怜终南山，回首清渭滨。","常拟报一饭，况怀辞大臣。","白鸥没浩荡，万里谁能驯。"],"theme":"应制干谒","theme2":[],"style":"豪放","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":["山"],"cats":{"抒情":["伤感"],"人生":["读书"]},"theme_conf":0.97},{"uid":"ef63c450-f64a-4b8b-8284-78685e90601d","title":"白菊杂书四首 四","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["黄鹂啭处谁同听，白菊开时且剩过。","漫道南朝足流品，由来叔宝不宜多。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["重阳"],"cats":{"抒情":["怀古"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.72},{"uid":"a7318ace-183f-44e8-9704-3fceabe908be","title":"人日寄杜二拾遗","author":"高适","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["人日题诗寄草堂，遥怜故人思故乡。","柳条弄色不忍见，梅花满枝空断肠。","身在远藩无所预，心怀百忧复千虑。","今年人日空相忆，明年人日知何处。","一卧东山三十春，岂知书劒老风尘。","龙钟还忝二千石，愧尔东西南北人。"],"theme":"寄赠酬答","theme2":["送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["春"],"cats":{"抒情":["友情","思念","思乡","伤感"],"四季":["春天"],"天气":["太阳"]},"theme_conf":0.94},{"uid":"cpc4da66c71f7c81","title":"三姝媚","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["湖山经醉惯。","溃春衫、啼痕酒痕无限。","又客长安，叹断襟零袂，尘谁浣。","紫曲门荒，沿败井、风摇青蔓。","对语东邻，犹是曾巢，谢堂双燕。","春梦人间须断。","但怪得、当年梦缘能短。","绣屋秦筝，傍海棠偏爱，夜深开宴。","舞歇歌沈，花未减、红颜先变。","伫久河桥欲去，斜阳泪满。"],"theme":"羁旅思乡","theme2":[],"style":"豪放","style2":["绮丽","幽峭"],"mood":"愁怨","mood2":[],"scene":["酒","春","花"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"07bec374-ff61-4d05-842c-c57c25f1d888","title":"陪杜侍御游湘西两寺独宿有题一首因献杨常侍","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["长沙千里平，胜地犹在险。","况当江阔处，斗起势匪渐。","深林高玲珑，青山上琬琰。","路穷台殿辟，佛事焕且俨。","剖竹走泉源，开廊架崖广。","是时秋之残，暑气尚未歛。","群行忘后先，朋息弃拘检。","客堂喜空凉，华榻有清簟。","涧蔬煮蒿芹，水果剥菱芡。","伊余夙所慕，陪赏亦云忝。","幸逢车马归，独宿门不掩。","山楼黑无月，渔火灿星点。","夜风一何喧，杉桧屡磨飐。","犹疑在波涛，怵惕梦成魇。","静思屈原沈，远忆贾谊贬。","椒兰争妬忌，绛灌共谗谄。","谁令悲生肠，坐使泪盈脸。","翻飞乏羽翼，指摘困瑕玷。","珥貂藩维重，政化类分陕。","礼贤道何优，奉己事苦俭。","大厦栋方隆，巨川檝行剡。","经营诚少暇，游宴固已歉。","旅程愧淹留，徂岁嗟荏苒。","平生每多感，柔翰遇频染。","展转岭猿鸣，曙灯青睒睒。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"婉约","style2":["冲淡","沉郁"],"mood":"孤寂","mood2":["欢愉"],"scene":["山","楼","夜","端午","夏"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["夏天"],"节日":["端午节"]},"theme_conf":0.433},{"uid":"306c2503-eff5-418b-873e-c72596a676bd","title":"杂曲歌辞 春江曲","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["春江无云潮水平，蒲心出水凫雏鸣。","长干夫壻爱远行，自染春衣缝已成。","妾身生长金陵侧，去年随夫住江北。","春来未到父母家，舟小风多渡不得。","欲辞舅姑先问人，私向江头祭水神。"],"theme":"闺情宫怨","theme2":["亲情","山水田园"],"style":"悲慨","style2":[],"mood":"惆怅","mood2":[],"scene":["江","春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"山水":["江河"]},"theme_conf":0.85},{"uid":"6c9acc43-e0e0-4509-94b9-2f877ea705e1","title":"述旧纪勋太原寄李光颜侍中二首 二","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["倚天长劒截云孤，报国纵横见丈夫。","五载登坛真宰相，六重分阃正司徒。","曾闻转战平坚寇，共说题诗压腐儒。","料敌知机在方寸，不劳心力讲阴符。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":[],"cats":{"抒情":["爱国"]},"theme_conf":0.88},{"uid":"b3de619f-cc8b-457d-942b-49f06651aba4","title":"蝉","author":"李商隐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["本以高难饱，徒劳恨费声。","五更疎欲断，一树碧无情。","薄宦梗犹泛，故园芜已平。","烦君最相警，我亦举家清。"],"theme":"咏物","theme2":["羁旅思乡"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["园林"],"cats":{"抒情":["思乡"]},"theme_conf":0.643},{"uid":"262d09ef-c986-4c06-81a4-9a75c6d83719","title":"岳阳楼别窦司直","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["洞庭九州间，厥大谁与让。","南汇群崖水，北注何奔放。","潴为七百里，吞纳各殊状。","自古澄不清，环混无归向。","炎风日搜搅，幽怪多冗长。","轩然大波起，宇宙隘而妨。","巍峩拔嵩华，腾踔较健壮。","声音一何宏，轰輵车万两。","犹疑帝轩辕，张乐就空旷。","蛟螭露笋簴，缟练吹组帐。","鬼神非人世，节奏颇跌踼。","阳施见夸丽，阴闭感凄怆。","朝过宜春口，极北缺隄障。","夜缆巴陵洲，丛芮才可傍。","星河尽涵泳，俯仰迷下上。","余澜怒不已，喧聒鸣瓮盎。","明登岳阳楼，辉焕朝日亮。","飞廉戢其威，清晏息纤纩。","泓澄湛凝绿，物影巧相况。","江豚时出戏，惊波忽荡瀁。","时当冬之孟，隙窍缩寒涨。","前临指近岸，侧坐眇难望。","涤濯神魂醒，幽怀舒以畅。","主人孩童旧，握手乍忻怅。","怜我窜逐归，相见得无恙。","开筵交履舃，烂漫倒家酿。","杯行无留停，高柱送清唱。","中盘进橙栗，投掷倾脯酱。","欢穷悲心生，婉娈不能忘。","念昔始读书，志欲干霸王。","屠龙破千金，为艺亦云亢。","爱才不择行，触事得谗谤。","前年出官由，此祸最无妄。","公卿采虚名，擢拜识天仗。","奸猜畏弹射，斥逐恣欺诳。","新恩移府庭，逼侧厕诸将。","于嗟苦驽缓，但惧失宜当。","追思南渡时，鱼腹甘所葬。","严程迫风帆，劈箭入高浪。","颠沈在须臾，忠鲠谁复谅。","生还真可喜，尅己自惩创。","庶从今日后，粗识得与丧。","事多改前好，趣有获新尚。","誓耕十亩田，不取万乘相。","细君知蚕织，稚子已能饷。","行当挂其冠，生死君一访。"],"theme":"送别","theme2":[],"style":"清新","style2":["幽峭"],"mood":"欢愉","mood2":["慷慨","悲怆"],"scene":["楼","江"],"cats":{"抒情":["离别","伤感"],"天气":["星星"],"人物":["儿童"],"人生":["读书"]},"theme_conf":0.467},{"uid":"91233d92-0156-4ead-9981-a5b834f9a3d2","title":"杜鹃行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见昔日蜀天子，化作杜鹃似老乌。","寄巢生子不自啄，群鸟至今与哺雏。","虽同君臣有旧礼，骨肉满眼身羁孤。","业工窜伏深树里，四月五月偏号呼。","其声哀痛口流血，所诉何事常区区。","尔岂摧残始发愤，羞带羽翮伤形愚。","苍天变化谁料得，万事反复何所无。","万事反复何所无，岂忆当殿群臣趋。"],"theme":"咏物","theme2":["送别","亲情","山水田园"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["相思","惆怅"],"scene":["鸟"],"cats":{"抒情":["思念","伤感"],"动物":["写鸟"]},"theme_conf":0.9},{"uid":"1fc07309-faba-489d-924d-9c46e950a35c","title":"裴端公使院赋得隔帘见春雨","author":"包何","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["细雨未成霖，垂帘但觉阴。","唯看上砌湿，不遣入簷深。","度隟沾霜简，因风润绮琴。","须移户外屦，簷溜夜相侵。"],"theme":"咏物","theme2":["闺情宫怨"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["雨"],"cats":{"抒情":["闺怨"],"四季":["春天"],"天气":["写雨"]},"theme_conf":0.621},{"uid":"114a62cf-942e-4515-aa95-8988f3a30e72","title":"将归旧山留别孟郊","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["择木无利刃，羡鱼无巧纶。","如何不量力，自取中路贫。","前者不厌耕，一日不离亲。","今来千里外，我心不在身。","悠悠慈母心，惟愿才如人。","蚕桑能几许，衣服常著新。","一饭吐尺丝，谁见此殷勤。","别君归耕去，持火烧车轮。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"抒情":["离别","感恩"],"人物":["母亲"]},"theme_conf":0.483},{"uid":"25b83882-d6df-4662-9463-fdde2af46b26","title":"东渡早梅一树岁华如雪酣赏成咏","author":"羊士谔","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["暇日留囗事，期云亦囗开。","乡心持岁酒，津下赏山梅。","晚实和商鼎，浓香拂寿杯。","唯应招北客，日日踏青来。"],"theme":"咏物","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["冬","雪","酒"],"cats":{"抒情":["思乡"],"天气":["写雪"],"节日":["清明节"],"植物":["梅花"]},"theme_conf":0.572},{"uid":"b0d04448-935e-4e7a-ad7e-9a69c31b0ad7","title":"阆水歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["嘉陵江色何所似，石黛碧玉相因依。","正怜日破浪花出，更复春从沙际归。","巴童荡桨攲侧过，水鸡衔鱼来去飞。","阆中胜事可肠断，阆州城南天下稀。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"愁怨","mood2":["欢愉"],"scene":["春","江"],"cats":{"抒情":["伤感"],"四季":["春天"],"人生":["励志"]},"theme_conf":1.0},{"uid":"d8e0db16-f56c-4180-bc8f-9724551bd8fc","title":"横吹曲辞 前出塞九首 三","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["磨刀呜咽水，水赤刃伤手。","欲轻肠断声，心绪乱已久。","丈夫誓许国，愤惋复何有？","功名图麒麟，战骨当速朽。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外"],"cats":{"抒情":["伤感"],"人生":["战争"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"3383ff3c-b6bf-44b6-900a-766acc558644","title":"王兵马使二角鹰","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["悲台萧飒石巃嵸，哀壑杈枒浩呼汹。","中有万里之长江，回风滔日孤光动。","角鹰飜倒壮士臂，将军玉帐轩翠气。","二鹰猛脑徐侯穟，目如愁胡视天地。","杉鸡竹兔不自惜，溪虎野羊俱辟易。","鞲上锋棱十二翮，将军勇锐与之敌。","将军树勋起安西，昆仑虞泉入马蹄。","白羽曾肉三狻猊，敢决岂不与之齐。","荆南芮公得将军，亦如角鹰下翔云。","恶鸟飞飞啄金屋，安得尔辈开其群，驱出六合枭鸾分。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["绮丽"],"mood":"悲怆","mood2":["慷慨"],"scene":["江"],"cats":{"抒情":["伤感"],"山水":["长江"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.518},{"uid":"974914ee-1fc0-4952-a863-820bad2e4065","title":"为有","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["为有云屏无限娇，凤城寒尽怕春宵。","无端嫁得金龟壻，辜负香衾事早朝。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":["愁怨"],"scene":["春","夜"],"cats":{"抒情":["闺怨"],"四季":["春天"]},"theme_conf":0.7},{"uid":"b795db08-a132-4d2c-9925-654193077602","title":"喜弟淑再至为长歌","author":"李渤","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["前年别时秋九月，白露吹霜金吹烈。","离鸿一别影初分，泪袖双挥心哽咽。","别来几度得音书，南岳知□□□□。","庐山峨峨倚天碧，捧排空崖千万尺。","社牓长题高士名，食堂每记云山迹。","我本开云此山住，偶为名利相萦误。","自负心机四十年，羞闻社客山中篇。","忧时魂梦忆归路，觉来疑在林中眠。","昨日亭前乌鹊喜，果得今朝尔来此。","吾吟行路五十篇，尽说江南数千里。","自怜兄弟今五人，共萦儒素家尚贫。","虽然廪饩各不一，就中总免拘常伦。","长兄年少曾落托，拔劒沙场随卫霍。","口里虽谭周孔文，怀中不舍孙吴略。","次兄一生能苦节，夏聚流萤冬映雪。","非论疾恶志如霜，更觉临泉心似铁。","第三之兄更奇异，昂昂独负青云志。","下看金玉不如泥，肯道王侯身可贵。","却愁清逸不干时，高踪大器无人知。","倘逢感激许然诺，必能万古留清规。","念尔年来方二十，夙夜孜孜能独立。","卷中笔落星汉摇，洞里丹灵鬼神泣。","嗟余流浪心最狂，十年学劒逢时康。","心中不解事拘束，世间谈笑多相妨。","广海青山殊未足，逢著高楼还醉宿。","朝走安公枥上驹，暮伦陶令篱边菊。","近来诗思殊无况，苦被时流不相放。","云腾浪走势未衰，鹤膝蜂腰岂能障。","送尔为文殊不识，贵从一一传胷臆。","若到湖南见紫霄，会须待我同攀陟。"],"theme":"亲情","theme2":["山水田园","边塞征战"],"style":"豪放","style2":["沉郁","幽峭"],"mood":"愁怨","mood2":["欢愉","孤寂"],"scene":["山","江南","秋","冬","雪","夜"],"cats":{"抒情":["离别","伤感","孤独"],"四季":["秋天","冬天"],"山水":["庐山"],"人生":["励志","梦想","战争"],"生活":["边塞"]},"theme_conf":0.95},{"uid":"5aee2c13-785a-4735-8a13-069d126a37f6","title":"相和歌辞 采莲曲二首 一","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["弄舟朅来南塘水，荷叶映身摘莲子。","暑衣清净鸳鸯喜，作浪舞花惊不起。","殷勤护惜纤纤指，水菱初熟多新刺。"],"theme":"爱情相思","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["夏","舟"],"cats":{"抒情":["爱情"],"四季":["夏天"],"植物":["荷花"]},"theme_conf":0.527},{"uid":"e502aa21-de65-4abd-99ab-ba4773dfbf7e","title":"荅李滁州题庭前石竹花见寄","author":"独孤及","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["殷疑曙霞染，巧类匣刀裁。","不怕南风热，能迎小暑开。","游蜂怜色好，思妇感年催。","览赠添离恨，愁肠日几廻。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":["园林","花","夏"],"cats":{"抒情":["伤感"],"四季":["夏天"],"植物":["竹子"]},"theme_conf":0.76},{"uid":"d850db6a-e07b-4fee-b642-57a70bdbbed2","title":"宫词二首 一","author":"张祜","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["故国三千里，深宫二十年。","一声河满子，双泪落君前。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["伤感","闺怨","怀古"]},"theme_conf":0.822},{"uid":"cb65a8de-23eb-4aa0-a490-61fb8e57f42a","title":"登湓城浦望庐山初晴直省赍敕催赴江阴","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["西望香炉雪，千峰晚色新。","白头悲作吏，黄纸苦催人。","多负登山屐，深藏漉酒巾。","伤心公府内，手板日相亲。"],"theme":"山水田园","theme2":["咏史怀古"],"style":"清新","style2":[],"mood":"悲怆","mood2":["相思"],"scene":["山"],"cats":{"抒情":["伤感","怀古"],"山水":["庐山"]},"theme_conf":0.562},{"uid":"6b074b75-44be-4068-bc31-c4f2cea7287f","title":"相和歌辞 襄阳曲","author":"施肩吾","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["大堤女儿郎莫寻，三三五五结同心。","清晨对镜冶容色，意欲取郎千万金。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["爱情"]},"theme_conf":1.0},{"uid":"efc46322-baf5-49cd-9988-7c7333a99a2b","title":"宋中别周梁李三子","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["曾是不得意，适来兼别离。","如何一尊酒，翻作满堂悲。","周子负高价，梁生多逸词。","周旋梁宋间，感激建安时。","白雪正如此，青云无自疑。","李侯怀英雄，肮脏乃天资。","方寸且无间，衣冠当在斯。","俱为千里游，忽念两乡辞。","且见壮心在，莫嗟携手迟。","凉风吹北原，落日满西陂。","露下草初白，天长云屡滋。","我心不可问，君去定何之。","京洛多知己，谁能忆左思。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"相思","mood2":["恬淡","悲怆"],"scene":["雪","酒"],"cats":{"抒情":["友情","离别","思念","伤感"]},"theme_conf":0.749},{"uid":"cp92f27b08a6a25e","title":"水调歌头","author":"苏轼","dynasty":"宋","section":"宋词","form":"词","paragraphs":["明月几时有，把酒问青天。","不知天上宫阙，今夕是何年。","我欲乘风归去，又恐琼楼玉宇，高处不胜寒。","起舞弄清影，何似在人间。","转朱阁，低绮户，照无眠。","不应有恨，何事长向别时圆。","人有悲欢离合，月有阴晴圆缺，此事古难全。","但愿人长久，千里共婵娟。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["豪放","清新"],"mood":"悲怆","mood2":["愁怨","欢愉"],"scene":["月","楼","中秋"],"cats":{"抒情":["离别","伤感"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":1.0},{"uid":"792e7017-3954-4a3b-a167-e183f17ca707","title":"七夕宴悬圃二首 二","author":"高宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["霓裳转云路，凤驾俨天潢。","亏星凋夜靥，残月落朝璜。","促欢今夕促，长离别后长。","轻梭聊驻织，掩泪独悲伤。"],"theme":"节令风俗","theme2":[],"style":"婉约","style2":["沉郁","悲慨"],"mood":"欢愉","mood2":[],"scene":["七夕"],"cats":{"抒情":["离别","伤感"],"节日":["七夕节"]},"theme_conf":0.92},{"uid":"08a8ab7b-fb84-4a05-8b4e-177f2728bdbf","title":"和浙西李大夫晚下北固山喜径松成阴怅然怀古偶题临江亭幷浙东元相公所和依本韵","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["一辞温室树，几见武昌柳。","荀谢年何少，韦平望已久。","种松夹石道，纡组临沙阜。","目览帝王州，心存股肱守。","叶动惊彩翰，波澄见頳首。","晋宋齐梁都，千山万江口。","烟散隋宫出，涛来海门吼。","风俗太伯余，衣冠永嘉后。","江长天作限，山固壤无朽。","自古称佳丽，非贤谁奄有。","八元邦族盛，万石门风厚。","天柱揭东溟，文星照北斗。","高亭一骋望，举酒共为寿。","因赋咏怀诗，远寄同心友。","禁中晨夜直，江左东西偶。","将手握兵符，儒腰盘贵绶。","颁条风有自，立事言无苟。","农野闻让耕，军人不使酒。","用材当构厦，知道宁窥牖。","谁谓青云高，鹏飞终背负。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["江","山","楼"],"cats":{"抒情":["怀古"],"山水":["江河"],"天气":["星星"],"人生":["梦想"]},"theme_conf":0.383},{"uid":"53507dd1-ecdc-459b-ad7f-18951aa1751b","title":"大礼毕皇帝御丹凤门改元建中大赦","author":"李益","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["大明曈曈天地分，六龙负日升天门。","凤凰飞来衔帝箓，言我万代金皇孙。","灵鸡鼓舞承天赦，高翔百尺垂朱幡。","宸居穆清受天历，建中甲子合上元。","昊穹景命即已至，王事乃可酬乾坤。","升中告成答玄贶，泥金检玉昭鸿恩。","云亭之事略可记，七十二君宁独尊。","小臣欲上封禅表，久而未就归文园。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":["元宵"],"cats":{"抒情":["孤独"],"节日":["元宵节"]},"theme_conf":0.418},{"uid":"ac97d42b-8fef-42c9-829f-baafe89b4cdc","title":"利州南渡","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["澹然空水对斜晖，曲岛苍茫接翠微。","波上马嘶看櫂去，柳边人歇待船归。","数丛沙草群鸥散，万顷江田一鹭飞。","谁解乘舟寻范蠡，五湖烟水独忘机。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":["雄浑"],"mood":"恬淡","mood2":["孤寂"],"scene":["江","舟"],"cats":{"抒情":["孤独"]},"theme_conf":0.694},{"uid":"e2f6d3a1-da3e-4651-a066-b9cb1c339757","title":"赋得亚父碎玉斗","author":"裴次元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["雄谋竟不决，宝玉将何爱。","倏尔霜刃挥，飒然春冰碎。","飞光动旗帜，散响惊环珮。","霜浓绣帐前，星流锦筵内。","图王业已失，为虏言空悔。","独有青史中，英风冠千载。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["春","秋","冬"],"cats":{"抒情":["孤独"],"四季":["春天","秋天"],"人物":["父亲"]},"theme_conf":0.524},{"uid":"cfb724d3-b6ef-4c81-a5c7-ef90595445ad","title":"相和歌辞 陇西行","author":"耿[𣲗]","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["雪下阳关路，人稀陇戍头。","封狐犹未翦，边将岂无羞。","白草三冬色，黄云万里愁。","因思李都尉，毕竟不封侯。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["冬","雪"],"cats":{"抒情":["伤感"],"四季":["冬天"],"生活":["边塞"]},"theme_conf":0.737},{"uid":"01cc3e31-e2e4-4598-915f-36e8dbbe7c95","title":"琴曲歌辞 湘夫人","author":"郎士元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["娥眉对湘水，遥哭苍梧间。","万乘既已殁，孤舟谁忍还。","至今楚山上，犹有泪痕斑。","南有涔阳路，渺渺多新愁。","昔神降回时，风波江上秋。","彩云忽无处，碧水空安流。"],"theme":"闺情宫怨","theme2":["闲适隐逸","羁旅思乡"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂","悲怆"],"scene":["舟","秋","山","江"],"cats":{"抒情":["思乡","伤感","孤独","闺怨"],"四季":["秋天"],"天气":["写云"]},"theme_conf":0.392},{"uid":"1365c1c9-e864-4920-ba10-d3815a59f6b7","title":"春日思归","author":"李频","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["春情不断若连环，一夕思归鬓欲斑。","壮志未酬三尺劒，故乡空隔万重山。","音书断绝干戈后，亲友相逢梦寐间。","却羡浮云与飞鸟，因风吹去又吹还。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"人生":["励志","梦想"]},"theme_conf":0.718},{"uid":"015761cf-2c04-44fa-8974-aafe4fa19be3","title":"詶陈翃郎中冬至携柳郎窦郎归河中旧居见寄","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["三旬一休沐，清景满林庐。","南郭群儒从，东床两客居。","烧烟浮雪野，麦陇润冰渠。","班白皆持酒，蓬茅尽有书。","终期买寒渚，同此利蒲鱼。"],"theme":"寄赠酬答","theme2":["送别","羁旅思乡"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["冬"],"cats":{"抒情":["思乡"],"四季":["冬天"],"植物":["柳树"]},"theme_conf":0.92},{"uid":"27ff54ab-4861-43d8-b3c1-69113d2e4e10","title":"近试上张籍水部","author":"朱庆余","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["洞房昨夜停红烛，待晓堂前拜舅姑。","[妆]罢低声问夫壻，画眉深浅入时无。"],"theme":"闺情宫怨","theme2":["爱情相思"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["夜"],"cats":{"抒情":["闺怨"]},"theme_conf":0.407},{"uid":"2fa31522-6b7d-4c10-b9a4-ee278d17a714","title":"雪夜观象阙待漏","author":"张少博","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["残雪初睛后，鸣珂奉阙庭。","九门传晓漏，五夜候晨扃。","北斗横斜汉，东方落曙星。","烟氛初动色，簪佩未分形。","雪重犹垂白，山遥不辨青。","鸡人更唱处，偏入此时听。"],"theme":"闺情宫怨","theme2":[],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["夜","雪"],"cats":{"抒情":["闺怨"],"天气":["写雪","星星"]},"theme_conf":0.65},{"uid":"cpe122a2a80234ea","title":"绿头鸭・多丽","author":"晁端礼","dynasty":"宋","section":"宋词","form":"词","paragraphs":["晚云收，淡天一片琉璃。","烂银盘、来从海底，皓色千里澄辉。","莹无尘、素娥淡伫，静可数、丹桂参差。","玉露初零，金风未凛，一年无似此佳时。","露坐久，疏莹时度，乌鹊正南飞。","瑶台冷，栏干凭暖，玉下迟迟。","念佳人，音尘别后，对此应解相思。","最关情、漏声正永，暗断肠、花影偷移。","料得来宵，清光未减，阴晴天气又争知。","共凝恋、如今别后，还是隔年期。","人强健，清尊素影，长愿相随。"],"theme":"送别","theme2":["爱情相思","游仙梦幻"],"style":"清新","style2":["冲淡"],"mood":"相思","mood2":["恬淡"],"scene":["夜"],"cats":{"抒情":["爱情","思念"],"人物":["女子"]},"theme_conf":0.351},{"uid":"a746d1f0-a72c-44d2-8b1c-c5c990749257","title":"送灵澈上人","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["苍苍竹林寺，杳杳钟声晚。","荷笠带夕阳，青山独归远。"],"theme":"送别","theme2":["山水田园"],"style":"雄浑","style2":[],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"抒情":["孤独"]},"theme_conf":0.548},{"uid":"1877173b-b4bb-467b-93da-a390559efe41","title":"留花门","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["北门天骄子，饱肉气勇决。","高秋马肥健，挟矢射汉月。","自古以为患，诗人厌薄伐。","修德使其来，羁縻固不绝。","胡为倾国至，出入暗金阙。","中原有驱除，隐忍用此物。","公主歌黄鹄，君王指白日。","连云屯左辅，百里见积雪。","长戟鸟休飞，哀笳曙幽咽。","田家最恐惧，麦倒桑枝折。","沙苑临清渭，泉香草丰洁。","渡河不用船，千骑常撇烈。","胡尘逾太行，杂种抵京室。","花门既须留，原野转萧瑟。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"悲怆","mood2":[],"scene":["花"],"cats":{"抒情":["爱国"],"天气":["写雪"],"生活":["田野"]},"theme_conf":0.443},{"uid":"a9c061a4-c957-4d74-a0f3-86001d8b2a7f","title":"杂曲歌辞 少年行四首 二","author":"令狐楚","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["家本清河住五城，须凭弓箭得功名。","等闲飞鞚秋原上，独向寒云试射声。"],"theme":"羁旅思乡","theme2":["边塞征战","闲适隐逸"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["恬淡","慷慨"],"scene":["秋"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"人生":["青春"]},"theme_conf":0.387},{"uid":"0613f575-4f07-4326-8591-603fb3d1da45","title":"秦中感秋寄远上人","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["一丘常欲卧，三径苦无资。","北土非吾愿，东林怀我师。","黄金然桂尽，壮志逐年衰。","日夕凉风至，闻蝉但益悲。"],"theme":"寄赠酬答","theme2":["闲适隐逸"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["慷慨"],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"山水":["庐山"],"人生":["励志","梦想"]},"theme_conf":0.82},{"uid":"990fcce5-9eed-4401-b5b4-e72eb0b05d5f","title":"武陵春日","author":"王建","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["寻春何事却悲凉，春到他乡忆故乡。","秦女洞桃欹涧碧，楚王堤柳舞烟黄。","波涛入梦家山远，名利关身客路长。","不似冥心叩尘寂，玉编金轴有仙方。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":["冲淡","悲慨"],"mood":"相思","mood2":["悲怆","孤寂"],"scene":["春"],"cats":{"抒情":["思念","思乡","伤感"],"四季":["春天"],"植物":["桃花"]},"theme_conf":0.557},{"uid":"edf798b9-3594-4320-bcbd-dfd9f6ef22b6","title":"独孤中丞筵陪饯韦君赴升州","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["中司龙节贵，上客虎符新。","地控吴襟带，才高汉缙绅。","泛舟应度腊，入境便行春。","处处歌来暮，长江建业人。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["江"],"cats":{"抒情":["孤独"],"山水":["长江"]},"theme_conf":0.704},{"uid":"28880f73-8de2-43d1-8e5d-648dee798338","title":"对酒赠故人","author":"包佶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["扶起离披菊，霜轻喜重开。","醉中惊老去，笑里觉愁来。","月送人无尽，风吹浪不回。","感时将有寄，诗思涩难裁。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["沉郁","幽峭"],"mood":"欢愉","mood2":["愁怨"],"scene":["酒"],"cats":{"抒情":["友情","伤感"],"食物":["写酒"]},"theme_conf":0.94},{"uid":"cp0f9b3bff925f7f","title":"驻马听・寂寂瑶阶，春日阑珊景物乖。困人天色，不堪梳洗傍妆台。梨花","author":"刘庭信","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["寂寞玉容衰，海常零落胭脂败。","自裁划，今春更比前春煞。"],"theme":"闺情宫怨","theme2":[],"style":"冲淡","style2":["绮丽"],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独","闺怨"],"四季":["春天"],"动物":["写马"],"植物":["梨花"]},"theme_conf":1.0},{"uid":"18734c96-6ba5-4e4d-9150-fa5d31b646d9","title":"晚次新丰北野老家书事呈赠韩质明府","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["机鸣舂响日暾暾，鸡犬相和汉古村。","数派清泉黄菊盛，一林寒露紫棃繁。","衰翁正席矜新社，稚子齐襟读古论。","共说年来但无事，不知何者是君恩。"],"theme":"山水田园","theme2":["山水田园","羁旅思乡"],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.68},{"uid":"a353dcb1-12cc-4ca8-af1e-55d1d62445f8","title":"蜀相","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["丞相祠堂何处寻，锦官城外柏森森。","映堦碧草自春色，隔叶黄鹂空好音。","三顾频烦天下计，两朝开济老臣心。","出师未捷身先死，长使英雄泪满襟。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":["悲慨","豪放"],"mood":"悲怆","mood2":["愁怨","欢愉"],"scene":["春"],"cats":{"抒情":["伤感","怀古"],"四季":["春天"]},"theme_conf":0.736},{"uid":"cp71965685b8581b","title":"柳梢青","author":"蔡伸","dynasty":"宋","section":"宋词","form":"词","paragraphs":["数声𫛸鴂。","可怜又是，春归时节。","满院东风，海棠铺绣，梨花飘雪。","丁香露泣残枝，算未比、愁肠寸结。","自是休文，多情多感，不干风月。"],"theme":"闺情宫怨","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["悲怆"],"scene":["春","花","雪"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.65},{"uid":"d32a2610-09d7-49ad-8cdf-dd9c649144c7","title":"风雨","author":"李商隐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["凄凉宝剑篇，羁泊欲穷年。","黄叶仍风雨，青楼自管弦。","新知遭薄俗，旧好隔良缘。","心断新丰酒，销愁斗几千。"],"theme":"讽喻刺世","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["雨"],"cats":{"抒情":["思乡","伤感"],"天气":["写风","写雨"]},"theme_conf":0.506},{"uid":"cpab03d04d6ede46","title":"谢金莲诗酒红梨花・仙吕/点绛唇","author":"张寿卿","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["恰才个满目繁华，可又早落红飞下，春潇洒。","苔径轻踏，香衬凌波袜。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["花","酒","春"],"cats":{"抒情":["感恩"],"四季":["春天"],"植物":["梨花","荷花"],"食物":["写酒"]},"theme_conf":1.0},{"uid":"7456691c-636e-46d7-9093-edc778b0a7ea","title":"楚江怀古三首 一","author":"马戴","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["露气寒光集，微阳下楚丘。","猨啼洞庭树，人在木兰舟。","广泽生明月，苍山夹乱流。","云中君不降，竟夕自悲秋。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["江","月"],"cats":{"抒情":["伤感","怀古"],"天气":["月亮"]},"theme_conf":0.773},{"uid":"16dbc4d3-1930-4f57-8d30-c358ec7ba315","title":"闻吹杨叶者二首 一","author":"郎士元","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["妙吹杨叶动悲笳，胡马迎风起恨赊。","若是鴈门寒月夜，此时应卷尽惊沙。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["沉郁"],"mood":"悲怆","mood2":["愁怨"],"scene":["月","夜"],"cats":{"抒情":["伤感"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"b9402122-80d2-4755-9cf1-1a6bd5a9a6de","title":"七夕诗","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["祥光若可求，闺女夜登楼。","月露浩方下，河云凝不流。","铅华潜警曙，机杼暗传秋。","回想歛余睠，人天俱是愁。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["七夕"],"cats":{"抒情":["伤感"],"节日":["七夕节"]},"theme_conf":0.9},{"uid":"f3e3dab9-6df9-4bc1-b428-ace90e3a922c","title":"杂曲歌辞 结客少年场行","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["长安重游侠，洛阳富才雄。","玉劒浮云骑，金鞍明月弓。","鬬鸡过渭北，走马向关东。","孙宾遥见待，郭解暗相通。","不受千金爵，谁论万里功。","将军下天上，虏骑入云中。","烽火夜似月，兵气晓成虹。","横行徇知己，负羽远从戎。","龙旌昏朔雾，鸟阵卷寒风。","追奔瀚海咽，战罢阴山空。","归来谢天子，何如马上翁。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["绮丽","冲淡"],"mood":"孤寂","mood2":[],"scene":["月"],"cats":{"抒情":["友情"],"天气":["月亮"],"人生":["青春","战争"],"生活":["边塞"]},"theme_conf":0.711},{"uid":"b10851b9-e6cb-41eb-979a-c897ccaac1df","title":"梅里旅夕","author":"杨凌","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["沧洲东望路，旅櫂怆羁游。","枫浦蝉随岸，沙汀鸥转流。","露天星上月，水国夜生秋。","谁忍持相忆，南归一叶舟。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["秋","江"],"cats":{"抒情":["思念","思乡"],"四季":["秋天"],"植物":["梅花"]},"theme_conf":0.723},{"uid":"9e49be0f-69ae-44a6-a0d6-dcd636c6452f","title":"寄哥舒仆射","author":"韩翃","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["万里长城家，一生唯报国。","腰垂紫文绶，手控黄金勒。","高视黑头翁，遥吞白骑贼。","先麾牙门将，转鬬黄河北。","帐下亲兵皆少年，锦衣承日绣行缠。","辘轳宝劒初出鞘，宛转角弓初上弦。","步人抽箭大如笛，前把两矛后双戟。","左盘右射红尘中，鹘入鸦群有谁敌。","杀将破军白日余，回旃舞旆北风初。","郡公楯鼻好磨墨，走马为君飞羽书。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":["江"],"cats":{"抒情":["爱国"],"山水":["黄河"]},"theme_conf":0.672},{"uid":"3cda5a92-ffa2-4af0-9217-97ce36113705","title":"枫桥夜泊","author":"张继","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["月落乌啼霜满天，江枫渔父对愁眠。","姑苏城外寒山寺，夜半钟声到客船。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","夜"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"生活":["写桥"]},"theme_conf":0.468},{"uid":"6711c65c-3dc9-4a48-bfe6-d5e2dfe66dac","title":"送廖融处士南游","author":"翁宏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["病卧瘴云间，莓苔渍竹关。","孤吟牛渚月，老忆洞庭山。","壮志潜消尽，淳风竟未还。","今朝忽相遇，执手一开颜。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["慷慨","相思"],"scene":["江"],"cats":{"抒情":["思念","孤独"],"人生":["励志","梦想"]},"theme_conf":0.648},{"uid":"7ff83e4f-cf78-4123-8a0c-4e39cb867020","title":"惜花吟","author":"鲍氏君徽","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["枝上花，花下人，可怜颜色俱青春。","昨日看花花灼灼，今朝看花花欲落。","不如尽此花下欢，莫待春风总吹却。","莺歌蝶舞韶光长，红炉煑茗松花香。","妆成罢吟恣游后，独把芳枝归洞房。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":["孤寂"],"scene":["花"],"cats":{"抒情":["孤独","闺怨"],"人生":["青春"]},"theme_conf":1.0},{"uid":"3255bc39-f3ff-4c7b-9ac9-ccc21176db06","title":"送王相公赴范阳","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["翊圣衔恩重，频年按节行。","安危皆报国，文武不缘名。","受脤乃调鼎，为霖更洗兵。","幕开丞相阁，旗总贰师营。","料敌知无战，安边示有征。","代云横马首，燕雁拂笳声。","去镇关河静，归看日月明。","欲知瞻恋切，迟暮一书生。"],"theme":"送别","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"恬淡","mood2":["慷慨"],"scene":["鸟","雨","月"],"cats":{"抒情":["爱国"],"人生":["战争"]},"theme_conf":0.484},{"uid":"48568d08-d789-4eca-b9a8-5dcf09d6a516","title":"李鄠县丈人胡马行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["丈人骏马名胡骝，前年避胡过金牛。","回鞭却走见天子，朝饮汉水暮灵州。","自矜胡骝奇绝代，乘出千人万人爱。","一闻说尽急难材，转益愁向驽骀辈。","头上锐耳批秋竹，脚下高蹄削寒玉。","始知神龙别有种，不比俗马空多肉。","洛阳大道时再清，累日喜得俱东行。","凤臆龙鬐未易识，侧身注目长风生。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["绮丽","沉郁"],"mood":"愁怨","mood2":["孤寂","欢愉"],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"动物":["写马"]},"theme_conf":0.775},{"uid":"569ef0e1-887d-4d98-b869-9634f099c8e9","title":"还乡偶书  其二","author":"黄拱","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["少小离家老大回，乡音难改鬓毛衰。","儿童相见不相识，借问客从何处来。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["惆怅"],"scene":[],"cats":{"抒情":["思乡"],"人物":["儿童"]},"theme_conf":0.883},{"uid":"27db32d1-c747-4c6d-a937-4091287b6622","title":"灵门寺赠灵一上人","author":"朱放","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["所思劳旦夕，惆怅去湘东。","禅客知何在，春山几处同。","独行残雪里，相见暮云中。","请住东林寺，弥年事远公。"],"theme":"寄赠酬答","theme2":["送别"],"style":"沉郁","style2":[],"mood":"惆怅","mood2":["孤寂"],"scene":["雪","春","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"山水":["庐山"]},"theme_conf":0.88},{"uid":"1a75c701-e7ec-453d-97dd-ba70181e07b5","title":"送杜秀才归桂林","author":"许浑","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["桂州南去与谁同，处处山连水自通。","两岸晓霞千里草，半帆斜日一江风。","瘴雨欲来枫树黑，火云初起荔枝红。","愁君路远销年月，莫滞三湘五岭中。"],"theme":"送别","theme2":["山水田园"],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["月","山"],"cats":{"抒情":["伤感"],"山水":["江河"],"食物":["荔枝"]},"theme_conf":0.632},{"uid":"029ff16c-6562-4d06-95d9-765045b30c69","title":"新桃行","author":"张籍","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["桃生叶婆娑，枝叶四向多。","高未出墙颠，蒿苋相凌摩。","植之三年余，今年初试花。","秋来已成实，其阴良已嘉。","青蝉不来鸣，安得迅羽过。","常恶牵丝虫，蒙幂成网罗。","顾托戏儿童，勿折吾柔柯。","明年结其实，磊磊充汝家。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":["婉约"],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡"],"四季":["秋天"],"人物":["儿童"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"e73e2743-3752-4ba3-938a-fb59cd3965ee","title":"山石","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["山石荦确行径微，黄昏到寺蝙蝠飞。","升堂坐阶新雨足，芭蕉叶大支子肥。","僧言古壁佛画好，以火来照所见稀。","铺床拂席置羹饭，疎粝亦足饱我饥。","夜深静卧百虫绝，清月出岭光入扉。","天明独去无道路，出入高下穷烟霏。","山红涧碧纷烂漫，时见松枥皆十围。","当流赤足蹋涧石，水声激激风吹衣。","人生如此自可乐，岂必局束为人鞿。","嗟哉吾党二三子，安得至老不更归。"],"theme":"山水田园","theme2":["哲理悟道"],"style":"幽峭","style2":["清新"],"mood":"恬淡","mood2":["孤寂"],"scene":["山","夜"],"cats":{"抒情":["孤独"]},"theme_conf":0.465},{"uid":"5a27558b-ebcb-4073-a6fa-fe619881a570","title":"擢第后东归书怀献座主吕侍御","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔岁辞亲泪，今为恋主泣。","去住情难竝，别离景易戢。","夭矫大空鳞，曾为小泉蛰。","幽意独沈时，震雷忽相及。","神行既不宰，直致非所执。","至运本遗功，轻生各自立。","大君思此化，良佐自然集。","宝镜无私光，时文有新习。","慈亲诫志就，贱子归情急。","擢第谢灵台，牵衣出皇邑。","行襟海日曙，逸抱江风入。","蒹葭得波浪，芙蓉红岸湿。","云寺势动摇，山钟韵嘘吸。","旧游期再践，悬水得重挹。","松萝虽可居，青紫终当拾。"],"theme":"应制干谒","theme2":["山水田园","闲适隐逸"],"style":"婉约","style2":["冲淡"],"mood":"孤寂","mood2":["悲怆"],"scene":[],"cats":{"抒情":["离别","伤感","孤独"],"人物":["母亲"]},"theme_conf":0.85},{"uid":"91833140-4a32-4508-b50e-2d5e57c4940d","title":"感春四首 二","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["皇天平分成四时，春气漫诞最可悲。","杂花妆林草盖地，白日坐上倾天维。","蜂喧鸟咽留不得，红萼万片从风吹。","岂如秋霜虽惨冽，摧落老物谁惜之。","为此径须沽酒饮，自外天地弃不疑。","近怜李杜无检束，烂漫长醉多文辞。","屈原离骚二十五，不肯𫗦啜糟与醨。","惜哉此子巧言语，不到圣处宁非痴。","幸逢尧舜明四目，条理品汇皆得宜。","平明出门暮归舍，酩酊马上知为谁。"],"theme":"咏怀抒感","theme2":[],"style":"豪放","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":["春","花","酒","秋"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"],"节日":["端午节"]},"theme_conf":0.88},{"uid":"83057247-91ce-43d8-8aee-2eccfdcc8773","title":"横吹曲辞 折杨柳","author":"张九龄","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["纤纤折杨柳，持此寄情人。","一枝何足贵，怜是故园春。","迟景那能久，流芳不及新。","更愁征戍客，鬓老边城尘。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["春","园林"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.468},{"uid":"bcc75cc7-04a6-4599-81e8-48817a28a056","title":"灯影","author":"元稹","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["洛阳昼夜无车马，漫挂红纱满树头。","见说平时灯影里，玄宗潜伴太真游。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"惆怅","mood2":[],"scene":["夜","元宵"],"cats":{"抒情":["怀古"],"节日":["元宵节"]},"theme_conf":1.0},{"uid":"8de30193-fba7-4aef-9ff9-c3726a22104d","title":"泊秦淮","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["烟笼寒水月笼沙，夜泊秦淮近酒家。","商女不知亡国恨，隔江犹唱后庭花。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"悲慨","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["江南"],"cats":{"抒情":["怀古"]},"theme_conf":0.643},{"uid":"35638e63-ef59-411d-a832-af24221fd0fd","title":"题落叶","author":"司空曙","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["霜景催危叶，今朝半树空。","萧条故国异，零落旅人同。","飒岸浮寒水，依堦拥夜虫。","随风偏可羡，得到洛阳宫。"],"theme":"羁旅思乡","theme2":["咏物"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡","怀古"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":0.463},{"uid":"cp68f66c294d5089","title":"琵琶仙・自度曲","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["双桨来时，有人似、旧曲桃根桃叶。","歌扇轻约飞花，蛾眉正奇绝。","春渐远、汀洲自绿，更添了、几声啼。","十里扬州，三生杜牧，前事休说。","又还是、宫烛分烟，奈愁里、匆匆换时节。","都把一襟芳思，与空阶榆荚。","千万缕、藏鸦细柳，为玉尊、起舞回雪。","想见西出阳关，故人初别。"],"theme":"送别","theme2":["题画咏艺"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春","江","花","雪"],"cats":{"抒情":["友情","伤感"],"四季":["春天"]},"theme_conf":0.378},{"uid":"494db3da-3155-4b47-8a6a-82691a2f0ed4","title":"奉和七夕宴悬圃应制二首 一","author":"许敬宗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["牛闺临浅汉，鸾驷涉秋河。","两怀萦别绪，一宿庆停梭。","星模铅里靥，月写黛中蛾。","奈许今宵度，长婴离恨多。"],"theme":"应制干谒","theme2":["节令风俗"],"style":"沉郁","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["七夕"],"cats":{"抒情":["离别"],"节日":["七夕节"]},"theme_conf":0.98},{"uid":"0e42b61d-d0b4-4876-bfbd-269008daa0f8","title":"北游还酬孟云卿","author":"张彪","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["忽忽忘前事，志愿能相乖。","衣马久羸弊，谁信文与才。","善道居贫贱，洁服蒙尘埃。","行行无定心，𡒄坎难归来。","慈母忧疾疹，至家念栖哀。","与君宿姻亲，深见中外怀。","俟余惜时节，伥望临高台。"],"theme":"寄赠酬答","theme2":["亲情"],"style":"婉约","style2":[],"mood":"悲怆","mood2":["愁怨"],"scene":[],"cats":{"抒情":["感恩"],"人物":["母亲"]},"theme_conf":0.84},{"uid":"cp1263481f8f5d84","title":"江神子・江城子","author":"苏轼","dynasty":"宋","section":"宋词","form":"词","paragraphs":["十年生死两茫茫。","不思量。","自难忘。","千里孤坟，无处话凄凉。","纵使相逢应不识，尘满面，鬓如霜。","夜来幽梦忽还乡。","小轩窗。","正梳妆。","相顾无言，惟有泪千行。","料得年年断肠处，明月夜，短松冈。"],"theme":"悼亡挽歌","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["月","江","夜"],"cats":{"抒情":["伤感","悼亡"],"天气":["月亮"]},"theme_conf":0.99},{"uid":"1b6f2389-2d09-4d51-982a-e7efb35113c5","title":"相和歌辞 长信怨 二","author":"王昌龄","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["奉帚平明金殿开，暂将团扇共裴回。","玉颜不及寒鵶色，犹带昭阳日影来。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["闺怨"]},"theme_conf":1.0},{"uid":"668bda10-2fcd-45a3-9795-a8393e22ae00","title":"和李舍人直中书对月见寄","author":"李端","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["名卿步月正淹留，上客裁诗怨别游。","素魄近成班女扇，清光远似庾公楼。","婵娟更称凭高望，皎洁能传自古愁。","盈手入怀皆不见，阳春曲丽转难酬。"],"theme":"寄赠酬答","theme2":[],"style":"冲淡","style2":[],"mood":"愁怨","mood2":[],"scene":["月"],"cats":{"抒情":["伤感"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.97},{"uid":"f613e665-0ed5-449e-9f4f-e094a102f993","title":"九曲词三首 二","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["万骑争歌杨柳春，千塲对舞绣骐𬴊。","到处尽逢欢洽事，相看总是太平人。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"山水":["黄河"]},"theme_conf":0.65},{"uid":"06bb6ddd-5f47-42f0-a020-b7671ad56bdf","title":"相和歌辞 短歌行六首 四","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["何处春风吹晓幕？江南绿水通朱阁。","美人二八面如花，泣向东风畏花落。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"悲怆","mood2":[],"scene":["春","江南"],"cats":{"抒情":["思乡"],"四季":["春天"],"天气":["写风"],"人物":["女子"]},"theme_conf":0.65},{"uid":"cp73f107efe4e3f6","title":"谢池春","author":"李之仪","dynasty":"宋","section":"宋词","form":"词","paragraphs":["残寒销尽，疏雨过、清明后。","花径敛馀红，风沼萦新皱。","乳燕穿庭户，飞絮沾襟袖。","正佳时，仍晚昼。","著人滋味，真个浓如酒。","频移带眼，空只恁、厌厌瘦。","不见又思量，见了还依旧。","为问频相见，何似长相守。","天不老，人未偶。","且将此恨，分付庭前柳。"],"theme":"爱情相思","theme2":[],"style":"沉郁","style2":["清新","幽峭"],"mood":"孤寂","mood2":["相思","愁怨"],"scene":["园林","春","清明"],"cats":{"抒情":["思念","感恩"],"四季":["春天"],"节日":["清明节"]},"theme_conf":0.92},{"uid":"cpe9c7ec8184a6ba","title":"蝶恋花","author":"晏几道","dynasty":"宋","section":"宋词","form":"词","paragraphs":["梦入江南烟水路。","行尽江南，不与离人遇。","睡里消魂无说处。","觉来惆怅消魂误。","欲尽此情书尺素。","浮雁沈鱼，终了无凭据。","却倚缓弦歌别绪。","断肠移破秦筝柱。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":["愁怨"],"scene":["江南","花","江"],"cats":{"抒情":["离别","伤感"]},"theme_conf":1.0},{"uid":"83de3747-2242-4ae3-be3e-56a7b040aae2","title":"宋中遇林卢杨十七山人因而有别","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔余涉漳水，驱车行邺西。","遥见林虑山，苍苍戛天倪。","邂逅逢尔曹，说君彼岩栖。","萝径垂野蔓，石房倚云梯。","秋韭何青青，药苗数百畦。","栗林隘谷口，栝树森廻谿。","耕耘有山田，纺绩有山妻。","人生苟如此，何必组与珪。","谁谓远相访，曩情殊不迷。","簷前举醇醪，灶下烹双鸡。","朔风忽振荡，昨夜寒螀啼。","游子益思归，罢琴伤解携。","出门尽原野，白日黯已低。","始惊道路难，终念言笑暌。","因声谢岑壑，岁暮一攀跻。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["山"],"cats":{"抒情":["离别"],"天气":["写风"]},"theme_conf":0.365},{"uid":"7e29d72b-7386-48c6-af3c-9dafd02f0665","title":"木兰歌","author":"韦元甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["木兰抱杼嗟，借问复为谁。","欲闻所戚戚，感激彊其颜。","老父隶兵籍，气力日衰耗。","岂足万里行，有子复尚少。","胡沙没马足，朔风裂人肤。","老父旧羸病，何以彊自扶。","木兰代父去，秣马备戎行。","易却纨绮裳，洗却铅粉妆。","驰马赴军幕，慷慨携干将。","朝屯雪山下，暮宿青海傍。","夜袭燕支虏，更携于阗羌。","将军得胜归，士卒还故乡。","父母见木兰，喜极成悲伤。","木兰能承父母颜，却卸巾鞲理丝簧。","昔为烈士雄，今为娇子容。","亲戚持酒贺父母，始知生女与男同。","门前旧军都，十年共崎岖。","本结弟兄交，死战誓不渝。","今者见木兰，言声虽是颜貌殊。","惊愕不敢前，叹息徒嘻吁。","世有臣子心，能如木兰节。","忠孝两不渝，千古之名焉可灭。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["豪放","悲慨"],"mood":"悲怆","mood2":["慷慨"],"scene":["冬","夜","雪"],"cats":{"抒情":["思乡","伤感"],"四季":["冬天"],"天气":["写风"],"人物":["父亲"],"人生":["战争"]},"theme_conf":0.668},{"uid":"cp38c9788dedb47a","title":"谢金莲诗酒红梨花・油葫芦","author":"张寿卿","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["秀才每从来我羡他，提起来偏喜恰，攻书学剑是生涯。","秀才每受辛苦下载寒窗下，久后他显才能一举登科甲。","秀才每习礼义，学问答。","哎，你一个小梅香今后休奸诈，只说那秀才每不当家。","(梅香云)秀才每几时能勾发达？(正旦唱)。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["豪放","旷达"],"mood":"欢愉","mood2":["孤寂"],"scene":["花","酒"],"cats":{"抒情":["感恩"],"人生":["读书"],"植物":["梨花","荷花"],"食物":["写酒"]},"theme_conf":1.0},{"uid":"c92216ac-114d-4bda-9c55-89688840f5b0","title":"薄命篇","author":"权德舆","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["昔住邯郸年尚少，只是娇羞弄花鸟。","青楼碧纱大道边，绿杨日暮风褭褭。","婵娟玉貌二八余，自怜颜色花不如。","丽质全胜秦氏女，藁砧宁用专城居。","岁去年来年渐长，青春红粉全堪赏。","玉楼珠箔但闲居，南陌东城讵来往。","韶光日日看渐迟，[摽]梅既落行有时。","宁知燕赵娉婷子，翻嫁幽幷游侠儿。","年年结束青丝骑，出门一去何时至。","秋月空悬翡翠帘，春帏嬾卧鸳鸯被。","沙塞经时不寄书，深闺愁独意何如。","花前拭泪情无限，月下调琴恨有余。","离别苦多相见少，洞房愁梦何由晓。","闲看双燕泪霏霏，静对空床魂悄悄。","镜里红颜不自禁，陌头香骑动春心。","为问佳期早晚是，人人总解有黄金。"],"theme":"闺情宫怨","theme2":["送别","闺情宫怨","爱情相思"],"style":"绮丽","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["花","秋","鸟","春","塞外","中秋"],"cats":{"抒情":["爱情","离别","伤感","闺怨"],"四季":["春天","秋天"],"天气":["月亮"],"人生":["青春"],"节日":["中秋节"]},"theme_conf":0.96},{"uid":"d05f4524-071a-4914-97f3-bed8e9683a48","title":"相和歌辞 大堤曲","author":"张柬之","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["南国多佳人，莫若大堤女。","玉床翠羽帐，宝袜莲花炬。","魂处自目成，色授开心许。","迢迢不可见，日暮空愁予。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":["沉郁","豪放"],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["伤感"],"人物":["女子"]},"theme_conf":0.82},{"uid":"94fe7344-b244-4341-8887-e717c373c9a2","title":"杂曲歌辞 少年行三首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["莫笑田家老瓦盆，自从盛酒长儿孙。","倾银注瓦惊人眼，共醉终同卧竹根。"],"theme":"山水田园","theme2":["羁旅思乡","闲适隐逸"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["酒"],"cats":{"抒情":["思乡"],"人生":["青春"],"生活":["田野"]},"theme_conf":0.394},{"uid":"be5ce2f9-2aaf-40b1-8f05-1a5817447ed3","title":"横吹曲辞 后出塞五首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["朝进东门营，暮上河阳桥。","落日照大旗，马鸣风萧萧。","平沙列万幕，部伍各见招。","中天悬明月，令严夜寂寥。","悲笳数声动，壮士惨不骄。","借问大将谁，恐是霍嫖姚。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["孤寂","慷慨"],"scene":["塞外","月"],"cats":{"抒情":["伤感"],"天气":["月亮"],"生活":["边塞","写桥"]},"theme_conf":1.0},{"uid":"82166154-7317-4617-a50c-a9a5a2896da3","title":"杂曲歌辞 伤歌行","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["黄门诏下促收捕，京兆君系御史府。","出门无复部曲随，亲戚相逢不容语。","辞成谪尉南海州，受命不得须臾留。","身著青衫骑恶马，东门之东无送者。","邮夫防吏急喧驱，往往惊堕马蹏下。","长安里中荒大宅，朱门已除十二戟。","高堂舞榭锁管弦，美人遥望西南天。"],"theme":"送别","theme2":["悼亡挽歌","讽喻刺世"],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"抒情":["伤感","悼亡"],"人物":["女子"]},"theme_conf":0.381},{"uid":"e8711802-5f93-4354-8422-a634ba2213e4","title":"代村中老人答","author":"李端","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["京洛风尘后，村乡烟火稀。","少年曾失所，衰暮欲何依。","夜静临江哭，天寒踏雪归。","时清应不见，言罢泪盈衣。"],"theme":"山水田园","theme2":["送别"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["恬淡","愁怨"],"scene":["雪","夜","江"],"cats":{"抒情":["伤感"],"生活":["乡村"]},"theme_conf":0.406},{"uid":"6a1115e5-1ec9-41ec-aab8-d61af62debf2","title":"听芦管","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["幽咽新芦管，凄凉古竹枝。","似临猨峡唱，疑在雁门吹。","调为高多切，声缘小乍迟。","麤豪嫌觱篥，细妙胜参差。","云水巴南客，风沙陇上儿。","屈原收泪夜，苏武断肠时。","仰秣胡驹听，惊栖越鸟知。","何言胡越异，闻此一同悲。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["鸟","江南","端午","夜"],"cats":{"抒情":["思乡","伤感"],"节日":["端午节"]},"theme_conf":0.504},{"uid":"013bf750-098b-4b37-93d9-82c2efea2634","title":"杂曲歌辞 行路难","author":"韦应物","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["荆山之白玉兮。","良工雕琢双环连，月蚀中央镜心穿。","故人赠妾初相结，恩在环中寻不绝。","人情厚薄苦须臾，昔似连环今似玦。","连环可碎不可离，如何物在人自移。","上客勿遽欢，听妾歌路难。","傍人见环环可怜，不知中有长恨端。"],"theme":"送别","theme2":["闺情宫怨"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["欢愉"],"scene":["月"],"cats":{"抒情":["友情","闺怨"]},"theme_conf":0.457},{"uid":"5aee80a3-db54-4787-9e2a-491e108b8f1d","title":"发秦州","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["我衰更嬾拙，生事不自谋。","无食问乐土，无衣思南州。","汉源十月交，天气凉如秋。","草木未黄落，况闻山水幽。","栗亭名更佳，下有良田畴。","充肠多薯蓣，崖蜜亦易求。","密竹复冬笋，清池可方舟。","虽伤旅寓远，庶遂平生游。","此邦俯要冲，实恐人事稠。","应接非本性，登临未销忧。","谿谷无异石，塞田始微收。","岂复慰老夫，惘然难久留。","日色隐孤戍，乌啼满城头。","中宵驱车去，饮马寒塘流。","磊落星月高，苍茫云雾浮。","大哉乾坤内，吾道长悠悠。"],"theme":"山水田园","theme2":["边塞征战"],"style":"雄浑","style2":["沉郁"],"mood":"孤寂","mood2":["惆怅"],"scene":["夜","冬","塞外","月","秋","舟"],"cats":{"抒情":["孤独"],"四季":["秋天","冬天"],"生活":["边塞"]},"theme_conf":0.407},{"uid":"39f705dc-3756-4ec4-bbc3-ea2e48e3e010","title":"云山","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["京洛云山外，音书静不来。","神交作赋客，力尽望乡台。","衰疾江边卧，亲朋日暮回。","白鸥元水宿，何事有余哀。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["恬淡"],"scene":["山"],"cats":{"抒情":["思乡"],"天气":["写云"]},"theme_conf":0.55},{"uid":"c11ca31f-2354-4bf8-8be4-101c5e81c601","title":"登润州城","author":"江为","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["天末江城晚，登临客望迷。","春潮平岛屿，残雨隔虹霓。","鸟与孤帆远，烟和独树低。","乡山何处是，目断广陵西。"],"theme":"咏史怀古","theme2":["羁旅思乡"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["江","春","雨","舟"],"cats":{"抒情":["思乡","孤独","怀古"],"四季":["春天"],"天气":["彩虹"]},"theme_conf":0.399},{"uid":"2d99b5dd-863a-4b50-ad3d-fe5c9ea8a8d9","title":"送元处士游天台","author":"朱庆余","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["青冥路口绝人行，独与僧期上赤城。","树列烟岚春更好，溪藏冰雪夜偏明。","空山雉雊禾苗短，野馆风来竹气清。","若过石桥看瀑布，不妨高处便题名。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["夜","冬","楼","雪","春","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"山水":["瀑布"],"天气":["写雪"],"生活":["写桥"]},"theme_conf":0.458},{"uid":"f4301f96-e872-4eae-aa51-0d12328059d1","title":"李端公","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["故关衰草遍，离别自堪悲。","路出寒云外，人归暮雪时。","少孤为客早，多难识君迟。","掩泪空相向，风尘何处期。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["冬"],"cats":{"抒情":["离别","伤感","孤独"]},"theme_conf":0.778},{"uid":"c6491c82-16cc-417f-bc8d-4cf938aa4ed4","title":"别耿都尉","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["四十能学劒，时人无此心。","如何耿夫子，感激投知音。","翩翩白马来，二月青草深。","别易小千里，兴酣倾百金。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["月"],"cats":{"抒情":["友情","离别"]},"theme_conf":1.0},{"uid":"2c6094fa-74b2-4226-b42d-d06cc51fb646","title":"怀鲁","author":"程弥纶","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["曲阜国，尼丘山。","周公邈难问，夫子犹启关。","履风雩兮若见，游夏兴兮鲁颜。","天孙天孙，何为今兮学且难，负星明而东游闲闲。"],"theme":"咏史怀古","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["夏","山"],"cats":{"抒情":["怀古"],"四季":["夏天"]},"theme_conf":0.9},{"uid":"4e9ac5c4-8f12-40f3-acce-39567d0bdfc5","title":"县斋有怀","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["少小尚奇伟，平生足悲咤。","犹嫌子夏儒，肯学樊迟稼。","事业窥臯稷，文章蔑曹谢。","濯缨起江湖，缀佩杂兰麝。","悠悠指长道，去去策高驾。","谁为倾国媒，自许连城价。","初随计吏贡，屡入泽宫射。","虽免十上劳，何能一战霸。","人情忌殊异，世路多权诈。","蹉跎颜遂低，摧折气愈下。","冶长信非罪，侯生或遭骂。","怀书出皇都，衔泪渡清灞。","身将老寂寞，志欲死闲暇。","朝食不盈肠，冬衣才掩髂。","军书既频召，戎马乃连跨。","大梁从相公，彭城赴仆射。","弓箭围狐兔，丝竹罗酒{炙火=肉}。","两府变荒凉，三年就休假。","求官去东洛，犯雪过西华。","尘埃紫陌春，风雨灵台夜。","名声荷朋友，援引乏姻娅。","虽陪彤庭臣，讵纵青冥靶。","寒空耸危阙，晓色曜修架。","捐躯辰在丁，铩翮时方蜡。","投荒诚职分，领邑幸宽赦。","湖波翻日车，岭石坼天罅。","毒雾恒熏昼，炎风每烧夏。","雷威固已加，飓势仍相借。","气象杳难测，声音吁可怕。","夷言听未惯，越俗循犹乍。","指摘两憎嫌，睢盱互猜讶。","祗缘恩未报，岂谓生足藉。","嗣皇新继明，率土日流化。","惟思涤瑕垢，长去事桑柘。","𣃁嵩开云扃，压颍抗风榭。","禾麦种满地，梨枣栽绕舍。","儿童稍长成，雀鼠得驱吓。","官租日输纳，村酒时邀迓。","闲爱老农愚，归弄小女姹。","如今便可尔，何用毕婚嫁。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["幽峭","沉郁"],"mood":"悲怆","mood2":["孤寂","慷慨"],"scene":["夏","冬","江"],"cats":{"抒情":["伤感","孤独","爱国"],"四季":["夏天","冬天"],"人物":["儿童"]},"theme_conf":0.494},{"uid":"e3ea1c9d-0de9-4738-97fb-034154b7b740","title":"题黄花驿","author":"薛逢","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["孤戍迢迢蜀路长，鸟鸣山馆客思乡。","更看绝顶烟霞外，数树岩花照夕阳。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["花","山"],"cats":{"抒情":["思乡","孤独"],"植物":["菊花"]},"theme_conf":0.57},{"uid":"19867a30-1b67-4123-b367-44565bab6516","title":"集灵台二首 一","author":"张祜","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["日光斜照集灵台，红树花迎晓露开。","昨夜上皇新授箓，太真含笑入帘来。"],"theme":"讽喻刺世","theme2":["咏史怀古"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["楼","花"],"cats":{"抒情":["怀古"]},"theme_conf":0.613},{"uid":"970e1233-9d3b-4ee6-92c1-1491ffc37bfa","title":"相和歌辞 凤凰曲","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["嬴女吹玉箫，吟弄天上春。","青鸾不独去，更有携手人。","影灭彩云断，遗声落西秦。"],"theme":"游仙梦幻","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独"],"四季":["春天"],"天气":["写云"]},"theme_conf":0.88},{"uid":"5641758a-d34f-4d86-8631-5f0b17869fc3","title":"相和歌辞 江南曲八首 四","author":"刘希夷","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["皓如楚江月，霭若吴岫云。","波中自皎镜，山上亦氛氲。","明月留照妾，轻云持赠君。","山川各离散，光气乃殊分。","天涯一为别，江北自相闻。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江南","江","月"],"cats":{"抒情":["离别"],"山水":["江河"],"天气":["月亮"]},"theme_conf":0.94},{"uid":"cp5c5c2d9dfa28fd","title":"谢金莲诗酒红梨花・后庭花","author":"张寿卿","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["俺将俏书生去问他，又怕这劣梅香瞧见咱。","俺这里有意传心事，他那里无言指落花。","争奈我是女孩儿家，做这一场活靶，可不的被傍人活笑杀。"],"theme":"闲适隐逸","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["花","酒"],"cats":{"抒情":["感恩"],"植物":["梨花","荷花"],"食物":["写酒"]},"theme_conf":0.65},{"uid":"362e9ec3-e452-4f59-b5f4-10757da34b28","title":"杂曲歌辞 妾薄命","author":"刘元淑","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["自从离别守空闺，遥闻征战起云梯。","夜夜愁君辽海外，年年弃妾渭桥西。","阳春白日照空暖，紫燕衔花向庭满。","彩鸾琴里怨声多，飞鹊镜前妆梳断。","谁家夫壻不从征，应是渔阳别有情。","莫道红颜燕地少，家家还似洛阳城。","且逐新人殊未归，还令秋至夜霜飞。","北斗星前横度鴈，南楼月下捣寒衣。","夜深闻鴈肠欲绝，独坐缝衣灯又灭。","暗啼罗帐空自怜，梦度阳关向谁说。","每怜容貌宛如神，如何薄命不胜人。","愿君朝夕燕山至，好作明年杨柳春。"],"theme":"闺情宫怨","theme2":["送别","边塞征战"],"style":"清新","style2":["绮丽"],"mood":"孤寂","mood2":["愁怨"],"scene":["夜","秋","鸟","春"],"cats":{"抒情":["离别","伤感","孤独","闺怨"],"四季":["春天","秋天"],"天气":["星星"],"人生":["战争"],"生活":["边塞","写桥"]},"theme_conf":0.354},{"uid":"c3a14148-94d9-47f2-afff-9f9ef345b018","title":"寄袁州李嘉祐员外","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["谁谓江山阻，心亲梦想偏。","容辉常在目，离别任经年。","郡国通流水，云霞共远天。","行春莺几啭，迟客月频圆。","雁有归乡羽，人无访戴船。","愿徴黄霸入，相见玉堦前。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"雄浑","style2":[],"mood":"惆怅","mood2":[],"scene":["春","鸟"],"cats":{"抒情":["离别","思乡"],"四季":["春天"],"天气":["写云"]},"theme_conf":0.96},{"uid":"832147f1-7dcc-4626-b3fc-0d197f29ad77","title":"杂曲歌辞 行路难","author":"翁绶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["行路艰难不复歌，故人荣达我蹉跎。","双轮晚上铜梁雪，一叶春浮瘴海波。","自古要津皆若此，方今失路欲如何？","君看西汉翟丞相，凤沼朝辞暮雀罗。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["雪","春"],"cats":{"抒情":["友情"],"四季":["春天"]},"theme_conf":1.0},{"uid":"c95d62a4-e333-4701-b69f-2f57ce986cd6","title":"系乐府十二首 谢大龟","author":"元结","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["客来自江汉，云得双大龟。","且言龟甚灵，问我君何疑。","自昔保方正，顾尝无妄私。","顺和固鄙分，全守真常规。","行之恐不及，此外将何为。","惠恩如可谢，占问敢终辞。"],"theme":"羁旅思乡","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["江"],"cats":{"抒情":["思乡","感恩"]},"theme_conf":0.65},{"uid":"22362105-f266-4297-b3e9-d54b40adf8f0","title":"上阳红叶","author":"徐凝","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["洛下三分红叶秋，二分翻作上阳愁。","千声万片御沟上，一片出宫何处流。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["花","秋"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":1.0},{"uid":"7a3afe60-f683-4e4f-a11d-ecfd38c7dc98","title":"送客一归襄阳二归浔阳","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["南驱匹马会心期，东望扁舟惬梦思。","熨斗山前春色早，香炉峰顶暮烟时。","空林欲访庞居士，古寺应怀远法师。","两地由来堪取兴，三贤他日幸留诗。"],"theme":"羁旅思乡","theme2":["送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["舟","山"],"cats":{"抒情":["思乡"],"山水":["庐山"]},"theme_conf":0.413},{"uid":"91f95b30-c42f-470a-9df8-dd6284fca474","title":"隋宫","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["乘兴南游不戒严，九重谁省谏书函。","春风举国裁宫锦，半作障泥半作帆。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["春","舟"],"cats":{"抒情":["怀古"],"四季":["春天"]},"theme_conf":0.722},{"uid":"124207a8-53d1-49be-aacd-ddcd530fab38","title":"寒食行","author":"王建","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["寒食家家出古城，老人看屋少年行。","丘垅年年无旧道，车徒散行入衰草。","牧儿驱牛下冢头，畏有家人来洒扫。","远人无坟水头祭，还引妇姑望乡拜。","三日无火烧纸钱，纸钱那得到黄泉。","但看垅上无新土，此中白骨应无主。"],"theme":"节令风俗","theme2":["羁旅思乡"],"style":"幽峭","style2":["悲慨"],"mood":"孤寂","mood2":["悲怆"],"scene":["清明"],"cats":{"抒情":["思乡"],"节日":["寒食节","清明节"]},"theme_conf":0.86},{"uid":"bd157d95-20f8-4e64-b2df-bda96308e128","title":"吊灵均","author":"王鲁复","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["万古汨罗深，骚人道不沈。","明明唐日月，应见楚臣心。"],"theme":"咏史怀古","theme2":[],"style":"雄浑","style2":[],"mood":"惆怅","mood2":[],"scene":["端午","月"],"cats":{"抒情":["怀古"],"节日":["端午节"]},"theme_conf":1.0},{"uid":"110ea489-e0f3-40c3-8bd1-39936729a6cf","title":"冬夜题旅馆","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["退飞忆林薮，乐业羡黎庶。","四海尽穷途，一枝无宿处。","严冬北风急，中夜哀鸿去。","孤烛思何深，寒窗坐难曙。","劳歌待明发，惆怅盈百虑。"],"theme":"羁旅思乡","theme2":["咏物"],"style":"豪放","style2":["悲慨"],"mood":"相思","mood2":["孤寂","惆怅"],"scene":["冬","夜"],"cats":{"抒情":["思念","思乡","孤独"],"四季":["冬天"],"人生":["读书"]},"theme_conf":0.624},{"uid":"5679526b-d077-4f1f-a67e-fc430e4643a9","title":"柳州二月榕叶落尽偶题","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["宦情羁思共凄凄，春半如秋意转迷。","山城过雨百花尽，榕叶满庭莺乱啼。"],"theme":"咏物","theme2":["羁旅思乡","山水田园"],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"天气":["月亮"],"植物":["柳树","叶子"]},"theme_conf":0.421},{"uid":"5a194d8f-5981-4036-9da1-dc6e3cedf4f9","title":"杂曲歌辞 少年行四首 一","author":"令狐楚","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["少小边州惯放狂，骣骑蕃马射黄羊。","如今年事无筋力，犹倚营门数鴈行。"],"theme":"羁旅思乡","theme2":[],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"人生":["青春"]},"theme_conf":0.65},{"uid":"065b8cb6-8cbd-461e-8ed8-62ee4ba449e8","title":"杂曲歌辞 桃花行 三","author":"李峤","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["源水丛花无数开，丹跗红蕚间青梅。","从今结子三千岁，预喜仙游复摘来。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["花"],"cats":{"抒情":["思乡"],"植物":["桃花"]},"theme_conf":0.65},{"uid":"11e193d2-f374-43c1-b475-94751f6569b8","title":"田园雨后赠邻人","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["安排常任性，偃卧晚开户。","樵客荷蓑归，向来春山雨。","残云虹未落，返景霞初吐。","时鸟鸣村墟，新泉遶林圃。","尧年尚恬泊，邻里成太古。","室迩人遂遥，相思怨芳杜。"],"theme":"山水田园","theme2":["送别"],"style":"清新","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["雨","园林"],"cats":{"抒情":["思念"],"天气":["写雨"],"生活":["田野"]},"theme_conf":0.447},{"uid":"c2c83ee2-940f-4ae3-9ab3-4f509d2991f3","title":"奉济驿重送严公四韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["远送从此别，青山空复情。","几时桮重把，昨夜月同行。","列郡讴歌惜，三朝出入荣。","江村独归处，寂寞养残生。"],"theme":"送别","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["夜","月","山","江"],"cats":{"抒情":["孤独"]},"theme_conf":0.696},{"uid":"5a5dcd73-11dd-46df-9eb3-e345148ad909","title":"故燕国相公挽歌二首 二","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["共美持衡日，皆言折槛时。","蜀侯供庙略，汉主缺台司。","车马行仍止，笳箫咽又悲。","今年杜陵陌，殄瘁百花迟。"],"theme":"悼亡挽歌","theme2":[],"style":"清新","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["鸟"],"cats":{"抒情":["伤感","悼亡"],"动物":["写鸟"]},"theme_conf":0.98},{"uid":"9997e88a-f75c-47ec-a336-359bb426fcf4","title":"横吹曲辞 洛阳道","author":"郑渥","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["客亭门外路东西，多少喧腾事不齐。","杨柳惹鞭公子醉，纻麻掩泪鲁人迷。","通宵尘土飞山月，是处经营夹御堤。","顷刻知音几存殁，半回依约认轮蹄。"],"theme":"山水田园","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["月","酒","夜","山"],"cats":{"抒情":["友情","伤感"]},"theme_conf":0.65},{"uid":"ad25550b-b0b6-49cd-981a-88d90471b624","title":"寄彭州高三十五使君适虢州岑二十七长史参三十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["故人何寂寞，今我独凄凉。","老去才难尽，秋来兴甚长。","物情尤可见，辞客未能忘。","海内知名士，云端各异方。","高岑殊缓步，沈鲍得同行。","意惬关飞动，篇终接混茫。","举天悲富骆，近代惜卢王。","似尔官仍贵，前贤命可伤。","诸侯非弃掷，半刺已翱翔。","诗好几时见，书成无信将。","男儿行处是，客子鬬身强。","羁旅推贤圣，沈绵抵咎殃。","三年犹疟疾，一鬼不销亡。","隔日搜脂髓，增寒抱雪霜。","徒然潜隙地，有腼屡鲜妆。","何太龙钟极，于今出处妨。","无钱居帝里，尽室在边疆。","刘表虽遗恨，庞公至死藏。","心微傍鱼鸟，肉瘦怯豺狼。","陇草萧萧白，洮云片片黄。","彭门劒阁外，虢略鼎湖旁。","荆玉簪头冷，巴笺染翰光。","乌麻蒸续晒，丹橘露应尝。","岂异神仙宅，俱兼山水乡。","竹斋烧药灶，花屿读书床。","更得清新否，遥知对属忙。","旧宫宁改汉，淳俗本归唐。","济世宜公等，安贫亦士常。","蚩尤终戮辱，胡羯漫猖狂。","会待祅氛静，论文暂裹粮。"],"theme":"羁旅思乡","theme2":["送别","山水田园"],"style":"幽峭","style2":[],"mood":"恬淡","mood2":["孤寂","悲怆"],"scene":["秋","雪"],"cats":{"抒情":["友情","思乡","伤感","孤独"],"四季":["秋天"],"人生":["读书"]},"theme_conf":0.373},{"uid":"57203d7f-380c-4052-b21b-d1ea79fbe231","title":"子夜吴歌 春歌","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["秦地罗敷女，采桑绿水边。","素手青条上，红妆白日鲜。","蚕饥妾欲去，五马莫留连。"],"theme":"闺情宫怨","theme2":["民生疾苦"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"]},"theme_conf":0.471},{"uid":"d2cb0132-c27d-4037-abb6-c76f576b866b","title":"送顾八分文学适洪吉州","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["中郎石经后，八分盖顦顇。","愿侯运𬬻锤，笔力破余地。","昔在开元中，韩蔡同赑屭。","玄宗妙其书，是以数子至。","御札早流传，揄扬非造次。","三人竝入直，恩泽各不二。","愿于韩蔡内，辨眼工小字。","分日示诸王，钩深法更秘。","文学与我游，萧疎外声利。","追随二十载，浩荡长安醉。","高歌卿相宅，文翰飞省寺。","视我扬马间，白首不相弃。","骅骝入穷巷，必脱黄金辔。","一论朋友难，迟暮敢失坠。","古来事反复，相见横涕泗。","向者玉珂人，谁是青云器。","才尽伤形体，病渴污官位。","故旧独依然，时危话颠踬。","我甘多病老，子负忧世志。","胡为困衣食，颜色少称遂。","远作辛苦行，顺从众多意。","舟檝无根蔕，蛟鼍好为祟。","况兼水贼繁，特戒风飙驶。","崩腾戎马际，往往杀长吏。","子干东诸侯，劝勉防纵恣。","邦以民为本，鱼饥费香饵。","请哀疮痍深，告诉皇华使。","使臣精所择，进德知历试。","恻隐诛求情，固应贤愚异。","列士恶苟得，俊杰思自致。","赠子猛虎行，出效载酸鼻。"],"theme":"送别","theme2":["民生疾苦"],"style":"沉郁","style2":[],"mood":"恬淡","mood2":["愁怨"],"scene":[],"cats":{"抒情":["伤感"],"人生":["梦想"]},"theme_conf":0.477},{"uid":"7c5abe03-8a94-43d1-b340-e25aa1f83fc6","title":"春日茶山病不饮酒因呈宾客","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["笙歌登画船，十日清明前。","山秀白云腻，溪光红粉鲜。","欲开未开花，半阴半晴天。","谁知病太守，犹得作茶仙。"],"theme":"寄赠酬答","theme2":["山水田园","羁旅思乡"],"style":"沉郁","style2":[],"mood":"恬淡","mood2":[],"scene":["山","春","酒","清明"],"cats":{"抒情":["思乡"],"四季":["春天"],"天气":["太阳"],"节日":["清明节"],"食物":["写酒","写茶"]},"theme_conf":0.7},{"uid":"14a78771-6e96-4a41-955b-825661ba6e8e","title":"九成宫","author":"李甘","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["中原无鹿海无波，凤辇鸾旗出幸多。","今日故宫归寂寞，太平功业在山河。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"抒情":["孤独","怀古","爱国"]},"theme_conf":1.0},{"uid":"cp5940b573c62030","title":"谢金莲诗酒红梨花・贺新郎","author":"张寿卿","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["听绝诗句猛然惊，早是他内性儿聪明，才调儿清正。","这两般消的人钦敬，不枉了风流俊英。","诗提着花酒为名，花娇如玉软，酒色似冰清。","世间花酒济人兴，洒斟金潋滟，花列玉娉婷。","(赵汝州云)对这好花好酒，又好良夜，知音相遇，岂不美哉。","(正旦唱)。"],"theme":"闲适隐逸","theme2":["应制干谒"],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["酒","花"],"cats":{"抒情":["友情","感恩"],"植物":["梨花","荷花"],"食物":["写酒"]},"theme_conf":0.509},{"uid":"8331c76b-a250-4d07-9c28-b8a456e0974c","title":"春雨","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["怅卧新春白袷衣，白门寥落意多违。","红楼隔雨相望冷，珠箔飘灯独自归。","远路应悲春晼晚，残宵犹得梦依稀。","玉珰缄札何由达，万里云罗一雁飞。"],"theme":"山水田园","theme2":["爱情相思","羁旅思乡"],"style":"绮丽","style2":[],"mood":"悲怆","mood2":["孤寂","相思"],"scene":["雨","春"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["春天"],"天气":["写雨"]},"theme_conf":0.38},{"uid":"cpa35401f760960a","title":"桂枝香","author":"王安石","dynasty":"宋","section":"宋词","form":"词","paragraphs":["登临送目。","正故国晚秋，天气初肃。","千里澄江似练，翠峰如簇。","归帆去棹残阳里，背西风、酒旗斜矗。","彩舟云淡，星河鹭起，画图难足。","念往昔、繁华竞逐。","叹门外楼头，悲恨相续。","千古凭高，对此漫嗟荣辱。","六朝旧事随流水，但寒烟、芳草凝绿。","至今商女，时时犹唱，后庭遗曲。"],"theme":"咏史怀古","theme2":[],"style":"清新","style2":["悲慨","绮丽"],"mood":"悲怆","mood2":["愁怨","恬淡"],"scene":["舟","秋","花"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"天气":["星星"]},"theme_conf":0.578},{"uid":"160c5168-d55c-4a4c-ba73-ae1596f4b900","title":"杂曲歌辞 行路难三首 三","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见少年头上如云发，少壮如云老如雪。","岂知灌顶有醍醐，能使清凉头不热。","吕梁之水挂飞流，鼋鼍蛟蜃不敢游。","少年恃险若平地，独倚长劒凌清秋。","行路难，行路难，昔少年，今已老。","前朝竹帛事皆空，日暮牛羊古城草。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["慷慨"],"scene":["雪","秋"],"cats":{"抒情":["孤独"],"四季":["秋天"],"山水":["瀑布"],"人生":["青春"]},"theme_conf":0.65},{"uid":"250f7cf0-6e19-4bfc-bcc3-96c0c2c67622","title":"寄薛三郎中","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["人生无贤愚，飘飖若埃尘。","自非得神仙，谁免危其身。","与子俱白头，役役常苦辛。","虽为尚书郎，不及村野人。","忆昔村野人，其乐难具陈。","蔼蔼桑麻交，公侯为等伦。","天未厌戎马，我辈本常贫。","子尚客荆州，我亦滞江滨。","峡中一卧病，疟疠终冬春。","春复加肺气，此病盖有因。","早岁与苏郑，痛饮情相亲。","二公化为土，嗜酒不失真。","余今委修短，岂得恨命屯。","闻子心甚壮，所遇信席珍。","上马不用扶，每扶必怒嗔。","赋诗宾客间，挥洒动八垠。","乃知盖代手，才力老益神。","青草洞庭湖，东浮沧海漘。","君山可避暑，况足采白苹。","子岂无扁舟，往复江汉津。","我未下瞿塘，空念禹功勤。","听说松门峡，吐药揽衣巾。","高秋却束带，鼓枻视青旻。","凤池日澄碧，济济多士新。","余病不能起，健者勿逡巡。","上有明哲君，下有行化臣。"],"theme":"寄赠酬答","theme2":["送别","羁旅思乡"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["慷慨","相思"],"scene":["江"],"cats":{"抒情":["思念","思乡"],"生活":["乡村"]},"theme_conf":0.95},{"uid":"be5f29a5-663b-4905-80e7-b034a6b2a745","title":"琴曲歌辞 王敬伯歌","author":"李端","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["妾本舟中客，闻君江上琴。","君初感妾叹，妾亦感君心。","遂出合欢被，同为交颈禽。","传杯惟畏浅，接膝犹嫌远。","侍婢奏箜篌，女郎歌宛转。","宛转怨如何，中庭霜渐多。","霜多叶可惜，昨日非今夕。","徒结万里欢，终成一宵客。","王敬伯，渌水青山从此隔。"],"theme":"爱情相思","theme2":["闺情宫怨","题画咏艺","羁旅思乡"],"style":"豪放","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["舟"],"cats":{"抒情":["思乡","伤感","闺怨","感恩"]},"theme_conf":0.9},{"uid":"cpe8a61267f2054a","title":"定风波","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["自春来、惨绿愁红，芳心是事可可。","日上花梢，莺穿柳带，犹压香衾卧。","暖酥消，腻云。","终日厌厌倦梳裹。","无那。","恨薄情一去，音书无个。","早知恁么。","悔当初、不把雕鞍锁。","向鸡窗、只与蛮笺象管，拘束教吟课。","镇相随，莫抛躲。","针线闲拈伴伊坐。","和我。","免使年少，光阴虚过。"],"theme":"闺情宫怨","theme2":[],"style":"沉郁","style2":["绮丽","清新"],"mood":"愁怨","mood2":[],"scene":["花","春"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"人生":["时光"]},"theme_conf":1.0},{"uid":"4a732464-35a5-4ffc-94d0-37d653eef2a1","title":"长干曲四首 二","author":"崔颢","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["家临九江水，来去九江侧。","同是长干人，自小不相识。"],"theme":"羁旅思乡","theme2":["闺情宫怨"],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["江"],"cats":{"抒情":["思乡","闺怨"]},"theme_conf":0.572},{"uid":"0334bf67-5fb4-45a2-ab4a-ef7e2b24af02","title":"送少微上人东南游","author":"严维","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["旧游多不见，师在翟公门。","瘴海空山热，雷州白日昏。","片心应为法，万里独无言。","人尽酬恩去，平生未感恩。"],"theme":"送别","theme2":[],"style":"豪放","style2":["婉约"],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"抒情":["孤独","感恩"]},"theme_conf":0.725},{"uid":"08224bf6-bbdb-47b7-b7f8-e002f6199136","title":"怀张为周朴","author":"贯休","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["张周二夫子，诗好人太癖。","更不过岭来，如今头尽白。","人传禹力不到处，河声流向西。","又到处即闭户，逢君方展眉。","不知是不是，若是即大奇。","我又闻二公，心与人不同。","一生常在寂寞中，有时狂吟入僧宅。","锦囊鸟啼荔枝红，有时冥搜海山脑。","珊瑚枝动日杲杲，圣君在上知不知，赤面浊醪许多好。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":["山","酒"],"cats":{"抒情":["孤独"],"食物":["荔枝"]},"theme_conf":0.72},{"uid":"bcf6124b-d0ca-48b1-9b9a-c62824a7d759","title":"严氏溪放歌行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["天下甲马未尽销，岂免沟壑常漂漂。","劒南岁月不可度，边头公卿仍独骄。","费心姑息是一役，肥肉大酒徒相要。","呜呼古人已粪土，独觉志士甘渔樵。","况我飘转无定所，终日慽慽忍羁旅。","秋宿霜溪素月高，喜得与子长夜语。","东游西还力实倦，从此将身更何许。","知子松根长茯苓，迟暮有有意来同煮。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["秋","夜","月","酒"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"人生":["时光"]},"theme_conf":0.529},{"uid":"d746a56b-a083-4549-b107-30764a8726b2","title":"观放鱼歌","author":"卢仝","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["常州贤刺史，从谏议大夫除。","天地好生物，刺史性与天地俱。","见山客，狎鱼鸟。","坐山客，北亭湖。","命舟人，驾舫子。","漾漾菰蒲，酒兴引行处。","正见渔人鱼，刺史密会山客意。","复念网罗婴无辜，忽脱身上殷绯袍。","尽买罟擭尽有无，鳗鳣鲇鳢䲡。","涎恶最顽愚，鳟舫见豳风。","质干稍高流，时白喷雪鲫鲤𦛇。","此辈肥脃为绝尤，老鲤变化颇神异。","三十六鳞如抹朱，水苞弘窟有蛟鼍。","饵非龙饵唯无鲈，丛杂百千头。","性命悬须臾，天心应刺史。","刺史尽活诸，一一投深泉。","跳脱不复拘，得水竞腾突。","动作诡怪殊，或透藻而出。","或破浪而趋，或掉尾孑孑。","或奋鬣愉愉，或如莺掷梭。","或如虵衔珠，四散渐不见。","岛屿徒萦纡，㶉𫛶鸰鸥凫。","喜观争呌呼，小虾亦相庆。","绕岸摇其须，乃知贪生不独顽痴夫。","可怜百千命，几为中肠葅。","若养圣贤真，大烹龙髓敢惜乎。","苦痛如今人，尽是鱼食鱼。","族类恣饮噉，强力无亲疏。","明明刺史心，不欲与物相欺诬。","岸虫两与命，无意杀此活彼用贼徒。","亦忆清江使，横遭乎余且。","圣神七十钻，不及泥中䲡。","哀哉托非贤，五脏生冤讐。","若当刺史时，圣物保不囚。","不疑且不卜，二子安能谀。","二子傥故谀，吾知心受诛。","礼重一草木，易卦称中孚。","又曰钓不纲，又曰远庖厨。","故仁人用心，刺史尽合符。","昔鲁公观棠距箴，遂被孔子贬而书。","今刺史好生，德洽民心。","谁为刺史一褒誉，刺史自上来。","德风如草铺，衣冠兴废礼。","百姓减暴租，豪猾不豪猾。","鳏孤不鳏孤，开古孟渎三十里。","四千顷泥坑为膏腴，刺史视之总若无。","讼庭雀噪坐不得，湖上拔茭植芙蕖。","胜业庄中二桑门，时时对坐谈真如。","因说十千天子事，福力当与刺史俱。","天雨曼陀罗花深没膝，四十千真珠璎珞堆高楼。","此中怪特不可会，但慕刺史仁有余。","刺史敕左右兼小家奴，慎勿背我沈毒钩。","念鱼承奉刺史仁，深僻处，远远游。","刺史官职小，教化未能敷。","第一莫近人，恶人唯口腴。","第一莫出境，四境多网罟。","重伤刺史心，丧尔微贱躯。"],"theme":"山水田园","theme2":["民生疾苦"],"style":"旷达","style2":["绮丽","沉郁"],"mood":"孤寂","mood2":["相思","悲怆"],"scene":["江","楼","鸟"],"cats":{"抒情":["思念","伤感","孤独"],"人生":["励志"]},"theme_conf":0.501},{"uid":"1c1d545e-07a1-46a9-bb76-b7473c1fde43","title":"九日登望仙台呈刘明府容","author":"崔曙","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["汉文皇帝有高台，此日登临曙色开。","三晋云山皆北向，二陵风雨自东来。","关门令尹谁能识，河上仙翁去不回。","且欲近寻彭泽宰，陶然共醉菊花杯。"],"theme":"咏史怀古","theme2":["游仙梦幻"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳"],"cats":{"抒情":["怀古"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.72},{"uid":"cp897e2c6cf08579","title":"瑞鹤仙","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["晴丝牵绪乱。","对沧江斜日，花飞人远。","垂杨暗吴苑。","正旗亭烟冷，河桥风暖。","兰情蕙盼。","惹相思、春根酒畔。","又争知、吟骨萦销，渐把旧衫重翦。","凄断。","流红千浪，缺月孤楼，总难留燕。","歌尘凝扇。","待凭信，拌分钿。","试挑灯欲写，还依不忍，笺幅偷和泪卷。","寄残云、剩雨蓬莱，也应梦见。"],"theme":"游仙梦幻","theme2":[],"style":"沉郁","style2":["清新"],"mood":"相思","mood2":["愁怨"],"scene":["鸟","楼"],"cats":{"抒情":["思念","伤感"],"生活":["写桥"],"动物":["写鸟"]},"theme_conf":0.503},{"uid":"68c0c67f-eb61-4dfc-8685-a43c60f1e0e2","title":"长安道中早行","author":"张泌","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["客离孤馆一灯残，牢落星河欲曙天。","鸡唱未沈函谷月，鴈声新度灞陵烟。","浮生已悟庄周蝶，壮志仍输祖逖鞭。","何事悠悠策羸马，此中辛苦过流年。"],"theme":"哲理悟道","theme2":["羁旅思乡"],"style":"沉郁","style2":[],"mood":"恬淡","mood2":["孤寂","慷慨"],"scene":["月"],"cats":{"抒情":["思乡","孤独"],"天气":["星星"],"人生":["励志","哲理","时光","梦想"]},"theme_conf":0.49},{"uid":"e9a7af99-eb7c-4977-bb08-833c8f32f7f9","title":"早春西湖闲游怅然兴怀忆与微之同赏因思在越官重事殷镜湖之游或恐未暇偶成十八韵寄微之","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["上马复呼宾，湖边景气新。","管弦三数事，骑从十余人。","立换登山屐，行携漉酒巾。","逢花看当妓，遇草坐为茵。","西日笼黄柳，东风荡白苹。","小桥装鴈齿，轻浪甃鱼鳞。","画舫牵徐转，银船酌慢巡。","野情遗世累，醉态任天真。","彼此年将老，平生分最亲。","高天从所愿，远地得为邻。","云树分三驿，烟波限一津。","飜嗟寸步隔，却厌尺书频。","浙右称雄镇，山阴委重臣。","贵垂长紫绶，荣驾大朱轮。","出动刀枪队，归生道路尘。","鴈惊弓易散，鸥怕鼓难驯。","百吏瞻相面，千夫捧拥身。","自然闲兴少，应负镜湖春。"],"theme":"寄赠酬答","theme2":["送别"],"style":"婉约","style2":["豪放"],"mood":"欢愉","mood2":["相思","恬淡"],"scene":["江南","春","江","酒"],"cats":{"抒情":["思念"],"四季":["春天"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":0.9},{"uid":"44916888-b8b7-4a9e-95fe-d18888843b29","title":"柳花歌送客往桂阳","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["沧浪渡头柳花发，断续因风飞不绝。","摇烟拂水积翠间，缀雪含霜谁忍攀。","夹岸纷纷送君去，鸣櫂孤寻到何处。","移家深入桂水源，种柳新成花更繁。","定知别后消散尽，却忆今朝伤旅魂。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["花","月","雪"],"cats":{"抒情":["离别","孤独"],"植物":["柳树"]},"theme_conf":0.668},{"uid":"ad3c4762-ee21-4eaf-a31d-d553075afdfb","title":"郊庙歌辞 祭神州乐章 舒和","author":"褚亮","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["坤道降祥和庶品，灵心载德厚群生。","水土既调三极泰，文武毕备九区平。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"抒情":["怀古","爱国"]},"theme_conf":1.0},{"uid":"fa2d3278-87d8-4be7-a9be-eaa04c23cd6a","title":"送太仆寺李丞赴都到桃林塞","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["远过桃林塞，休年自昔闻。","曲河随暮草，重阜接闲云。","造父为周御，詹嘉守晋军。","应多怀古思，落叶又纷纷。"],"theme":"送别","theme2":["送别"],"style":"旷达","style2":[],"mood":"恬淡","mood2":[],"scene":["塞外"],"cats":{"抒情":["怀古"],"生活":["边塞"],"植物":["桃花"]},"theme_conf":0.85},{"uid":"ea6c5a06-ed63-49f3-82aa-bb7bbded3ee5","title":"鼓吹曲辞 有所思","author":"刘氏云","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["朝亦有所思，暮亦有所思。","登楼望君处，蔼蔼浮云飞。","浮云遮却阳关道，向晚谁知妾怀抱。","玉井苍苔春院深，桐花落地无人扫。"],"theme":"边塞征战","theme2":["送别","闺情宫怨"],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":["春","楼","园林"],"cats":{"抒情":["闺怨"],"四季":["春天"],"天气":["写云"],"生活":["边塞"]},"theme_conf":0.38},{"uid":"cp30a4d20b32a6da","title":"祝英台令","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["宝钗分，桃叶渡。","烟柳暗南浦。","怕上层楼，十日九风雨。","断肠片片飞红，都无人管，倩谁唤、流莺声住。","鬓边觑。","试把花卜心期，才簪又重数。","罗帐灯昏，呜咽梦中语。","是他春带愁来，春归何处。","却不解、将愁归去。"],"theme":"闺情宫怨","theme2":["送别"],"style":"绮丽","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["楼","春","雨"],"cats":{"抒情":["离别","伤感","闺怨"],"四季":["春天"]},"theme_conf":0.533},{"uid":"75e8e864-7f92-42e9-9467-8988475bdf49","title":"幽怀","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["幽怀不能写，行此春江浔。","适与佳节会，士女竞光阴。","凝妆耀洲渚，繁吹荡人心。","间关林中鸟，亦知和为音。","岂无一尊酒，自酌还自吟。","但悲时易失，四序迭相侵。","我歌君子行，视古犹视今。"],"theme":"咏怀抒感","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["江","酒"],"cats":{"抒情":["伤感"],"人生":["时光"]},"theme_conf":0.88},{"uid":"cp4189bec3f75298","title":"瑞鹤仙","author":"蒋捷","dynasty":"宋","section":"宋词","form":"词","paragraphs":["绀烟迷雁迹。","渐断鼓零钟，街喧初息。","风檠背寒壁。","放冰蜍飞到，丝丝窗隙。","琼瑰暗泣。","念乡关、霜芜似织。","漫将身、化鹤归来，忘却旧游端的。","欢极。","蓬壶蕖浸，花院梨溶，醉连春夕。","柯云罢弈。","樱桃在，梦难觅。","劝清光，乍可幽窗相伴，休照红楼夜笛。","怕人间、换谱伊凉，素娥未识。"],"theme":"羁旅思乡","theme2":["闲适隐逸","游仙梦幻"],"style":"旷达","style2":["清新"],"mood":"悲怆","mood2":["欢愉","相思"],"scene":["鸟"],"cats":{"抒情":["思乡"],"动物":["写鸟"]},"theme_conf":0.457},{"uid":"05a734dd-b434-428e-ab3f-695ac637d516","title":"伤桃源薛道士","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["坛边松在鹤巢空，白鹿闲行旧径中。","手植红桃千树发，满山无主任春风。"],"theme":"山水田园","theme2":["悼亡挽歌"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春","山"],"cats":{"抒情":["伤感","悼亡"],"四季":["春天"],"植物":["桃花"]},"theme_conf":0.491},{"uid":"d827bbc7-2b82-4437-b81b-5e174dcdc134","title":"石上阁","author":"无名氏","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["水石引我去，南湖复东壑。","不厌随竹阴，来登石上阁。","磴道通石门，欹崖断如凿。","飞梁架峰头，夭矫虹霓若。","下视竹木杪，仰见悬泉落。","水声兼松吹，音响参众乐。","时时为雾雨，飘洒湿帘箔。","吾欲弃簪缨，于兹守寂寞。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["楼","山"],"cats":{"抒情":["孤独"],"山水":["瀑布"],"天气":["彩虹"]},"theme_conf":0.75},{"uid":"151b748b-c973-46df-9c3a-6ce7a9ab53e0","title":"杂曲歌辞 汉宫少年行","author":"李益","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见上宫警夜营八屯，冬冬街鼓朝朱轩。","玉阶霜仗拥未合，少年排入铜龙门。","暗闻弦管九天上，宫漏沈沈清吹繁。","才明走马绝驰道，呼鹰挟弹通缭垣。","玉笼金琐养黄口，探雏取卵伴王孙。","分曹六博快一掷，迎欢先意笑语喧。","巧为柔媚学优孟，儒衣嬉戏冠沐猨。","晚来香街经柳市，行过倡市宿桃根。","相逢杯酒一言失，回朱点白闻至尊。","金张许史伺颜色，王侯将相莫敢论。","岂知人事无定势，朝欢暮戚如掌翻。","椒房宠移子爱夺，一夕秋风生戾园。","徒用黄金将买赋，宁知白玉暗成痕。","持杯收水水已覆，徙薪避火火更燔。","欲求四老张丞相，南山如天不可上。"],"theme":"闺情宫怨","theme2":["咏史怀古"],"style":"绮丽","style2":["婉约","沉郁"],"mood":"欢愉","mood2":[],"scene":["夜","酒","秋","冬"],"cats":{"抒情":["闺怨","怀古"],"四季":["秋天","冬天"],"人生":["青春"]},"theme_conf":0.513},{"uid":"d1d57a82-baf7-4776-854e-b99e5319ae87","title":"在滁苦雨归桃花崦伤亲友略尽","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["废弃忝残生，后来亦先夭。","诗人感风雨，长夜何时晓。","去国宦情无，近乡归梦少。","庇身绝中授，甘静忘外扰。","丽景变重阴，洞山空木表。","灵潮若可通，寄谢西飞鸟。"],"theme":"羁旅思乡","theme2":["悼亡挽歌"],"style":"冲淡","style2":[],"mood":"愁怨","mood2":["恬淡"],"scene":["雨"],"cats":{"抒情":["友情","思乡","伤感","悼亡"],"天气":["写雨"],"植物":["桃花"]},"theme_conf":0.431},{"uid":"34bac317-4e11-40fa-abae-731bfb0e8d9c","title":"横吹曲辞 折杨柳","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["玉窗朝日映，罗帐春风吹。","拭泪攀杨柳，长条宛地垂。","白花飞历乱，黄鸟思参差。","妾自肝肠断，旁人那得知。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["婉约","沉郁"],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"植物":["柳树"]},"theme_conf":1.0},{"uid":"19b577a6-dca0-4c95-9365-7e4a8356e71d","title":"郑驸马池台喜遇郑广文同饮","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["不谓生戎马，何知共酒杯。","然脐郿坞败，握节汉臣回。","白发千茎雪，丹心一寸灰。","别离经死地，披写忽登台。","重对秦箫发，俱过阮宅来。","留连春夜舞，泪落强裴回。"],"theme":"送别","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"欢愉","mood2":[],"scene":["酒","楼","园林","雪","春"],"cats":{"抒情":["离别"],"四季":["春天"],"动物":["写马"]},"theme_conf":1.0},{"uid":"0732a1c2-259d-451e-b11e-11344d0ed7ce","title":"登庐山峰顶寺","author":"刘眘虚","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["孤峰临万象，秋气何高清。","天际南郡出，林端西江明。","山门二缁叟，振锡闻幽声。","心照有无界，业悬前后生。","虽知真机静，尚与爱网幷。","方首金门路，未遑参道情。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["山"],"cats":{"抒情":["孤独"],"山水":["庐山"]},"theme_conf":0.538},{"uid":"09788f19-1e11-4394-a543-0edf2cfdcae9","title":"相和歌辞 燕歌行","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["汉家烟尘在东北，汉将辞家破残贼。","男儿本自重横行，天子非常赐颜色。","𪭢金伐鼓下榆关，旌旗逶迤碣石间。","校尉羽书飞瀚海，单于猎火照狼山。","山川萧条极边土，胡骑凭凌杂风雨。","战士军前半死生，美人帐下犹歌舞。","大漠穷秋塞草衰，孤城落日鬬兵稀。","身当恩遇常轻敌，力尽关山未解围。","铁衣远戍辛勤久，玉箸应啼别离后。","少妇城南欲断肠，征人蓟北空回首。","边风飘飘那可度，绝域苍茫更何有。","杀气三日作阵云，寒声一夜传刁斗。","相看白刃血纷纷，死节从来岂顾勋。","君不见沙场征战苦，至今犹忆李将军。"],"theme":"边塞征战","theme2":[],"style":"雄浑","style2":["沉郁","婉约"],"mood":"孤寂","mood2":["愁怨","相思"],"scene":["塞外"],"cats":{"抒情":["离别","思念","伤感","孤独"],"人物":["女子"],"人生":["战争"],"生活":["边塞"],"动物":["写鸟"]},"theme_conf":0.755},{"uid":"0f1e20b5-a8e4-45cd-a1e2-45710eec46fb","title":"横吹曲辞 骢马曲","author":"纪唐天","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["连钱出塞蹋沙蓬，岂比当时御史骢。","逐北自谙深碛路，连嘶谁念静边功。","登山每与青云合，弄影应知碧草同。","今日虏平将换妾，不如罗袖舞春风。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["塞外","春","山"],"cats":{"抒情":["闺怨"],"四季":["春天"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.63},{"uid":"4de1320f-f293-4f10-846b-1059c07aaab8","title":"清明日送邓芮二子还乡","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["钟鼓喧离日，车徒促夜装。","晓厨新变火，轻柳暗翻霜。","传镜看华发，持杯话故乡。","每嫌儿女泪，今日自沾裳。"],"theme":"送别","theme2":["节令风俗","羁旅思乡"],"style":"清新","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["清明"],"cats":{"抒情":["思乡","伤感"],"天气":["太阳"],"节日":["清明节"]},"theme_conf":0.329},{"uid":"1669d597-4c37-4897-b5f8-a15eedd8cdf0","title":"经河上公庙","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔闻有耆叟，河上独遗荣。","迹与尘嚻隔，心将道德幷。","讵以天地累，宁为宠辱惊。","矫然翔寥廓，如何屈坚贞。","玄玄妙门启，肃肃祠宇清。","冥漠无先后，那能纪姓名。"],"theme":"咏史怀古","theme2":[],"style":"雄浑","style2":[],"mood":"孤寂","mood2":[],"scene":["塞外"],"cats":{"抒情":["孤独","怀古"],"山水":["江河"]},"theme_conf":0.65},{"uid":"df01972d-f851-4b0f-bbd5-9e57be874eb6","title":"古意","author":"蒋冽","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["冉冉红罗帐，开君玉楼上。","画作同心鸟，衔花两相向。","春风正可怜，吹暎绿窗前。","妾意空相感，君心何处边。"],"theme":"闺情宫怨","theme2":["爱情相思"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["花","春","楼"],"cats":{"抒情":["爱情","闺怨","感恩"],"四季":["春天"]},"theme_conf":0.524},{"uid":"72366286-73aa-49c3-9ac0-fa0017da8a4a","title":"王可封临终","author":"许浑","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["十世为儒少子孙，一生长负信陵恩。","今朝埋骨寒山下，为报慈亲休倚门。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"抒情":["怀古"],"人物":["母亲"]},"theme_conf":0.65},{"uid":"cp1b8e27c601410e","title":"谢金莲诗酒红梨花・醉中天","author":"张寿卿","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["笑哈哈捧流霞，我羞怯怯怎酬答。","也不知前世今生甚的缘法，相会在花枝下。","可知道刘郎喜杀，又值着我玉真未嫁，抵多少香饭胡麻。","(赵汝州云)小娘子，今夜幸得相会，但不知后会何时？实难为别。","(正旦云)妾明夜晚间，将一樽酒一瓶花，与秀才回礼。","(赵汝州云)小生来日晚间专望也。","(正旦唱)。"],"theme":"送别","theme2":["闲适隐逸"],"style":"豪放","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["酒","花"],"cats":{"抒情":["感恩"],"植物":["梨花","荷花"],"食物":["写酒"]},"theme_conf":0.615},{"uid":"cp234b5064f09847","title":"浪淘沙","author":"欧阳修","dynasty":"宋","section":"宋词","form":"词","paragraphs":["五岭麦秋残。","荔子初丹。","绛纱囊里水晶丸。","可惜天教生处远，不近长安。","往事忆开元。","妃子偏怜。","一从魂散马嵬关。","只有红尘无驿使，满眼骊山。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"悲慨","style2":[],"mood":"相思","mood2":[],"scene":["山","秋"],"cats":{"抒情":["思念","怀古"],"四季":["秋天"],"食物":["荔枝"]},"theme_conf":0.511},{"uid":"0ba3b183-531e-48da-aa22-cacc3936e6aa","title":"杂曲歌辞 伤歌行","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["众毒蔓贞松，一枝难久荣。","岂知黄庭客，仙骨生不成。","春色舍芳蕙，秋风遶枯茎。","弹琴不成曲，始觉知音倾。","馆月改旧照，吊宾写余情。","还舟空江上，波浪送铭旌。"],"theme":"悼亡挽歌","theme2":["羁旅思乡","送别"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["春","秋","舟","月","园林","江"],"cats":{"抒情":["友情","思乡","伤感","悼亡"],"四季":["春天","秋天"]},"theme_conf":0.95},{"uid":"3108e645-afe2-4f20-b8a8-cc280496b99c","title":"对梨花赠皇甫秀才","author":"韦庄","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["林上梨花雪压枝，独攀琼艳不胜悲。","依前此地逢君处，还是去年今日时。","且恋残阳留绮席，莫推红袖诉金巵。","腾腾战鼓正多事，须信明朝难重持。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":[],"mood":"悲怆","mood2":["孤寂"],"scene":["花","雪"],"cats":{"抒情":["伤感","孤独"],"植物":["梨花"]},"theme_conf":0.85},{"uid":"86500cf0-f0a0-4a79-893e-6bedd71460ee","title":"怀钟陵旧游四首 二","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["滕阁中春绮席开，柘枝蛮鼓殷晴雷。","垂楼万幕青云合，破浪千帆阵马来。","未掘双龙牛斗气，高悬一榻栋梁材。","连巴控越知何事，珠翠沈檀处处堆。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["楼","春"],"cats":{"抒情":["怀古"],"四季":["春天"],"人生":["励志"]},"theme_conf":1.0},{"uid":"609cfa44-628d-4344-91bd-ca03998bf52e","title":"冬至宿杨梅馆","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["十一月中长至夜，三千里外远行人。","若为独宿杨梅馆，冷枕单床一病身。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["冬"],"cats":{"抒情":["思乡","孤独"],"四季":["冬天"],"植物":["梅花"]},"theme_conf":0.9},{"uid":"03ab8d68-3b2a-4180-8592-cd523ee54570","title":"相和歌辞 猛虎行","author":"李贺","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["长戈莫舂，彊弩莫烹。","乳孙哺子，教得生狞。","举头为城，掉尾为旌。","东海黄公，愁见夜行。","道逢驺虞，牛哀不平。","生何用尺刀，壁上雷鸣。","泰山之下，妇人哭声。","官家有程，吏不敢听。"],"theme":"边塞征战","theme2":["悼亡挽歌","羁旅思乡"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["山"],"cats":{"抒情":["思乡","伤感","悼亡"],"山水":["泰山"]},"theme_conf":0.408},{"uid":"5a422f68-ee50-4809-a6f7-e1ef510e51a5","title":"芳兰","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["春晖开紫苑，淑景媚兰场。","映庭含浅色，凝露泫浮光。","日丽参差影，风传轻重香。","会须君子折，佩里作芬芳。"],"theme":"咏物","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["花"],"cats":{"抒情":["感恩"]},"theme_conf":1.0},{"uid":"2ceb871e-c8a7-488a-95e9-46d34a6f088f","title":"寻华山云台观道士","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋日西山明，胜趣引孤策。","桃源数曲尽，洞口两岸坼。","还从罔象来，忽得仙灵宅。","霓裳谁之子，霞酌能止客。","残阳在翠微，携手更登历。","林行拂烟雨，溪望乱金碧。","飞鸟下天窗，褭松际云壁。","稍寻玄踪远，宛入寥天寂。","愿言葛仙翁，终年炼玉液。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"抒情":["孤独"],"天气":["写云"]},"theme_conf":0.831},{"uid":"e4a1f615-2b63-4797-8b7a-3ea3708722df","title":"杂言湖山歌送许鸣谦","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["湖中之山兮波上青，桂飒飒兮雨冥冥。","君归兮春早，满山兮碧草。","晨舂暮汲兮心何求，涧户岩扉兮身自老。","东岭西峰兮同白云，鸡鸣犬吠兮时相闻。","幽芳媚景兮当嘉月，践石扪萝兮恣超忽。","空山寂寂兮颍阳人，旦夕孤云随一身。"],"theme":"山水田园","theme2":["送别"],"style":"沉郁","style2":["冲淡"],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"抒情":["孤独"],"天气":["写云"]},"theme_conf":0.564},{"uid":"16c63af4-622a-45e2-9a1c-ebb406711054","title":"琴曲歌辞 宛转歌 一","author":"郎大家宋氏","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["风已清，月朗琴复鸣。","掩抑非千态，殷勤是一声。","歌宛转，宛转和且长。","愿为双鸿鹄，比翼共翱翔。"],"theme":"爱情相思","theme2":["爱情相思"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["月"],"cats":{"抒情":["爱情"],"人生":["梦想"]},"theme_conf":0.95},{"uid":"7b9b330b-4d3f-4de9-96bd-610bdd918133","title":"射训狐","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["有鸟夜飞名训狐，矜凶挟狡夸自呼。","乘时阴黑止我屋，声势慷慨非常麤。","安然大唤谁畏忌，造作百怪非无须。","聚鬼征妖自朋扇，摆掉栱桷颓塈涂。","慈母抱儿怕入席，那暇更护鸡窠雏。","我念乾坤德泰大，卵此恶物常勤劬。","纵之岂即遽有害，斗柄行拄西南隅。","谁谓停奸计尤剧，意欲唐突羲和乌。","侵更历漏气弥厉，何由侥幸休须臾。","咨余往射岂得已，候女两眼张睢盱。","枭惊堕梁蛇走窦，一夫斩颈群雏枯。"],"theme":"亲情","theme2":[],"style":"幽峭","style2":[],"mood":"相思","mood2":[],"scene":["夜"],"cats":{"抒情":["感恩"],"人物":["母亲"]},"theme_conf":1.0},{"uid":"b8ae44b3-ba8d-42d3-85a7-a70aa8608379","title":"长安遇冯著","author":"韦应物","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["客从东方来，衣上灞陵雨。","问客何为来，采山因买斧。","冥冥花正开，飏飏燕新乳。","昨别今已春，鬓丝生几缕。"],"theme":"民生疾苦","theme2":["送别","羁旅思乡"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["春","雨","山"],"cats":{"抒情":["思乡"],"四季":["春天"]},"theme_conf":0.358},{"uid":"4d6973c8-af8f-4d6f-a5a1-b118bfe79d1e","title":"相和歌辞 相逢行","author":"韦应物","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["二十登汉朝，英声迈今古。","适从东方来，又欲谒明主。","犹酣新丰酒，尚带霸陵雨。","邂逅两相逢，别来间寒暑。","宁知白日晚，暂向花间语。","忽闻长乐钟，走马东西去。"],"theme":"咏史怀古","theme2":["送别"],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["夏","酒","雨"],"cats":{"抒情":["怀古"],"四季":["夏天"]},"theme_conf":0.552},{"uid":"4e519eda-bd1c-4705-982e-b96f19b1a67f","title":"汉阴吊崔员外坟","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["远别望有归，叶落望春晖。","所痛泉路人，一去无还期。","荒坟遗汉阴，坟树啼子规。","存没抱冤滞，孤魂意何依。","岂无骨肉亲，岂无深相知。","曝露不复问，高名亦何为。","相携恸君罢，春日空迟迟。"],"theme":"悼亡挽歌","theme2":[],"style":"冲淡","style2":[],"mood":"悲怆","mood2":["孤寂"],"scene":["春"],"cats":{"抒情":["孤独","悼亡","感恩"],"四季":["春天"]},"theme_conf":0.99},{"uid":"7343f60d-c51e-44a0-9b6d-30fb63783ab0","title":"竹枝曲","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["帝子苍梧不复归，洞庭叶下荆云飞。","巴人夜唱竹枝后，肠断晓猿声渐稀。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"愁怨","mood2":[],"scene":["江","夜","园林"],"cats":{"抒情":["伤感"],"植物":["竹子"]},"theme_conf":1.0},{"uid":"eaf1094e-b116-4d91-819b-df1a80e1c991","title":"月蚀诗","author":"卢仝","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["新天子即位五年，岁次庚寅。","斗柄插子，律调黄钟。","森森万木夜僵立，寒气赑屭顽无风。","烂银盘从海底出，出来照我草屋东。","天色绀滑凝不流，冰光交贯寒朣胧。","初疑白莲花，浮出龙王宫。","八月十五夜，比并不可双。","此时怪事发，有物吞食来。","轮如壮士斧斫坏，桂似雪山风拉摧。","百炼镜，照见胆。","平地埋寒灰，火龙珠。","飞出脑，却入蚌蛤胎。","摧环破璧眼看尽，当天一搭如煤炲。","磨踪灭迹须臾间，便似万古不可开。","不料至神物，有此大狼狈。","星如撒沙出，争头事光大。","奴婢炷暗灯，揜菼如玳瑁。","今夜吐燄长如虹，孔隙千道射户外。","玉川子，涕泗下。","中庭独自行，念此日月者。","太阴太阳精，皇天要识物。","日月乃化生，走天汲汲劳四体。","与天作眼行光明，此眼不自保。","天公行道何由行，吾见阴阳家有说。","望日蚀月月光灭，朔月掩日日光缺。","两眼不相攻，此说吾不容。","又孔子师老子云，五色令人目盲。","吾恐天似人，好色即丧明。","幸且非春时，万物不娇荣。","青山破瓦色，绿水冰峥嵘。","花枯无女艳，鸟死沈歌声。","顽冬何所好，偏使一目盲。","传闻古老说，蚀月虾蟇精。","径圆千里入汝腹，汝此痴骸阿谁生。","可从海窟来，便解缘青冥。","恐是眶睫间，揜塞所化成。","黄帝有二目，帝舜重瞳明。","二帝悬四目，四海生光辉。","吾不遇二帝，滉漭不可知。","何故瞳子上，坐受虫豸欺。","长嗟白兔捣灵药，恰似有意防奸非。","药成满臼不中度，委任白兔夫何为。","忆昔尧为天，十日烧九州。","金烁水银流，玉煼丹砂焦。","六合烘为窑，尧心增百忧。","帝见尧心忧，勃然发怒决洪流。","立拟沃杀九日妖，天高日走沃不及。","但见万国赤子𧥄𧥄生鱼头，此时九御导九日。","争持节幡麾幢旒，驾车六九五十四头蛟螭虬。","掣电九火辀，汝若蚀开齱齵轮。","御辔执索相爬钩，推荡轰訇入汝喉。","红鳞燄鸟烧口快，翎鬣倒侧声醆邹。","撑肠拄肚礧傀如山丘，自可饱死更不偷。","不独填饥坑，亦解尧心忧。","恨汝时当食，藏头𢬍脑不肯食。","不当食，张唇哆觜食不休。","食天之眼养逆命，安得上帝请汝刘。","呜呼！人养虎，被虎啮。","天媚蟇，被蟇瞎。","乃知恩非类，一一自作孽。","吾见患眼人，必索良工诀。","想天不异人，爱眼固应一。","安得常娥氏，来习扁鹊术。","手操舂喉戈，去此睛上物。","其初犹朦胧，既久如抹漆。","但恐功业成，便此不吐出。","玉川子又涕泗下，心祷再拜额榻砂土中。","地上虮虱臣仝告愬帝天皇，臣心有铁一寸。","可刳妖蟇痴肠，上天不为臣立梯磴。","臣血肉身，无由飞上天。","扬天光，封词付与小心风。","𩙥排阊阖入紫宫，密迩玉几前擘坼。","奏上臣仝顽愚胸，敢死横干天。","代天谋其长，东方苍龙角。","插戟尾捭风，当心开明堂。","统领三百六十鳞虫，坐理东方宫。","月蚀不救援，安用东方龙。","南方火鸟赤泼血，项长尾短飞跋躠。","头戴井冠高逵枿，月蚀鸟宫十三度。","鸟为居停主人不觉察，贪向何人家。","行赤口毒舌，毒虫头上吃却月。","不啄杀，虚眨鬼眼明䆕䆷。","鸟罪不可雪，西方攫虎立踦踦。","斧为牙，凿为齿。","偷牺牲，食封豕。","大蟇一脔，固当软美。","见似不见，是何道理。","爪牙根天不念天，天若准拟错准拟。","北方寒龟被虵缚，藏头入壳如入狱。","虵筋束紧束破壳，寒龟夏鼈一种味。","且当以其肉充臛，死壳没信处。","唯堪支床脚不堪钻灼与天卜，岁星主福德。","官爵奉董秦，忍使黔娄生。","覆尸无衣巾，天失眼不吊。","岁星胡其仁，荧惑矍铄翁。","执法大不中，月明无罪过。","不纠蚀月虫，年年十月朝太微。","支卢谪罚何灾凶，土星与土性相背。","反养福德生祸害，到人头上死破败。","今夜月蚀安可会，太白真将军。","怒激锋铓生，恒州阵斩郦定进。","项骨脃甚春蔓菁，天唯两眼失一眼。","将军何处行天兵，辰星任廷尉。","天律自主持，人命在盆底。","固应乐见天盲时，天若不肯信。","试唤臯陶鬼一问，一如今日。","三台文昌宫，作上天纪纲。","环天二十八宿，磊磊尚书郎。","整顿排班行，劒握他人将。","一四太阳侧，一四天市傍。","操斧代大匠，两手不怕伤。","弧矢引满反射人，天狼呀啄明煌煌。","痴牛与𫘤女，不肯勤农桑。","徒劳含淫思，旦夕遥相望。","蚩尤簸旗弄旬朔，始搥天鼓鸣珰琅。","枉矢能蛇行，眊目森森张。","天狗下舐地，血流何滂滂。","谲险万万党，架搆何可当。","眯目衅成就，害我光明王。","请留北斗一星相北极，指麾万国悬中央。","此外尽扫除，堆积如山冈。","赎我父母光，当时常星没。","殒雨如迸浆，似天会事发。","叱喝诛奸强，何故中道废。","自遗今日殃，善善又恶恶。","郭公所以亡，愿天神圣心。","无信他人忠，玉川子词讫。","风色紧格格，近月黑暗边。","有似动劒戟，须臾痴蟇精。","两吻自决坼，初露半个璧。","渐吐满轮魄，众星尽原赦。","一蟇独诛磔，腹肚忽脱落。","依旧挂穹碧，光彩未苏来。","惨澹一片白，奈何万里光。","受此吞吐厄，再得见天眼。","感荷天地力，或问玉川子。","孔子修春秋，二百四十年。","月蚀尽不收，今子咄咄词。","颇合孔意不，玉川子笑荅。","或请听逗留，孔子父母鲁。","讳鲁不讳周，书外书大恶。","故月蚀不见收，予命唐天。","口食唐土，唐礼过三。","唐乐过五，小犹不说。","大不可数，灾沴无有小大瘉。","安得引衰周，研核其可否。","日分昼，月分夜。","辨寒暑，一主刑。","二主德，政乃举。","孰为人面上，一目偏可去。","愿天完两目，照下万方土。","万古更不瞽，万万古。","更不瞽，照万古。"],"theme":"边塞征战","theme2":[],"style":"雄浑","style2":["幽峭","豪放"],"mood":"相思","mood2":["欢愉","愁怨"],"scene":["月","夏","冬"],"cats":{"抒情":["思念","伤感"],"四季":["夏天","冬天"],"天气":["月亮","星星"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.423},{"uid":"99953267-a278-429d-8470-cc30ebcb23d8","title":"九日诸人集于林","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["九日明朝是，相要旧俗非。","老翁难早出，贤客幸知归。","旧采黄花賸，新梳白发微。","漫看年少乐，忍泪已沾衣。"],"theme":"节令风俗","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"欢愉","mood2":["愁怨"],"scene":["重阳"],"cats":{"抒情":["伤感"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.75},{"uid":"cpee91838ef68a70","title":"玉楼春","author":"刘克庄","dynasty":"宋","section":"宋词","form":"词","paragraphs":["年年跃马长安市。","客舍似家家似寄。","青钱换酒日无何，红烛呼庐宵不寐。","易挑锦妇机中字。","难得玉人心下事。","男儿西北有神州，莫滴水西桥畔泪。"],"theme":"羁旅思乡","theme2":["送别"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["夜","春","楼"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"生活":["写桥"]},"theme_conf":0.535},{"uid":"de7404b1-b2f2-4924-b187-b47aa50039d7","title":"清明","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["著处繁花务是日，长沙千人万人出。","渡头翠柳艳明眉，争道朱蹄骄啮膝。","此都好游湘西寺，诸将亦自军中至。","马援征行在眼前，葛强亲近同心事。","金镫下山红粉晚，牙樯捩柁青楼远。","古时丧乱皆可知，人世悲欢暂相遣。","弟姪虽存不得书，干戈未息苦离居。","逢迎少壮非吾道，况乃今朝更祓除。"],"theme":"节令风俗","theme2":[],"style":"绮丽","style2":["清新"],"mood":"悲怆","mood2":["欢愉","慷慨"],"scene":["清明"],"cats":{"抒情":["伤感"],"人生":["青春"],"节日":["清明节"]},"theme_conf":0.78},{"uid":"76d53cae-3896-4d5a-a8ee-5594289c037a","title":"玉华仙子歌","author":"李康成","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["紫阳仙子名玉华，珠盘承露饵丹砂。","转态凝情五云里，娇颜千岁芙蓉花。","紫阳彩女矜无数，遥见玉华皆掩嫭。","高堂初日不成妍，洛渚流风徒自怜。","璇阶霓绮阁，碧题霜罗幕。","仙娥桂树长自春，王母桃花未尝落。","上元夫人宾上清，深宫寂历厌层城。","解佩空怜郑交甫，吹箫不逐许飞琼。","溶溶紫庭步，渺渺瀛台路。","兰陵贵士谢相逢，济北风生尚回顾。","沧洲傲吏爱金丹，清心回望云之端。","羽盖霓裳一相识，传情写念长无极。","长无极，永相随。","攀霄历金阙，弄影下瑶池。","夕宿紫府云母帐，朝餐玄圃昆仑芝。","不学兰香中道绝，却教青鸟报相思。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["元宵","园林","江","楼","花","春"],"cats":{"抒情":["思念"],"四季":["春天"],"节日":["元宵节"]},"theme_conf":0.734},{"uid":"cpf19c04dfb7e362","title":"祝英台近","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["翦红情，裁绿意，花信上钗股。","残日东风，不放岁华去。","有人添烛西窗，不眠侵晓，笑声转、新年莺语。","旧尊俎。","玉纤曾擘黄柑，柔香系幽素。","归梦湖边，还迷镜中路。","可怜千点吴霜，寒销不尽，又相对、落梅如雨。"],"theme":"闺情宫怨","theme2":[],"style":"清新","style2":["婉约","绮丽"],"mood":"欢愉","mood2":[],"scene":["花","春","楼","雨"],"cats":{"抒情":["闺怨"],"四季":["春天"],"节日":["春节"]},"theme_conf":0.65},{"uid":"6b78aaf7-4de0-4fc2-a524-8eaa6e66a244","title":"题清源寺","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["儒墨兼宗道，云泉隐旧庐。","盂城今寂寞，辋水自纡余。","内学销多累，西林易故居。","深房春竹老，细雨夜钟疎。","陈迹留金地，遗文在石渠。","不知登座客，谁得蔡邕书。"],"theme":"山水田园","theme2":["哲理悟道"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["雨"],"cats":{"抒情":["孤独"],"山水":["庐山"],"天气":["写雨"]},"theme_conf":0.563},{"uid":"d9b26a58-c9cb-4a98-8980-32df48b58348","title":"代九九","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["昔年桃李月，颜色共花宜。","廻脸莲初破，低蛾柳竝垂。","望山多倚树，弄水爱临池。","远被登楼识，潜因倒影窥。","隔林徒想像，上砌转逶迤。","谩掷庭中果，虚攀墙外枝。","强持文玉佩，求结麝香缡。","阿母怜金重，亲兄要马骑。","把将娇小女，嫁与冶游儿。","自隐勤勤索，相要事事随。","每常同坐卧，不省暂参差。","才学羞兼妒，何言宠便移。","青春来易皎，白日誓先亏。","僻性嗔来见，邪行醉后知。","别床铺枕席，当面指瑕疵。","妾貌应犹在，君情遽若斯。","的成终世恨，焉用此宵为。","鸾镜灯前扑，鸳衾手下隳。","参商半夜起，琴瑟一声离。","努力新丛艳，狂风次第吹。"],"theme":"送别","theme2":["闺情宫怨"],"style":"绮丽","style2":["豪放","婉约"],"mood":"慷慨","mood2":["愁怨"],"scene":["园林","夜","春"],"cats":{"抒情":["离别","闺怨"],"四季":["春天"],"天气":["写风"],"人物":["母亲"],"人生":["青春"]},"theme_conf":0.431},{"uid":"cp8a42437795a11b","title":"高阳台","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["宫粉雕痕，仙云堕影，无人野水荒湾。","古石埋香，金沙锁骨连环。","南楼不恨吹横笛，恨晓风、千里关山。","半飘零，庭上黄昏，月冷阑干。","寿阳空理愁鸾。","问谁调玉髓，暗补香瘢。","细雨归鸿，孤山无限春寒。","离魂难倩招清些，梦缟衣、解佩溪边。","最愁人，啼鸟晴明，叶底青圆。"],"theme":"山水田园","theme2":["羁旅思乡","游仙梦幻"],"style":"沉郁","style2":["婉约","绮丽"],"mood":"孤寂","mood2":["愁怨"],"scene":["楼","雨"],"cats":{"抒情":["思乡","伤感","孤独"],"山水":["西湖"],"天气":["写雨"]},"theme_conf":0.378},{"uid":"8af643c9-a8b0-49b7-b8e9-88920ab0bbd8","title":"石鱼湖上醉歌","author":"元结","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["石鱼湖，似洞庭，夏水欲满君山青。","山为樽，水为沼，酒徒历历坐洲岛。","长风连日作大浪，不能废人运酒舫。","我持长瓢坐巴丘，酌饮四坐以散愁。"],"theme":"闲适隐逸","theme2":["山水田园"],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["酒","江"],"cats":{"抒情":["伤感"],"食物":["写酒"]},"theme_conf":0.84},{"uid":"5cee205e-5c59-46e5-b060-9b0916c64a3f","title":"忆昔二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["忆昔先皇巡朔方，千乘万骑入咸阳。","阴山骄子汗血马，长驱东胡胡走藏。","邺城反复不足怪，关中小儿坏纪纲，张后不乐上为忙。","至今今上犹拨乱，劳身焦思补四方。","我昔近侍叨奉引，出兵整肃不可当。","为留猛士守未央，致使岐雍防西羌。","犬戎直来坐御床，百官跣足随天王愿见北地傅介子，老儒不用尚书郎。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["思念"],"人物":["儿童"],"人生":["战争"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"4760fc44-7062-447a-ad4f-579453cc556e","title":"句","author":"幸夤逊","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["苦教作镇居中国，争得泥金在泰山。","才闻暖律先偷眼，既待和风始展眉。","蒙君知重惠琼实，薄起金刀钉玉深。","嚼处春冰敲齿冷，咽时雪液沃心寒。","深妆玉瓦平无垅，乱拂芦花细有声。","日回禽影穿疎木，风递猨声入小楼。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["婉约","幽峭"],"mood":"愁怨","mood2":[],"scene":["山","雪","冬"],"cats":{"抒情":["闺怨"],"山水":["泰山"]},"theme_conf":1.0},{"uid":"10cd87b1-fae0-4741-b32e-140d49041c4f","title":"江上送客游庐山","author":"张继","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["楚客自相送，沾裳春水边。","晚来风信好，并发上江船。","花映新林岸，云开瀑布泉。","惬心应在此，佳句向谁传。"],"theme":"送别","theme2":["羁旅思乡"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["山","江"],"cats":{"抒情":["思乡"],"山水":["庐山","江河","瀑布"]},"theme_conf":0.458},{"uid":"fd631736-f18f-45dd-a65a-2c61d5785bd9","title":"南中怀友生","author":"栖蟾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["荔枝江上立，望北几思量。","隔海无书劄，前年在汉阳。","瘴村人起早，铜柱象揩光。","居此成何事，寻君过碧湘。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["江"],"cats":{"抒情":["友情"],"食物":["荔枝"]},"theme_conf":0.65},{"uid":"78f8699c-a199-4dde-8be3-79fb887a596d","title":"相和歌辞 门有车马客行","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["门有车马客，金鞍曜朱轮。","谓从丹霄落，乃是故乡亲。","呼儿埽中堂，坐客论悲辛。","对酒两不饮，停觞泪盈巾。","叹我万里游，飘飖三十春。","空谈霸王略，紫绶不挂身。","雄劒藏玉匣，阴符生素尘。","廓落无所合，流离湘水滨。","借问宗党间，多为泉下人。","生苦百战役，死托万鬼邻。","北风扬胡沙，埋翳周与秦。","大运且如此，苍穹宁匪仁。","恻怆竟何道？存亡任大钧。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"豪放","style2":["绮丽","冲淡"],"mood":"悲怆","mood2":["愁怨"],"scene":["酒"],"cats":{"抒情":["思乡","伤感","悼亡"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.438},{"uid":"db149aaa-c52b-4893-8b6b-7047bd84b92f","title":"石龛","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["熊罴哮我东，虎豹号我西。","我后鬼长啸，我前狨又啼。","天寒昏无日，山远道路迷。","驱车石龛下，仲冬见虹蜺。","伐竹者谁子，悲歌上云梯。","为官采美箭，五岁供梁齐。","苦云直簳尽，无以充提携。","奈何渔阳骑，飒飒惊烝黎。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":[],"mood":"悲怆","mood2":["惆怅"],"scene":["冬"],"cats":{"抒情":["伤感"],"四季":["冬天"]},"theme_conf":1.0},{"uid":"7e57dc35-56b8-4e3d-ab51-25d6c4bd1fab","title":"逢故人","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["故交相见稀，相见倍依依。","尘路事不尽，云岩闲好归。","投人销壮志，徇俗变真机。","又落他乡泪，风前一满衣。"],"theme":"羁旅思乡","theme2":["送别","闲适隐逸"],"style":"婉约","style2":["沉郁"],"mood":"慷慨","mood2":["恬淡","愁怨"],"scene":["山"],"cats":{"抒情":["友情","思乡","伤感"],"人生":["励志","梦想"]},"theme_conf":0.388},{"uid":"d43a4767-2240-44b7-8d5b-c2acdc689839","title":"黄鹤楼送孟浩然之广陵","author":"李白","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["故人西辞黄鹤楼，烟花三月下扬州。","孤帆远影碧山尽，唯见长江天际流。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["楼","江"],"cats":{"抒情":["友情","孤独"],"山水":["长江"],"动物":["写鸟"]},"theme_conf":0.73},{"uid":"0cf6265f-c453-4bc5-9f3f-55a6ab43a83a","title":"杂曲歌辞 少年行三首 二","author":"李嶷","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["侍猎长杨下，承恩更射飞。","尘生马影灭，箭落鴈行稀。","薄暮归随仗，联翩入琐闱。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"人生":["青春"]},"theme_conf":1.0},{"uid":"13619ace-57d2-4444-ac03-15481045fff6","title":"淇上酬薛三据兼寄郭少府微","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["自从别京华，我心乃萧索。","十年守章句，万事空寥落。","北上登蓟门，茫茫见沙漠。","倚劒对风尘，慨然思卫霍。","拂衣去燕赵，驱马怅不乐。","天长沧洲路，日暮邯郸郭。","酒肆或淹留，渔潭屡栖泊。","独行备艰险，所见穷善恶。","永愿拯刍荛，孰云干鼎镬。","皇情念淳古，时俗何浮薄。","理道资任贤，安人在求瘼。","故交负灵奇，逸气抱謇谔。","隐轸经济具，纵横建安作。","才望忽先鸣，风期无宿诺。","飘飖劳州县，迢递限言谑。","东驰眇贝丘，西顾弥虢略。","淇水徒自流，浮云不堪托。","吾谋适可用，天路岂寥廓。","不然买山田，一身与耕凿。","且欲同鹪鹩，焉能志鸿鹄。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":["豪放","幽峭"],"mood":"孤寂","mood2":["恬淡","相思"],"scene":["塞外","酒"],"cats":{"抒情":["孤独"],"人生":["梦想"]},"theme_conf":0.98},{"uid":"bc532435-aea1-41b7-b74f-f30dc115f154","title":"宫词一百首 八十一","author":"王建","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["宿妆残粉未明天，总立昭阳花树边。","寒食内人长白打，库中先散与金钱。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["清明"],"cats":{"抒情":["闺怨"],"节日":["寒食节","清明节"]},"theme_conf":0.795},{"uid":"4c57a579-0494-41cf-a174-6472ac4f2e8e","title":"游桃源一百韵","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["沅江清悠悠，连山郁岑寂。","回流抱绝𪩘，皎镜含虚碧。","昏旦递明媚，烟岚分委积。","香蔓垂绿潭，暴龙照孤碛。","渊明著前志，子骥思远跖。","寂寂无何乡，密尔天地隔。","金行太元岁，渔者偶探赜。","寻花得幽踪，窥洞穿暗隙。","依微闻鸡犬，豁达值阡陌。","居人互将迎，笑语如平昔。","广乐虽交奏，海禽心不怿。","挥手一来归，故溪无处觅。","绵绵五百载，市朝几迁革。","有路在壶中，无人知地脉。","皇家感至道，圣祚自天锡。","金阙传本枝，玉函留宝历。","禁山开秘宇，复户洁灵宅。","蘂检香氛氲，醮坛烟幂幂。","我来尘外躅，莹若朝星析。","崖转对翠屏，水穷留画鹢。","三休俯乔木，千级扳峭壁。","旭日闻撞钟，彩云迎蹑屐。","遂登最高顶，纵目还楚泽。","平湖见草青，远岸连霞赤。","幽寻如梦想，绵思属空阒。","夤缘且忘疲，耽玩近成癖。","清猨伺晓发，瑶草凌寒坼。","祥禽舞葱茏，珠树摇玓𬍛。","羽人顾我笑，劝我税归轭。","霓裳何飘飖，童颜洁白皙。","重岩是藩屏，驯鹿受羁靮。","楼居弥清霄，萝茑成翠帟。","仙翁遗竹杖，王母留桃核。","姹女飞丹砂，青童护金液。","宝气浮鼎耳，神光生劒脊。","虚无天乐来，僁窣鬼兵役。","丹丘肃朝礼，玉札工䌷绎。","枕中淮南方，床下阜乡舄。","明灯坐遥夜，幽籁听淅沥。","因话近世仙，耸然心神惕。","乃言瞿氏子，骨状非凡格。","往事黄先生，群儿多侮剧。","謷然不屑意，元气贮肝膈。","往往游不归，洞中观博弈。","言高未易信，犹复加诃责。","一旦前致辞，自云仙期迫。","言师有道骨，前事常被谪。","如今三山上，名字在真籍。","悠然谢主人，后岁当来觌。","言毕依庭树，如烟去无迹。","观者皆失次，惊追纷络绎。","日暮山径穷，松风自萧槭。","适逢修蛇见，瞋目光激射。","如严三清居，不使恣搜索。","唯余步纲势，八趾在沙砾。","至今东北隅，表以坛上石。","列仙徒有名，世人非目击。","如何庭庑际，白日振飞翮。","洞天岂幽远，得道如咫尺。","一气无死生，三光自迁易。","因思人间世，前路何狭窄。","瞥然此生中，善祝期满百。","大方播群类，秀气肖翕辟。","性静本同和，物牵成阻厄。","是非鬬方寸，荤血昏精魄。","遂令多夭伤，犹喜见斑白。","喧喧车马驰，苒苒桑榆夕。","共安缇绣荣，不悟泥途适。","纷吾本孤贱，世业在逢掖。","九流宗指归，百氏旁捃摭。","公卿偶慰荐，乡曲缪推择。","居安白社贫，至傲玄𫄸辟。","功名希自取，簪组俟扬历。","书府蚤怀铅，射宫曾发的。","起草香生帐，坐曹乌集柏。","赐燕聆箫韶，侍祠阅琮璧。","尝闻履忠信，可以行蛮貊。","自述希古心，忘恃干时画。","巧言忽成锦，苦志徒食蘗。","平地生峰峦，深心有矛戟。","层波一震荡，弱植忽沦溺。","北渚吊灵均，长岑思亭伯。","祸来昧几兆，事去空叹息。","尘累与时深，流年随漏滴。","才能疑木鴈，报施迷夷跖。","楚奏絷钟仪，商歌劳宁戚。","禀生非悬解，对镜方感激。","自从婴网罗，每事问龟策。","王正降雷雨，环玦赐迁斥。","倘伏夷平人，誓将依羽客。","买山构精舍，领徒开讲席。","冀无身外忧，自有闲中益。","道芽期日就，尘虑乃冰释。","且欲遗姓名，安能慕竹帛。","长生尚学致，一溉岂虚掷。","芝术资糇粮，烟霞拂巾帻。","黄石履看堕，洪崖肩可拍。","聊复嗟蜉蝣，何烦哀虺蜴。","青囊既深味，琼葩亦屡摘。","纵无西山资，犹免长戚戚。"],"theme":"游仙梦幻","theme2":["羁旅思乡"],"style":"绮丽","style2":["幽峭","冲淡"],"mood":"孤寂","mood2":["恬淡","欢愉"],"scene":["山","江","夜"],"cats":{"抒情":["思乡","孤独"],"天气":["写云","太阳"],"人物":["老师"],"人生":["时光","战争"],"植物":["桃花"]},"theme_conf":0.87},{"uid":"40c2882a-7e79-4915-a77a-95acb7cc4715","title":"在郡秋怀二首 一","author":"张九龄","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["秋风入前林，萧瑟鸣高枝。","寂寞游子思，寤叹何人知。","宦成名不立，志存岁已驰。","五十而无闻，古人深所疵。","平生去外饰，直道如不羁。","未得操割效，忽复寒暑移。","物情自古然，身退毁亦随。","悠悠沧江渚，望望白云涯。","露下霜且降，泽中草离披。","兰艾若不分，安用馨香为。"],"theme":"亲情","theme2":["羁旅思乡"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["相思"],"scene":["秋"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"人生":["励志"]},"theme_conf":0.519},{"uid":"92f88db8-3548-4e2e-87f7-aa0aac87af2c","title":"汴河怀古二首 二","author":"皮日休","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["尽道隋亡为此河，至今千里赖通波。","若无水殿龙舟事，共禹论功不较多。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"惆怅","mood2":[],"scene":["端午","舟"],"cats":{"抒情":["怀古"],"山水":["江河"],"节日":["端午节"]},"theme_conf":1.0},{"uid":"7f4d2f20-a7ac-4310-b2d5-3fb079011272","title":"郊庙歌辞 晋朝飨乐章 群臣酒行歌 二","author":"不详","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["万国咸归禹，千官共祝尧。","拜恩瞻凤扆，倾耳听云韶。","运启金行远，时和玉烛调。","酒酣齐抃舞，同贺圣明朝。"],"theme":"羁旅思乡","theme2":["闲适隐逸"],"style":"豪放","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["酒"],"cats":{"抒情":["思乡"],"食物":["写酒"]},"theme_conf":0.519},{"uid":"cp8c89ce7125f188","title":"薄幸","author":"贺铸","dynasty":"宋","section":"宋词","form":"词","paragraphs":["艳真多态。","更的的，频回眄睐。","便认得、琴心相许，与写宜男双带。","记画堂、斜月朦胧，轻颦微笑娇无奈。","便翡翠屏开，芙蓉帐掩，与把香罗偷解。","自过了收灯后，都不见、踏青挑菜。","几回凭双燕，丁宁深意，往来翻恨重帘碍。","约何时再。","正春浓酒暖，人闲昼永无聊赖。","厌厌睡起，犹有花梢日在。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["清明","夜","花","春","酒","月"],"cats":{"抒情":["伤感"],"四季":["春天"],"节日":["清明节"]},"theme_conf":0.96},{"uid":"03b8aaf4-9827-470b-ab77-9666b6e11f4c","title":"送归中丞使新罗","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["诏使殊方远，朝仪旧典行。","浮天无尽处，望日计前程。","暂喜孤山出，长愁积水平。","野风飘叠鼓，海雨湿危旌。","异俗知文教，通儒有令名。","还将大戴礼，方外授诸生。"],"theme":"送别","theme2":["应制干谒"],"style":"沉郁","style2":["绮丽","豪放"],"mood":"愁怨","mood2":["欢愉","孤寂"],"scene":["雨","山"],"cats":{"抒情":["伤感","孤独"],"山水":["西湖"]},"theme_conf":0.579},{"uid":"368fc6bb-1636-419e-8ddb-cdc1dd07a1ca","title":"新年作","author":"宋之问","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["乡心新岁切，天畔独澘然。","老至居人下，春归在客先。","岭猨同旦暮，江柳共风烟。","已似长沙傅，从今又几年。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["除夕"],"cats":{"抒情":["思乡","孤独"],"节日":["春节"]},"theme_conf":0.698},{"uid":"35927911-8c33-4e84-98eb-73578b5137ad","title":"祭社宵兴灯前偶作","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["城头传鼓角，灯下整衣冠。","夜镜藏须白，秋泉漱齿寒。","欲将闲送老，须著病辞官。","更待年终后，支持归计看。"],"theme":"闲适隐逸","theme2":["咏史怀古","边塞征战","闲适隐逸"],"style":"沉郁","style2":[],"mood":"欢愉","mood2":["恬淡"],"scene":["夜"],"cats":{"抒情":["怀古"],"节日":["元宵节"]},"theme_conf":0.7},{"uid":"a9b677e8-2657-4d20-9572-1a7479846124","title":"送女子","author":"刘商","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["青娥宛宛聚为裳，乌鹊桥成别恨长。","惆怅梧桐非旧影，不悲鸿鴈暂随阳。"],"theme":"送别","theme2":[],"style":"悲慨","style2":["沉郁"],"mood":"惆怅","mood2":["悲怆","愁怨"],"scene":["七夕"],"cats":{"抒情":["伤感"],"人物":["女子"],"生活":["写桥"],"节日":["七夕节"]},"theme_conf":1.0},{"uid":"aeb383ee-1d05-4d4c-a662-dcb83fb07284","title":"折菊","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["篱东菊径深，折得自孤吟。","雨中衣半湿，拥鼻自知心。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"抒情":["孤独"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"f0e9fe34-bbb9-4763-be64-4d7ea74b65ec","title":"省中春暮酬嵩阳焦道士见招","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["朝花飞暝林，对酒伤春心。","流年催素发，不觉映华簪。","垂老遇知己，酬恩看寸阴。","如何紫芝客，相忆白云深。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["友情","思念"],"四季":["春天"],"人生":["时光"]},"theme_conf":0.92},{"uid":"2e32f511-cc12-47dd-9c32-b3ca629c807f","title":"九日五首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["旧日重阳日，传杯不放杯。","即今蓬鬓改，但媿菊花开。","北阙心长恋，西江首独回。","茱萸赐朝士，难得一枝来。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"抒情":["孤独"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.73},{"uid":"2247b3d2-8476-4f8a-be6e-d3f8276751d3","title":"忆杭州梅花因叙旧游寄萧协律","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["三年闲闷在余杭，曾为梅花醉几场。","伍相庙边繁似雪，孤山园里丽如妆。","蹋随游骑心长惜，折赠佳人手亦香。","赏自初开直至落，欢因小饮便成狂。","薛刘相次埋新垅，沈谢双飞出故乡。","歌伴酒徒零散尽，唯残头白老萧郎。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["沉郁"],"mood":"欢愉","mood2":["相思","孤寂"],"scene":["花","冬","酒"],"cats":{"抒情":["思念","思乡","孤独"],"山水":["西湖"],"人物":["女子"],"植物":["梅花"]},"theme_conf":0.9},{"uid":"b4f19aab-ff6a-40e2-b499-e43a45f7515c","title":"相和歌辞 子夜四时歌六首 春歌二首 一","author":"郭元振","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["青楼含日光，绿池起风色。","赠子同心花，殷勤此何极。"],"theme":"爱情相思","theme2":["爱情相思"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春","夜"],"cats":{"抒情":["爱情"],"四季":["春天"]},"theme_conf":0.95},{"uid":"cp49b50543fc106f","title":"兰陵王","author":"刘辰翁","dynasty":"宋","section":"宋词","form":"词","paragraphs":["送春去。","春去人间无路。","秋千外、芳草连天，谁遣风沙暗南浦。","依依甚意绪。","漫忆海门飞絮。","乱鸦过，斗转城荒，不见来时试灯处。","春去。","最谁苦。","但箭雁沉边，梁燕无主。","杜鹃声里长门暮。","想玉树凋土，泪盘如露。","咸阳送客屡回顾。","斜日未能度。","春去。","尚来否。","正江令恨别，庾信愁赋。","苏堤尽日风和雨。","叹神游故国，花记前度。","人生流落，顾孺子，共夜雨。"],"theme":"送别","theme2":["咏史怀古"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["鸟"],"cats":{"抒情":["离别","思念","伤感","闺怨","怀古"],"山水":["西湖"]},"theme_conf":0.452},{"uid":"22e72306-f41c-4621-a925-83bab7f9d76e","title":"怨情","author":"李白","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["美人卷珠帘，深坐颦蛾眉。","但见泪痕湿，不知心恨谁。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["伤感","闺怨"],"人物":["女子"]},"theme_conf":1.0},{"uid":"2656cc2f-8178-477d-88b4-13bb0d73a634","title":"崔司录宅燕大理李卿","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["多雨殊未已，秋云更沈沈。","洛阳故人初解印，山东小吏来相寻。","上卿才大名不朽，早朝至尊暮求友。","豁达常推海内贤，殷勤但酌尊中酒。","饮醉欲言归剡溪，门前驷马光照衣。","路傍观者徒唧唧，我公不以为是非。"],"theme":"寄赠酬答","theme2":["山水田园","应制干谒"],"style":"豪放","style2":["清新"],"mood":"恬淡","mood2":[],"scene":["酒"],"cats":{"抒情":["友情"],"动物":["写鸟"]},"theme_conf":0.68},{"uid":"1a3d6317-14e6-4974-85bf-696d58458a5e","title":"送严员外","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["春风倚櫂阖闾城，水国春寒阴复晴。","细雨湿衣看不见，闲花落地听无声。","日斜江上孤帆影，草绿湖南万里情。","君去若逢相识问，青袍今已误儒生。"],"theme":"送别","theme2":[],"style":"婉约","style2":["清新","豪放"],"mood":"孤寂","mood2":["恬淡"],"scene":["雨"],"cats":{"抒情":["孤独"],"天气":["写雨"]},"theme_conf":0.649},{"uid":"70cfbaa0-6ea5-4a6a-a6ac-0e8bbfd8413c","title":"贻华阳柳少府","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["系马乔木间，问人野寺门。","柳侯披衣笑，见我颜色温。","竝坐石下堂，俛视大江奔。","火云洗月露，绝壁上朝暾。","自非晓相访，触热生病根。","南方六七月，出入异中原。","老少多暍死，汗逾水浆飜。","俊才得之子，筋力不辞烦。","指挥当世事，语及戎马存。","涕泪溅我裳，悲气排帝阍。","郁陶抱长策，义仗知者论。","吾衰卧江汉，但媿识玙璠。","文章一小技，于道未为尊。","起予幸斑白，因是托子孙。","俱客古信州，结庐依毁垣。","相去四五里，径微山叶繁。","时危挹佳士，况免军旅喧。","醉从赵女舞，歌鼓秦人盆。","子壮顾我伤，我驩兼泪痕。","余生如过鸟，故里今空邨。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["婉约"],"mood":"悲怆","mood2":["慷慨"],"scene":["月"],"cats":{"抒情":["思乡","伤感"],"山水":["长江"],"植物":["柳树"]},"theme_conf":0.708},{"uid":"cf854c36-62d7-4c54-ad3f-258cfedbb14a","title":"题郑十八著作虔","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["台州地阔海冥冥，云水长和岛屿青。","乱后故人双别泪，春深逐客一浮萍。","酒酣嬾舞谁相拽，诗罢能吟不复听。","第五桥东流恨水，皇陂岸北结愁亭。","贾生对𫛳伤王傅，苏武看羊陷贼庭。","可念此翁怀直道，也沾新国用轻刑。","祢衡实恐遭江夏，方朔虚传是岁星。","穷巷悄然车马绝，案头干死读书萤。"],"theme":"送别","theme2":["咏物"],"style":"沉郁","style2":["豪放","婉约"],"mood":"愁怨","mood2":[],"scene":["楼","夏","春","酒"],"cats":{"抒情":["友情","伤感"],"四季":["春天","夏天"],"人生":["读书"],"生活":["写桥"]},"theme_conf":0.53},{"uid":"da42362f-b22f-4ca6-a18e-69284623c195","title":"横吹曲辞 关山月","author":"长孙佐辅","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["凄凄还切切，戍客多离别。","何处最伤心？关山见秋月。","关月竟如何？由来远近过。","始经玄兔塞，终绕白狼河。","忽忆秦楼妇，流光应共有。","已得竝蛾眉，还知揽纤手。","去岁照同行，比翼复连形。","今宵照独立，顾影自茕茕。","余晖渐西落，夜夜看如昨。","借问映旌旗，何如鉴帷幕。","拂晓朔风悲，蓬惊雁不飞。","几时征戍罢，还向月中归。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"悲怆","mood2":["愁怨","孤寂"],"scene":["塞外","月","山"],"cats":{"抒情":["离别","思乡","伤感","孤独"],"天气":["写风","月亮"],"生活":["边塞"]},"theme_conf":0.403},{"uid":"cp99f30691ef4ed8","title":"汉宫春","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["春已归来，看美人头上，袅袅春幡。","无端风雨，未肯收尽馀寒。","年时燕子，料今宵、梦到西园。","浑未办、黄柑荐酒，更传青韭堆盘。","却笑东风从此，便薰梅染柳，更没些闲。","闲时又来镜里，转变朱颜。","清愁不断，问何人、会解连环。","生怕见、花开花落，朝来塞雁先还。"],"theme":"节令风俗","theme2":["闲适隐逸","边塞征战"],"style":"清新","style2":[],"mood":"愁怨","mood2":["恬淡","欢愉"],"scene":["春"],"cats":{"抒情":["伤感"],"四季":["春天"],"人物":["女子"],"生活":["边塞"]},"theme_conf":0.85},{"uid":"410b6c68-3226-47ea-a83c-c93f648d5213","title":"安平公诗","author":"李商隐","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["丈人博陵王名家，怜我总角称才华。","华州留语晓至暮，高声喝吏放两衙。","明朝骑马出城外，送我习业南山阿。","仲子延岳年十六，面如白玉欹乌纱。","其弟炳章犹两丱，瑶林琼树含奇花。","陈留阮家诸侄秀，逦迤出拜何骈罗。","府中从事杜与李，麟角虎翅相过摩。","清词孤韵有歌响，击触钟磬鸣环珂。","三月石堤冻销释，东风开花满阳坡。","时禽得伴戏新木，其声尖咽如鸣梭。","公时载酒领从事，踊跃鞍马来相过。","仰看楼殿撮清汉，坐视世界如恒沙。","面热脚掉互登陟，青云表柱白云崖。","一百八句在贝叶，三十三天长雨花。","长者子来辄献盖，辟支佛去空留𫖇。","公时受诏镇东鲁，遣我草诏随车牙。","顾我下笔即千字，疑我读书倾五车。","呜嘑大贤苦不寿，时世方士无灵砂。","五月至止六月病，遽颓泰山惊逝波。","明年徒步吊京国，宅破子毁哀如何。","西风冲户卷素帐，隟光斜照旧燕窠。","古人常叹知己少，况我沦贱艰虞多。","如公之德世一二，岂得无泪如黄河。","沥胆咒愿天有眼，君子之泽方滂沱。"],"theme":"送别","theme2":["悼亡挽歌","民生疾苦"],"style":"沉郁","style2":["清新"],"mood":"孤寂","mood2":["愁怨","恬淡"],"scene":["山","江"],"cats":{"抒情":["友情","伤感","孤独","悼亡"],"山水":["泰山","黄河"],"天气":["写风"],"人生":["读书"]},"theme_conf":0.431},{"uid":"f5c7c474-4fff-4fec-9f4a-d8e2d1447a77","title":"送翰林张司马南海勒碑","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["冠冕通南极，文章落上台。","诏从三殿去，碑到百蛮开。","野馆浓花发，春帆细雨来。","不知沧海上，天遣几时回。"],"theme":"送别","theme2":["咏史怀古"],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["雨"],"cats":{"抒情":["怀古"],"天气":["写雨"],"动物":["写马"]},"theme_conf":0.509},{"uid":"50c438e3-3f13-4895-9f90-c59ce043671d","title":"过终南柳处士","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["五老正相寻，围棋到煮金。","石摧丹井闭，月过洞门深。","猨鸟三时下，藤萝十里阴。","绿泉多草气，青壁少花林。","自愧非仙侣，何言见道心。","悠哉宿山口，雷雨夜沈沈。"],"theme":"山水田园","theme2":["咏史怀古","闲适隐逸"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["月","雨","夜","山"],"cats":{"抒情":["怀古"],"植物":["柳树"]},"theme_conf":0.401},{"uid":"ba17fece-e517-4da1-8ff2-f42bf2bacb18","title":"莲叶","author":"郑谷","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["移舟水溅差差绿，倚槛风摇柄柄香。","多谢浣溪人不折，雨中留得盖鸳鸯。"],"theme":"咏物","theme2":["山水田园","爱情相思"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["舟","雨"],"cats":{"抒情":["爱情"],"植物":["荷花","叶子"]},"theme_conf":0.427},{"uid":"cpe47cfbafe8fffc","title":"月照梨花・河传","author":"陆游","dynasty":"宋","section":"宋词","form":"词","paragraphs":["闷已萦损。","那堪多病。","几曲屏山，伴人昼静。","梁燕催起犹慵。","换熏龙。","新愁旧恨何时尽。","渐凋绿鬓。","小雨知花信。","芳笺寄与何处，绣阁珠栊。","柳阴中。"],"theme":"闺情宫怨","theme2":["送别"],"style":"沉郁","style2":["清新","绮丽"],"mood":"愁怨","mood2":[],"scene":["花","月"],"cats":{"抒情":["伤感","闺怨"],"天气":["月亮"],"植物":["梨花"]},"theme_conf":0.556},{"uid":"c1280e87-ac81-4f9b-9de5-377d6af38ae8","title":"月夜忆舍弟","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["戍鼓断人行，秋边一雁声。","露从今夜白，月是故乡明。","有弟皆分散，无家问死生。","寄书长不避，况乃未休兵。"],"theme":"亲情","theme2":["边塞征战","送别"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["夜","月","秋"],"cats":{"抒情":["思念","思乡"],"四季":["秋天"],"天气":["月亮"]},"theme_conf":0.9},{"uid":"818ab313-009a-4bca-829a-30768146e907","title":"杂曲歌辞 结客少年场行","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["紫燕黄金瞳，啾啾摇绿鬉。","平明相驰逐，结客洛门东。","少年学劒术，凌轹白猨公。","珠袍曳锦带，七首插吴鸿。","由来万夫勇，挟此生雄风。","托交从剧孟，买醉入新丰。","笑尽一杯酒，杀人都市中。","羞道易水寒，从令日贯虹。","燕丹事不立，虚没秦帝宫。","舞阳死灰人，安可与成功。"],"theme":"羁旅思乡","theme2":[],"style":"豪放","style2":["绮丽","清新"],"mood":"欢愉","mood2":["悲怆"],"scene":["酒"],"cats":{"抒情":["思乡"],"人生":["青春"]},"theme_conf":1.0},{"uid":"c4a21fba-29eb-4fe6-a426-05ef19f72c13","title":"杂感","author":"鲍防","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["汉家海内承平久，万国戎王皆稽首。","天马常衔苜蓿花，胡人岁献葡萄酒。","五月荔枝初破颜，朝离象郡夕函关。","鴈飞不到桂阳岭，马走先过林邑山。","甘泉御果垂仙阁，日暮无人香自落。","远物皆重近皆轻，鸡虽有德不如鹤。"],"theme":"山水田园","theme2":["边塞征战"],"style":"婉约","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":["山","月","花","酒"],"cats":{"抒情":["孤独"],"食物":["荔枝"]},"theme_conf":0.571},{"uid":"4a648ac2-fe66-438d-b082-2da34f651fe6","title":"晚到盩厔耆老家","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["老翁曾旧识，相引出柴门。","苦话别时事，因寻溪上村。","数年何处客，近日几家存。","冒雨看禾黍，逢人忆子孙。","乱藤穿井口，流水到篱根。","惆怅不堪住，空山月又昏。"],"theme":"山水田园","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":["相思"],"scene":["雨","月","山"],"cats":{"抒情":["思念"],"生活":["乡村"]},"theme_conf":0.615},{"uid":"b0a1ab7c-8206-4c5c-b333-d5410c429a19","title":"徐卿二子歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见徐卿二子生绝奇，感应吉梦相追随。","孔子释氏亲抱送，竝是天上麒麟儿。","大儿九龄色清澈，秋水为神玉为骨。","小儿五岁气食牛，满堂宾客皆回头。","吾知徐公百不忧，积善衮衮生公侯。","丈夫生儿有如此二雏者，名位岂肯悲微休。"],"theme":"送别","theme2":["羁旅思乡"],"style":"豪放","style2":["悲慨"],"mood":"慷慨","mood2":["相思","悲怆"],"scene":["秋"],"cats":{"抒情":["思念","思乡","伤感"],"四季":["秋天"],"人物":["儿童"]},"theme_conf":0.617},{"uid":"359bc72a-6f60-4c69-a4cd-9d579e22fc8e","title":"苦雪四首 四","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["孰云久闲旷，本自保知寡。","穷巷独无成，春条秪盈把。","安能羡鹏举，且欲歌牛下。","乃知古时人，亦有如我者。"],"theme":"民生疾苦","theme2":["闲适隐逸"],"style":"沉郁","style2":[],"mood":"恬淡","mood2":["愁怨","孤寂"],"scene":["雪"],"cats":{"抒情":["孤独"],"天气":["写雪"]},"theme_conf":0.608},{"uid":"e1fea3c2-af73-4b77-8cd1-ebf233140999","title":"从驿次草堂复至东屯二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["短景难高卧，衰年强此身。","山家蒸栗暖，野饭射麋新。","世路知交薄，门庭畏客频。","牧童斯在眼，田父实为邻。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["山","园林"],"cats":{"抒情":["思乡"],"人物":["儿童"]},"theme_conf":1.0},{"uid":"018cab44-8167-40eb-8934-09667eb405da","title":"挽辞 一","author":"后主煜","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["珠碎眼前珍，花凋世外春。","未销心里恨，又失掌中身。","玉笥犹残药，香匳已染尘。","前哀将后感，无泪可沾巾。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":["绮丽","婉约"],"mood":"愁怨","mood2":[],"scene":["花","春"],"cats":{"抒情":["伤感","悼亡"],"四季":["春天"]},"theme_conf":0.99},{"uid":"4e01deae-f2e1-403a-a615-97aaf7e78738","title":"鼓吹曲辞 战城南二首 一","author":"僧贯休","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["万里桑干傍，茫茫古蕃壤。","将军貌顦顇，抚劒悲年长。","胡兵尚陵逼，久住亦非强。","邯郸少年辈，个个有伎俩。","拖枪半夜去，雪片大如掌。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["雪","夜"],"cats":{"抒情":["伤感"],"人生":["战争"]},"theme_conf":1.0},{"uid":"930a9bfb-ee77-4806-b03c-7bf63a9b070e","title":"宋州东登望题武陵驿","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["梁宋人稀鸟自啼，登舻一望倍含凄。","白骨半随河水去，黄云犹傍郡城低。","平陂战地花空落，旧苑春田草未齐。","明主频移虎符守，几时行县向黔黎。"],"theme":"咏史怀古","theme2":["羁旅思乡","咏物"],"style":"悲慨","style2":[],"mood":"相思","mood2":["悲怆","愁怨"],"scene":["春"],"cats":{"抒情":["思乡","怀古"],"四季":["春天"],"人生":["战争"],"植物":["桃花"]},"theme_conf":0.377},{"uid":"7b501b42-fe79-4c87-97bc-7ff610629698","title":"竹窗闻风寄苗发司空曙","author":"李益","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["微风惊暮坐，临牖思悠哉。","开门复动竹，疑是故人来。","时滴枝上露，稍沾堦下苔。","何当一入幌，为拂绿琴埃。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"清新","style2":["冲淡"],"mood":"相思","mood2":["孤寂"],"scene":[],"cats":{"抒情":["友情"],"天气":["写风"],"植物":["竹子"]},"theme_conf":0.91},{"uid":"c0c804f0-03cb-4610-a809-f413608ac25e","title":"送何兆下第还蜀","author":"李端","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["重江不可涉，孤客莫晨装。","高木莎城小，残星栈道长。","褭猿枫子落，过雨荔枝香。","劝尔成都住，文翁有草堂。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["雨","江"],"cats":{"抒情":["孤独"],"食物":["荔枝"]},"theme_conf":1.0},{"uid":"0710a746-8660-4bc1-b073-8ce51ac9f4d9","title":"梦李白二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["浮云终日行，游子久不至。","三夜频梦君，情亲见君意。","告归常局促，苦道来不易。","江湖多风波，舟楫恐失坠。","出门搔白首，若负平生志。","冠盖满京华，斯人独顦顇。","孰云网恢恢，将老身反累。","千秋万岁名，寂莫身后事。"],"theme":"寄赠酬答","theme2":["民生疾苦","送别"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["相思"],"scene":["江","舟","秋","夜"],"cats":{"抒情":["思念","孤独"],"四季":["秋天"],"人生":["梦想"]},"theme_conf":0.75},{"uid":"3e971330-6463-4711-83aa-1d0da96589e1","title":"王夫子","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["王夫子，送君为一尉，东南三千五百里。","道途虽远位虽卑，月俸犹堪活妻子。","男儿口读古人书，束带敛手来从事。","近将徇禄给一家，远则行道佐时理。","行道佐时须待命，委身下位无为耻。","命苟未来且求食，官无卑高及远迩。","男儿上既未能济天下，下又不至饥寒死。","吾观九品至一品，其间气味都相似。","紫绶朱绂青布衫，颜色不同而已矣。","王夫子，别有一事欲劝君，遇酒逢春且欢喜。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":["惆怅"],"scene":["酒","春"],"cats":{"抒情":["离别"],"四季":["春天"],"人物":["老师"]},"theme_conf":0.749},{"uid":"66e31443-c3ec-4c2a-8c39-bdb2d589aa29","title":"寄李十员外","author":"王仲舒","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["百丈悬泉旧卧龙，欲将肝胆佐时雍。","惟愁又入烟霞去，知在庐峰第几重。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["山"],"cats":{"抒情":["伤感"],"山水":["瀑布"]},"theme_conf":0.95},{"uid":"57ea34b3-5fb6-46b0-8686-c55fa62fdf55","title":"相和歌辞 祠神歌 送神","author":"王叡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["枨枨山响荅琵琶，酒湿青莎肉饲鵶。","树叶无声神去后，纸钱灰出木绵花。"],"theme":"送别","theme2":["咏史怀古"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["清明","酒","山"],"cats":{"抒情":["怀古"],"节日":["清明节"]},"theme_conf":0.456},{"uid":"0d07875d-bf3e-4a2e-9139-ba767079c8ad","title":"八哀诗 故秘书少监武功苏公源明","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["武功少也孤，徒步客徐衮。","读书东岳中，十载考坟典。","时下莱芜郭，忍饥浮云𪩘。","负米晚为身，每食脸必泫。","夜字照𦶟薪，垢衣生碧藓。","庶以勤苦志，报兹劬劳显。","学蔚醇儒姿，文包旧史善。","洒落辞幽人，归来潜京辇。","射君东堂策，宗匠集精选。","制可题未干，乙科已大阐。","文章日自负，吏禄亦累践。","晨趋阊阖内，足蹋宿昔趼。","一麾出守还，黄屋朔风卷。","不暇陪八骏，虏庭悲所遣。","平生满尊酒，断此朋知展。","忧愤病二秋，有恨石可转。","肃宗复社稷，得无逆顺辨。","范晔顾其儿，李斯忆黄犬。","秘书茂松意，溟涨本末浅。","青荧芙蓉劒，犀兕岂独剸。","反为后辈亵，予实苦怀缅。","煌煌斋房芝，事绝万手搴。","垂之俟来者，正始征劝勉。","不要悬黄金，胡为投乳贙。","结交三十载，吾与谁游衍。","荥阳复冥莫，罪罟已横罥。","呜呼子逝日，始泰则终蹇。","长安米万钱，凋丧尽余喘。","战伐何当解，归帆阻清沔。","尚缠漳水疾，永负蒿里饯。"],"theme":"悼亡挽歌","theme2":[],"style":"悲慨","style2":["沉郁"],"mood":"悲怆","mood2":["愁怨","孤寂"],"scene":[],"cats":{"抒情":["伤感","孤独","悼亡"],"天气":["写风"],"人生":["读书"]},"theme_conf":0.99},{"uid":"7ea69c75-5aa8-47f9-980d-b65d7cdb01ee","title":"被谪连州","author":"卢肇","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["黄绢外孙翻得罪，华颠故老莫相嗤。","连州万里无亲戚，旧识唯应有荔枝。"],"theme":"羁旅思乡","theme2":[],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"食物":["荔枝"]},"theme_conf":0.72},{"uid":"108dcb9b-73b4-4157-9269-32514cd5dc3e","title":"途中酬李少府赠别之作","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["西上逢节换，东征私自怜。","故人今卧疾，欲别还留连。","举酒临南轩，夕阳满中筵。","宁知江上兴，乃在河梁偏。","行李多光辉，札翰忽相鲜。","谁谓岁月晚，交情尚贞坚。","终嗟州县劳，官谤复迍邅。","虽负忠信美，其如方寸悬。","连帅扇清风，千里犹眼前。","曾是趋藻镜，不应翻弃捐。","日来知自强，风气殊未痊。","可以加药物，胡为輙忧煎。","驱马出大梁，原野一悠然。","柳色感行客，云阴愁远天。","皇明烛幽遐，德泽普照宣。","鹓鸿列霄汉，燕雀何翩翩。","余亦惬所从，渔樵十二年。","种瓜漆园里，凿井卢门边。","去去勿重陈，生涯难勉旃。","或期遇春事，与尔复周旋。","投报空回首，狂歌谢比肩。"],"theme":"送别","theme2":[],"style":"豪放","style2":["冲淡","清新"],"mood":"愁怨","mood2":[],"scene":["酒","春"],"cats":{"抒情":["友情","离别","伤感"],"四季":["春天"]},"theme_conf":0.679},{"uid":"3d26433c-a673-4094-8c83-cadb1b08412a","title":"登柳州城楼寄漳汀封连四州","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["城上高楼接大荒，海天愁思正茫茫。","惊风乱飐芙蓉水，密雨斜侵薜荔墙。","岭树重遮千里目，江流曲似九廻肠。","共来百越文身地，犹自音书滞一乡。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["楼","江"],"cats":{"抒情":["伤感"],"山水":["江河"],"植物":["柳树"]},"theme_conf":0.92},{"uid":"d40a3095-f2e8-4ee3-9f18-b8dba56e4131","title":"赠比部萧郎中十兄","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["有美生人杰，由来积德门。","汉朝丞相系，梁日帝王孙。","蕴藉为郎久，魁梧秉哲尊。","词华倾后辈，风雅蔼孤骞。","宅相荣姻戚，儿童惠讨论。","见知真自幼，谋拙丑诸昆。","漂荡云天阔，沈埋日月奔。","致君时已晚，怀古意空存。","中散山阳锻，愚公野谷村。","宁纡长者辙，归老任乾坤。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["月"],"cats":{"抒情":["孤独","怀古"],"人物":["儿童"]},"theme_conf":0.86},{"uid":"12ae270e-cab4-4a34-b9a1-0aaa66c16f98","title":"感寓二首 一","author":"梁德裕","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["彩云呈瑞质，五色发人寰。","独作龙虎状，孤飞天地间。","隐隐临北极，峨峨象南山。","恨在帝乡外，不逢枝叶攀。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["旷达"],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"抒情":["思乡","孤独"],"天气":["写云"]},"theme_conf":1.0},{"uid":"b130568d-ec30-48db-ae64-7883c77f10b7","title":"郭处士击瓯歌","author":"温庭筠","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["佶栗金虬石潭古，勺陂潋滟幽修语。","湘君宝马上神云，碎佩丛铃满烟雨。","吾闻三十六宫花离离，软风吹春星斗稀。","玉晨冷磬破昏梦，天露未干香著衣。","兰钗委坠垂云发，小响丁当逐回雪。","晴碧烟滋重叠山，罗屏半掩桃花月。","太平天子驻云车，龙𬬻勃郁双蟠拏。","宫中近臣抱扇立，侍女低鬟落翠花。","乱珠触续正跳荡，倾头不觉金乌斜。","我亦为君长叹息，缄情远寄愁无色。","莫沾香梦绿杨丝，千里春风正无力。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["花","春","雪"],"cats":{"抒情":["伤感"],"四季":["春天"],"食物":["写茶"]},"theme_conf":0.512},{"uid":"9e60181d-a16b-4261-89b7-a3814a52a107","title":"禁中九日对菊花酒忆元九","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["赐酒盈杯谁共持，宫花满把独相思。","相思只傍花边立，尽日吟君咏菊诗。"],"theme":"节令风俗","theme2":["爱情相思"],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":["酒","重阳"],"cats":{"抒情":["爱情","思念"],"天气":["太阳"],"节日":["重阳节"],"植物":["菊花"],"食物":["写酒"]},"theme_conf":0.78},{"uid":"2ae550b6-e1b7-406d-9834-8ffeb33e8824","title":"寒食日出游","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["李花初发君始病，我往看君花转盛。","走马城西惆怅归，不忍千株雪相暎。","迩来又见桃与梨，交开红白如争竞。","可怜物色阻携手，空展霜缣吟九咏。","纷纷落尽泥与尘，不共新妆比端正。","桐华最晚今已繁，君不强起时难更。","关山远别固其理，寸步难见始知命。","忆昔与君同贬官，夜渡洞庭看斗柄。","岂料生还得一处，引袖拭泪悲且庆。","各言生死两追随，直置心亲无貌敬。","念君又署南荒吏，路指鬼门幽且敻。","三公尽是知音人，曷不荐贤陛下圣。","囊空甑倒谁救之，我今一食日还并。","自然忧气损天和，安得康强保天性。","断鹤两翅鸣何哀，絷骥四足气空横。","今朝寒食行野外，绿杨帀岸蒲生迸。","宋玉庭边不见人，轻浪参差鱼动镜。","自嗟孤贱足瑕疵，特见放纵荷宽政。","饮酒宁嫌𧣴底深，题诗尚倚笔锋劲。","明宵故欲相就醉，有月莫愁当火令。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["幽峭","清新"],"mood":"悲怆","mood2":["愁怨","孤寂"],"scene":["清明"],"cats":{"抒情":["友情","思念","伤感","孤独"],"天气":["太阳"],"节日":["寒食节","清明节"]},"theme_conf":0.72},{"uid":"6532c143-b684-4399-abfa-4edc7e8de03c","title":"避地","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["避地岁时晚，窜身筋骨劳。","诗书遂墙壁，奴仆且旌旄。","行在仅闻信，此生随所遭。","神尧旧天下，会见出腥臊。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"人生":["读书"]},"theme_conf":0.64},{"uid":"59e2fe4b-c925-4b3e-851d-e1c355c43b98","title":"关山月","author":"鲍氏君徽","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["高高秋月明，北照辽阳城。","塞迥光初满，风多晕更生。","征人望乡思，战马闻鼙惊。","朔风悲边草，胡沙暗虏营。","霜凝匣中劒，风惫原上旌。","早晚谒金阙，不闻刁斗声。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["相思"],"scene":["塞外","月","秋"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"天气":["写风","月亮"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.595},{"uid":"efb2f4fe-cbfc-424a-9980-7015cd556941","title":"宋中遇陈二","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["常忝鲍叔义，所期王佐才。","如何守苦节，独此无良媒。","离别十年外，飘飖千里来。","安知罢官后，惟见柴门开。","穷巷隐东郭，高堂咏南陔。","篱根长花草，井上生莓苔。","伊昔望霄汉，于今倦蒿莱。","男儿命未达，且尽手中桮。"],"theme":"送别","theme2":["山水田园"],"style":"旷达","style2":[],"mood":"孤寂","mood2":[],"scene":[],"cats":{"抒情":["离别","孤独"],"生活":["乡村"]},"theme_conf":0.434},{"uid":"3138fe30-6cf6-45b0-a441-2d5398107a9a","title":"云阳馆与韩绅宿别","author":"司空曙","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["故人江海别，几度隔山川。","乍见翻疑梦，相悲各问年。","孤灯寒照雨，湿竹暗浮烟。","更有明朝恨，离杯惜共传。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["悲慨"],"mood":"孤寂","mood2":["悲怆","愁怨"],"scene":["夜","雨","江","山","酒"],"cats":{"抒情":["友情","离别","伤感","孤独"]},"theme_conf":0.771},{"uid":"a032115c-e129-487b-b0cb-c8d15f01d2a7","title":"行路难","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["出门行路难，富贵安可期。","淮阴不免恶少辱，阮生亦作穷途悲。","颠倒英雄古来有，封侯却属屠沽儿。","长安车马随轻肥，青云宾从纷交驰。","白眼向人多意气，宰牛烹羊如折葵。","䜩乐宁知白日短，时时醉拥双蛾眉。","扬雄闭门空读书，门前碧草春离离。","不如拂衣且归去，世上浮名徒尔为。"],"theme":"羁旅思乡","theme2":["送别"],"style":"豪放","style2":["婉约"],"mood":"慷慨","mood2":["悲怆","欢愉"],"scene":["春"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"人生":["读书"]},"theme_conf":0.5},{"uid":"3c1693fc-f4e6-43b7-a66f-6379c3a26eef","title":"长相思","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["长相思，在长安，络纬秋啼金井阑。","微霜凄凄簟色寒，孤灯不明思欲绝。","卷帷望月空长叹，美人如花隔云端。","上有青冥之长天，下有渌水之波澜。","天长路远魂飞苦，梦魂不到关山难。","长相思，摧心肝。"],"theme":"爱情相思","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["爱情","思念"],"四季":["秋天"],"人物":["女子"]},"theme_conf":0.775},{"uid":"50de24cb-7548-4a09-bb9f-7681a1fe7d27","title":"感兴","author":"崔膺","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["富贵难义合，困穷易感恩。","古来忠烈士，多出贫贱门。","世上桃李树，但结繁华子。","白屋抱关人，青云壮心死。","本以势利交，势尽交情已。","如何失情后，始叹门易轨。"],"theme":"讽喻刺世","theme2":[],"style":"绮丽","style2":[],"mood":"慷慨","mood2":["欢愉","悲怆"],"scene":[],"cats":{"抒情":["感恩"]},"theme_conf":1.0},{"uid":"29611f25-d27c-4485-920f-d9ab1cfc8a18","title":"重阳席上赋白菊","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["满园花菊郁金黄，中有孤丛色似霜。","还似今朝歌酒席，白头翁入少年场。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"抒情":["孤独"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.9},{"uid":"cp4696cb09a62715","title":"采桑子·蝤蛴领上诃梨子","author":"和凝","dynasty":"五代","section":"五代","form":"词","paragraphs":["蝤蛴领上诃梨子，绣带双垂，椒户闲时，竞学樗蒲赌荔枝。","丛头鞋子红编细，裙窣金丝。","无事颦眉，春思翻教阿母疑。"],"theme":"山水田园","theme2":["闺情宫怨","闲适隐逸"],"style":"绮丽","style2":["婉约"],"mood":"恬淡","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"人物":["母亲"],"植物":["梨花"],"食物":["荔枝"]},"theme_conf":0.416},{"uid":"82f57261-b608-4ee9-8d88-7fde20c49a7a","title":"遣悲怀三首 三","author":"元稹","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["闲坐悲君亦自悲，百年都是几多时。","邓攸无子寻知命，潘岳悼亡犹费词。","同穴窅冥何所望，他生缘会更难期。","唯将终夜长开眼，报荅平生未展眉。"],"theme":"悼亡挽歌","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["夜"],"cats":{"抒情":["伤感","悼亡"]},"theme_conf":0.98},{"uid":"14ae27a0-2641-41e6-8c0a-60a9185f8b6d","title":"谒衡岳庙遂宿岳寺题门楼","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["五岳祭秩皆三公，四方环镇嵩当中。","火维地荒足妖怪，天假神柄专其雄。","喷云泄雾藏半腹，虽有绝顶谁能穷。","我来正逢秋雨节，阴气晦昧无清风。","潜心默祷若有应，岂非正直能感通。","须臾静扫众峰出，仰见突兀撑青空。","紫盖连延接天柱，石廪腾掷堆祝融。","森然魄动下马拜，松柏一迳趋灵宫。","粉墙丹柱动光彩，鬼物图画填青红。","升阶伛偻荐脯酒，欲以菲薄明其衷。","庙令老人识神意，睢盱侦伺能鞠躬。","手持桮珓导我掷，云此最吉余难同。","窜逐蛮荒幸不死，衣食才足甘长终。","侯王将相望久绝，神纵欲福难为功。","夜投佛寺上高阁，星月掩暎云朣胧。","猿鸣钟动不知曙，杲杲寒日生于东。"],"theme":"山水田园","theme2":["咏史怀古"],"style":"幽峭","style2":[],"mood":"恬淡","mood2":[],"scene":["楼"],"cats":{"抒情":["怀古"]},"theme_conf":0.72},{"uid":"c0616c55-b4a7-45f5-a73c-76e59fe5c4d7","title":"续古二十九首 十","author":"陈陶","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["周穆恣游幸，横天驱八龙。","宁知泰山下，日日望登封。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"抒情":["怀古"],"山水":["泰山"]},"theme_conf":0.95},{"uid":"3b847cf5-16b1-449d-a436-e5995c6433c4","title":"桃源行","author":"王维","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["渔舟逐水爱山春，两岸桃花夹去津。","坐看红树不知远，行尽青溪不见人。","山口潜行始隈隩，山开旷望旋平陆。","遥看一处攒云树，近入千家散花竹。","樵客初传汉姓名，居人未改秦衣服。","居人共住武陵源，还从物外起田园。","月明松下房栊静，日出云中鸡犬喧。","惊闻俗客争来集，竞引还家问都邑。","平明闾巷埽花开，薄暮渔樵乘水入。","初因避地去人间，及至成仙遂不还。","峡里谁知有人事，世中遥望空云山。","不疑灵境难闻见，尘心未尽思乡县。","出洞无论隔山水，辞家终拟长游衍。","自谓经过旧不迷，安知峰壑今来变。","当时只记入山深，青溪几曲到云林。","春来遍是桃花水，不辨仙源何处寻。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":["恬淡","孤寂"],"scene":["山"],"cats":{"抒情":["思念","思乡"],"生活":["田野"],"植物":["桃花"]},"theme_conf":0.687},{"uid":"704cf3c8-46c0-4e9f-b015-7e386bd0eff2","title":"题衡山县文宣王庙新学堂呈陆宰","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["旄头彗紫微，无复俎豆事。","金甲相排荡，青衿一顦顇。","呜呼已十年，儒服弊于地。","征夫不遑息，学者沦素志。","我行洞庭野，歘得文翁肆。","侁侁胄子行，若舞风雩至。","周室宜中兴，孔门未应弃。","是以资雅才，涣然立新意。","衡山虽小邑，首唱恢大义。","因见县尹心，根源旧宫閟。","讲堂非曩搆，大屋加涂墍。","下可容百人，墙隅亦深邃。","何必三千徒，始压戎马气。","林木在庭户，密干叠苍翠。","有井朱夏时，辘轳冻阶戺。","耳闻读书声，杀伐灾髣髴。","故国延归望，衰颜减愁思。","南纪改波澜，西河共风味。","采诗倦跋涉，载笔尚可记。","高歌激宇宙，凡百慎失坠。"],"theme":"寄赠酬答","theme2":["山水田园","咏物"],"style":"绮丽","style2":["清新"],"mood":"愁怨","mood2":["相思"],"scene":["山","江"],"cats":{"抒情":["伤感","怀古"],"人生":["读书"]},"theme_conf":0.75},{"uid":"884a25ac-d492-45dc-aeb8-d1e7c987ff0a","title":"燕居","author":"羊士谔","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["秋斋膏沐暇，旭日照轩墀。","露重芭蕉叶，香凝橘柚枝。","简书随吏散，宝骑与僧期。","报国得何力，流年已觉衰。"],"theme":"咏怀抒感","theme2":[],"style":"清新","style2":[],"mood":"慷慨","mood2":[],"scene":["鸟","秋"],"cats":{"抒情":["爱国"],"四季":["秋天"],"天气":["太阳"],"人生":["时光"],"动物":["写鸟"]},"theme_conf":0.76},{"uid":"a23b4c7c-255d-4a62-b221-4b62b42fcbcb","title":"将之京国赠薛员外","author":"李群玉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["黄叶下空馆，寂寥寒雨愁。","平居岁华晏，络纬啼林幽。","节物凋壮志，咄嗟不能休。","空怀赵鞅叹，变化良无由。","所思杳何如，侧身仰皇州。","苍烟晦楚野，寒浪埋昭丘。","赵壹赋命薄，陈思多世忧。","翻然羡鱼鸟，畅矣山川游。","薛公龙泉姿，其气在斗牛。","南冠束秀发，白石劳悲讴。","圭衮照崇阅，文儒嗣箕裘。","旷然方寸地，霁海浮云舟。","澧浦一遗佩，郢南再悲秋。","叫阍路既阻，浩荡怀灵修。","莫奏武溪笛，且登仲宣楼。","亨通与否闭，物理相沈浮。","天子坐宣室，夔龙奉谟猷。","行当赐环去，岂作遗贤羞。"],"theme":"应制干谒","theme2":["山水田园"],"style":"冲淡","style2":["雄浑","旷达"],"mood":"孤寂","mood2":["愁怨","慷慨"],"scene":["舟","秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"人生":["励志","梦想"]},"theme_conf":0.91},{"uid":"d2b5090e-e6fe-4d4f-9dd6-fe94ff6d4b5c","title":"清明日宴梅道士房","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["林卧愁春尽，开轩览物华。","忽逢青鸟使，邀入赤松家。","丹灶初开火，仙桃正落花。","童颜若可驻，何惜醉流霞。"],"theme":"佛道禅颂","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["清明"],"cats":{"抒情":["伤感"],"节日":["清明节"],"植物":["梅花"]},"theme_conf":0.68},{"uid":"a455576e-eadf-4a75-a283-80266e1054fb","title":"杂曲歌辞 行路难五首 二","author":"贺兰进明","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见门前柳，荣曜暂时萧索久。","君不见陌上花，狂风吹去落谁家。","谁家思妇见之叹，蓬首不梳心历乱。","盛年夫壻长别离，岁暮相逢色凋换。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["离别","思念"],"天气":["写风"]},"theme_conf":0.668},{"uid":"b59e2948-4c90-4b33-8af6-d02b79efd5fd","title":"彭衙行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["忆昔避贼初，北走经险艰。","夜深彭衙道，月照白水山。","尽室久徒步，逢人多厚颜。","参差谷鸟吟，不见游子还。","痴女饥𫜪我，啼畏虎狼闻。","怀中掩其口，反侧声愈嗔。","小儿强解事，故索苦李餐。","一旬半雷雨，泥泞相牵攀。","既无御雨备，径滑衣又寒。","有时经契阔，竟日数里间。","野果充糇粮，卑枝成屋椽。","早行石上水，暮宿天边烟。","少留周家洼，欲出芦子关。","故人有孙宰，高义薄曾云。","延客已曛黑，张灯启重门。","煖汤濯我足，剪纸招我魂。","从此出妻孥，相视涕阑干。","众雏烂熳睡，唤起沾盘餐。","誓将与夫子，永结为弟昆。","遂空所坐堂，安居奉我欢。","谁肯艰难际，豁达露心肝。","别来岁月周，胡羯仍搆患。","何当有翅翎，飞去堕尔前。"],"theme":"寄赠酬答","theme2":["送别","民生疾苦","山水田园"],"style":"幽峭","style2":[],"mood":"相思","mood2":["慷慨"],"scene":["夜","月","雨"],"cats":{"抒情":["友情","思念"],"人物":["儿童"]},"theme_conf":0.82},{"uid":"9c92bbd7-1c25-4ea2-8854-8db8e6de5284","title":"雨四首 三","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["物色岁将晏，天隅人未归。","朔风鸣淅淅，寒雨下霏霏。","多病久加饭，衰容新授衣。","时危觉凋丧，故旧短书稀。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["雨"],"cats":{"抒情":["思乡"],"天气":["写风","写雨"]},"theme_conf":0.91},{"uid":"48703e8c-71bb-4c72-b21f-9dbde75ee5af","title":"晚至华阴","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["腊尽促归心，行人及华阴。","云霞仙掌出，松柏古祠深。","野渡冰生岸，寒川烧隔林。","温泉看渐近，宫树晚沈沈。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["冬"],"cats":{"抒情":["思乡"],"天气":["写云"]},"theme_conf":0.579},{"uid":"130ff9df-d0d9-4812-8ae2-cba09ed87050","title":"岁暮","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["岁暮远为客，边隅还用兵。","烟尘犯雪岭，鼓角动江城。","天地日流血，朝廷谁请缨。","济时敢爱死，寂寞壮心惊。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":[],"mood":"慷慨","mood2":[],"scene":["雪","江"],"cats":{"抒情":["孤独","爱国"],"人生":["战争"]},"theme_conf":0.776},{"uid":"f99f99d1-0379-4ce5-a570-90e6b5db19b4","title":"太子纳妃太平公主出降","author":"高宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["龙楼光曙景，鲁馆启朝扉。","艳日浓妆影，低星降婺辉。","玉庭浮瑞色，银牓藻祥徽。","云转花萦盖，霞飘叶缀旗。","雕轩回翠陌，宝驾归丹殿。","鸣珠佩晓衣，镂璧轮开扇。","华冠列绮筵，兰醑申芳宴。","环阶凤乐陈，玳席珍羞荐。","蝶舞袖香新，歌分落素尘。","欢凝欢懿戚，庆叶庆初姻。","暑阑炎气息，凉早吹疎频。","方期六合泰，共赏万年春。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["夏","花","楼"],"cats":{"抒情":["闺怨"],"四季":["夏天"]},"theme_conf":0.65},{"uid":"9bf453d9-38b0-44e5-85b9-f556c7785271","title":"荆门行","author":"王建","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["江边行人暮悠悠，山头殊未见荆州。","岘亭西南路多曲，栎林深深石镞镞。","看炊红米煮白鱼，夜向鸡鸣店家宿。","南中三月蚊蚋生，黄昏不闻人语声。","生纱帷疎薄如雾，隔衣噆肤耳边鸣。","欲明不待灯火起，唤得官船过蛮水。","女儿停客茆屋新，开门扫地桐花里。","犬声扑扑寒溪烟，人家烧竹种山田。","巴云欲雨薰石热，麋鹿度江虫出穴。","大蛇过处一山腥，野牛惊跳双角折。","斜分汉水横千山，山青水绿荆门关。","向前问个长沙路，旧是屈原沈溺处。","谁家丹旐已南来，逢著流人从此去。","月明山鸟多不栖，下枝飞上高枝啼。","主人念远心不怿，罗衫卧对章台夕。","红烛交横各自归，酒醒还是他乡客。","壮年留滞尚思家，况复白头在天涯。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"幽峭","style2":["沉郁","绮丽"],"mood":"相思","mood2":[],"scene":["夜"],"cats":{"抒情":["思乡"],"节日":["端午节"]},"theme_conf":0.644},{"uid":"cp839304eb1db0bb","title":"玉楼春","author":"晏殊","dynasty":"宋","section":"宋词","form":"词","paragraphs":["绿杨芳草长亭路。","年少抛人容易去。","楼头残梦五更钟，花底离情三月雨。","无情不似多情苦。","一寸还成千万缕。","天涯地角有穷时，只有相思无尽处。"],"theme":"送别","theme2":["爱情相思","羁旅思乡"],"style":"绮丽","style2":["清新"],"mood":"相思","mood2":[],"scene":["楼","春"],"cats":{"抒情":["爱情","离别","思念","思乡"],"四季":["春天"]},"theme_conf":0.378},{"uid":"cpd16a9a874ab03a","title":"好事近","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["凉夜摘花钿，苒苒动摇云绿。","金络一团香露，正纱厨人独。","朝来碧缕放长穿，钗头挂层玉。","记得如今时候，正荔枝初熟。"],"theme":"闺情宫怨","theme2":[],"style":"清新","style2":["绮丽"],"mood":"孤寂","mood2":[],"scene":["花","夜"],"cats":{"抒情":["孤独","闺怨"],"食物":["荔枝"]},"theme_conf":0.65},{"uid":"87589e47-69eb-4b30-8204-5678cb0c8636","title":"游子吟","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["故枥思疲马，故窠思迷禽。","浮云蔽我乡，踯躅游子吟。","游子悲久滞，浮云郁东岑。","客堂无丝桐，落叶如秋霖。","艰哉远游子，所以悲滞淫。","一为浮云词，愤塞谁能禁。","驰归百年内，唯愿展所钦。","胡为不归欤，坐使年病侵。","未老霜遶鬓，非狂火烧心。","太行何难哉，北斗不可斟。","夜静星河出，耿耿辰与参。","佳人敻青天，尺素重于金。","泬寥群动异，眇默诸境森。","苔衣上闲阶，蟋蟋催寒碪。","立身计几悮，道险无容针。","三年不还家，万里遗锦衾。","梦魂无重阻，离忧罔古今。","胡为不归欤，辜负匣中琴。","腰下是何物，牵缠旷登寻。","朝与名山期，夕宿楚水阴。","楚水殊演漾，名山窅岖嵚。","客从洞庭来，婉娈潇湘深。","橘柚在南国，鸿雁遗秋音。","下有碧草洲，上有青橘林。","引烛窥洞穴，凌波睥天琛。","蒲荷影参差，凫鹤雏淋涔。","浩歌惜芳杜，散发轻华簪。","胡为不归欤，泪下沾衣襟。","鸢飞戾宵汉，蝼蚁制鳣鱏。","赫赫大圣朝，日月光照临。","圣主虽启迪，奇人分湮沈。","层城登云韶，王府锵球琳。","鹿鸣志丰草，况复虞人箴。"],"theme":"羁旅思乡","theme2":["山水田园","亲情"],"style":"豪放","style2":["沉郁","幽峭"],"mood":"恬淡","mood2":["愁怨","悲怆"],"scene":["秋","江","月","夜","鸟"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"天气":["写云","星星"],"人物":["女子"]},"theme_conf":0.292},{"uid":"6c71ef5d-2b99-4ece-b3db-deefc25bc346","title":"途中立春寄杨郇伯","author":"窦常","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["浪迹终年客，惊心此地春。","风前独去马，泽畔耦耕人。","老大交情重，悲凉外物亲。","子云今在宅，应见柳条新。"],"theme":"羁旅思乡","theme2":["节令风俗"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["孤寂"],"scene":["春"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["春天"],"生活":["田野"]},"theme_conf":0.88},{"uid":"a7bd6a97-1713-4cfc-bb5d-0fb0c6b7cca3","title":"渔父","author":"汪遵","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["棹月眠流处处通，绿蓑苇带混元风。","灵均说尽孤高事，全与逍遥意不同。"],"theme":"山水田园","theme2":["亲情"],"style":"旷达","style2":[],"mood":"孤寂","mood2":[],"scene":["舟","月"],"cats":{"抒情":["孤独"],"人物":["父亲"]},"theme_conf":0.533},{"uid":"f61de6f0-8b47-4b5f-8344-b95849bd556d","title":"鼓吹曲辞 有所思","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["君子事行役，再空芳岁期。","美人旷延伫，万里浮云思。","园槿绽红艳，郊桑柔绿滋。","坐看长夏晚，秋月生罗帏。"],"theme":"山水田园","theme2":["闺情宫怨"],"style":"绮丽","style2":["婉约","豪放"],"mood":"相思","mood2":[],"scene":["夏","花","秋","月","园林"],"cats":{"抒情":["闺怨"],"四季":["夏天","秋天"],"人物":["女子"]},"theme_conf":0.524},{"uid":"ea3f91f0-487e-4df7-826a-3692ef82e64d","title":"遣悲怀三首 二","author":"元稹","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["昔日戏言身后意，今朝皆到眼前来。","衣裳已施行看尽，针线犹存未忍开。","尚想旧情怜婢仆，也曾因梦送钱财。","诚知此恨人人有，贫贱夫妻百事哀。"],"theme":"悼亡挽歌","theme2":["送别"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":[],"cats":{"抒情":["伤感","悼亡"]},"theme_conf":0.98},{"uid":"31bc78e4-ece6-4a4f-b5bb-a8c00df6c620","title":"杂曲歌辞 鸣雁行","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["朔风动地来，吹起沙上声。","闺中有边思，玉筯此时横。","莫怕儿女恨，主人烹不鸣。"],"theme":"羁旅思乡","theme2":["闺情宫怨","亲情"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["鸟","冬"],"cats":{"抒情":["思乡","闺怨"],"四季":["冬天"],"天气":["写风"],"动物":["写鸟"]},"theme_conf":0.41},{"uid":"cp168ce1c08d4007","title":"凤凰台上忆吹箫","author":"李清照","dynasty":"宋","section":"宋词","form":"词","paragraphs":["香冷金猊，被翻红浪，起来人未梳头。","任宝奁闲掩，日上帘钩。","生怕闲愁暗恨，多少事、欲说还休。","今年瘦，非干病酒，不是悲秋。","明朝，这回去也，千万遍阳关，也即难留。","念武陵春晚，云锁重楼。","记取楼前绿水，应念我、终日凝眸。","凝眸处，从今更数，几段新愁。"],"theme":"送别","theme2":["边塞征战"],"style":"沉郁","style2":["幽峭"],"mood":"愁怨","mood2":["相思"],"scene":["楼"],"cats":{"抒情":["思念","伤感"],"生活":["边塞"]},"theme_conf":0.7},{"uid":"5f444f7d-1c9a-42c5-a2dd-1dda1aac432a","title":"望送魏征葬","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["阊阖总金鞍，上林移玉辇。","野郊怆新别，河桥非旧饯。","惨日映峰沈，愁云随盖转。","哀笳时断续，悲旌乍舒卷。","望望情何极，浪浪泪空泫。","无复昔时人，芳春共谁遣。"],"theme":"送别","theme2":[],"style":"悲慨","style2":["沉郁","绮丽"],"mood":"悲怆","mood2":["愁怨","相思"],"scene":["春","山"],"cats":{"抒情":["伤感"],"四季":["春天"],"生活":["写桥"]},"theme_conf":0.65},{"uid":"41d292d2-b752-4c30-8b6b-7b7380f2f9bd","title":"赋得","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["莺啼燕语报新年，马邑龙堆路几千。","家住层城临汉苑，[心]随明月到胡天。","机中锦字论长恨，楼上花枝笑独眠。","为问元戎窦车骑，何时返斾勒燕然。"],"theme":"咏物","theme2":["边塞征战","闺情宫怨"],"style":"清新","style2":["绮丽","沉郁"],"mood":"相思","mood2":["愁怨","孤寂"],"scene":["春","月","鸟"],"cats":{"抒情":["孤独","闺怨"],"四季":["春天"],"天气":["月亮"],"节日":["春节"]},"theme_conf":0.39},{"uid":"46dae050-2936-49c0-8e85-618f626602df","title":"上田仆射","author":"王建","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["一方新地隔河烟，曾接诸生听管弦。","却忆去年寒食会，看花犹在水堂前。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["清明"],"cats":{"抒情":["思念"],"节日":["寒食节","清明节"]},"theme_conf":0.78},{"uid":"49016fc5-51cc-4d01-896d-a6e14768ce6e","title":"横吹曲辞 紫骝马","author":"李白","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["紫骝行且嘶，双飜碧玉蹄。","临流不肎渡，似惜锦障泥。","白雪关山远，黄云海树迷。","挥鞭万里去，安得念春闺。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"绮丽","style2":["豪放"],"mood":"相思","mood2":[],"scene":["雪","春","塞外","山"],"cats":{"抒情":["思乡"],"四季":["春天"],"动物":["写马"]},"theme_conf":0.358},{"uid":"2ca1001f-fdbb-40f3-8338-ded648912642","title":"晚春闲居杨工部寄诗杨常州寄茶同到因以长句荅之","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["宿酲寂寞眠初起，春意阑珊日又斜。","劝我加餐因早笋，恨人休醉是残花。","闷吟工部新来句，渴饮毗陵远到茶。","兄弟东西官职冷，门前车马向谁家。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["冲淡","清新"],"mood":"恬淡","mood2":["孤寂","愁怨"],"scene":["春"],"cats":{"抒情":["孤独"],"四季":["春天"],"食物":["写茶"]},"theme_conf":0.9},{"uid":"39588d10-121c-4f20-aace-8cd5392070a7","title":"杂曲歌辞 桃花行 四","author":"李峤","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["桃花灼灼有光辉，无数成蹊点更飞。","为见芳林含笑待，遂同温树不言归。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["花"],"cats":{"抒情":["思乡"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"0eaf80f5-5cbe-4075-9e50-793cfa66c8f5","title":"宿叶公棋阁","author":"李洞","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["带风棋阁竹相敲，局莹无尘拂树梢。","日到长天征未断，钟来岳顶劫须抛。","挑灯雪客栖寒店，供茗溪僧𦶟废巢。","因悟修身试贪教，不须焚火向三茅。"],"theme":"哲理悟道","theme2":["哲理悟道","羁旅思乡"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["楼"],"cats":{"抒情":["思乡"],"人生":["哲理"],"植物":["叶子"]},"theme_conf":0.72},{"uid":"a6c85d29-ad02-4f54-a347-63800213a7b4","title":"故行宫","author":"王建","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["寥落古行宫，宫花寂寞红。","白头宫女在，闲坐说玄宗。"],"theme":"闺情宫怨","theme2":["咏史怀古"],"style":"婉约","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["花"],"cats":{"抒情":["孤独","闺怨","怀古"]},"theme_conf":0.438},{"uid":"1aaa5f58-ec89-4cdc-b96a-2717e03edf95","title":"挽辞 二","author":"后主煜","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["艳质同芳树，浮危道略同。","正悲春落实，又苦雨伤丛。","秾丽今何在？飘零事已空。","沈沈无问处，千载谢东风。"],"theme":"悼亡挽歌","theme2":[],"style":"悲慨","style2":["沉郁"],"mood":"悲怆","mood2":[],"scene":["春"],"cats":{"抒情":["伤感","悼亡"],"四季":["春天"]},"theme_conf":0.99},{"uid":"c8e50d0a-dd19-4fa2-b07e-95882090e9d7","title":"横吹曲辞 折杨柳 一","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["杨柳多短枝，短枝多别离。","赠远累攀折，柔条安得垂。","青春有定节，离别无定时。","但恐人别促，不怨来迟迟。","莫言短枝条，中有长相思。","朱颜与绿杨，幷在别离期。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["春"],"cats":{"抒情":["离别","思念"],"四季":["春天"],"人生":["青春"],"植物":["柳树"]},"theme_conf":0.753},{"uid":"2f37297b-77d5-412b-bc73-105bfa4d011d","title":"蜀先主庙","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["天地英雄气，千秋尚凛然。","势分三足鼎，业复五铢钱。","得相能开国，生儿不象贤。","凄凉蜀故妓，来舞魏宫前。"],"theme":"咏史怀古","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"]},"theme_conf":1.0},{"uid":"c5b54cf0-094f-4f32-ae1b-d12cb826cead","title":"杂曲歌辞 蔟拍相府莲","author":"不详","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["莫以今时宠，宁无旧日恩。","看花满眼泪，不共楚王言。","闺烛无人影，罗屏有梦魂。","近来音耗绝，终日望应门。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"孤寂","mood2":["愁怨","相思"],"scene":[],"cats":{"抒情":["伤感","孤独","闺怨"],"植物":["荷花"]},"theme_conf":1.0},{"uid":"32a56143-74fd-4375-97a4-148dee929cd1","title":"七夕赋咏成篇","author":"何仲宣","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["日日思归勤理鬓，朝朝伫望嬾调梭。","凌风宝扇遥临月，映水仙车远渡河。","历历珠星疑拖珮，冉冉云衣似曳罗。","通宵道意终无尽，向晓离愁已复多。"],"theme":"节令风俗","theme2":["咏物"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["相思"],"scene":["七夕"],"cats":{"抒情":["伤感"],"节日":["七夕节"]},"theme_conf":0.85},{"uid":"c26445b5-a433-4cd7-9020-435866b845f9","title":"送方外上人","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["孤云将野鹤，岂向人间住。","莫买沃洲山，时人已知处。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"抒情":["孤独"]},"theme_conf":1.0},{"uid":"939b6cc6-63cf-4c88-a5bf-7396fac69fb1","title":"题青龙寺镜公房","author":"马戴","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["一室意何有，闲门为我开。","炉香寒自灭，履雪饭初回。","窗迥孤山入，灯残片月来。","禅心方此地，不必访天台。"],"theme":"佛道禅颂","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["冬","雪","月","山"],"cats":{"抒情":["孤独"],"山水":["西湖"],"人生":["哲理"]},"theme_conf":0.86},{"uid":"82ed411b-a2e4-4e0b-94fb-b73c350e7f6f","title":"相和歌辞 相逢行二首 一","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["朝骑五花马，谒帝出银台。","秀色谁家子，云车珠箔开。","金鞭遥指点，玉勒近迟回。","夹毂相借问，疑从天上来。","怜肠愁欲断，斜日复相催。","下车何轻盈，飘然似落梅。","邀入青绮门，当歌共衔杯。","衔杯映歌扇，似月云中见。","相见不相亲，不如不相见。","相见情已深，未语可知心。","胡为守空闺，孤眠愁锦衾。","锦衾与罗帏，缠緜会有时。","春风正澹荡，暮雨来何迟？","愿因三青鸟，更报长相思。","光景不待人，须臾发成丝。","当年失行乐，老去徒伤悲。","持此道密意，无令旷佳期。"],"theme":"闺情宫怨","theme2":["爱情相思"],"style":"绮丽","style2":["沉郁"],"mood":"相思","mood2":["孤寂","愁怨"],"scene":["春","酒"],"cats":{"抒情":["爱情","思念","伤感","孤独","闺怨"],"四季":["春天"]},"theme_conf":0.404},{"uid":"77e2e49f-c95f-4deb-84ba-4af7aab28da2","title":"晨兴寄赠窦使君","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["江陵岁方晏，晨起眄庭柯。","白露伤红叶，清风断绿萝。","徇时真气索，念远怀忧多。","夙昔乐山意，纵横南浦波。","有美婵娟子，百虑攒双蛾。","缄情郁不舒，幽行骈复罗。","为予歌苦寒，酌酒朱颜酡。","世事浮云变，功名将奈何。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":["豪放","绮丽"],"mood":"欢愉","mood2":["愁怨","慷慨"],"scene":["酒","中秋"],"cats":{"抒情":["离别","伤感"],"节日":["中秋节"]},"theme_conf":0.93},{"uid":"361a3e5e-ef71-4749-b39a-aa2f5d9180e4","title":"听董大弹胡笳声兼寄语弄房给事","author":"李颀","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["蔡女昔造胡笳声，一弹一十有八拍。","胡人落泪沾边草，汉使断肠对归客。","古戍苍苍烽火寒，大荒沈沈飞雪白。","先拂商弦后角羽，四郊秋叶惊摵摵。","董夫子，通神明，深山窃听来妖精。","言迟更速皆应手，将往复旋如有情。","空山百鸟散还合，万里浮云阴且晴。","嘶酸雏鴈失群夜，断绝胡儿恋母声。","川为净其波，鸟亦罢其鸣。","乌孙部落家乡远，逻娑沙尘哀怨生。","幽音变调忽飘洒，长风吹林雨堕瓦。","迸泉飒飒飞木末，野鹿呦呦走堂下。","长安城连东掖垣，凤凰池对青琐门。","高才脱略名与利，日夕望君抱琴至。"],"theme":"题画咏艺","theme2":["送别"],"style":"豪放","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["雪","夜"],"cats":{"抒情":["伤感"],"天气":["写雪"]},"theme_conf":0.96},{"uid":"da7e5017-c5ed-43a9-9400-e1a77958aa19","title":"送李栖桐道举擢第还乡省侍","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["几年深道要，一举过贤关。","名与玄珠出，乡宜昼锦还。","莲舟同宿浦，柳岸向家山。","欲见宁亲孝，儒衣稚子斑。"],"theme":"羁旅思乡","theme2":["送别"],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["舟","山"],"cats":{"抒情":["思乡"],"人物":["儿童"]},"theme_conf":0.474},{"uid":"5af61ecb-4c41-4634-983d-a27fddb5341e","title":"岳阳怀古","author":"吕温","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["晨飙发荆州，落日到巴丘。","方知刳剡利，可接鬼神游。","二湖豁南寖，九派驶东流。","襟带三千里，尽在岳阳楼。","忆昔鬬群雄，此焉争上游。","吴昌屯虎旅，晋盛骛龙舟。","宋齐纷祸难，梁陈成寇雠。","钟鼓长震耀，鱼龙不得休。","风雪一萧散，功业忽如浮。","今日时无事，空江满白鸥。"],"theme":"咏史怀古","theme2":[],"style":"幽峭","style2":[],"mood":"惆怅","mood2":[],"scene":["楼","江","端午"],"cats":{"抒情":["怀古"],"节日":["端午节"]},"theme_conf":0.798},{"uid":"6f50b001-74c4-4c85-a2a3-626560010c86","title":"长安客舍赠李行父明府","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["藏器待时少，知人自古难。","遂令丹穴凤，晚食金琅玕。","谁谓兵戈际，鸣琴方一弹。","理烦善用简，济猛能兼宽。","夙夜念黎庶，寝兴非宴安。","洪波未静壑，何树不惊鸾。","凫舄傍京辇，甿心悬灌坛。","高槐暗苦雨，长剑生秋寒。","旅食还为客，饥年亦尽欢。","亲劳携斗水，往往救泥蟠。","但恐酬明义，蹉跎芳岁阑。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"婉约","style2":[],"mood":"恬淡","mood2":["欢愉"],"scene":["秋","夜","山","雨"],"cats":{"抒情":["思乡"],"四季":["秋天"],"人物":["父亲"]},"theme_conf":0.78},{"uid":"4c91b589-bd48-42db-8034-5b8c236dd885","title":"琴曲歌辞 别鹤","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["分飞共所从，六翮势摧风。","声断碧云外，影孤明月中。","青田归路远，月桂旧巢空。","矫翼知何处，天涯不可穷。"],"theme":"送别","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["月"],"cats":{"抒情":["离别","孤独"],"天气":["月亮"],"动物":["写鸟"]},"theme_conf":0.534},{"uid":"cp645ccc138fd1c2","title":"秦楼月・忆秦娥","author":"范成大","dynasty":"宋","section":"宋词","form":"词","paragraphs":["楼阴缺。","阑干影卧东厢月。","东厢月。","一天风露，杏花如雪。","隔烟催漏金虬咽。","罗帏暗淡灯花结。","灯花结。","片时春梦，江南天阔。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["楼","月"],"cats":{"抒情":["思念","闺怨"],"天气":["月亮"]},"theme_conf":1.0},{"uid":"0fd231d3-c040-4a2c-9b0b-5b96297cb884","title":"别李明府","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["宠光五世要青组，出入珠宫引箫鼓。","醉舞雄王玳瑁床，娇嘶骏马珊瑚柱。","胡儿夹鼓越婢随，行捧玉盘尝荔枝。","罗山道士请人送，林邑使臣调象骑。","爱君一身游上国，阙下名公如旧识。","万里初怀印绶归，湘江过尽岭花飞。","五侯焦石烹江笋，千户沈香染客衣。","别后想君难可见，苍梧云里空山县。","汗苑芳菲入夏阑，待君障日蒲葵扇。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["花","山","夏","江"],"cats":{"抒情":["离别"],"四季":["夏天"],"食物":["荔枝"]},"theme_conf":0.55},{"uid":"cd66d8b3-abe6-4316-ab34-b88a4bb8bb83","title":"杂曲歌辞 北风行","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["烛龙栖寒门，光曜犹旦开。","日月照之何不及此，惟有北风怒号天上来。","燕山雪花大如席，片片吹落轩辕台。","幽州思妇十二月，停歌罢笑双蛾摧。","倚门望行人，念君长城苦寒良可哀。","别时提劒救边去，遗此虎文金髀钗。","中有一双白羽箭，蜘蛛结网生尘埃。","箭空在，人今战死不复回。","不忍见此物，焚之已成灰。","黄河捧土尚可塞，北风雨雪恨难裁。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"豪放","style2":[],"mood":"相思","mood2":["悲怆","愁怨"],"scene":["雪","冬","雨"],"cats":{"抒情":["闺怨"],"山水":["黄河"],"天气":["写风"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.317},{"uid":"ca42b16b-5f16-40f4-8291-34970d922fac","title":"槐叶冷淘","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["青青高槐叶，采掇付中厨。","新面来近市，汁滓宛相俱。","入鼎资过熟，加餐愁欲无。","碧鲜俱照箸，香饭兼苞芦。","经齿冷于雪，劝人投此珠。","愿随金騕褭，走置锦屠苏。","路远思恐泥，兴深终不渝。","献芹则小小，荐藻明区区。","万里露寒殿，开冰清玉壶。","君王纳凉晚，此味亦时须。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":["冬","雪"],"cats":{"抒情":["伤感"],"节日":["春节"],"植物":["叶子"]},"theme_conf":0.93},{"uid":"34d953bb-1383-4a20-ab85-9313f0c82b7d","title":"复愁十二首 十一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["每恨陶彭泽，无钱对菊花。","如今九日至，自觉酒须赊。"],"theme":"节令风俗","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["重阳","酒"],"cats":{"抒情":["伤感"],"节日":["重阳节"]},"theme_conf":0.63},{"uid":"cpc4cd8e0d3c721d","title":"摸鱼儿","author":"朱嗣发","dynasty":"宋","section":"宋词","form":"词","paragraphs":["对西风、鬓摇烟碧，参差前事流水。","紫丝罗带鸳鸯结，的的镜盟钗誓。","浑不记、漫手织回文，几度欲心碎。","安花著蒂。","奈雨覆云翻，情宽分窄，石上玉簪脆。","朱楼外。","愁压空云欲坠。","月痕犹照无寐。","阴晴也只随天意。","枉了玉消香碎。","君且醉。","君不见、长门青草春风泪。","一时左计。","悔不早荆钗，暮天修竹，头白倚寒翠。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["沉郁","婉约"],"mood":"愁怨","mood2":["孤寂"],"scene":["花","春"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"天气":["写风"]},"theme_conf":0.733},{"uid":"8fc37ad3-7f3b-466e-aad1-e00a080fdf1d","title":"睢阳酬别畅大判官","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["吾友遇知己，策名逢圣朝。","高才擅白雪，逸翰怀青霄。","承诏选嘉宾，慨然即驰轺。","清昼下公馆，尺书忽相邀。","留欢惜别离，毕景驻行镳。","言及沙漠事，益令胡马骄。","丈夫拔东蕃，声冠霍嫖姚。","兜鍪冲矢石，铁甲生风飙。","诸将出冷陉，连营济石桥。","酋豪尽俘馘，子弟输征徭。","边庭绝刁斗，战地成渔樵。","榆关夜不扃，塞口长萧萧。","降胡满蓟门，一一能射雕。","军中多宴乐，马上何轻趫。","戎狄本无厌，羇縻非一朝。","饥附诚足用，饱飞安可招。","李牧制儋蓝，遗风岂寂寥。","君还谢幕府，慎勿轻刍荛。"],"theme":"送别","theme2":["边塞征战"],"style":"豪放","style2":["幽峭"],"mood":"欢愉","mood2":[],"scene":["塞外"],"cats":{"抒情":["友情","离别"],"人生":["战争"],"生活":["边塞","写桥"]},"theme_conf":0.421},{"uid":"cp1dbe46a9ca1ac2","title":"绮罗香","author":"史达祖","dynasty":"宋","section":"宋词","form":"词","paragraphs":["做冷欺花，将烟困柳，千里偷催春暮。","尽日冥迷，愁里欲飞还住。","惊粉重、蝶宿西园，喜泥润、燕归南浦。","最妨它、佳约风流，钿车不到杜陵路。","沈沈江上望极，还被春潮晚急，难寻官渡。","隐约遥峰，和泪谢娘眉妩。","临断岸、新绿生时，是落红、带愁流处。","记当日、门掩梨花，翦灯深夜语。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["婉约","沉郁"],"mood":"愁怨","mood2":[],"scene":["花","春","江","夜"],"cats":{"抒情":["离别","伤感"],"四季":["春天"]},"theme_conf":1.0},{"uid":"cpbf1334f01df25f","title":"少年游","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["长安古道马迟迟。","高柳乱蝉栖。","夕阳岛外，秋风原上，目断四天垂。","归云一去无踪迹，何处是前期。","狎兴生疏，酒徒萧索，不似去年时。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","酒"],"cats":{"抒情":["思乡"],"四季":["秋天"],"人生":["青春"]},"theme_conf":0.72},{"uid":"0ef99715-15ba-4586-98d0-bb90aece4b71","title":"杂曲歌辞 鸣雁行","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["七月朔方雁心苦，联影翻空落南土。","八月江南阴复晴，浮云绕天难夜行。","羽翼劳痛心虚惊，一声相呼百处鸣。","楚童夜宿烟波侧，沙上布罗连草色。","月暗风悲欲下天，不知何处容栖息？","楚童胡为伤我神，尔不曾作远行人。","江南羽族本不少，宁得网罗此客鸟。"],"theme":"羁旅思乡","theme2":[],"style":"冲淡","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["鸟","江","江南"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"动物":["写鸟"]},"theme_conf":0.745},{"uid":"066e5f06-6d53-47d1-81f8-982462f0281d","title":"酬郭先辈","author":"徐铉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["太原郭夫子，行高文炳蔚。","弱龄负世誉，一举游月窟。","仙籍第三人，时人故称屈。","昔余吏西省，倾盖名籍籍。","及我窜群舒，向风心郁郁。","归来暮江上，云雾一披拂。","雷雨不下施，犹作池中物。","念君介然气，感时思奋发。","示我数篇文，与古争驰突。","彩褥粲英华，理深刮肌骨。","古诗尤精奥，史论皆宏拔。","举此措诸民，何忧民不活。","吁嗟吾道薄，与世长迂阔。","顾我徒有心，数奇身正绌。","论兵属少年，经国须儒术。","夫子无自轻，苍生正愁疾。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["伤感"],"人生":["励志"]},"theme_conf":0.95},{"uid":"4925c861-b0f8-4b2f-923e-9cba2df1323e","title":"洛阳女儿行","author":"王维","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["洛阳女儿对门居，才可容颜十五余。","良人玉勒乘骢马，侍女金盘鲙鲤鱼。","画阁朱楼尽相望，红桃绿柳垂簷向。","罗帏送上七香车，宝扇迎归九华帐。","狂夫富贵在青春，意气骄奢剧季伦。","自怜碧玉亲教舞，不惜珊瑚持与人。","春窗曙灭九微火，九微片片飞花璅。","戏罢曾无理曲时，妆成秪是薰香坐。","城中相识尽繁华，日夜经过赵李家。","谁怜越女颜如玉，贫贱江头自浣纱。"],"theme":"闺情宫怨","theme2":["羁旅思乡"],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":["春","楼","花"],"cats":{"抒情":["思乡","闺怨"],"四季":["春天"],"人生":["青春"]},"theme_conf":0.396},{"uid":"64e506a0-6664-49b3-bd7d-826cc4629274","title":"寒食","author":"卢纶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["孤客飘飘岁载华，况逢寒食倍思家。","莺啼远墅多从柳，人哭荒坟亦有花。","浊水秦渠通渭急，黄埃京洛上原斜。","驱车西近长安好，宫观参差半隐霞。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"孤寂","mood2":["悲怆"],"scene":["清明"],"cats":{"抒情":["思乡","孤独"],"节日":["寒食节","清明节"]},"theme_conf":0.92},{"uid":"a8e39b30-119d-4b4f-b557-da792950a2a3","title":"杂曲歌辞 行路难三首 三","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["飞雪断道冰成梁，侯家炽炭雕玉房。","蟠龙吐耀虎喙张，熊蹲豹掷争低昂。","攒峦丛崿射朱光，丹霞翠雾飘奇香。","美人四向回明珰，雪山冰谷晞太阳。","星躔奔走不得止，奄忽双燕栖虹梁。","风台露榭生光饰，死灰弃置参与商。","盛时一去贵反贱，桃笙葵扇安可常。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"悲怆","mood2":[],"scene":["雪","冬"],"cats":{"抒情":["思乡"],"天气":["写雪"],"人物":["女子"]},"theme_conf":1.0},{"uid":"fe6f4b72-855c-43b9-8883-8b3fe3cd8bd4","title":"杜少府之任蜀州","author":"王勃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["城阙辅三秦，风烟望五津。","与君离别意，同是宦游人。","海内存知己，天涯若比隣。","无为在岐路，儿女共沾巾。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"抒情":["友情","离别"]},"theme_conf":0.566},{"uid":"cp37352233f0f196","title":"谢金莲诗酒红梨花・金盏儿","author":"张寿卿","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["这秀才忒撑达，将我问根芽。","妾身住处兀那东直下，深村旷野不堪夸。","俺那里遮藏红杏树，掩映碧桃花。","兀良山前五六里，林外两三家。","(赵汝州云)小娘子，你端的谁氏之家？(正旦云)妾身是王同知之女，今夜晚间，因看花来到太守花园里，不想遇着秀才。","敢问秀才姓甚名谁？(赵汝州云)小生是太守相公的表弟赵汝州是也。","小娘子既到此处，到我书房中饮几杯，有何不可？(正旦云)既然如此，同到书房中攀话去咱。","(做进书房科)(赵汝州云)小娘子不嫌亵渎，请满饮一杯。","(正旦云)秀才请。","(赵汝州云)难得小娘子到此，多饮几杯。","(正旦唱)。"],"theme":"山水田园","theme2":["闲适隐逸","闺情宫怨"],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["花","酒"],"cats":{"抒情":["闺怨","感恩"],"植物":["梨花","荷花"],"食物":["写酒"]},"theme_conf":0.401},{"uid":"1bba0f29-6b38-446b-98d5-20268903330c","title":"琴曲歌辞 别鹤","author":"张籍","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["双鹤出云谿，分飞各自迷。","空巢在松杪，折羽落江泥。","寻水终不饮，逢林亦未栖。","别离应易老，万里两凄凄。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["鸟"],"cats":{"抒情":["离别"],"动物":["写鸟"]},"theme_conf":0.671},{"uid":"c9362aba-fb50-481b-a4cd-08ddd65cdd2a","title":"梦李白二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["死别已吞声，生别常恻恻。","江南瘴疠地，逐客无消息。","故人入我梦，明我长相忆。","恐非平生魂，路远不可测。","魂来枫叶青，魂返关塞黑。","君今在罗网，何以有羽翼。","落月满屋梁，犹疑照颜色。","水深波浪阔，无使蛟龙得。"],"theme":"寄赠酬答","theme2":["游仙梦幻","羁旅思乡","边塞征战"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["江南","塞外","月"],"cats":{"抒情":["友情","思念","思乡"],"人生":["梦想"],"生活":["边塞"]},"theme_conf":0.75},{"uid":"811a5f9e-0df5-46f1-a587-0d4df7bca5a0","title":"无题四首 二","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["飒飒东风细雨来，芙蓉塘外有轻雷。","金蟾啮鏁烧香入，玉虎牵丝汲井回。","贾氏窥帘韩掾少，宓妃留枕魏王才。","春心莫共花争发，一寸相思一寸灰。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["雨","春","花"],"cats":{"抒情":["爱情","思念"],"四季":["春天"],"天气":["写雨"]},"theme_conf":0.713},{"uid":"73dadc56-88ff-4f11-9ff5-da0e0adf533c","title":"杂曲歌辞 清平调 二","author":"李白","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["一枝红艳露凝香，云雨巫山枉断肠。","借问汉宫谁得似，可怜飞燕倚新妆。"],"theme":"闺情宫怨","theme2":["咏史怀古"],"style":"清新","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["花","雨","山"],"cats":{"抒情":["伤感","闺怨","怀古"]},"theme_conf":0.637},{"uid":"fadd4ab1-6b70-4a7b-b9b5-4190edae96e0","title":"寒食寄李补阙","author":"郭郧","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["兰陵士女满晴川，郊外纷纷拜古埏。","万井闾阎皆禁火，九原松柏自生烟。","人间后事悲前事，镜里今年老去年。","介子终知禄不及，王孙谁肯一相怜。"],"theme":"寄赠酬答","theme2":["送别"],"style":"悲慨","style2":["幽峭"],"mood":"悲怆","mood2":[],"scene":["清明"],"cats":{"抒情":["伤感"],"节日":["寒食节","清明节"]},"theme_conf":0.78},{"uid":"954bc2e7-212b-4af0-afc2-f9230822a784","title":"送孙泼赴云中","author":"韩翃","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["黄骢少年舞双戟，目视旁人皆辟易。","百战能夸陇上儿，一身复作云中客。","寒风动地气苍茫，横吹先悲出塞长。","敲石军中传夜火，斧冰河畔汲朝浆。","前锋直指阴山外，虏骑纷纷胆应碎。","匈奴破尽人看归，金印酬功如斗大。"],"theme":"送别","theme2":["边塞征战"],"style":"雄浑","style2":["悲慨","幽峭"],"mood":"悲怆","mood2":[],"scene":["塞外","夜"],"cats":{"抒情":["伤感"],"天气":["写云"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.479},{"uid":"094c888f-a963-43dc-9e4e-b1b644c54abe","title":"解闷十二首 十","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["忆过泸戎摘荔枝，青峰隐暎石逶迤。","京中旧见无颜色，红颗酸甜只自知。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["山"],"cats":{"抒情":["思念"],"食物":["荔枝"]},"theme_conf":0.65},{"uid":"3182d857-499a-4f62-89f1-aa628eaf63e3","title":"哭长孙侍郎","author":"杜诵","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["道为诗书重，名因赋颂雄。","礼闱曾擢桂，宪府既乘骢。","流水生涯尽，浮云世事空。","唯余旧台柏，萧瑟九原中。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":[],"cats":{"抒情":["悼亡"],"人生":["读书"]},"theme_conf":0.98},{"uid":"f2df70bb-0958-4bc6-bef3-593eae26d678","title":"田家秋日送友","author":"于良史","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["苍茫日初宴，遥野云初收。","残雨北山里，夕阳东渡头。","舟依渔溓合，水入田家流。","何意君迷驾，山林应有秋。"],"theme":"山水田园","theme2":["送别"],"style":"雄浑","style2":[],"mood":"欢愉","mood2":[],"scene":["秋"],"cats":{"抒情":["友情"],"四季":["秋天"],"天气":["太阳"],"生活":["田野"]},"theme_conf":0.412},{"uid":"7cebb127-e2e6-423d-a597-340dc11ecfdf","title":"红叶","author":"唐彦谦","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["无处不飘扬，高楼临道旁。","素娥前夕月，青女夜来霜。","宿雨随时润，秋晴著物光。","幽怀长若此，病眼更相妨。","蜀纸裁深色，燕脂落靓粧。","低丛侵小阁，倒影入回塘。","谢朓留霞绮，甘宁弃锦张。","何人休远道，是处有斜阳。","薜荔垂书幌，梧桐坠井床。","晚风生旅馆，寒籁近僧房。","桂绿明淮甸，枫丹照楚乡。","鴈疎临鄠杜，蝉急傍潇湘。","树异桓宣武，园非顾辟疆。","茂陵愁卧客，不自保危肠。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":["清新","沉郁"],"mood":"愁怨","mood2":[],"scene":["秋","楼"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":0.7},{"uid":"3d4e85e1-0bed-4e7b-8bb6-81677d9f448d","title":"杂曲歌辞 轻薄行","author":"僧齐己","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["玉鞭金镫骅骝蹏，横眉吐气如虹霓。","五陵春暖芳草齐，笙歌到处花成泥。","日沈月上且鬬鸡，醉来莫问天高低。","伯阳道德何涕唾，仲尼礼乐徒卑栖。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["花","春","月","酒"],"cats":{"抒情":["思乡"],"四季":["春天"],"天气":["彩虹"]},"theme_conf":0.65},{"uid":"0919893a-6302-4409-87ac-c1208e2e2f87","title":"横吹曲辞 骢马","author":"李群玉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["浮云何权奇，绝足势未知。","长嘶青海风，躞蹀振云丝。","由来渥洼种，本是苍龙儿。","穆满不再活，无人昆阆骑。","君识跃峤怯，宁劳耀金羁。","青刍与白水，空笑驽骀肥。","伯乐傥一见，应惊耳长垂。","当思八荒外，逐日向瑶池。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"欢愉","mood2":["孤寂"],"scene":[],"cats":{"抒情":["思乡","孤独"],"动物":["写马"]},"theme_conf":0.577},{"uid":"16b8caaa-e64d-4ad8-839f-8627c0a40f62","title":"送魏八","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["更沽淇上酒，还泛驿前舟。","为惜故人去，复怜嘶马愁。","云山行处合，风雨兴中秋。","此路无知己，明珠莫暗投。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["雨","中秋","酒","舟","秋"],"cats":{"抒情":["友情","伤感"],"四季":["秋天"],"节日":["中秋节"]},"theme_conf":0.731},{"uid":"3fff5496-d24c-48c6-9c61-0d8925b663fe","title":"登蒲州逍遥楼","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["长榆息烽火，高柳静风尘。","卜征巡九洛，展豫出三秦。","昔是潜龙地，今为上理辰。","时平乘道泰，聊赏遇年春。","黄河分地络，飞观接天津。","一览遗芳翰，千载肃如神。"],"theme":"咏史怀古","theme2":["边塞征战"],"style":"旷达","style2":[],"mood":"恬淡","mood2":[],"scene":["楼","江","春"],"cats":{"抒情":["怀古"],"四季":["春天"],"山水":["黄河"],"人生":["战争"]},"theme_conf":0.565},{"uid":"cpace79dfe6e198c","title":"踏莎行","author":"欧阳修","dynasty":"宋","section":"宋词","form":"词","paragraphs":["候馆梅残，溪桥柳细。","草熏风暖摇征辔。","离愁渐远渐无穷，迢迢不断如春水。","寸寸柔肠，盈盈粉泪。","楼高莫近危阑倚。","平芜尽处是春山，行人更在春山外。"],"theme":"山水田园","theme2":["送别"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春","山","楼"],"cats":{"抒情":["伤感"],"四季":["春天"],"生活":["写桥"]},"theme_conf":0.6},{"uid":"4c09aa73-453f-4edb-953d-0f72a14a1e5c","title":"和鲁望白菊","author":"张贲","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["雪彩冰姿号女华，寄身多是地仙家。","有时南国和霜立，几处东篱伴月斜。","谢客琼枝空贮恨，袁郎金钿不成夸。","自知终古清香在，更出梅粧弄晚霞。"],"theme":"咏物","theme2":["羁旅思乡","山水田园","送别"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["冬","雪","重阳"],"cats":{"抒情":["思乡"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.92},{"uid":"d5da9d7d-1e52-4992-8be5-73e556b07e0b","title":"清平调 一","author":"李白","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["云想衣裳花想容，春风拂槛露华浓。","若非群玉山头见，会向瑶台月下逢。"],"theme":"游仙梦幻","theme2":["闺情宫怨"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["春","月","山"],"cats":{"抒情":["闺怨"],"四季":["春天"]},"theme_conf":0.513},{"uid":"cdc8c314-14e2-4e5d-a692-70986b3a2a25","title":"和李公七夕","author":"任希古","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["落日照高牖，凉风起庭树。","悠悠天宇平，昭昭月华度。","开轩卷绡幕，延首晞云路。","层汉有灵妃，仙居无与晤。","履化悲流易，临川怨迟暮。","昔从九春徂，方此三秋遇。","瑶驾越星河，羽盖凝珠露。","便妍耀井色，窈窕凌波步。","始阅故人新，俄见新人故。","掩泪收机石，衔啼襞纨素。","惆怅何伤已，裴回劳永慕。","无由西北归，空自东南顾。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["冲淡"],"mood":"愁怨","mood2":["惆怅","悲怆"],"scene":["七夕"],"cats":{"抒情":["友情","伤感"],"天气":["月亮","星星"],"节日":["七夕节"]},"theme_conf":0.76},{"uid":"549a5a94-a8f5-436e-bc9c-1253d01c1940","title":"后宫词","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["泪湿罗巾梦不成，夜深前殿按歌声。","红颜未老恩先断，斜倚薰笼坐到明。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":["沉郁","绮丽"],"mood":"愁怨","mood2":[],"scene":["夜"],"cats":{"抒情":["伤感","闺怨"]},"theme_conf":1.0},{"uid":"65c4e93c-38d0-4247-a7cc-b19c6ee77743","title":"叶上题诗从苑中流出","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["花落深宫莺亦悲，上阳宫女断肠时。","君恩不闭东流水，叶上题诗寄与谁。"],"theme":"咏物","theme2":["送别","咏史怀古","闺情宫怨"],"style":"悲慨","style2":["婉约"],"mood":"悲怆","mood2":["愁怨"],"scene":[],"cats":{"抒情":["伤感","闺怨","怀古"],"植物":["叶子"]},"theme_conf":0.353},{"uid":"8098529a-3316-4f89-a17f-6e6a2ce52d59","title":"咏桃","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["禁苑春晖丽，花蹊绮树妆。","缀条深浅色，点露参差光。","向日分千笑，迎风共一香。","如何仙岭侧，独秀隐遥芳。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["花","春"],"cats":{"抒情":["孤独","感恩"],"四季":["春天"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"fbb109b7-3b66-4f82-a111-97892b26fa7a","title":"喜闻官军已临贼境二十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["胡虏潜京县，官军拥贼壕。","鼎鱼犹假息，穴蚁欲何逃。","帐殿罗玄冕，辕门照白袍。","秦山当警跸，汉苑入旌旄。","路失羊肠险，云横雉尾高。","五原空壁垒，八水散风涛。","今日看天意，游魂贷尔曹。","乞降那更得，尚诈莫徒劳。","元帅归龙种，司空握豹韬。","前军苏武节，左将吕虔刀。","兵气回飞鸟，威声没巨鼇。","戈鋋开雪色，弓矢尚秋毫。","天步艰方尽，时和运更遭。","谁云遗毒螫，已是沃腥臊。","睿想丹墀近，神行羽卫牢。","花门腾绝漠，拓羯渡临洮。","此辈感恩至，羸俘何足操。","锋先衣染血，骑突劒吹毛。","喜觉都城动，悲怜子女号。","家家卖钗钏，只待献春醪。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["雪","塞外","秋","春","酒"],"cats":{"抒情":["感恩"],"四季":["春天","秋天"],"人生":["战争"]},"theme_conf":1.0},{"uid":"80c6900a-4be3-44cb-9a58-346a4c8fa498","title":"重忆白菊","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["我怜贞白重寒芳，前后丛生夹小堂。","月朵暮开无绝艳，风茎时动有奇香。","何慙谢雪清才咏，不羡刘梅贵主妆。","更忆幽窗凝一梦，夜来村落有微霜。"],"theme":"咏物","theme2":[],"style":"幽峭","style2":["婉约"],"mood":"相思","mood2":[],"scene":["夜","重阳","花","冬","雪","月"],"cats":{"抒情":["思念"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"5d05fef6-e4aa-48e5-917d-c29d0e6d6b33","title":"登岳阳楼","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["昔闻洞庭水，今上岳阳楼。","吴楚东南坼，乾坤日夜浮。","亲朋无一字，老病有孤舟。","戎马关山北，凭轩涕泗流。"],"theme":"山水田园","theme2":["羁旅思乡","咏史怀古"],"style":"沉郁","style2":[],"mood":"慷慨","mood2":["孤寂"],"scene":["楼"],"cats":{"抒情":["思乡","孤独","怀古"]},"theme_conf":0.396},{"uid":"e951ac7e-488c-4282-a368-a58852fc9f2f","title":"过梅里七首  家于无锡四十载今敝庐数堵犹存今列题于后 忆题惠山寺书堂","author":"李绅","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["故山一别光阴改，秋露清风岁月多。","松下壮心年少去，池边衰影老人过。","白云生灭依岩岫，青桂荣枯托薜萝。","惟有此身长是客，又驱旌斾寄烟波。"],"theme":"羁旅思乡","theme2":["送别","山水田园"],"style":"清新","style2":[],"mood":"相思","mood2":["慷慨"],"scene":["山"],"cats":{"抒情":["思念","思乡"],"人生":["时光"],"植物":["梅花"]},"theme_conf":0.9},{"uid":"bab8a287-f853-4c81-ab99-2795a5484ae1","title":"杂曲歌辞 浩歌行","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["天长地久无终毕，昨夜今朝又明日。","鬓发苍浪牙齿疎，不觉身年四十七。","前去五十有几年，把镜照面心茫然。","既无长绳系白日，又无大药驻朱颜。","朱颜日渐不如故，青史功名在何处？","欲留年少待富贵，富贵不来年少去。","去复去兮如长河，东流赴海无回波。","贤愚贵贱同归尽，北邙冢墓高嵯峨。","古来如此非独我，未死有酒且酣歌。","颜回短命伯夷饿，我今所得亦已多。"],"theme":"民生疾苦","theme2":["悼亡挽歌","羁旅思乡"],"style":"豪放","style2":["雄浑"],"mood":"孤寂","mood2":["惆怅"],"scene":["酒"],"cats":{"抒情":["思乡","孤独","悼亡"]},"theme_conf":0.358},{"uid":"05dda800-bd7b-43f0-b0f4-6edeafa87e5f","title":"酬孟武昌苦雪","author":"元结","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["积[雪]闲山路，有人到庭前。","云是孟武昌，令献苦雪篇。","长吟未及终，不觉为凄然。","古之贤达者，与世竟何异。","不能救时患，讽谕以全意。","知公惜春物，岂非爱时和。","知公苦阴雪，伤彼灾患多。","奸凶正驱驰，不合问君子。","林莺与野兽，无乃怨于此。","兵兴向九岁，稼穑谁能忧。","何时不发卒，何日不杀牛。","耕者日已少，耕牛日已希。","皇天复何忍，更又恐毙之。","自经危乱来，触物堪伤叹。","见君问我意，只益胸中乱。","山禽饥不飞，山木冻皆折。","悬泉化为冰，寒水近不热。","出门望天地，天地皆昏昏。","时见双峰下，雪中生白云。"],"theme":"民生疾苦","theme2":["山水田园","送别"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["雪","冬"],"cats":{"抒情":["伤感"],"山水":["瀑布"],"天气":["写雪"]},"theme_conf":0.319},{"uid":"cp66426d06db2e64","title":"夜合花","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["柳暝河桥，莺晴台苑，短策频惹春香。","当时夜泊，温柔便入深乡。","词韵窄，酒杯长。","翦蜡花、壶箭催忙。","共追游处，凌波翠陌，连棹横塘。","十年一梦凄凉。","似西湖燕去，吴馆巢荒。","重来万感，依前唤酒银罂。","溪雨急，岸花狂。","趁残鸦、飞过苍茫。","故人楼上，凭谁指与，芳草斜阳。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"清新","style2":["雄浑","豪放"],"mood":"愁怨","mood2":[],"scene":["花","酒","夜","鸟","江南","春"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":0.558},{"uid":"2065dc7a-5ac9-406f-b7cd-285c5b5293df","title":"晚渡渭桥寄示京邑游好","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["我行背城阙，驱马独悠悠。","寥落百年事，裴回万里忧。","途遥日向夕，时晚鬓将秋。","滔滔俯东逝，耿耿泣西浮。","长虹掩钓浦，落雁下星洲。","草变黄山曲，花飞清渭流。","迸水惊愁鹭，腾沙起狎鸥。","一赴清泥道，空思玄灞游。"],"theme":"山水田园","theme2":["送别"],"style":"豪放","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["山"],"cats":{"抒情":["伤感","孤独"],"天气":["彩虹"],"生活":["写桥"]},"theme_conf":0.501},{"uid":"8baa7c35-9afb-40bf-b5e4-41d9895e2710","title":"相思","author":"王维","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["红豆生南国，秋来发故枝。","愿君多采撷，此物最相思。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["秋"],"cats":{"抒情":["爱情","思念"],"四季":["秋天"]},"theme_conf":0.714},{"uid":"e110c62b-f130-4558-b4af-8282d6a2a5de","title":"酬杨司业十二兄早秋述情见寄","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["白发故人少，相逢意弥远。","往事共销沈，前期各衰晚。","昨来遇弥苦，已复云离𪩘。","秋草古胶庠，寒沙废宫苑。","知心岂忘鲍，咏怀难和阮。","壮志日萧条，那能竞朝幰。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"慷慨","mood2":[],"scene":["秋"],"cats":{"抒情":["友情"],"四季":["秋天"],"人生":["励志","梦想"]},"theme_conf":0.94},{"uid":"19a657e3-0b2b-4c6b-b69b-14057f346891","title":"从军行","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["丈夫四方志，结发事远游。","远游历燕蓟，独戍边城陬。","西风垅水寒，明月关山悠。","酬恩仗孤剑，十年弊貂裘。","封侯属何人，磋跎雪盈头。","老马思故枥，穷鳞忆深流。","弹铗动深慨，浩歌气横秋。","报国期努力，功名良见收。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["沉郁"],"mood":"慷慨","mood2":["孤寂"],"scene":["月","秋","雪"],"cats":{"抒情":["孤独","爱国"],"四季":["秋天"],"天气":["月亮"]},"theme_conf":0.641},{"uid":"17097de0-b154-43fd-9213-91d38353eb8c","title":"杂曲歌辞 桃花行 五","author":"李峤","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["红蕚竞妍春苑曙，粉茸新向御筵开。","长年愿奉西王宴，近侍慙无东朔才。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["花","春"],"cats":{"抒情":["思乡"],"四季":["春天"],"植物":["桃花"]},"theme_conf":0.65},{"uid":"cpa94a5ad72e936a","title":"唐多令","author":"刘过","dynasty":"宋","section":"宋词","form":"词","paragraphs":["芦叶满汀洲。","塞沙带浅流。","二十年、重过南楼。","柳下系舟犹未稳，能几日、又中秋。","黄鹤断矶头。","故人今不在。","旧江山，浑是新愁。","欲买桂花同载酒，终不似、少年游。"],"theme":"咏史怀古","theme2":["边塞征战"],"style":"雄浑","style2":[],"mood":"愁怨","mood2":[],"scene":["江","中秋"],"cats":{"抒情":["伤感","怀古"],"生活":["边塞"],"节日":["中秋节"]},"theme_conf":0.64},{"uid":"b2883592-eaf5-47a2-bd3d-7ded35fda71a","title":"谢友生遗端溪砚瓦","author":"李咸用","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["寻常濡翰次，恨不到端溪。","得自新知己，如逢旧解携。","玩余轻照乘，谢欲等悬黎。","静对胜凡客，闲窥忆好题。","娲天补剩石，昆剑切来泥。","著指痕犹湿，停旬水未低。","呵云润柱础，笔彩饮虹霓。","鹆眼工谙谬，羊肝士乍刲。","连澌光比镜，囚墨腻于䃜。","书信成池黑，吟须到日西。","正夸忧盗窃，将隐怯攀跻。","捧受同交印，矜持过秉珪。","草颠终近旭，嬾癖必无嵇。","用合缘鹦鹉，珍应负会稽。","贞姿还落落，寒韵或凄凄。","风月情相半，烟花思岂迷。","宜从方袋挈，枉把短行批。","浅小金为斗，泓澄玉作堤。","遇人依我惜，想尔与天齐。","□□□□□，行时秪独赍。"],"theme":"山水田园","theme2":[],"style":"清新","style2":["绮丽"],"mood":"愁怨","mood2":["恬淡"],"scene":[],"cats":{"抒情":["友情","感恩"],"天气":["彩虹"],"人生":["读书"]},"theme_conf":0.748},{"uid":"533e2212-7d88-4b6d-9f5f-a8d42f4d3627","title":"耳聋","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["生年鹖冠子，叹世鹿皮翁。","眼复几时暗，耳从前月聋。","猨鸣秋泪缺，雀噪晚愁空。","黄落惊山树，呼儿问朔风。"],"theme":"咏怀抒感","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","月","冬","山"],"cats":{"抒情":["伤感"],"四季":["秋天","冬天"],"天气":["写风"]},"theme_conf":0.88},{"uid":"42c8db32-a5d6-4d73-869d-36bd63632165","title":"九日五首 四","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["故里樊川菊，登高素浐源。","他时一笑后，今日几人存。","巫峡蟠江路，终南对国门。","系舟身万里，伏枕泪双痕。","为客裁乌帽，从儿具绿尊。","佳辰对群盗，愁绝更谁论。"],"theme":"羁旅思乡","theme2":["羁旅思乡"],"style":"沉郁","style2":["豪放"],"mood":"愁怨","mood2":[],"scene":["重阳"],"cats":{"抒情":["思乡","伤感"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.9},{"uid":"7242db95-41ec-4932-af0b-3d5d9b362775","title":"春日书情赠别司空曙","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["壮志随年尽，谋身意未安。","风尘交契阔，老大别离难。","腊近晴多暖，春迟夜却寒。","谁堪少兄弟，三十又无官。"],"theme":"送别","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["慷慨"],"scene":["春"],"cats":{"抒情":["离别"],"四季":["春天"],"人生":["励志","梦想"]},"theme_conf":0.875},{"uid":"f9747c4d-c1e5-4d2c-8bce-10889bba41b4","title":"樱桃曲","author":"顾况","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["百舌犹来上苑花，游人独自忆京华。","遥知寝庙尝新后，敕赐樱桃向几家。"],"theme":"讽喻刺世","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["相思"],"scene":[],"cats":{"抒情":["思念","孤独"],"植物":["桃花"]},"theme_conf":0.72},{"uid":"cp870b6030df582d","title":"高阳台","author":"张炎","dynasty":"宋","section":"宋词","form":"词","paragraphs":["接叶巢莺，平波卷絮，断桥斜日归船。","能几番游，看花又是明年。","东风且伴蔷薇住，到蔷薇、春已堪怜。","更凄然。","万绿西泠，一抹荒烟。","当年燕子知何处，但苔深韦曲，草暗斜川。","见说新愁，如今也到鸥边。","无心再续笙歌梦，掩重门、浅醉闲眠。","莫开帘。","怕见飞花，怕听啼鹃。"],"theme":"咏史怀古","theme2":["山水田园"],"style":"清新","style2":[],"mood":"愁怨","mood2":["恬淡"],"scene":["春","鸟"],"cats":{"抒情":["伤感","怀古"],"四季":["春天"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":0.82},{"uid":"d8d4a2e2-28ae-42d1-84ce-306a9b4df039","title":"听唱赤白桃李花","author":"李益","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["赤白桃李花，先皇在时曲。","欲向西宫唱，西宫[宫]树绿。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["花","春"],"cats":{"抒情":["怀古"],"四季":["春天"],"人物":["老师"],"植物":["桃花"]},"theme_conf":0.7},{"uid":"c0f731fe-706b-4e7e-a27c-db14c06686e9","title":"相和歌辞 江南曲","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["江南人家多橘树，吴姬舟上织白纻。","土地卑湿饶虫蛇，连木为牌入江住。","江村亥日长为市，落帆渡桥来浦里。","青莎覆城竹为屋，无井家家饮潮水。","长江午日酤春酒，高高酒旗悬江口。","倡楼两岸悬水栅，夜唱竹枝留北客。","江南风土欢乐多，悠悠处处尽经过。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["江","江南"],"cats":{"抒情":["思乡"],"山水":["江河","长江"],"生活":["写桥"]},"theme_conf":0.604},{"uid":"cp334c6d9b3adb62","title":"月下笛","author":"张炎","dynasty":"宋","section":"宋词","form":"词","paragraphs":["万里孤云，清游渐远，故人何处。","寒窗梦里，犹记经行旧时路。","连昌约略无多柳，第一是、难听夜雨。","谩惊回凄悄，相看烛影，拥衾谁语。","张绪。","归何暮。","半零落，依依断桥鸥鹭。","天涯倦旅。","此时心事良苦。","只愁重洒西州泪，问杜曲、人家在否。","恐翠袖、正天寒，犹倚梅花那树。"],"theme":"羁旅思乡","theme2":["咏史怀古"],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["月"],"cats":{"抒情":["思乡","伤感","怀古"],"山水":["西湖"],"天气":["月亮"],"人生":["读书"],"生活":["写桥"]},"theme_conf":0.416},{"uid":"efaaa86e-5628-40d3-a137-1ae8fcbe41b8","title":"新嫁娘词三首 三","author":"王建","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["三日入厨下，洗手作羹汤。","未谙姑食性，先遣小姑尝。"],"theme":"爱情相思","theme2":["闺情宫怨"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":[],"cats":{"抒情":["闺怨"]},"theme_conf":0.588},{"uid":"68a3e39c-58e3-4b5b-890a-22f1e3f1c185","title":"杂曲歌辞 夜夜曲","author":"王偃","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["北斗星移银汉低，班姬愁思凤城西。","青槐陌上人行绝，明月楼前乌夜啼。"],"theme":"闺情宫怨","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["夜","月"],"cats":{"抒情":["伤感","闺怨"],"天气":["月亮","星星"]},"theme_conf":0.95},{"uid":"bb111748-d8f1-4a5e-b618-b70272a7a642","title":"相和歌辞 江南曲","author":"李益","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["嫁得瞿塘贾，朝朝误妾期。","早知潮有信，嫁与弄潮儿。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["江南","江"],"cats":{"抒情":["闺怨"]},"theme_conf":1.0},{"uid":"cpbe9192b90bad20","title":"尉迟杯","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["隋堤路。","渐日晚、密霭生深树。","阴阴淡月笼沙，还宿河桥深处。","无情画舸，都不管、烟波隔南浦。","等行人、醉拥重衾，载将离恨归去。","因念旧客京华，长偎傍、疏林小槛欢聚。","冶叶倡条俱相识，仍惯见、珠歌翠舞。","如今向、渔村水驿，夜如岁、焚香独自语。","有何人、念我无，梦魂凝想鸳侣。"],"theme":"羁旅思乡","theme2":["送别","山水田园"],"style":"绮丽","style2":["冲淡"],"mood":"愁怨","mood2":["欢愉","孤寂"],"scene":["酒"],"cats":{"抒情":["离别","思乡","孤独"],"生活":["写桥"],"食物":["写酒"]},"theme_conf":0.361},{"uid":"c81a3a3f-0eec-4fe0-b482-40c50959b37e","title":"望雪","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["冻云宵徧岭，素雪晓凝华。","入牖千重碎，迎风一半斜。","不妆空散粉，无树独飘花。","萦空慙夕照，破彩谢晨霞。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["惆怅"],"scene":["雪"],"cats":{"抒情":["孤独"],"天气":["写雪"]},"theme_conf":0.531},{"uid":"e82ca232-9a56-4a68-acaa-b6e622fe2777","title":"登叶县故城谒沈诸梁庙","author":"李百药","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["总辔临秋原，登城望寒日。","烟霞共掩映，林野俱萧瑟。","楚塞郁不穷，吴山高渐出。","客行殊未已，沐澡期终吉。","椒桂奠芳樽，风云下虚室。","馆宇肃而静，神心康且逸。","伊我非真龙，勿惊疲朽质。"],"theme":"咏史怀古","theme2":[],"style":"沉郁","style2":[],"mood":"恬淡","mood2":[],"scene":["塞外","秋","酒"],"cats":{"抒情":["怀古"],"四季":["秋天"],"植物":["叶子"]},"theme_conf":0.548},{"uid":"e848498b-1ab8-48c7-8b3e-e98b5550b855","title":"苏端薛复筵简薛华醉歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["文章有神交有道，端复得之名誉早。","爱客满堂尽豪翰，开筵上日思芳草。","安得健步移远梅，乱插繁花向晴昊。","千里犹残旧冰雪，百壶且试开怀抱。","垂老恶闻战鼓悲，急觞为缓忧心捣。","少年努力纵谈笑，看我形容已枯槁。","坐中薛华善醉歌，歌辞自作风格老。","近来海内为长句，汝与山东李白好。","何刘沈谢力未工，才兼鲍昭愁绝倒。","诸生颇尽新知乐，万事终伤不自保。","气酣日落西风来，愿吹野水添金杯。"],"theme":"寄赠酬答","theme2":[],"style":"豪放","style2":["沉郁","清新"],"mood":"愁怨","mood2":["欢愉","悲怆"],"scene":["酒"],"cats":{"抒情":["伤感"],"天气":["写雪"],"食物":["写酒"]},"theme_conf":0.82},{"uid":"c76247eb-572b-4fa3-8d38-ab33fe686124","title":"江上柳送人","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["江柳断肠色，黄丝垂未齐。","人看几重恨，鸟入一枝低。","乡泪正堪落，与君又解携。","相思万里道，春去夕阳西。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["婉约","豪放"],"mood":"愁怨","mood2":["相思"],"scene":["江"],"cats":{"抒情":["思念","伤感"],"山水":["江河"],"植物":["柳树"]},"theme_conf":0.609},{"uid":"058db0d1-0656-4e8f-ac49-87622e16b19b","title":"题大庾岭北驿","author":"宋之问","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["阳月南飞雁，传闻至此回。","我行殊未已，何日复归来？江静潮初落，林昏瘴不开。","明朝望乡处，应见陇头梅。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":["恬淡"],"scene":["江","山","月"],"cats":{"抒情":["思念","思乡"]},"theme_conf":0.671},{"uid":"50cd4ba1-47b5-476b-9b7c-1b3bba01cad6","title":"夏日原西避暑寄吟友","author":"齐己","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["热烟疎竹古原西，日日乘凉此杖藜。","闲处雨声随霹雳，旱田人望隔虹霓。","蝉依独树干吟苦，鸟忆平川渴过齐。","别有相招好泉石，瑞花瑶草尽堪携。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":["孤寂","恬淡"],"scene":["夏"],"cats":{"抒情":["友情","思念","孤独"],"四季":["夏天"],"天气":["彩虹","太阳"]},"theme_conf":0.88},{"uid":"6ab9a8e7-1c8c-46bd-b852-7d7fa4451978","title":"谢张法曹万顷小山暇景见忆","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["乐道随去处，养和解朝簪。","茅堂近丹阙，佳致亦何深。","退食不趋府，忘机还在林。","清风乱流上，永日小山阴。","解箨雨中竹，将雏花际禽。","物华对幽寂，弦酌兼咏吟。","自昔仰高步，及兹劳所钦。","郢歌叨继组，知己复知音。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"冲淡","style2":[],"mood":"相思","mood2":["孤寂","恬淡"],"scene":["山"],"cats":{"抒情":["友情","思念","感恩"]},"theme_conf":0.425},{"uid":"47dbfc92-dd51-458f-859a-1953cde28460","title":"秋日作","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["端居值秋节，此日更愁辛。","寂寞无一事，蒿莱通四邻。","闭门生白发，回首忆青春。","岁月不相待，交游随众人。","云霄何处托，愚直有谁亲。","举酒聊自劝，穷通信尔身。"],"theme":"咏怀抒感","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂","相思"],"scene":["秋"],"cats":{"抒情":["思念","伤感","孤独"],"四季":["秋天"],"天气":["太阳"],"人物":["老师"],"人生":["青春"]},"theme_conf":0.9},{"uid":"baccf46a-41c4-4a0f-b90f-37cc35b04a64","title":"子夜吴歌 秋歌","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["长安一片月，万户捣衣声。","秋风吹不尽，总是玉关情。","何日平胡虏，良人罢远征。"],"theme":"闺情宫怨","theme2":["边塞征战"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["秋","月"],"cats":{"抒情":["思念","闺怨"],"四季":["秋天"]},"theme_conf":0.576},{"uid":"2ed9d032-88fc-465d-a637-3a344fcad426","title":"宿新安江深渡馆寄郑州王使君","author":"朱长文","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["霜飞十月中，摇落众山空。","孤馆闭寒木，大江生夜风。","赋诗忙有意，沈约在关东。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["江"],"cats":{"抒情":["孤独"],"山水":["江河","长江"]},"theme_conf":0.86},{"uid":"96b213f7-21b6-47a8-936c-39dde6ca7969","title":"相和歌辞 櫂歌行","author":"徐坚","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["櫂女饰银钩，新妆下翠楼。","霜丝青桂檝，兰栧紫霞舟。","水落金陵曙，风起洞庭秋。","扣船过曲浦，飞帆越回流。","影入桃花浪，香飘杜若洲。","洲长殊未返，萧散云霞晚。","日下大江平，烟生归岸远。","岸远闻潮波，争途游戏多。","因声赵津女，来听采菱歌。"],"theme":"咏史怀古","theme2":["羁旅思乡"],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["江","舟"],"cats":{"抒情":["思乡","怀古"],"四季":["秋天"],"山水":["长江"],"天气":["写云"]},"theme_conf":0.579},{"uid":"de9b1a7e-ae47-460e-9d7d-6798210877ff","title":"送友人入湘","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["闻说湘川路，年年苦雨多。","猨啼巫峡雨，月照洞庭波。","穷海人还去，孤城雁共过。","青山不可极，来往自蹉跎。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["江","雨","月","园林","鸟","山"],"cats":{"抒情":["友情","孤独"]},"theme_conf":0.778},{"uid":"a3aec75e-d67c-4a40-920a-c3ccbac03993","title":"秋日夔府咏怀奉寄郑监李宾客一百韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["绝塞乌蛮北，孤城白帝边。","飘零仍百里，消渴已三年。","雄劒鸣开匣，群书满系船。","乱离心不展，衰谢日萧然。","筋力妻孥问，菁华岁月迁。","登临多物色，陶冶赖诗篇。","峡束沧江起，岩排石树圆。","拂云霾楚气，朝海蹴吴天。","煮井为盐速，烧畬度地偏。","有时惊叠嶂，何处觅平川。","㶉𫛶双双舞，猕猿垒垒悬。","碧萝长似带，锦石小如钱。","春草何曾歇，寒花亦可怜。","猎人吹戍火，野店引山泉。","唤起搔头急，扶行几屐穿。","两京犹薄产，四海绝随肩。","幕府初交辟，郎官幸备员。","瓜时犹旅寓，萍泛苦夤缘。","药饵虚狼藉，秋风洒静便。","开襟驱瘴疠，明目扫云烟。","高宴诸侯礼，佳人上客前。","哀筝伤老大，华屋艳神仙。","南内开元曲，常时弟子传。","法歌声变转，满座涕潺湲。","吊影夔州僻，回肠杜曲煎。","即今龙厩水，莫带犬戎膻。","耿贾扶王室，萧曹拱御筵。","乘威灭蜂虿，戮力効鹰鹯。","旧物森犹在，凶徒恶未悛。","国须行战伐，人忆止戈鋋。","奴仆何知礼，恩荣错与权。","胡星一彗孛，黔首逐拘挛。","哀痛丝纶切，烦苛法令蠲。","业成陈始王，兆喜出于畋。","宫禁经纶密，台阶翊戴全。","熊罴载吕望，鸿雁美周宣。","侧听中兴主，长吟不世贤。","音徽一柱数，道里下牢千。","郑李光时论，文章并我先。","阴何尚清省，沈宋歘联翩。","律比昆仑竹，音知燥湿弦。","风流俱善价，惬当久忘筌。","置驿常如此，登龙盖有焉。","虽云隔礼数，不敢坠周旋。","高视收人表，虚心味道玄。","马来皆汗血，鹤唳必青田。","羽翼商山起，蓬莱汉阁连。","管宁纱帽净，江令锦袍鲜。","东郡时题壁，南湖日扣舷。","远游凌绝境，佳句染华牋。","每欲孤飞去，徒为百虑牵。","生涯已寥落，国步乃迍邅。","衾枕成芜没，池塘作弃捐。","别离忧怛怛，伏腊涕涟涟。","露菊班丰镐，秋蔬影涧瀍。","共谁论昔事，几处有新阡。","富贵空回首，喧争嬾著鞭。","兵戈尘漠漠，江汉月娟娟。","局促看秋燕，萧疎听晚蝉。","雕虫蒙记忆，烹鲤问沈绵。","卜羡君平杖，偷存子敬毡。","囊虚把钗钏，米尽坼花钿。","甘子阴凉叶，茅斋八九椽。","阵图沙北岸，市暨瀼西巅。","羁绊心常折，栖迟病即痊。","紫收岷岭芋，白种陆池莲。","色好梨胜颊，穰多栗过拳。","勅厨唯一味，求饱或三鳣。","儿去看鱼笱，人来坐马鞯。","缚柴门窄窄，通竹溜涓涓。","堑抵公畦棱，村依野庙壖。","缺篱将棘拒，倒石赖藤缠。","借问频朝谒，何如稳醉眠。","谁云行不逮，自觉坐能坚。","雾雨银章涩，馨香粉署妍。","紫鸾无近远，黄雀任翩翾。","困学违从众，明公各勉旃。","声华夹宸极，早晚到星躔。","恳谏留匡鼎，诸儒引服虔。","不逢输鲠直，会是正陶甄。","宵旰忧虞轸，黎元疾苦骈。","云台终日画，青简为谁编。","行路难何有，招寻兴已专。","由来具飞檝，𫏐拟控鸣弦。","身许双峰寺，门求七祖禅。","落帆追宿昔，衣褐向真诠。","安石名高晋，昭王客赴燕。","途中非阮籍，查上似张骞。","披拂云宁在，淹留景不延。","风期终破浪，水怪莫飞涎。","他日辞神女，伤春怯杜鹃。","淡交随聚散，泽国绕回旋。","本自依迦叶，何曾藉偓佺。","𬬻峰生转盻，橘井尚高褰。","东走穷归鹤，南征尽跕鸢。","晚闻多妙教，卒践塞前愆。","顾凯丹青列，头陀琬琰镌。","众香深黯黯，几地肃芊芊。","勇猛为心极，清羸任体孱。","金蓖空刮眼，镜象未离铨。"],"theme":"寄赠酬答","theme2":["山水田园","边塞征战","送别"],"style":"沉郁","style2":["幽峭","清新"],"mood":"欢愉","mood2":["恬淡","孤寂"],"scene":["秋","山","鸟","塞外"],"cats":{"抒情":["离别","孤独"],"四季":["秋天"],"天气":["太阳"],"人物":["女子"],"人生":["励志","战争"],"生活":["乡村","边塞"]},"theme_conf":0.95},{"uid":"3057f1b2-f2c5-482d-a9c8-b4d1a02125e9","title":"追酬故高蜀州人日见寄","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["自蒙蜀州人日作，不意清诗久零落。","今晨散帙眼忽开，迸泪幽吟事如昨。","呜呼壮士多慷慨，合沓高名动寥廊。","叹我凄凄求友篇，感时郁郁匡君略。","锦里春光空烂熳，瑶墀侍臣已冥莫。","潇湘水国傍鼋鼍，鄠杜秋天失雕鹗。","东西南北更谁论，白首扁舟病独存。","遥拱北辰缠寇盗，欲倾东海洗乾坤。","边塞西蕃最充斥，衣冠南渡多崩奔。","鼓瑟至今悲帝子，曳裾何处觅王门。","文章曹植波澜阔，服食刘安德业尊。","长笛谁能乱愁思，昭州词翰与招魂。"],"theme":"悼亡挽歌","theme2":["节令风俗"],"style":"悲慨","style2":["沉郁","绮丽"],"mood":"愁怨","mood2":[],"scene":["舟","塞外"],"cats":{"抒情":["伤感","悼亡"],"天气":["太阳"]},"theme_conf":0.88},{"uid":"90652c8c-0dbc-4eae-8e27-edd71d621b92","title":"汝坟别业","author":"祖咏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["失路农为业，移家到汝坟。","独愁常废卷，多病久离群。","鸟雀垂窻柳，虹霓出涧云。","山中无外事，樵唱有时闻。"],"theme":"山水田园","theme2":["送别","山水田园"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["山"],"cats":{"抒情":["离别","伤感","孤独"],"天气":["彩虹"]},"theme_conf":0.82},{"uid":"e84d461b-df53-426b-ba6a-848c87223cab","title":"故吏部郎中赠给事中韦公挽歌二首 一","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["神理今何在，斯人竟若斯。","颜渊徒有德，伯道且无儿。","白发今非老，青云数有奇。","谁言夕郎拜，翻向夜台悲。"],"theme":"悼亡挽歌","theme2":["送别"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["夜"],"cats":{"抒情":["伤感","悼亡"]},"theme_conf":0.98},{"uid":"f0dc1b19-1846-4837-937f-8c2ff37fcd18","title":"杂曲歌辞 长相思三首 三","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["美人在时花满堂，美人去后花余床。","床中绣被卷不寝，至今三载犹闻香。","香亦竟不灭，人亦竟不来。","相思黄叶落，白露点青苔。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["花"],"cats":{"抒情":["爱情","思念"],"人物":["女子"]},"theme_conf":0.77},{"uid":"49e8d65c-a254-42eb-9bb6-152ba3d3986e","title":"别韦五","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["徒然酌桮酒，不觉散人愁。","相识仍远别，欲归翻旅游。","夏云满郊甸，明月照河洲。","莫恨征途远，东看漳水流。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["酒","月","夏"],"cats":{"抒情":["离别","伤感"],"四季":["夏天"],"天气":["月亮"]},"theme_conf":0.721},{"uid":"947e5189-4418-49fd-898a-9f7118777a2e","title":"相和歌辞 挽歌","author":"孟云卿","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["草草门巷喧，涂车俨成位。","冥寞何所须，尽我生人意。","北邙路非远，此别终天地。","临穴频抚棺，至哀反无泪。","尔形未衰老，尔息犹童穉。","骨肉不可离，皇天若容易。","房帷即虚张，庭宇为哀次。","薤露歌若斯，人生尽如寄。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":["悲慨"],"mood":"悲怆","mood2":["愁怨"],"scene":[],"cats":{"抒情":["离别","伤感","悼亡"]},"theme_conf":0.99},{"uid":"70ea423c-d3c0-4870-885f-4ebadc8b8fcf","title":"久雨期王将军不至","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["天雨萧萧滞茅屋，空山无以慰幽独。","锐头将军来何迟，令我心中苦不足。","数看黄雾乱玄云，时听严风折乔木。","泉源泠泠杂猿狖，泥泞漠漠饥鸿鹄。","岁暮穷阴耿未已，人生会面难再得。","忆尔腰下铁丝箭，射杀林中雪色鹿。","前者坐皮因问毛，知子历险人马劳。","异兽如飞星宿落，应弦不碍苍山高。","安得突骑只五千，崒然眉骨皆尔曹。","走平乱世相催促，一豁明主正郁陶。","忆昔范增碎玉斗，未使吴兵著白袍。","昏昏阊阖闭氛祲，十月荆南雷怒号。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["雨"],"cats":{"抒情":["孤独"],"天气":["写雨"],"人生":["梦想"]},"theme_conf":0.558},{"uid":"cpdddf03096ffc13","title":"蝶恋花","author":"赵令","dynasty":"宋","section":"宋词","form":"词","paragraphs":["欲减罗衣寒未去。","不卷珠帘，人在深深处。","红杏枝头花几许。","啼痕止恨清明雨。","尽日沈烟香一缕。","宿酒醒迟，恼破春情绪。","飞燕又将归信误。","小屏风上西江路。"],"theme":"闺情宫怨","theme2":["节令风俗"],"style":"婉约","style2":["绮丽"],"mood":"愁怨","mood2":[],"scene":["花","清明"],"cats":{"抒情":["闺怨"],"节日":["清明节"]},"theme_conf":0.515},{"uid":"127a633c-22c0-45a6-af3f-21a31f284d5a","title":"曾游","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["泊舟古城下，高阁快登眺。","大江会彭蠡，群峰豁玄峤。","清影涵空明，黛色凝远照。","碑留太史书，词刻长公调。","绝粒感楚囚，丹衷犹照耀。","怀哉不可招，凭阑一悲啸。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["舟","楼","江","山"],"cats":{"抒情":["伤感"],"山水":["长江"]},"theme_conf":1.0},{"uid":"fc602fe2-1cc5-4eb6-a67e-8dc478e1579c","title":"题汉州西湖","author":"薛能","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["西湖天下名，可以濯吾缨。","况是携家赏，从妨半驿程。","尝茶春味渴，断酒晚怀清。","尽得幽人趣，犹嫌守吏迎。","重湌逢角暮，百事喜诗成。","坐阻湘江谪，谁为话政声。"],"theme":"山水田园","theme2":["咏物","羁旅思乡"],"style":"冲淡","style2":[],"mood":"欢愉","mood2":[],"scene":["江南","江"],"cats":{"抒情":["思乡"],"山水":["西湖"]},"theme_conf":0.7},{"uid":"cpfefb3d1fd306d5","title":"惜黄花慢","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["送客吴皋。","正试霜夜冷，枫落长桥。","望天不尽，背城渐杳，离亭黯黯，恨水迢迢。","翠香零落红衣老，暮愁锁、残柳眉梢。","念瘦腰。","沈郎旧日，曾系兰桡。","仙人凤咽琼箫。","怅断魂送远，九辨难招。","醉鬟留盼，小窗翦烛，歌云载恨，飞上银霄。","素秋不解随船去，败红趁、一叶寒涛。","梦翠翘。","怨鸿料过南谯。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":["秋","花"],"cats":{"抒情":["伤感"],"四季":["秋天"],"生活":["写桥"],"植物":["菊花"]},"theme_conf":0.497},{"uid":"992df222-c445-4925-a656-0caa4447d5bb","title":"夜上受降城闻笛","author":"李益","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["回乐峰前沙似雪，受降城下月如霜。","不知何处吹芦管，一夜征人尽望乡。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":["月","夜","冬"],"cats":{"抒情":["思乡"]},"theme_conf":0.718},{"uid":"080a9610-9c99-4c53-88ad-b299396e09cc","title":"寄刘方平大谷田家","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["故山闻独往，樵路忆相从。","冰结泉声绝，霜清野翠浓。","篱边颍阳道，竹外少姨峰。","日夕田家务，寒烟隔几重。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["相思"],"scene":["山"],"cats":{"抒情":["思念","孤独"],"生活":["田野"]},"theme_conf":0.557},{"uid":"d4bba55e-36f1-47d1-96af-eb87264434f6","title":"贺收复秦原诸州诗","author":"白敏中","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["一诏皇城四海颁，丑戎无数束身还。","戍楼吹笛人休战，牧野嘶风马自闲。","河水九盘收数曲，天山千里锁诸关。","西边北塞今无事，为报东南夷与蛮。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["塞外","楼","山"],"cats":{"抒情":["爱国"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.631},{"uid":"c2f5bd6f-76a1-4d3f-b5d7-81d81b6c6190","title":"校猎曲","author":"马戴","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["楚子畋郊野，布罟笼天涯。","浮云张作罗，万草结成罝。","意在绝飞鸟，臂弓腰镆鎁。","远将射句践，次欲诛夫差。","壮志一朝尽，他□□繁华。","当时能猎贤，保国兼保家。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":[],"cats":{"抒情":["思乡"],"人生":["励志","梦想"]},"theme_conf":0.636},{"uid":"e392bb57-06bc-4c4f-946b-5423d9168e5e","title":"和微之诗二十三首 和我年三首 三","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["我年五十七，荣名得非少。","报国竟何如，谋身犹未了。","昔尝速官谤，恩大而惩小。","一黜鹤辞轩，七年鱼在沼。","将枯鳞再跃，经铩翮重矫。","白日上昭昭，青云高渺渺。","平生颇同病，老大宜相晓。","紫绶足可荣，白头不为夭。","夙怀慕箕颍，晚节期松筿。","何当阙下来，同拜陈情表。"],"theme":"讽喻刺世","theme2":[],"style":"沉郁","style2":["婉约"],"mood":"慷慨","mood2":[],"scene":[],"cats":{"抒情":["爱国"]},"theme_conf":1.0},{"uid":"60de5a95-c758-49be-ad0a-380712d15cb3","title":"杂曲歌辞 少年行","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["射飞夸侍猎，行乐爱联镳。","荐枕青娥艳，鸣鞭白马骄。","曲房珠翠合，深巷管弦调。","日晚春风里，衣香满路飘。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"人生":["青春"]},"theme_conf":0.65},{"uid":"31e9a6b0-5035-4b1b-a9d3-ff1c279f53b6","title":"杂诗 十三","author":"无名氏","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["近寒食雨草萋萋，著麦苗风柳映堤。","早是有家归未得，杜鹃休向耳边啼。"],"theme":"羁旅思乡","theme2":["羁旅思乡"],"style":"清新","style2":[],"mood":"愁怨","mood2":[],"scene":["清明"],"cats":{"抒情":["思乡"],"节日":["寒食节","清明节"]},"theme_conf":0.95},{"uid":"de08789e-f931-4c88-aece-d70d5c5aa197","title":"送荀道士归庐山","author":"李端","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["先生归有处，欲别笑无言。","绿水到山口，青林连洞门。","月明寻石路，云霁望花源。","早晚还乘鹤，悲歌向故园。"],"theme":"送别","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["欢愉"],"scene":["山"],"cats":{"抒情":["思乡","伤感"],"山水":["庐山"]},"theme_conf":0.522},{"uid":"24f9e8b4-e32d-49e7-af89-50e05880b662","title":"雨","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["行云递崇高，飞雨霭而至。","潺潺石间溜，汩汩松上驶。","亢阳乘秋热，百谷皆已弃。","皇天德泽降，焦卷有生意。","前雨伤卒暴，今雨喜容易。","不可无雷霆，间作鼓增气。","佳声达中宵，所望时一致。","清霜九月天，髣髴见滞穗。","郊扉及我私，我圃日苍翠。","恨无抱瓮力，庶减临江费。"],"theme":"山水田园","theme2":[],"style":"雄浑","style2":[],"mood":"欢愉","mood2":["愁怨"],"scene":["雨","秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"天气":["写雨"]},"theme_conf":1.0},{"uid":"6ecbed64-2409-4f6d-ade3-ccfec85ff92c","title":"梅雨","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["梅实迎时雨，苍茫值晚春。","愁深楚猿夜，梦断越鸡晨。","海雾连南极，江云暗北津。","素衣今尽化，非为帝京尘。"],"theme":"山水田园","theme2":[],"style":"雄浑","style2":[],"mood":"愁怨","mood2":[],"scene":["雨"],"cats":{"抒情":["伤感"],"天气":["写雨"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"b84b8b0b-9447-467f-819f-0ddf0f00a03a","title":"相和歌辞 饮马长城窟行","author":"王翰","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["长安少年无远图，一生惟羡执金吾。","骐𬴊前殿拜天子，走马为君西击胡。","胡沙猎猎吹人面，汉虏相逢不相见。","遥闻鼙鼓动地来，传道单于夜犹战。","此时顾恩宁顾身，为君一行摧万人。","壮士挥戈回白日，单于溅血染朱轮。","回来饮马长城窟，长安道傍多白骨。","问之耆老何代人，云是秦王筑城卒。","黄昏塞北无人烟，鬼哭啾啾声沸天。","无罪见诛功不赏，孤魂流落此城边。","当昔秦王按劒起，诸侯膝行不敢视。","富国彊兵二十年，筑怨兴徭九千里。","秦王筑城何太愚，天实亡秦非北胡。","一朝祸起萧墙内，渭水咸阳不复都。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["悲慨"],"mood":"孤寂","mood2":["悲怆"],"scene":["夜","塞外"],"cats":{"抒情":["孤独"],"人生":["战争"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.803},{"uid":"2ece861e-f4da-4663-9ca7-22ed69e049dd","title":"献刘济","author":"李益","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["草绿古燕州，莺声引独游。","雁归天北畔，春尽海西头。","向日花偏落，驰年水自流。","感恩知有地，不上望京楼。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["鸟","春"],"cats":{"抒情":["孤独","感恩"],"四季":["春天"]},"theme_conf":0.92},{"uid":"cp266b10b82b6e56","title":"木兰花・玉楼春","author":"晏几道","dynasty":"宋","section":"宋词","form":"词","paragraphs":["秋千院落重帘暮。","彩笔闲来题绣户。","墙头丹杏雨馀花，门外绿杨风后絮。","朝云信断知何处。","应作襄王春梦去。","紫骝认得旧游踪，嘶过画桥东畔路。"],"theme":"闺情宫怨","theme2":["闲适隐逸"],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["春","花","楼"],"cats":{"抒情":["闺怨"],"四季":["春天"],"生活":["写桥"]},"theme_conf":0.565},{"uid":"5c676620-1448-4ee7-815d-35512077d8ad","title":"郑典设自施州归","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["吾怜荥阳秀，冒暑初有适。","名贤慎所出，不肯妄行役。","旅兹殊俗远，竟以屡空迫。","南谒裴施州，气合无险僻。","攀援悬根木，登顿入天石。","青山自一川，城郭洗忧戚。","听子话此邦，令我心悦怿。","其俗则纯朴，不知有主客。","温温诸侯门，礼亦如古昔。","敕厨倍常羞，杯盘颇狼藉。","时虽属丧乱，事贵赏匹敌。","中宵惬良会，裴郑非远戚。","群书一万卷，博涉供务隙。","他日辱银钩，森疎见矛戟。","倒屣喜旋归，画地求所历。","乃闻风土质，又重田畴辟。","刺史似寇恂，列郡宜竞惜。","北风吹瘴疠，羸老思散策。","渚拂蒹葭塞，峤穿萝茑幂。","此身仗儿仆，高兴潜有激。","孟冬方首路，强饭取崖壁。","叹尔疲驽骀，汗沟血不赤。","终然备外饰，驾驭何所益。","我有平肩舆，前途犹准的。","翩翩入鸟道，庶脱蹉跌厄。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"沉郁","style2":["幽峭","冲淡"],"mood":"欢愉","mood2":[],"scene":["塞外","冬","夏"],"cats":{"抒情":["思乡"],"四季":["夏天","冬天"],"人生":["读书"],"生活":["边塞"]},"theme_conf":0.593},{"uid":"e4dc9fac-1160-45b6-8182-51829ac15f72","title":"河南白尹有喜崔宾客归洛兼见怀长句因而继和","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["几年侍从作名臣，却向青云索得身。","朝士忽为方外士，主人仍是眼中人。","双鸾游处天京好，五马行时海峤春。","遥羡光阴不虚掷，肯令丝竹暂生尘。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"人生":["时光"]},"theme_conf":1.0},{"uid":"1c084d0f-76cc-4294-bd80-4e8672338d39","title":"和梦游春诗一百韵","author":"白居易","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["昔君梦游春，梦游仙山曲。","怳若有所遇，似惬平生欲。","因寻菖蒲水，渐入桃花谷。","到一红楼家，爱之看不足。","池流渡清泚，草嫩蹋绿蓐。","门柳暗全低，檐樱红半熟。","转行深深院，过尽重重屋。","乌龙卧不惊，青鸟飞相逐。","渐闻玉珮响，始辨珠履躅。","遥见窗下人，娉婷十五六。","霞光抱明月，莲艳开初旭。","缥缈云雨仙，氛氲兰麝馥。","风流薄梳洗，时世宽妆束。","袖輭异文绫，裾轻单丝縠。","裙腰银线压，梳掌金筐蹙。","带襭紫蒲萄，袴花红石竹。","凝情都未语，付意微相瞩。","眉敛远山青，鬟低片云绿。","帐牵翡翠带，被解鸳鸯襆。","秀色似堪餐，秾华如可掬。","半卷锦头席，斜铺绣腰褥。","朱唇素指匀，粉汗红緜扑。","心惊睡易觉，梦断魂难续。","笼委独栖禽，劒分连理木。","存诚期有感，誓志贞无黩。","京洛八九春，未曾花里宿。","壮年徒自弃，佳会应无复。","鸾歌不重闻，凤兆从兹卜。","韦门女清贵，裴氏甥贤淑。","罗扇夹花灯，金鞍攒绣毂。","既倾南国貌，遂坦东床腹。","刘阮心渐忘，潘杨意方睦。","新修履信第，初食尚书禄。","九酝备圣贤，八珍穷水陆。","秦家重萧史，彦辅怜卫叔。","朝馔馈独盘，夜醪倾百斛。","亲宾盛辉赫，妓乐纷晔煜。","宿醉才解酲，朝欢俄枕曲。","饮过君子争，令甚将军酷。","酩酊歌鹧鸪，颠狂舞鸲鹆。","月流春夜短，日下秋天速。","谢傅隙过驹，萧娘风过烛。","全凋蕣花折，半死梧桐秃。","暗镜对孤鸾，哀弦留寡鹄。","凄凄隔幽显，冉冉移寒燠。","万事此时休，百身何处赎。","提携小儿女，将领旧姻族。","再入朱门行，一傍青楼哭。","枥空无廐马，水涸失池[鹜]。","摇落废井梧，荒凉故篱菊。","莓苔上几阁，尘土生琴筑。","舞榭缀蟏蛸，歌梁聚蝙蝠。","嫁分红粉妾，卖散苍头仆。","门客思徬徨，家人泣吚噢。","心期正萧索，宦序仍拘跼。","怀策入崤函，驱车辞郏鄏。","逢时念既济，聚学思大畜。","端详筮仕蓍，磨拭穿杨镞。","始从讐校职，首中贤良目。","一拔侍瑶墀，再升纡绣服。","誓酬君王宠，愿使朝廷肃。","密勿奏封章，清明操宪牍。","鹰鞲中病下，豸角当邪触。","纠谬静东周，申冤动南蜀。","危言诋阍寺，直气忤钧轴。","不忍曲作钩，乍能折为玉。","扪心无媿畏，腾口有谤讟。","只要明是非，何曾虞祸福。","车摧太行路，劒落酆城狱。","襄汉问修途，荆蛮指殊俗。","谪为江府掾，遣事荆州牧。","趋走谒麾幢，喧烦视鞭朴。","簿书常自领，缧囚每亲鞫。","竟日坐官曹，经旬旷休沐。","宅荒渚宫草，马瘦畬田粟。","薄俸等涓毫，微官同桎梏。","月中照形影，天际辞骨肉。","鹤病翅羽垂，兽穷爪牙缩。","行看须间白，谁劝杯中绿。","时伤大野麟，命问长沙𫛳。","夏梅山雨渍，秋瘴江云毒。","巴水白茫茫，楚山青簇簇。","吟君七十韵，是我心所蓄。","既去诚莫追，将来幸前勗。","欲除忧恼病，当取禅经读。","须悟事皆空，无令念将属。","请思游春梦，此梦何闪倏。","艳色即空花，浮生乃焦谷。","良姻在嘉偶，顷克为单独。","入仕欲荣身，须臾成黜辱。","合者离之始，乐兮忧所伏。","愁恨僧祇长，欢荣刹那促。","觉悟因傍喻，迷执由当局。","膏明诱暗蛾，阳焱奔痴鹿。","贪为苦聚落，爱是悲林麓。","水荡无明波，轮回死生辐。","尘应甘露洒，垢待醍醐浴。","障要智灯烧，魔须慧刀戮。","外熏性易染，内战心难衂。","法句与心王，期君日三复。"],"theme":"寄赠酬答","theme2":["哲理悟道"],"style":"绮丽","style2":[],"mood":"悲怆","mood2":["愁怨","孤寂"],"scene":["春","酒","元宵","月","楼"],"cats":{"抒情":["爱情","伤感","孤独"],"四季":["春天"],"天气":["月亮"],"人物":["儿童"],"人生":["哲理","梦想"],"节日":["元宵节","清明节"]},"theme_conf":0.9},{"uid":"1ab8a232-27bf-4de3-b67c-28e4735fea7f","title":"横吹曲辞 长安道","author":"韦应物","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["汉家宫殿含云烟，两宫十里相连延。","晨霞出没弄丹阙，春雨依微自甘泉。","春雨依微春尚早，长安贵游爱芳草。","宝马横来下建章，香车却转避驰道。","贵游谁最贵，卫霍世难比。","何能蒙主恩？幸遇边尘起。","归来甲第拱皇居，朱门峨峨临九衢。","中有流苏合欢之宝帐，一百二十凤皇罗列含明珠。","下有锦铺翠被之粲烂，博山吐香五云散。","丽人绮阁情飘飖，头上鸳钗双翠翘。","低鬟曳袖回春雪，聚黛一声愁碧霄。","山珍海错弃藩篱，烹犊炰羔如折葵。","既请列侯封部曲，还将金印授庐儿。","欢荣若此何所苦，但苦白日西南驰。"],"theme":"山水田园","theme2":["闺情宫怨","讽喻刺世"],"style":"绮丽","style2":[],"mood":"愁怨","mood2":["恬淡","欢愉"],"scene":["春","花","雪","雨"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"人物":["女子"]},"theme_conf":0.429},{"uid":"d5082efe-beda-482e-8f57-f88241cdda54","title":"奉陪韦中丞使君游鹤林寺","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["古寺传灯久，层城闭阁闲。","香花同法侣，旌斾入深山。","寒磬虚空里，孤云起灭间。","谢公忆高卧，徒御欲东还。"],"theme":"哲理悟道","theme2":["山水田园","应制干谒"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["鸟","花","楼","山"],"cats":{"抒情":["孤独"],"动物":["写鸟"]},"theme_conf":0.37},{"uid":"a42d87f4-4427-4933-90d9-d25d0192f409","title":"元和甲午岁诏书尽征江湘逐客余自武陵赴京宿于都亭有怀续来诸君子","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["雷雨江山起卧龙，武陵樵客蹑仙踪。","十年楚水枫林下，今夜初闻长乐钟。"],"theme":"羁旅思乡","theme2":["山水田园","咏史怀古"],"style":"雄浑","style2":[],"mood":"欢愉","mood2":[],"scene":["江"],"cats":{"抒情":["思乡","怀古"],"山水":["江河"],"植物":["桃花"]},"theme_conf":0.359},{"uid":"e3c39438-5647-430e-b814-1318cde0ffb1","title":"琴曲歌辞 别鹤","author":"王建","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["主人一去池水绝，池鹤散飞不相别。","青天漫漫碧海重，知向何山风雪中？","万里虽然音影在，向心终是死生同。","池边巢破松树死，树头年年乌生子。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"悲怆","mood2":[],"scene":["鸟"],"cats":{"抒情":["离别"],"动物":["写鸟"]},"theme_conf":0.667},{"uid":"6113d640-c2f5-4e11-aaae-0368e78f3fb6","title":"七夕","author":"权德舆","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["佳期人不见，天上喜新秋。","玉珮沾新露，香车渡浅流。","东西一水隔，迢遰两年愁。","别有穿针处，微明月暎楼。"],"theme":"节令风俗","theme2":[],"style":"婉约","style2":["清新"],"mood":"愁怨","mood2":["欢愉"],"scene":["七夕","月"],"cats":{"抒情":["伤感"],"天气":["月亮"],"节日":["七夕节"]},"theme_conf":0.88},{"uid":"cp44b029899def35","title":"疏影","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["苔枝缀玉。","有翠禽小小，枝上同宿。","客里相逢，篱角黄昏，无言自倚修竹。","昭君不惯胡沙远，但暗忆、江南江北。","想佩环、月夜归来，化作此花幽独。","犹记深宫旧事，那人正睡里，飞近蛾绿。","莫似春风，不管盈盈，早与安排金屋。","还教一片随波去，又却怨、玉龙哀曲。","等恁时、重觅幽香，已入小窗横幅。"],"theme":"闺情宫怨","theme2":["山水田园","羁旅思乡"],"style":"绮丽","style2":["婉约","冲淡"],"mood":"愁怨","mood2":["孤寂","悲怆"],"scene":["夜","江南","花","春","江"],"cats":{"抒情":["思乡","孤独","闺怨"],"四季":["春天"],"植物":["梅花"]},"theme_conf":0.373},{"uid":"83e70b6e-ff59-4a3b-8e81-249ab0cda0c3","title":"月下独酌四首 一","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["花间一壶酒，独酌无相亲。","举杯邀明月，对影成三人。","月既不解饮，影徒随我身。","暂伴月将影，行乐须及春。","我歌月裴回，我舞影零乱。","醒时同交欢，醉后各分散。","永结无情游，相期邈云汉。"],"theme":"闲适隐逸","theme2":["节令风俗"],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["酒","月"],"cats":{"抒情":["孤独"],"天气":["月亮"],"食物":["写酒"]},"theme_conf":0.88},{"uid":"9a844318-403b-47ed-9b46-99508519957a","title":"宣武军镇作","author":"王彦威","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["天兵十万勇如貔，正是酬恩报国时。","汴水波澜喧鼓角，隋堤杨柳拂旌旗。","前驱红斾关西将，坐间青娥赵国姬。","寄语长安旧冠盖，麤官到底是男儿。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":[],"cats":{"抒情":["爱国"]},"theme_conf":0.71},{"uid":"18801489-9f1d-4d5d-9618-66e682d3fc54","title":"寄司空曙","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["细雨柴门生远愁，向来诗句若为酬。","林花落处频中酒，海燕飞时独倚楼。","北郭晚晴山更远，南塘春尽水争流。","可能相别还相忆，莫遣杨花笑白头。"],"theme":"寄赠酬答","theme2":[],"style":"冲淡","style2":["沉郁","婉约"],"mood":"孤寂","mood2":["愁怨"],"scene":["雨"],"cats":{"抒情":["伤感","孤独"],"天气":["写雨"],"人物":["老师"]},"theme_conf":0.92},{"uid":"b6ccc575-b4f1-4027-b442-811fc39a451d","title":"重忆山居六首 罗浮山","author":"李德裕","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["龙伯钓鼇时，蓬莱一峰坼。","飞来碧海畔，遂与三山隔。","其下多长溪，潺湲淙乱石。","知君分如此，赠逾荆山璧。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"相思","mood2":[],"scene":["山"],"cats":{"抒情":["思念"],"植物":["梅花"]},"theme_conf":0.572},{"uid":"88e98bed-27fa-4dbe-8d6e-e7cb8c3e4d97","title":"八月十五夜赠张功曹","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["纤云四卷天无河，清风吹空月舒波。","沙平水息声影绝，一桮相属君当歌。","君歌声酸辞且苦，不能听终泪如雨。","洞庭连天九疑高，蛟龙出没猩鼯号。","十生九死到官所，幽居默默如藏逃。","下床畏蛇食畏药，海气湿蛰熏腥臊。","昨者州前搥大鼓，嗣皇继圣登夔臯。","赦书一日行万里，罪从大辟皆除死。","迁者追廻流者还，涤瑕荡垢清朝班。","州家申名使家抑，坎轲祗得移荆蛮。","判司卑官不堪说，未免捶楚尘埃间。","同时辈流多上道，天路幽险难追攀。","君歌且休听我歌，我歌今与君殊科。"],"theme":"寄赠酬答","theme2":["闲适隐逸"],"style":"豪放","style2":["幽峭"],"mood":"愁怨","mood2":["悲怆"],"scene":["月","中秋","夜"],"cats":{"抒情":["伤感"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.9},{"uid":"edca8c83-0380-4c83-af64-371da14c6611","title":"和令狐相公谢太原李侍中寄蒲桃","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["珍果出西域，移根到北方。","昔年随汉使，今日寄梁王。","上相芳缄至，行台绮席张。","鱼鳞含宿润，马乳带残霜。","染指铅粉腻，满喉甘露香。","酝成十日酒，味敌五云桨。","咀嚼停金盏，称嗟响画堂。","慙非末至客，不得一枝尝。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["花","酒"],"cats":{"抒情":["感恩"],"植物":["桃花"]},"theme_conf":0.83},{"uid":"cp0ddc73d1a3910a","title":"竹马子・竹马儿","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["登孤垒荒凉，危亭旷望，静临烟渚。","对雌霓挂雨，雄风拂槛，微收烦暑。","渐觉一叶惊秋，残蝉噪晚，素商时序。","览景想前欢，指神京，非雾非烟深处。","向此成追感，新愁易积，故人难聚。","凭高尽日凝伫。","赢得消魂无语。","极目霁霭霏微，暝鸦零乱，萧索江城暮。","南楼画角，又送残阳去。"],"theme":"送别","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂","欢愉"],"scene":["雨","楼","江","秋","夏"],"cats":{"抒情":["友情","伤感","孤独"],"四季":["夏天","秋天"],"动物":["写马"],"植物":["竹子"]},"theme_conf":0.639},{"uid":"89150285-38e4-480d-87d6-95db4cb9a4ed","title":"自淇涉黄河途中作十三首 四","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["南登滑台上，却望河淇间。","竹树夹流水，孤城对远山。","念兹川路阔，羡尔沙鸥闲。","长想别离处，犹无音信还。"],"theme":"送别","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"孤寂","mood2":["恬淡","相思"],"scene":["江","山"],"cats":{"抒情":["离别","孤独"],"山水":["江河","黄河"]},"theme_conf":0.455},{"uid":"2c9a2809-eb92-46db-bdea-5c6071efe4f1","title":"梦好梨花歌","author":"王建","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["薄薄落落雾（别本作「路」）不分，梦中唤作梨花云。","瑶池水光蓬莱雪，青叶白花相次发。","不从地上生枝柯，合在天头遶宫阙。","天风微微吹不破，白艳却愁香涴露。","玉房彩女齐看来，错认仙山鹤飞过。","落花散粉飘满空，梨花颜色同不同。","眼穿臂短取不得，取得亦如从梦中。","无人为我解此梦，梨花一曲心珍重。","（见宋张邦基《墨庄漫录》卷六）（按：《墨庄漫录》：「东坡作梅花词云：『高情已逐晓云空，不与梨花同梦。","』注云：『唐王建有《梦看梨花云诗》。","』予求王建诗，行世甚少，唯印行本一卷，乃无此篇。","后得之于晏元献《类要》中。","后又得建全集七卷，乃得全篇，题云《梦好梨花歌》。","〖诗略〗或误传为王昌龄，非也。","」另参本书卷九王昌龄诗附按。","）。"],"theme":"游仙梦幻","theme2":[],"style":"清新","style2":["婉约"],"mood":"孤寂","mood2":["相思","愁怨"],"scene":["花"],"cats":{"抒情":["伤感","孤独"],"人生":["梦想","读书"],"植物":["梨花"]},"theme_conf":0.776},{"uid":"1fb10ea4-f46c-4c08-bd06-f039f1907be6","title":"杂诗三首 三","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["闻道黄龙戍，频年不解兵。","可怜闺里月，长在汉家营。","少妇今春意，良人昨夜情。","谁能将旗鼓，一为取龙城。"],"theme":"边塞征战","theme2":["爱情相思","闺情宫怨"],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":["春","月","夜"],"cats":{"抒情":["闺怨"],"四季":["春天"]},"theme_conf":0.418},{"uid":"152b72c8-0e20-4cf2-9877-c843aeab9cd0","title":"送谢十二判官","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["四牡驱驰千里余，越山稠叠海林疎。","不辞终日离家远，应为刘公一纸书。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江南","山"],"cats":{"抒情":["感恩"]},"theme_conf":1.0},{"uid":"19f067ad-0289-4474-a94a-fe5117350987","title":"求自试","author":"窦常","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["仙禁祥云合，高梧彩凤游。","沈冥求自试，通鉴果蒙收。","文墨悲无位，诗书误白头。","陈王抗表日，毛遂请行秋。","双剑曾埋狱，司空问斗牛。","希垂拂拭惠，感激愿相投。"],"theme":"游仙梦幻","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"人生":["读书"]},"theme_conf":0.65},{"uid":"4b40ffb4-d390-4d54-a701-87cc76906bcf","title":"哭吕衡州六首 三","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["白马双旌队，青山八阵图。","请缨期系虏，枕草誓捐躯。","势激三千壮，年应四十无。","遥闻不瞑目，非是不怜吴。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":[],"mood":"慷慨","mood2":[],"scene":["山","江南"],"cats":{"抒情":["悼亡","爱国"]},"theme_conf":0.97},{"uid":"8a9195a1-6b5d-4054-b785-21350c64f373","title":"谢王郎中见赠琴鹤","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["此琴等焦尾，此鹤方胎生。","赴节何徘徊，理感物自幷。","独立江海上，一弹天地清。","朱弦动瑶华，白羽飘玉京。","因想羡门辈，眇然四体轻。","子乔翔邓林，王母游层城。","忽如启灵署，鸾凤相和鸣。","何由玉女床，去食琅玕英。"],"theme":"咏物","theme2":["闲适隐逸"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["鸟"],"cats":{"抒情":["孤独","感恩"],"动物":["写鸟"]},"theme_conf":0.76},{"uid":"8df8e94b-ffe4-4930-af4c-491d7cb04651","title":"奉和中书舍人贾至早朝大明宫","author":"岑参","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["鸡鸣紫陌曙光寒，莺啭皇州春色阑。","金阙晓钟开万户，玉阶仙仗拥千官。","花迎劒珮星初落，柳拂旌旗露未干。","独有凤皇池上客，阳春一曲和皆难。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":["绮丽"],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独"],"四季":["春天"]},"theme_conf":0.95},{"uid":"4d16ccaa-a7a3-45e6-b0d9-6e94e3e1d99d","title":"缆船苦风戏题四韵奉简郑十三判官","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["楚岸朔风疾，天寒鸧鸹呼。","涨沙霾草树，舞雪渡江湖。","吹帽时时落，维舟日日孤。","因声置驿外，为觅酒家垆。"],"theme":"寄赠酬答","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["愁怨"],"scene":["舟","冬","江"],"cats":{"抒情":["孤独"],"四季":["冬天"],"天气":["写风"]},"theme_conf":0.86},{"uid":"60f3c484-4e4f-4612-9f93-e753c7c67c02","title":"送大理封主簿五郎亲事不合却赴通州主簿前阆州贤子余与主簿平章郑氏女子垂欲纳郑氏伯父京书至女子已前许他族亲事遂停","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["禁脔去东床，趋庭赴北堂。","风波空远涉，琴瑟几虚张。","渥水出骐骥，昆山生凤皇。","两家诚款款，中道许苍苍。","颇谓秦晋匹，从来王谢郎。","青春动才调，白首缺辉光。","玉润终孤立，珠明得暗藏。","余寒折花卉，恨别满江乡。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["沉郁","冲淡"],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独"],"四季":["春天"],"人物":["女子","父亲"],"人生":["青春"]},"theme_conf":0.524},{"uid":"dc52501e-3598-4ebf-bba8-7bf0c3a9a172","title":"归阳萧寺有丁行者能修无生忍担水施僧况归命稽首作诗","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["化佛示持帚，仲尼称执鞭。","列生御风归，饲豕如人焉。","曹溪第六祖，踏碓逾三年。","伊人自何方，长绶趋遥泉。","开士行何苦，双瓶胝两肩。","萧寺百余僧，东厨正扬烟。","露足沙石裂，外形巾褐穿。","若其有此身，岂得安稳眠。","独出违顺境，不为寒暑还。","大圣于其中，领我心之虔。","万法常空灭，无生因忍全。","一国一释迦，一灯分百千。","永愿遗世知，现身弥勒前。","潜容偏虚空，灵响不可传。","智慧舍利佛，神通自干连。","阿若楚系简帛陈如，迦叶迦旜延。","左右二菩萨，文殊幷普贤。","身披六铢衣，亿刦为大僊。","宝塔宝楼阁，重簷交梵天。","譬如一明珠，共赞光白圆。","天魔波[旬]等，降伏金刚坚。","野叉罗刹鬼，亦赦尘垢缠。","乃致金翅鸟，吞龙护洪渊。","一十一众中，身意皆快然。","八河注大海，中有楞伽船。","佛法付国王，平等无颇偏。","天子事端拱，大臣行其权。","玉堂无蝇飞，五月冰凛筵。","尽力答明主，犹自招罪愆。","九族无白身，百花动婵娟。","神圣恶如此，物华不能妍。","禄山一微胡，驱马来自燕。","宛彼宫阙丽，如何犬羊膻。","苦哉千万人，流血成丹川。","此辈之死后，镬汤所熬煎。","业风吹其魂，猛火烧其烟。","独有丁行者，无忧树枝边。","市头盲老人，长者乞一钱。","韬照多密用，为君吟此篇。"],"theme":"佛道禅颂","theme2":[],"style":"绮丽","style2":["幽峭"],"mood":"孤寂","mood2":["愁怨"],"scene":["楼","鸟","中秋","夏"],"cats":{"抒情":["孤独"],"四季":["夏天"],"天气":["月亮"],"人生":["哲理"],"节日":["中秋节"]},"theme_conf":0.97},{"uid":"221ebe63-3aa2-4662-9c8e-f303d99700bb","title":"送志弥师往淮南","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["已能持律藏，复去礼禅亭。","长老偏摩顶，时流尚诵经。","独行寒野旷，旅宿远山青。","眷属空相望，鸿飞已杳冥。"],"theme":"送别","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["山"],"cats":{"抒情":["孤独"],"人生":["梦想"]},"theme_conf":0.588},{"uid":"a7b8e17f-ee93-4bdc-a144-b1ba5ab32bb5","title":"行路难三首 三","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["有耳莫洗颍川水，有口莫食首阳蕨。","含光混世贵无名，何用孤高比云月。","吾观自古贤达人，功成不退皆殒身。","子胥既弃吴江上，屈原终投湘水滨。","陆机雄才岂自保，李斯税驾苦不早。","华亭鹤唳讵可闻，上蔡苍鹰何足道。","君不见吴中张翰称达生，秋风忽忆江东行。","且乐生前一杯酒，何须身后千载名。"],"theme":"民生疾苦","theme2":["哲理悟道"],"style":"旷达","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["酒","端午","秋"],"cats":{"抒情":["思念","孤独"],"四季":["秋天"],"节日":["端午节"]},"theme_conf":0.601},{"uid":"c9e8cd22-8ed0-407b-a20a-8c4650f1fa2e","title":"燕子来舟中作","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["湖南为客动经春，燕子衔泥两度新。","旧入故园常识主，如今社日远看人。","可怜处处巢君室，何异飘飘托此身。","暂语船樯还起去，穿花落水益沾巾。"],"theme":"羁旅思乡","theme2":["山水田园","节令风俗"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["舟","鸟"],"cats":{"抒情":["思乡"],"动物":["写鸟"]},"theme_conf":0.45},{"uid":"982f789a-c377-4b64-808a-56f36abf9ff0","title":"可叹","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["天上浮云如白衣，斯须改变如苍狗。","古往今来共一时，人生万事无不有。","近者抉眼去其夫，河东女儿身姓柳。","丈夫正色动引经，酆城客子王季友。","群书万卷常暗诵，孝经一通看在手。","贫穷老瘦家卖屐，好事就之为携酒。","豫章太守高帝孙，引为宾客敬颇久。","闻道三年未曾语，小心恐惧闭其口。","太守得之更不疑，人生反复看亦丑。","明月无瑕岂容易，紫气郁郁犹冲斗。","时危可仗真豪俊，二人得置君侧否。","太守顷者领山南，邦人思之比父母。","王生早曾拜颜色，高山之外皆培𪣻。","用为羲和天为成，用平水土地为厚。","王也论道阻江湖，李也丞疑旷前后。","死为星辰终不灭，致君尧舜焉肯朽。","吾辈碌碌饱饭行，风后力牧长回首。"],"theme":"羁旅思乡","theme2":["亲情"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["月","江"],"cats":{"抒情":["思乡"],"山水":["江河"],"天气":["月亮"],"人生":["读书"]},"theme_conf":0.523},{"uid":"d755f74b-18fd-44d1-a6e1-43e77490bb09","title":"喜见外弟又言别","author":"李益","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["十年离乱后，长大一相逢。","问姓惊初见，称名忆旧容。","别来沧海事，语罢暮天钟。","明日巴陵道，秋山又几重。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"欢愉","mood2":[],"scene":["秋","江","山"],"cats":{"抒情":["离别"],"四季":["秋天"]},"theme_conf":1.0},{"uid":"cpcf88bc5d6261e8","title":"苏武慢","author":"蔡伸","dynasty":"宋","section":"宋词","form":"词","paragraphs":["雁落平沙，烟笼寒水，古垒鸣笳声断。","青山隐隐，败叶萧萧，天际暝鸦零乱。","楼上黄昏，片帆千里归程，年华将晚。","望碧云空暮，佳人何处，梦魂俱远。","忆旧游、邃馆朱扉，小园香径，尚想桃花人面。","书盈锦轴，恨满金徽，难写寸心幽怨。","两地离愁，一尊芳酒，凄凉危阑倚遍。","尽迟留、凭仗西风，吹干泪眼。"],"theme":"羁旅思乡","theme2":["闲适隐逸"],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["花","鸟","酒"],"cats":{"抒情":["思乡","伤感"],"人物":["女子"]},"theme_conf":0.51},{"uid":"44b128d9-264f-48b0-83e9-751db7dbb08e","title":"题高云客舍","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["孤兴日自深，浮云非所仰。","窗中西城峻，树外东川广。","晏起簪葛巾，闲吟倚藜杖。","阮公道在醉，庄子生常养。","五柳转扶疎，千峰恣来往。","清秋香秔获，白露寒菜长。","吴国滞风烟，平陵延梦想。","时人趋缨弁，高鸟违罗网。","世事徒乱纷，吾心方浩荡。","唯将山与水，处处谐真赏。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["清新"],"mood":"孤寂","mood2":["欢愉","恬淡"],"scene":["山","秋"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"],"天气":["写云"]},"theme_conf":0.368},{"uid":"8fc09639-9e38-402f-9827-589c1cc161ff","title":"夏日对雨寄朱放拾遗","author":"武元衡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["才非谷永传，无意谒王侯。","小暑金将伏，微凉麦正秋。","远山欹枕见，暮雨闭门愁。","更忆东林寺，诗家第一流。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"沉郁","style2":["旷达"],"mood":"愁怨","mood2":["相思"],"scene":["夏","雨"],"cats":{"抒情":["思念","伤感"],"四季":["夏天"],"山水":["庐山"],"天气":["写雨"]},"theme_conf":0.95},{"uid":"c7166837-c70d-4cfd-bf45-baf6930473bf","title":"酬卫八雪中见寄","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["季冬忆淇上，落日归山樊。","旧宅带流水，平田临古村。","雪中望来信，醉里开衡门。","果得希代宝，缄之那可论。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["雪","冬"],"cats":{"抒情":["思念"],"四季":["冬天"],"天气":["写雪"]},"theme_conf":0.95},{"uid":"86909f2e-2ccb-40d2-8773-8bdec8006cce","title":"赠康洽","author":"李端","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["黄须康兄酒泉客，平生出入王侯宅。","今朝醉卧又明朝，忽忆故乡头已白。","流年恍惚瞻西日，陈事苍茫指南陌。","声名恒压鲍参军，班位不过扬执戟。","迩来七十遂无机，空是咸阳一布衣。","后辈轻肥贱衰朽，五侯门馆许因依。","自言万物有移改，始信桑田变成海。","同时献赋人皆尽，共壁题诗君独在。","步出东城风景和，青山满眼少年多。","汉家尚壮今则老，发短心长知奈何。","华堂举杯白日晚，龙钟相见谁能免。","君今已反我正来，朱颜宜笑能几回。","借问朦胧花树下，谁家畚插筑高台。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"雄浑","style2":["豪放"],"mood":"孤寂","mood2":["慷慨"],"scene":["酒"],"cats":{"抒情":["思乡","孤独"],"人生":["青春","时光"]},"theme_conf":0.96},{"uid":"72e1b5ac-d83c-483c-a5eb-5b33172fc16f","title":"江北忆崔汶","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["夜问江西客，还知在楚乡。","全身出部伍，尽室逐渔商。","晴日游瓜步，新年对汉阳。","月昏惊浪白，瘴起觉云黄。","望岭家何处，登山泪几行。","闽中传有雪，应且住南康。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"清新","style2":["婉约","沉郁"],"mood":"相思","mood2":[],"scene":["江","山"],"cats":{"抒情":["思念","思乡"],"山水":["江河"],"节日":["春节"]},"theme_conf":0.504},{"uid":"4b0bc117-6db3-4fe7-a7ac-6df03c52a62a","title":"天边行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["天边老人归未得，日暮东临大江哭。","陇右河源不种田，胡骑羌兵入巴蜀。","洪涛滔天风拔木，前飞秃鹙后鸿鹄。","九度附书向洛阳，十年骨肉无消息。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["江"],"cats":{"抒情":["思乡"],"山水":["长江","黄河"],"人生":["梦想"]},"theme_conf":0.425},{"uid":"20a6a82e-639c-4244-a3c4-193f16fd0b57","title":"赠李八秘书别三十韵","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["往时中补右，扈跸上元初。","反气凌行在，妖星下直庐。","六龙瞻汉阙，万骑略姚墟。","玄朔回天步，神都忆帝车。","一戎才汗马，百姓免为鱼。","通籍蟠螭印，差肩列凤舆。","事殊迎代邸，喜异赏朱虚。","寇盗方归顺，乾坤欲晏如。","不才同补衮，奉诏许牵裾。","鸳鹭叨云阁，麒麟滞玉除。","文园多病后，中散旧交疎。","飘泊哀相见，平生意有余。","风烟巫峡远，台榭楚宫虚。","触目非论故，新文尚起予。","清秋凋碧柳，别浦落红蕖。","消息多旗帜，经过叹里闾。","战连唇齿国，军急羽毛书。","幕府筹频问，山家药正锄。","台星入朝谒，使节有吹嘘。","西蜀灾长弭，南翁愤始摅。","对敭抏士卒，干没费仓储。","势藉兵须用，功无礼忽诸。","御鞍金騕褭，宫砚玉蟾蜍。","拜舞银钩落，恩波锦帕舒。","此行非不济，良友昔相于。","去斾依颜色，沿流想疾徐。","沈绵疲井臼，倚薄似樵渔。","乞米烦佳客，钞诗听小胥。","杜陵斜晚照，潏水带寒淤。","莫话清溪发，萧萧白暎梳。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["元宵","楼"],"cats":{"抒情":["离别"],"人生":["战争"],"节日":["元宵节"]},"theme_conf":0.348},{"uid":"6c49fcc2-e014-4a5f-8b7b-bc592de83062","title":"遭田父泥饮美严中丞","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["步屧随春风，邨邨自花柳。","田翁逼社日，邀我尝春酒。","酒酣夸新尹，畜眼未见有。","回头指大男，渠是弓弩手。","名在飞骑籍，长番岁时久。","前日放营农，辛苦救衰朽。","差料死则已，誓不举家走。","今年大作社，拾遗能住否。","叫妇开大缾，盆中为吾取。","感此气扬扬，须知风化首。","语多虽杂乱，说尹终在口。","朝来偶然出，自卯将及酉。","久客惜人情，如何拒邻叟。","高声索果栗，欲起时被肘。","指挥过无礼，未觉邨野丑。","月出遮我留，仍嗔问升斗。"],"theme":"应制干谒","theme2":["山水田园","节令风俗","羁旅思乡"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["春","酒"],"cats":{"抒情":["思乡"],"四季":["春天"],"人物":["父亲"]},"theme_conf":0.62},{"uid":"cp6df3966a4d64dc","title":"卜算子","author":"陆游","dynasty":"宋","section":"宋词","form":"词","paragraphs":["驿外断桥边，寂寞开无主。","已是黄昏独自愁，更著风和雨。","无意苦争春，一任群芳妒。","零落成泥碾作尘，只有香如故。"],"theme":"羁旅思乡","theme2":[],"style":"旷达","style2":["婉约"],"mood":"孤寂","mood2":["愁怨"],"scene":["夜","花","春","雨"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["春天"],"山水":["西湖"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"a0fdbeaf-ac46-407c-a611-24775a378981","title":"唐明堂乐章 羽音","author":"则天皇后","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["葭律肇启隆冬，苹藻攸陈飨祭。","黄钟既陈玉烛，红粒方殷稔岁。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["冬"],"cats":{"抒情":["怀古"],"四季":["冬天"]},"theme_conf":0.65},{"uid":"cpd6348b5969a59a","title":"谢金莲诗酒红梨花・南吕/一枝花","author":"张寿卿","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["花梢月正高，院宇人初静。","为怜才子约，嫌煞月儿明。","俺忍怕耽惊，俏俏的穿芳径。","怕人来更犬惊，花阴里蹑足行行，柳影中潜身等等。"],"theme":"闲适隐逸","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":[],"scene":["花"],"cats":{"抒情":["感恩"],"植物":["梨花","荷花"],"食物":["写酒"]},"theme_conf":0.65},{"uid":"cpcecdecaab6d888","title":"凤箫吟・芳草","author":"韩缜","dynasty":"宋","section":"宋词","form":"词","paragraphs":["锁离愁，连绵无际，来时陌上初熏。","绣帏人念远，暗垂珠泪，泣送征轮。","长亭长在眼，更重重、远水孤云。","但望极楼高，尽日目断王孙。","消魂。","池塘别后，曾行处、绿妒轻裙。","恁时携素手，乱花飞絮里，缓步香。","朱颜空自改，向年年、芳意长新。","遍绿野，嬉游醉眠，莫负青春。"],"theme":"送别","theme2":[],"style":"清新","style2":["沉郁","婉约"],"mood":"愁怨","mood2":["孤寂"],"scene":["花"],"cats":{"抒情":["离别","伤感","孤独"],"人生":["青春"]},"theme_conf":0.813},{"uid":"31cc87f3-da0f-421d-8674-8753530077e2","title":"送别","author":"王维","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["下马饮君酒，问君何所之。","君言不得意，归卧南山陲。","但去莫复问，白云无尽时。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["酒","山"],"cats":{"抒情":["离别"]},"theme_conf":0.869},{"uid":"799e398b-266a-474f-a861-cdcacae127a2","title":"湘灵鼓瑟","author":"魏璀","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["瑶瑟多哀怨，朱弦且莫听。","扁舟三楚客，藂竹二妃灵。","淅沥闻余响，依稀欲辨形。","柱间寒水碧，曲里暮山青。","良马悲衔草，游鱼思绕萍。","知音若相遇，终不滞南溟。"],"theme":"羁旅思乡","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["舟"],"cats":{"抒情":["友情","思乡","伤感"]},"theme_conf":1.0},{"uid":"cpb5f8447a154523","title":"谢金莲诗酒红梨花・哭皇天","author":"张寿卿","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["待道是海棠呵杜子美无诗兴，(赵汝州云)敢是桃花么？(正旦唱)若是桃花呵怕阮肇却早共你争。","(赵汝州云)敢是石榴花么？(正旦唱)那石榴花夏月开，这其间未过清明。","(赵汝州云)敢是山茶花么？(正旦唱)若论山茶花却是冬暮景，(赵汝州云)敢是刺梅花么？(正旦唱)刺梅花初开未盛。","(赵汝州云)敢是碧桃花么？(正旦唱)若说着碧桃花，那里讨墙外谁家凤吹声。","(赵汝州云)我也猜不着。","(正旦唱)枉将伊侯幸，说与你便省。"],"theme":"悼亡挽歌","theme2":["闲适隐逸"],"style":"沉郁","style2":["绮丽","豪放"],"mood":"悲怆","mood2":[],"scene":["花","酒","冬"],"cats":{"抒情":["悼亡","感恩"],"四季":["冬天"],"节日":["清明节"],"植物":["梨花","荷花"],"食物":["写酒"]},"theme_conf":0.494},{"uid":"cp7c35167f827ea7","title":"风入松","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["听风听雨过清明。","愁草瘗花铭。","楼前绿暗分携路，一丝柳、一寸柔情。","料峭春寒中酒，交加晓梦啼莺。","西园日日扫林亭。","依旧赏新晴。","黄蜂频扑秋千索，有当时、纤手香凝。","惆怅双鸳不到，幽阶一夜苔生。"],"theme":"山水田园","theme2":["节令风俗"],"style":"清新","style2":[],"mood":"惆怅","mood2":["愁怨"],"scene":["春","清明","楼","花","酒","秋"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"],"天气":["写风"],"节日":["清明节"]},"theme_conf":0.446},{"uid":"88a56b30-c190-4149-9876-6751971c2597","title":"和刘七读书","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["夜雨深馆静，苦心黄卷前。","云阴留墨沼，萤影傍华编。","梦鸟富清藻，通经仍妙年。","何愁丹穴凤，不饮玉池泉。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"愁怨","mood2":[],"scene":["夜","雨"],"cats":{"抒情":["伤感"],"人生":["读书"]},"theme_conf":1.0},{"uid":"fdefa73b-111d-4b67-ae50-343eb1acce7a","title":"宿黄花馆","author":"杨发","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["孤馆萧条槐叶稀，暮蝉声隔水声微。","年年为客路无尽，日日送人身未归。","何处迷鸿离浦月，谁家愁妇捣霜衣。","夜深不卧帘犹卷，数点残萤入户飞。"],"theme":"羁旅思乡","theme2":["送别"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂"],"scene":["花","秋","月","夜"],"cats":{"抒情":["思乡","伤感","孤独"],"四季":["秋天"],"植物":["菊花"]},"theme_conf":0.506},{"uid":"0ae0e3bd-a32e-481f-9719-b283da2da964","title":"滁州西涧","author":"韦应物","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["独怜幽草涧边生，上有黄鹂深树鸣。","春潮带雨晚来急，野渡无人舟自横。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独"],"四季":["春天"]},"theme_conf":0.78},{"uid":"15079155-e95e-4abc-b36e-f6b605848f37","title":"杂曲歌辞 独不见","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["卢家小妇郁金堂，海燕双栖玳瑁梁。","九月寒砧催下叶，十年征戍忆辽阳。","白狼河北音书断，丹凤城南秋夜长。","谁知含愁独不见，使妾明月照流黄。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["月","秋"],"cats":{"抒情":["思念","孤独","闺怨"],"四季":["秋天"],"天气":["月亮"]},"theme_conf":0.698},{"uid":"7cae1dc9-23b8-4611-938d-27d143c3781b","title":"草堂前新开一池养鱼种荷日有幽趣","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["淙淙三峡水，浩浩万顷陂。","未如新塘上，微风动涟漪。","小萍加泛泛，初蒲正离离。","红鲤二三寸，白莲八九枝。","绕水欲成径，护堤方插篱。","已被山中客，呼作白家池。"],"theme":"山水田园","theme2":["闲适隐逸","羁旅思乡"],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["园林","夏"],"cats":{"抒情":["思乡"],"四季":["夏天"],"植物":["荷花"]},"theme_conf":0.364},{"uid":"cpa683c993407ae0","title":"烛影摇红","author":"廖世美","dynasty":"宋","section":"宋词","form":"词","paragraphs":["霭霭春空，画楼森耸凌云渚。","紫薇登览最关情，绝妙夸能赋。","惆怅相思迟暮。","记当日、朱阑共语。","塞鸿难问，岸柳何穷，别愁纷絮。","催促年光，旧来流水知何处。","断肠何必更残阳，极目伤平楚。","晚霁波声带雨。","悄无人、舟横野渡。","数峰江上，芳草天涯，参差烟树。"],"theme":"爱情相思","theme2":["爱情相思","山水田园","送别"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["相思","孤寂"],"scene":["江","花","塞外","春","舟","楼"],"cats":{"抒情":["爱情","思念","伤感","孤独"],"四季":["春天"]},"theme_conf":0.75},{"uid":"5c5e7185-6ddb-443f-81ed-e7d2d9d59460","title":"自云阳归晚泊陆澧宅","author":"严维","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["天阴行易晚，前路故人居。","孤棹所思久，寒林相见初。","闲灯忘夜水，清漏任更疎。","明发还须去，离家几岁除。"],"theme":"羁旅思乡","theme2":["节令风俗","羁旅思乡","山水田园"],"style":"清新","style2":[],"mood":"孤寂","mood2":["恬淡"],"scene":["夜","除夕"],"cats":{"抒情":["思乡","孤独"],"节日":["春节"]},"theme_conf":0.9},{"uid":"cpb4d17b6c2877aa","title":"烛影摇红","author":"张抡","dynasty":"宋","section":"宋词","form":"词","paragraphs":["双阙中天，凤楼十二春寒浅。","去年元夜奉宸游，曾侍瑶池宴。","玉殿珠帘尽卷。","拥群仙、蓬壶阆苑。","五云深处，万烛光中，揭天丝管。","驰隙流年，恍如一瞬星霜换。","今宵谁念泣孤臣，回首长安远。","可是尘缘未断。","谩惆怅、华胥梦短。","满怀幽恨，数点寒灯，几声归雁。"],"theme":"羁旅思乡","theme2":["应制干谒"],"style":"绮丽","style2":["沉郁"],"mood":"孤寂","mood2":["惆怅","悲怆"],"scene":["夜"],"cats":{"抒情":["思乡","孤独"],"人生":["时光"]},"theme_conf":0.52},{"uid":"de7ae571-5241-4ea9-82f7-0d49eeebd710","title":"月蚀诗效玉川子作","author":"韩愈","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["元和庚寅斗插子，月十四日三更中。","森森万木夜僵立，寒气屃奰顽无风。","月形如白盘，完完上天东。","忽然有物来噉之，不知是何虫。","如何至神物，遭此狼狈凶。","星如撒沙出，攒集争强雄。","油灯不照席，是夕吐燄如长虹。","玉川子，涕泗下，中庭独行。","念此日月者，为天之眼睛。","此犹不自保，吾道何由行。","尝闻古老言，疑是虾蟆精。","径圆千里纳女腹，何处养女百丑形。","杷沙脚手钝，谁使女解缘青冥。","黄帝有四目，帝舜重其明。","今天祗两目，何故许食使偏盲。","尧呼大水浸十日，不惜万国赤子鱼头生。","女于此时若食日，虽食八九无嚵名。","赤龙黑鸟烧口热，翎鬣倒侧相搪撑。","婪酣大肚遭一饱，饥肠彻死无由鸣。","后时食月罪当死，天罗磕帀何处逃汝刑。","玉川子立于庭而言曰，地行贱臣仝。","再拜敢告上天公，臣有一寸刃。","可刳凶蟆肠，无梯可上天。","天阶无由有臣踪，寄牋东南风。","天门西北祈风通，丁宁附耳莫漏泄。","薄命正值飞廉慵，东方青色龙。","牙角何呀呀，从官百余座。","嚼啜烦官家，月蚀汝不知。","安用为龙窟天河，赤鸟司南方。","尾秃翅觰沙，月蚀于汝头。","汝口开呀呀，虾蟆掠汝两吻过。","忍学省事不以汝觜啄虾蟆，於菟蹲于西。","旗旄卫毵㲚，既从白帝祠。","又食于蜡礼有加，忍令月被恶物食。","枉于汝口插齿牙，乌龟怯奸。","怕寒缩颈，以壳自遮。","终令夸蛾抉汝出，卜师烧锥钻灼满板如星罗。","此外内外官，琐细不足科。","臣请悉埽除，慎勿许语令啾哗。","幷光全耀归我月，盲眼镜净无纤瑕。","弊蛙拘送主府官，帝箸下腹尝其皤。","依前使兔操杵臼，玉阶桂树闲婆娑。","姮娥还宫室，太阳有室家。","天虽高，耳属地。","感臣赤心，使臣知意。","虽无明言，潜喻厥旨。","有气有形，皆吾赤子。","虽忿大伤，忍杀孩穉。","还汝月明，安行于次。","尽释众罪，以蛙磔死。"],"theme":"送别","theme2":["民生疾苦"],"style":"绮丽","style2":["豪放"],"mood":"恬淡","mood2":["孤寂","悲怆"],"scene":["月","夜"],"cats":{"抒情":["伤感","孤独"],"天气":["彩虹","月亮"]},"theme_conf":0.628},{"uid":"f0dc1af7-c04b-47b3-a488-a60082869b1b","title":"经埋轮地","author":"蒋冽","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["汉家张御史，晋国绿珠楼。","时代邈已远，共谢洛阳秋。","洛阳大道边，旧地尚依然。","下马独太息，扰扰城市喧。","时人欣绿珠，诗满金谷圆。","千载埋轮地，无人兴一言。","正直死犹忌，况乃未死前。","汨罗有飜浪，恐是嫌屈原。","我闻太古水，上与天相连。","如何一落地，又作九曲泉。","万古惟高步，可以旌我贤。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["端午"],"cats":{"抒情":["孤独"],"山水":["黄河"],"节日":["端午节"]},"theme_conf":1.0},{"uid":"c64926d8-1757-4e1f-8096-dd24190f1ba1","title":"送萧十八与房侍御廻还","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["常苦古人远，今见斯人古。","澹泊遗声华，周旋必邹鲁。","故交在梁宋，游方出庭户。","匹马鸣朔风，一身济河浒。","辛勤采兰咏，款曲翰林主。","岁月催别离，庭围远风土。","寥寥寒烟静，莽莽夕阴吐。","明发不在兹，青天眇难覩。"],"theme":"送别","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":["孤寂"],"scene":["园林","月","冬"],"cats":{"抒情":["离别"],"四季":["冬天"],"天气":["写风"]},"theme_conf":1.0},{"uid":"2986234c-d484-47aa-b566-f370e03f2602","title":"白菊杂书四首 三","author":"司空图","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["狂才不足自英雄，仆妾驱令学贩舂。","侯印几人封万户，侬家只办买孤峰。"],"theme":"闺情宫怨","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳","山"],"cats":{"抒情":["孤独","闺怨"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"8aa36cc8-fec9-455c-91b7-23fc83cdddb1","title":"和张尹忆东篱菊","author":"李端","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["传书报刘尹，何事忆陶家。","若为篱边菊，山中有此花。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["重阳"],"cats":{"抒情":["思念"],"生活":["乡村"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.82},{"uid":"7bb37684-e982-4765-bce8-fbfe3b87dc15","title":"赠别王十七管记","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["故交吾未测，薄宦空年岁。","晚节踪曩贤，雄词冠当世。","堂中皆食客，门外多酒债。","产业曾未言，衣裘与人敝。","飘飖戎幕下，出入关山际。","转战轻壮心，立谈有边计。","云沙自廻合，天海空迢递。","星高汉将骄，月盛胡兵锐。","沙深冷陉断，雪暗辽阳闭。","亦谓扫欃枪，旋惊陷蜂虿。","归旌告东捷，鬬骑传西败。","遥飞绝汉书，已筑长安第。","画龙俱在叶，宠鹤先居卫。","勿辞部曲勋，不藉将军势。","相逢季冬月，伥望穷海裔。","折劒留赠人，严装遂云迈。","我行将悠𥾝，及此还羁滞。","曾非济代谋，且有临深诫。","随波混清浊，与物同丑丽。","眇忆青岩栖，宁忘褐衣拜。","自言爱水石，本欲亲兰蕙。","何意薄松筠，翻然重菅蒯。","恒深取与分，孰慢平生契。","欵曲鸡黍期，酸辛别离袂。","逢时愧名节，遇坎悲沦替。","适赵非解纷，游燕往无说。","浩歌方振荡，逸翮思凌励。","倏若异鹏抟，吾当学蝉蜕。"],"theme":"送别","theme2":[],"style":"豪放","style2":["幽峭","清新"],"mood":"相思","mood2":["恬淡","悲怆"],"scene":["冬","山","鸟","雪","月"],"cats":{"抒情":["离别","思念","伤感"],"四季":["冬天"],"人生":["战争"]},"theme_conf":0.519},{"uid":"c27daaf8-489e-4fdb-8d82-85a074f8fd2e","title":"闻友人入越幕因以诗赠","author":"罗邺","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["稽岭春生酒冻销，烟鬟红袖恃娇饶。","岸边丛雪晴香老，波上长虹晚影遥。","正哭阮途归未得，更闻江笔赴嘉招。","人间荣瘁真堪恨，坐想征轩鬓欲凋。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["愁怨"],"scene":["江南","雪","春","酒","花"],"cats":{"抒情":["友情"],"四季":["春天"],"天气":["彩虹"]},"theme_conf":0.9},{"uid":"cp18f1742f4cfcc4","title":"念奴娇","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["闹红一舸，记来时、尝与鸳鸯为侣。","三十六陂人未到，水佩风裳无数。","翠叶吹凉，玉容销酒，更洒菰蒲雨。","嫣然摇动，冷香飞上诗句。","日暮。","青盖亭亭，情人不见，争忍凌波去。","只恐舞衣寒易落，愁入西风南浦。","高柳垂阴，老鱼吹浪，留我花间住。","田田多少，几回沙际归路。"],"theme":"送别","theme2":["爱情相思"],"style":"绮丽","style2":["沉郁","豪放"],"mood":"相思","mood2":["愁怨","孤寂"],"scene":["花","酒","舟","雨"],"cats":{"抒情":["爱情","离别","思念","伤感"]},"theme_conf":0.538},{"uid":"cp79ac7bfce7f15c","title":"满庭芳","author":"秦观","dynasty":"宋","section":"宋词","form":"词","paragraphs":["晓色云开，春随人意，骤雨才过还晴。","古台芳榭，飞燕蹴红英。","舞困榆钱自落，秋千外、绿水桥平。","东风里，朱门映柳，低底按小秦筝。","多情。","行乐处，珠钿翠盖，玉辔红缨。","渐酒空金，花困蓬瀛。","豆蔻梢头旧恨，十年梦，屈指堪惊。","凭阑久，疏烟淡日，寂寞下芜城。"],"theme":"讽喻刺世","theme2":[],"style":"绮丽","style2":["冲淡","清新"],"mood":"孤寂","mood2":["愁怨"],"scene":["花","春"],"cats":{"抒情":["孤独"],"四季":["春天"],"天气":["写雨"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"1dbf0b9d-bdb3-4ee1-9bbf-005087cefe54","title":"相和歌辞 决绝[词]三首 三","author":"元稹","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["夜夜相抱眠，幽怀尚沈结。","那堪一年事，长遣一宵说。","但感久相思，何暇暂相悦。","虹桥薄夜成，龙驾侵晨列。","生憎野鹊往迟回，死恨天鸡识时节。","曙色渐曈昽，华星次明灭。","一去又一年，一年何时彻。","有此迢遰期，不如生死别。"],"theme":"爱情相思","theme2":["闲适隐逸","送别"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["夜"],"cats":{"抒情":["爱情","思念"],"生活":["写桥"]},"theme_conf":0.357},{"uid":"8f4ff5d9-6454-4e9a-94e9-9baca2276713","title":"相和歌辞 安乐宫","author":"李贺","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["深井桐乌起，尚复牵清水。","未盥邵陵王，瓶中弄长翠。","新城安乐宫，宫如凤皇翅。","歌回蜡版鸣，大绾提壶使。","绿繁悲水曲，茱萸别秋子。"],"theme":"咏史怀古","theme2":[],"style":"清新","style2":["悲慨"],"mood":"欢愉","mood2":["恬淡"],"scene":["重阳","秋"],"cats":{"抒情":["怀古"],"四季":["秋天"],"节日":["重阳节"]},"theme_conf":0.82},{"uid":"ca98fed4-d62e-480c-bcb7-b2b95749441a","title":"琴曲歌辞 胡笳十八拍 第十一拍","author":"刘商","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["日来月往相推迁，迢迢星岁欲周天。","无冬无夏卧霜霰，水冻草枯为一年。","汉家甲子有正朔，绝域三光空自悬。","几回鸿雁来又去，肠断蟾蜍亏复圆。"],"theme":"边塞征战","theme2":["闲适隐逸","民生疾苦"],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["月","冬","夏","雪"],"cats":{"抒情":["伤感"],"四季":["夏天","冬天"]},"theme_conf":0.452},{"uid":"9ad03d65-0953-4326-8d85-9e69bb02b4de","title":"和西川李尚书汉州微月游房太尉西湖","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["木落汉川夜，西湖悬玉钩。","旌旗环水次，舟檝泛中流。","目极想前事，神交如共游。","瑶琴久已绝，松韵自悲秋。"],"theme":"山水田园","theme2":["边塞征战"],"style":"婉约","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["江南","江"],"cats":{"抒情":["伤感"],"山水":["西湖"],"天气":["月亮"]},"theme_conf":0.545},{"uid":"db548528-fbd1-4356-bc2d-403760c1267c","title":"登三台言志","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["未央初壮汉，阿房昔侈秦。","在危犹骋丽，居奢遂役人。","岂如家四海，日宇罄朝伦。","扇天裁户旧，砌地翦基新。","引月擎宵桂，飘云逼曙鳞。","露除光炫玉，霜阙映雕银。","舞接花梁燕，歌迎鸟路尘。","镜池波太液，庄苑丽宜春。","作异甘泉日，停非路寝辰。","念劳慙逸己，居旷返劳神。","所欣成大厦，宏材伫渭滨。"],"theme":"咏史怀古","theme2":[],"style":"清新","style2":["豪放","绮丽"],"mood":"慷慨","mood2":[],"scene":["园林","月","鸟","楼","春"],"cats":{"抒情":["怀古"],"四季":["春天"],"人生":["梦想"]},"theme_conf":1.0},{"uid":"baee79b5-b12e-4782-a0a6-33f6d2262a69","title":"相和歌辞 王昭君","author":"僧皎然","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["自倚婵娟望主恩，谁知美恶忽相飜。","黄金不买汉宫貌，青冢空埋胡地魂。"],"theme":"边塞征战","theme2":["咏史怀古"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["中秋"],"cats":{"抒情":["怀古"],"节日":["中秋节"]},"theme_conf":0.5},{"uid":"b47a1058-7706-4f5b-b110-c5078de3abd6","title":"题惟干上人房","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["绳床茅屋下，独坐味闲安。","苦行无童子，忘机避宰官。","是非齐已久，夏腊比应难。","更悟真如性，尘心稍自宽。"],"theme":"佛道禅颂","theme2":["哲理悟道","咏物"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":["孤寂"],"scene":["夏"],"cats":{"抒情":["孤独"],"四季":["夏天"],"人生":["哲理"]},"theme_conf":0.95},{"uid":"80fe70cd-6e63-48eb-9c1e-ab26330d45d9","title":"崔九欲往南山马上口号与别","author":"裴迪","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["归山深浅去，须尽丘壑美。","莫学武陵人，暂游桃源里。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"抒情":["离别"],"动物":["写马"]},"theme_conf":0.677},{"uid":"a7ff247d-a11c-4ca9-a22f-ca420b8c537c","title":"帝京篇十首 三","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["移步出词林，停舆欣武宴。","雕弓写明月，骏马疑流电。","惊雁落虚弦，啼猿悲急箭。","阅赏诚多美，于兹乃忘倦。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":[],"mood":"欢愉","mood2":["悲怆"],"scene":["月"],"cats":{"抒情":["伤感"],"天气":["月亮"]},"theme_conf":1.0},{"uid":"f2f04c30-149d-4b2b-bce1-1334adf84739","title":"灞上秋居","author":"马戴","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["灞原风雨定，晚见鴈行频。","落叶他乡树，寒灯独夜人。","空园白露滴，孤壁野僧隣。","寄卧郊扉久，何门致此身。"],"theme":"羁旅思乡","theme2":["讽喻刺世","节令风俗","送别"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"抒情":["思乡","孤独"],"四季":["秋天"]},"theme_conf":0.289},{"uid":"0a5c5d0f-c729-4ca6-8655-68557df89721","title":"瀑布泉","author":"冷朝阳","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["潺湲半空里，霖落石房边。","风激珠光碎，山欹练影偏。","急流难起浪，迸沫祗如烟。","自古惟今日，凄凉一片泉。"],"theme":"山水田园","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["雨","山"],"cats":{"抒情":["伤感"],"山水":["瀑布"]},"theme_conf":0.737},{"uid":"bd80d8ef-c061-4d52-bb4e-3b364ef260b2","title":"题竹扇赠别","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["湘竹殊堪制，齐纨且未工。","幸亲芳袖日，尤带旧林风。","掩笑歌筵里，传书卧阁中。","竟将为别赠，宁与合欢同。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["楼"],"cats":{"抒情":["离别"],"植物":["竹子"]},"theme_conf":0.699},{"uid":"a46125e8-7617-40ac-90f6-35d2f9af010c","title":"杂曲歌辞 爱妾换马 二","author":"张祜","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["绮阁香销华厩空，忍将行雨换追风。","休怜柳叶双眉翠，却爱桃花两耳红。","侍宴永辞春色里，趁朝休立漏声中。","恩劳未尽情先尽，暗泣嘶风两意同。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"悲怆","mood2":["欢愉"],"scene":["花","春","雨"],"cats":{"抒情":["闺怨"],"四季":["春天"],"动物":["写马"]},"theme_conf":0.729},{"uid":"ec8e6f54-f69f-43a9-ab8b-155ff46ce8f2","title":"和贺兰判官望北海作","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["圣代务平典，𬨎轩推上才。","迢遥溟海际，旷望沧波开。","四牡未遑息，三山安在哉。","巨鼇不可钓，高浪何崔嵬。","湛湛朝百谷，茫茫连九垓。","挹流纳广大，观异增迟廻。","日出见鱼目，月圆知蚌胎。","迹非想像到，心以精灵猜。","远色带孤屿，虚声涵殷雷。","风行越裳贡，水遏天吴灾。","揽辔隼将击，忘机鸥复来。","缘情韵骚雅，独立遗尘埃。","吏道竟殊用，翰林仍忝陪。","长鸣谢知己，所媿非龙媒。"],"theme":"山水田园","theme2":[],"style":"豪放","style2":[],"mood":"孤寂","mood2":["恬淡","相思"],"scene":["山","江南"],"cats":{"抒情":["友情","孤独"]},"theme_conf":0.587},{"uid":"4572699f-cc98-457f-8880-7258b363532a","title":"赠沛禅师","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["南岳满湘沅，吾师经利涉。","身归沃洲老，名与支公接。","净教传荆吴，道缘止渔猎。","观空色不染，对境心自惬。","室中人寂寞，门外山重叠。","天台积幽梦，早晚当负笈。"],"theme":"哲理悟道","theme2":["送别"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["江南","山"],"cats":{"抒情":["孤独"],"人生":["哲理"]},"theme_conf":0.54},{"uid":"45110b81-0f02-4c85-b72a-f2210d10c12f","title":"八哀诗 赠太子师汝阳郡王琎","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["汝阳让帝子，眉宇真天人。","虬须似太宗，色映塞外春。","往者开元中，主恩视遇频。","出入独非时，礼异见群臣。","爱其谨洁极，倍此骨肉亲。","从容听朝后，或在风雪晨。","忽思格猛兽，苑囿腾清尘。","羽旗动若一，万马肃𬳽𬳽。","诏王来射雁，拜命已挺身。","箭出飞鞚内，上又回翠麟。","飜然紫塞翮，下拂明月轮。","胡人虽获多，天笑不为新。","王每中一物，手自与金银。","袖中谏猎书，扣马久上陈。","竟无衔橛虞，圣聪矧多仁。","官免供给费，水有在藻鳞。","匪唯帝老大，皆是王忠勤。","晚年务置醴，门引申白宾。","道大容无能，永怀侍芳茵。","好学尚贞烈，义形必沾巾。","挥翰绮绣扬，篇什若有神。","川广不可溯，墓久狐兔邻。","宛彼汉中郡，文雅见天伦。","何以开我悲，泛舟俱远津。","温温昔风味，少壮已书绅。","旧游易磨灭，衰谢增酸辛。"],"theme":"悼亡挽歌","theme2":["送别","边塞征战"],"style":"绮丽","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["月","塞外","雪"],"cats":{"抒情":["伤感","悼亡"],"天气":["月亮"],"人生":["青春"],"生活":["边塞"]},"theme_conf":0.99},{"uid":"8c067a87-d475-491d-8786-b811118cfce2","title":"相和歌辞 雁门太守行","author":"庄南杰","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["旌旗闪闪摇天末，长笛横吹虏尘阔。","跨下嘶风白练狞，腰间切玉青蛇活。","击革𪭢金燧牛尾，犬羊兵败如山死。","九泉寂寞葬秋虫，湿云荒草啼秋思。"],"theme":"边塞征战","theme2":["羁旅思乡","悼亡挽歌","山水田园"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["悲怆"],"scene":["鸟","秋"],"cats":{"抒情":["思乡","孤独","悼亡"],"四季":["秋天"],"动物":["写鸟"]},"theme_conf":0.301},{"uid":"cpc94d671a952717","title":"鹧鸪天","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["池上红衣伴倚阑。","栖鸦常带夕阳还。","殷云度雨疏桐落，明月生凉宝扇闲。","乡梦窄，水天宽。","小窗愁黛澹秋山。","吴鸿好为传归信，杨柳阊门屋数间。"],"theme":"羁旅思乡","theme2":[],"style":"冲淡","style2":["婉约"],"mood":"恬淡","mood2":["愁怨"],"scene":["月"],"cats":{"抒情":["思乡","伤感"],"天气":["月亮"]},"theme_conf":0.649},{"uid":"8e61bd73-2066-410f-88f8-ec41840eeee7","title":"发南康夜泊灨石中","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["倦客乘归舟，春溪杳将暮。","群林结暝色，孤泊有佳趣。","夜山转长江，赤月吐深树。","飒飒松上吹，泛泛花间露。","险石俯潭涡，跳湍碍沿溯。","岂唯垂堂戒，兼以临深惧。","稍出回雁峰，明登斩蛟柱。","连云向重山，杳未见钟路。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"幽峭","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["江","夜","山"],"cats":{"抒情":["思乡","孤独"],"山水":["长江"]},"theme_conf":0.571},{"uid":"4f5f758b-ba23-44d3-b26e-e7b0f9e728e7","title":"故王维右丞堂前芍药花开凄然感怀","author":"钱起","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["芍药花开出旧栏，春衫掩泪再来看。","主人不在花长在，更胜青松守岁寒。"],"theme":"悼亡挽歌","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["花","除夕"],"cats":{"抒情":["伤感","悼亡"],"节日":["春节"]},"theme_conf":0.94},{"uid":"4b13e5da-48ea-4213-9ede-dd8cec48c7c3","title":"春雪间早梅","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["梅将雪共春，彩艳不相因。","逐吹能争密，排枝巧妬新。","谁令香满座，独使净无尘。","芳意饶呈瑞，寒光助照人。","㻏珑开已徧，点缀坐来频。","那是俱疑似，须知两逼真。","荧煌初乱眼，浩荡忽迷神。","未许琼华比，从将玉树亲。","先期迎献岁，更伴占兹晨。","愿得长辉暎，轻微敢自珍。"],"theme":"咏物","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["雪","冬","春"],"cats":{"抒情":["孤独"],"四季":["春天"],"天气":["写雪"],"植物":["梅花"]},"theme_conf":0.95},{"uid":"6f6ac3d7-9e04-4c74-9726-953c3455a4e6","title":"文宗陵","author":"曹邺","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["千年尧舜心，心成身已殁。","始随苍梧云，不返苍龙阙。","宫女衣不香，黄金赐白发。","留此奉天下，所以无征伐。","至今汨罗水，不葬大夫骨。"],"theme":"咏史怀古","theme2":["闺情宫怨"],"style":"绮丽","style2":["雄浑"],"mood":"惆怅","mood2":[],"scene":["端午"],"cats":{"抒情":["闺怨","怀古"],"节日":["端午节"]},"theme_conf":0.506},{"uid":"039da037-7d76-4ada-9506-457d36bdcc9b","title":"灯","author":"李商隐","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["皎洁终无倦，煎熬亦自求。","花时随酒远，雨后背窗休。","冷暗黄茅驿，暄明紫桂楼。","锦囊名画揜，玉局败碁收。","何处无佳梦，谁人不隐忧。","影随帘押转，光信簟文流。","客自胜潘岳，侬今定莫愁。","固应留半燄，廻照下帏羞。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":["旷达"],"mood":"愁怨","mood2":[],"scene":["元宵","夜","酒","雨","楼"],"cats":{"抒情":["思乡","伤感"],"节日":["元宵节"]},"theme_conf":1.0},{"uid":"028b5cb7-2c3b-4023-ae17-90d2128c5b75","title":"杂曲歌辞 行路难","author":"李颀","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["汉家名臣杨德祖，四代五公享茅土。","父兄子弟绾银黄，跃马鸣珂朝建章。","火浣单衣绣方领，茱萸锦带玉盘囊。","宾客填街复满坐，片言出口生辉光。","世人逐势争奔走，沥胆隳肝惟恐后。","当时一顾生青云，自谓生死长随君。","一朝谢病还乡里，穷巷苍茫绝知己。","秋风落叶闭重门，昨日论交竟谁是。","薄俗嗟嗟难重陈，深山麋鹿下为邻。","鲁连所以蹈沧海，古往今来称达人。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":["雄浑"],"mood":"相思","mood2":[],"scene":["秋","重阳"],"cats":{"抒情":["友情","思乡"],"四季":["秋天"],"节日":["重阳节"]},"theme_conf":1.0},{"uid":"cpf018dd823a543a","title":"安公子","author":"袁去华","dynasty":"宋","section":"宋词","form":"词","paragraphs":["弱柳丝千缕。","嫩黄匀遍鸦啼处。","寒入罗衣春尚浅，过一番风雨。","问燕子来时，绿水桥边路。","曾画楼、见个人人否。","料静掩云窗，尘满哀弦危柱。","庾信愁如许。","为谁都著眉端聚。","独立东风弹泪眼，寄烟波东去。","念永昼春闲，人倦如何度。","闲傍枕、百啭黄鹂语。","唤觉来厌厌，残照依然花坞。"],"theme":"爱情相思","theme2":["闺情宫怨","送别"],"style":"婉约","style2":["沉郁"],"mood":"恬淡","mood2":["愁怨"],"scene":["春","雨","鸟"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"生活":["写桥"]},"theme_conf":0.86},{"uid":"4639195c-ea55-4380-a88f-c1b3dca3282e","title":"夜宿灵台寺寄郎士元","author":"钱起","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["西日横山含碧空，东方吐月满禅宫。","朝瞻双顶青冥上，夜宿诸天色界中。","石潭倒献莲花水，塔院空闻松柏风。","万里故人能尚尔，知君视听我心同。"],"theme":"寄赠酬答","theme2":["哲理悟道"],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["夜"],"cats":{"抒情":["友情"],"人生":["哲理"]},"theme_conf":0.9},{"uid":"396cd474-fdac-49f4-9594-f28d013760ac","title":"杂歌谣辞 郑樱桃歌","author":"李颀","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["石季龙，僭天禄。","擅雄豪，美人姓郑名樱桃。","樱桃美颜香且泽，娥娥侍寝专宫掖。","后庭卷衣三万人，翠眉清镜不得亲。","官军女骑一千匹，繁花照耀漳河春。","织成花映红纶巾，红旗掣曳卤簿新。","鸣鼙走马接飞鸟，铜[驮]琴瑟随去尘。","凤阳重门如意馆，百尺金梯倚银汉。","自言富贵不可量，女为公主男为王。","赤花双簟珊瑚床，盘龙斗帐琥珀光。","淫昏伪位神所恶，灭石者陵终不误。","邺城苍苍白露微，世事飜覆黄云飞。"],"theme":"闺情宫怨","theme2":["节令风俗"],"style":"绮丽","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["花","春","七夕"],"cats":{"抒情":["闺怨"],"四季":["春天"],"人物":["女子"],"节日":["七夕节"],"植物":["桃花"]},"theme_conf":0.581},{"uid":"cp9c6ef11cc870d5","title":"浪淘沙","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["梦觉、透窗风一线，寒灯吹息。","那堪酒醒，又闻空阶，夜雨频滴。","嗟因循、久作天涯客。","负佳人、几许盟言，便忍把、从前欢会，陡顿翻成忧戚。","愁极。","再三追思，洞房深处，几度饮散歌阑，香暖鸳鸯被，岂暂时疏散，费伊心力。","云尤雨，有万般千种，相怜相惜。","恰到如今，天长漏永，无端自家疏隔。","知何时、却拥秦云态，愿低帏昵枕，轻轻细说与，江乡夜夜，数寒更思忆。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["冲淡"],"mood":"愁怨","mood2":["相思"],"scene":["夜"],"cats":{"抒情":["思念","思乡","伤感"],"人物":["女子"]},"theme_conf":0.765},{"uid":"131c9f87-273f-4684-9b67-bd7b58ad4008","title":"筹笔驿","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["猿鸟犹疑畏简书，风云常为护储胥。","徒令上将挥神笔，终见降王走传车。","管乐有才终不忝，关张无命欲何如。","他年锦里经祠庙，梁父吟成恨有余。"],"theme":"咏史怀古","theme2":["羁旅思乡"],"style":"绮丽","style2":["沉郁"],"mood":"愁怨","mood2":["欢愉"],"scene":[],"cats":{"抒情":["思乡","怀古"]},"theme_conf":0.573},{"uid":"3b70daa4-ed82-4ba5-8dc0-6345d6542862","title":"忆平泉杂咏 忆茗芽","author":"李德裕","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["谷中春日暖，渐忆掇茶英。","欲及清明火，能销醉客酲。","松花飘鼎泛，兰气入瓯轻。","饮罢闲无事，扪萝溪上行。"],"theme":"山水田园","theme2":["咏物","闲适隐逸"],"style":"冲淡","style2":[],"mood":"相思","mood2":[],"scene":["清明","春"],"cats":{"抒情":["思念"],"四季":["春天"],"节日":["清明节"],"食物":["写茶"]},"theme_conf":0.394},{"uid":"df572f9e-bc85-4b4b-bf6a-05b06c3244dc","title":"相和歌辞 凤台曲","author":"王无竞","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["凤台何逶迤，嬴女管参差。","一旦彩云至，身去无还期。","遗曲此台上，世人多学吹。","一吹一落泪，至今怜玉姿。"],"theme":"咏史怀古","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["楼"],"cats":{"抒情":["伤感","怀古"],"天气":["写云"]},"theme_conf":0.88},{"uid":"2e1e7ba7-1beb-4430-a7f2-3e5d7241beec","title":"送樊二十三侍御赴汉中判官","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["威弧不能弦，自尔无宁岁。","川谷血横流，豺狼沸相噬。","天子从北来，长驱振凋敝。","顿兵岐梁下，却跨沙漠裔。","二京陷未收，四极我得制。","萧索汉水清，缅通淮湖税。","使者纷星散，王纲尚旒缀。","南伯从事贤，君行立谈际。","生知七曜历，手画三军势。","冰雪净聪明，雷霆走精锐。","幕府辍谏官，朝廷无此例。","至尊方旰食，仗尔布嘉惠。","补阙暮征入，柱史晨征憩。","正当艰难时，实藉长久计。","回风吹独树，白日照执袂。","恸哭苍烟根，山门万重闭。","居人莽牢落，游子方迢递。","裴回悲生离，局促老一世。","陶唐歌遗民，后汉更列帝。","恨无匡复姿，聊欲从此逝。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["冬","塞外","雪"],"cats":{"抒情":["伤感"],"天气":["写雪"],"人生":["战争"]},"theme_conf":0.416},{"uid":"57fcfc8f-4993-43a2-a154-615b75a5105f","title":"八哀诗 赠左仆射郑国公严公武","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["郑公瑚琏器，华岳金天晶。","昔在童子日，已闻老成名。","嶷然大贤后，复见秀骨清。","开口取将相，小心事友生。","阅书百纸尽，落笔四座惊。","历识匪父任，嫉邪常力争。","汉议尚整肃，胡骑忽纵横。","飞传自河陇，逢人问公卿。","不知万乘出，雪涕风悲鸣。","受词劒阁道，谒帝萧关城。","寂寞云台仗，飘飖沙塞旌。","江山少使者，笳鼓凝皇情。","壮士血相视，忠臣气不平。","密论贞观体，挥发岐阳征。","感激动四极，联翩收二京。","西郊牛酒再，原庙丹青明。","匡汲俄宠辱，卫霍竟哀荣。","四登会府地，三掌华阳兵。","京兆空柳色，尚书无履声。","群乌自朝夕，白马休横行。","诸葛蜀人爱，文翁儒化成。","公来雪山重，公去雪山轻。","记室得何逊，韬钤延子荆。","四郊失壁垒，虚馆开逢迎。","堂上指图画，军中吹玉笙。","岂无成都酒，忧国只细倾。","时观锦水钓，问俗终相幷。","意待犬戎灭，人藏红粟盈。","以兹报主愿，庶或裨世程。","炯炯一心在，沈沈二竖婴。","颜回竟短折，贾谊徒忠贞。","飞旐出江汉，孤舟轻荆衡。","虚无马融笛，怅望龙骧茔。","空余老宾客，身上媿簪缨。"],"theme":"悼亡挽歌","theme2":["悼亡挽歌","送别"],"style":"悲慨","style2":["绮丽"],"mood":"悲怆","mood2":["孤寂"],"scene":["雪","楼","酒","塞外"],"cats":{"抒情":["伤感","孤独","悼亡"],"人生":["战争"]},"theme_conf":0.95},{"uid":"df99dd63-0832-4715-8e63-ce89452560a1","title":"鼓吹曲辞 巫山高二首 一","author":"孟郊","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["巴山上峡重复重，阳台碧峭十二峰。","荆王猎时逢暮雨，夜卧高丘梦神女。","轻红流烟湿艳姿，行云飞去明星稀。","目极魂断望不见，猨啼三声泪沾衣。"],"theme":"山水田园","theme2":[],"style":"婉约","style2":["沉郁","幽峭"],"mood":"相思","mood2":["愁怨"],"scene":["山"],"cats":{"抒情":["思念","伤感"],"节日":["重阳节"]},"theme_conf":0.706},{"uid":"cp23ced89521c2e8","title":"帝台春","author":"李甲","dynasty":"宋","section":"宋词","form":"词","paragraphs":["芳草碧色，萋萋遍南陌。","暖絮乱红，也知人、春愁无力。","忆得盈盈拾翠侣，共携赏、凤城寒食。","到今来，海角逢春，天涯为客。","愁旋释。","还似织。","泪暗拭。","又偷滴。","谩伫立、遍倚危阑，尽黄昏，也只是、暮云凝碧。","拼则而已今拼了，忘则怎生便忘得。","又还问鳞鸿，试重寻消息。"],"theme":"羁旅思乡","theme2":["节令风俗"],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["思乡","伤感"],"四季":["春天"],"节日":["寒食节"]},"theme_conf":0.556},{"uid":"3b39dc82-798d-44db-8452-bf8e17e7d343","title":"客自江南话过亡友朱司议故宅","author":"包佶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["交臂多相共，风流忆此人。","海翻移里巷，书蠹积埃尘。","奉佛栖禅久，辞官上疏频。","故来分半宅，惟是旧交亲。"],"theme":"悼亡挽歌","theme2":["哲理悟道","咏史怀古"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["江南","江"],"cats":{"抒情":["友情","思念","悼亡","怀古"],"人生":["哲理"]},"theme_conf":0.95},{"uid":"7bfe6521-bb53-46ae-af7c-2339309f0605","title":"昭德皇后挽歌词","author":"包佶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["西汜驰晖过，东园别路长。","岁华唯陇柏，春事罢公桑。","龟兆开泉户，禽巢闭画梁。","更闻哀礼过，明诏制心丧。"],"theme":"悼亡挽歌","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["春","园林"],"cats":{"抒情":["悼亡"],"四季":["春天"]},"theme_conf":0.98},{"uid":"3f0c3044-abde-40f5-bd9f-ac83fdbe8319","title":"杂曲歌辞 伊州 入破第五","author":"盖嘉运","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["君住孤山下，烟深夜径长。","辕门渡绿水，游苑遶垂杨。"],"theme":"爱情相思","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["夜","山"],"cats":{"抒情":["孤独"],"山水":["西湖"]},"theme_conf":0.62},{"uid":"cp47edac7a31dd39","title":"燕山亭","author":"赵佶","dynasty":"宋","section":"宋词","form":"词","paragraphs":["裁翦冰绡，打叠数重，冷淡燕脂匀注。","新样靓妆，艳溢香融，羞杀蕊珠宫女。","易得凋零，更多少、无情风雨。","愁苦。","闲院落凄凉，几番春暮。","凭寄离恨重重，这双燕，何曾会人言语。","天遥地远，万水千山，知他故宫何处。","怎不思量，除梦里、有时会去。","无据。","和梦也、有时不做。"],"theme":"送别","theme2":["闺情宫怨"],"style":"清新","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["山","鸟","雨","花"],"cats":{"抒情":["伤感","闺怨"],"动物":["写鸟"]},"theme_conf":0.537},{"uid":"b51c9f56-c13f-487f-846f-90ec85b1b7ac","title":"秋朝木芙蓉","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["水面芙蓉秋已衰，繁条到是著花时。","平明露滴垂红脸，似有朝愁暮落悲。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":["悲慨"],"mood":"愁怨","mood2":["悲怆"],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"植物":["荷花"]},"theme_conf":0.95},{"uid":"e1ea09bb-0ca8-4ec2-b9ee-f1299f878734","title":"游后湖赏莲花","author":"嗣主璟","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["蓼花蘸水火不灭，水鸟惊鱼银梭投。","满目荷花千万顷，红碧相杂敷清流。","孙武已斩吴宫女，琉璃池上佳人头。"],"theme":"山水田园","theme2":["咏史怀古","闺情宫怨"],"style":"绮丽","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["花","江"],"cats":{"抒情":["闺怨","怀古"],"人物":["女子"],"植物":["荷花"]},"theme_conf":0.354},{"uid":"3a5a5f7f-3f3d-4471-b883-9f8ab80cd1a7","title":"郑国夫人挽歌词","author":"赵良器","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["淑德延公胄，宜家接帝姻。","桂宫男掌仆，兰殿女升嫔。","恩泽昭前命，盈虚变此辰。","万年今已矣，彤管列何人。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"抒情":["悼亡"]},"theme_conf":0.98},{"uid":"cf913d33-9ec7-4d06-a644-07dc1adafde1","title":"题张氏隐居二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["春山无伴独相求，伐木丁丁山更幽。","涧道余寒历冰雪，石门斜日到林丘。","不贪夜识金银气，远害朝看糜鹿游。","乘兴杳然迷出处，对君疑是泛虚舟。"],"theme":"闲适隐逸","theme2":[],"style":"幽峭","style2":[],"mood":"孤寂","mood2":[],"scene":["夜","冬","雪","春","舟","山"],"cats":{"抒情":["孤独"],"四季":["春天"],"天气":["写雪"]},"theme_conf":0.88},{"uid":"cp8faa60807b632f","title":"临江仙","author":"陈与义","dynasty":"宋","section":"宋词","form":"词","paragraphs":["高咏楚词酬午日，天涯节序匆匆。","榴花不似舞裙红。","无人知此意，歌罢满帘风。","万事一身伤老矣，戌葵凝笑墙东。","酒杯深浅去年同。","试浇桥下水，今夕到湘中。"],"theme":"送别","theme2":["游仙梦幻","羁旅思乡"],"style":"婉约","style2":[],"mood":"孤寂","mood2":["欢愉"],"scene":["酒","江","花"],"cats":{"抒情":["思乡","孤独"],"生活":["写桥"]},"theme_conf":0.366},{"uid":"a15343da-3f7e-4d97-8df0-6d9a5b567a40","title":"秋思二首 一","author":"马戴","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["万木秋霖后，孤山夕照余。","田园无岁计，寒近忆樵渔。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["秋"],"cats":{"抒情":["思念","孤独"],"四季":["秋天"],"山水":["西湖"],"生活":["田野"]},"theme_conf":1.0},{"uid":"ed927451-c3fd-4566-97a2-c86f8c2fa756","title":"行官张望补稻畦水归","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东屯大江北，百顷平若案。","六月青稻多，千畦碧泉乱。","插秧适云已，引溜加溉灌。","更仆往方塘，决渠当断岸。","公私各地著，浸润无天旱。","主守问家臣，分明见溪伴。","芊芊炯翠羽，剡剡生银汉。","欧鸟镜里来，关山云边看。","秋菰成黑米，精凿传白粲。","玉粒足晨炊，红鲜任霞散。","终然添旅食，作苦期壮观。","遗穗及众多，我仓戒滋蔓。"],"theme":"山水田园","theme2":["羁旅思乡"],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":["秋","七夕"],"cats":{"抒情":["思乡"],"四季":["秋天"],"山水":["长江"],"生活":["田野"],"节日":["七夕节"]},"theme_conf":0.531},{"uid":"71cd9908-9167-4099-8fef-fe6d27fca4b5","title":"荅友人寄新茗","author":"李群玉","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["满火芳香碾曲尘，吴瓯湘水绿花新。","媿君千里分滋味，寄与春风酒渴人。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["花","春","酒"],"cats":{"抒情":["友情"],"四季":["春天"],"食物":["写茶"]},"theme_conf":0.95},{"uid":"cp2f1b9514a94dec","title":"鹧鸪天","author":"姜夔","dynasty":"宋","section":"宋词","form":"词","paragraphs":["肥水东流无尽期。","当初不合种相思。","梦中未比丹青见，暗里忽惊山鸟啼。","春未绿，鬓先丝。","人间别久不成悲。","谁教岁岁红莲夜，两处沈吟各自知。"],"theme":"爱情相思","theme2":["题画咏艺","送别"],"style":"清新","style2":["悲慨"],"mood":"相思","mood2":[],"scene":["春","夜","山"],"cats":{"抒情":["爱情","思念"],"四季":["春天"]},"theme_conf":0.349},{"uid":"3c0f4e33-d046-48ce-bf7f-0aaf1d7f85dc","title":"莲塘驿","author":"李益","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["五月渡淮水，南行遶山陂。","江村远鸡应，竹里闻缲丝。","楚女肌发美，莲塘烟露滋。","菱花覆碧渚，黄鸟双飞时。","渺渺溯洄远，凭风托微词。","斜光动流睇，此意难自持。","女歌本轻艳，客行多怨思。","女萝蒙幽蔓，拟上青桐枝。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["江","月"],"cats":{"抒情":["思乡"],"植物":["荷花"]},"theme_conf":0.579},{"uid":"a6250fd5-bdd4-4c24-9074-a3023c832ae4","title":"宿云溪观赋得秋灯引送客","author":"杨衡","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["云房寄宿秋夜客，一灯荧荧照虚壁。","虫声呼客客未眠，几人语话清景侧。","不可离别愁纷多，秋灯秋灯奈别何。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["秋","夜","元宵"],"cats":{"抒情":["离别","伤感"],"四季":["秋天"],"天气":["写云"],"节日":["元宵节"]},"theme_conf":0.466},{"uid":"c28c271b-70b9-422c-8bfd-6a062f40d40c","title":"天育骠骑歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["吾闻天子之马走千里，今之画图无乃是。","是何意态雄且杰，骏尾萧梢朔风起。","毛为绿缥两耳黄，眼有紫燄双瞳方。","矫矫龙性合变化，卓立天骨森开张。","伊昔太仆张景顺，监牧攻驹阅清峻。","遂令大奴守天育，别养骥子怜神俊。","当时四十万匹马，张公叹其材尽下。","故独写真传世人，见之座右久更新。","年多物化空形影，呜呼健步无由骋。","如今岂无騕褭与骅骝，时无王良伯乐死即休。"],"theme":"送别","theme2":[],"style":"清新","style2":["豪放"],"mood":"孤寂","mood2":[],"scene":[],"cats":{"抒情":["孤独"],"天气":["写风"],"节日":["春节"]},"theme_conf":1.0},{"uid":"cpc07deb8829e3ce","title":"临江仙","author":"辛弃疾","dynasty":"宋","section":"宋词","form":"词","paragraphs":["忆醉三山芳树下，几层风韵忘怀。","黄金颜色五花开。","味如庐橘熟。","贵似荔枝来。","闻道商山馀四老，橘中自酿秋醅。","试呼名品细推排。","重重香腑脏，偏𣨼圣贤杯。"],"theme":"游仙梦幻","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["花","酒","江","秋","山"],"cats":{"抒情":["思念"],"四季":["秋天"],"食物":["荔枝"]},"theme_conf":1.0},{"uid":"ff7aca6e-232d-464f-91cf-75f019591e69","title":"酬马八效古见赠","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["深崖无绿竹，秀色徒氛氲。","时代种桃李，无人顾此君。","奈何冰雪操，尚与蒿莱群。","愿托灵仙子，一声吹入云。"],"theme":"咏物","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":["惆怅"],"scene":["冬","雪"],"cats":{"抒情":["孤独"],"天气":["写雪"],"动物":["写马"]},"theme_conf":0.86},{"uid":"cp756f53532104c7","title":"生查子","author":"晏几道","dynasty":"宋","section":"宋词","form":"词","paragraphs":["关山魂梦长，鱼雁音尘少。","两鬓可怜青，只为相思老。","归梦碧纱窗，说与人人道。","真个别离难，不似相逢好。"],"theme":"送别","theme2":["羁旅思乡","爱情相思"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["塞外","山","鸟"],"cats":{"抒情":["爱情","离别","思念","思乡"]},"theme_conf":0.393},{"uid":"23aa1422-258b-4783-a800-1f28dc71facd","title":"苦雪四首 三","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["蒙蒙洒平陆，淅沥至幽居。","且喜润群物，焉能悲斗储。","故交久不见，鸟雀投吾庐。"],"theme":"咏物","theme2":[],"style":"悲慨","style2":[],"mood":"愁怨","mood2":["悲怆","欢愉"],"scene":["雪"],"cats":{"抒情":["伤感"],"天气":["写雪"]},"theme_conf":0.66},{"uid":"b281e5ae-9731-4a72-b474-7ac786246f35","title":"琴曲歌辞  秋思二首 一","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["胡风吹雁翼，远别无人乡。","君近鴈来处，几回断君肠。","昔奉千日书，抚心怨星霜。","无书又千日，世路重茫茫。","燕国有佳丽，蛾眉富春光。","自然君归晚，花落君空堂。","君其若不然，岁晚双鸳鸯。","顾兔蚀残月，幽光不如星。","女儿晚事夫，颜色同秋萤。","秋日边马思，武夫不遑宁。","燕歌易水怨，劒舞蛟龙腥。","风折连枝树，水翻无蒂萍。","立身多户门，何必燕山铭。","生世不如鸟，双双比翼翎。"],"theme":"闺情宫怨","theme2":["羁旅思乡","闲适隐逸","送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":["孤寂","愁怨"],"scene":["秋","鸟"],"cats":{"抒情":["爱情","思乡","孤独","闺怨"],"四季":["秋天"]},"theme_conf":0.72},{"uid":"34445d84-93cc-43fd-b651-97b205aeddf9","title":"别刘秀才","author":"许浑","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["三献无功玉有瑕，更携书劒客天涯。","孤帆夜别潇湘雨，广陌春期鄠杜花。","灯照水萤千点灭，棹惊滩鴈一行斜。","关河万里秋风急，望见乡山不到家。"],"theme":"送别","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"孤寂","mood2":[],"scene":["元宵","夜","舟"],"cats":{"抒情":["离别","思乡","孤独"],"节日":["元宵节"]},"theme_conf":0.624},{"uid":"c56fd82e-2fab-4c3b-b52c-2631132e0ddf","title":"九日奉寄严大夫","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["九日应愁思，经时冒险艰。","不眠持汉节，何路出巴山。","小驿香醪嫩，重岩细菊斑。","遥知簇鞍马，回首白云间。"],"theme":"寄赠酬答","theme2":["送别"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["重阳"],"cats":{"抒情":["伤感"],"天气":["太阳"],"节日":["重阳节"]},"theme_conf":0.9},{"uid":"6281fbf0-c461-4efe-ac5d-26e86d33fc49","title":"横吹曲辞 入塞曲 一","author":"沈彬","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["欲为皇王服远戎，万人金甲鼓鼙中。","阵云暗塞三边黑，兵血愁天一片红。","半夜飜营旗搅月，深秋防戍劒磨风。","谤书未及明君𦶟，卧骨将军已殁功。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["绮丽"],"mood":"愁怨","mood2":[],"scene":["塞外"],"cats":{"抒情":["伤感"],"人生":["战争"],"生活":["边塞"]},"theme_conf":0.894},{"uid":"cpf2a280a2cda3d4","title":"月照梨花・河传","author":"黄升","dynasty":"宋","section":"宋词","form":"词","paragraphs":["昼景。","方永。","重帘花影。","好梦犹酣，莺声唤醒。","门外风絮交飞。","送春归。","修蛾画了无人问。","几多别恨。","泪洗残妆粉。","不知郎马何处嘶。","烟草萋迷。","鹧鸪啼。"],"theme":"送别","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"孤寂","mood2":["愁怨"],"scene":["花","月","春"],"cats":{"抒情":["伤感","孤独"],"四季":["春天"],"天气":["月亮"],"植物":["梨花"]},"theme_conf":0.737},{"uid":"2d7dac40-92dc-450e-a834-3050521eb709","title":"杂曲歌辞 结客少年场行","author":"沈彬","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["重义轻生一劒知，白虹贯日报讐归。","片心惆怅清平世，酒市无人问布衣。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["惆怅"],"scene":["酒"],"cats":{"抒情":["思乡","孤独"],"人生":["青春"]},"theme_conf":1.0},{"uid":"4ceed844-05e4-493f-a345-b26e9230b080","title":"春日题苗发竹亭","author":"耿𣲗","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["春亭及策上，郎吏谢玄晖。","闲咏疎篁近，高眠远岫微。","偏宜留野客，暂得解朝衣。","犹忆东溪里，雷云掩故扉。"],"theme":"闲适隐逸","theme2":["咏物","闲适隐逸"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":["相思"],"scene":["春","楼"],"cats":{"抒情":["思念"],"四季":["春天"],"植物":["竹子"]},"theme_conf":0.75},{"uid":"5c373cc0-d72c-4bc8-b39e-c48d0564c86e","title":"酬王维春夜竹亭赠别","author":"钱起","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["山月随客来，主人兴不浅。","今宵竹林下，谁觉花源远。","惆怅曙莺啼，孤云还绝𪩘。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":["孤寂"],"scene":["春","夜"],"cats":{"抒情":["离别","孤独"],"四季":["春天"],"植物":["竹子"]},"theme_conf":0.715},{"uid":"9c2e9bc9-e7a3-459b-8c90-e3aefae8d962","title":"奉和礼部尚书酬杨著作竹亭歌","author":"权德舆","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["直城朱户相逦连，九逵丹毂声阗阗。","春官自有花源赏，终日南山当目前。","晨摇玉佩趋温室，莫入竹溪疑洞天。","烟销雨过看不足，晴翠鲜飙逗深谷。","独谣一曲泛流霞，闲对千竿连净绿。","萦回疏凿随胜地，石磴岩扉光景异。","虚斋寂寂清籁唫，幽涧纷纷杂英坠。","家承麟趾贵，劒有龙泉赐。","上奉明时事无事，人间方外兴偏多。","能以簪缨狎薜萝，常通内学青莲偈。","更奏新声白雪歌，风入松，云归栋。","鸿飞灭处犹目送，蝶舞闲时梦忽成。","兰台有客叙交情，返照中林曳履声。","直为君恩催造膝，东方辨色谒承明。"],"theme":"寄赠酬答","theme2":["送别","应制干谒"],"style":"清新","style2":["冲淡","绮丽"],"mood":"孤寂","mood2":[],"scene":["楼","山","雪","春"],"cats":{"抒情":["友情","孤独"],"四季":["春天"],"植物":["竹子"]},"theme_conf":0.8},{"uid":"54008cd0-f9bf-424f-bc55-f15c1e9025f3","title":"赠别二首 一","author":"杜牧","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["娉娉褭褭十三余，豆蔻梢头二月初。","春风十里扬州路，卷上珠帘总不如。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["春","月"],"cats":{"抒情":["离别"],"四季":["春天"]},"theme_conf":1.0},{"uid":"7f4cacb5-cde8-40de-9b14-e223879cc2f4","title":"留别王侍御维","author":"孟浩然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["寂寂竟何待，朝朝空自归。","欲寻芳草去，惜与故人违。","当路谁相假，知音世所稀。","秪应守索寞，还掩故园扉。"],"theme":"送别","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["园林"],"cats":{"抒情":["友情","离别","思乡"]},"theme_conf":0.556},{"uid":"9532d5be-e0a2-4623-aaf5-322a8b90d1ea","title":"暮秋扬子江寄孟浩然","author":"刘眘虚","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["木叶纷纷下，东南日烟霜。","林山相晚暮，天海空青苍。","暝色况复久，秋声亦何长。","孤舟兼微月，独夜仍越乡。","寒笛对京口，故人在襄阳。","咏思劳今夕，江汉遥相望。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["相思"],"scene":["秋","江"],"cats":{"抒情":["友情","孤独"],"四季":["秋天"],"山水":["江河","长江"]},"theme_conf":0.86},{"uid":"f8071036-9e39-49c2-b3e9-09fdeb4a5f82","title":"同州端午","author":"殷尧藩","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["鹤发垂肩尺许长，离家三十五端阳。","儿童见说深惊讶，却问何方是故乡。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["端午"],"cats":{"抒情":["思乡"],"人物":["儿童"],"节日":["端午节"]},"theme_conf":0.92},{"uid":"26d3dbf4-bc0f-4b19-ab8d-fce4d9e2af10","title":"除夜作","author":"高适","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["旅馆寒灯独不眠，客心何事转凄然。","故乡今夜思千里，愁鬓明朝又一年。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":["愁怨"],"scene":["夜","除夕"],"cats":{"抒情":["思乡","伤感","孤独"],"节日":["春节"]},"theme_conf":0.732},{"uid":"00a16385-1ebb-4923-a397-23253e7a0498","title":"紫阳真人歌（幷序）","author":"卢象","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见先生耳鼻有仙骨，自号狂生中有物。","金华侍讲三十年，儿戏公卿与簪笏。","青门抗行谢客儿，健笔连羁王献之。","长安素绢书欲徧，主人爱惜常保持。","每叹二疏不足道，复言四皓常枯槁。","去年寝疾弥数旬，神鬼盈庭谋一老。","长男泣血求司命，少女[颦]（频）眉诵《灵宝》。","还如简子复归来，更与洪崖同寿考。","上书北阙言授箓。","税驾东州愿修道。","初闻行路犹未信，果达吾君谓之好。","山阴旧宅作仙坛，湖上闲田种芝草。","镜湖之水含杳冥，会稽仙洞多精灵。","须乘赤鲤游沧海，当以群鹅写道经。","皇恩赠诗四十字，明主赐金三十镒。","供帐倾朝一送归，双童驷马从兹出。","回看紫绶若轻尘，远别青门嗟故人。","鸳鹭差池攀羽盖，虹霓夭矫翊车轮。","田田列侍浮丘伯，曾子荣过朱买臣。","余高若是有先觉，灭迹归根从大朴。","千载悠悠等令威，十洲漫漫思方朔。","归去来，青牛顿足少迟回。","忽然云雾不相见，唯有飘飘香气来。","（见宋孔延之编《会稽掇英总集》卷二）。"],"theme":"送别","theme2":[],"style":"婉约","style2":["豪放","冲淡"],"mood":"恬淡","mood2":["相思","悲怆"],"scene":["江","园林"],"cats":{"抒情":["友情","思念"],"天气":["彩虹"]},"theme_conf":0.441},{"uid":"5afe3c27-812c-4eed-bb30-74e657009e41","title":"北风","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["北风破南极，朱凤日威垂。","洞庭秋欲雪，鸿雁将安归。","十年杀气盛，六合人烟稀。","吾慕汉初老，时清犹茹芝。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["江","雪","秋","园林","鸟"],"cats":{"抒情":["思乡"],"四季":["秋天"],"天气":["写风"]},"theme_conf":0.65},{"uid":"cp16bdb8f3299f70","title":"瑞鹤仙","author":"陆淞","dynasty":"宋","section":"宋词","form":"词","paragraphs":["脸霞红印枕。","睡觉来、冠儿还是不整。","屏间麝煤冷。","但眉峰压翠，泪珠弹粉。","堂深昼永。","燕交飞、风帘露井。","恨无人，与说相思，近日带围宽尽。","重省。","残灯朱幌，淡月纱窗，那时风景。","阳台路迥。","云雨梦，便无准。","待归来，先指花梢教看，却把心期细问。","问因循、过了青春，怎生意稳。"],"theme":"闺情宫怨","theme2":["爱情相思","游仙梦幻","山水田园"],"style":"绮丽","style2":["婉约","沉郁"],"mood":"相思","mood2":["愁怨"],"scene":["鸟"],"cats":{"抒情":["爱情","思念","伤感","闺怨"],"人生":["青春"],"动物":["写鸟"]},"theme_conf":0.274},{"uid":"687eb62a-e2af-449a-b1d5-4a8a7c0c6f09","title":"招隐寺送阎判官还江州","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["离别那逢秋气悲，东林更作上方期。","共知客路浮云外，暂爱僧房坠叶时。","长江九派人归少，寒岭千重雁度迟。","借问浔阳在何处，每看潮落一相思。"],"theme":"送别","theme2":[],"style":"悲慨","style2":[],"mood":"相思","mood2":["悲怆"],"scene":["江"],"cats":{"抒情":["离别","思念","伤感"],"山水":["庐山","江河","长江"]},"theme_conf":0.426},{"uid":"dfc0cb68-548a-41aa-a47f-492d7e264183","title":"琴曲歌辞 琴歌","author":"顾况","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["琴调秋些，胡风遶雪。","峡泉生咽，佳人愁些。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["雪","秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"人物":["女子"]},"theme_conf":0.628},{"uid":"d1734c10-cff7-42c7-8763-0b04378a3864","title":"感石榴二十韵","author":"元稹","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["何年安石国，万里贡榴花。","迢递河源道，因依汉使槎。","酸辛犯葱岭，顦顇涉龙沙。","初到摽珍木，多来比乱麻。","深抛故园里，少种贵人家。","唯我荆州见，怜君胡地赊。","从教当路长，兼恣入檐斜。","绿叶裁烟翠，红英动日华。","新帘帬透影，疎牖烛笼纱。","委作金炉燄，飘成玉砌瑕。","乍惊珠缀密，终误绣帏奢。","琥珀烘梳碎，燕支嬾颊涂。","风翻一树火，电转五云车。","绛帐迎宵日，芙蕖绽早牙。","浅深俱隐映，前后各分葩。","宿露低莲脸，朝光借绮霞。","暗虹徒缴绕，濯锦莫周遮。","俗态能嫌旧，芳姿尚可嘉。","非专爱颜色，同恨阻幽遐。","满眼思乡泪，相嗟亦自嗟。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["花","园林"],"cats":{"抒情":["思乡","伤感"],"山水":["黄河"],"人物":["老师"]},"theme_conf":0.504},{"uid":"c65539db-4e2b-4ce4-a22b-563b6ef3f4f1","title":"在岳咏蝉","author":"骆宾王","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["西陆蝉声唱，南冠客思侵。","那堪玄鬓影，来对白头吟。","露重飞难进，风多响易沈。","无人信高洁，谁为表予心。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["秋"],"cats":{"抒情":["孤独"]},"theme_conf":1.0},{"uid":"31df356e-d9f2-4984-8f0e-66349cab666e","title":"横吹曲辞 关山月","author":"沈佺期","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["汉月生辽海，曈昽出半晖。","合昏玄兔郡，中夜白登围。","晕落关山迥，光合霜霰微。","将军听晓角，战马欲南归。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["月","塞外","山"],"cats":{"抒情":["思乡"],"天气":["月亮"],"人生":["战争"]},"theme_conf":0.544},{"uid":"8e4dd8bd-be62-478f-bd88-f6db89276125","title":"相和歌辞 明妃曲","author":"王偃","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["北望单于日半斜，明君马上泣胡沙。","一双泪滴黄河水，应得东流入汉家。"],"theme":"边塞征战","theme2":["咏史怀古"],"style":"婉约","style2":["沉郁"],"mood":"悲怆","mood2":["愁怨"],"scene":["江"],"cats":{"抒情":["伤感","怀古"],"山水":["黄河"]},"theme_conf":0.56},{"uid":"efad3f8b-87d3-406e-a916-fc8fb2bdf381","title":"秋日登岳阳楼晴望","author":"张碧","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["三秋倚练飞金盏，洞庭波定平如刬。","天高云卷绿罗低，一点君山碍人眼。","漫漫万顷铺琉璃，烟波阔远无鸟飞。","西南东北竞无际，直疑侵断青天涯。","屈原回日牵愁吟，龙宫感激致应沈。","贾生憔悴说不得，茫茫烟霭堆湖心。"],"theme":"咏史怀古","theme2":["羁旅思乡","山水田园"],"style":"绮丽","style2":["清新","婉约"],"mood":"愁怨","mood2":[],"scene":["楼","江","秋"],"cats":{"抒情":["思乡","伤感","怀古"],"四季":["秋天"],"天气":["太阳"],"节日":["端午节"]},"theme_conf":0.414},{"uid":"c2e105eb-bf47-46ea-b2d3-fc6e0613e869","title":"冬日有怀李白","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["寂寞书斋里，终朝独尔思。","更寻嘉树传，不忘角弓诗。","短褐风霜入，还丹日月迟。","未因乘兴去，空有鹿门期。"],"theme":"边塞征战","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["冬"],"cats":{"抒情":["孤独"],"四季":["冬天"],"天气":["太阳"]},"theme_conf":1.0},{"uid":"1d6885a4-d11e-4428-80a8-fcf75d7a41aa","title":"春宫怨","author":"周朴","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["早被婵娟误，欲妆临镜慵。","承恩不在貌，教妾若为容。","风暖鸟声碎，日高花影重。","年年越溪女，相忆采芙蓉。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"节日":["中秋节"]},"theme_conf":0.76},{"uid":"feed970e-6f9d-451c-ba5c-ba6a629f924f","title":"杂曲歌辞 长相思","author":"郎大家宋氏","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["长相思，久离别。","关山阻，风烟绝。","台上镜文销，袖中书字灭。","不见君形影，何曾有懽悦。"],"theme":"爱情相思","theme2":["送别"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["塞外","山"],"cats":{"抒情":["爱情","离别","思念"]},"theme_conf":0.621},{"uid":"be76202d-c128-4278-b070-dcb351ae96ae","title":"白马","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["白马东北来，空鞍贯双箭。","可怜马上郎，意气今谁见。","近时主将戳，中夜商于战。","丧乱死多门，呜呼泪如霰。"],"theme":"边塞征战","theme2":["咏物"],"style":"婉约","style2":["沉郁"],"mood":"慷慨","mood2":["悲怆","愁怨"],"scene":["雪","夜"],"cats":{"抒情":["伤感"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.594},{"uid":"cpa13dd8628ea1d7","title":"虞美人","author":"舒亶","dynasty":"宋","section":"宋词","form":"词","paragraphs":["芙蓉落尽天涵水。","日暮沧波起。","背飞双燕帖云寒。","独向小楼东畔、倚阑看。","浮生只合尊前老。","雪满长安道。","故人早晚上高台。","赠我江南春色、一枝梅。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["楼","江南","冬","雪","春"],"cats":{"抒情":["友情","孤独"],"四季":["春天"],"人物":["女子"]},"theme_conf":1.0},{"uid":"287bc2ee-eb64-4d40-9f02-07052ccea9ca","title":"奉送刘相公江淮催转运","author":"钱起","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["国用资戎事，臣劳为主忧。","将徴任土贡，更发济川舟。","拥传星还去，过池凤不留。","唯高饮水节，稍浅别家愁。","落叶淮边雨，孤山海上秋。","遥知谢公兴，微月上江楼。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["江","秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"山水":["江河","西湖"]},"theme_conf":0.54},{"uid":"9cac30d1-12da-43d9-8773-ec5a4648c782","title":"相和歌辞 从军有苦乐行","author":"李益","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["劳者且勿歌，我欲送君觞。","从军有苦乐，此曲乐未央。","仆本居陇上，陇水断人肠。","东过秦宫路，宫路入咸阳。","时逢汉帝出，谏猎至长杨。","讵驰游侠窟，非结少年场。","一旦承嘉惠，轻命重恩光。","秉笔参帷帟，从军至朔方。","边地多阴风，草木自凄凉。","断绝海云去，出没胡沙长。","参差引雁翼，隐辚腾军装。","劒文夜如水，马汗冻成霜。","侠气五都少，矜功六郡良。","山河起目前，睚眦死路傍。","北逐驱獯虏，西临复旧疆。","昔还赋余资，今出乃赢粮。","一矢弢夏服，我弓不再张。","寄言丈夫雄，苦乐身自当。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":["欢愉"],"scene":["夏","酒"],"cats":{"抒情":["伤感"],"四季":["夏天"]},"theme_conf":0.56},{"uid":"50d96cb2-de4f-4cbe-bf62-3159b077d2f6","title":"鲁郡途中遇徐十八录事","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["谁谓嵩颍客，遂经邹鲁乡。","前临少昊墟，始觉东蒙长。","独行岂吾心，怀古激中肠。","圣人久已矣，游夏遥相望。","裴回野泽间，左右多悲伤。","日出见阙里，川平知汶阳。","弱冠负高节，十年思自强。","终然不得意，去去任行藏。"],"theme":"羁旅思乡","theme2":["咏史怀古"],"style":"悲慨","style2":[],"mood":"悲怆","mood2":["惆怅","孤寂"],"scene":["夏"],"cats":{"抒情":["思乡","伤感","孤独","怀古"],"四季":["夏天"]},"theme_conf":0.568},{"uid":"ab07dac2-299a-485a-bc5f-41450e4a41e0","title":"杂曲","author":"李益","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["妾本蚕家女，不识贵门仪。","藁砧持玉斧，交结五陵儿。","十日或一见，九日在路岐。","人生此夫壻，富贵欲何为。","杨柳徒可折，南山不可移。","妇人贵结发，宁有再嫁资。","嫁女莫望高，女心愿所宜。","宁从贱相守，不愿贵相离。","蓝叶郁重重，蓝花若榴色。","少妇归少年，华光自相得。","谁言配君子，以奉百年身。","有义即夫壻，无义还他人。","爱如寒炉火，弃若秋风扇。","山岳起面前，相看不相见。","丈夫非小儿，何用强相知。","不见朝生菌，易成还易衰。","征客欲临路，居人还出门。","北风河梁上，四野愁云繁。","岂不恋我家，夫壻多感恩。","前程有日月，勋绩在河源。","少妇马前立，请君听一言。","春至草亦生，谁能无别情。","殷勤展心素，见新莫忘故。","遥望孟门山，殷勤报君子。","既为随阳雁，勿学西流水。","尝闻生别离，悲莫悲于此。","同器不同荣，堂下即千里。","与君贫贱交，何异萍上水。","托身天使然，同生复同死。"],"theme":"送别","theme2":["羁旅思乡"],"style":"豪放","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["秋","山"],"cats":{"抒情":["离别","思乡","伤感","感恩"],"四季":["秋天"],"山水":["黄河"],"天气":["写风"],"人物":["儿童"],"人生":["青春"]},"theme_conf":0.616},{"uid":"9202aa26-8e4f-4828-9fdc-237729e175f7","title":"塞下曲五首 三","author":"张仲素","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["朔雪飘飘开鴈门，平沙历乱卷蓬根。","功名耻计擒生数，直斩楼兰报国恩。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外"],"cats":{"抒情":["爱国"],"生活":["边塞"]},"theme_conf":1.0},{"uid":"5561dd82-ac19-4c72-ba0c-a941cec526c8","title":"酬李少府","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["出塞魂屡惊，怀贤意难说。","谁知吾道间，乃在客中别。","日夕捧琼瑶，相思无休歇。","伊人虽薄宦，举代推高节。","述作凌江山，声华满冰雪。","一登蓟丘上，四顾何惨烈。","来雁无尽时，边风正骚屑。","将从崖谷遁，且与沈浮绝。","君若登青云，余当投魏阙。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["雪","冬","塞外"],"cats":{"抒情":["思念"],"天气":["写雪"]},"theme_conf":0.94},{"uid":"ca2c489a-e433-4c0f-8248-77d354f0665e","title":"静夜思","author":"李白","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["床前看月光，疑是地上霜。","举头望山月，低头思故乡。"],"theme":"羁旅思乡","theme2":["节令风俗"],"style":"冲淡","style2":[],"mood":"相思","mood2":["恬淡"],"scene":["月"],"cats":{"抒情":["思乡"]},"theme_conf":0.62},{"uid":"1a55ca5a-de6c-4286-90a0-e57ed2adfeec","title":"走笔追王内丘","author":"卢仝","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["自识夫子面，便获夫子心。","夫子一启颜，义重千黄金。","平原孟尝骨已土，始有夫子堪知音。","忽然夫子不语，带席帽，骑驴去。","余对醁醽不能斟，君且来，余之瞻望心悠哉。","零雨其蒙愁不散，闲花寂寂斑堦苔。","不如对此景，含笑倾金罍。","莫问四肢畅，暂取眉头开。","弦琴待夫子，夫子来不来。"],"theme":"寄赠酬答","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":["孤寂","愁怨"],"scene":["雨"],"cats":{"抒情":["友情","伤感"],"人物":["老师"]},"theme_conf":0.82},{"uid":"98ce6f68-fa8f-42b6-a5d6-5447079d3a04","title":"相和歌辞 公无渡河","author":"王建","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["渡头恶天两岸远，波涛塞川如叠坂。","幸无白刃驱向前，何用将身自弃捐。","蛟龙啮尸鱼食血，黄泥直下无青天。","男儿纵轻妇人语，惜君性命还须取。","妇人无力挽断衣，舟沈身死悔难追，公无渡河公自为。"],"theme":"咏史怀古","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["塞外","舟"],"cats":{"抒情":["怀古"],"山水":["江河"],"生活":["边塞"]},"theme_conf":0.55},{"uid":"2f6e3b2d-dc26-4be1-bf64-0710c7eaa7cd","title":"相和歌辞 铜雀妓","author":"李贺","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["佳人一壶酒，秋容满千里。","石马卧新烟，忧来何所似？","歌声且潜弄，陵树风自起。","长裾压高台，泪眼看花机。"],"theme":"咏史怀古","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["酒","秋"],"cats":{"抒情":["伤感","怀古"],"四季":["秋天"],"人物":["女子"]},"theme_conf":1.0},{"uid":"cpff779c5996e524","title":"月照梨花・河传","author":"陆游","dynasty":"宋","section":"宋词","form":"词","paragraphs":["霁景风软，烟江春涨。","小阁无人，绣帘半上。","花外姊妹相呼。","约樗蒲。","修蛾忘了章台样。","细思一饷。","感事添惆怅。","胸酥臂玉消减，拟觅双鱼。","倩传书。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"惆怅","mood2":["孤寂"],"scene":["花","月","楼","春"],"cats":{"抒情":["孤独","闺怨"],"四季":["春天"],"山水":["江河"],"天气":["月亮"],"植物":["梨花"]},"theme_conf":1.0},{"uid":"6556f501-f5b9-4353-bde2-75ec0e1bb616","title":"新年作","author":"刘长卿","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["乡心新岁切，天畔独潸然。","老至居人下，春归在客先。","岭猨同旦暮，江柳共风烟。","已是长沙傅，从今又几年。"],"theme":"羁旅思乡","theme2":[],"style":"清新","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["除夕"],"cats":{"抒情":["思乡","孤独"],"节日":["春节"]},"theme_conf":0.698},{"uid":"cp03094b5525f32e","title":"宝鼎现","author":"刘辰翁","dynasty":"宋","section":"宋词","form":"词","paragraphs":["红妆春骑。","踏月影、竿旗穿市。","望不尽、楼台歌舞，习习香尘莲步底。","箫声断、约彩鸾归去，未怕金吾呵醉。","甚辇路、喧阗且止。","听得念奴歌起。","父老犹记宣和事。","抱铜仙、清泪如水。","还转盼、沙河多丽。","漾明光连邸第。","帘影冻、散红光成绮。","月浸葡萄十里。","看往来、神仙才子。","肯把菱花扑碎。","肠断竹马儿童，空见说、三千乐指。","等多时春不归来，到春时欲睡。","又说向、灯前拥髻。","暗滴鲛珠坠。","便当日、亲见霓裳，天上人间梦里。"],"theme":"闺情宫怨","theme2":["山水田园","民生疾苦"],"style":"绮丽","style2":["婉约"],"mood":"愁怨","mood2":["相思"],"scene":["花","楼","春","月"],"cats":{"抒情":["伤感","闺怨"],"四季":["春天"],"人物":["儿童"]},"theme_conf":0.405},{"uid":"cp8aaa92b7ad5aae","title":"夜飞鹊・夜飞鹊慢","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["河桥送人处，凉夜何其。","斜月远堕馀辉。","铜盘烛泪已流尽，霏霏凉露沾衣。","相将散离会，探风前津鼓，树杪参旗。","华骢会意，纵扬鞭、亦自行迟。","迢递路回清野，人语渐无闻，空带愁归。","何意重红满地，遗钿不见，斜径都迷。","兔葵燕麦，向残阳、欲与人齐。","但徘徊班草，欷酹酒，极望天西。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["清新"],"mood":"愁怨","mood2":[],"scene":["夜","鸟"],"cats":{"抒情":["伤感"],"生活":["写桥"],"动物":["写鸟"]},"theme_conf":1.0},{"uid":"27400495-0bfe-4223-a30b-a6c4a1ef4816","title":"寄赠虢州张参军","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["三十事诸侯，贤豪冠北州。","桃花迎骏马，苏合染轻裘。","观妓将军第，题诗关尹楼。","青林朝送客，绿屿晚回舟。","好栗分通子，名香赠莫愁。","洗杯新酒熟，把烛故人留。","百雉归云过，千峰宿雨收。","蒹葭露下晚，菡萏水中秋。","忆昨陪行乐，常时接献酬。","佳期虽雾散，惠问亦川流。","开卷酲堪解，含毫思苦抽。","无因达情意，西望日悠悠。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":["婉约","旷达"],"mood":"愁怨","mood2":["相思"],"scene":["酒","中秋","花","舟","秋"],"cats":{"抒情":["友情","思念","伤感"],"四季":["秋天"],"节日":["中秋节"]},"theme_conf":0.91},{"uid":"caddd8da-5834-41d5-a136-9e1a56c7cef2","title":"杂曲歌辞 行路难五首 四","author":"贺兰进明","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见云间月，暂盈还复缺。","君不见林下风，声远意难穷。","亲故平生欲聚散，欢娱未尽尊酒空。","自叹青青陵上柏，岁寒能与几人同。"],"theme":"羁旅思乡","theme2":[],"style":"冲淡","style2":[],"mood":"欢愉","mood2":["孤寂","相思"],"scene":["酒","冬","月"],"cats":{"抒情":["思念","思乡"],"四季":["冬天"]},"theme_conf":1.0},{"uid":"ea2ee88a-1def-4bda-833b-762f75314d5d","title":"和徐法曹赠崔洛阳斑竹杖以诗见荅","author":"卢纶","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["玉干一寻余，苔花锦不如。","劲堪和醉倚，轻好向空书。","采拂稽山曲，因依释氏居。","方辰将独步，岂与此君疎。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"孤寂","mood2":[],"scene":["酒","山"],"cats":{"抒情":["孤独"],"植物":["竹子"]},"theme_conf":0.86},{"uid":"b881b056-6d92-45e8-9620-4710a375776f","title":"和晋陵陆丞早春游望","author":"杜审言","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["独有宦游人，偏惊物候新。","云霞出海曙，梅柳渡江春。","淑气催黄鸟，晴光转绿苹。","忽闻歌古调，归思欲沾巾。"],"theme":"羁旅思乡","theme2":["咏史怀古","送别"],"style":"清新","style2":[],"mood":"相思","mood2":["愁怨","孤寂"],"scene":["春"],"cats":{"抒情":["思乡","孤独","怀古"],"四季":["春天"],"天气":["写云"]},"theme_conf":0.464},{"uid":"b301d20a-9934-4e51-bada-c92bd451baaf","title":"织女词","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["凤梭停织鹊无音，梦忆仙郎夜夜心。","难得相逢容易别，银河争似妾愁深。"],"theme":"送别","theme2":["闺情宫怨"],"style":"婉约","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["七夕"],"cats":{"抒情":["思念","伤感","闺怨"],"天气":["星星"],"节日":["七夕节"]},"theme_conf":0.542},{"uid":"054f613f-675f-4387-aa4d-428b8a6c601e","title":"赠别褚山人","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["携手赠将行，山人道姓名。","光阴蓟子训，才术褚先生。","墙上梨花白，尊中桂酒清。","洛阳无二价，犹是慕风声。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"抒情":["离别"],"人生":["时光"]},"theme_conf":0.858},{"uid":"1130a58d-d738-46e6-8052-1252a540540d","title":"江边星月二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["江月辞风缆，江星别雾船。","鸡鸣还曙色，鹭浴自清川。","历历竟谁种，悠悠何处圆。","客愁殊未已，他夕始相鲜。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["月","江"],"cats":{"抒情":["思乡","伤感"],"山水":["江河"],"天气":["月亮","星星"]},"theme_conf":1.0},{"uid":"997b631a-bfdd-40d0-9142-69a887e1092e","title":"和吴中丞悼笙妓","author":"李群玉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["丽质仙姿烟逐风，凤皇声断吹台空。","多情草色怨还绿，无主杏花春自红。","堕珥尚存芳树下，余香渐减玉堂中。","唯应去抱云和管，从此长归阿母宫。"],"theme":"悼亡挽歌","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["花","江南"],"cats":{"抒情":["悼亡"],"人物":["母亲"]},"theme_conf":0.94},{"uid":"cp72c5d65e1c6c79","title":"玉胡蝶・玉蝴蝶","author":"史达祖","dynasty":"宋","section":"宋词","form":"词","paragraphs":["晚雨未摧宫树，可怜闲叶，犹抱凉蝉。","短景归秋，吟思又接愁边。","漏初长、梦魂难禁，人渐老、风月俱寒。","想幽欢。","土花庭，虫网阑干。","无端。","啼蛄搅夜，恨随团扇，苦近秋莲。","一笛当楼，谢娘悬泪立风前。","故园晚、强留诗酒，新雁远、不致寒暄。","隔苍烟。","楚香罗袖，谁伴婵娟。"],"theme":"爱情相思","theme2":["闲适隐逸","边塞征战","哲理悟道"],"style":"沉郁","style2":["绮丽","婉约"],"mood":"愁怨","mood2":[],"scene":["秋","园林","楼","夜","中秋","花"],"cats":{"抒情":["思乡","伤感","闺怨"],"四季":["秋天"],"天气":["月亮"],"节日":["中秋节"]},"theme_conf":0.8},{"uid":"294a2fee-f9ee-4b2b-9442-f15496b6eb8e","title":"不离西阁二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["西阁从人别，人今亦故亭。","江云飘素练，石壁断空青。","沧海先迎日，银河倒列星。","平生耽胜事，吁骇始初经。"],"theme":"送别","theme2":[],"style":"冲淡","style2":[],"mood":"惆怅","mood2":[],"scene":["楼","江"],"cats":{"抒情":["离别"],"天气":["星星"]},"theme_conf":1.0},{"uid":"c06c6f1d-b88f-4169-8df1-6aea35110ec1","title":"柳边","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["只道梅花发，那知柳亦新。","枝枝总到地，叶叶自开春。","紫燕时飜翼，黄鹂不露身。","汉南应老尽，霸上远愁人。"],"theme":"咏物","theme2":[],"style":"清新","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["春"],"cats":{"抒情":["伤感"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.78},{"uid":"7109feaf-91db-4b77-a50e-3e71c6a4c66c","title":"送韦讽上阆州录事参军","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["国步犹艰难，兵革未衰息。","万方哀嗷嗷，十载供军食。","庶官务割剥，不暇忧反侧。","诛求何多门，贤者贵为德。","韦生富春秋，洞彻有清识。","操持纪纲地，喜见朱丝直。","当令豪夺吏，自此无颜色。","必若救疮痍，先应去蟊贼。","挥泪临大江，高天意凄恻。","行行树佳政，慰我深相忆。"],"theme":"边塞征战","theme2":["送别"],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["春","秋"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"],"山水":["长江"]},"theme_conf":0.464},{"uid":"bbd2ad8c-e1cd-4b4e-afb2-8464e20188d2","title":"别崔法曹","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["欲作别离西入秦，芝田枣迳往来频。","东湖此夕更留醉，逢著庐山学道人。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"抒情":["离别"],"山水":["庐山"]},"theme_conf":1.0},{"uid":"6685502b-4f24-4ab8-82db-c0b0b155c13e","title":"杂曲歌辞 桃花行 二","author":"李峤","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["绮蕚成蹊遍籞芳，红英扑地满筵香。","莫将秋宴传王母，来比春华寿圣皇。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["花"],"cats":{"抒情":["思乡"],"植物":["桃花"]},"theme_conf":0.65},{"uid":"e12edd83-36cd-4e8a-a630-91874631c51f","title":"杂曲歌辞 行路难三首 二","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["大道如青天，我独不得出。","羞逐长安社中儿，赤鸡白狗赌梨栗。","弹劒作歌奏苦声，曳裾王门不称情。","淮阴市井笑韩信，汉朝公卿忌贾生。","君不见昔时燕家重郭隗，拥篲折腰无嫌猜。","剧辛乐毅感恩分，输肝剖胆效英才。","昭王白骨萦蔓草，谁人更扫黄金台。","行路难，归去来。"],"theme":"羁旅思乡","theme2":["闲适隐逸"],"style":"悲慨","style2":[],"mood":"欢愉","mood2":["惆怅","悲怆"],"scene":[],"cats":{"抒情":["思乡","感恩"]},"theme_conf":0.542},{"uid":"cc5abbb6-01a9-4346-8ba9-29770f446154","title":"雨","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["山雨不作埿，江云薄为雾。","晴飞半岭鹤，风乱平沙树。","明灭洲景微，隐见岩姿露。","拘闷出门游，旷绝经目趣。","消中日伏枕，卧久尘及屦。","岂无平肩舆，莫辨望乡路。","兵戈浩未息，蛇虺反相顾。","悠悠边月破，郁郁流年度。","针灸阻朋曹，糠籺对童孺。","一命须屈色，新知渐成故。","穷荒益自卑，飘泊欲谁诉。","虺羸愁应接，俄顷恐违迕。","浮俗何万端，幽人有独步。","庞公竟独往，尚子终罕遇。","宿留洞庭秋，天寒潇湘素。","杖策可入舟，送此齿发暮。"],"theme":"羁旅思乡","theme2":["边塞征战","山水田园","送别"],"style":"清新","style2":["沉郁","幽峭"],"mood":"愁怨","mood2":["孤寂"],"scene":["江","雨","山"],"cats":{"抒情":["思乡","伤感","孤独"],"天气":["写雨"],"人生":["时光"]},"theme_conf":0.356},{"uid":"dc20aed7-693e-44db-99c4-ab3d8f5ba7d1","title":"南阳公请东樱桃亭子春䜩","author":"孟郊","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["万木皆未秀，一林先含春。","此地独何力，我公布深仁。","霜叶日舒卷，风枝远埃尘。","初英濯紫霞，飞雨流清津。","赏异出嚣杂，折芳积懽忻。","文心兹焉重，俗尚安能珍。","碧玉粧粉比，飞琼秾艳均。","鸳鸯七十二，花态并相新。","常恐遗秀志，迨兹广䜩陈。","芳菲争胜引，歌咏竟良辰。","方知戏马会，永谢登龙宾。"],"theme":"爱情相思","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["爱情","孤独"],"四季":["春天"],"植物":["桃花"]},"theme_conf":1.0},{"uid":"9d551104-88c1-4011-b24a-2ef8f5e60731","title":"木莲树生巴峡山谷间巴民亦呼为黄心树大者高五丈涉冬不凋身如青杨有白文叶如桂厚大无脊花如莲香色艳腻皆同独房蘂有异四月初始开自开迨谢仅二十日忠州西北十里有鸣玉谿生者秾茂尤异元和十四年夏命道士母丘元志写惜其遐僻因题三绝句云 一","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["如折芙蓉栽旱地，似抛芍药挂高枝。","云埋水隔无人识，唯有南宾太守知。"],"theme":"山水田园","theme2":["咏物"],"style":"绮丽","style2":["婉约"],"mood":"孤寂","mood2":[],"scene":["月","冬","夏","花","山"],"cats":{"抒情":["孤独","感恩"],"四季":["夏天","冬天"],"天气":["写云","月亮"],"人生":["梦想"],"植物":["荷花","叶子"]},"theme_conf":0.488},{"uid":"599ee7ca-7e82-4689-b92a-709e51bfce33","title":"寄梅处士","author":"张籍","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["扰扰人间是与非，官闲自觉省心机。","六行班里身常下，九列符中事亦稀。","市客惯曾赊贱药，家僮惊见著新衣。","君今独得居山乐，应喜多时未办归。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":["冬","山"],"cats":{"抒情":["思乡"],"植物":["梅花"]},"theme_conf":0.96},{"uid":"dd5f08ab-e872-48df-978b-369433e46e7d","title":"同诸子哭张元易","author":"刘商","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["盛德高名总是空，神明福善大朦胧。","游魂永永无归日，流水年年自向东。","素帷旅榇乡关远，丹旐孤灯客舍中。","伯道共悲无后嗣，孀妻老母断根蓬。"],"theme":"羁旅思乡","theme2":["悼亡挽歌"],"style":"沉郁","style2":["冲淡"],"mood":"悲怆","mood2":[],"scene":[],"cats":{"抒情":["思乡","伤感","悼亡"],"人物":["母亲"]},"theme_conf":0.521},{"uid":"cp0421a4bd503827","title":"唐多令","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["何处合成愁。","离人心上秋。","纵芭蕉、不雨也飕飕。","都道晚凉天气好，有明月、怕登楼。","年事梦中休。","花空烟水流。","燕辞归、客尚淹留。","垂柳不萦裙带住，漫长是、系行舟。"],"theme":"送别","theme2":["羁旅思乡"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["月"],"cats":{"抒情":["思乡","伤感"],"天气":["月亮"]},"theme_conf":0.551},{"uid":"08dc6c3a-07bc-479a-9bbe-4225ff0352e6","title":"忆幼子","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["骥子春犹隔，莺歌暖正繁。","别离惊节换，聪慧与谁论。","涧水空山道，柴门老树村。","忆渠愁只睡，炙背俯晴轩。"],"theme":"山水田园","theme2":["送别"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["春"],"cats":{"抒情":["离别","思念"],"四季":["春天"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.638},{"uid":"932de3da-b56d-4987-b9cc-3b2d5956a4ff","title":"悼诗","author":"后主煜","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["永念难消释，孤怀痛自嗟。","雨深秋寂莫，愁引病增加。","咽绝风前思，昏蒙眼上花。","空王应念我，穷子正迷家。"],"theme":"悼亡挽歌","theme2":[],"style":"沉郁","style2":["冲淡"],"mood":"孤寂","mood2":[],"scene":["秋","雨"],"cats":{"抒情":["孤独","悼亡"],"四季":["秋天"]},"theme_conf":0.98},{"uid":"ef119060-f85f-444a-a103-4a07a56d1202","title":"自淇涉黄河途中作十三首 十三","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["皤皤河滨叟，相遇似有耻。","辍榜聊问之，荅言尽终结。","一生虽贫贱，九十年未死。","且喜对儿孙，弥慙远城市。","结庐黄河曲，垂钓长河里。","漫漫望云沙，萧条听风水。","所思强饭食，永愿在乡里。","万事吾不知，其心只如此。"],"theme":"羁旅思乡","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"欢愉","mood2":["相思","悲怆"],"scene":["江"],"cats":{"抒情":["思乡"],"山水":["江河","黄河"]},"theme_conf":0.519},{"uid":"5eb98284-b6e8-4232-acf1-47cc896293d1","title":"和中书侍郎院壁画云","author":"李收","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["粉壁画云成，如能上太清。","影从霄汉发，光照掖垣明。","暎筿多幽趣，临轩得野情。","独思作霖雨，流润及生灵。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["雨"],"cats":{"抒情":["孤独"],"天气":["写云"]},"theme_conf":0.649},{"uid":"88d529e0-7481-45fa-8568-bf134ec06a59","title":"界围岩水帘","author":"柳宗元","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["界围汇湘曲，青壁环澄流。","悬泉粲成帘，罗注无时休。","韵磬叩凝碧，锵锵彻岩幽。","丹霞冠其巅，想像凌虚游。","灵境不可状，鬼工谅难求。","忽如朝玉皇，天冕垂前旒。","楚臣昔南逐，有意仍丹丘。","今我始北旋，新诏释缧囚。","采真诚眷恋，许国无淹留。","再来寄幽梦，遗贮催行舟。"],"theme":"山水田园","theme2":["闺情宫怨"],"style":"婉约","style2":["清新","绮丽"],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"抒情":["闺怨"],"山水":["瀑布"]},"theme_conf":0.492},{"uid":"cpd4e5b07119f773","title":"临江仙","author":"晏几道","dynasty":"宋","section":"宋词","form":"词","paragraphs":["梦后楼台高锁，酒醒帘幕低垂。","去年春恨却来时。","落花人独立，微雨燕双飞。","记得小苹初见，两重心字罗衣。","琵琶弦上说相思。","当时明月在，曾照彩云归。"],"theme":"爱情相思","theme2":["游仙梦幻","题画咏艺","闺情宫怨"],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["月","江","楼"],"cats":{"抒情":["爱情","思念","闺怨"],"天气":["写云","月亮"]},"theme_conf":0.292},{"uid":"d70c3690-62ad-4004-b45e-6bb39c53f844","title":"郊庙歌辞 祭神州乐章 送神","author":"不详","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["神州阴祀，洪恩广济。","草树沾和，飞沈沐惠。","礼修鼎俎，奠歆瑶币。","送乐有章，灵轩其逝。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"抒情":["爱国"]},"theme_conf":0.697},{"uid":"3979821a-6f07-41ad-9625-f9a4b76d9108","title":"过柳溪道院","author":"戴叔伦","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["溪上谁家掩竹扉，鸟啼浑似惜春晖。","日斜深巷无人迹，时见棃花片片飞。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["园林","春"],"cats":{"抒情":["孤独","感恩"],"四季":["春天"],"植物":["柳树"]},"theme_conf":0.705},{"uid":"0f5d3f4a-dbf2-4831-b658-e75bd4a0ca38","title":"羌村 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["晚岁迫偷生，还家少欢趣。","娇儿不离膝，畏我复却去。","忆昔好追凉，故绕池边树。","萧萧北风劲，抚事煎百虑。","赖知禾黍收，已觉糟床注。","如今足斟酌，且用慰迟暮。"],"theme":"山水田园","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"欢愉","mood2":["相思"],"scene":["酒"],"cats":{"抒情":["思念"],"人物":["儿童"],"生活":["乡村"]},"theme_conf":0.405},{"uid":"c8a0aa65-3552-4460-9a5a-08eecec348a7","title":"送裴宣城上元所居","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["水流过海稀，尔去换春衣。","泪向槟榔尽，身随鸿雁归。","草思晴后发，花怨雨中飞。","想到金陵渚，酣歌对落晖。"],"theme":"送别","theme2":["节令风俗"],"style":"豪放","style2":["婉约","沉郁"],"mood":"愁怨","mood2":[],"scene":["元宵"],"cats":{"抒情":["伤感"],"节日":["元宵节"]},"theme_conf":0.433},{"uid":"fc114608-fa50-4999-8471-217ef1936685","title":"咏菊","author":"陈叔达","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["霜间开紫蔕，露下发金英。","但令逢采摘，宁辞独晚荣。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["重阳"],"cats":{"抒情":["孤独"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":1.0},{"uid":"5b2c85ac-3edd-43b7-aa6d-b32c31d01bd0","title":"横吹曲辞 折杨柳","author":"李端","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["东城攀柳叶，柳叶低著草。","少壮莫轻年，轻年有人老。","柳发徧川岗，登高堪断肠。","雨烟轻漠漠，何树近君乡？","赠君折杨柳，颜色岂能久。","上客莫沾巾，佳人正回首。","新柳送君行，古柳伤君情。","突兀临荒渡，婆娑出旧营。","隋家两岸尽，陶宅五株平。","日暮偏愁望，春山有鸟声。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["塞外","春","重阳","雨"],"cats":{"抒情":["离别","伤感"],"四季":["春天"],"人物":["女子"],"人生":["青春"],"节日":["重阳节"],"植物":["柳树"]},"theme_conf":0.653},{"uid":"5052c292-7fcd-4d89-90f8-f585cba128be","title":"却渡西陵别越中父老","author":"李绅","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["海潮晚上江风急，津吏篙师语默齐。","倾手奉觞看故老，拥流争拜见孩提。","慙非杜母临襄岘，自鄙朱翁别会稽。","渐举云帆烟水阔，杳然凫雁各东西。"],"theme":"送别","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":["江","江南","酒","舟"],"cats":{"抒情":["离别"],"人物":["父亲"]},"theme_conf":0.522},{"uid":"b3ac6bba-d692-4203-9bef-62c9decf88a4","title":"行路难","author":"冯著","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["男儿𫐘轲徒搔首，入市脱衣且沽酒。","行路难，权门慎勿干，平人争路相摧残。","春秋四气更回换，人事何须再三叹。","君不见雀为鸽，鹰为鸠，东海成田谷为岸。","负薪客，归去来，龟反顾，鹤裴回，黄河岸上起尘埃。","相逢未相识，何用强相猜。","行路难，故山应不改，茅舍汉中在。","白酒杯中聊一歌，苍蝇苍蝇奈尔何。"],"theme":"羁旅思乡","theme2":["闲适隐逸"],"style":"豪放","style2":[],"mood":"相思","mood2":[],"scene":["酒","江"],"cats":{"抒情":["思念","思乡"],"山水":["黄河"]},"theme_conf":0.521},{"uid":"556a1fa5-a3d2-48cb-bfb7-354c057e042f","title":"季冬自嵩山赴洛道中作","author":"独孤及","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["皇运偶中变，长蛇食中土。","天盖西北倾，众星陨如雨。","胡尘动地起，千里闻战鼓。","死人成为阜，流血涂草莽。","策马何纷纷，捐躯抗豺虎。","甘心赴国难，谁谓荼叶苦。","天子初受命，省方造区宇。","斩鲸安溟波，截鼇作天柱。","三微复正统，五玉归文祖。","不图汉官仪，今日忽再覩。","升高望京邑，佳气连海浦。","宝鼎歊景云，明堂舞干羽。","虎臣囗激昂，囗囗囗御侮。","腐儒著缝掖，何处议邹鲁。","西上轘辕山，丘陵横今古。","和气蒸万物，腊月春霭吐。","得为太平人，穷达不足数。","他日遇封禅，著书继三五。"],"theme":"边塞征战","theme2":["山水田园","哲理悟道"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["山","冬"],"cats":{"抒情":["爱国"],"四季":["冬天"],"人生":["哲理","战争"]},"theme_conf":0.433},{"uid":"c724c20d-b1a6-4044-af22-5cb1b6aba150","title":"送桃岩成上人归本寺","author":"严维","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["长老归缘起，桃花忆旧岩。","清晨云抱石，深夜月笼杉。","道具门人捧，斋粮谷鸟衔。","余生愿依止，文字欲三缄。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["山"],"cats":{"抒情":["思念"],"植物":["桃花"]},"theme_conf":0.557},{"uid":"f5b4927a-9a37-4e40-87ee-e75fff02d48a","title":"横吹曲辞 陇头水","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["陇坂高无极，征人一望乡。","关河别去水，沙塞断归肠。","马系千年树，旌悬九月霜。","从来共呜咽，皆是为勤王。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["塞外","月"],"cats":{"抒情":["思乡"],"生活":["边塞"]},"theme_conf":0.356},{"uid":"078f4ec7-6634-44b2-ba3d-f19e322069cb","title":"赠别王炼师往罗浮","author":"施肩吾","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["道俗骈阗留不住，罗浮山上有心期。","却愁仙处人难到，别后音书寄与谁。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["山"],"cats":{"抒情":["离别","伤感"],"植物":["梅花"]},"theme_conf":1.0},{"uid":"e6fd205b-a5b4-415a-87f4-ad87b918ebbb","title":"赴无锡别灵一上人","author":"郎士元","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["高僧本姓竺，开士旧名林。","一入春山里，千峰不可寻。","新年芳草徧，度日白云深。","欲问微官去，悬知讶此心。"],"theme":"送别","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["山","春"],"cats":{"抒情":["离别"],"四季":["春天"],"节日":["春节"]},"theme_conf":0.549},{"uid":"71a62f85-a346-4872-927c-b12ef74f36d6","title":"茶山诗","author":"袁高","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["禹贡通远俗，所图在安人。","后王失其本，职吏不敢陈。","亦有奸佞者，因兹欲求伸。","动生千金费，日使万姓贫。","我来顾渚源，得与茶事亲。","甿辍耕农耒，采采实苦辛。","一夫旦当役，尽室皆同臻。","扪葛上欹壁，蓬头入荒榛。","终朝不盈掬，手足皆鳞皴。","悲嗟遍空山，草木为不春。","阴岭芽未吐，使者牒已频。","心争造化功，走挺麋鹿均。","选纳无昼夜，捣声昏继晨。","众工何枯栌，俯视弥伤神。","皇帝尚巡狩，东郊路多堙。","周回遶天涯，所献愈艰勤。","况减兵革困，重兹固疲民。","未知供御余，谁合分此珍。","顾省忝邦守，又慙复因循。","茫茫沧海间，丹愤何由申。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"冲淡","style2":[],"mood":"悲怆","mood2":[],"scene":["山"],"cats":{"抒情":["伤感"],"食物":["写茶"]},"theme_conf":0.408},{"uid":"49f054a5-f141-4fe7-94d6-7f7b43d7f494","title":"阙题","author":"陈润","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["丈夫不感恩，感恩宁有泪。","心头感恩血，一滴染天地。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":["豪放"],"mood":"愁怨","mood2":["慷慨"],"scene":[],"cats":{"抒情":["伤感","感恩"]},"theme_conf":1.0},{"uid":"c7b4ab4c-0e3f-4fa0-b1e1-09b4e98fc4ac","title":"郊庙歌辞 祭神州乐章 迎神","author":"不详","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["黄舆厚载，赤寰归德。","含育九区，保安万国。","诚敬无怠，禋祀有则。","乐以迎神，其仪不忒。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"抒情":["怀古","爱国"]},"theme_conf":1.0},{"uid":"cp9665af6a84dad4","title":"宴清都","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["绣幄鸳鸯柱。","红情密，腻云低护秦树。","芳根兼倚，花梢钿合，锦屏人妒。","东风睡足交枝，正梦花、瑶钗燕股。","障滟蜡、满照欢丛，嫠蟾冷落羞度。","人间万感幽单，华清惯浴，春盎风露。","连鬟并暖，同心共结，向承恩处。","凭谁为歌长恨，暗殿锁、秋灯夜语。","叙旧期、不负春盟，红朝翠暮。"],"theme":"闺情宫怨","theme2":["爱情相思","咏史怀古"],"style":"绮丽","style2":["清新"],"mood":"欢愉","mood2":[],"scene":["春","花","夜"],"cats":{"抒情":["爱情","闺怨","怀古"],"四季":["春天"]},"theme_conf":0.4},{"uid":"cf912dac-30ed-4f16-a951-ddecd90387ed","title":"郡斋左偏栽竹百余竿炎凉已周青翠不改而为墙垣所蔽有乖爱赏假日命去斋居之东墙由是俯临轩阶低映帷户日夕相对颇有翛然之趣","author":"令狐楚","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["斋居栽竹北窗边，素壁新开映碧鲜。","青蔼近当行药处，绿阴深到卧帷前。","风惊晓叶如闻雨，月过春枝似带烟。","老子忆山心暂缓，退公闲坐对婵娟。"],"theme":"讽喻刺世","theme2":["山水田园"],"style":"清新","style2":["绮丽"],"mood":"欢愉","mood2":["恬淡","相思"],"scene":["夏","中秋","楼","春"],"cats":{"抒情":["思念"],"四季":["春天"],"天气":["月亮"],"节日":["中秋节"],"植物":["竹子"]},"theme_conf":0.464},{"uid":"6038ff33-cb0f-4ab7-82bd-c603b030c1bb","title":"伤歙州陈二使君","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["怜君辞满卧沧洲，一旦云亡万事休。","慈母断肠妻独泣，寒云惨色水空流。","江村故老长怀惠，山路孤猨亦共愁。","寂寞荒坟近渔浦，野松孤月即千秋。"],"theme":"悼亡挽歌","theme2":["山水田园","亲情"],"style":"沉郁","style2":["冲淡"],"mood":"孤寂","mood2":["愁怨"],"scene":["江","秋","月"],"cats":{"抒情":["伤感","孤独","悼亡","感恩"],"四季":["秋天"],"人物":["母亲"]},"theme_conf":0.98},{"uid":"cpc38bcb93c5acea","title":"谢金莲诗酒红梨花・隔尾","author":"张寿卿","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["我为甚商抄过绿径慌忙迸，我则怕迟到蓝桥淹了尾生。","则这窃玉偷香的急心性。","冷落了那画屏，香消了宝鼎，这其间倚定鸳鸯枕头儿等。","(梅香云)姐姐，可早来到也。","俺和你过去。","(赵汝州慌迎科，云)小娘子来了也。","(正旦云)秀才，妾身无甚么礼物，则这一樽酒一瓶花儿，朵与你回礼。","(赵汝州云)小娘子，小生久等多时了也。","(正旦云)梅香，你先回去。","则怕夫人问着，你可支吾咱。","(梅香云)理会得，我先回去也。","(下)(正旦云)秀才，你认的这瓶花么？(赵汝州云)小娘子，这瓶花是甚么花？(正旦云)你试猜咱。","(赵汝州云)敢是海棠花么？(正旦唱)。"],"theme":"闺情宫怨","theme2":["闲适隐逸"],"style":"绮丽","style2":["豪放"],"mood":"愁怨","mood2":[],"scene":["酒","花"],"cats":{"抒情":["闺怨","感恩"],"生活":["写桥"],"植物":["梨花","荷花"],"食物":["写酒"]},"theme_conf":0.566},{"uid":"c33a6b03-6ab3-42eb-b49a-4c3327d34f3f","title":"郊庙歌辞 享章怀太子庙乐章 登歌酌鬯","author":"不详","dynasty":"唐","section":"唐诗","form":"四言","paragraphs":["忠孝本著，羽翼先成。","寝门昭德，驰道为程。","币帛有典，容卫无声。","司存既肃，庙享惟清。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"欢愉","mood2":[],"scene":["酒"],"cats":{"抒情":["怀古"],"食物":["写酒"]},"theme_conf":1.0},{"uid":"81c77b01-47cd-4aba-a980-5bc74b5b9711","title":"狂夫","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["万里桥西一，草堂，百花潭水即沧浪。","风含翠筿娟娟静，雨裛红蕖冉冉香。","厚禄故人书断绝，恒饥稚子色凄凉。","欲填沟壑唯疎放，自笑狂夫老更狂。"],"theme":"民生疾苦","theme2":["亲情"],"style":"豪放","style2":[],"mood":"恬淡","mood2":["愁怨","欢愉"],"scene":["花","雨","山"],"cats":{"抒情":["伤感"],"人物":["儿童"],"生活":["写桥"]},"theme_conf":0.49},{"uid":"3d5cbb39-2531-4c18-b45e-fe6af04c857e","title":"东都父老望幸","author":"薛存诚","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["銮舆秦地久，羽卫洛阳空。","彼土虽凭固，兹川乃得中。","龙颜觐白日，鹤发仰清风。","望幸诚逾邈，怀来意不穷。","昔因封泰岳，今伫蹑维嵩。","天地心无异，神祇理亦同。","翠华翔渭北，玉检候关东。","众愿其难阻，明君早勒功。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["沉郁"],"mood":"相思","mood2":[],"scene":[],"cats":{"抒情":["闺怨"],"人物":["父亲"]},"theme_conf":0.623},{"uid":"cfefd449-c8d9-4b64-b391-480f64682615","title":"陪王使君晦日泛江就黄家亭子二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["有径金沙软，无人碧草芳。","野畦连蛱蝶，江槛俯鸳鸯。","日晚烟花乱，风生锦绣香。","不须吹急管，衰老易悲伤。"],"theme":"爱情相思","theme2":[],"style":"绮丽","style2":[],"mood":"悲怆","mood2":["孤寂"],"scene":["江","花"],"cats":{"抒情":["爱情","伤感","孤独"],"山水":["江河"],"天气":["太阳"]},"theme_conf":1.0},{"uid":"cp593585bc170a9b","title":"御街行","author":"范仲淹","dynasty":"宋","section":"宋词","form":"词","paragraphs":["纷纷堕叶飘香砌。","夜寂静、寒声碎。","真珠帘卷玉楼空，天淡银河垂地。","年年今夜，月华如练，长是人千里。","愁肠已断无由醉。","酒未到、先成泪。","残灯明灭枕头欹。","谙尽孤眠滋味。","都来此事，眉间心上，无计相回避。"],"theme":"爱情相思","theme2":[],"style":"冲淡","style2":["沉郁","婉约"],"mood":"孤寂","mood2":["愁怨","恬淡"],"scene":["酒","夜"],"cats":{"抒情":["伤感","孤独"],"天气":["月亮"]},"theme_conf":0.9},{"uid":"9894e249-6b01-4703-ae50-dbc73beb1249","title":"寒食忆归","author":"王建","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["京中曹局无多事，寒食贫儿要在家。","遮莫杏园胜别处，亦须归看傍村花。"],"theme":"羁旅思乡","theme2":[],"style":"幽峭","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["清明"],"cats":{"抒情":["思念","思乡"],"节日":["寒食节","清明节"]},"theme_conf":0.8},{"uid":"cpb5b77eed9ebb49","title":"秃厮儿・出郡城愁临浙水，寓钱塘闷度朝夕，匆匆一鞭行色催。洒梨花，","author":"贯云石","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["雨霏霏，寒食。"],"theme":"节令风俗","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["雨","江南","清明","花"],"cats":{"抒情":["伤感"],"节日":["寒食节","清明节"],"植物":["梨花"]},"theme_conf":0.578},{"uid":"cp194ecb5ec04420","title":"迷神引","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["一叶扁舟轻帆卷。","暂泊楚江南岸。","孤城暮角，引胡茄怨。","水茫茫，平沙雁、旋惊散。","烟敛寒林簇，画屏展。","天际遥山小，黛眉浅。","旧赏轻抛，到此成游宦。","觉客程劳，年光晚。","异乡风物，忍萧索、当愁眼。","帝城赊，秦楼阻，旅魂乱。","芳草连空阔，残照满。","佳人无消息，断云远。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":["孤寂"],"scene":["舟"],"cats":{"抒情":["思乡","伤感","孤独"],"人物":["女子"]},"theme_conf":0.601},{"uid":"cp00f32cca7838bf","title":"永遇乐","author":"李清照","dynasty":"宋","section":"宋词","form":"词","paragraphs":["落日熔金，暮云合璧，人在何处。","染柳烟浓，吹梅笛怨，春意知几许。","元宵佳节，融和天气，次第岂无风雨。","来相召、香车宝马，谢他酒朋诗侣。","中州盛日，闺门多暇，记得偏重三五。","铺翠冠儿，拈金雪柳，簇带争济楚。","如今憔悴，风鬟霜鬓，怕见夜间出去。","不如向、帘儿底下，听人笑语。"],"theme":"闺情宫怨","theme2":["节令风俗"],"style":"婉约","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["夜","雨","元宵","冬","雪","春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"节日":["元宵节"]},"theme_conf":0.515},{"uid":"e94f7b4c-7e68-4d8b-81b3-053539a689d8","title":"画马篇","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君侯枥上骢，貌在丹青中。","马毛连钱蹄铁色，图画光辉骄玉勒。","马行不动势若来，权奇蹴踏无尘埃。","感兹绝代称妙手，遂令谈者不容口。","麒麟独步自可珍，驽骀万匹知何有，终未如他枥上骢。","载华毂，聘飞鸿，荷君剪拂与君用，一日千里如旋风。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":[],"cats":{"抒情":["孤独"],"动物":["写马"]},"theme_conf":1.0},{"uid":"4ed14233-782c-4837-9c21-d6b8de27518b","title":"水帘吟","author":"薛能","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["万滴相随万响兼，路尘天产尽旁沾。","源从颢气何因绝，派助前溪岂觉添。","豪客每来清夏葛，愁人才见认愁簷。","嘉名已极终难称，别是风流不是帘。"],"theme":"山水田园","theme2":["送别","闺情宫怨"],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["夏"],"cats":{"抒情":["伤感","闺怨"],"四季":["夏天"],"山水":["瀑布"]},"theme_conf":0.451},{"uid":"89948763-087c-4404-b98d-eedc526849ec","title":"同李员外贺哥舒大夫破九曲之作","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["遥传副丞相，昨日破西蕃。","作气群山动，扬军大斾翻。","奇兵邀转战，连孥绝归奔。","泉喷诸戎血，风驱死虏魂。","头飞攒万戟，面缚聚辕门。","鬼哭黄埃暮，天愁白日昏。","石城与岩险，铁骑皆云屯。","长策一言决，高踪百代存。","威棱慑沙漠，忠义感乾坤。","老将黯无色，儒生安敢论。","解围凭庙算，止杀报君恩。","唯有关河渺，苍茫空树墩。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"悲怆","mood2":["愁怨"],"scene":["山","塞外"],"cats":{"抒情":["伤感"],"山水":["黄河"],"人生":["战争"]},"theme_conf":0.492},{"uid":"c0944f9f-23d3-4187-9968-bf7a253903dd","title":"观竞渡","author":"薛逢","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["三月三日天清明，杨花绕江啼晓莺。","使君未出郡斋内，江上已闻齐和声。","使君出时皆有引，马前已被红旗阵。","两岸罗衣破鼻香，银钗照日如霜刃。","鼓声三下红旗开，两龙跃出浮水来。","擢影斡波飞万劒，鼓声劈浪鸣千雷。","雷声冲急波相近，两龙望标目如瞬。","江上人呼霹雳声，竿头彩挂虹霓晕。","前船抢水已得标，后船失势空挥桡。","疮眉血首争不定，输岸一朋心似烧。","只将标示输赢赏，两岸十舟五来往。","须臾戏罢各东西，竞脱文身请书上。","吾今细观竞渡儿，何殊当路权相持。","不思得所各休去，会到摧舟折楫时。"],"theme":"闺情宫怨","theme2":["节令风俗"],"style":"婉约","style2":[],"mood":"孤寂","mood2":["相思"],"scene":["舟","清明","花"],"cats":{"抒情":["闺怨"],"天气":["彩虹"],"节日":["清明节"]},"theme_conf":0.568},{"uid":"84817a87-9ee4-4fc1-8207-68ba2ef51bc0","title":"杂曲歌辞 荆州泊","author":"李端","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["南楼西下时，月里闻来棹。","桂水舳舻回，荆州津济闹。","移帷望星汉，引带思容貌。","今夜一江人，惟应妾身觉。"],"theme":"闺情宫怨","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["月","楼","舟","夜","江"],"cats":{"抒情":["闺怨"],"山水":["江河"]},"theme_conf":1.0},{"uid":"b2c9ad7d-19b9-4f75-8adf-ea9fcc4e1a84","title":"西湖留别","author":"白居易","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["征途行色惨风烟，祖帐离声咽管弦。","翠黛不须留五马，皇恩只许住三年。","绿藤阴下铺歌席，红藕花中泊妓船。","处处回头尽堪恋，就中难别是湖边。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":["江南","江"],"cats":{"抒情":["离别"],"山水":["西湖"]},"theme_conf":1.0},{"uid":"33789ba7-a44a-4989-9da1-f1379968bb8a","title":"饮后戏示弟子","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["吾为尔先生，尔为吾弟子。","孔门有遗训，复坐吾告尔。","先生馔酒食，弟子服劳止。","孝敬不在他，在兹而已矣。","欲我少忧愁，欲我多欢喜。","无如酝好酒，酒须多且旨。","旨即宾可留，多即罍不耻。","吾更有一言，尔宜听入耳。","人老多忧贫，人病多忧死。","我今虽老病，所忧不在此。","忧在半酣时，尊空座客起。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":["豪放"],"mood":"愁怨","mood2":["欢愉"],"scene":["酒"],"cats":{"抒情":["思乡","伤感"],"人物":["老师"]},"theme_conf":0.65},{"uid":"e74b2d34-c0a4-4049-a02d-b2d9aa00fd80","title":"横吹曲辞 幽州胡马客歌","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["幽州胡马客，绿眼虎皮冠。","笑拂两只箭，万人不可干。","弯弓若转月，白雁落云端。","双双掉鞭行，游猎向楼兰。","出门不顾后，报国死何难。","天骄五单于，狼戾好凶残。","牛马散北海，割鲜若虎餐。","虽居燕支山，不道朔雪寒。","妇女马上笑，颜如赪玉盘。","飜入射鸟兽，花月醉雕鞍。","旄头四光芒，争战若蜂攒。","白刃洒赤血，流沙为之丹。","名将古谁是，疲兵良可叹。","何时天狼灭？父子得闲安。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["沉郁","绮丽"],"mood":"恬淡","mood2":["孤寂","慷慨"],"scene":["鸟"],"cats":{"抒情":["爱国"],"人生":["战争"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.574},{"uid":"1ba275a5-93d8-4d90-9367-7192e01dae10","title":"塞下曲","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见芳树枝，春花落尽蜂不窥。","君不见梁上泥，秋风始高燕不栖。","荡子从军事征战，蛾眉婵娟守空闺。","独宿自然堪下泪，况复时闻鸟夜啼。"],"theme":"边塞征战","theme2":[],"style":"婉约","style2":["冲淡","沉郁"],"mood":"孤寂","mood2":["愁怨"],"scene":["塞外","鸟"],"cats":{"抒情":["伤感","孤独"],"人生":["战争"],"生活":["边塞"],"节日":["中秋节"]},"theme_conf":0.824},{"uid":"d9d4c055-1dc0-4555-b180-979008c8d0f0","title":"南充谢郡客游澧州留赠宇文中丞","author":"畅当","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["仆本濩落人，辱当州郡使。","量力颇及早，谢归今即已。","萧萧若凌虚，襟带顿销靡。","车服率然来，涔阳作游子。","郁郁寡开颜，默默独行李。","忽逢平生友，一笑方在此。","秋情宁风日，楚思浩云水。","为语弋林者，冥冥鸿远矣。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"婉约","style2":[],"mood":"孤寂","mood2":["愁怨","欢愉"],"scene":["秋"],"cats":{"抒情":["思乡","孤独","感恩"],"四季":["秋天"]},"theme_conf":0.88},{"uid":"3dabbe1b-2f16-498b-a1e7-be13ab466eca","title":"相和歌辞 湖边采莲妇","author":"李白","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["小姑织白纻，未解将人语。","大嫂采芙蓉，溪湖千万重。","长兄行不在，莫使外人逢。","愿学秋胡妇，真心比古松。"],"theme":"山水田园","theme2":["爱情相思","闺情宫怨"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江"],"cats":{"抒情":["闺怨"],"植物":["荷花"]},"theme_conf":0.362},{"uid":"7e26f9c9-ef6f-4b26-bf34-c683d1e41786","title":"杂曲歌辞 长相思","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["九月西风兴，月冷霜华凝。","思君秋夜长，一夜魂九升。","二月东风来，草坼花心开。","思君春日迟，一日肠九回。","妾住洛桥北，君住洛桥南。","十五即相识，今年二十三。","有如女萝草，生在松之侧。","蔓短枝苦高，萦回上不得。","人言人有愿，愿至天必成。","愿作远方兽，步步比肩行。","愿作深山木，枝枝连理生。"],"theme":"爱情相思","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":[],"scene":["秋","春"],"cats":{"抒情":["爱情","思念"],"四季":["春天","秋天"],"天气":["写风"],"生活":["写桥"]},"theme_conf":1.0},{"uid":"f3900a71-2d1e-4099-81d9-2f4e099b0940","title":"秋夜闻鴈寄南十五兼呈空和尚","author":"张南史","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["晚节闻君道趣深，结茅栽树近东林。","禅师几度曾摩顶，高士何年更发心。","北渚三更闻过鴈，西城万木动寒砧。","不见支公与玄度，相思拥膝坐长吟。"],"theme":"寄赠酬答","theme2":["送别"],"style":"冲淡","style2":[],"mood":"相思","mood2":["孤寂"],"scene":["夜","秋"],"cats":{"抒情":["思念"],"四季":["秋天"],"山水":["庐山"]},"theme_conf":0.9},{"uid":"8138a2d0-cd03-4430-95cf-487daa5d6902","title":"将赴成都草堂途中有作先寄严郑公五首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["处处青江带白苹，故园犹得见残春。","雪山斥候无兵马，锦里逢迎有主人。","休怪儿童延俗客，不教鹅鸭恼比邻。","习池未觉风流尽，况复旌州赏更新。"],"theme":"寄赠酬答","theme2":["羁旅思乡"],"style":"幽峭","style2":["绮丽"],"mood":"惆怅","mood2":[],"scene":["园林","雪","春"],"cats":{"抒情":["思乡"],"四季":["春天"],"人物":["儿童"]},"theme_conf":0.95},{"uid":"189ab60e-c415-4aa2-b883-e6a899426407","title":"乌程水楼留别","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["悠悠千里去，惜此一尊同。","客散高楼上，帆飞细雨中。","山程随远水，楚思在青枫。","共说前期易，沧波处处同。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["楼","雨"],"cats":{"抒情":["离别"],"天气":["写雨"]},"theme_conf":0.561},{"uid":"ce013b49-2360-4975-868d-51f326a07115","title":"梁司马画马歌","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["画精神，画筋骨，一团旋风瞥灭没。","仰秣如上贺兰山，低头欲饮长城窟。","此马昂然独此群，阿爷是龙飞入云。","黄沙枯碛无寸草，一日行过千里道。","展处把笔欲描时，司马一䯄赛倾倒。"],"theme":"题画咏艺","theme2":["边塞征战"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":[],"cats":{"抒情":["孤独","感恩"],"动物":["写马"]},"theme_conf":0.632},{"uid":"16ddf43c-ac3a-47bc-95a5-36a49bceb30b","title":"贫女","author":"秦韬玉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["蓬门未识绮罗香，拟托良媒益自伤。","谁爱风流高格调，共怜时世俭梳妆。","敢将十指夸偏巧，不把双眉鬬画长。","苦恨年年压金线，为他人作嫁衣裳。"],"theme":"闺情宫怨","theme2":["哲理悟道"],"style":"绮丽","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":[],"cats":{"抒情":["伤感","闺怨"]},"theme_conf":0.429},{"uid":"cb5b6b57-47da-4cde-aa13-9a28bebc7fc4","title":"琴曲歌辞 湘妃列女操","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["有虞夫人哭虞后，淑女何事又伤离。","竹上泪迹生不尽，寄哀云和五十丝。","云和经奏钧天曲，乍听宝琴遥嗣续。","三湘测测流急绿，秋夜露寒蜀帝飞。","枫林月斜楚臣宿，更疑川宫日黄昏。","暗携女手殷勤言，环佩玲珑有无间。","终疑既远双悄悄，苍梧旧云岂难召。","老猨心寒不可啸，目眄眄兮意蹉跎。"],"theme":"咏史怀古","theme2":["闲适隐逸","悼亡挽歌","山水田园"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["夜","秋"],"cats":{"抒情":["伤感","悼亡","怀古"],"四季":["秋天"]},"theme_conf":0.85},{"uid":"b11c8320-d662-41e0-a9f2-8f4d4c4ceccd","title":"冬狩","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["烈烈寒风起，惨惨飞云浮。","霜浓凝广隰，冰厚结清流。","金鞍移上苑，玉勒骋平畴。","旌旗四望合，罝罗一面求。","楚踣争兕殪，秦亡角鹿愁。","兽忙投密树，鸿惊起砾洲。","骑敛原尘静，戈回岭日收。","心非洛汭逸，意在渭滨游。","禽荒非所乐，抚辔更招忧。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":[],"mood":"愁怨","mood2":[],"scene":["冬"],"cats":{"抒情":["伤感"],"四季":["冬天"]},"theme_conf":1.0},{"uid":"81d2c0f7-48ad-4b35-b142-9ed40165e8e2","title":"孟生诗","author":"韩愈","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["孟生江海士，古貌又古心。","尝读古人书，谓言古犹今。","作诗三百首，窅默咸池音。","骑驴到京国，欲和熏风琴。","岂识天子居，九重郁沈沈。","一门百夫守，无籍不可寻。","晶光荡相射，旗戟翩以森。","迁延乍却走，惊怪靡自任。","举头看白日，泣涕下沾襟。","朅来游公卿，莫肯低华簪。","谅非轩冕族，应对多差参。","萍蓬风波急，桑榆日月侵。","奈何从进士，此路转岖嵚。","异质忌处群，孤芳难寄林。","谁怜松桂性，竞爱桃李阴。","朝悲辞树叶，夕感归巢禽。","顾我多慷慨，穷檐时见临。","清宵静相对，发白聆苦吟。","采兰起幽念，眇然望东南。","秦吴修且阻，两地无数金。","我论徐方牧，好古天下钦。","竹实凤所食，德馨神所歆。","求观众丘小，必上泰山岑。","求观众流细，必泛沧溟深。","子其听我言，可以当所箴。","既获则思返，无为久滞淫。","卞和试三献，期子在秋砧。"],"theme":"山水田园","theme2":[],"style":"悲慨","style2":["旷达"],"mood":"悲怆","mood2":["相思"],"scene":["山","秋","月"],"cats":{"抒情":["伤感"],"四季":["秋天"],"山水":["泰山"]},"theme_conf":0.647},{"uid":"cf8aa5b6-2baa-45ef-af3c-7a1f04138f8a","title":"故武卫将军挽歌三首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["舞劒过人绝，鸣弓射兽能。","铦锋行惬顺，猛噬失𫏋腾。","赤羽千夫膳，黄河十月冰。","横行沙漠外，神速至今称。"],"theme":"边塞征战","theme2":["悼亡挽歌"],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["江","塞外","月","冬"],"cats":{"抒情":["悼亡"],"山水":["黄河"]},"theme_conf":0.536},{"uid":"cp5d1d2428d640c6","title":"谢金莲诗酒红梨花・一煞","author":"张寿卿","dynasty":"元","section":"元曲","form":"杂言古诗","paragraphs":["你休愁我衾寒枕剩人孤另，我则怕你酒醒灯昏梦不成，佳期漏泄无干净。","慌出兰堂，四下眶天如悬镜。","夜气扑人冷，一片闲云近玉绳，空余着银汉澄澄。"],"theme":"闲适隐逸","theme2":[],"style":"绮丽","style2":["豪放"],"mood":"孤寂","mood2":["愁怨","惆怅"],"scene":["酒","夜","花"],"cats":{"抒情":["伤感","孤独","感恩"],"植物":["梨花","荷花"],"食物":["写酒"]},"theme_conf":0.411},{"uid":"12c06865-5953-478a-86df-2ae3d927be97","title":"咏史诗 叶县","author":"胡曾","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["叶公丘墓已尘埃，云矗崇墉亦半摧。","借问往年龙见日，几多风雨送将来。"],"theme":"咏史怀古","theme2":["咏物"],"style":"悲慨","style2":[],"mood":"惆怅","mood2":[],"scene":["雨"],"cats":{"抒情":["怀古"],"植物":["叶子"]},"theme_conf":0.457},{"uid":"f19370d8-5bc7-42c7-a16b-740337f9e5d8","title":"故燕国相公挽歌二首 一","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["文若为全德，留侯是重名。","论公长不宰，因病得无生。","大梦依禅定，高坟共化城。","自应怜寂灭，人世但伤情。"],"theme":"悼亡挽歌","theme2":[],"style":"清新","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["鸟"],"cats":{"抒情":["悼亡"],"动物":["写鸟"]},"theme_conf":0.99},{"uid":"a6144ae0-3bcf-4503-b58d-9abf24d6608c","title":"渡汉江","author":"李频","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["岭外音书绝，经年复历春。","近乡情更怯，不敢问来人。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["江"],"cats":{"抒情":["思乡"]},"theme_conf":0.698},{"uid":"b5d52c7f-9cd4-4805-8b40-47771a17af7b","title":"赠别晋三处士","author":"高适","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["有人家住清河源，渡河问我游梁园。","手持道经注已毕，心知内篇口不言。","卢门十年见秋草，此心惆怅谁能道。","知己从来不易知，慕君为人与君好。","别时九月桑叶疎，出门千里无行车。","爱君且欲君先达，今上求贤早上书。"],"theme":"送别","theme2":[],"style":"旷达","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","月"],"cats":{"抒情":["友情","离别"],"四季":["秋天"],"山水":["黄河"]},"theme_conf":1.0},{"uid":"c0f319bd-70b8-4e2b-ad82-9ed3d84ed7b0","title":"相和歌辞 怨歌行","author":"吴少微","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["城南有怨妇，含怨倚兰丛。","自谓二八时，歌舞入汉宫。","皇恩弄幸玉堂中，绿陌黄花催夜酒。","锦衣罗袂逐春风，建章西宫焕若神。","燕赵美女二千人，君王厌德不忘新。","况群艳冶纷来陈，是时别君不再见。","三十三春长信殿，长信重门昼掩关。","清房晓帐幽且闲，绮窗虫网氛尘色。","文轩莺对桃李颜，天王贵宫不贮老。","浩然泪陨今来还，自怜转晚暮。","试逐佳游芳草路，小腰丽女夺人奇。","金鞍少年曾不顾，归来谁为夫。","请谢西家妇，莫辞先醉解罗襦。"],"theme":"闺情宫怨","theme2":["送别","羁旅思乡"],"style":"绮丽","style2":["清新"],"mood":"愁怨","mood2":[],"scene":["春","酒","鸟"],"cats":{"抒情":["思乡","伤感","闺怨","感恩"],"四季":["春天"]},"theme_conf":0.97},{"uid":"84b9a130-8145-4902-aac7-5779c17e3fef","title":"饮马长城窟行","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["塞外悲风切，交河冰已结。","瀚海百重波，阴山千里雪。","迥戍危烽火，层峦引高节。","悠悠卷斾旌，饮马出长城。","寒沙连骑迹，朔吹断边声。","胡尘清玉塞，羌笛韵金钲。","绝漠干戈戢，车徒振原隰。","都尉反龙堆，将军旋马邑。","扬麾氛雾静，纪石功名立。","荒裔一戎衣，灵台凯歌入。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["绮丽"],"mood":"恬淡","mood2":["悲怆"],"scene":["冬","塞外"],"cats":{"抒情":["伤感"],"人生":["战争"],"生活":["边塞"],"动物":["写马"]},"theme_conf":1.0},{"uid":"9649f4dc-e18d-4b00-bb8c-018e0d725b03","title":"远寺钟","author":"司空曙","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["杳杳疎钟发，因风清复引。","中宵独听之，似与东林近。"],"theme":"哲理悟道","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["夜"],"cats":{"抒情":["孤独"],"山水":["庐山"]},"theme_conf":1.0},{"uid":"6766b37d-23ee-41e7-8aa8-023dfe603107","title":"与独孤穆冥会诗 一","author":"临淄县主","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["江都昔丧乱，阙下多搆兵。","豺虎恣吞噬，干戈日纵横。","逆徒自外至，半夜开重城。","膏血浸宫殿，刀枪倚簷楹。","今知从逆者，廼是公与卿。","白刃汚黄屋，邦家遂因倾。","疾风知劲草，世乱识忠臣。","哀哀独孤公，临死乃结缨。","天地既板荡，云雷时未亨。","今者二百载，幽怀犹未平。","山河风月古，陵寝露烟青。","君子秉祖德，方垂忠烈名。","华轩一惠顾，土室以为荣。","丈夫立志操，存没感其情。","求义若可托，谁能抱幽贞。"],"theme":"边塞征战","theme2":["悼亡挽歌"],"style":"沉郁","style2":["豪放","悲慨"],"mood":"孤寂","mood2":[],"scene":[],"cats":{"抒情":["孤独","悼亡"],"人生":["励志","战争"]},"theme_conf":0.639},{"uid":"103a8266-2d76-413d-9cde-e32f15f47d4c","title":"九月九日幸临渭亭登高得秋字","author":"中宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["九月正乘秋，三杯兴已周。","泛桂迎尊满，吹花向酒浮。","长房萸早熟，彭泽菊初收。"],"theme":"节令风俗","theme2":["咏史怀古"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["重阳","月","秋"],"cats":{"抒情":["怀古"],"四季":["秋天"],"天气":["月亮"],"节日":["重阳节"]},"theme_conf":0.92},{"uid":"4fa92777-9bd6-45ca-9272-bac30459cf5e","title":"金陵五题 乌衣巷","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["朱雀桥边野草花，乌衣巷口夕阳斜。","旧时王谢堂前燕，飞入寻常百姓家。"],"theme":"咏史怀古","theme2":[],"style":"绮丽","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"抒情":["怀古"],"生活":["写桥"]},"theme_conf":0.738},{"uid":"cp40369a60024392","title":"浣溪沙","author":"晏殊","dynasty":"宋","section":"宋词","form":"词","paragraphs":["一向年光有限身。","等闲离别易消魂。","酒筵歌席莫辞频。","满目山河空念远，落花风雨更伤春。","不如怜取眼前人。"],"theme":"送别","theme2":["山水田园","闲适隐逸"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["雨","酒","春"],"cats":{"抒情":["离别"],"四季":["春天"]},"theme_conf":0.38},{"uid":"7715e2f7-4e7e-4794-942e-bfbad57f953d","title":"燕歌行","author":"屈同仙","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见渔阳八月塞草腓，征人相对并思归。","云和朔气连天黑，蓬杂惊沙散野飞。","是时天地阴埃遍，瀚海龙城皆习战。","两军鼓角暗相闻，四面旌旗看不见。","昭君远嫁已年多，戎狄无厌不复和。","汉兵候月秋防塞，胡骑乘冰夜渡河。","河塞东西万余里，地与京华不相似。","燕支山下少春晖，黄沙碛里无流水。","金戈玉剑十年征，红粉青楼多怨情。","厌向殊乡久离别，秋来愁听捣衣声。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":["清新","豪放"],"mood":"愁怨","mood2":["相思"],"scene":["鸟","塞外","秋"],"cats":{"抒情":["离别","思念","伤感","感恩"],"四季":["秋天"],"人生":["战争"],"生活":["边塞"],"动物":["写鸟"]},"theme_conf":0.592},{"uid":"8e44e405-1497-4a50-8d60-2a6d66979a92","title":"放鱼","author":"窦巩","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["金钱赎得免刀痕，闻道禽鱼亦感恩。","好去长江千万里，不须辛苦上龙门。"],"theme":"边塞征战","theme2":[],"style":"旷达","style2":["豪放"],"mood":"慷慨","mood2":[],"scene":["江"],"cats":{"抒情":["感恩"],"山水":["长江"]},"theme_conf":0.65},{"uid":"2c24cec1-4105-4511-bf8b-bc6d5d8d48c7","title":"送李少府贬峡中王少府贬长沙","author":"高适","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["嗟君此别意何如，驻马衔桮问谪居。","巫峡啼猿数行泪，衡阳归雁几封书。","青枫江上秋天远，白帝城边古木疎。","圣代即今多雨露，暂时分手莫踌躇。"],"theme":"送别","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["秋天"]},"theme_conf":0.556},{"uid":"2186935c-d029-4ee0-b0b1-4f6341b0323b","title":"野菊","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["苦竹园南椒坞边，微香冉冉泪涓涓。","已悲节物同寒雁，忍委芳心与暮蝉。","细路独来当此夕，清尊相伴省他年。","紫云新苑移花处，不取霜栽近御筵。"],"theme":"咏物","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":["孤寂","悲怆"],"scene":["花","重阳","秋"],"cats":{"抒情":["伤感","孤独"],"四季":["秋天"],"节日":["重阳节"],"植物":["菊花"]},"theme_conf":0.757},{"uid":"6d8dba87-8e48-42cb-9943-653cd609afe3","title":"七夕曲","author":"王建","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["河边独自看星宿，夜织天丝难接续。","抛梭振镊动明珰，为有秋期眠不足。","遥愁今夜河水隔，龙驾车辕鹊填石。","流苏翠帐星渚间，环珮无声灯寂寂。","两情缠绵忽如故，复畏秋风生晓路。","幸回郎意且斯须，一年中别今始初，明星未出少停车。"],"theme":"节令风俗","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":["相思"],"scene":["七夕","夜"],"cats":{"抒情":["孤独"],"节日":["七夕节"]},"theme_conf":0.86}];
